-- 自动生成：仅含中文译文与匹配指纹。来源见 SOURCES.md。
local D = TauriChineseDB
D.Strings[56560]="谁知道在这些厚墙内隐藏着多少知识呢。我们还能让这座宝库变得更加宏大。$b$b在你探索这片土地时，留心寻找那些不同寻常的物品，或许能帮我们加深对过往的了解。当你对我们的历史有足够的认识时，我就能与你分享一两个故事。"
D.Strings[56561]="能见到另一位探险者真是太好了！当某些人发现一片新土地时，他们总会立刻动身前往堡垒和寺院。$b$b我跟他们可不一样。$b$b要想深入了解一个地方的人，你就必须脚踏实地。来吧，随我四处逛逛！让我们看看这些陆地熊猫人真正重视的是什么。$b$b这才是云游者之道。"
D.Strings[56562]="我的侄女丽丽无法静下心来探索潘达利亚。但如果只是蜻蜓点水般的东游西逛，是不可能了解一片全新土地的。重要的是，要跟你遇见的每一个人交谈，用心体会每一个地方，直到它已深入你的灵魂。$b$b这才是云游者之道！"
D.Strings[56563]="丽丽不明白为什么我总是停下来品尝各地的美酒。可根据我的经验，一个人群的性格，就体现在他们喝的东西里！$b$b你尝过大陆熊猫人的啤酒了吗？口感既清冽，又醇厚。只需品上一口，你就会知道，这酒是经由悉心慢酿而成。喝这酒的人，也必然是淡然恬静，不慌不忙，乐于与朋友分享美好的时光。$b$b你喝什么呢，$c？它又如何反映着你的性格，嗯？"
D.Strings[56564]="这些熊猫人农夫真是一群有趣的家伙！这是个紧密相连的社区。人人都熟悉彼此。$b$b跟卡利姆多或东部王国的那些大城市很不一样！"
D.Strings[56565]="你为何总是这么行色匆匆呢，$n？你不断地帮助一个又一个陌生人，醉心于丰富自己的经验。$b$b人生不只是一个供你装满水的玻璃杯，去享受你已发现的佳境吧！"
D.Strings[56566]="我的家人离开潘达利亚大陆去探索迷踪岛以外的世界。这是几代人之前的事。$b$b但是我知道潘达利亚这里还有其他风暴烈酒家族的成员！我失散已久的家人。他们长什么样子？他们还像我一样在酿酒吗？他们是和你我一样的冒险家吗？"
D.Strings[56567]="如果你在这谷里待足够长的时间，也许你能与所有当地人交上朋友。甚至有一天，你可以安顿下来，拥有属于自己的一亩三分地。$b$b想象一下，你这厌倦尘世的$c，却在这里安顿下来，管理农场！$b$b<陈闭上双眼，捧腹大笑。>"
D.Strings[56568]="拥抱云游者之道吧！与其说这是一个行动过程，不如说是一种态度。$b$b你遇到的每一个人都是一个故事。你去过的每一个地方都是一次冒险奇遇。你喝的每一杯酒都是前所未见的美酒。$b$b这种生活还算不错，对吧？"
D.Strings[56569]="<陈点头表示同意你的观点，但他看上去却一反常态地沉着脸。>"
D.Strings[56570]="灵魂世界之旅暂时在你身上留下了|cFFFF0000|Hspell:117723|h[脆弱灵魂]|h|r的效果！如果你在脆弱灵魂效果结束之前再次试图前往灵魂世界，你将立即消亡！"
D.Strings[56571]="这些神圣之水被污染了，但希望仍在。即便是面对如此巨大的腐蚀之力，我们古老的仪式也能坚持完成净化。当水复原后，污染之人的力量就会衰退。"
D.Strings[56572]="这种生物也许能从恐惧中汲取力量，但我们心中可没有恐惧。停止你的仪式，因为我们不需要别人帮忙净化这个地方。"
D.Strings[56573]="一旦停止这个仪式，我们将不能重新开始，腐蚀会保有全部力量。你的勇气令人钦佩，但如果你失败了，我们将无力回天。你明白你在做什么吗？你清楚后果吗？"
D.Strings[56574]="这是一个历史性的时刻，$n。你觉得在门外有什么在等着我们？"
D.Strings[56575]="当我问：“谁是主人？”你回答：“烁奴夫！”"
D.Strings[56576]="我燃起了战欲！"
D.Strings[56577]="来，面对死亡吧。"
D.Strings[56578]="我要把你的护甲当成战利品！"
D.Strings[56579]="|TInterface\\Icons\\inv_misc_bomb_05.blp:20|t破坏者吉普提拉克对|cFFFF0000$n|r施放了|cFFFF0000|Hspell:107268|h[破坏]|h|r！"
D.Strings[56580]="你死到临头了。"
D.Strings[56581]="你已被|cFFFF0000|Hspell:107268|h[破坏]|h|r击中！"
D.Strings[56582]="破坏者吉普提拉克引发了一连串的爆炸！"
D.Strings[56583]="很高兴在这里见到你，孩子。"
D.Strings[56584]="我做的到。战胜恐惧的方法便是直视它，坚定不移，毫不动摇。"
D.Strings[56585]="|TInterface\\Icons\\ability_parry.blp:20|t雪流大师启用他的|cFFFF0000|Hspell:106454|h[招架姿态]|h|r！"
D.Strings[56586]="愿灵魂与你同在，勇者。"
D.Strings[56587]="|TInterface\\Icons\\spell_nature_earthbind.blp:20|t雪流大师使用他的|cFFFF0000|Hspell:106434|h[飓风腿]|h|r！"
D.Strings[56588]="|TInterface\\Icons\\ability_hunter_sickem.blp:20|t雪流大师将目光转向了|cFFFF0000$n|r，开始|cFFFF0000|Hspell:118961|h[追逐]|h|r！"
D.Strings[56589]="让我们弄清楚！"
D.Strings[56590]="很好，这些利刃无坚不摧。它们仿佛从始至终都是为我存在的。"
D.Strings[56591]="雪流大师正在|cFFFF0000|Hspell:118961|h[追逐]|h|r你！如果被他抓住，他就会对你使用|cFFFF0000|Hspell:106352|h[狂风掼]|h|r！在追逐效果结束前，离雪流大师远点！"
D.Strings[56592]="|TInterface\\Icons\\inv_weapon_hand_30.blp:20|t雪流大师使出了|cFFFF0000|Hspell:106853|h[怒雷破]|h|r的招数！"
D.Strings[56593]="飞雪选择|cFFFF0000$n|r，作为用|cFFFF0000|Hspell:106706|h[钢铁漩涡]|h|r追踪的目标！"
D.Strings[56594]="飞雪正在用|cFFFF0000|Hspell:|h[钢铁漩涡]|h|r追赶你！在她选中其他人之前，离她远点！"
D.Strings[56595]="|TInterface\\Icons\\inv_sword_24.blp:20|t飞雪使出了|cFFFF0000|Hspell:106706|h[钢铁漩涡]|h|r的招数！"
D.Strings[56596]="影踪派新人将你选作|cFFFF0000|Hspell:106774|h[荣誉之战]|h|r的目标！在落败之前，他们会使出浑身解数来对付你！"
D.Strings[56597]="|TInterface\\Icons\\ability_warrior_battleshout.blp:20|t武器大师哈兰召唤了两名同伴加入战斗！"
D.Strings[56598]="|TInterface\\Icons\\inv_weapon_halberd_05.blp:20|t武器大师哈兰施放了|cFFFF0000|Hspell:111216|h[光明之刃]|h|r！"
D.Strings[56599]="你被武器大师哈兰的|cFFFF0000|Hspell:|h[光明之刃]|h|r技能杀死了。武器大师哈兰在使用该技能时会从两个方向中任选其一行进，所以试着根据他的行进路线作出反应，以免于被他击中！"
D.Strings[56600]="|TInterface\\Icons\\spell_shadow_psychicscream.blp:20|t皇家宰相佐尔洛克已经将你选作|cFFFF0000|Hspell:122761|h[吐气]|h|r技能的目标！利用你的生存技能，或让生存能力较强的同伴站在你和皇家宰相佐尔洛克之间！"
D.Strings[56601]="你被皇家宰相佐尔洛克的|cFFFF0000|Hspell:122713|h[力与魄]|h|r杀死了。试着进入|cFFFF0000|Hspell:122706|h[噪音取消]|h|r区域来尽量降低力与魄的伤害，并进行自我治疗或让同伴用治疗技能来保你不死。"
D.Strings[56602]="你被皇家宰相佐尔洛克的|cFFFF0000|Hspell:123791|h[女皇赞歌]|h|r杀死了。要确保让你自己或其中一位盟友移动至皇家宰相佐尔洛克所在的平台，并与皇家宰相佐尔洛克交战。"
D.Strings[56603]="皇家宰相佐尔洛克已将你|cFFFF0000|Hspell:122740|h[策反]|h|r为替螳螂妖帝国战斗！你原来的同伴必须把使你的生命降低至50%，才能帮你摆脱女皇的控制！"
D.Strings[56604]="你被皇家宰相佐尔洛克的|cFFFF0000|Hspell:122336|h[超声波之环]|h|r技能杀死了。当皇家宰相佐尔洛克开始施放|cFFFF0000|Hspell:122496|h[音波衰减]|h|r时，一定要从他身边走开，并躲避他发出的超声波之环。"
D.Strings[56605]="|TInterface\\Icons\\spell_shaman_earthquake.blp:20|t力冠三军库乌艾使用了|cFFFF0000|Hspell:119922|h[震荡波]|h|r技能！"
D.Strings[56606]="|TInterface\\Icons\\ability_druid_supriseattack.blp:20|t穆辛巴对|cFFFF0000$n|r施放了|cFFFF0000|Hspell:119946|h[毁灭]|h|r！"
D.Strings[56607]="|TInterface\\Icons\\inv_elemental_primal_air.blp:20|t鬼谋神算冥谷子召唤了|cFFFF0000|Hspell:119981|h[回旋风暴]|h|r！"
D.Strings[56608]="|TInterface\\Icons\\spell_druid_ursolsvortex.blp:20|t鬼谋神算冥谷子生成了一个|cFFFF0000|Hspell:120099|h[磁场]|h|r！"
D.Strings[56609]="|TInterface\\Icons\\ability_warrior_savageblow.blp:20|t势不可挡哈伊岩用|cFFFF0000|Hspell:123655|h[外伤打击]|h|r攻击了|cFFFF0000$n|r！"
D.Strings[56610]="我们全都在这。这是个历史性的时刻，$n。我的妻子在弥留之际预见到了在这些大门之外的光明之城。你觉得我们会找到什么？"
D.Strings[56611]="势不可挡哈伊岩用|cFFFF0000|Hspell:123655|h[外伤打击]|h|r攻击了你！在效果持续期间，治疗技能只会为你回复较少的生命值！"
D.Strings[56612]="只有一种办法可以弄清楚……"
D.Strings[56613]="|TInterface\\Icons\\spell_fire_meteorstorm.blp:20|t势不可挡哈伊岩用|cFFFF0000|Hspell:120195|h[流星]|h|r瞄准了|cFFFF0000$n|r！"
D.Strings[56614]="你被势不可挡哈伊岩的|cFFFF0000|Hspell:120195|h[流星]|h|r杀死了！一定要在势不可挡哈伊岩使用该技能时与你的同伴站在一起，从而分担伤害。"
D.Strings[56615]="|TInterface\\Icons\\spell_fire_fireball.blp:20|t势不可挡哈伊岩开始施放|cFFFF0000|Hspell:120167|h[燃烧]|h|r了！"
D.Strings[56616]="我会用自己的生命守护山谷！"
D.Strings[56617]="我们必须维护平衡！"
D.Strings[56618]="金莲必须保护山谷！"
D.Strings[56619]="只要我还有一口气在，仲夏原就会永享安宁！"
D.Strings[56620]="我们并肩战斗，兄弟们！"
D.Strings[56621]="把这些畜生从山谷里赶出去！"
D.Strings[56622]="能用生命守卫山谷，是我的荣耀！"
D.Strings[56623]="这是我们的战斗！"
D.Strings[56624]="啊——哈！检验我力量的机会又到了。"
D.Strings[56625]="他们在撤退！"
D.Strings[56626]="被这种……打败了……"
D.Strings[56627]="哈——哈！"
D.Strings[56628]="啧！你还得再练练才行。"
D.Strings[56629]="愿他们获得宁静。"
D.Strings[56630]="雪怒教会了我们勇气。"
D.Strings[56631]="山谷现在更加安全了。"
D.Strings[56632]="当她从怀特迈恩的尸体上将刀刃拔出时，刀刃变换了。"
D.Strings[56633]="你能相信这个小土地精的胆量吗？这个精明的小谈判者马上就能以他的价格把我搞破产。"
D.Strings[56634]="嗯哼！"
D.Strings[56635]="他指着前来的雕像，希望得到你的帮助。"
D.Strings[56636]="有猢狲强盗在偷酒！快阻止他！"
D.Strings[56637]="你好啊$n！游学者正在楼下讲学，要是你有兴趣不妨去听听。"
D.Strings[56638]="可怜的生物。"
D.Strings[56639]="我要教会你们力量的意义。"
D.Strings[56640]="雷神回来了，弱者。"
D.Strings[56641]="山谷属于韶天！"
D.Strings[56642]="我们会再次统治潘达利亚！"
D.Strings[56643]="谁也别想从我们的力量面前逃脱！"
D.Strings[56644]="快放弃吧。"
D.Strings[56645]="他的剑一旦出鞘，敌人已经没有好下场！请对蜥蜴人武士水刃马基恭敬地鞠躬！"
D.Strings[56646]="这是第一位熊猫人探险者——刘浪之歌。"
D.Strings[56647]="这首歌是由古文写成，那是皇帝和学者们使用的语言。现在几乎已经没人会说了。"
D.Strings[56648]="歌曲描绘了他的冒险之旅。"
D.Strings[56649]="勇敢的刘浪骑在海龟背上，出发去探索这个世界。"
D.Strings[56650]="有人记得那只海龟的名字吗？尹记得吗？"
D.Strings[56651]="没错，那只海龟被称作神真子。一开始，他的大小只容得下刘浪一人坐在上面。"
D.Strings[56652]="后来他越变越大，大得惊人，所以现在有些人叫他“迷踪岛”。"
D.Strings[56653]="有问题吗，昊？"
D.Strings[56654]="是的，昊——我们的家就在神真子的背上。"
D.Strings[56655]="刘浪在探索世界的过程中有许多发现——噢——怎么了，昊？"
D.Strings[56656]="这个问题问得好。历代以来，没人和神真子说过话。他只对刘浪开口。"
D.Strings[56657]="可我相信，神真子知道我们在这儿。而且他在乎我们每一个人！"
D.Strings[56658]="尤其是昊！刘浪曾经说过：“频频提问的人最为可贵。”"
D.Strings[56659]="“我们都该表现得像个孩子，因为世界才是长者，有很多东西要教给我们。”"
D.Strings[56660]="弟子们！弟子们！集中精神。"
D.Strings[56661]="有人知道刘浪多久回潘达利亚一次吗？"
D.Strings[56662]="哈哈，不是的，尹。刘浪走到哪儿就吃到哪儿。"
D.Strings[56663]="他每隔五年返回潘达利亚的主大陆一次。"
D.Strings[56664]="你说得对，尹。它被藏起来了，藏在迷雾后面。"
D.Strings[56665]="有人记得刘浪总是如何找到它的吗？楠？"
D.Strings[56666]="没错！刘浪总能设法回到家乡。每隔五年他就会回去，带走更多的探险者。"
D.Strings[56667]="是的，昊！只有最勇敢的熊猫人才会爬上龟背，与刘浪一同外出探索世界。"
D.Strings[56668]="神真子很久没有上岸了。可那也没能阻止某些熊猫人外出探险。"
D.Strings[56669]="是的，就像陈和丽丽！他们出去探索世界了。也许有一天，你们也会。"
D.Strings[56670]="很高兴你提出了这个问题，尹。刘浪一生都在探索世界，还在迷踪岛上养育了许多子女。"
D.Strings[56671]="最后他变得非常老迈，最后一次造访了潘达利亚。"
D.Strings[56672]="但却没有其他人愿意和他一同探险。于是他离开了。"
D.Strings[56673]="神真子再也没有返回潘达利亚。"
D.Strings[56674]="疲惫不已的刘浪告别了神真子——这位与他交情至深的老朋友。"
D.Strings[56675]="然后，刘浪去了禅杖林，身上背着那柄随他四处游历的竹伞。"
D.Strings[56676]="他撑开竹伞，把伞柄插进地里，坐在伞下乘凉。"
D.Strings[56677]="他闭上双眼，与大地融为一体。然后——你们知道发生了什么吗？"
D.Strings[56678]="他的竹伞……发芽了！生根，开花，变成了一颗树！"
D.Strings[56679]="嗯，是真的。要是你去禅杖林，就能看见了。"
D.Strings[56680]="那些在我们之前到来的长者，他们的禅杖也已生根发芽，那里已经长出参天密林。"
D.Strings[56681]="这不是个难过的故事！刘浪自己说过：“生时精彩，死亦无憾。”"
D.Strings[56682]="在我看来，刘浪的人生无比精彩。我们的一切都得益于刘浪——这位熊猫人探险者始祖。"
D.Strings[56683]="我们讲述他的故事，是为了让他能够被永远铭记。"
D.Strings[56684]="洛林，谢谢你！你的歌喉美极了。"
D.Strings[56685]="你能再唱一遍吗，唱给那些刚刚到来的弟子听？"
D.Strings[56686]="高贵马基的光荣结局……如果他不是他们当中的最后一个，我敢肯定，他的部族会感到自豪！"
D.Strings[56687]="影踪派一直是土地精的朋友。他们为什么不让我们进去做生意？"
D.Strings[56688]="我们长途跋涉。现在影踪派却说，他们不想要我们的商品。真是太奇怪了。"
D.Strings[56689]="我们一路上曾遇到愤怒的猢狲、发狂的雪人和肮脏的牦牛，最后来到这里。现在，影踪派把我们当陌生人。$b$b运气真是不好。"
D.Strings[56690]="我的鼻子凉了。这是非常糟糕的预兆。"
D.Strings[56691]="我在前来的途中丢失了牦牛。这可真糟糕。"
D.Strings[56692]="如果这个影踪派弟子不快点让我们进去，我就让他闻闻我的幸运符。"
D.Strings[56693]="太奇怪了。影踪派是我们最好的客户。我们将物资出售给他们，他们则保证我们的安全。$b$b现在为什么要对我们不理不睬？我无法理解。"
D.Strings[56694]="我怎么一句都听不懂？"
D.Strings[56695]="现在掠过死亡迷雾，迎向他双拳的是——阴险沉着的锦鱼人杀手——萨塔耶·布宇！"
D.Strings[56696]="噢，这个风光无限的杀手鲤鱼终于要变成俎上鱼肉。"
D.Strings[56697]="那首歌是关于什么的？"
D.Strings[56698]="神真子！"
D.Strings[56699]="所有人，请为破军比武场的新冠军欢呼！"
D.Strings[56700]="我们住在一只巨龟的背上？！"
D.Strings[56701]="嘘，昊。你一直都没注意听吗？"
D.Strings[56702]="我刚还觉得纳闷呢，怎么山峰会长蹼！"
D.Strings[56703]="海龟知道我们在这儿吗？"
D.Strings[56704]="甚至是昊？"
D.Strings[56705]="对，你们都该跟我学学。"
D.Strings[56706]="得了！我宁可从这桥上跳下去。"
D.Strings[56707]="……每当他饿了的时候？"
D.Strings[56708]="可潘达利亚不是被藏起来了吗？没人能找到它！"
D.Strings[56709]="因为海龟总会返回他们出生的海岸！"
D.Strings[56710]="那是不是说，我们的爸爸妈妈爷爷奶奶也都是探险者？"
D.Strings[56711]="可我们现在不怎么探险了，对吧？"
D.Strings[56712]="就像陈和丽丽·风暴烈酒！"
D.Strings[56713]="我想要探索世界！"
D.Strings[56714]="不行。到处都是巨魔。"
D.Strings[56715]="噢。好吧，当我没说过。"
D.Strings[56716]="游学者！刘浪后来又遇到了什么事？"
D.Strings[56717]="什么？什么？"
D.Strings[56718]="那不可能！"
D.Strings[56719]="真令人难过！"
D.Strings[56720]="他摆弄着你笼子上的锁。"
D.Strings[56721]="他指着东边的山谷，然后消失在暗影中。"
D.Strings[56722]="他努力想要挣脱。"
D.Strings[56723]="他精疲力竭地跌在地上。"
D.Strings[56724]="他指着前方的大厅。"
D.Strings[56725]="他示意让你等等。"
D.Strings[56726]="他小心翼翼地继续前进。"
D.Strings[56727]="你可以使用附近的炸弹和火炮来轰走猢狲！"
D.Strings[56728]="我还以为这会是一场“力量”的对决。可我却只看到软弱。"
D.Strings[56729]="我是国王的武器！你凭什么觉得自己有机会？"
D.Strings[56730]="你注定要失败。"
D.Strings[56731]="呃……那是什么？"
D.Strings[56732]="哇哦！小心点！这些砖有暴力倾向……"
D.Strings[56733]="云瓷砖不错。其他瓷砖不好。在入口楼梯的底部有一块瓷砖差点害我摔跤。我敏锐的目光又一次挽救了我美好的形象！"
D.Strings[56734]="噢宝贝儿！看来我们有伴了……你解决那些混蛋，我去酿酒。"
D.Strings[56735]="呦！就差一点儿。好，不如这样……"
D.Strings[56736]="这些尸体表明，魔古族似乎不擅长玩这个游戏。"
D.Strings[56737]="我知道了，知道了。"
D.Strings[56738]="嗯，好吗？"
D.Strings[56739]="我想我还蛮喜欢像跳房子一样地穿过走廊。真有意思！"
D.Strings[56740]="刚才还在这里踩来踏去的魔古大块头去哪儿了？"
D.Strings[56741]="他……简直……"
D.Strings[56742]="……丑毙了！"
D.Strings[56743]="那你在这干什么呢？大老远跑下来，就为了享有我的陪伴？"
D.Strings[56744]="是智派我来的。"
D.Strings[56745]="蠢蛋！！！"
D.Strings[56746]="蠢货，你们得跟我一起死！"
D.Strings[56747]="我失败了，可你们别想活着把这场胜利告诉任何人！"
D.Strings[56748]="火炮会烧灼大地，什么都不会留下！"
D.Strings[56749]="援军，过来消灭这群懦夫！"
D.Strings[56750]="哈哈，不会飞的蠢货！"
D.Strings[56751]="野牛人摧毁了一切！"
D.Strings[56752]="我们就不能消停一晚上吗？"
D.Strings[56753]="大家安静下来，听谢说。"
D.Strings[56754]="节日得救了！"
D.Strings[56755]="嘿，$n！我正在为节日酿制某种特饮。晚些时候再来吧，我请你喝上几杯。"
D.Strings[56756]="好了！我把它放在桌子上面了。"
D.Strings[56757]="外面在吵什么？"
D.Strings[56758]="效果不太好，$n。你还是别试了。"
D.Strings[56759]="我需要一分钟来恢复。"
D.Strings[56760]="我必须恢复力量。"
D.Strings[56761]="保护我！"
D.Strings[56762]="你的心智真是软弱。"
D.Strings[56763]="真是没用的东西。"
D.Strings[56764]="又一个弱者。"
D.Strings[56765]="你的意志听命于我。"
D.Strings[56766]="你闯进了自己的坟墓。"
D.Strings[56767]="你会成为听话的宠物。"
D.Strings[56768]="赶快，所有人拿好武器！"
D.Strings[56769]="寺庙决不会陷落！"
D.Strings[56770]="我们不允许出现这样的事情。"
D.Strings[56771]="我们欠你的太多了。"
D.Strings[56772]="从今天起，你就是我们的一员了。"
D.Strings[56773]="以影踪派弟子的身份，前进吧！"
D.Strings[56774]="这些家伙毫无品味。"
D.Strings[56775]="我给你准备了一些特别的！"
D.Strings[56776]="太容易看穿了。"
D.Strings[56777]="我对付过的兔妖都比你聪明。"
D.Strings[56778]="要是你做了热身，会发挥得更好。"
D.Strings[56779]="漂亮的招式。我得学学。"
D.Strings[56780]="如果你想这样打，那我就奉陪……"
D.Strings[56781]="哈？噢，嘿，敌人。"
D.Strings[56782]="在那场对决中，我想出了一种伟大的新配方。"
D.Strings[56783]="我们跟这些家伙不在同一水平线上。"
D.Strings[56784]="先淡啤，后烈酒，拳速疾，无影手。"
D.Strings[56785]="真是充满创意的战斗。"
D.Strings[56786]="什么？不！"
D.Strings[56787]="我们得阻止他们！"
D.Strings[56788]="你们别想从我们这儿过。"
D.Strings[56789]="招惹影踪派可不太明智。"
D.Strings[56790]="%s因要和他的唤珀者分开而愤怒了！"
D.Strings[56791]="魔古族在攻击寺院！"
D.Strings[56792]="魔古族在攻击砮皂寺。我们需要你的帮助。"
D.Strings[56793]="相信你自己的力量。"
D.Strings[56794]="别放弃！"
D.Strings[56795]="只要我还没倒下，寺院就不会陷落。"
D.Strings[56796]="你的力量是我的！"
D.Strings[56797]="在我面前自取灭亡！"
D.Strings[56798]="我会展示真正的力量！"
D.Strings[56799]="你永远都赢不了！"
D.Strings[56800]="见识一下恐惧之心！"
D.Strings[56801]="你的软弱背叛了你。"
D.Strings[56802]="像风中落叶一样飘零吧！"
D.Strings[56803]="你什么都不是。"
D.Strings[56804]="不。不！"
D.Strings[56805]="我不会被打败。"
D.Strings[56806]="事情不该是这个样子的！"
D.Strings[56807]="我的力量在衰退！"
D.Strings[56808]="主人，指挥我！"
D.Strings[56809]="你休想躲过这场风暴。"
D.Strings[56810]="你已经被螳螂妖包围了。"
D.Strings[56811]="你的寺院被攻破。"
D.Strings[56812]="你的守卫被屠杀。"
D.Strings[56813]="你被遗忘了。这才是你最害怕的吧？"
D.Strings[56814]="远离人群，在长城的阴影中彷徨。"
D.Strings[56815]="你独自面对强大的虫群，如同黑暗之海中的一线光明。"
D.Strings[56816]="你那些同为天神的兄弟姐妹来帮助过你吗？不，没有。"
D.Strings[56817]="如果你倒下了，又有谁会在意？"
D.Strings[56818]="把你的衣钵传给我的宠物，让新的天神取代你！"
D.Strings[56819]="那我别无选择，只能杀了你。"
D.Strings[56820]="山泽！黑风！杀了他！"
D.Strings[56821]="哈！轻而易举！"
D.Strings[56822]="哈！真好玩！"
D.Strings[56823]="该去粉碎我们的敌人了。"
D.Strings[56824]="打得好，朋友！"
D.Strings[56825]="让我们瞧瞧你的本事！"
D.Strings[56826]="太轻松了。真让人失望！"
D.Strings[56827]="胜利的气味！"
D.Strings[56828]="也许你会是个挑战？"
D.Strings[56829]="真是浪费时间。"
D.Strings[56830]="胜利的荣耀！"
D.Strings[56831]="那不可能。"
D.Strings[56832]="他们不行了！乘胜追击！"
D.Strings[56833]="干得好！你真是个像样的战士。"
D.Strings[56834]="打完一场漂亮的仗，感觉总是很美妙。"
D.Strings[56835]="让我们庆祝吧！"
D.Strings[56836]="挡住他们！不能让他们知晓我们的秘密！"
D.Strings[56837]="这场战斗对我们有利。"
D.Strings[56838]="小心——不要放松警惕。"
D.Strings[56839]="养精蓄锐，来日再战。"
D.Strings[56840]="我们绝不动摇。"
D.Strings[56841]="我们打得很好，但也不能冒进。"
D.Strings[56842]="去杀敌吧——我来做你的后盾。"
D.Strings[56843]="为同胞们的福祉而战。"
D.Strings[56844]="你打得很好，但不要太自满了。"
D.Strings[56845]="为了牺牲的人们！"
D.Strings[56846]="你们休想再伤害无辜者们！"
D.Strings[56847]="我们赢得了战斗。"
D.Strings[56848]="只有这家伙死掉，我才能松口气。"
D.Strings[56849]="无法容忍。"
D.Strings[56850]="为了影踪派！"
D.Strings[56851]="坚持住！胜利在望了。"
D.Strings[56852]="打得好。我很高兴你能活下来。"
D.Strings[56853]="和你并肩作战是我的荣幸。"
D.Strings[56854]="我要去缅怀那些不能与我们分享胜利的人了。"
D.Strings[56855]="一片充满失落秘密的新大陆！跟这里的游学者和我分享你了解到的一切，我会让你参与到其它的项目中来。"
D.Strings[56856]="让我参与你其它的项目吧。"
D.Strings[56857]="你在这里做得十分出色，朋友。我们应该很快就能建立起强大的行动基地了——去看看还有没有别人需要你的帮助。"
D.Strings[56858]="你干得十分出色。我们现在应该能轻松守住这里的行动基地了。"
D.Strings[56859]="为什么？为什么非得是他？"
D.Strings[56860]="我会讨回公道！"
D.Strings[56861]="以命偿命！"
D.Strings[56862]="出发前别忘了跟非离谈谈。她的技能会有力地帮你对付我们的敌人。"
D.Strings[56863]="你的进步比我预想中快得多。"
D.Strings[56864]="如果你需要我协助作战，就告诉我一声。"
D.Strings[56865]="和你并肩战斗是我的荣幸。"
D.Strings[56866]="相信女皇的力量吧！她会引领我们走向辉煌！"
D.Strings[56867]="团结起来，虫群会比这片土地上的任何帝国都要强大！"
D.Strings[56868]="女皇的意志就是我们的意志。女皇的伟大就是我们的伟大。女皇的胜利就是虫群的胜利！"
D.Strings[56869]="你竟敢藐视女皇的声音？这声音足以号令整个虫群！"
D.Strings[56870]="亵渎！你不是虫群的一员！"
D.Strings[56871]="你只是个对抗女皇圣怒的渣滓！你也必将灭亡！"
D.Strings[56872]="虫群将像利刃般刺穿我们的敌人！"
D.Strings[56873]="只需一刀就够了。"
D.Strings[56874]="敌人将在我们的利刃下毙命！"
D.Strings[56875]="你想试试我利刃的刀锋吗？"
D.Strings[56876]="我闻到了卡拉克西大逆不道的臭味！站住，面对刀锋领主吧！"
D.Strings[56877]="啊哈哈哈哈哈……这样疼不疼？"
D.Strings[56878]="冷风呼啸。虫群的时代到了！"
D.Strings[56879]="他们真以为用一道石墙就能挡住我们？挡住御风而来的骑士？"
D.Strings[56880]="浩荡的虫群会遮天蔽日！永恒的黑夜将吞噬这片土地！"
D.Strings[56881]="渗透者！你别妄想阻挡虫群！"
D.Strings[56882]="飞走了，小骑士？真正的勇士即便心怀恐惧也会面对我！"
D.Strings[56883]="枉费力气。"
D.Strings[56884]="对，我的小怪物们！去吧！肆意蹂躏我们的敌人！"
D.Strings[56885]="实验下一阶段开始了！"
D.Strings[56886]="啊，要是让我抓住你就好了！你肯定是个绝佳的实验品！"
D.Strings[56887]="啊啊！好疼！"
D.Strings[56888]="你……怕了吗？"
D.Strings[56889]="这个岛上挤满了女皇的仆从。"
D.Strings[56890]="这场仗可没那么好打。"
D.Strings[56891]="必须要将女皇绳之以法。"
D.Strings[56892]="不要害怕。"
D.Strings[56893]="恐惧只是假象。"
D.Strings[56894]="前进吧，战士！"
D.Strings[56895]="为了虫群！"
D.Strings[56896]="正义必胜。"
D.Strings[56897]="她必须要偿还自己的罪孽。"
D.Strings[56898]="你做得不错，城墙行者。"
D.Strings[56899]="你比看上去勇敢得多，陌生人。"
D.Strings[56900]="别让恐惧吞噬你！"
D.Strings[56901]="我们不能让他们毁掉这棵树。"
D.Strings[56902]="我们不能让他们毁掉这棵树。就只剩下这一棵了。"
D.Strings[56903]="战争还没结束，可我们已经让他们受到重创。"
D.Strings[56904]="不要跟卡拉克西作对。"
D.Strings[56905]="啊，看看是谁加入我们了。"
D.Strings[56906]="看来英杰终于前来扭转局势了。"
D.Strings[56907]="你这落伍的老古董！"
D.Strings[56908]="你打算如何与虫群之力抗衡？"
D.Strings[56909]="不值一提。不堪一击。"
D.Strings[56910]="虫群将吞噬你们！"
D.Strings[56911]="很可怕是吧？"
D.Strings[56912]="你……害怕了？"
D.Strings[56913]="见证虫群的力量吧！"
D.Strings[56914]="我……孤身一人。"
D.Strings[56915]="这还……不够。"
D.Strings[56916]="我让你失望了，女皇陛下。"
D.Strings[56917]="有人说过，宁愿点燃蜡烛，也不愿意诅咒黑暗……$b$b好吧，他们点过的蜡烛可能没我多。"
D.Strings[56918]="能给我根红萝卜吗？"
D.Strings[56919]="你有多余的甘甜湖瓜吗？"
D.Strings[56920]="我能帮艾拉拿个毛桃吗？"
D.Strings[56921]="你这里有黑樱桃吗？"
D.Strings[56922]="哎呀，我自己正要吃呢！好吧，要是艾拉想要，我就不能不给。接着，拿去吧！"
D.Strings[56923]="可爱的小艾拉要一根萝卜？是的，我肯定能让出一根。给你。"
D.Strings[56924]="小艾拉在试着酿酒？好吧，我是！祝她好运。你知道，酿造不是新手可以掌握的。无论如何，我可以让给她一个湖瓜。"
D.Strings[56925]="我本该向你收取买那个桃子的一大笔钱，但考虑到艾拉是我最好的顾客，这个就免费送给你。仅此一次，听到了吧！"
D.Strings[56926]="有句话是这么说的——“你的脸朝向太阳，阴影将落在你身后。”$b$b我希望你能发现光明的未来，$n！"
D.Strings[56927]="哇！这可是个好东西！在哪里能找到更多？"
D.Strings[56928]="嗯，这味道好极了！好极了！这是我这么长时间以来尝到的最好的东西。是谁酿造的？"
D.Strings[56929]="嗯，口味太棒了，$n。我不会介意再来一杯……或两杯……嗝！"
D.Strings[56930]="嗯，自从……风暴烈酒酿造厂的黄金时代过后……我就没有尝到过口感如此醇厚清冽的美酒！无论是谁酿的，他都是一个真正的人才。"
D.Strings[56931]="从一而精，此为烹饪之道。"
D.Strings[56932]="嗯。嗯……这……简直是……令人吃惊。你的朋友艾拉真是太有天赋了！让她去找我在酿造厂的高老伯谈一谈。我想她已经在我们风暴烈酒家族里找到了自己的位置。"
D.Strings[56933]="<米师关切地看着你。>"
D.Strings[56934]="<米师不明白你为什么这么做。>"
D.Strings[56935]="<米师不明白你在做什么。>"
D.Strings[56936]="<米师歪着脑袋，好奇地看着你。>"
D.Strings[56937]="<米师看着你。>"
D.Strings[56938]="<米师很高兴和你在一起！>"
D.Strings[56939]="<米师兴奋得上窜下跳。>"
D.Strings[56940]="<米师冲着你笑。>"
D.Strings[56941]="<米师欢快得上窜下跳。>"
D.Strings[56942]="<米师很快乐！>"
D.Strings[56943]="用香料喷洒将猢狲从车上赶下去！"
D.Strings[56944]="对跳到车上的猢狲使用香料喷洒！"
D.Strings[56945]="哇！一切都应该从此一帆风顺！"
D.Strings[56946]="从没有任何外来者与纳拉克煞引擎如此接近。"
D.Strings[56947]="看来我们成功了！我们畅通无阻了！"
D.Strings[56948]="不见了！哇！看来障碍已经消除。"
D.Strings[56949]="我们成功了！从这里开始，应该畅通无阻了。"
D.Strings[56950]="噢！伟大的幸运符！那是什么？！"
D.Strings[56951]="噢！最不幸的日子！那是什么？"
D.Strings[56952]="我们最不幸的日子！那是什么？"
D.Strings[56953]="噢！雪人跟来了！"
D.Strings[56954]="噢！后边有雪人！快走，牦牛！快点，再快点！"
D.Strings[56955]="噢！雪人跟来了！看来我们还没有摆脱这些麻烦呢！"
D.Strings[56956]="你就带着这些秘密一起进棺材吧。"
D.Strings[56957]="我们正要去参加云游节。你一定得跟我们一起去！"
D.Strings[56958]="今晚就是云游节了。你要来参加吗？"
D.Strings[56959]="云游节是什么？"
D.Strings[56960]="相传刘浪曾经骑在一只巨龟背上，去探索潘达利亚之外的广阔海域。他每隔几年会回来一次，并邀请新的探险家与他同行。直到今天，每当有熊猫人做白日梦或者呆望天空的时候，我们便会问他们是不是在“等待海龟”。$b$b大部分熊猫人并不爱冒险。他们喜欢温暖舒适的居家生活。但我们中仍然有一些梦想家……今晚我们将聚集在南部海岸的海龟沙滩眺望大海，纪念刘浪的冒险精神。$b$b这就是“云游节”。"
D.Strings[56961]="这就是云游节，$n！具有冒险精神的熊猫人在这里聚集一堂，庆祝第一位冒险穿越迷雾的探险家。$b$b这是沉思和歌颂的时刻。感谢你的加入！"
D.Strings[56962]="欢迎光临，$n！$b$b这是“云游节”，我们都聚集在海滩上眺望大海，以纪念第一个熊猫人探险家的事迹。$b$b笼罩潘达利亚的迷雾曾经非常浓密，那时你甚至看不到近海处的大岩石。现在再看看这里，多么美丽的夜晚啊！我很高兴你能来这里参加这个盛会。"
D.Strings[56963]="游学者周卓！我很高兴你能和我们一起度过这一周。"
D.Strings[56964]="你可以为我们唱刘浪之歌吗？"
D.Strings[56965]="你的声音太动人了。有时我甚至觉得能在你的歌声中听到整支乐队的美妙乐音！"
D.Strings[56966]="游学者，谢谢你！"
D.Strings[56967]="$n！很高兴看到你来和我们一起庆祝云游节！$b$b人们常说熊猫人不是探险的料。但是看看周围的这些人的脸庞，啊，你看到了吗？这些属于梦想家的闪亮眼睛！$b$b我相信不久的将来，就会出现更多被世人传颂的熊猫人冒险家，他们会遍布世界的各个角落并有所作为。你不这样觉得吗？"
D.Strings[56968]="我要给你一个惊喜。你猜他们正在庆祝什么？你认为庆祝这个节日，喝什么比较合适呢？"
D.Strings[56969]="哇，不可思议！快看这些灯！$b$B你觉得那是什么？骑在海龟背上的那个家伙是谁？$b$b等等，那是刘浪吗？$b$b那只海龟肯定就是神真子了。没错！那座雕像就是一座微缩的迷踪岛！$b$B陈叔，我们回到家了！$b$b嗯，几乎算到家了。"
D.Strings[56970]="避开或者破坏嘎什努尔的风暴图腾。"
D.Strings[56971]="%s从他的驭风者上下来了。"
D.Strings[56972]="巴巴姆还没醉，巴巴姆还能喝！"
D.Strings[56973]="来跳支猢狲舞吧！"
D.Strings[56974]="嘿呀！我这儿有酒。"
D.Strings[56975]="乌克还在做饭和酿酒！"
D.Strings[56976]="戈卡戈卡要点亮这个派对！"
D.Strings[56977]="我想跟翔龙宝宝练习接球。"
D.Strings[56978]="看来你已经在跟翔龙宝宝练习接球了，$n。你每次只能跟一条翔龙玩接球。$B$B在跟其他翔龙练习之前，请先完成你当前的训练课程。"
D.Strings[56979]="我完成练习了。请收回你的雏龙。"
D.Strings[56980]="这里到处都熠熠生辉。我未必会喜欢这里。它似乎少了点“居家”的味道。"
D.Strings[56981]="将弹力球扔向你的翔龙，看你们能让它在空中停留多长时间！完成练习后请告诉我，我会带走你的翔龙。祝你好运！"
D.Strings[56982]="那么，情况如何？应该还不错吧？"
D.Strings[56983]="固定"
D.Strings[56984]="潘达利亚的子民们，迷雾已经散去。无论如何，这片土地都将对外开放。"
D.Strings[56985]="让我们团结一致，重建这片神圣的土地，向治愈这个破碎的世界迈出第一步。"
D.Strings[56986]="我信任来自迷雾之外的朋友们。"
D.Strings[56987]="嗯……这股力量是种鼓舞……至关重要。要相信他们的心是纯洁的。"
D.Strings[56988]="只要……再来……一次！"
D.Strings[56989]="联盟……在逼近……"
D.Strings[56990]="我的力量就是你的力量。让我们一起去消灭我们的敌人吧！"
D.Strings[56991]="在对付多个敌人时，我的信息素将会有所帮助。"
D.Strings[56992]="快去打开这个东西。"
D.Strings[56993]="不，不，不要起来。这里没有战争，士兵，你需要休息。"
D.Strings[56994]="|TInterface\\Icons\\ability_warlock_soulsiphon:20|t%s开始施放|cFFFF0000|Hspell:126299|h[灵魂释放]|h|r！快跳进水里！"
D.Strings[56995]="这里的建筑很奇怪，与传统的魔古族设计风格有很多不同之处。这个房间似乎是某种装置，但是从我的笔记上看不出它的用途。\n$b我们只有去激活它然后观察，才能弄清其用途。\n$b最糟糕的情况会是什么呢？"
D.Strings[56996]="我们在迷雾中航行了好几个小时了，将军。船员们感觉很不好……"
D.Strings[56997]="坚守岗位，士兵！就算死也要找到那片陆地。"
D.Strings[56998]="联盟舰船！左舷方向！"
D.Strings[56999]="右舷发现敌舰！炮火准备！自由射击！"
D.Strings[57000]="|TInterface\\Icons\\ability_warrior_charge.blp:20|t%s将目光转向|cFFFF0000$n|r并开始施放|cFFFF0000|Hspell:127245|h[致命一击]|h|r！快跑开！"
D.Strings[57001]="部落……来了……"
D.Strings[57002]="直接命中！她掉下去了！"
D.Strings[57003]="陆地，吼吼！"
D.Strings[57004]="这个房间里涌动着能量，但是和我们所见过的完全不同。"
D.Strings[57005]="太棒了，我从没听说过这样的事。魔古族很擅长保密。"
D.Strings[57006]="这好像是这个装置的控制终端。看这儿……"
D.Strings[57007]="每天都有越来越多的陌生人登上我们的海滩。$b$b直到昨天晚上，这群人才停止向对方射击。但愿这不是什么事情即将发生的预兆。"
D.Strings[57008]="呃，情况不对，将军……我们下降得……很快！"
D.Strings[57009]="传感器上线。所有核心满功率运转。"
D.Strings[57010]="启用"
D.Strings[57011]="认证矩阵不匹配。检测到不明物体。"
D.Strings[57012]="%s开始施放|cFFFF0000|Hspell:116529|h[能源关闭]|h|r！"
D.Strings[57013]="太神奇了！它说话了……看来我们低估了魔古族的能力。"
D.Strings[57014]="噢……这恐怕要糟糕。我还是把它留给你，然后远远地看着吧。"
D.Strings[57015]="你需要什么东西吗？"
D.Strings[57016]="我们要追捕敌人。"
D.Strings[57017]="我会成为插入敌人咽喉的那把利刃。"
D.Strings[57018]="机器已经被摧毁了，魔古族的力量也被削弱了。"
D.Strings[57019]="没有人敢和影踪派作对。"
D.Strings[57020]="这些圆盘很眼熟，但我无法找到其出处。"
D.Strings[57021]="圆盘……在召唤我……我必须……"
D.Strings[57022]="我……我终于看清了一切。"
D.Strings[57023]="泰坦……？看来魔古族篡改了古代泰坦技术，并以此发展壮大他们的帝国！"
D.Strings[57024]="我们得走了，还有更多事情要做。"
D.Strings[57025]="“赤烟”腾武向你问好。"
D.Strings[57026]="影踪派的所有敌人都将倒在“赤烟”腾武面前。"
D.Strings[57027]="别让那些弓箭手登上墙头。让莱公冲到大门前。"
D.Strings[57028]="来……尝尝这个吧。"
D.Strings[57029]="噢，是啊。唔，我……很抱歉没能让你称心如意……"
D.Strings[57030]="她早该变成一堆枯骨和烂泥了！她还真有一个好胃啊……"
D.Strings[57031]="在我的族人间存在两大修行戒律。土水派耐心沉稳，谨慎从容；火金派凶猛激进，活跃积极。两种戒律各有用途，而又相辅相成，缺一不可。"
D.Strings[57032]="我主要是帮助年轻的熊猫人在这些方面发掘他们的潜力。虽然真正掌握技巧需要大量的时间和练习，但首先寻找到一种合适的方法也十分重要。"
D.Strings[57033]="父……亲……"
D.Strings[57034]="啊，当然。"
D.Strings[57035]="耐心地寻找你的力量。"
D.Strings[57036]="哇！嗯，太有趣了！"
D.Strings[57037]="是谁控制着这个虫群！出来！ 回应卡拉克西的召唤。"
D.Strings[57038]="报上名来，傀儡，让我们的历史记载更完整些。"
D.Strings[57039]="你的“女皇”已经倒下了。卡拉克西做出了判决。让开，否则就死。"
D.Strings[57040]="亵渎！"
D.Strings[57041]="只有集中精力，才能直面任何考验。"
D.Strings[57042]="只有冷静的头脑能够做好战斗的准备。"
D.Strings[57043]="你喜欢神奇的冶金技术、奥妙的熔炼技艺、优美的合金秘法吗？"
D.Strings[57044]="<咳嗽><结巴>我……我回来了。"
D.Strings[57045]="系好你的安全带……开玩笑啦，我们没有安全带！"
D.Strings[57046]="我们到了吗，雪人？"
D.Strings[57047]="唤醒者，你的功劳为你赢得了我们的信任。"
D.Strings[57048]="希望这头牦牛知道上山的路，因为我不知道！"
D.Strings[57049]="这是你第一次来不息山？我也一样！"
D.Strings[57050]="我明白，土水派之道并非通向智慧之门的唯一途径。但，有些选择依然令人无法接受，有些风险仍然令人难以承担，有些决定始终让我难以原谅……$B$B现在，是我离开神真子的时候了。我敬重德罗娜·莱因哈特的信心和勇气，她口中有关联盟的故事对她的人民赞誉有加。我还不知道自己是否能在那里找到归宿，但是无论我的道路通向何方，我都会找到一个方法来帮助迷踪岛之外的世界。$B$B无论如何，我很喜欢我们共处的这段短暂时光，$n。我希望你可以和我一起走，但我明白做这个决定并不容易。"
D.Strings[57051]="你将受到嘉奖。随我来。"
D.Strings[57052]="只有登上山顶，我们才能休息！嗨？明白了吗？"
D.Strings[57053]="我们螳螂妖是个古老的种族。你结识的熊猫人——不过是孩童。他们有自己要扮演的角色。"
D.Strings[57054]="每次轮回，我们年轻的虫群涌上长城。熊猫人杀光弱者。而强者得以返回。"
D.Strings[57055]="代代繁衍，我们变得越发强大。"
D.Strings[57056]="嗯，也许我应该将小货车带来，这样操作起来会更方便一些。"
D.Strings[57057]="在你们之前，我们的帝国早已广大无边。我们与姐妹王国安其拉和艾卓-尼鲁布平分这个世界。"
D.Strings[57058]="我们的神祗众多而强大。我们螳螂妖崇拜的是七首亚煞极。"
D.Strings[57059]="上古尊者很伟大，可发起怒来令人胆寒。他吞噬希冀，招引绝望；他吸进勇气，呼出恐惧。"
D.Strings[57060]="被你们称为“泰坦”的篡位者到来时，亚煞极遭到了毁灭。"
D.Strings[57061]="他最后的恐怖呼吸变成挥之不散的阴影，可跟他先前的荣耀相比不值一提。"
D.Strings[57062]="我们信任你，所以给你这个警告。"
D.Strings[57063]="你的神将不再是神，外来者。"
D.Strings[57064]="一旦上古尊者归来，螳螂妖将再一次追随他们。"
D.Strings[57065]="你们当中的智者也会如此。"
D.Strings[57066]="要说的就这么多。来吧，拿上你的奖赏。记住你今天学到的一切。"
D.Strings[57067]="看来今天注定是充满了艰难抉择的一天。为了我们大家着想，我必须勇敢地面对这些抉择。我做了我必须做的事情，如果不这样做，我们可能已经全都命丧黄泉了……不幸的是，并非所有人都这样想。$B$B我想现在是时候离开神真子了，这样大家就不用为我的艰难抉择而背上负担，我也可以为更多的人继续战斗。$B$B我和科尔加相识不久，但一见如故，如果不是因为肤色不同，我们本应成为兄弟，我敬佩他的勇敢和气节，能够与他并肩作战是我的荣耀。你也本应成为我的$g兄弟:姐妹;，毕竟我们一起出生入死过。我希望你能加入我们，但我理解事情并非如此简单。"
D.Strings[57068]="我的家族以制作玉石和宝石为生，这门手艺已经传承了将近十代人。我能传授给你的技艺可能会令你大吃一惊。"
D.Strings[57069]="我不得不承认，这非常有趣！"
D.Strings[57070]="看来你交到了一位新朋友。"
D.Strings[57071]="他真难对付……"
D.Strings[57072]="精力充沛，不知疲倦。一天到晚都在埋头苦干。"
D.Strings[57073]="不少治疗者被困在了残骸里。救他们出来！"
D.Strings[57074]="帮助那些治疗者摆脱敌人！我们需要他们来这儿治愈伤口。"
D.Strings[57075]="别离开太远，保护治疗者！我们全指望他们了。"
D.Strings[57076]="要是治疗者们遭遇不测，神真子和我们都死定了。保护好他们！"
D.Strings[57077]="来吧，朋友。部落在等着我们！"
D.Strings[57078]="让我们看看这位“大酋长”是何方神圣。"
D.Strings[57079]="结合部落的力量，我们一起把这个世界变得更好！"
D.Strings[57080]="|TInterface\\Icons\\warrior_talent_icon_lambstotheslaughter.blp:20|t你要被|cFFFF0000|Hspell:127275|h[处刑]|h|r！"
D.Strings[57081]="<艾莎似乎正沉浸在她的功课中。>"
D.Strings[57082]="你是来学习的？真是个幸运的家伙。我能教给你很多东西。"
D.Strings[57083]="啊！一个药剂爱好者？酒仙们知道如何调配化合物，但却常常遗漏药剂或疗法的精细配方。"
D.Strings[57084]="你要找光板儿？"
D.Strings[57085]="你有好吃的？"
D.Strings[57086]="你为什么叫光板儿？"
D.Strings[57087]="光板儿听到了口哨声！"
D.Strings[57088]="你为什么要叫醒光板儿？"
D.Strings[57089]="光板儿在这儿！"
D.Strings[57090]="你究竟要干嘛？"
D.Strings[57091]="光板儿能帮上忙！"
D.Strings[57092]="你想从光板儿这里得到什么？"
D.Strings[57093]="光板儿，给我搜！"
D.Strings[57094]="光板儿马上回来！"
D.Strings[57095]="你可真棒！"
D.Strings[57096]="光板儿找到礼物了！"
D.Strings[57097]="你只是向神器中注入了魔力，并不意味着那些魔力将永远留存在其中。"
D.Strings[57098]="光板儿回来了！"
D.Strings[57099]="是的，你小子最好快点逃跑！"
D.Strings[57100]="光板儿把礼物带给你！"
D.Strings[57101]="光板儿任你差遣！"
D.Strings[57102]="小兔崽子，我要你不得好死！"
D.Strings[57103]="光板儿能帮上忙！看见没？？"
D.Strings[57104]="我要把你剁成一堆肉泥！"
D.Strings[57105]="黑蹄会把你碾成尘土！"
D.Strings[57106]="感受野牛人的力量吧！"
D.Strings[57107]="你已经激怒了公牛，现在，准备面对我的犄角吧！"
D.Strings[57108]="达卡要杀了你！"
D.Strings[57109]="我在影踪派期间学到了许多秘技。或许你也已经有幸学到了一些。"
D.Strings[57110]="你！你在这儿干嘛？"
D.Strings[57111]="黑夜漫漫，处处凶险。"
D.Strings[57112]="我要抽你的筋，剥你的皮！"
D.Strings[57113]="我要将你放逐到狂风和鬼魂肆虐之地！"
D.Strings[57114]="感受黑暗之拳吧！"
D.Strings[57115]="你的死期就要到了。"
D.Strings[57116]="黑暗降临了。"
D.Strings[57117]="你的灵魂将属于我！"
D.Strings[57118]="消灭他们。"
D.Strings[57119]="你将承受痛苦。"
D.Strings[57120]="我要赤手空拳打爆你的头。"
D.Strings[57121]="死亡！末日！毁灭！"
D.Strings[57122]="你将被痛苦地折磨致死……"
D.Strings[57123]="又来一群送死的……"
D.Strings[57124]="来吧，杂碎，你们死到临头了。"
D.Strings[57125]="不！我必须回去向她汇报！"
D.Strings[57126]="你走得有点远啊，不是吗？"
D.Strings[57127]="她会保护我！"
D.Strings[57128]="我能感受到你的恐惧……"
D.Strings[57129]="我的同胞无穷无尽。"
D.Strings[57130]="雏龙将享用你的尸体！"
D.Strings[57131]="螳螂妖将席卷这片土地，挡我者死！"
D.Strings[57132]="池水翻波……"
D.Strings[57133]="涛生涛灭……"
D.Strings[57134]="你敢打断我的冥想？你要付出代价……"
D.Strings[57135]="我能看到你的末日……"
D.Strings[57136]="水流预示了你的灭亡……"
D.Strings[57137]="如果你想学习有关熔炼的知识，随时可以来找我！"
D.Strings[57138]="水流因你的靠近而翻涌……"
D.Strings[57139]="雷鸣的深渊正在召唤你……"
D.Strings[57140]="我们想要什么就拿什么！"
D.Strings[57141]="我要把你的皮做成帽子戴！"
D.Strings[57142]="不！我的金子！！"
D.Strings[57143]="你们给我们的家园带来了战争！我要让你们也尝尝战争的滋味！"
D.Strings[57144]="我心中的这片阴影，正是你造成的！"
D.Strings[57145]="我被蒙蔽了，你为什么要这样对待我们？"
D.Strings[57146]="只要结果了你，这片土地就不会再有死亡！"
D.Strings[57147]="我必须屈从于愤怒！这是唯一的出路！"
D.Strings[57148]="都是因为你，让我的训练全白费了！"
D.Strings[57149]="我灵魂中的黑暗呼之欲出！"
D.Strings[57150]="我要干掉你！"
D.Strings[57151]="好好教训他们！"
D.Strings[57152]="我要打烂你的脸！"
D.Strings[57153]="你还有点脑子！"
D.Strings[57154]="哈哈，你碰不到伊克伊克！"
D.Strings[57155]="我要揍扁你！"
D.Strings[57156]="拜托，美味的小动物，跟马尔泰走吧？"
D.Strings[57157]="嘿嘿，嘿嘿，嘿嘿嘿……"
D.Strings[57158]="马尔泰想要个毛茸茸的伙伴！！"
D.Strings[57159]="不！马尔泰的宝贝是马尔泰的！"
D.Strings[57160]="这片陌生的新土地上长满了各种草药和药石，但你要先学会如何去寻找它们。"
D.Strings[57161]="莉莉安的灵魂逐融入了亡者的国度！她将免疫一切伤害！"
D.Strings[57162]="皇帝的力量出现在壁龛中！"
D.Strings[57163]="一个也别放走！"
D.Strings[57164]="皇帝的勇气出现在壁龛中！"
D.Strings[57165]="不要松懈，毫不留情！"
D.Strings[57166]="猎犬太多了。我们顶不住啊！"
D.Strings[57167]="我辜负了……我的弟兄们……"
D.Strings[57168]="你是来看老泰平的吗？听说过我的绰号吗？为了表现我的剥皮技艺，人们曾经称我为“理发师”。"
D.Strings[57169]="带上这块石头。早晚会用得上。"
D.Strings[57170]="准备倒计时，3……"
D.Strings[57171]="开始翻滚！"
D.Strings[57172]="你偏离了翻滚路线！"
D.Strings[57173]="路线完成！"
D.Strings[57174]="恭喜！"
D.Strings[57175]="你是第一名！"
D.Strings[57176]="你是第二名！"
D.Strings[57177]="你是第三名！"
D.Strings[57178]="周泽客小声的嘀咕着。"
D.Strings[57179]="<螳螂妖从藏身处显身。>$b$b退后，$r。$b$b女皇已经疯了。我们卡拉克西正在召集人马，准备向她的王座发动突袭，但是我们尚未做好准备。你也一样。$b$b进攻的时刻即将到来……但不是现在。"
D.Strings[57180]="多亏了你，猢狲开始忌惮你的族人了。暂且等我一下——"
D.Strings[57181]="啊！好了。在一万四千多年以前，这整片大陆由一个名叫“魔古”的可怕督军部族统治。"
D.Strings[57182]="魔古族用恐惧统治臣民，用恐惧维持强权……直到第一代熊猫人武僧激发了人民的勇气。"
D.Strings[57183]="于是魔古族的政权被推翻了。"
D.Strings[57184]="你看，凭恐惧统治的帝王，只能在臣民缺乏勇气时才能永掌大权。"
D.Strings[57185]="猢狲有许多特点，但并不懦弱——至少不会一直懦弱。如果你不想和他们交战，就必须……激励他们！"
D.Strings[57186]="我会帮助你，可我想先对你的族人有所了解。你愿意花点时间随我走走吗？"
D.Strings[57187]="我今天需要你的帮忙，伊约库克。"
D.Strings[57188]="我今天需要你的帮忙，虫群卫士。"
D.Strings[57189]="我今天需要你的帮忙，暴食蝗。"
D.Strings[57190]="我今天需要你的帮忙，操纵者。"
D.Strings[57191]="在杀死一个敌人的时候，你将可以使用我的利刃回旋技能。你可以任凭敌人攻击你，这些攻击都将转嫁到他们自己身上。"
D.Strings[57192]="我为那位大人效力，他是该族最后的血脉。$b$b如果你对我有意见，就去向王子殿下诉说吧。"
D.Strings[57193]="我会时刻盯着你的，$c。但这并无恶意。$b$b如果你有任何消息，我会替你转达。如果没有，你最好不要停下。"
D.Strings[57194]="保持头脑的开放与清醒。善于发现并利用机会！"
D.Strings[57195]="唤醒者，我已经在你的武器上涂了特殊的混合物。你刀下的每具尸体都会感染一种诱变剂……好吧……你必须亲眼见证它的效果。"
D.Strings[57196]="这种追踪信息素会帮你发现有巨大价值的目标。"
D.Strings[57197]="胜利的关键是控制，唤醒者。你可以使用我的技能控制敌人的心智，将它变为盟友。"
D.Strings[57198]="我去找，你出钱。"
D.Strings[57199]="靠近以避开|cFFFF0000|Hspell:127404|h[黄金战矛]|h|r！"
D.Strings[57200]="|TInterface\\Icons\\ability_hunter_pet_devilsaur.blp:20|t奴监希提斯使用|cFFFF0000|Hspell:127414|h[原始呼唤]|h|r提升了其盟友的实力！"
D.Strings[57201]="在……在哪儿？卑劣无能，一无是处……真该死！"
D.Strings[57202]="这是个……陷阱……"
D.Strings[57203]="何苦还要挣扎？！"
D.Strings[57204]="哈哈，那么轻易就死了！"
D.Strings[57205]="呸！失败者活该受死，你们只不过是淘汰了弱者！"
D.Strings[57206]="|TInterface\\Icons\\spell_nature_lightningoverload.blp:20|t烛恒将军对他的敌人释放了|cFFFF0000|Hspell:127334|h[痛苦之潮]|h|r！"
D.Strings[57207]="别动，这一点儿都不疼！"
D.Strings[57208]="啊，喂狗的鲜肉送上门了！"
D.Strings[57209]="刺穿血肉。"
D.Strings[57210]="宝贝儿…把他们切成碎片！"
D.Strings[57211]="鲜血！在我身边流淌吧！"
D.Strings[57212]="笨狗！等我杀死这些废物之后再来教训你！"
D.Strings[57213]="狗崽子们有肉吃了。"
D.Strings[57214]="我要放狗了！"
D.Strings[57215]="我的狗！"
D.Strings[57216]="啊，援军来了！"
D.Strings[57217]="碾碎你们，就像碾碎虫子！"
D.Strings[57218]="我们也弄到了树脂！来尝尝吧！"
D.Strings[57219]="即使……联手……我们也败了……"
D.Strings[57220]="闪电绝无怜悯！"
D.Strings[57221]="谁也不许违抗影踪派！"
D.Strings[57222]="感谢你挽救了节日，$n！"
D.Strings[57223]="干得好，$n。多亏了你我们才能做到这一切。"
D.Strings[57224]="野牛人从四面八方包围过来了，$n！快，保卫村庄，别让他们烧了它！"
D.Strings[57225]="影踪派不需要外人的帮助！送走这些不速之客！"
D.Strings[57226]="|TInterface\\Icons\\ability_warstomp.blp:20|t %s开始施放|cFFFF0000|Hspell:127480|h[碾压重击]|h|r！快走开！"
D.Strings[57227]="%s捡起掉落的武器。"
D.Strings[57228]="来吧！我们不能让他们伤害游学者！"
D.Strings[57229]="影踪派有许多秘密。这其中的最高机密就是如何制造品质超凡的武器和护甲。"
D.Strings[57230]="哦……老天。这酒比我预想中更烈一些……"
D.Strings[57231]="哦……老天。这酒比我预想中更烈一些……我……"
D.Strings[57232]="只是需要打个盹……"
D.Strings[57233]="我只为卡拉克西瓦效力。"
D.Strings[57234]="我们由衷地感谢你！我会在这儿目送游学者安全地前往锦绣谷。"
D.Strings[57235]="你找回了一桶酒！我真是感激不尽……"
D.Strings[57236]="一桶珍贵的绿石佳酿！好哇！"
D.Strings[57237]="这可以给那些窃取我们道场珍贵产品的小偷们一个教训！"
D.Strings[57238]="啊，物归原主了。谢谢你！"
D.Strings[57239]="一位冒险家挽救了村庄，而一位英雄将美酒物归原主！"
D.Strings[57240]="我们的佳酿回来了！我们所有人都由衷地感谢你。"
D.Strings[57241]="如果你有胆量进入周围的森林，把被盗的酒桶找回来带给我，我就会为你调制一种具有神奇力量的浓缩生啤……"
D.Strings[57242]="好！这些差劲的新兵快让我无聊死了！"
D.Strings[57243]="水黾"
D.Strings[57244]="魁麟"
D.Strings[57245]="蜥蜴"
D.Strings[57246]="仙鹤"
D.Strings[57247]="山羊"
D.Strings[57248]="豪猪"
D.Strings[57249]="漂亮的帽子！我猜这就是你在找的东西？"
D.Strings[57250]="回头见，朋友！"
D.Strings[57251]="山谷的防御者们，你们必须在30分钟之内返回鎏金亭！"
D.Strings[57252]="魔古大军正涌向正门！所有防御者必须在15分钟之内返回鎏金亭！"
D.Strings[57253]="防御者们，你们将在5分钟后被召回鎏金亭！"
D.Strings[57254]="很好，你回来了。"
D.Strings[57255]="斥候回报，魔古将于30分钟后发起攻势！扫清西部山谷！"
D.Strings[57256]="防御者们，你们还有15分钟的时间来扫清西部山谷！魔古的突袭部队已经离营出发了！"
D.Strings[57257]="魔古族将在5分钟后入侵西部的山谷！防御者们，这是你们扫清山谷的最后机会！"
D.Strings[57258]="我会配合你的，$n！"
D.Strings[57259]="$n烹制了一顿酿造大餐！"
D.Strings[57260]="$n烹制了一顿烧烤大餐！"
D.Strings[57261]="$n烹制了一顿烘焙大餐！"
D.Strings[57262]="$n烹制了一顿炖煮大餐！"
D.Strings[57263]="$n烹制了一顿蒸烧大餐！"
D.Strings[57264]="$n烹制了一顿烹炒大餐！"
D.Strings[57265]="$n烹制了一顿酿造盛宴！"
D.Strings[57266]="$n烹制了一顿烧烤盛宴！"
D.Strings[57267]="$n烹制了一顿烘焙盛宴！"
D.Strings[57268]="$n烹制了一顿炖煮盛宴！"
D.Strings[57269]="$n烹制了一顿烹炒盛宴！"
D.Strings[57270]="$n烹制了一顿蒸烧盛宴！"
D.Strings[57271]="$n烹制了一顿熊猫人大餐！"
D.Strings[57272]="$n烹制了一顿熊猫人盛宴！"
D.Strings[57273]="我听说过你的“英雄事迹”，暴食蝗。据说你突袭了魔古族劳工营和农田，使长城的完工时间推迟了几十年。"
D.Strings[57274]="我无法否认你的战果，但是荣耀的虫群战士怎么能把自己的名声建立在追杀溃逃的农夫和雇农上呢？"
D.Strings[57275]="很简单：因为你在追杀他们时不用跳很远。"
D.Strings[57276]="觅血者，你的再生能力让我着迷。我不知道你是否愿意做一些测试。"
D.Strings[57277]="什么样的测试？"
D.Strings[57278]="只不过是一些简单的细胞穿刺感应，可能还要进行一些组织取样，再进行一次深入的超声波基因探查。不会造成严重损伤的！"
D.Strings[57279]="你说最后一步是什么？"
D.Strings[57280]="组织取样吗？"
D.Strings[57281]="后面那句。"
D.Strings[57282]="不会造成严重损伤的？"
D.Strings[57283]="我们没什么可以聊的了。"
D.Strings[57284]="再次起义是什么感觉，虫群卫士？你的女皇也曾被妄想控制，不是吗？"
D.Strings[57285]="大女皇赞柯哈兰以慈爱之名掩盖自己的真正目的。她声称是自己的独裁统治是为了保护我们。"
D.Strings[57286]="实际上，她只是恋栈权位而已。她渴望延长自己的统治，并为了实现这一目标而牺牲了我们永恒的轮回。我们别无选择，只能杀死她。"
D.Strings[57287]="所以在看到大女皇夏柯希尔在我们土地上的所作所为之后……我就已下定决心。"
D.Strings[57288]="你知道，我曾经为夏柯希尔效力过一段时间。那是在我被封印之前的事情了。她的疯狂和野心一样毫无理性可言。"
D.Strings[57289]="当她试图禁锢虫群时，用她的话说，是为了防止“无谓的牺牲”。"
D.Strings[57290]="她不相信任何人。妄想侵蚀了她的心智。无尽的恐惧驱使着她的行动。"
D.Strings[57291]="那种感觉如何？我并不后悔，如果这就是你想问的。能够为卡拉克西效力是我的荣幸。"
D.Strings[57292]="能够随侍在您身边是一种荣耀，至尊者。我曾深入研究过您的工作。"
D.Strings[57293]="多亏您在开发封印仓时留下的详细记录，我才得以在此处建造出保存科沃克的改进版封印仓。"
D.Strings[57294]="是的，他看起来确实……健康。"
D.Strings[57295]="我从来没有想到我的工作会有如此进展。这是凯帕圣树伟大力量的一次证明。如果没有它们，我们的文明永远都将无法复兴。请记住这一点。"
D.Strings[57296]="操纵者，你的这头野兽真是令人印象深刻。非常有趣。"
D.Strings[57297]="多年来一直出于休眠停滞的状态，现在又突然快速增长。"
D.Strings[57298]="问也别问。"
D.Strings[57299]="我只是随口说说……我敢打赌，他的基因将揭示一段引人入胜的故事……"
D.Strings[57300]="我也只是随口说说，切割者，看来你对声波操控不具有任何抵抗力。"
D.Strings[57301]="要是你突然对自己的腹腔“来了兴趣”会怎么样？我敢打赌，只要稍作诱导，你那双巧手就能在几秒钟内把自己剖开。"
D.Strings[57302]="说得好。"
D.Strings[57303]="哎呀……我得去杀掉点什么。我等得都要发疯了。"
D.Strings[57304]="你，安静。"
D.Strings[57305]="武僧，翻滚不会让你感到头晕吗？"
D.Strings[57306]="猢狲不一定是最好的酿酒师，但是盎迦猴岛的那些猢狲似乎偷到了最好的原料。"
D.Strings[57307]="欢迎来到天禅院。"
D.Strings[57308]="很高兴见到你，$n！我和我的学生来品尝酒仙布夫酿造的美酒，顺便庆祝酿月祭！"
D.Strings[57309]="作为织雾者，我们必须始终为需要帮助的人提供保护。"
D.Strings[57310]="织雾者年云也许有些严厉，但实际上是个心地善良的老师。"
D.Strings[57311]="姐妹们，村庄需要我们的援助。到前线上去，治疗伤员！"
D.Strings[57312]="他们打算处死游学者福云！你一定要帮我阻止他们……"
D.Strings[57313]="如果游学者被杀害，我们的牺牲就白费了……\n\n你愿意和我一起去阻止他们的处决吗？"
D.Strings[57314]="我们去救他吧。"
D.Strings[57315]="雪怒教给了我们力量的意义。"
D.Strings[57316]="看到大家精神如此饱满，真是太好了。"
D.Strings[57317]="这个节日让我意识到昆莱山是多么美丽。"
D.Strings[57318]="你好，$n。你喜欢这个节日吗？"
D.Strings[57319]="我们必须保护村民！我来把守前门，你们其他人分散开，别放任何野牛人过去！"
D.Strings[57320]="这些翔龙幼龙可以参加宠物战斗吗？"
D.Strings[57321]="我在我们的训练场地看到一个宠物斗士。云端翔龙无论做什么都一样表现出色，包括与其他宠物战斗！要获得雏龙的关键在于与一只成年翔龙建立良好的关系。只要你在骑士团中的声望达到崇拜，就可以在百木园的各个角落找到它们。"
D.Strings[57322]="两个巨型构造体出现在大型的壁龛中！"
D.Strings[57323]="为了烛恒将军的荣耀！"
D.Strings[57324]="以雷电之王的名义！"
D.Strings[57325]="你的脑袋归我了！"
D.Strings[57326]="你竟敢站在司书冯恩的弟子面前？！"
D.Strings[57327]="你将痛不欲生！"
D.Strings[57328]="我要砸碎你的脑袋！"
D.Strings[57329]="我要打断你身上的每根骨头！"
D.Strings[57330]="感谢你的帮助，朋友。我得去向女射手李琪薇汇报了。"
D.Strings[57331]="是！"
D.Strings[57332]="你认为我疯了，对吧？是……是的，也许有一点儿。$b$b如你所见，即便是在沉寂了八百七十七年之后，渴望呼吸的欲望仍然挥之不去。$b$b或许是我的包裹体出了什么问题，或许只是因为我有着……超乎常人的敏锐感知力。不管是什么原因，在被封存于琥珀中的悠长岁月里，我完全能感觉到时间的流逝。$b$b在挣扎了七十八年后，我放下了逃离的念头。我不断地自创和解答谜题，以免让自己变得头脑迟钝。身体就交给琥珀保养了。$b$b至于我的理智？不，我可不敢保证它还健全。"
D.Strings[57333]="入侵者！囚笼被攻击了……快派援兵！"
D.Strings[57334]="卡拉克西说，他们需要有人继续在后世惩罚那些蠢货。$B$B我告诉他们，“我是你们的螳螂妖。”"
D.Strings[57335]="寺院内有入侵者！"
D.Strings[57336]="警报！入侵者已经进入了寺院！"
D.Strings[57337]="寺院的围墙已经被攻破了！"
D.Strings[57338]="寺院遭到了入侵！警报！警报！"
D.Strings[57339]="大师！寺院中有入侵者！"
D.Strings[57340]="警报，大师！入侵者！"
D.Strings[57341]="寺院被入侵了，大师！警报！"
D.Strings[57342]="警报，大师！警报！"
D.Strings[57343]="为物资支付一些费用是必需的。"
D.Strings[57344]="盾牌上刻着：哨兵姚枯。它属于那个男孩的父亲。"
D.Strings[57345]="姚枯的被窝是空的。他不在这。"
D.Strings[57346]="这是哈查，哨兵姚枯的牦牛。"
D.Strings[57347]="你在寻找姚枯吗？我好几天没有看到他了。你说他会不会遇到麻烦了？"
D.Strings[57348]="感谢你的帮助，$g先生:女士;。我现在要继续寻找我的爸爸了。"
D.Strings[57349]="希望我能找到他。"
D.Strings[57350]="你……影踪派。你是来帮助我的？"
D.Strings[57351]="我的儿子……他在这儿？安然无恙！？"
D.Strings[57352]="是的。你的儿子莫苦，他一直在寻找你。"
D.Strings[57353]="他现在身处影踪卫戍营。这儿有只风筝。去看看他吧！"
D.Strings[57354]="返回粗麻小径！"
D.Strings[57355]="需要三名玩家才能净化生命之池！"
D.Strings[57356]="我把你的十字弓带来了，爸爸！"
D.Strings[57357]="现在，你可以用它来射杀螳螂妖了！"
D.Strings[57358]="这可能就是卡拉克西正在寻找的那块琥珀。"
D.Strings[57359]="我觉得我的战斗已经告一段落了，莫苦。"
D.Strings[57360]="来吧。我们该回家了。"
D.Strings[57361]="你可以留着这把十字弓，莫苦。"
D.Strings[57362]="哇……"
D.Strings[57363]="即使在梦中，我也能听到她的恐惧。"
D.Strings[57364]="恐惧控制了她的灵魂和躯体。女皇已经不再适合统治帝国。"
D.Strings[57365]="觉醒的时刻就要到来，但他们还没有来找我。卡拉克西还在等什么？"
D.Strings[57366]="有气息在逼近！有人能听见我说话！可……那不是卡拉克西。"
D.Strings[57367]="是的！把它打破！将我从琥珀的沉眠中释放出来！"
D.Strings[57368]="放弃邪能小鬼"
D.Strings[57369]="放弃空灵领主"
D.Strings[57370]="放弃破坏魔"
D.Strings[57371]="放弃眼魔"
D.Strings[57372]="放弃愤怒卫士"
D.Strings[57373]="灭亡吧！"
D.Strings[57374]="这让你生气吗？"
D.Strings[57375]="感受你的愤怒！"
D.Strings[57376]="让怒火吞噬你！"
D.Strings[57377]="让我痛饮你的愤怒！"
D.Strings[57378]="我的怒火无人能挡！！"
D.Strings[57379]="我会把你放在塔附近。不要掉以轻心。"
D.Strings[57380]="塔就在那边。我会在空中掩护你。动作快。"
D.Strings[57381]="从升降机井里传来一声刺耳的噪音！"
D.Strings[57382]="该给你们做个心脏小手术了！"
D.Strings[57383]="将我的……身体……献给科学……"
D.Strings[57384]="又一次成功的手术！"
D.Strings[57385]="我想该兰达尔·P·沃克登场了。"
D.Strings[57386]="嗯……无路可走。看来兰达尔·P·沃克得游泳了。"
D.Strings[57387]="那可真不错。现在兰达尔·P·沃克该休息了。"
D.Strings[57388]="|TInterface\\Icons\\item_earthenmight.blp:20|t %s开始施放|cFFFF0000|Hspell:128107|h[升腾大地]|h|r！小心！"
D.Strings[57389]="兰达尔·P·沃克看来该跳跃了。"
D.Strings[57390]="是，卡拉克西瓦。长久以来，我一直在苦等议会的命令！"
D.Strings[57391]="我明白。自从我开始长眠，已经发生了翻天覆地的变化。"
D.Strings[57392]="你休想破坏调谐！"
D.Strings[57393]="你的力量源自哪里？回答前好好想想。很多人都归因于他们手中的武器、身上的装备，或是奥术力量宝典。"
D.Strings[57394]="很久以前，我的族人还是魔古帝国的奴隶，他们被禁止携带武器。他们不是战士，既无魔法也无钢铁，没人相信他们能对抗魔古族。"
D.Strings[57395]="直到曙光之拳——康，拨开了我们的双眼。"
D.Strings[57396]="有一天，这位饱受爱戴的武僧向他的奴隶同伴们发起了挑战。“过来打我！”他命令道。"
D.Strings[57397]="奴隶们非常诧异，尝试着攻击康，结果无一例外地失败了。他如舞者般格挡着他们的拳脚，如风中芦苇般闪避着他们的攻击。"
D.Strings[57398]="“我们的脊背因鞭打而变得硬实，”他告诉他们，“我们的手臂因建造堡垒而变得强壮。我们的头脑因与敌共处而变得敏锐。你们以为魔古族更强大？我想说，我们才是他们的力量！”"
D.Strings[57399]="那些农夫、砖瓦工、牧羊人和铁匠纷纷跪拜说道，“康，教教我们如何战斗吧。”"
D.Strings[57400]="而当他们起身时……他们已成为战士。"
D.Strings[57401]="你的声音。你的双手。这些成就了真正的英雄。善加利用……你便能改变世界。"
D.Strings[57402]="跳起以阻止树脂硬化！"
D.Strings[57403]="没翅膀的可怜虫也敢踏足我的地盘。我马上就会听见你从平台上摔下去时发出的惨叫！"
D.Strings[57404]="赛特提克，列阵！让他们瞧瞧谁才是潘达利亚的御风者！"
D.Strings[57405]="女皇之息，带来强大的加拉隆吧！"
D.Strings[57406]="加拉隆，碾碎他们的骨头！"
D.Strings[57407]="不可能！瑟里提克、扎尔提克、库尔提克，到平台顶上来！我们必须守卫女皇！"
D.Strings[57408]="孩子，我想你是为龙龟而来的吧？很抱歉。你得先证明自己是我族人民的忠实盟友才行。"
D.Strings[57409]="孩子，我想你是为龙龟而来的吧？"
D.Strings[57410]="哪种龙龟是可以出售的？"
D.Strings[57411]="但愿他们能闯过来。这样才能让人们看清我的实力！"
D.Strings[57412]="哈哈！你们很快就会后悔选了这条路……"
D.Strings[57413]="不……我是……谁还能……？！"
D.Strings[57414]="我要把你的骨头雕成武器上的装饰品！"
D.Strings[57415]="你以为自己会有机会吗？！"
D.Strings[57416]="让我给你们展示一下琥珀炼金术吧……"
D.Strings[57417]="欢迎你，外来者。雪流大师正在学院里等着你呢。请对大师表示应有的尊重。"
D.Strings[57418]="看来女皇夏柯希尔已经把我们的帝国搞得乌烟瘴气。这个问题必须得到解决。但首先，我得恢复自己的力量。"
D.Strings[57419]="我没说过我能神速翱翔么？你移动得可真慢啊，唤醒者。"
D.Strings[57420]="附近的血色十字军兵力正蓄势待发，一旦指挥官遭到攻击，立刻出手相助。"
D.Strings[57421]="今天可真是个好日子。"
D.Strings[57422]="你喜欢步行么？我很喜欢。"
D.Strings[57423]="我已经不知道我们走了多久了。"
D.Strings[57424]="噢！你什么时候来的？"
D.Strings[57425]="没什么能比长长的慢速步行更能促进血液循环了。"
D.Strings[57426]="再你开口发问之前先回答你——没到，还远着呢。"
D.Strings[57427]="希望你跟我一样享受这个过程。"
D.Strings[57428]="有像你这么友好的$r$c同行，真是让人足下生风啊。"
D.Strings[57429]="我想我在这里待得够久了，你愿意随我一起走走吗？"
D.Strings[57430]="走走？好啊！"
D.Strings[57431]="欢迎光临我的小店，旅行者！"
D.Strings[57432]="啊！你要找神奇的物品？那你可来对地方了！"
D.Strings[57433]="请随意浏览，但不要乱碰！"
D.Strings[57434]="也许你会对魔法地图感兴趣？噢算了，都卖光了。"
D.Strings[57435]="愿风指引你的旅途！"
D.Strings[57436]="祝你好运，朋友！"
D.Strings[57437]="净化火焰！"
D.Strings[57438]="你怎么知道我会愿意卖给你啊，外来者？"
D.Strings[57439]="等等。卡拉克西在跟我说话。是的，议会，我听到了女皇的意图。必须终结她的统治。"
D.Strings[57440]="不必多说了，议会。我要用自己的双眼看看过去的家园。我要凝视夏柯希尔酿下的恶果！"
D.Strings[57441]="在我被封进琥珀之前，我孤注一掷地赌了一把。$B$B我意识到琥珀能创造出令我望尘莫及的奇迹，哪怕我在再实验室里精心研究一千年也赶不上。$B$B在我变成英杰前，我往自己体内注入了大量致命毒素。我想是琥珀维持生命的特性令我免于一死，剩下的都是时间的功劳。$B$B现在，我已经能无所畏惧地应对我想要的任何毒素。"
D.Strings[57442]="这个身体柔软的家伙应该也能效力。来吧，唤醒者。"
D.Strings[57443]="这个问题问得好。我们是一群奇怪的家伙……很少有熊猫人会选择住在长城的这一侧。$b$b长话短说吧，我们是酿酒的。但可不是什么酒都酿……是用伟大的凯帕圣树的树脂酿酒。"
D.Strings[57444]="……有点恶心，我知道。可事实并非如此。$b$b这些大树生成的琥珀具有神奇的治愈能力。但欲求不满的螳螂妖还进一步消耗它，用来制造武器和建筑……我甚至听到过这样的传说，螳螂妖会将它们的大英雄封存在琥珀里，以使其永存不朽。"
D.Strings[57445]="没错。树脂大师的起源可追溯到无数世代以前。我在广大渴求树脂的熊猫人中，只是一位无名小卒。$b$b但有时候，我担心自己也许是最后一代传人了。"
D.Strings[57446]="大树正在消亡。凯帕圣树·沃尔已经死了……沦为了邪煞的牺牲品。它再也不会生出琥珀。甚至连外形都不再像是一棵树。$b$b仅剩的几棵仍在生成琥珀的大树也面临着被螳螂妖过度开采的困境，或是处在邪煞的威胁之下。不论如何，一旦没有了树脂，也就不会再有树脂大师。到那时，我就只能重操旧业了。"
D.Strings[57447]="滚汤团啊。$b$b<吴暮叹息着。>"
D.Strings[57448]="用树脂酿的酒……那听起来……"
D.Strings[57449]="而你用它酿酒。"
D.Strings[57450]="你的旧业是什么？"
D.Strings[57451]="%s正在|cFFFF0000|Hspell:128419|h[疾跑]|h|r！"
D.Strings[57452]="继续！决不手软！"
D.Strings[57453]="%s被战斗的声音唤醒了！"
D.Strings[57454]="嗷呜嗷呜嗷呜嗷呜……"
D.Strings[57455]="真……甜！"
D.Strings[57456]="这么多种子！"
D.Strings[57457]="真……辣！！！"
D.Strings[57458]="请放入植物……"
D.Strings[57459]="放入一堆人参。"
D.Strings[57460]="放入一堆爽脆胡萝卜。"
D.Strings[57461]="放入一堆绿色卷心菜。"
D.Strings[57462]="放入一堆碧玉瓜。"
D.Strings[57463]="放入一堆魔古南瓜。"
D.Strings[57464]="放入一堆粉色芜菁。"
D.Strings[57465]="放入一堆红韭花。"
D.Strings[57466]="放入一堆葱。"
D.Strings[57467]="放入一堆菜瓜。"
D.Strings[57468]="放入一堆白色芜菁。"
D.Strings[57469]="放入一堆女巫浆果。"
D.Strings[57470]="维加特隆4000正在充能，请稍后再试。"
D.Strings[57471]="战斗让我……饥肠辘辘！"
D.Strings[57472]="生命之池的闯入者！别让他们跑了！"
D.Strings[57473]="嗝咕！"
D.Strings[57474]="等等，什么……？！"
D.Strings[57475]="螳螂妖从长城上打来了！"
D.Strings[57476]="%s瞅准机会，投出了巢毒炸弹！"
D.Strings[57477]="大力投掷来袭！别从山上摔下去！"
D.Strings[57478]="把共鸣水晶给我，你这只会啃树皮的小懦夫！"
D.Strings[57479]="我早该知道你不会一个人来的，科尔里克。"
D.Strings[57480]="|TInterface\\Icons\\ability_druid_ravage.blp:20|t加拉隆没能击中2名以上玩家，变得|cFFFF0000|Hspell:122754|h[狂怒]|h|r了！"
D.Strings[57481]="由我动手消灭卡拉克西的宠物再合适不过了！"
D.Strings[57482]="来吧外来者！有胆就来挑战我！"
D.Strings[57483]="开炮来杀死投弹兵！"
D.Strings[57484]="打扰别人是愚蠢的行为，外来者。"
D.Strings[57485]="他走了？这一切都结束了？"
D.Strings[57486]="巨像受伤了！继续攻击！"
D.Strings[57487]="它就快倒下了！继续出拳！"
D.Strings[57488]="并没结束……"
D.Strings[57489]="卡拉克西的仆从想要什么？"
D.Strings[57490]="带我去盐碱泥滩。"
D.Strings[57491]="你想向我致敬？那就用血来表达吧！"
D.Strings[57492]="我要去别的地方。"
D.Strings[57493]="带我去群星湖。"
D.Strings[57494]="[右键点击]你物品栏中徒弟的武器来装备它。\n打开背包的默认按键是[B]。"
D.Strings[57495]="我们在这里的工作暂时结束了。让我们将胜利的消息传达给卡拉克西议会吧。他们在等我们回去。"
D.Strings[57496]="你令我刮目相看，年轻的弟子。在你体内蕴藏着巨大的力量。"
D.Strings[57497]="发生什么事了？我们怎么这么快就要发动群袭？"
D.Strings[57498]="不，不……这群袭发动得过早了。我必须跟副官谈谈！"
D.Strings[57499]="我为什么……会在这儿……"
D.Strings[57500]="我们在哪儿？我们是在……群袭？！"
D.Strings[57501]="熊猫人早就有所准备。这攻击真是愚蠢。"
D.Strings[57502]="这是不对的。还没到发起群袭的时候。"
D.Strings[57503]="这道长城阻止不了螳螂妖的力量！"
D.Strings[57504]="我在此执行女皇的意志！我们要粉碎这道长城，吞噬另一侧的土地！"
D.Strings[57505]="你不会恰巧有另一捆那种熏香吧？"
D.Strings[57506]="我会尽量将船留在这里。$B$B多加小心！"
D.Strings[57507]="我们会尽力保护船只和船员。$B$B别为我们担心！"
D.Strings[57508]="这里发生了什么事？！$B$B普罗德摩尔女士的塔就这么……消失了！"
D.Strings[57509]="真是灾难！$B$B会是什么人干的？！"
D.Strings[57510]="不知还有没有人活下来……"
D.Strings[57511]="是部落干的吗？！$B$B圣光啊，救救我们……"
D.Strings[57512]="以圣光之名……塞拉摩！这里究竟发生了什么事？！"
D.Strings[57513]="埃比，到甲板下面藏好。其他人加强戒备，准备迎战。"
D.Strings[57514]="要是有人敢深入调查，我们会尽量将船停在这里。"
D.Strings[57515]="是——是，长官！"
D.Strings[57516]="船长！请让船员安全待在船上。一旦遭到攻击，我们会保护舰船！"
D.Strings[57517]="有艘船！联盟的船！"
D.Strings[57518]="我不管！甲板上的一个不留！动手吧，弟兄们！"
D.Strings[57519]="只是艘运输船，格鲁德。不是战舰。"
D.Strings[57520]="我一直想知道，在那些大门背后究竟有什么。"
D.Strings[57521]="看看这地方！真令人吃惊！"
D.Strings[57522]="我听说，是来自远方的英雄说服了虎神雪怒，让它打开了山谷的大门。没准哪天我能见见他们。"
D.Strings[57523]="影踪派告诉我们，这里是为昆莱难民挡风遮雨的避风港。也许我们终于能在这里寻获宁静。"
D.Strings[57524]="关于在大门背后有些什么，我听到过形形色色的传说。真没想到竟然是这样的。"
D.Strings[57525]="也许我们能在山谷里找到新家。"
D.Strings[57526]="他们来了，哈特斯！做好准备！"
D.Strings[57527]="这里真是潘达利亚古代皇帝的家园么？真是太美了。"
D.Strings[57528]="亲眼见证大门的开启……这一幕必定会在我的子孙万代间流传不绝。"
D.Strings[57529]="为了塞拉摩！"
D.Strings[57530]="在那家伙的背上仿佛有什么东西闪了一下。"
D.Strings[57531]="拿上那件物品。"
D.Strings[57532]="有许多伤害亟待补救。"
D.Strings[57533]="科尔里克只是第一个背叛我们的人。谁也不能相信。"
D.Strings[57534]="战争已经来临，唤醒者。"
D.Strings[57535]="那家伙的甲壳在闪光。"
D.Strings[57536]="贾鲁今天能为你做些什么？"
D.Strings[57537]="永远努力成就不可能的事。"
D.Strings[57538]="愿你在今后的日子里荣耀相伴，勇敢无畏，$r。"
D.Strings[57539]="我们只会对最可信赖的盟友透露金莲至深的秘密。"
D.Strings[57540]="你简直是……钢筋铁骨……"
D.Strings[57541]="欢迎到山谷来，朋友。一切随意，别惹麻烦。"
D.Strings[57542]="祝你好运，$r。你在这里能找到潘达利亚所有阵营的代表。当你经验再丰富些时，就回来与我们交谈吧。伟大的冒险和丰厚的奖励在等着你。"
D.Strings[57543]="愿幸运之星照耀着你，$c。你在这里能找到潘达利亚所有阵营的代表。与他们交谈，看看你是不是他们要找的勇敢冒险者。"
D.Strings[57544]="警报！联盟从港口靠近！"
D.Strings[57545]="动起来，狗崽子们！"
D.Strings[57546]="赶紧干活，苦工！"
D.Strings[57547]="麻利些，狗崽子们，不然就解雇你们！"
D.Strings[57548]="快点！快点！你们这群懒虫！"
D.Strings[57549]="欢迎你，旅行者。如果你愿意，就把这里当成自己的家吧。楼上有银行和城市传送门。出售各种商品的小贩都已经在这座建筑附近摆摊开店了。请随意选购。"
D.Strings[57550]="我能在镇上找到什么？"
D.Strings[57551]="欢迎你，$r。你在这里能找到潘达利亚所有阵营的代表。当你的经验再丰富一些时，就回来与我们交谈吧。前方有伟大的冒险和丰厚的奖励在等着你。"
D.Strings[57552]="欢迎你，$r。你在这里能找到潘达利亚所有阵营的代表。与他们交谈，看看你是不是他们所要寻找的勇敢冒险者。"
D.Strings[57553]="喔，嚯！喔嚯嚯。$B$B呦嚯嚯，扯平。$B$B我刚从潘达利亚回来，那里丘陵起伏，山势崎岖，还有味道最为诡异的朗姆酒。我的船在翡翠林中失事了，我的货物把当地变得无法居住，可与此同时，我能带你风驰电掣般地前往四风谷。$B$B你相信我吗，$c？"
D.Strings[57554]="很好。再接再厉。"
D.Strings[57555]="干得好。到此为止！"
D.Strings[57556]="把这里的活儿干完，人人都有朗姆酒喝！"
D.Strings[57557]="如此能量。真了不起！"
D.Strings[57558]="你是从那船上下来的？真不明智。塞拉摩现在是部落的地盘了！"
D.Strings[57559]="呀，将军派我到这儿来，把我们从翡翠林抢来的战利品卖给你。他认为这会对你的旅途有所帮助。$B$B如果你愿意的话，我还能带你返回大陆。"
D.Strings[57560]="四风谷"
D.Strings[57561]="在临死之前，畜生，记得我曾给过你机会。"
D.Strings[57562]="来自各地的商贩都进城了。你要找什么？"
D.Strings[57563]="你在城里没能找到需要的东西吗？$B$B你在找什么？也许我能帮你找到它。"
D.Strings[57564]="噢，你在找职业训练师？很可惜，他们并没能抵达锦绣谷。$B$B你可以回主城去找他们。"
D.Strings[57565]="在找专业训练师？$B$B在潘达利亚各地都能找到禅师级训练师。告诉我你要找哪位吧。$B$B如果你无法在潘达利亚找到要找的人，那就回主城找专业大师吧。他们应该也能帮你提高手艺。"
D.Strings[57566]="你可以在四风谷的丝纱工坊上找到蔡丝匠。我会在你的地图上标出他的位置。"
D.Strings[57567]="你可以去卡桑琅丛林的渔人码头找纳特·帕格，提升钓鱼技能。让我为你标出他的位置。"
D.Strings[57568]="制皮训练师就在昆莱山的土地精集市。我会在你的地图上标出位置。"
D.Strings[57569]="我听说在卡拉克西当中有炼金大师，就在距离长城很远的恐惧废土。我会为你在地图上标出位置。"
D.Strings[57570]="在四风谷的奈辛瓦里狩猎队营地里有位剥皮训练师。$B$B我会在你的地图上标出位置。"
D.Strings[57571]="如果你有附魔方面的需求，就得去翡翠林的晨芳园找莱·咒爪谈谈。$B$B我会在你的地图上标出位置。"
D.Strings[57572]="你可以在四风谷的奈辛瓦里狩猎队营地里找到你要找的人。$B$B我会在你的地图上标出位置。"
D.Strings[57573]="你一定是在找禅宗铁匠劳敖！他在锦绣谷的残阳关卫戍营里工作。$B$B我会在你的地图上标出他的位置。"
D.Strings[57574]="在锦绣谷魔古山宫殿上方的闻道之座有位考古学大师。$B$B我会在你的地图上标出位置。"
D.Strings[57575]="噢是的，你一定是在找治疗者楠。她就在七星殿里。$B$B我会在你的地图上标出她的位置。"
D.Strings[57576]="想提高自己的厨艺是吗？$B$B你应该跟铁掌家族的人谈谈。他们就在四风谷的半山市集。$B$B我会为你在地图上标出位置。"
D.Strings[57577]="如果你想对草药学有更深的了解，我建议你去找翡翠林中的训练师谈谈。$B$B我会为你在地图上标出位置。"
D.Strings[57578]="是的，我知道在锦绣谷的闻道之座有位铭文训练师。$B$B让我在你的地图上标出位置。"
D.Strings[57579]="你要找的人是塑玉者麦逸。她就在翡翠林的绿石村。$B$B我会在你的地图上标出她的位置。"
D.Strings[57580]="能给我们一些宠物吗，芬克斯维奇小姐？拜托了。"
D.Strings[57581]="不，不，小家伙们。你们还太小了！"
D.Strings[57582]="噢，天哪……"
D.Strings[57583]="穿云行者凌大师能教你如何在潘达利亚飞行。他正骑着云端翔龙停在主露台上。我会在你的地图上标出他的位置。"
D.Strings[57584]="哼。我可能比她还高呢。"
D.Strings[57585]="在谷中没有战场军官。$B$B你必须返回主城，才能加入战场或竞技场的战斗队列。"
D.Strings[57586]="你可以在自己的主城使用幻化和虚空仓库服务。"
D.Strings[57587]="飞行训练师"
D.Strings[57588]="战斗宠物训练师"
D.Strings[57589]="其它"
D.Strings[57590]="位于翡翠林的青龙寺已开放测试。该地下城适合85至87级的玩家。请组满队伍后再传送至地下城。该地下城的集合石尚未开放。\n\n穿过地下城内的常规出口，即可离开青龙寺并被传送出去。如果角色死亡并选择释放灵魂，请从该NPC处传送回去。"
D.Strings[57591]="我已组好队伍，准备好被传送到青龙寺了！"
D.Strings[57592]="送我回青龙寺！"
D.Strings[57593]="萨拉·芬克斯维奇命令小骗子跳跃！"
D.Strings[57594]="幻化与虚空仓库"
D.Strings[57595]="牧师白眉痛苦地呻吟着。"
D.Strings[57596]="炼金商品"
D.Strings[57597]="锻造补给品"
D.Strings[57598]="面包"
D.Strings[57599]="美酒"
D.Strings[57600]="烹饪补给品"
D.Strings[57601]="附魔补给品"
D.Strings[57602]="工程学补给品"
D.Strings[57603]="好了，好了，牧师。你现在谁也帮不了，自己的两条胳膊都断了！我给你敷点药。"
D.Strings[57604]="焰火"
D.Strings[57605]="急救补给品"
D.Strings[57606]="钓鱼补给品"
D.Strings[57607]="草药"
D.Strings[57608]="给我们来一扎冰镇啤酒！快点！"
D.Strings[57609]="铭文补给品"
D.Strings[57610]="珠宝加工供应商"
D.Strings[57611]="制皮与剥皮补给品"
D.Strings[57612]="肉类"
D.Strings[57613]="采矿补给品"
D.Strings[57614]="甜点"
D.Strings[57615]="裁缝补给品"
D.Strings[57616]="想买杂货？伯妮那儿应该有你要找的东西。她就在金色神灯卖杂货。我会在你的地图上标出位置。"
D.Strings[57617]="我看到有个小贩在金色神灯摆摊卖货。我会在你的地图上标出位置。"
D.Strings[57618]="我想你会说……"
D.Strings[57619]="我想你会说，她在烤箱里藏了个小宝宝。"
D.Strings[57620]="你妻子怎么还在用烤箱？我还等着烤肉呢！"
D.Strings[57621]="米歇尔·扫榻咆哮起来。"
D.Strings[57622]="你们两个都给我闭嘴！"
D.Strings[57623]="打得不错，弟子。你已用行动证明，自己真正领会了我的……朱鹤之道."
D.Strings[57624]="希望之花会在各处盛开……哪怕是在被遗忘丛林的阴暗角落也不例外。"
D.Strings[57625]="所需要的就是一位像你这样的英雄，来播下种子。"
D.Strings[57626]="停止这噩梦！"
D.Strings[57627]="啊，你在找什么军需官？也许我能帮你找到他们。"
D.Strings[57628]="垂钓翁军需官？看来你要找的人是纳特·帕格。他就在卡桑琅丛林的渔人码头。$B$B让我为你在地图上标出位置。"
D.Strings[57629]="你应该跟邓·雷酒谈谈！他就在四风谷的风暴烈酒酿造厂。$B$B让我为你在地图上标出位置。"
D.Strings[57630]="如果你要找阡陌客军需官，那就去跟吉娜·泥爪谈谈。她就在半山市集经商。$B$B让我为你在地图上标出位置。"
D.Strings[57631]="嗯，恐怕我对卡拉克西一无所知，但我听人私下里提到过他们的城市——卡拉克西维斯，就在位于遥远西方的恐惧废土。也许你能在那里找到卡拉克西军需官。$B$B我会在你的地图上标出位置。"
D.Strings[57632]="影踪派军需官就在螳螂高原的影踪卫戍营。$B$B我会在你的地图上标出位置。"
D.Strings[57633]="啊，你要找宽仁的贾鲁！他就在我身旁。"
D.Strings[57634]="至尊天神军需官就在山谷里。白心贤者与其他阵营的代表都在夏之台的下层。$B$B我会在你的地图上标出他的位置。"
D.Strings[57635]="至尊天神军需官就在山谷里。莲蕊贤者与其他阵营的代表都在夏之台的下层。$B$B我会在你的地图上标出她的位置。"
D.Strings[57636]="你要找谭欣眺。她就在锦绣谷魔古山宫殿上方的闻道之座。$B$B我会在你的地图上标出她的位置。"
D.Strings[57637]="勇气军需官——指挥官牛心，就在螳螂高原的砮皂寺。$B$B我会在你的地图上标出她的位置。"
D.Strings[57638]="你可以找指挥官罗平兑换公正印记，他就在螳螂高原的砮皂寺。$B$B我会在你的地图上标出他的位置。"
D.Strings[57639]="你可以在西边那道名为蟠龙脊的雄伟长城上找到荣誉军需官。$B$B我会为你在地图上标出位置。"
D.Strings[57640]="军需官"
D.Strings[57641]="征服军需官"
D.Strings[57642]="勇气军需官"
D.Strings[57643]="荣誉军需官"
D.Strings[57644]="垂钓翁"
D.Strings[57645]="酒仙"
D.Strings[57646]="阡陌客"
D.Strings[57647]="云端翔龙骑士团"
D.Strings[57648]="卡拉克西"
D.Strings[57649]="影踪派"
D.Strings[57650]="金莲教"
D.Strings[57651]="解散。返回影踪卫戍营。"
D.Strings[57652]="至尊天神"
D.Strings[57653]="游学者"
D.Strings[57654]="你可以返回影踪卫戍营选择一位新的影踪派同伴。\n\n你确定要解散你的影踪派同伴吗？"
D.Strings[57655]="你可以在西边的蟠龙脊上找到征服军需官和卓越征服军需官。$B$B我会在你的地图上标出他们的位置。"
D.Strings[57656]="我在哪里能找到垂钓翁军需官？"
D.Strings[57657]="我在哪里能找到酒仙军需官？"
D.Strings[57658]="我在哪里能找到金莲教军需官？"
D.Strings[57659]="我在哪里能找到卡拉克西军需官？"
D.Strings[57660]="我在哪里能找到游学者军需官？"
D.Strings[57661]="我在哪里能找到云端翔龙骑士团军需官？"
D.Strings[57662]="我在哪里能找到影踪派军需官？"
D.Strings[57663]="我在哪里能找到阡陌客军需官？"
D.Strings[57664]="凝视避无可避的厄运吧！"
D.Strings[57665]="直面死亡吧！"
D.Strings[57666]="终于……安静了。"
D.Strings[57667]="普利波先生在教我如何做一位标本剥制师。我个人觉得他的思想过于陈旧了，应该从侏儒工程学中找点儿灵感。"
D.Strings[57668]="噢，小伙子！你让那个雷霆坦克XT-9000开始工作了吗？"
D.Strings[57669]="不，先生。我不这么认为。"
D.Strings[57670]="朋友，你最近去过卡桑琅吗？$B$B真该去一探究竟。那里水产丰富，绝对能让你满网而归。$B$B我父亲说过，早起的渔夫有鱼吃！"
D.Strings[57671]="位于卡桑琅丛林东南部的渔人码头是潘达利亚这一带所有的钓鱼发烧友都倾心向往的好地方。$B$B如果你愿意忙里偷闲，在海边享受一日静谧的好时光，就来找我们吧。"
D.Strings[57672]="你想要……奖励？$B$B成功捕到一条大鱼的快乐还不算是奖励？那么身临大海的兴奋呢？还有仅凭一根钓竿就能获得的归属感？$B$B你还有很多东西要学，$r。$B$B抛开我的个人见解不谈，光是垂钓的学问就能让你钻研好久了。$B$B你可以提高自己的钓鱼技能。今后，你能买到强大的钓竿。$B$B倍受尊重的渔夫还能获得特殊的鱼类宠物、水黾坐骑，甚至还有捕鱼木筏。"
D.Strings[57673]="谢谢。多亏你了。"
D.Strings[57674]="我在被囚禁时偷听到了不少消息。任塞一定会对我所带来的情报感到很高兴的。"
D.Strings[57675]="希望我们很快就能再次相见，我的新朋友。"
D.Strings[57676]="地穴里闯进了入侵者！别让他们活着出去！"
D.Strings[57677]="你很快就会跟那些被遗忘的尸体一样被埋在这里了，小$c！"
D.Strings[57678]="影踪派的不懈戍守，是这片土地至今仍未被螳螂妖大军席卷的唯一理由。我们不求感谢，可我们眼下再也无力独自完成这项任务了。"
D.Strings[57679]="$n踩中了闪电陷阱！"
D.Strings[57680]="在船被烈焰吞噬前，赶快逃离！"
D.Strings[57681]="多加小心，$r。这片土地的怒火尚未平息。你的到来令它感到前所未有的不安。"
D.Strings[57682]="我们为什么要继续在一场毫无裨益的战斗中继续苦战？千万条生命临死前的叫喊，竟没让你夜夜噩梦缠身？"
D.Strings[57683]="战争结束后又会怎么样？在亲眼见证了这些恐怖的场面之后，你还想继续拥有风平浪静的人生么？"
D.Strings[57684]="我们公开与虚灵达成了交易，却对它们的真实意图一无所知。我们是不是在给自己准备葬礼？"
D.Strings[57685]="北方仍有亡灵肆虐。我们的家乡满目疮痍。潘达利亚四处散发着我们的仇恨与怀疑。当燃烧军团再次踏上我们的海岸时，这个世界还有什么希望？"
D.Strings[57686]="我们的内心何时变得跟我们竭力压制的巨大邪恶一样充满黑暗？"
D.Strings[57687]="我能闻到你心中仇恨、暴力和怀疑的气味。你的灵魂承受着毕生苦难的重量。为什么你还要在一条通往毁灭的道路上继续走下去？"
D.Strings[57688]="快来坐下吃点东西吧！任何时候都该畅享美餐！"
D.Strings[57689]="一份热腾腾的饭菜，一杯透心凉的啤酒，绝对能让战斗的伤口复原得更快些，对吧？"
D.Strings[57690]="要是你能把这矮子从我的新椅子上赶走，我就免费请你吃一顿！"
D.Strings[57691]="李，再给我一支龙枪。"
D.Strings[57692]="你认为这些是长在树上的？"
D.Strings[57693]="你这有没有什么冒气泡的能量饮料？"
D.Strings[57694]="萨娅·茗流在洗手。"
D.Strings[57695]="萨娅·茗流叹了口气。"
D.Strings[57696]="你们哪位还要再来一杯么？"
D.Strings[57697]="这么多伤患……"
D.Strings[57698]="呦，该休息了！"
D.Strings[57699]="请对我进行急救训练。"
D.Strings[57700]="瞧瞧这令人惊讶的泥土！简直太有泥土的样子了！"
D.Strings[57701]="你干嘛不来跟我跳舞啊，小可爱？"
D.Strings[57702]="不知我的鞋子对于探险来说是不是太过花哨了？"
D.Strings[57703]="这些树真是太神奇了！"
D.Strings[57704]="呀！我要走了！回旋式多彩隐形装置启动！"
D.Strings[57705]="我从没见过这样的根！"
D.Strings[57706]="这些岩石栩栩如生！"
D.Strings[57707]="我这么可爱，是不是不该待在丛林里？"
D.Strings[57708]="我得带些花回家！"
D.Strings[57709]="当个传奇探险家可真不容易！"
D.Strings[57710]="你好，$n。只有精通工程学的人才能使用我的拍卖服务。很遗憾，你不在此列。只好请你离开了。"
D.Strings[57711]="鹰隼翱翔时的优美身姿甚是养眼，但其利爪的威力也不可小觑。"
D.Strings[57712]="即便没有武器在手，也无需害怕。单凭你的身体就足以对抗任何敌人。"
D.Strings[57713]="在战斗中，你的护甲就是你的皮肤。保护它，善待它，它就会以同样的方式回报你。"
D.Strings[57714]="心中熊熊燃烧的激情火焰，也会让他人感同身受。"
D.Strings[57715]="有时，弱不禁风的黄蜂会比力大无穷的公牛更有威力。"
D.Strings[57716]="你能相信他们竟然不放我进去么？在所有人当中偏偏是我？"
D.Strings[57717]="你看不见我正在参加瞪眼大赛吗？"
D.Strings[57718]="我才不会落入你的圈套，$r。胜利属于我！"
D.Strings[57719]="老陈的疗伤珠在对他进行治疗后消失不见了！"
D.Strings[57720]="这个蠢货不明白。他毫无顾忌地放任自己的负面情绪。如果任其发展，我们所有人都会尝到苦果。"
D.Strings[57721]="这个老熊猫人愚蠢至极。我们怎能不带着情绪战斗？那不可能！"
D.Strings[57722]="他比我们更加了解这片土地。也许你该留意他的告诫。"
D.Strings[57723]="你知道什么？别搞得自己像是艾泽拉斯的救世主一样！"
D.Strings[57724]="船着火了！"
D.Strings[57725]="嘿，宝贝儿，我想要提款。"
D.Strings[57726]="船怎么了？！"
D.Strings[57727]="真是太谢谢你了。"
D.Strings[57728]="我们的船……不！大家都逃出来了吗？来这集合！"
D.Strings[57729]="什么？！我的船！是谁干的？！"
D.Strings[57730]="来吧，朋友们！我们都来美美地喝一杯。"
D.Strings[57731]="沙背穆山幼兽大声求救！"
D.Strings[57732]="下次见，我的朋友们。"
D.Strings[57733]="呃……呃……"
D.Strings[57734]="嘘，锦鱼人。在这儿钓鱼已经够困难了！"
D.Strings[57735]="我下次一定要带上迪娜，她会爱死这些植物的！"
D.Strings[57736]="我现在真想听古大叔讲笑话，这地方太吓人了！"
D.Strings[57737]="将来，我也要成为探险家！"
D.Strings[57738]="我已经有段时间没见过提兹了，希望她一切安好！"
D.Strings[57739]="嘿！别把鞋踩在桌子上！还有脚！"
D.Strings[57740]="要是有一天能离开山谷也是不错的，可这里真是太漂亮了！"
D.Strings[57741]="你要不要吃点什么？"
D.Strings[57742]="要是你能进入我们的睡室，那就自便吧。"
D.Strings[57743]="看在你还有用的份上，你可以留下，外来者。"
D.Strings[57744]="真没想到卡拉克西瓦竟允许你活着，反正也轮不到我管。"
D.Strings[57745]="只要你对我们还有用处，我就会为你安排膳宿。"
D.Strings[57746]="你！离我们的庄稼远点儿！"
D.Strings[57747]="吃我一耙！"
D.Strings[57748]="我们种得更好！你这讨厌鬼！"
D.Strings[57749]="我们可不好惹！"
D.Strings[57750]="“闪光之刃就是这么来到了潘达利亚，而后又离开，从此下落不明。”$B$B在我们的人民间充满了精彩丰富的传说故事。我要做的就是将它们收集起来，使其能千秋万代地流传下去。"
D.Strings[57751]="在这里贮存着关于这个古老世界浩如烟海的广博知识，而我们才刚刚开始知晓而已！"
D.Strings[57752]="你休想活着离开塞拉摩！"
D.Strings[57753]="祝你好运连连，$r。$B$B如果你在找好运符，我马上就能让你如愿以偿。"
D.Strings[57754]="有猫相伴，谁还需要朋友？"
D.Strings[57755]="感谢大海，陌生人！我能自己返回香里拉村了。"
D.Strings[57756]="我当时正在岸边钓鱼，突然就遭到了蜘蛛的袭击！多谢你救了我。"
D.Strings[57757]="是云端翔龙骑士团派你来的吗？祝福他们。请帮帮其他人吧！"
D.Strings[57758]="其他受害者……他们的声音惨不忍闻。多谢你救了我！"
D.Strings[57759]="我以为自己死定了。谢谢你，也谢谢骑士团。我能自己离开这里了。"
D.Strings[57760]="我曾经有个农场，但那是在很久之前了。我想要痛快地大战一场，你呢？"
D.Strings[57761]="我原本只逮到了两只兔子。可现在却有这么多！"
D.Strings[57762]="带我去奥格瑞玛。"
D.Strings[57763]="我没想到还会有人来帮忙。你给我了新的希望，陌生人。"
D.Strings[57764]="当我被困在网中时，我心中充满了怀疑与绝望。是你把我从自己的恐惧中解救了出来。"
D.Strings[57765]="我开始害怕，担心自己不会得救了。自己被所有人遗忘了。感谢骑士团派你来救我！"
D.Strings[57766]="你怕蜘蛛吗？据某些在这片无尽森林中往来的旅者说，他们老觉得身上有蜘蛛在爬。"
D.Strings[57767]="你看见朗姆酒了吗？……嗝儿！我到处都找遍了！"
D.Strings[57768]="部落要为自己在这里犯下的恶行付出代价。$B$B等我从这……怪物身上拿到聚焦之虹……加尔鲁什就会明白毁灭的真正含义。$B$B奥格瑞玛……必将覆灭。"
D.Strings[57769]="在你工作的同时，我们会把部落从废墟里赶出去。"
D.Strings[57770]="请接受我最诚挚的谢意。聚焦之虹已被移除，这个失去能量的炸弹现在只是加尔鲁什暴行的邪恶佐证。变幻之风猛烈刮过，艾泽拉斯处在战争的边缘。抱歉，请你们原谅我……我总是有许多顾虑。再见。"
D.Strings[57771]="你瞧，历史学家的工作是永远也干不完的。那些需要我们铭记的重要事件总是层出不穷。$B$B我已经开始收集你们的人来到这片土地的相关史料。你叫什么来着？我得把它记下来，好让我们的子孙后代能读到你的故事，了解你的传说。"
D.Strings[57772]="我的名字是……"
D.Strings[57773]="哦，原来就是你啊。我听说过你的事迹，$N。我一定会把你的故事写下来，让你名留青史，我说到做到。"
D.Strings[57774]="简宁！这就是$n。你最近也听过$g他的:她的;事迹了吧？$G他:她;为我们的人民做了许多事。"
D.Strings[57775]="很抱歉，建言者。我没能认出$G他:她;来！"
D.Strings[57776]="我现在就开始动笔写你的冒险故事！"
D.Strings[57777]="进入彻底毁灭程序。再见。"
D.Strings[57778]="俗话说得好，树大易招风，菇小可避雨。"
D.Strings[57779]="尺有所长，寸有所短。量才器使，知人善用。"
D.Strings[57780]="早起的鸟儿有虫吃，但耐心的熊猫人才有美酒喝。"
D.Strings[57781]="暴力虽能逞一时之快，但所造恶业永难消除。"
D.Strings[57782]="以德报怨，以爱消恨。"
D.Strings[57783]="与我分享你的智慧吧，建言者。"
D.Strings[57784]="清理中"
D.Strings[57785]="很多人都不知道我曾经当过角斗士，专门取悦部落那些野兽们。所以我也多少懂一点武术。"
D.Strings[57786]="不！！我的宝贝鞋子！"
D.Strings[57787]="滚开，偷鞋贼！"
D.Strings[57788]="你在干什么！？别碰它们！"
D.Strings[57789]="不！！那是我最喜欢的一双鞋！"
D.Strings[57790]="不！我的宝贝收藏！"
D.Strings[57791]="我只不过……想再要……一双……"
D.Strings[57792]="鞋是永远不嫌……多的……"
D.Strings[57793]="我今天不能加入你们了，朋友们。宴会在即，我得把鱼准备好！"
D.Strings[57794]="莫格莱尼……"
D.Strings[57795]="为了答谢你们为保护锦绣谷所做的贡献，金莲教将举办一场盛大的宴会。请你务必要来参加。"
D.Strings[57796]="欢迎你，$r。$B$B我还只是一棵小树苗，我将在潘达利亚扎根，与这片土地融为一体。这样，泰兰德才能从它蕴藏的故事中受益。为了达成她的心愿，强弓家族自愿留下来保护我渡过幼年期。"
D.Strings[57797]="别担心，雏龙在这里会很安全的。"
D.Strings[57798]="这些年来，我见过不少弟子，但你似乎有些与众不同。"
D.Strings[57799]="一个新弟子？啊，不错，很好。你和安离长老谈过了吗？"
D.Strings[57800]="对你的翔龙表现出你的善意和尊重，它就会慢慢信赖你。"
D.Strings[57801]="不积跬步，无以至千里。"
D.Strings[57802]="我会密切注意所有的弟子。我非常渴望看到你的进步。"
D.Strings[57803]="野生云端翔龙的生育率非常低。所以，每一枚翔龙蛋都是极其珍贵的。$B$B如果我们不努力保护野生云端翔龙，它们或许就会彻底绝种。"
D.Strings[57804]="在所有的野生翔龙中，玛瑙翔龙是最稀有的。据悉，这些难得一见的黑色云端翔龙会在东北边的临风岛上产卵。$B$B如果你在那里发现任何玛瑙翔龙蛋，请把它们带来给我。我会好好奖赏你的。"
D.Strings[57805]="你能抵御我的刀法？"
D.Strings[57806]="你马上就用不上这个身躯了！"
D.Strings[57807]="你竟敢反抗山泽部族？！"
D.Strings[57808]="又一个不安的灵魂……"
D.Strings[57809]="我会让你摆脱那副可怜的皮囊，把你重塑成我们的仆人！"
D.Strings[57810]="躯体或将腐朽……但灵魂……不灭……"
D.Strings[57811]="你休想阻止我们！我们的大军将带来狂风骤雨！"
D.Strings[57812]="真是无礼！"
D.Strings[57813]="把你的灵魂交付给岩石之躯吧！"
D.Strings[57814]="山泽……会抓住你的……"
D.Strings[57815]="送上门的灵魂……"
D.Strings[57816]="我的魂瓮正等着你呢！"
D.Strings[57817]="你会和其他人一样，永世为奴！"
D.Strings[57818]="蠢货！你死定了！"
D.Strings[57819]="我要把你的灵魂抽出来！"
D.Strings[57820]="别动，很快就过去了……"
D.Strings[57821]="死亡只是你受罚的开始！"
D.Strings[57822]="不错的灵魂——归我了。"
D.Strings[57823]="一只狂怒的果园钉刺者出现了！"
D.Strings[57824]="小心！要是让他们看见你，他们就会发出警报的。$B$B是金莲教派你来救我的吗？除了我，别人都被杀死或抓走了……"
D.Strings[57825]="探险队出什么事了？"
D.Strings[57826]="你能带我们去找那些俘虏吗？"
D.Strings[57827]="我们当时正在调查寺庙，一个魔古军阀突然带着大批随从闯了进来。$B$B好多人当场毙命，剩下的都被抓走了。$B$B他们以为我死了，我一直躲在这里才逃过一劫。$B$B我不知道那些魔古族来这里干什么，但肯定不是好事！"
D.Strings[57828]="他们被带到东南边的瀑布那里去了。我带你们去。"
D.Strings[57829]="我们一定得小心。寺庙的地界上有魔古族和他们的蜥蜴人奴隶巡逻，而路边的草丛里则潜伏着他们驯养的畜生。"
D.Strings[57830]="中庭的守卫十分森严。我们得绕过去。"
D.Strings[57831]="杀死古代灵魂来为裴智之杖充能！"
D.Strings[57832]="你知道自己在做什么吗？！算了——我也不需要那根法杖了。"
D.Strings[57833]="你喜欢我的蛇吗？我感觉它们不喜欢你！"
D.Strings[57834]="<你的雏龙好奇地看着你。>"
D.Strings[57835]="<你的雏龙对你微笑。>"
D.Strings[57836]="<你的雏龙对你啾啾鸣叫。>"
D.Strings[57837]="<你的雏龙看着你。>"
D.Strings[57838]="<你的雏龙百无聊赖地看着你。>"
D.Strings[57839]="<你的雏龙四处嬉戏飞翔。>"
D.Strings[57840]="<你的雏龙在你的手臂上蹭着鳞片。>"
D.Strings[57841]="<你的雏龙舔了舔你。>"
D.Strings[57842]="<雏龙好奇地看着你。>"
D.Strings[57843]="<雏龙对你啾啾鸣叫。>"
D.Strings[57844]="<雏龙看着你。>"
D.Strings[57845]="<雏龙百无聊赖地看着你。>"
D.Strings[57846]="<雏龙四处嬉戏飞翔。>"
D.Strings[57847]="<雏龙在你的手臂上蹭着鳞片。>"
D.Strings[57848]="<雏龙舔了舔你。>"
D.Strings[57849]="<雏龙失望地瞪着你。它看见你在和其他雏龙玩耍。>$B$B<你一次只能和一条雏龙玩耍。在跟这条雏龙玩接球之前，先去和安离长老谈谈，把你目前的这条雏龙归还给他吧。>"
D.Strings[57850]="人们将铭记你的英勇事迹。"
D.Strings[57851]="你的翔龙飞回家了！"
D.Strings[57852]="|TInterface\\Icons\\spell_shadow_sacrificialshield.blp:20|t%s开始施放|cFFFF0000|Hspell:117697|h[黑暗之盾]|h|r！"
D.Strings[57853]="每一次受伤，都是学习的过程。每一次失败，都是成长的机会。"
D.Strings[57854]="找寻内心的平静，这能帮助你理性地看待前路上的阻碍。"
D.Strings[57855]="智慧只会垂青真正开放的心灵。"
D.Strings[57856]="那是我的！我先偷到的！"
D.Strings[57857]="痛……好痛啊……"
D.Strings[57858]="想想他们的所作所为，不要对他们手软。"
D.Strings[57859]="噩梦！真是可怕的噩梦！"
D.Strings[57860]="痛死啦……"
D.Strings[57861]="好痛苦……"
D.Strings[57862]="救救其他人！求你了！"
D.Strings[57863]="我欠你一条命！"
D.Strings[57864]="拍卖行位于二楼，就在建筑物进门的右手边。$B$B我会在你的地图上标出位置。"
D.Strings[57865]="银行位于二楼，就在建筑物进门的左手边。$B$B我会在你的地图上标出位置。"
D.Strings[57866]="舞空者书恩可以教你如何在潘达利亚飞行。他就在主露台上，骑着他的云端翔龙。我会在你的地图上标出位置。"
D.Strings[57867]="有个名叫文雅的萨恩的战斗训练师在主露台上训练她的宠物。$B$B我会在你的地图上标出位置。"
D.Strings[57868]="你可以在主楼外的主露台上找到兽栏管理员追踪者老朗。他就站在战斗宠物训练师的旁边。$B$B我会在你的地图上标出位置。"
D.Strings[57869]="征服者陵墓就在你的正下方。沿着这条土路就能找到入口。动作快！"
D.Strings[57870]="在找啤酒吗？烈酒窖有最香醇的美酒！我会在你的地图上标出位置。"
D.Strings[57871]="我们得拿到那些箭矢，然后离开这儿。"
D.Strings[57872]="新兵，能再给我一个箭袋吗？"
D.Strings[57873]="啊，看来你想当厨师对吧？你可以在大麦花那里找到你所需要的一切。她就在烈酒窖里卖货。$B$B我会在你的地图上标出位置。"
D.Strings[57874]="德兰达·安克辛携带着附魔物资。在师匠大厅内可以找到她，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。"
D.Strings[57875]="我依稀记得在师匠大厅内有一名工程师，就位于你进入主建筑物时的左侧。$B$B我会在你的地图上标记这个位置。"
D.Strings[57876]="考虑过燃放一两个烟花吗？我应该自己去买些烟花！在师匠大厅内可以找到商贩。$B$B我会在你的地图上标记这个位置。"
D.Strings[57877]="别担心，急救人员离这不远。治疗者就在师匠大厅里。$B$B我会在你的地图上标记这个位置。"
D.Strings[57878]="那些……野牛人！\n\n他们攻击了我的农场，还有附近的东风之眠……他们杀了许多人，还把剩下的村民都赶走了！\n\n我设法在这里聚集了一些乡亲。有滨岸村的人来帮忙么？"
D.Strings[57879]="我来自部落。我们是来救你们，并帮你们重建村庄的。"
D.Strings[57880]="班，能再多给我一些炸药吗？"
D.Strings[57881]="是的，在静思之厅内有渔具供应商。动作要轻，以免吓跑大鱼！$B$B我会在你的地图上标记这个位置。"
D.Strings[57882]="你在寻找食物和饮料吗？如果是的话，夏之眠的米凡那儿有你要寻找的东西。$B$B我会在你的地图上标记这个位置。"
D.Strings[57883]="你知道，自打你来了之后，情况确实好了许多！\n\n可我还是很担心农场上的朋友们……"
D.Strings[57884]="想买杂货？胼趾马利那儿应该有你要找的东西。他就在夏之眠。我会在你的地图上标出位置。"
D.Strings[57885]="是的，城市里有草药供应商。在师匠大厅内可以找到哈夫纳·地行者，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。"
D.Strings[57886]="啊，来了一位绘卷大师！我想你在寻找墨水和羊皮纸，对吗？在师匠大厅里可以找到这些，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。"
D.Strings[57887]="珠宝加工？这的确是件精细活儿。你可以从师匠大厅的瓦纳里斯·白歌那购买物资。$B$B我会在你的地图上标记这个位置。"
D.Strings[57888]="皮革加工和皮草？你一定是在寻找皮匠。如果我没记错的话，在师匠大厅里有一位。$B$B我会在你的地图上标记这个位置。"
D.Strings[57889]="在可以在师匠大厅里找拉兹·煤钳购买采矿用品。$B$B我会在你的地图上标记这个位置。"
D.Strings[57890]="辛娜·织日在师匠大厅里兜售试剂，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。"
D.Strings[57891]="尽管前景黯淡，可我决不会放弃希望。我们不能向野牛人的暴力低头。\n\n你……是来帮我们的？"
D.Strings[57892]="我必须承认，在那最黑暗的时刻，我不敢相信我们还能活下来。多亏你和你的族人，幸好事情没往我预想的方向发展。"
D.Strings[57893]="织花女士伊莎那一流的制衣手艺人尽皆知。$B$B她在师匠大厅内工作，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。"
D.Strings[57894]="我知道有个小贩在夏之眠摆摊卖货。我会在你的地图上标出位置。"
D.Strings[57895]="你需要与巴空谈谈。他供应充足的肉类，听说新鲜得很。$B$B我会在你的地图上标记这个位置。祝你好运！"
D.Strings[57896]="嘴馋想要吃些甜品吗？你需要找到米色糖。$B$B他通常在底层徘徊，尽管他时不时地会跑进烈酒窖里慰劳自己。"
D.Strings[57897]="那些……野牛人！\n\n它们袭击了我的农场，还有附近的西风之息……杀死了不少人，然后把剩下的全都赶走了！\n\n我在这里集结了一些乡亲。滨岸村会来帮忙吗？"
D.Strings[57898]="我来自联盟。我们是来救你们的，帮忙重建村庄。"
D.Strings[57899]="真是美好的一天啊，不是吗？"
D.Strings[57900]="凡事向前看，不要回头。"
D.Strings[57901]="你见过玛瑙翔龙吗？它们会在临风岛上产卵。要是你能把龙蛋带给安离长老，一定能得到应有的回报。"
D.Strings[57902]="你参加飞行竞技赛了吗？祝你好运。"
D.Strings[57903]="噢是的，你一定是在找艾拉西尼尔。她就在双月殿里。$B$B我会在你的地图上标出她的位置。"
D.Strings[57904]="事情总没有看上去那么糟。"
D.Strings[57905]="你的云端翔龙来了，$n。等你准备好就骑到它背上，我们开始。"
D.Strings[57906]="我想我对朔弥的看法是错的……"
D.Strings[57907]="长者们说得对——人确实不可貌相。"
D.Strings[57908]="你觉得朔弥能向我展示她的战技吗？"
D.Strings[57909]="别让她知道我说过这些，可我认为朔弥确实将村庄守得很好。"
D.Strings[57910]="我要抓住你！"
D.Strings[57911]="慢点儿，梅，我累了！"
D.Strings[57912]="我是故意让你赢的。"
D.Strings[57913]="哎呦，我鞋里有颗石子。"
D.Strings[57914]="啦啦！你抓不到我！"
D.Strings[57915]="来呀，瞧你慢的！"
D.Strings[57916]="我压根就没认真！"
D.Strings[57917]="你抓不到我，罗！"
D.Strings[57918]="跟其他人一块去死吧，奴隶！"
D.Strings[57919]="把这些奴隶送到昆莱山！打开传送门！"
D.Strings[57920]="主人等这些神器已经等得不耐烦了。"
D.Strings[57921]="打开通往昆莱山的传送门，你们这群蠢货！赶快！"
D.Strings[57922]="安静点，奴隶！你们活着跟死了没什么两样。"
D.Strings[57923]="我的技术大不如前……开锁工具显然也生锈了。帮我个忙，别让任知道你在这里找到我了，行吗？"
D.Strings[57924]="看来你又是空手而归？"
D.Strings[57925]="今天有收获吗？你还是什么都没带回来呢。"
D.Strings[57926]="我见你又在钓鱼了……运气有没有比昨天好一点？"
D.Strings[57927]="这是一个好运之吻，相信会对你有所帮助。"
D.Strings[57928]="要是你能多抓几条鱼回来，我也不会怪你终日虚度光阴。"
D.Strings[57929]="还好我当初不是因为你的钓鱼技术才嫁给你的……"
D.Strings[57930]="你知道，我一直被困在这笼子里，看着魔古的一举一动，可我相当肯定，自己从没见过魔古女孩。那是为什么？"
D.Strings[57931]="我被他们抓住时，正在其中一个金色池塘边解决内急问题。我想这就叫因果报应吧。"
D.Strings[57932]="任说我肯定连一个魔古炮弹都偷不到。我怎么知道它们竟然这么重！"
D.Strings[57933]="那是我最后一次被他们抓住了，我保证。"
D.Strings[57934]="你怎么耽搁了这么久？我差点以为他们这次不会派人来救我了……有点心灰意冷。"
D.Strings[57935]="我总结出来一条规律，魔古都睡得不沉。去转告别人吧。"
D.Strings[57936]="终于能伸展筋骨了！在里面只能缩着。他们真该花钱造些大点的笼子！"
D.Strings[57937]="啊，这些孩子永远是精力旺盛！"
D.Strings[57938]="要是摔倒了，擦破膝盖，可别跑来对着我哭鼻子！"
D.Strings[57939]="他们整天如此。照看他们真是让我精疲力尽。"
D.Strings[57940]="目前还没钓到什么，可时间还早。"
D.Strings[57941]="我看见它们在水里游来游去，可就是不咬线！"
D.Strings[57942]="还是运气不佳。我想是鱼饵的问题。"
D.Strings[57943]="请再给我一个应急浮标，阿林。"
D.Strings[57944]="记住——飞过10个检查点旗帜，然后从下方穿过终点线。"
D.Strings[57945]="我们用三角旗围出了赛道，但如果你选择其它飞行路线，也不会受到惩罚。"
D.Strings[57946]="你也许会发现其它捷径。"
D.Strings[57947]="我已经带你看过了部分赛道。现在让我们去瞧瞧终点线吧。跟我来！"
D.Strings[57948]="记住，在真实比赛中，你要与骑士团的其它受训者同场竞技。"
D.Strings[57949]="这就是终点线。在你飞过所有10个检查点之后，从下方穿过终点线，以锁定排名。"
D.Strings[57950]="切记，要从下方飞过终点线！"
D.Strings[57951]="我们的课程结束了。"
D.Strings[57952]="如果你想对草药学有更深的了解，我建议你去四风谷的半山市集找韩·繁花谈谈。$B$B我会为你在地图上标出位置。"
D.Strings[57953]="你正在寻找药剂师。他能配出真正神奇的药水和酊剂。立刻使我摆脱了皮疹！$B$B呃哼……维克多·皮尔斯在师匠大厅出售他的商品。我会在你的地图上标记这个位置。"
D.Strings[57954]="奖励丰厚。"
D.Strings[57955]="速度越快，奖励就越丰厚。"
D.Strings[57956]="傲古，再给我一个火罐。"
D.Strings[57957]="多加小心，朋友！"
D.Strings[57958]="愿你得到清风的眷顾！"
D.Strings[57959]="常回来看看！"
D.Strings[57960]="一路平安，旅行者！"
D.Strings[57961]="德明大叔送了我条金鱼当生日礼物。他管它叫苏石。"
D.Strings[57962]="可爸爸说我把它喂得太饱了，于是它越长越胖。"
D.Strings[57963]="胖得连碗都装不下了，所以我们只好把它养在这池塘里！"
D.Strings[57964]="还算好。我想它喜欢这里。"
D.Strings[57965]="你喜欢待在这儿，对吧苏石？"
D.Strings[57966]="给，苏石。你是我最好的朋友！"
D.Strings[57967]="至尊天神军需官就在山谷里。莲蕊贤者与其他阵营的代表都在金色平台的下层。$B$B我会在你的地图上标出他的位置。"
D.Strings[57968]="啊，你要找宽仁的贾鲁！他就在锦绣谷魔古山宫殿的台阶上徘徊。$B$B我会为你在地图上标出他的位置。"
D.Strings[57969]="旋翼机出击！"
D.Strings[57970]="让我们再试试旋翼机之击！"
D.Strings[57971]="我真是毫无头绪。旋翼机之击？"
D.Strings[57972]="为什么……为什么是他？我们只是淳朴的农民……怎么竟然这么倒霉？"
D.Strings[57973]="旋……翼……"
D.Strings[57974]="怎么了？"
D.Strings[57975]="我丈夫想去看看水边发生了什么事。就在那时……那时……$B$B<苏云长老泣不成声。>"
D.Strings[57976]="……机……"
D.Strings[57977]="先别哭。然后呢？"
D.Strings[57978]="一枚该死的炸弹朝我们袭来。我没死，可……我丈夫……"
D.Strings[57979]="我要跑走了。"
D.Strings[57980]="呃，老方，我好像把你的洒水壶给弄丢了。能再给我一个吗？"
D.Strings[57981]="我是在昆莱山上的棚屋里找到这罐虫子的。起初我也没多想，直到看见了这些字……"
D.Strings[57982]="这一定是条信息！搞不好还是什么重大线索！"
D.Strings[57983]="你不明白！这可能是末日来临的预兆！"
D.Strings[57984]="什么字？噢，你是说盖子上的那些？可能只是别人随手乱写的。没什么深层含义。"
D.Strings[57985]="呜哇！！"
D.Strings[57986]="别搞笑了。那只是一罐虫子。对我来说简直不堪入目。"
D.Strings[57987]="胡说！看，这就是我们不该离开村子的原因！"
D.Strings[57988]="随便你。我敢说，它会带你绕上一个大圈子，然后害你一无所获！"
D.Strings[57989]="好，我就跟着线索走，看看它会带我去哪儿！"
D.Strings[57990]="小心那东西，军军！一阵狂风就能把你卷到海里去！"
D.Strings[57991]="天哪，杜宇。你喂那东西吃了什么？"
D.Strings[57992]="也许我们该把你喂给那条鱼！"
D.Strings[57993]="杜宇是鱼食！哈哈！"
D.Strings[57994]="对于心怀和平的人来说，那可真是永生难忘的武器，陌生人。"
D.Strings[57995]="我要治疗。"
D.Strings[57996]="哇哦，杜宇。你拿的是什么啊？"
D.Strings[57997]="对我鞠躬，我们就开始。"
D.Strings[57998]="<杜宇看着你，颇感自豪。>"
D.Strings[57999]="欢迎你，$r。不必拘束，就像在自己家里一样。这里有好酒好饭，楼上还有卧床供你休息。\n\n<茂林热情地对你微笑。>"
D.Strings[58000]="谢谢你，茂林。"
D.Strings[58001]="好吧，女士们！看好了！"
D.Strings[58002]="真了不起！看来我得提防你了。"
D.Strings[58003]="这回合我赢了，菜鸟！"
D.Strings[58004]="我们为什么要跟你做生意？除了旗帜颜色以外，你和你那些部落同伴还有什么区别？"
D.Strings[58005]="我是这村庄唯一的保护者。我叫楚瑟农。$B$B我对你的到来表示欢迎，但我从冥想中得知，你此行会给这片土地带来巨大改变。希望当你离开潘达利亚时，这里会变得比从前更加美好。"
D.Strings[58006]="皎皎人呢？他应该保护村长。"
D.Strings[58007]="皎皎来自四风谷。他是个农民的孩子，一听说你到来的消息就立即从家里赶来。他觉得自己是个战士，可我敢说，他只是个自大的年轻人，渴望战斗的刺激，却不曾感受过战争带来的恐惧。"
D.Strings[58008]="啊，清风传达了贵客来访的消息。只要我们能保持开放的心胸，纯净的灵魂，就一定能从彼此身上获益良多。$B$B跟部落比起来，也许你的族人能给予我们更大的尊重。"
D.Strings[58009]="在探索潘达利亚时一定要心存戒备。对冒失的旅者来说，这是一片机遇与危险并存的土地。"
D.Strings[58010]="你脚下的大地富有生命力。别看它现在让你站得稳稳的，要是你胆敢将战祸和痛苦引来这里，它就会以牙还牙。这就是自然之道。"
D.Strings[58011]="噢，我就知道你会赢！我还得多加练习……"
D.Strings[58012]="让我们都全力以赴！"
D.Strings[58013]="<咆哮声。>"
D.Strings[58014]="让我们看看谁才是更出色的弟子。我要跟你决斗！"
D.Strings[58015]="我们的村庄不大，但我家世代都在这片山上酿造潘达利亚最优质的苹果酒。$B$B我现在只想平安回去，好收割庄稼，与孩子们团聚。"
D.Strings[58016]="嘿，伙计！我现在有点忙。等我教训完这个菜鸟再来跟我说话！"
D.Strings[58017]="你的攻击力很强，可我的防守更强！"
D.Strings[58018]="你得集中精神。再来一次！"
D.Strings[58019]="钓鱼能磨砺灵魂，但捕蟹能犒劳肠胃！"
D.Strings[58020]="难道不美么？如此优雅地在空中起舞。希望有一天，我也能拥有鹤般的美好气韵。"
D.Strings[58021]="$n引发了反击风暴。"
D.Strings[58022]="抱歉，我现在可没空理你。这是我向那些小姐们炫耀身手的大好机会。等我打赢再来找我！"
D.Strings[58023]="这么快就认输了？我早知道你不是我的对手！"
D.Strings[58024]="吉斯坦大师要跑去附近的青龙雕像处寻求治疗了。快对她使用切喉手，在她伤愈前将她击败！"
D.Strings[58025]="我又输了！我得多加训练才行。"
D.Strings[58026]="这次我赢了。看来需要多加训练的是你才对。"
D.Strings[58027]="从决斗中逃跑可不像话。"
D.Strings[58028]="愿先祖保佑我们免受这些外来者和他们暴力行径的侵扰。"
D.Strings[58029]="你是种什么生物？真奇怪……"
D.Strings[58030]="在你之前到来的陌生人偷走了我们的孩子。你又想偷什么？我们的妻子？还是美酒？"
D.Strings[58031]="许大师对你施放了致命的剧毒！快使用清创生血解毒。"
D.Strings[58032]="这里原本是个宁静的酿酒村。可现在，恐怖的战争已经让我们的孩子失去了天真。$B$B去别处打仗吧，$r。"
D.Strings[58033]="嘿，$n，我现在正忙着呢。我得集中精神！"
D.Strings[58034]="我感到浑身充满了力量。来吧！"
D.Strings[58035]="该死，我输了！哎呦……真累啊……"
D.Strings[58036]="想跑？看来我可真是够吓人的！"
D.Strings[58037]="哈！这回合苏琪赢了。"
D.Strings[58038]="我正忙着让这菜鸟尝尝我拳头的滋味！"
D.Strings[58039]="让我们瞧瞧谁才是更强的翔龙骑士。"
D.Strings[58040]="跑了？等你鼓起勇气时再来面对我吧。"
D.Strings[58041]="什么？我……我输了？啊！我得多加努力，一定要打败你！"
D.Strings[58042]="不出所料。你根本不是我的对手！"
D.Strings[58043]="我有其它事情要忙。过会儿再来找我。"
D.Strings[58044]="开始吧。祝你好运。"
D.Strings[58045]="应该直面挑战，而不是消极逃避。"
D.Strings[58046]="你堂堂正正地打败了我。干得好。"
D.Strings[58047]="这回是我赢了。祝你下次好运。"
D.Strings[58048]="我不想麻烦外人帮忙。但要是你乐意……"
D.Strings[58049]="再次感谢你的帮助，$n。我们的孩子都已安全返回，敌人也已经四散而逃。$b$b对我来说，随时欢迎你和你的部落造访潘达利亚。"
D.Strings[58050]="这里很少有外来者。乘死亡浮船而来的外来者更是少之又少。"
D.Strings[58051]="你好啊，外来者。$b$b<金警惕地打量着你。>"
D.Strings[58052]="谢谢你，$g先生:女士;！那家伙可真难闻。"
D.Strings[58053]="我可以走了吗？"
D.Strings[58054]="我……我能回家么？"
D.Strings[58055]="用锤子是挺有趣，可我现在准备回家了。"
D.Strings[58056]="妈妈！我要回家，妈妈！"
D.Strings[58057]="我想家！"
D.Strings[58058]="谢谢！我不喜欢联盟。"
D.Strings[58059]="瞧瞧你，简直瘦得皮包骨头！你得多吃点！"
D.Strings[58060]="你是否值得我们信赖，不是我说了算。在村长作出相反的判定以前，我都当你是朋友。"
D.Strings[58061]="就在不久前，我们还过着只知道酿造可口苹果酒的简单生活。在这么短的时间内，一切都变了。"
D.Strings[58062]="我准备好开始飞行竞技赛了。"
D.Strings[58063]="我需要另一只坐骑，参加飞行竞技赛。"
D.Strings[58064]="谁也不知道变幻之风会带来什么，也许是可怕的风暴，也许是盛大的丰收。看来这次带来的是你。$B$B现在，我想问问，你究竟是风暴还是丰收？"
D.Strings[58065]="妹妹，我们必须行动起来！否则，我们所有的收成都会赔在这场自己无份参与的战斗中！"
D.Strings[58066]="我们只能尽力而为，亲爱的妹妹。我们不是战士，无法赶走外来者。"
D.Strings[58067]="楚在干嘛？他怎么还在道场里训练？他应该保护我们！"
D.Strings[58068]="要是我们陷入更大的危机，楚一定会挺身而出。他向来如此。"
D.Strings[58069]="我真心希望你是对的。"
D.Strings[58070]="欢迎来到坡东村，异乡人。我不知你是为何而来，但你看起来需要休息。$B$B不如坐下喝杯可口的苹果酒，将烦恼丢到一边，怎么样？"
D.Strings[58071]="你为什么会到我们村子里来，外来者？"
D.Strings[58072]="我们是来执行救援任务的。"
D.Strings[58073]="他们是为战争而来！你没看见他们是怎么杀死其他外来者的吗？"
D.Strings[58074]="你不明白。部落都是怪物！我们跟他们可不一样。"
D.Strings[58075]="够了，全都闭嘴！你们击败了那些偷走我们孩子的人。光凭这个，我就该给你们一次机会，让你们证明自己值得我们信赖。"
D.Strings[58076]="当你渐渐离开恐惧废土，你对科沃克的控制力也越来越弱！赶快回去！"
D.Strings[58077]="我就知道你能做到！"
D.Strings[58078]="有人来救我们了？也许还有希望……"
D.Strings[58079]="<你的翔龙好奇地看着你。>"
D.Strings[58080]="我不了解这个所谓的“联盟”，但你看起来值得信任。我会集结所有人，做好重建的准备后，就来与你会面！"
D.Strings[58081]="<你的翔龙对你微微一笑。>"
D.Strings[58082]="我不了解这个所谓的“部落”，但你看起来值得信任。我会集结所有人，做好重建的准备后，就来与你会面！"
D.Strings[58083]="<你的翔龙对你咕噜了两声。>"
D.Strings[58084]="<你的翔龙看着你。>"
D.Strings[58085]="<你的翔龙百无聊赖地看着你。>"
D.Strings[58086]="<你的翔龙优雅地四处翱翔。>"
D.Strings[58087]="<你的翔龙在你的手臂上蹭着鳞片。>"
D.Strings[58088]="<你的翔龙撞了你一下，差点把你撞倒。>"
D.Strings[58089]="<雏龙对你咕噜了两声。>"
D.Strings[58090]="<雏龙优雅地四处翱翔。>"
D.Strings[58091]="<雏龙撞了你一下，差点把你撞倒。>"
D.Strings[58092]="你们这群畜生不懂放弃吗？"
D.Strings[58093]="龌龊的畜生！我不允许你们玷污这片土地！"
D.Strings[58094]="不…我不能让国王失望…我…我…"
D.Strings[58095]="你们部落在这里毫无力量。"
D.Strings[58096]="要是你输了，别说酸话！"
D.Strings[58097]="别担心。如果你输了，我可以把肩膀借给你哭。"
D.Strings[58098]="我也许看上去温和可人，可我也是冲着头等奖来的！"
D.Strings[58099]="我会品尝到甜美的胜利。"
D.Strings[58100]="我会是个有风度的赢家，我保证！"
D.Strings[58101]="我刻苦训练了一个星期。胜利将是我努力付出换来的回报。"
D.Strings[58102]="别担心。我会光荣取胜。"
D.Strings[58103]="我会全力以赴，拔得头筹。"
D.Strings[58104]="以我的必胜战略，我不可能失败。"
D.Strings[58105]="尹大师正在治疗，快打断他！"
D.Strings[58106]="欢迎来到云端翔龙骑士团。只有在我们骑士团里达到崇拜的人才能获得我们的云端翔龙。"
D.Strings[58107]="欢迎你，翔龙骑士！我这里有美丽的云端翔龙，欢迎随意挑选。"
D.Strings[58108]="干得好，$n。你驯养的云端翔龙现在是你的了。你们共同的旅程……才刚刚开始。"
D.Strings[58109]="决定去游泳了，是吧？嗯，看你毫发无伤的样子，我就知道你一切平安。"
D.Strings[58110]="再等……一会儿。"
D.Strings[58111]="我们必须小心应对近来在海岸上发生的事。坡东村是个酿酒小镇，不是战斗要塞。$B$B你也应该提醒你的首领，在评判我族人时也应该持有同样谨慎的态度。我们不主动寻衅，但也决不是缩头乌龟。$B$B我得好好想想。"
D.Strings[58112]="我的族人面对过许多考验……可却从没遇到过这样的事。"
D.Strings[58113]="你们的战争让这里遭遇了前所未有的灾难。与你们那些飞艇和炸弹比起来，就连螳螂妖的威胁都显得稍逊一筹。"
D.Strings[58114]="我已经把这里发生的一切报告给了影踪派。希望他们能采取行动。$B$B尽管我们都对即将到来的考验毫无准备，但也必须面对。"
D.Strings[58115]="雏龙也爱你！"
D.Strings[58116]="雏龙亲昵地蹭着你的手臂。"
D.Strings[58117]="雏龙喜欢你的爱抚！"
D.Strings[58118]="雏龙认为你该原谅自己。"
D.Strings[58119]="雏龙认为你非常有趣。"
D.Strings[58120]="正在掷出诱饵"
D.Strings[58121]="雏龙很高兴见到你！"
D.Strings[58122]="在天上！它靠近了！"
D.Strings[58123]="在那！准备好！"
D.Strings[58124]="你可以在这钓鱼，但别耽搁太久。我不喜欢被打扰。"
D.Strings[58125]="祝你好运，王牌飞行员！"
D.Strings[58126]="你能做到，王牌飞行员！"
D.Strings[58127]="咿！我爱你，王牌飞行员！"
D.Strings[58128]="我会为你喝彩，王牌飞行员！"
D.Strings[58129]="那只不过是小菜一碟。"
D.Strings[58130]="我就知道你能做到，王牌飞行员！"
D.Strings[58131]="你是这里最好的训练员！"
D.Strings[58132]="王牌飞行员，你是最棒的！"
D.Strings[58133]="你看见他的脚了吗？"
D.Strings[58134]="冲啊，王牌飞行员！"
D.Strings[58135]="你太酷了，王牌飞行员！"
D.Strings[58136]="哎呀，你应该能赢的，王牌飞行员！"
D.Strings[58137]="不！他怎么会输了？"
D.Strings[58138]="我依然爱你，王牌飞行员！"
D.Strings[58139]="重赛！"
D.Strings[58140]="你下次一定能赢，王牌飞行员！"
D.Strings[58141]="你做到了，王牌飞行员！"
D.Strings[58142]="把他们打得落花流水，王牌飞行员！"
D.Strings[58143]="噢，快看他那一身肌肉！"
D.Strings[58144]="把衬衫脱掉，王牌飞行员！"
D.Strings[58145]="在下一场飞行竞技赛开始前，你有充足的时间思考自己学到了什么。在比赛日，与我交谈即可参与竞赛。"
D.Strings[58146]="程大师要把你活活烧死！快走开！"
D.Strings[58147]="你这臭猢狲！"
D.Strings[58148]="瞧你那张蠢脸，穆诺！"
D.Strings[58149]="吃芜菁去吧，穆诺！"
D.Strings[58150]="在我们的农场上不许出现笨猢狲！滚开！"
D.Strings[58151]="我要用铁铲敲爆你的头！"
D.Strings[58152]="你们兔妖全身都是烂芜菁和臭牦牛的味儿！"
D.Strings[58153]="我败了。"
D.Strings[58154]="你今天做了许多事，$n。好好休息，明天再来吧。"
D.Strings[58155]="你怕那些恐怖的爬虫吗，$r？"
D.Strings[58156]="你今天已经为岛上的翔龙尽了全力。明天再回来继续训练吧。"
D.Strings[58157]="你今天已经为你的雏龙尽了全力。我会照顾好它，但记得明天要回来查看进展。"
D.Strings[58158]="我们明天再继续对抗邪煞。现在，好好休息吧。"
D.Strings[58159]="你今天做了许多工作，$n。我们明天再继续训练。"
D.Strings[58160]="我想我感觉到了干扰，看来你已经打败了我的助手们。现在可以来挑战我了。"
D.Strings[58161]="干得好，$n！参加完比赛，想必你一定累坏了。去好好休息吧。明天还有很多任务等你完成呢。"
D.Strings[58162]="你想让祖塔再为你做点什么，嗯？"
D.Strings[58163]="嚯，$n！你今天收拾了好大一个烂摊子！嗯，你今天的“任务”已经完成了。去好好休息吧。明天还有很多事情要做！"
D.Strings[58164]="谢天谢地，你终于把酒找回来了，$n！既然今天的任务已经完成，是时候开怀畅饮了！"
D.Strings[58165]="你把你的雏龙照料得很好，$n。你今天已经竭尽所能了。明天一定要再来看望翔龙哦！"
D.Strings[58166]="你只会成为这片贫瘠土地上的又一位无名牺牲者。"
D.Strings[58167]="等你做好参赛准备，就来与我交谈，$n。"
D.Strings[58168]="该死的螳螂妖！走开！"
D.Strings[58169]="去城外找奥黛丽·伯恩赫普，就在矮人区北部，湖畔小屋附近。"
D.Strings[58170]="去城中台地的顶上找名叫瓦佐克的兽人，就在飞行管理员东边。"
D.Strings[58171]="程大师正在旋转！使她瘫痪！"
D.Strings[58172]="谢谢，光板儿！"
D.Strings[58173]="看看光板儿找到什么了！"
D.Strings[58174]="%s变得愤怒异常！"
D.Strings[58175]="你知道“碎玉闪电”用牛头人语怎么说吗？萨拉斯语呢？纳迦语呢？"
D.Strings[58176]="对，就是那个！我们的果酒享誉翡翠林。真希望我能把它们都带在身上。"
D.Strings[58177]="潘达利亚自从被迷雾笼罩之后，就再也没经历过全面战争。影踪派总能应对在这片土地上滋生的任何麻烦。"
D.Strings[58178]="哎……我不知道该怎么说你们。为什么要把战争引到我们的海岸上来？为什么要跟这……部落作战？"
D.Strings[58179]="康村长担心不已，他请求影踪派帮忙应对你们的到来。我至今还不敢相信祝踏岚来了！"
D.Strings[58180]="我们不愿卷入你们的争端。可我担心的是，一旦燃起战火，我们将再难独善其身。"
D.Strings[58181]="啊，这想法真令人不安。我们的末代皇帝建议我们不要活在恐惧的阴影里。现在你明白为什么我们喜欢喝酒和欢庆了吗？"
D.Strings[58182]="你们这些入侵者！出去！"
D.Strings[58183]="我不是战士，可我也会帮忙守卫坡东村！"
D.Strings[58184]="咿呀！"
D.Strings[58185]="离……开……我的……果园！"
D.Strings[58186]="我们必须保护美酒！"
D.Strings[58187]="我也许不是一名战士，可我会保护我的家园和家人！"
D.Strings[58188]="拿出勇气来，邓！苹花家的甜酒危在旦夕！"
D.Strings[58189]="我们走吧！酒桶在果园里。"
D.Strings[58190]="那是个非常奇特的仪式。"
D.Strings[58191]="你要尽量避免打断这个奇特的仪式。"
D.Strings[58192]="从可疑的雪堆里钻出了一只淘气的雪妖。"
D.Strings[58193]="别动，相信它不会攻击我们的！"
D.Strings[58194]="不管你做什么，别让自己看上去像根胡萝卜！"
D.Strings[58195]="要是它想过桥，就发起攻击！"
D.Strings[58196]="我习惯击退小不点……"
D.Strings[58197]="看看我们找到了什么。第一桶失而复得的美酒！这桶归我了，各位。"
D.Strings[58198]="我对各种形式的恢复魔法都有所涉猎，从潮汐之能到神圣之力，但我真正擅长驾驭的始终是雾之优雅。"
D.Strings[58199]="我们会继续监视魔古族的动态，$n。但是，恐怕要具备更大的力量才能应对前方的危险，你目前还没做好准备。等你累积更多经验后，再回来找我们吧。"
D.Strings[58200]="在粉碎我的对手前，我总是喜欢让他们美餐一顿。"
D.Strings[58201]="我曾经以为过于强大的是牧师。现在看来，是潜行者才对。"
D.Strings[58202]="我不忍心看武僧同伴们受苦。可我能撑过去。"
D.Strings[58203]="海特总会对我们没完没了的工作发牢骚。看看你能不能让他打开话匣子。绝对是滔滔不绝。"
D.Strings[58204]="不，我不是那个程。没任何关系。 \n\n是的，我是一位武僧，尽管我总梦想着有一天能成为猎魔人。"
D.Strings[58205]="干得好。记住，只有身心矫捷，才能活得长久。"
D.Strings[58206]="最后一波猢狲舰船来袭了！"
D.Strings[58207]="等你打败他们之后，跟同伴一起为珀收集丛林酒！"
D.Strings[58208]="包围他们！一个也别放走！"
D.Strings[58209]="让他们见识巨魔的力量！"
D.Strings[58210]="迅速干掉他们！还有很多事情要做！"
D.Strings[58211]="思南，请再给我一次希望之翼好吗？"
D.Strings[58212]="也许我们可以把剩下的货物卖给你，换些金币？要想活命，我们就必须从其它村子采购食物和饮水。"
D.Strings[58213]="你看起来似乎饱经风霜。要是你想买什么旅途用品，一定要告诉我。"
D.Strings[58214]="我会用生命保护我的家园！"
D.Strings[58215]="只要我守口如瓶，就能让孩子们对战争一无所知！"
D.Strings[58216]="再敢靠近一步，我就……我就攻击了！我发誓！"
D.Strings[58217]="我们跟你们无冤无仇。愿意挑选些货物吗？"
D.Strings[58218]="我们是生意人，不是战士。要不要看看我的商品？"
D.Strings[58219]="一颗不长眼的炸弹击毁了我的农场。我该怎么生活下去？"
D.Strings[58220]="为什么不去其它地方重新开垦农田？相信其他村民会帮助你的。"
D.Strings[58221]="在南边有一处断崖，在那种田应该不错。站在崖边还能俯瞰峡谷。你也许是对的，陌生人。"
D.Strings[58222]="我在这村里住腻了。真希望能到处旅行，看看这个世界啊。也许等我存够了钱，我就能开始自己的史诗冒险了！"
D.Strings[58223]="我们不是战士。我只负责制作工具和狩猎用的轻型武器。"
D.Strings[58224]="蜜露村根本没做好战斗的准备。希望这场争斗能尽早结束！"
D.Strings[58225]="哦天哪……那武器真不一般。"
D.Strings[58226]="想不想躺下歇会儿？那听起来当然比战斗要好。"
D.Strings[58227]="你是从哪儿找到那么精美的护甲的？能让我……摸一下吗？"
D.Strings[58228]="美食是生活中必不可少的。即便是像你这么勇敢的$c，也应该花时间坐下来享受人生的精华！"
D.Strings[58229]="许多人都忘了，美酒不仅可以用来喝，还能用来烹饪美食！在全潘达利亚，没什么能跟我大名鼎鼎的蜜露烤鱼相提并论！"
D.Strings[58230]="即使是在眼下这种战乱时期，人们也仍然需要并享受着美食。我花再长时间烹饪也是值得的。"
D.Strings[58231]="我们得把酒送到安全的地方。我的佳酿简直是全村的命脉！"
D.Strings[58232]="让开，送酒员来了！"
D.Strings[58233]="让他过来！那个魁梧的年轻熊猫人救了一桶蜜酒！"
D.Strings[58234]="美酒来了！"
D.Strings[58235]="它还没准备好起飞呢，姐妹！"
D.Strings[58236]="我们别无选择！必须通知其他村民，让他们知道这里发生的一切！"
D.Strings[58237]="请抓紧时间。我想出发了。"
D.Strings[58238]="再给我点时间，我能弄好。真的。"
D.Strings[58239]="在遭遇死亡之翼后，我们已经对天火号进行了全面改装！我们现在不但有了舰载固定翼战机和旋翼机，还给它装上了18英寸口径的滑膛式海岸轰击炮组。$b$b密集的炮火一定会让部落无处遁形，随便他们上天入地，翻山过海，都会被我们给炸出来。"
D.Strings[58240]="我准备好出发了。"
D.Strings[58241]="呸！这里不欢迎你！"
D.Strings[58242]="不论敌人使出何种招数，若能逮准时机命中要害，就会使其动弹不得。利用这一要诀，避开致命攻击。"
D.Strings[58243]="不是所有问题都能用拳头解决。有时你必须以自己为中心点，朝远处的目标引导你的能量。"
D.Strings[58244]="作为武僧，反应力就是你最可宝贵的资源之一。迅速思考和行动的能力，常常能助你转危为安。"
D.Strings[58245]="有时，最好的防御就是在敌人采取行动前，先发制人。"
D.Strings[58246]="对某些敌人来说，大部分力量都是来自于手中挥持的武器。我？我更喜欢用巨型武器和致命剧毒来对付我的敌人。"
D.Strings[58247]="有时候，时机和精准都把握得恰到好处的攻击，足以击败最难对付的敌人。"
D.Strings[58248]="等你学会控制自己的动作后，就必须学会控制敌人以占取先机。敌人在给自己疗伤时，可能会暴露出自己弱点，使你有机会打断他们。这往往能让胜败立显。"
D.Strings[58249]="你可真是耐人寻味啊，$c。是什么动力驱使你来到了潘达利亚？渴望冒险？期待战斗？也许还有别的？"
D.Strings[58250]="我们不是第一次经历黑暗时期了。在黑暗中总会有一抹曙光。"
D.Strings[58251]="我们已经许久没有经历过战事了。为了所有人的幸福，真希望和平能尽快到来。"
D.Strings[58252]="我们怎么办？已经一败涂地了！"
D.Strings[58253]="要是没有了庄稼，我们就要失去美酒了！"
D.Strings[58254]="拜托，别把战火引到这里来。这跟我们毫无干系！"
D.Strings[58255]="我的家人世代守卫着这座村庄。我祈求自己能继承祖业。"
D.Strings[58256]="我愿意献出自己的生命，以确保蜜露村安全无虞。这是祖业的传承。"
D.Strings[58257]="武僧的训练永无竭日。总有身心合一的更高境界等待追寻。"
D.Strings[58258]="你们为什么要让这片土地遭受战争和杀戮？潘达利亚是和平之地。"
D.Strings[58259]="我们也许不是正牌的战士，可我们会不惜一切代价守护自己的家园和土地。"
D.Strings[58260]="我担心，你们的到来会打破这片土地微妙的平衡。"
D.Strings[58261]="呀，那东西是个致命陷阱！"
D.Strings[58262]="你们的飞行死亡机器是末日来临的预兆。"
D.Strings[58263]="你们怎么如此仇恨其他外乡人？我不明白。"
D.Strings[58264]="让我们瞧瞧……要是我把这个燃料阀门给卸下来的话……"
D.Strings[58265]="你为什么会来这里？"
D.Strings[58266]="我很确定，这个“阀门”其实是个脚趾甲。地精……"
D.Strings[58267]="%s一边摆弄着伐木机，一边自言自语。"
D.Strings[58268]="长久以来，我们已经过惯了和平的日子，真不知道大家要怎么应对这突然降临海岸的战事。"
D.Strings[58269]="你们为什么要剑拔弩张地来到这里？你们在这里展开激战与杀戮，究竟有什么目的？"
D.Strings[58270]="我一直想知道，外乡人何时会闯上我们的海岸，然后你们就来了。"
D.Strings[58271]="瞧瞧这个——简直太业余了！甚至连二级涡轮叶片都没有。"
D.Strings[58272]="对！我奶奶能造出比这个可靠复杂十倍的东西。而且她做到了！"
D.Strings[58273]="等着瞧吧，伙计们。我们马上就能拥有一台完美的杀人机器了。"
D.Strings[58274]="那是……樱桃木传动轴吗？是谁做的？！"
D.Strings[58275]="二层已固定。现在加固第三层……"
D.Strings[58276]="这原本是一座由我爸爸负责治理的小村庄。我们农时耕种，闲时酿酒。我们每年都会造访其它村子一次，与那里的村民们互通有无。这种生活让我们感到怡然自得。$B$B现在，战斗的回音响彻四野，我们必须小心谨慎地度过眼下这个混乱时期。我只希望问题能尽快得到解决。"
D.Strings[58277]="我不信任你，$r。"
D.Strings[58278]="我这一生见多识广，可从没遇见过像你这么奇怪的生物。"
D.Strings[58279]="你们这些人总是喜欢不请自来。"
D.Strings[58280]="你必须先跟我的助手过招来证明自己。只有打败他们，你才能面对我。"
D.Strings[58281]="好了。继续前进。"
D.Strings[58282]="最多只能走到这里了。看看你能找到什么！"
D.Strings[58283]="我不喜欢它看南瓜的眼神……"
D.Strings[58284]="它就像是一只愤怒的兔子……体型更大……更咬牙切齿。"
D.Strings[58285]="我在为陛下执行重要任务。$b$b“探听消息”的重要任务。而这与你无关！"
D.Strings[58286]="我的宠物们会跟我说话。还会在夜晚给我讲故事。"
D.Strings[58287]="那说不通。再好好检查一下。"
D.Strings[58288]="你将长久牢记这场战斗。"
D.Strings[58289]="真是太诡异了。我不认为这水流被施了某种魔法，可却存在着一股微弱的残余能量。"
D.Strings[58290]="我在索拉查盆地见过类似的东西。"
D.Strings[58291]="……这里肯定有些不对劲。在我们回去之前，也许应该采集一些他们在这里种植的大个蔬菜？"
D.Strings[58292]="你疯了！女孩，你疯了！"
D.Strings[58293]="他在为我们创造一个新世界。他不是在……拌色拉！"
D.Strings[58294]="你必须把精神集中在训练上！再试一次！"
D.Strings[58295]="我看见你在底下调查船只，对付那些生物。干得好。有什么发现吗？"
D.Strings[58296]="你们俩要不要来点儿什么？"
D.Strings[58297]="联盟的“英雄”。我倒要看看没有飞艇掩护，你还怎么战斗！"
D.Strings[58298]="这片土地蕴藏着——你不了解的玄机——"
D.Strings[58299]="他们竟敢违抗我们——违抗地狱咆哮的部落——我当时真应该赶尽杀绝！"
D.Strings[58300]="燃烧吧，联盟渣滓！燃烧！"
D.Strings[58301]="这片土地将是你葬身之地。"
D.Strings[58302]="不！猛砸！我说猛砸！"
D.Strings[58303]="你这里有什么美酒？"
D.Strings[58304]="你好啊，$n。我为你精心挑选了几种美酒。要是你有兴趣，我还愿意把酿造的本领传授给你。"
D.Strings[58305]="上将！看见你平安真是太好了。"
D.Strings[58306]="恐怕你得独自向前推进了。"
D.Strings[58307]="我要奉命返回主战队，执行母舰护航任务。联盟海军的全部兵力将在两个月后抵达。"
D.Strings[58308]="别耍小孩子脾气，泰勒。军情七处的军官们会留下帮你。我建议先做一番侦查。"
D.Strings[58309]="你或许可以招募些当地人。你很能干，这里就交给你了。"
D.Strings[58310]="谢谢，凯瑟琳。你来得正好，在母舰的全力支持下我们就能向北推进——"
D.Strings[58311]="那我怎么办？我没有人手！我们不知道部落在哪儿，也不知道要对付多少敌人！"
D.Strings[58312]="遵命，上将。"
D.Strings[58313]="祝你成功。"
D.Strings[58314]="“大展拳脚。”哼。"
D.Strings[58315]="夜风，带着你的人往内陆地区搜查。探测部落的踪迹，找到安度因王子。"
D.Strings[58316]="蠢蛇。我说开火！"
D.Strings[58317]="这片土地饱经风霜，灭世者败亡后，它再次焕发了生机。你会发现，我的宠物们也具备类似的坚毅品格。"
D.Strings[58318]="做好准备，$n。$b$b我们即将进入危机四伏的环境！"
D.Strings[58319]="我准备好出发了，将军。"
D.Strings[58320]="哎呦。那可真疼。才没有呢。"
D.Strings[58321]="噢。邪恶的大魔古。我好怕呦。"
D.Strings[58322]="来吧，蠢货。"
D.Strings[58323]="你想干掉我？"
D.Strings[58324]="感谢圣光，你终于来了，$n。这里出了大问题，我们的头领正在大肆屠杀！"
D.Strings[58325]="请抓紧时间！我必须留下照顾伤患。"
D.Strings[58326]="非常感谢！$B$B由于我们雇用冒险者帮忙驱赶那些淘气的精灵，土灵仇灰为此大发雷霆。$B$B我能理解他的烦乱，可这攻击也太过分了！"
D.Strings[58327]="由于我们雇用冒险者帮忙驱赶那些淘气的精灵，土灵仇灰为此大发雷霆。"
D.Strings[58328]="我能理解他的烦乱，可这攻击也太过分了！"
D.Strings[58329]="你就这点本事？"
D.Strings[58330]="那连挠痒痒都算不上。"
D.Strings[58331]="看来你真不擅长折磨人。"
D.Strings[58332]="那招也能伤到人？"
D.Strings[58333]="有时这些蠢蛋太好对付了。"
D.Strings[58334]="这根本不是他想要的。"
D.Strings[58335]="准备受死吧，$r。"
D.Strings[58336]="我要把螺栓插进你们的厚脑壳里！"
D.Strings[58337]="对，没错……站在那儿……"
D.Strings[58338]="别动，$r！"
D.Strings[58339]="不要动，野兽！"
D.Strings[58340]="终于……有了战斗的理由。"
D.Strings[58341]="我……我以为永远无法脱身了……"
D.Strings[58342]="我还以为自己永远也摆脱不了那些眼睛！"
D.Strings[58343]="我认识回家的路。谢谢你，$g先生:女士;！"
D.Strings[58344]="爸爸！我要回家，爸爸！"
D.Strings[58345]="我想念我的亲人。我想家！"
D.Strings[58346]="谢谢！我不喜欢部落。"
D.Strings[58347]="部落入侵者！弟兄们，拿起武器！"
D.Strings[58348]="联盟必胜！"
D.Strings[58349]="潘达利亚是我们的，混账！"
D.Strings[58350]="别弄脏我们的基地！"
D.Strings[58351]="死吧，部落渣滓！"
D.Strings[58352]="我想我闻到了什么气味……"
D.Strings[58353]="你休想活着逃走，$r！"
D.Strings[58354]="潘达利亚是我们的！"
D.Strings[58355]="终于有了值得交手的敌人。"
D.Strings[58356]="蝼蚁般的$r……"
D.Strings[58357]="%s仔细地检查着谷中的水流。"
D.Strings[58358]="你看起来十分可口……"
D.Strings[58359]="你会是一具不错的尸体，$c。"
D.Strings[58360]="你好啊，$n。想学习制皮技术吗？如果你需要，我这里还有不少精美的手工制品。"
D.Strings[58361]="地狱咆哮的军队会将这片土地染红！"
D.Strings[58362]="你好啊，$n。有兴趣学习铭文的神秘艺术吗？还是想了解草药学的复杂知识？"
D.Strings[58363]="我不怕你，$r。你应该怕我才对……"
D.Strings[58364]="我跟那个笨手笨脚的家伙共处过很长时间了，也学会了一两招疗伤的本领。也许我能把它们传授给你？"
D.Strings[58365]="猢狲不和你耍嘴皮子了！"
D.Strings[58366]="把蠢蛋偷得分文不剩！"
D.Strings[58367]="杀死蠢蛋！"
D.Strings[58368]="你觉得熊猫人明白自己在这里的处境吗？"
D.Strings[58369]="也许他们早就知道了。也许那正是他们躲起来的原因。"
D.Strings[58370]="集齐我们所需要的，让他弄清原委。你准备好了吗？我们出发吧。"
D.Strings[58371]="拉希奥的密探相互低声窃语着。"
D.Strings[58372]="我所目睹的恐惧……"
D.Strings[58373]="再也不想看见第二次。"
D.Strings[58374]="%s朝$n憨笑。"
D.Strings[58375]="我要让这些畜生付出代价……"
D.Strings[58376]="我对你感激不尽，朋友。"
D.Strings[58377]="你在等什么？新人们需要你的帮助！"
D.Strings[58378]="不，我也不知道里面有什么。"
D.Strings[58379]="我们付出了汗水和鲜血，这片土地属于我们！"
D.Strings[58380]="是个术士！他不可能传送很远——肯定还有其它基地。"
D.Strings[58381]="我这是怎么了？"
D.Strings[58382]="你携带太多酒了。返回酿酒大锅，把美酒送回去。"
D.Strings[58383]="噢！又失败了。"
D.Strings[58384]="你真该小心点儿……"
D.Strings[58385]="让我看看能不能帮你善后……"
D.Strings[58386]="哇，我想我逮到了一条大鱼……"
D.Strings[58387]="哎呦！看来那家伙比我想的还要大……"
D.Strings[58388]="你有时间吗？"
D.Strings[58389]="我已经准备好了。"
D.Strings[58390]="我跟随影踪派，将他们在长城另一侧的诸多事迹如实记录下来——我可不想在这混战中弄丢任何宝贵的手札！$b$b这并非没有先例。游学者们世代以来始终在编纂着熊猫人的历史。在潘达利亚各地都散落着他们的笔记。要是你能收集到这些史料，一定能得到游学者们的赏识！"
D.Strings[58391]="哇哦，那是个大家伙，看起来很难对付！"
D.Strings[58392]="通往昆莱山的道路寒冷险峻，危机四伏。可不入虎穴，焉得虎子——轻易达成的交易哪有什么油水可捞！"
D.Strings[58393]="翅膀给了我们高飞的自由。"
D.Strings[58394]="谁说机器不是天然的？！我的宠物至少是百分之五十的纯天然！"
D.Strings[58395]="我正在集中精神……你能不能去烦别人？"
D.Strings[58396]="你能相信吗，奥妮克希亚竟然任由这些留在她的巢穴里？我要发大财了！"
D.Strings[58397]="要是你没到过奥妮克希亚的巢穴，就不算是真正冒险过！"
D.Strings[58398]="外边的沼泽散发着一股奥妮克希亚的口臭味！"
D.Strings[58399]="我会慢慢、慢慢地打你。"
D.Strings[58400]="主人会在艾泽拉斯降下地狱烈焰，然后我们就能让圣光从这恼人的世界上彻底消散！"
D.Strings[58401]="你们所有人都必须帮主人实现伟大的复活。只有凭借他的力量，我们才能迎来永久的安宁！"
D.Strings[58402]="我们的主人——万物守护者，他的光芒将刺瞎异教徒的双眼，赋予我们无限的力量！"
D.Strings[58403]="你准备好接受主人的馈赠了吗？你将被他慈爱的怒火庇佑，还是会像其他人那样被吞噬殆尽？"
D.Strings[58404]="萨格拉斯必将重生！"
D.Strings[58405]="恶魔是这个世界的未来。你越早接受这一点，就能越早加入胜利方。"
D.Strings[58406]="卡利姆多属于恐怖图腾。没人能妨碍我们。$B$B我们是至高无上的，你马上就会亲眼看着我粉碎你那悲惨的队伍。"
D.Strings[58407]="我知道你是一位战斗宠物训练师，$r。不如施展本领，跟恐怖图腾较量一下？"
D.Strings[58408]="我的蛇很漂亮对吧？……对吧？"
D.Strings[58409]="在我和我可爱的毒蛇面前，你毫无半点儿机会！"
D.Strings[58410]="不可能！你下次输定了！"
D.Strings[58411]="换这家伙试试！"
D.Strings[58412]="不！我的宝贝蛇！"
D.Strings[58413]="我要让你冷晕过去！"
D.Strings[58414]="我提醒过你了，宝贝儿。就你那点热量，还不足以对付我！"
D.Strings[58415]="哎呦！我被烧伤了！"
D.Strings[58416]="歇会，降降温吧，宝贝儿。很快就又轮到你了。"
D.Strings[58417]="雪球失控碾压！你现在没机会了！"
D.Strings[58418]="支离破碎！"
D.Strings[58419]="没想到你那么不怕冷。"
D.Strings[58420]="你的宠物是个冰冷无情的杀手！"
D.Strings[58421]="这事决不会就这么算了！"
D.Strings[58422]="就凭你的热度还对付不了我！"
D.Strings[58423]="你好吗，宝贝儿？"
D.Strings[58424]="<赤精的声音在你脑内回响。>$b$b你需要我帮你抵达台顶吗，$n？"
D.Strings[58425]="是的，赤精。"
D.Strings[58426]="飞上高空！"
D.Strings[58427]="<赤精的声音在你脑内回响。>$b$b我感觉到你需要我帮你抵达台顶。"
D.Strings[58428]="<赤精的声音在你脑内回响。>$b$b让我帮你登上台顶吧，朋友。"
D.Strings[58429]="我很愿意接受你的帮助，赤精。"
D.Strings[58430]="战争使者来了！退后！"
D.Strings[58431]="我在调查这里的生态情况，为了……研究。"
D.Strings[58432]="送他们下地狱吧，$n！不管那些是什么……"
D.Strings[58433]="生命是通往不死的必经之路。我的宠物们深知这个道理。"
D.Strings[58434]="啊，驯龙。$B$B等这些美丽的家伙长大后，就能把我那蠢哥哥比下去了！"
D.Strings[58435]="我就说相信老苏利没错吧！哈哈哈！"
D.Strings[58436]="吸下去，怪物！！"
D.Strings[58437]="呀！这些是什么？！"
D.Strings[58438]="呸，离开我的新座驾！"
D.Strings[58439]="让我们瞧瞧这个控制杆是干嘛用的……哦，对了！它能让你屁股开花！"
D.Strings[58440]="我甚至还忙里偷闲，装了个I.W.I.N.按钮！"
D.Strings[58441]="干得好啊，$n！过桥就能抵达村子了。我正在替那些陆战队员收拾烂摊子。"
D.Strings[58442]="我有点喜欢这玩意儿。你们觉得呢？我们能留下它吗？"
D.Strings[58443]="我们就是不能安静地搞定它！"
D.Strings[58444]="……你们只是农民的孩子。"
D.Strings[58445]="你今天为我们做了太多事，$n。我们的工作还将继续，但好歹已经取得了小小的胜利。"
D.Strings[58446]="谢谢你，$r！我感到战局正在朝有利于我们的方向发展。你为我们赢得了喘息之机，$n！"
D.Strings[58447]="别担心，泰峰。玉珑很强大。我相信，她一定能摆脱煞的腐化。"
D.Strings[58448]="煞是如何冲破了古老的囚牢，已经不重要了。我们必须制定行动方案，想想怎样才能再次将其逐出我们的土地？"
D.Strings[58449]="眼下，祝踏岚和影踪派正在向西行进。等他们找到煞之后，正义必将得伸。"
D.Strings[58450]="寺院的守卫人数寥寥，可他们意志坚强。我相信，我们一定能击败煞，将其逐出寺院，但那将会是一场艰苦卓绝的持久战。"
D.Strings[58451]="在这片沼泽里发生过许多重大冲突。我仍然能感觉到那久未散尽的能量。"
D.Strings[58452]="我们的战斗极其艰苦，泰峰。疑之煞狡诈阴险。怀疑的黑暗种子一经种下，只有心神无比强大的人才能将其荡除。"
D.Strings[58453]="寺院的守卫者在陆地上死守，而云端翔龙骑士团则在空中作战。只要齐心协力，就一定能将煞赶离我们的家园。"
D.Strings[58454]="我也能出去对抗邪煞吗？"
D.Strings[58455]="别犯傻！煞魔危险得很！"
D.Strings[58456]="煞魔会冲进来吗？"
D.Strings[58457]="好了，好了。别害怕。勇敢的英雄们正在和煞交战。只要我在这，就没人能伤害你。"
D.Strings[58458]="大多数人都讨厌沼泽，可我知道在沼泽地阴湿的表面之下，隐藏着不为人知的重大秘密。"
D.Strings[58459]="让萨弗拉斯在你头顶上方挂个几年，你就能学会欣赏熔火甲虫的适应力了。"
D.Strings[58460]="你在这里只会一败涂地。"
D.Strings[58461]="你休想击败我的队伍。我是永生不灭的！"
D.Strings[58462]="柯尔凡，我们继续吧。"
D.Strings[58463]="|TInterface\\Icons\\ability_warrior_shieldmastery.blp:20|t%s施放|cFFFF0000|Hspell:117961|h[密封之盾]|h|r！"
D.Strings[58464]="要是这些小东西与它们的原型有半点相像，你就毫无机会！"
D.Strings[58465]="真希望有一天能环游世界。你见过暴风城吗？"
D.Strings[58466]="外域的微风中夹杂着平静与安宁的气息。"
D.Strings[58467]="已获取目标。开火！"
D.Strings[58468]="我们必须精诚合作，保护纳格兰的本土生态。"
D.Strings[58469]="将它烧成平地！"
D.Strings[58470]="收到。让他们尝尝厉害！"
D.Strings[58471]="你介意吗？"
D.Strings[58472]="收到。马上行动。"
D.Strings[58473]="血精灵是宇宙的主宰。这毋庸置疑。"
D.Strings[58474]="来做个交易如何？要是我赢了，你就给我一万个金币？"
D.Strings[58475]="十三个螺旋分离器？没错。十个电动轴节钳？没错。我那把专用扳手上哪儿去了？"
D.Strings[58476]="呃。执行这任务才有两吨炸药？分量不够啊。完成这种使命光靠这么点儿炸药怎么行。起码得请……地精纵火型炸药出马。"
D.Strings[58477]="才三十台旋翼机？要想顺利完成任务，还需要许多许多台。"
D.Strings[58478]="我不管你有多矮，也不管这些箱子对你来说有多大多重，把它们弄到甲板下面去。"
D.Strings[58479]="咯咯！"
D.Strings[58480]="康村长，我们必须赶快行动！至少，把村里的卫兵召集起来！"
D.Strings[58481]="等等，邓。我们……有访客了。"
D.Strings[58482]="干得好！我们守住了基地其它区域。"
D.Strings[58483]="国王在上——这里怎么了？那玩意是什么？"
D.Strings[58484]="你的敌人被名叫“煞”的黑暗能量控制了。煞能依靠疑惑等负面情绪滋长。"
D.Strings[58485]="我并不惊讶。部落都是怪物！"
D.Strings[58486]="我见过你们的空中堡垒。你们对“和平”的定义很是有趣。"
D.Strings[58487]="如果任其作恶，部落会吞噬你们的土地。你不打算帮忙对抗他们？"
D.Strings[58488]="我们不怕战斗。我们的战士尽管人数稀少，却个个身手不凡。"
D.Strings[58489]="感谢你的盛情款待，村长。我向你保证，你做得很对。"
D.Strings[58490]="如何处置这些士兵是你的事情，我们不会选择立场。"
D.Strings[58491]="这不是一场种族战争这么简单。他们的仇恨会吞噬这片土地——我们绝不会介入。"
D.Strings[58492]="我必须离开了——还有其他人登上了我们北方的海岸。"
D.Strings[58493]="喷泉那边！把他们轻轻放下。"
D.Strings[58494]="丹尼尔，那位病人休克了。待在旁边观察他的心率，要是有异常，马上通知我。"
D.Strings[58495]="斯坦顿，把冰块敷在那人的头上。我们得帮他消肿。"
D.Strings[58496]="我们要对林地采取什么行动？"
D.Strings[58497]="这里需要守卫。要是你想去林地复仇，邓，你可以跟这位客人谈谈。"
D.Strings[58498]="他们说，要种下巨大的胡萝卜。他们说，会其乐无穷。"
D.Strings[58499]="这么大个的胡萝卜显得真不实际。"
D.Strings[58500]="呸，我锄头又崩掉了一个角！"
D.Strings[58501]="看起来简直毫无进展……"
D.Strings[58502]="我们干嘛要种这么大个的胡萝卜？"
D.Strings[58503]="夜风，报告！下面发生了什么事？"
D.Strings[58504]="部落士兵从船骸游向你所在的位置。立即开火。"
D.Strings[58505]="你难道不知道，他们现在恨不得徒手掐死你？击毙他们！"
D.Strings[58506]="这场毁灭本可避免，$c。曾几何时，塞拉摩是和平的象征……"
D.Strings[58507]="让我看看塞拉摩被毁前的样子。"
D.Strings[58508]="没有旗舰的线索，也没有上将泰勒或安度因王子的踪迹。"
D.Strings[58509]="上将——我想他们是要投降。他们手无寸铁——只是不想淹死！"
D.Strings[58510]="不……这简直是屠杀……他们手无寸铁——呃！我不太……不太舒服……"
D.Strings[58511]="也许他们确实该死。"
D.Strings[58512]="某些决定会引发可怕的后果。"
D.Strings[58513]="你们这群畜生！你们疯了吗？"
D.Strings[58514]="弟兄们，放下武器——这是个当地人。"
D.Strings[58515]="我们来自联盟，没有恶意。告诉我，你刚才从我体内逐出的黑影是什么？"
D.Strings[58516]="这儿不是作详细解释的地方。简单说吧，由于你的所作所为，源自你自身的疑惑现形了。"
D.Strings[58517]="你不明白——我们是在这里打仗——"
D.Strings[58518]="噢，我明白得很。我有眼睛。可潘达利亚跟其它地方不一样，它有生命，会呼吸。你应该小心控制自己带来的能量。现在，丢掉那些武器！"
D.Strings[58519]="我好像把狗哨放错地方了。"
D.Strings[58520]="你似乎愿意收拾自己的烂摊子，外来者。也许我们能互相帮助。"
D.Strings[58521]="药剂师，能再给我来点跌打酒吗？"
D.Strings[58522]="嘎！"
D.Strings[58523]="他们领头的还躲着呢。把他找出来！"
D.Strings[58524]="你干掉他了——好样的！"
D.Strings[58525]="那黑影是什么？联盟在玩什么把戏？"
D.Strings[58526]="又是你。现在你见识到联盟的傲慢了吧！"
D.Strings[58527]="没有你们，我们也挺着胸膛在这里生活了几千年。"
D.Strings[58528]="你们是害怕战斗吧？"
D.Strings[58529]="这里是敌方领地，我们又孤立无援。看我们临场发挥了，勇士。"
D.Strings[58530]="但我发誓——地狱咆哮一定会在这里站稳脚跟。我们决不允许联盟霸占这片新大陆！"
D.Strings[58531]="我还没能证明我可以飞呢！我的宠物们也没有！"
D.Strings[58532]="孤身一人在树林里游荡不太安全，你觉得呢？"
D.Strings[58533]="呱呱"
D.Strings[58534]="不要相信别人的鬼话。龙只是战争的武器，别无它用。"
D.Strings[58535]="那些联盟渣滓会明白，激怒部落是什么下场！"
D.Strings[58536]="我们将以部落之名夺取这片土地，至死方休！"
D.Strings[58537]="他们甚至都还没见识到部落的怒火！"
D.Strings[58538]="等我们完成这里的事之后，联盟一定会后悔踏上这片土地。"
D.Strings[58539]="真是高明的把戏，可你真以为我就带一套武器来与你交手吗？我等了这么久，终于迎来了旗鼓相当的对手，总算能试试我这浸毒的利剑了。"
D.Strings[58540]="我总是觉得心神不宁。"
D.Strings[58541]="我们会从另一侧进攻，$c。联盟不会料到，我们这么快就发起地面攻击。等屠杀结束后再来找我。"
D.Strings[58542]="来吧，伙计们。我们能行。起飞！"
D.Strings[58543]="总有一天，我将探索整个世界，而我的宠物们也会与我同行！"
D.Strings[58544]="有人来找莫勒鲁了……"
D.Strings[58545]="坚持住，伙计。你会没事的。"
D.Strings[58546]="他的脉搏平稳，米希卡。但很虚弱。"
D.Strings[58547]="这些绷带脏兮兮的。我们帮你清理一下吧。"
D.Strings[58548]="要想真正了解这片土地，我们就必须公平地对待这些人。"
D.Strings[58549]="米希卡会好好照顾你的，能听见我说话吗？"
D.Strings[58550]="我接下来要杀死的十个兽人是献给你的，朋友。"
D.Strings[58551]="如果你继续在战争的路上越走越远，你的行为一定会引发严重的后果。"
D.Strings[58552]="任何行为都会引发后果。你知道自己的行为已经酿成什么后果了吗？"
D.Strings[58553]="我担心，这仅仅是个开始。"
D.Strings[58554]="你眼瞎了吗，竟然要延续这场战斗？"
D.Strings[58555]="所有的酒……都没了……"
D.Strings[58556]="好戏即将上演！爆炸！"
D.Strings[58557]="该你了！"
D.Strings[58558]="我会为了联盟的荣耀，勇敢光荣地战斗！"
D.Strings[58559]="沐浴在联盟的荣光下吧，$r。今天你应该明白，你根本不可能打败我！"
D.Strings[58560]="你也有宠物。我们打一场吧？"
D.Strings[58561]="收集蜜露酒桶"
D.Strings[58562]="这里乱糟糟的，是吧？"
D.Strings[58563]="部落需要你的帮助。"
D.Strings[58564]="我的帮助？！你们需要我的帮助？！我才不要介入你们那琐碎的战斗。"
D.Strings[58565]="你需要我的帮助？我正忙着帮你们收拾残局，恢复这里的和平。"
D.Strings[58566]="我今天原本只想收割庄稼。结果却跟小偷纠缠不休！"
D.Strings[58567]="我跟妹妹从来都没在蜜露村里见过这种阵势，从来没有！"
D.Strings[58568]="你们的飞艇差点把我们的气球弄爆了！"
D.Strings[58569]="我们对你们的战争不感兴趣，外乡人。这是个平静的村庄。"
D.Strings[58570]="在你们到来之前，平静得很。"
D.Strings[58571]="我们决不会让自己卷入你们的战斗。你可以留在这里，照料伤员，但休想拖我们下水。"
D.Strings[58572]="寺院绝不能沦陷！"
D.Strings[58573]="据说，“智慧能照亮前路。”$b$b……可光有智慧，我在夜晚照样会撞到脚趾头。"
D.Strings[58574]="很弱，但我比他强！"
D.Strings[58575]="他只是个受训者。大师的意志要强大得多！"
D.Strings[58576]="干得好，你距离真正的挑战又近了一步。"
D.Strings[58577]="击倒他们，我变得更为强大，超乎你的想象。"
D.Strings[58578]="你好，$n，你愿意学习如何在我们的土地上找到各种各样的金属，并加以冶炼吗？"
D.Strings[58579]="把绳子绑紧了，兄弟们！我们要立刻捕到这只幼龙。"
D.Strings[58580]="加把劲儿，你们这群懒虫，不然我就把你们活活烤熟！"
D.Strings[58581]="要是敢弄破一件货物，我就打碎你的脑袋！"
D.Strings[58582]="用生命守卫这些货物，你们这群垃圾杂碎！"
D.Strings[58583]="别用你们那长满跳蚤的脏爪子碰食物，肮脏的畜生们！"
D.Strings[58584]="密切注意这些雇佣兵，兄弟们！"
D.Strings[58585]="锣朝下方的螳螂妖大军发出了一声嘲讽般的巨响，加快了它们攻击的节奏。"
D.Strings[58586]="你今天的训练已经完成了。明天再回来继续训练。"
D.Strings[58587]="但我们不想卷入这场生灵涂炭……血流成河的屠杀。"
D.Strings[58588]="你们的冲突会让这里饱受摧残。别把战火引到这片海岸！"
D.Strings[58589]="但我们不想卷入这场……血流成河的种族纷争。"
D.Strings[58590]="这里隐藏着力量，我们必须让它显现！"
D.Strings[58591]="我能感觉到它们，逝去已久的魔古魂灵！"
D.Strings[58592]="不惜一切代价，守住这片遗迹！"
D.Strings[58593]="每个角落都仔仔细细的搜查！"
D.Strings[58594]="不要动摇！我们很快就能和古老的魔古同伴们团结在一起了！"
D.Strings[58595]="第一包种子是免费的！要是想买更多种子，随时可以回来找我，明白了吗？"
D.Strings[58596]="记住一点，真正的庄稼需要一整天的生长周期，所以在你完成耕种和照料后，第二天再回去收获果实吧！"
D.Strings[58597]="好吧伙计，看来你已经能独立打理这个农场了。要是愿意的话，可以每天回来种植和收割蔬菜。如果我们努力劳作，也许还能把这地方升级！"
D.Strings[58598]="好吧伙计，我这有些坏消息。你每天都可以回来种植和收割蔬菜，但你得积累更多经验，才能帮我加入阡陌客。不过别忘了——随时欢迎你到农场上来！"
D.Strings[58599]="我们必须竭尽全力保护我族人的圣地和寺院。"
D.Strings[58600]="莫鲁克要打扁你！"
D.Strings[58601]="今年的收成不仅包括庄稼！"
D.Strings[58602]="我为这场战斗做了无数小时的准备。"
D.Strings[58603]="勇闯这片荒野，已经让我的宠物变得战无不胜。"
D.Strings[58604]="你将在潘达利亚最神圣的区域内面对最困难的挑战。"
D.Strings[58605]="叛徒卡拉克西……女皇陛下说得一点不错。"
D.Strings[58606]="大宰相佐尔洛克，女皇的代言人。"
D.Strings[58607]="遵照女皇的旨意，卡拉克西将被遣散。"
D.Strings[58608]="我看到绝望的卡拉克西已经沦落到去挖化石了。好极了，让我们做个了结吧。"
D.Strings[58609]="“毫发未伤”，确实如此。"
D.Strings[58610]="前进！卡拉克西已经公然显露叛徒的身份。消灭他们，一个不留。"
D.Strings[58611]="我看见你也排除万难，登上了寇塔峰。你已经证明了自己的能力，有资格与我交战。"
D.Strings[58612]="嘿女士！小心点好吗！"
D.Strings[58613]="别再摆弄那根棍子了！"
D.Strings[58614]="当心点！"
D.Strings[58615]="哎呦！怎么老用棍子戳人？！"
D.Strings[58616]="轻点女士！我可娇嫩得很！"
D.Strings[58617]="别再用那玩意儿戳我！"
D.Strings[58618]="干得好。你已经完成训练了。与我在玄牛神龛会面，领取奖励。"
D.Strings[58619]="怎么——不——不！他们有空军基地，秘密空军基地……我的船——我的——地狱咆哮会要了我的脑袋的！"
D.Strings[58620]="他们都得死。"
D.Strings[58621]="你！熊——什么的。这是什么巫术？"
D.Strings[58622]="我们只是渴望胜利的荣耀，渴望粉碎敌人。你们一直在帮助联盟吗？"
D.Strings[58623]="陌生人——你自身的疑惑现形了。潘达利亚跟其它地方有所不同，它有生命，会呼吸。你应该小心控制自己带来的能量。"
D.Strings[58624]="我们才不想卷入这场血腥杀戮。现在，请让你的人放下武器，否则你在这里就要面对两拨敌人了。"
D.Strings[58625]="你们的疑惑和仇恨在这片遗迹间引发了浩劫。自己收拾残局吧，然后到下方的村里来——我会尽力解释给你们听。"
D.Strings[58626]="阿卡隆已经进入了战场！"
D.Strings[58627]="夏克提克已经进入了战场！"
D.Strings[58628]="惊怖具象已经出现在战场上了！"
D.Strings[58629]="既然我们已经是熟人了，$n，那我就给你点提示吧。这附近的村民能帮你装扮农场，但你得先跟他们成为朋友才行。遗憾的是，你现在还无力帮助他们或赠送礼物，先把自己变强吧！"
D.Strings[58630]="噢你好，$n……吉娜是阡陌客的表决成员，所以……试着给她留个好印象，好吗？"
D.Strings[58631]="你受到了许大师致命毒药的折磨。快帮自己解毒！"
D.Strings[58632]="蒙蒙对你印象深刻，$n。你不求回报地帮助我。那正是阡陌客的意义所在。我会去你的农场上找你。蒙蒙决定投你一票。"
D.Strings[58633]="渣滓们，休想像玷污卡利姆多那样毁掉这片土地！"
D.Strings[58634]="这些卷心菜说服了我，$n。能种出这种作物的人，理应是阡陌客的一员。我会为你和农夫老愚投上一票。待会儿在你农场上见。"
D.Strings[58635]="噢，别再抱怨了，抓住棍子！"
D.Strings[58636]="这么多抱怨！你以为我要杀了你吗！"
D.Strings[58637]="你没资格抱怨别人对你提供的帮助！"
D.Strings[58638]="你愿意继续卡在树上吗？！"
D.Strings[58639]="嘿，是你把自己卡在那的！我只是想帮你！"
D.Strings[58640]="知道么，我其实可以让你自生自灭！"
D.Strings[58641]="在这世上要是存在岩石和石料专家，那就一定是矮人！"
D.Strings[58642]="如果我们能弄清拉格纳罗斯是如何影响了海加尔的低等住民，也许就能想出更好的补救措施。"
D.Strings[58643]="你的世界……所有世界……都将燃烧！"
D.Strings[58644]="任何在园艺方面显示出如此高超天赋的人，都理应成为阡陌客的成员。我才不在乎我那浮躁的孙子说什么！郝瀚对农夫老愚的看法是错的。我投你一票，$n。"
D.Strings[58645]="我为了迎接这一天的到来，已经做了世世代代的准备。"
D.Strings[58646]="就连林中可爱的花朵都与我们作对了……"
D.Strings[58647]="你看见没有？\n\n仇灰诅咒了绿石采掘场的玉石，并把它变成了怪物。"
D.Strings[58648]="这座村庄是经仇灰同意后建造的，那是在很久以前了。"
D.Strings[58649]="就连著名的绿石佳酿，都被仇灰诅咒得跟我们作对！\n\n他的仆从把未受影响的佳酿都偷走了。"
D.Strings[58650]="我觉得自己已经无力对抗它们了。\n\n真是太感谢你了！"
D.Strings[58651]="仇灰的大地魔法甚至让齐理的玉狮雕像活了过来！\n\n谁知道它跑到哪儿去了……"
D.Strings[58652]="嗯，听起来昆森猢狲给泥爪先生添了不少麻烦。也许我们能帮得上忙。"
D.Strings[58653]="%s召唤|cFF298A08瑟拉提克工虫|r前来帮忙！"
D.Strings[58654]="我会在村里与你会面。"
D.Strings[58655]="我需要更多时间准备混合，$n。好了会通知你的。"
D.Strings[58656]="你应该慎重考虑自己对帮助的定义，女士！你拿着那根棍子危险得很！"
D.Strings[58657]="你想给我看什么，克尔鲁克？"
D.Strings[58658]="你能再给我看看卡拉克西维斯下方的内室吗？"
D.Strings[58659]="你确定要与克尔鲁克同行么？"
D.Strings[58660]="虽然山峰很安全，但附近那些地方可不一定。多加小心！"
D.Strings[58661]="|TInterface\\Icons\\ability_druid_tigersroar.blp:20|t %s躲了起来，准备|cFFFF0000|Hspell:131271|h[跃出暗影]|h|r！"
D.Strings[58662]="%s看不见他的猎物！"
D.Strings[58663]="记得拿上一袋悟道者补给品！"
D.Strings[58664]="嘿，吉娜！真是稀客啊。"
D.Strings[58665]="随我走走吧，$n。我想去看看农夫老愚。"
D.Strings[58666]="知道吗，真是多亏了你的那些葱。"
D.Strings[58667]="厨师总在寻觅新鲜的蔬菜。不管你在农场上种了什么，都能用于烹饪，或是出售给其他厨师。"
D.Strings[58668]="你好，农夫老愚！"
D.Strings[58669]="听着，鉴于你们俩帮了我这么大一个忙，我会投出第一票，帮你们加入阡陌客。"
D.Strings[58670]="你们还得争取到另外四张选票才行，但迟早会有的。"
D.Strings[58671]="安顿下来吧，要是你想找工作，可以随时到市场上来。"
D.Strings[58672]="先安顿下来吧。你可以在自己的农场上耕种，但由于经验不足，你能做的恐怕也仅限于此。等你见识了潘达利亚更多的风土人情后，一定要再来找我。"
D.Strings[58673]="欢迎来到汇风岭！"
D.Strings[58674]="你一定就是我听说的那位训练师了。说说，你害怕失败吗？"
D.Strings[58675]="一次勇敢的尝试，可还远远不够。等你准备好重试之后，再来与我交谈。"
D.Strings[58676]="卡拉克西说话了。女皇必亡。"
D.Strings[58677]="我们开始吧。"
D.Strings[58678]="各种各样的诡异生物……从天而降！"
D.Strings[58679]="你好，蒙蒙。泥爪先生的农场上一切都好吗？"
D.Strings[58680]="嘿，小愚！是我啊，蒙蒙！"
D.Strings[58681]="嘿，沿路走来的不是蒙蒙吗？"
D.Strings[58682]="太可怕了，但别告诉他我说过这样的话。兔妖到处肆虐。庄稼也长不出来。还有东西在不断地吞吃着收成。"
D.Strings[58683]="但你的农场看起来还不错。知道吗，要是你能跟这里的人交上朋友，他们也许会给你些好东西，更让农场增色。"
D.Strings[58684]="天哪，看看这地方！你的农场太漂亮了。看来你可没少交朋友！"
D.Strings[58685]="不管怎样，我只是来为那些胡萝卜向你道谢。"
D.Strings[58686]="它们真是脆爽，郝瀚觉得那简直是他最棒的作物！哈哈！"
D.Strings[58687]="你干得不错嘛，小愚。这是我的选票。"
D.Strings[58688]="谢谢大家能来！"
D.Strings[58689]="梦想家代代不绝——如刘浪一般的梦想家。"
D.Strings[58690]="你的梦想又是什么？别让任何人夺走它！"
D.Strings[58691]="珍藏于心，努力实现。梦想家有着改变世界的力量。"
D.Strings[58692]="朱鹤会保佑你们所有人。晚安！"
D.Strings[58693]="快看，有人走过来了。你好呀，农夫老方！很高兴见到你！"
D.Strings[58694]="你好，农夫老愚。我得亲自前来看看你的农场。"
D.Strings[58695]="|TInterface\\Icons\\inv_polearm_2h_mantid_01.blp:20|t%s施放了|cFFFF0000|Hspell:131320|h[利刃灌能]|h|r，快跑！"
D.Strings[58696]="不算太糟。看来你在那边还能多耕出几块地来。"
D.Strings[58697]="让同是农夫的我给你个建议。在半山市集里可以买到各种各样的升级用品。吉娜·泥爪出售工具，商人绿野贩卖种子。"
D.Strings[58698]="不论如何，我只是来为那些卷心菜向你致谢。比我种的还要好！"
D.Strings[58699]="事实上，任何能种出这种完美蔬菜的人都应该成为阡陌客，这正是我要投票支持你的原因。"
D.Strings[58700]="嘿，看来你只要再争取到两张赞成票就行了！"
D.Strings[58701]="你得向娜娜·泥爪和郝瀚·泥爪证明自己。这两位泥爪家族的成员可不好说话，但我相信你能办到。"
D.Strings[58702]="趁你在这里，别忘了四处看看。在晴日峰上能饱览昆莱山的美景。"
D.Strings[58703]="你在这里可以找到几位精通各类手艺的匠师。要是你在旅途中需要任何补给品，可以去他们那里采购。"
D.Strings[58704]="要是我们希望消灭联盟，就得尽快重整部队了。"
D.Strings[58705]="这里是训练场，你大部分训练都将在这里进行。来吧，让我为你引荐几位大师，他们将对你传授本领。"
D.Strings[58706]="这位是吉斯坦大师，她是引导迷雾的专家，能为自己和盟友提供帮助。"
D.Strings[58707]="这位是吴大师。她精通防御，能化解持久的攻击。"
D.Strings[58708]="这位是尹大师。他善于使用强大专注的治疗技能，令自己在战斗中免于殒命。"
D.Strings[58709]="这位是程大师。她掌握着行间战的高超战技。"
D.Strings[58710]="你——你——你是——娜娜·泥爪！我从——从没想过女——女——女族长会大驾光临！"
D.Strings[58711]="这位是曾大师。他精通冥想，并对发生在身边的一切有着敏锐的感知力。"
D.Strings[58712]="我得亲自前来看看老老愚的孙儿。"
D.Strings[58713]="我跟你祖父是老相识了。他过世时，我悲伤不已。"
D.Strings[58714]="知道吗，你们两个又让我想起他来了。"
D.Strings[58715]="在没有太多经验的情况下，你却还在坚持犁地，真是固执。"
D.Strings[58716]="敢于对抗我的孙子郝瀚，真是勇敢。"
D.Strings[58717]="而且你们两个还种出了美味的水果和蔬菜，展现出了过人的天赋。"
D.Strings[58718]="这位是许大师。他十八般兵器样样精通，普天之下几乎没有任何武器能难得倒他。"
D.Strings[58719]="因此，你赢得了我的尊重，我的感谢，还有我的选票。干得好。"
D.Strings[58720]="噢，还有农夫老愚。"
D.Strings[58721]="相信你爷爷一定会为你感到无比骄傲。"
D.Strings[58722]="最后要介绍的是程大师。程大师专攻反应和速度，会帮你开始你的训练。"
D.Strings[58723]="那么，我得走了。祝你训练顺利。"
D.Strings[58724]="我们只该在需要时才继续留在这里，$c。"
D.Strings[58725]="那个，至少蜜酒是不缺啦！"
D.Strings[58726]="欢迎加入……阡陌客！"
D.Strings[58727]="我期待与你合作。"
D.Strings[58728]="欢迎来到晴日峰。祝你训练顺利。"
D.Strings[58729]="欢迎。等你准备好开始时，就来与我交谈。"
D.Strings[58730]="她狠狠摔了一跤。伤势严重！我一直都叫不醒她。"
D.Strings[58731]="噢！你是说，她在意外发生前就是这个样子的？！"
D.Strings[58732]="欢迎来到晴日峰，$n。需要什么帮助？"
D.Strings[58733]="你能带我四处转转吗？"
D.Strings[58734]="好了！就像是没受过伤一样……吧……"
D.Strings[58735]="发生……什么事了？！"
D.Strings[58736]="啊，我想起来了。我有个祖传的酿酒师独门秘方……"
D.Strings[58737]="等等！别碰酒！那是我们仅有的一切！"
D.Strings[58738]="我的助手会带你去见程大师。祝你好运！"
D.Strings[58739]="跟我来，我会带你在晴日峰四处走走。"
D.Strings[58740]="<琪麟茫然地凝视天空，没有任何回应。>"
D.Strings[58741]="上将，我们看见了充满当地风格的景色。华丽的建筑群——"
D.Strings[58742]="别啰嗦了，伙计们。瞄准目标！"
D.Strings[58743]="听从上将命令，准备攻击，集中火力对付部落基地。"
D.Strings[58744]="他们开火了，长官！"
D.Strings[58745]="用火箭鱼雷轰击那些舰船。"
D.Strings[58746]="击中目标。打得真准。"
D.Strings[58747]="干得好。毫不留情！"
D.Strings[58748]="那一炮是为塞拉摩！"
D.Strings[58749]="下方有旗舰的线索吗？"
D.Strings[58750]="没有，上将。未能发现泰勒上尉及其坐舰的线索。"
D.Strings[58751]="敌人攻势猛烈……苏利，提升高度！"
D.Strings[58752]="反击！好好教训他们！"
D.Strings[58753]="够了——全军回报。准备地面进攻。"
D.Strings[58754]="我会帮你搬桶。还是说，你觉得那些桶会魔法般地钻进你的背包里？"
D.Strings[58755]="旗舰最后报告的位置就在下方。你能看见什么吗？"
D.Strings[58756]="雾……只有浓雾……等等！右转舵！我看见船了。"
D.Strings[58757]="英烈长存，$n。"
D.Strings[58758]="您先请，阁下。"
D.Strings[58759]="我说，看来我又赢了！"
D.Strings[58760]="那可真是太不幸了。"
D.Strings[58761]="啊，可你想到这个了吗？"
D.Strings[58762]="今天可真是个好日子啊，我都赢得不好意思了！"
D.Strings[58763]="哦天哪，我要输了！"
D.Strings[58764]="这可真是个大好机会啊。"
D.Strings[58765]="我就知道自己的选择是对的！"
D.Strings[58766]="也许我还能把自己的旧农场给找回来……"
D.Strings[58767]="我发现，有时适当地做些改变是好的。"
D.Strings[58768]="要是我妻子能看到这一切该多好啊。我要赢了！"
D.Strings[58769]="好戏还在后头呢！"
D.Strings[58770]="我不会对你客气的！"
D.Strings[58771]="迎面痛击！"
D.Strings[58772]="妈咪！妈咪！这个小气的驯兽员不肯让我赢！"
D.Strings[58773]="哦不，不是吧！"
D.Strings[58774]="你为——为什么要杀——杀死我的小兔子……"
D.Strings[58775]="希望你已经做好准备，让你的宠物变成我宠物的盘中餐。"
D.Strings[58776]="我已经提醒过你，在这片树林里危机四伏。"
D.Strings[58777]="你的勇气令人钦佩。"
D.Strings[58778]="感觉到什么了吗？"
D.Strings[58779]="真了不起！"
D.Strings[58780]="不要紧。为了胜利，牺牲区区一条性命是值得的。"
D.Strings[58781]="停，陆地上的傻大个们发起攻击了！准备鱼叉！"
D.Strings[58782]="所有战利品都是我的！"
D.Strings[58783]="你为什么非得那么做？……嗝儿！"
D.Strings[58784]="现在……动真格的了！不管是谁在控制着这些宠物，肯定是……嗝儿！"
D.Strings[58785]="阵亡！"
D.Strings[58786]="我们现在要杀了你。"
D.Strings[58787]="祖塔意料之中！"
D.Strings[58788]="今天你是赢家。享受胜利吧。"
D.Strings[58789]="你试穿下这个怎么样？"
D.Strings[58790]="很好，很好。祖塔晚点再款待你。"
D.Strings[58791]="干嘛对祖塔这么刻薄啊？"
D.Strings[58792]="战斗打响了。粉碎他们！"
D.Strings[58793]="我们是今天的主角。"
D.Strings[58794]="我马上就会教训你。"
D.Strings[58795]="我不会让你好过。"
D.Strings[58796]="再接再厉！杀啊！"
D.Strings[58797]="无关紧要。什么都别想阻止我胜利的步伐！"
D.Strings[58798]="别被我的平静给骗了。我会打败你。"
D.Strings[58799]="胜利是我们的，孩子们！"
D.Strings[58800]="干得好。几乎没人享受过击败我的殊荣。"
D.Strings[58801]="惊人的转折！"
D.Strings[58802]="你竟然！"
D.Strings[58803]="在我干掉你之前，我要让你尝尝前所未有的痛苦。"
D.Strings[58804]="感觉到疼了吗，伙计？"
D.Strings[58805]="我从没见过像你这样战斗的人。"
D.Strings[58806]="我敢说，你绝对没想到过这个。"
D.Strings[58807]="瞧瞧，这会有一点儿疼！"
D.Strings[58808]="看来这个会让人感到刺痛！"
D.Strings[58809]="我警告你，你的攻击不会让我动摇半步。"
D.Strings[58810]="与大地的力量抗争，注定是徒劳无功的。"
D.Strings[58811]="你很能打。"
D.Strings[58812]="大地绝不会动摇！"
D.Strings[58813]="循环永续。"
D.Strings[58814]="我真希望能找到更多蜜酒。我想我会试着自己去找。如果你需要更多帮助，就告诉我一声！"
D.Strings[58815]="你在对抗不可阻挡的力量。"
D.Strings[58816]="我们打呀！"
D.Strings[58817]="我赢了！"
D.Strings[58818]="不！我赢了！"
D.Strings[58819]="不！别杀死！改打这个吧！"
D.Strings[58820]="优秀的小东西！杀死另一个小东西！"
D.Strings[58821]="怎么不打？我让你们打！"
D.Strings[58822]="看来你被束缚在地面上了！"
D.Strings[58823]="我们被射到九天之外了！"
D.Strings[58824]="干得好。休息一下吧。"
D.Strings[58825]="我们赢定了！"
D.Strings[58826]="一个美丽的生命消逝了。"
D.Strings[58827]="启动进攻模块！"
D.Strings[58828]="你在我强大的战队面前毫无机会！"
D.Strings[58829]="系统彻底瘫痪！"
D.Strings[58830]="接合自我保护芯片。"
D.Strings[58831]="决不懈怠。全速前进！"
D.Strings[58832]="没什么难题是解决不了的。"
D.Strings[58833]="你以为我会怕你？我面对过奥妮克希亚！"
D.Strings[58834]="谁最伟大？是我！"
D.Strings[58835]="我希望你被龙吃掉！"
D.Strings[58836]="好吧，够了。换！"
D.Strings[58837]="进入巢穴就会遇到那样的事情！"
D.Strings[58838]="一桶？！我牙牙学语时就能轻而易举地搬起一桶，那时我才跟你膝盖一样高！"
D.Strings[58839]="好重，可我还能扛得动更多！再来！"
D.Strings[58840]="我也许高估了自己的力量……"
D.Strings[58841]="够了，这是我的极限了！这可真累人！"
D.Strings[58842]="我精疲力尽了！"
D.Strings[58843]="战斗简直是浪费生命。你们这些人怎么整天打打杀杀的？什么时候才能让自己享受简简单单的快意人生？"
D.Strings[58844]="部落，联盟……有什么分别？！你们不都爱喝美酒？你们不都珍惜自己的朋友和家人？"
D.Strings[58845]="你们怎么就不能开诚布公地讨论下彼此的分歧？我还没遇见过什么难题是长谈解决不了的！"
D.Strings[58846]="你根本无法理解自己面对的是什么力量。"
D.Strings[58847]="也许你现在准备按我的方式看待事物了？"
D.Strings[58848]="蜜露村是由蜜露家族管理的，但村子的支柱产业是酿酒！说到酿酒，那可是我蜜掌家族的拿手好戏！你在别处绝对喝不到这么好的蜜酒！"
D.Strings[58849]="你只会拖慢我们，但无法阻止我们。"
D.Strings[58850]="我们正赶去晨芳园过节，然后你就出现了！当我想象今夜的绚烂焰火时，我可没想到会是这样的！"
D.Strings[58851]="你见过这么壮观的东西吗？"
D.Strings[58852]="那是部落的船。全船战备部署！各就各位，准备战斗。打起精神来，弟兄们。大战一场！"
D.Strings[58853]="放弃吧，趁你还有机会！"
D.Strings[58854]="为什么要把战争引到我们的土地上来？你们的家乡呢？在那里已经没什么好争的了吗？"
D.Strings[58855]="你们的行为必定会引起影踪派的注意。说不定我能见到他们！"
D.Strings[58856]="我的村庄不会卷入你们的冲突。尽管你们的到来也许已经彻底打乱了我们平静的生活。"
D.Strings[58857]="这蜜酒是整个村子的命脉。现在也成了值得你争我抢的东西！"
D.Strings[58858]="赶快，这边！炮弹击穿了院墙！"
D.Strings[58859]="我们得走了。那蜜酒不会自己跑出来！"
D.Strings[58860]="很抱歉，可我没有圣物可以出售给你了。它们的魔法力量似乎已经消失了！也许我该改行当全职舞蹈家，改变一下人生的步伐也不错。"
D.Strings[58861]="多谢你的帮助。我一定会把这蜜酒送回村里。尽量别惹其它麻烦了！"
D.Strings[58862]="多谢你的帮助。尽量别惹其它麻烦了！"
D.Strings[58863]="我们不该让他们留在这儿吗？他们有伤员需要照料。"
D.Strings[58864]="那些从你们的战船上掉到我们农场里的炸弹又怎么说！"
D.Strings[58865]="他们会给我们的村庄带来更多灾难！"
D.Strings[58866]="在你们来之前，我们根本与世无争！"
D.Strings[58867]="在亲眼看着他们把我们从天上击落后，你们怎么还能继续保持中立？！"
D.Strings[58868]="那是战争的代价！"
D.Strings[58869]="够了！我们很快就转移。这些家伙把我们的舰船摧毁得面目全非了。"
D.Strings[58870]="把村民们愿意卖给我们的东西收集起来，准备安排其他人撤离。"
D.Strings[58871]="我真想马上长大！"
D.Strings[58872]="有人看见我哥哥了吗？"
D.Strings[58873]="要是有甜饼吃就好了。我喜欢甜饼！"
D.Strings[58874]="看来我的防御更胜一筹。等你准备好重试时，再来与我交谈。"
D.Strings[58875]="胡戈伦爱你！"
D.Strings[58876]="打得不错，可你还得多加努力才行。准备好重试时再来与我交谈。"
D.Strings[58877]="看来你还奈何不了我啊。等你准备好重试时，再来与我交谈。"
D.Strings[58878]="对你来说，我的力量似乎过于强大了。等你准备好重试时，再来与我交谈。"
D.Strings[58879]="看来你没能击败我。等你准备好重试时，再来与我交谈。"
D.Strings[58880]="如果你想将战火引到我们的海岸，那么这片土地会对你的冲动和暴力作出回应。"
D.Strings[58881]="我不知道最终会造成什么后果——没人知道。"
D.Strings[58882]="你的意志十分强大，但与我相比还是稍逊一筹。等你准备好重试时，再来与我交谈。"
D.Strings[58883]="看来我的助手们对你而言太难应对了。等你准备好重试时，再来与我交谈。"
D.Strings[58884]="你准备好面对最后的考验了吗，$n？"
D.Strings[58885]="要想击败我，你必须使出自己从其他大师那里学到的所有招数。要是你能做到，你的训练就完成了。"
D.Strings[58886]="你似乎还没能将我们传授给你的技能融会贯通。等你准备好重试时，再来与我交谈。"
D.Strings[58887]="海特大师要把你活活烧死。快走开！"
D.Strings[58888]="海特大师正在治疗。打断他！"
D.Strings[58889]="海特大师正在旋转。使他瘫痪！"
D.Strings[58890]="海特大师正准备用长矛发起重击！将他缴械！"
D.Strings[58891]="咱俩想到一块去了吗，$n？"
D.Strings[58892]="你在底下还舒服吗？"
D.Strings[58893]="我确定已经把结打得很紧了。要是你摔下来了，告诉我一声。"
D.Strings[58894]="没人能阻止恐怖图腾！"
D.Strings[58895]="你的傲慢将为你招致毁灭。记住我说的话！"
D.Strings[58896]="还没结束！"
D.Strings[58897]="太弱了。"
D.Strings[58898]="人人都爱马尔泰！"
D.Strings[58899]="来跟马尔泰聊聊吧！"
D.Strings[58900]="不用担心，速战速决。"
D.Strings[58901]="不算太糟，是吧？"
D.Strings[58902]="也许我该加大剂量，避免如此快速地死亡。"
D.Strings[58903]="先别高兴得太早。"
D.Strings[58904]="我会直接让你看看亡灵的力量。"
D.Strings[58905]="我果然更胜一筹！"
D.Strings[58906]="休息吧，宝贝儿。"
D.Strings[58907]="是的……加入我们吧！"
D.Strings[58908]="不！我们是战无不胜的！"
D.Strings[58909]="你确定想要面对巨龙之力吗？"
D.Strings[58910]="是时候让我兄弟看看，谁才是真正的驯宠大师！"
D.Strings[58911]="你只是走运罢了，仅此而已。"
D.Strings[58912]="我的话应验了吧！"
D.Strings[58913]="不！我才刚把它养大！"
D.Strings[58914]="希望你喜欢失败的滋味！"
D.Strings[58915]="我就知道沼泽是个正确的选择！"
D.Strings[58916]="也许我到这里来探险是错误的。"
D.Strings[58917]="沼泽中埋藏着许多秘密。"
D.Strings[58918]="胜利属于我！"
D.Strings[58919]="这可真惨啊。"
D.Strings[58920]="以吾父黑锤之名，我要打败你！"
D.Strings[58921]="干得好，兄弟们！我们办到了！"
D.Strings[58922]="你阻止不了我。为时尚早。我会继续训练！"
D.Strings[58923]="换这个试试！"
D.Strings[58924]="不出所料。你完全没机会。"
D.Strings[58925]="好好照顾那些葱。然后就耐心等待明天的到来吧，它们会长得成熟喜人。"
D.Strings[58926]="离结束还早呢。"
D.Strings[58927]="嘿，$n。你知道植物在生长过程中会遇到各种各样的突发情况吗？要是你有任何解决不了的难题，就来问我吧！"
D.Strings[58928]="不费吹灰之力。"
D.Strings[58929]="你将因自己的恶行而受到惩罚。"
D.Strings[58930]="呃——噢，看来今天我们的植物要被烤糊了。来浇些水吧。"
D.Strings[58931]="说赢就赢了！哇噢！"
D.Strings[58932]="要是你想提升自己的烹饪技能，就去集市上与任何铁掌家族的人聊聊吧。"
D.Strings[58933]="也许我该准备更多武器的……"
D.Strings[58934]="嘿！我在它身上可是花了大价钱的！"
D.Strings[58935]="千万别对我客气啊！"
D.Strings[58936]="我敢说，要是我一直赢下去的话，哪天也许会被邀请去暴风城作战！"
D.Strings[58937]="哇哦，你可真有两下子！"
D.Strings[58938]="再来！"
D.Strings[58939]="兽人最强！"
D.Strings[58940]="水流从不说谎。"
D.Strings[58941]="我要把你们全都消灭掉！"
D.Strings[58942]="你就这点本事吗？"
D.Strings[58943]="离我的船远点儿！"
D.Strings[58944]="我要摘掉你们所有人的脑袋！"
D.Strings[58945]="你们究竟是打哪儿冒出来的？！"
D.Strings[58946]="这些家伙已经吃尽苦头了。我不会让你得逞！"
D.Strings[58947]="灵魂在对我的胜利微笑！"
D.Strings[58948]="先祖，请原谅我。我败了……"
D.Strings[58949]="休息一下吧。保存体力，应对接下来的战斗。"
D.Strings[58950]="你的灵魂与先祖同在，小家伙。"
D.Strings[58951]="这些老骨头有不少学问要传授。"
D.Strings[58952]="你下次会做得更好。"
D.Strings[58953]="这是一份荣誉，外乡人。"
D.Strings[58954]="也许这会考验你的技能。"
D.Strings[58955]="你必须集中精神。"
D.Strings[58956]="身手矫捷啊，外乡人。"
D.Strings[58957]="你是谁来着？"
D.Strings[58958]="我的记性大不如前了。"
D.Strings[58959]="我队伍的攻势会把你粉碎！"
D.Strings[58960]="希望你现在能认清现实，你是不可能打败我的。"
D.Strings[58961]="不要紧。最后谁也阻止不了我。"
D.Strings[58962]="我的胜利近在眼前。"
D.Strings[58963]="那还远远不够。"
D.Strings[58964]="（已通过启用抑制力场，在英雄难度下击败了某位首领。该效果不能被取消。）"
D.Strings[58965]="不……这不对……"
D.Strings[58966]="它应该是美丽而淳朴的！"
D.Strings[58967]="也许是我泡错了茶？对，肯定是这样。抱歉，我泡错茶了。"
D.Strings[58968]="你最后怎么会在这儿？"
D.Strings[58969]="当军情七处的特工人员找到我时，他们想带我回家。可我却跑掉了。$B$B过了没多久，部落发现了我。$B$B在神龙之心的战斗中，我趁乱逃了出来。有位商人正携家眷逃往西边的朱家堡，他愿意载我一程。$B$B我就是在那里遇见梅·残酒的。$B$B她向我介绍了这个名为鹤翼的组织，并建议我陪同信使前往寺院，与朱鹤赤精会面。$B$B当邪煞出现时，我正在和其他门徒一起修炼。"
D.Strings[58970]="我无法眼睁睁的看着自己的人民在这里抛洒热血，自己却端坐在暴风要塞里！$B$B潘达利亚能教会我们许多事。这里蕴藏着巨大的力量。足以拯救万千苍生的力量。$B$B而我要做的，就是令这力量得见天日。"
D.Strings[58971]="你为什么不跟军情七处的特工们返回暴风城？"
D.Strings[58972]="闪亮的工具是我的！可口的胡萝卜也是我的！一切都属于昆森。一切都属于酋长伊普伊普！"
D.Strings[58973]="你好啊，陌生人。农场上一切还好吗？"
D.Strings[58974]="你看起来弱了点儿，$r。你得在这片土地上多加游历，才能让自己变得强大起来，帮助这里的住民。"
D.Strings[58975]="这附近的住民对陌生人心怀警惕，可一旦熟识之后，他们就会令你如沐春风。$B$B等你积累更多经验后，你就能向他们提供帮助，与他们建立友谊。"
D.Strings[58976]="这附近的住民常常需要帮助，可你还不够强大。你需要在这片土地上多加游历，等你回来时，他们就会求你帮忙了。"
D.Strings[58977]="你见过商人绿野出售的种子了吗？你在自己的农场上可以种植各种各样新鲜又奇妙的作物。"
D.Strings[58978]="你有没有考虑过在自己的农场上养几只动物？"
D.Strings[58979]="知道吗，农夫老愚住的房子简直就是个垃圾场！他应该跟迪娜谈谈。听说她很擅长重新装修。"
D.Strings[58980]="你看过我出售的所有商品了吗？你得先赢得阡陌客的青睐，才能从我这里买东西，要想做到这一点，你需要在这片土地上多加游历，积累更多经验。"
D.Strings[58981]="冈尼和我，我们与其它几名船员一起，被冲到了翡翠林的香里拉村附近。在海上颠簸了几个月后，我们的双脚早已疼得走不动路。我们来到了这里，找到了天堂。"
D.Strings[58982]="我和拉古旅行了好多天。可就在我们认为自己已经饱览一切时，我们再次感到了惊奇。"
D.Strings[58983]="我想继续前进，直到抵达西边那道雄伟长城，看见另一侧的景象为止，可拉古的眼睛却总盯着附近那些巨大的蔬菜。也许在内心深处，他渴望成为一名农夫！"
D.Strings[58984]="谁在召——召——召唤？"
D.Strings[58985]="懦——懦——懦夫……"
D.Strings[58986]="你现在有什么商品出售？"
D.Strings[58987]="你能告诉我一些关于你村子的事吗？"
D.Strings[58988]="村里人都是酿酒师和农夫。我们偶尔也会在需要时外出狩猎。$B$B这正是我想说的。如果缺少一把好弓，狩猎可真是难得要命啊！"
D.Strings[58989]="今天可真是逛集市的好日子啊，邻居。"
D.Strings[58990]="欢迎来到半山市集！"
D.Strings[58991]="你这有什么商品？"
D.Strings[58992]="你好啊旅行者，想要学习烹饪吗？"
D.Strings[58993]="你喜欢烹饪？那你可走运了，因为我愿意帮助志向远大的厨师。"
D.Strings[58994]="如果你因贸易而出名，其它村的熊猫人都去哪儿了？"
D.Strings[58995]="放下武器，拿起切肉刀吧，旅行者。铁掌家族的人能把烘焙、酿造、炖煮、蒸烧、烧烤等各类烹饪手艺传授给你！"
D.Strings[58996]="如果你想提升自己的烹饪技能，我正好有些知识要与你分享。"
D.Strings[58997]="我只能说，那个巨大的漂浮堡垒近来让许多旅行者却步难行。"
D.Strings[58998]="我想看看你这里有什么商品出售。"
D.Strings[58999]="那是漫长的旅程，可我最终还是找到了山谷。现在我正与哨兵部队一起努力，破解水池之谜。"
D.Strings[59000]="我们设法赢得了天神的信任，打开了山谷的大门，可我们必须继续向他们表明，我们肩负着和平的使命。"
D.Strings[59001]="看见那么多人被迫离开昆莱山的家园，这令我倍感煎熬。幸好我们为那些寻求庇护的人们找到了避风港。"
D.Strings[59002]="哨兵部队与我交换了在卡桑琅丛林经历的故事。我把自己在赤精寺院里的冒险奇遇告诉了他们。"
D.Strings[59003]="我在这片土地上游历得越久，就越喜欢这群熊猫人。唯爱佳肴美酒，平生与世无争。"
D.Strings[59004]="我在这片土地上旅行时，目睹了许多见闻。我感觉自己长大了一些……也许还略微……睿智了点儿。"
D.Strings[59005]="我相信联盟的未来与潘达利亚息息相关。$B$B在我们抵达这里后，就开始按部就班地采取行动。当神龙之心陷落时，我们就在那里。从某种意义上说，我们也参与促成了游学者周卓预见的实现。$B$B正因如此，在一切重回正途之前，我无法返回暴风城。"
D.Strings[59006]="兄弟们，你们都是受过严格训练的。你们都是精英，天火号的精英！"
D.Strings[59007]="这艘船曾经击败过死亡之翼。你们觉得那又小又破的部落前哨能跟联盟舰队的骄傲抗衡吗？不可能！"
D.Strings[59008]="哨兵部队与我交换了在卡桑琅丛林经历的故事。我把我们在赤精寺院里的冒险奇遇告诉了他们。"
D.Strings[59009]="下面那些绿皮渣滓摧毁了你们在南海镇的家园，封锁了孩子们在赤脊山玩耍的乐土，还把塞拉摩的妇孺屠杀殆尽。"
D.Strings[59010]="报仇的时刻到了！"
D.Strings[59011]="我们不该在这里战斗。不该这样！"
D.Strings[59012]="只要我们学会如何适当地索取，大地就会给予我们许多馈赠。如果你愿意的话，我会教你如何做。"
D.Strings[59013]="你不是本地人。有兴趣了解下潘达利亚的原生植物吗？"
D.Strings[59014]="这片土地上的野兽与你家乡那些截然不同。随我训练，你也许就能学会给它们剥皮的技巧。"
D.Strings[59015]="放血者兆金在冲击大门！我们必须阻止他进入宫殿内室！"
D.Strings[59016]="要是我们现在不击败韶天，就要满盘皆输了！"
D.Strings[59017]="我正在阻止其他魔古族接近宫殿阶梯。赶快！"
D.Strings[59018]="我……必须……坚持住！"
D.Strings[59019]="我不可能永远守住这道障碍。赶快，你必须去宫殿阶梯上解决督军！"
D.Strings[59020]="赶快，$r！我们双方也许正在交战，可眼下正面临着更大的威胁！"
D.Strings[59021]="我是来帮忙作战的。我能做些什么吗？"
D.Strings[59022]="%s开始召唤|cFFFE9A2E伪焰之灵|r！击败它们，阻止火墙！"
D.Strings[59023]="$n？你在这里做什么？天火号上需要你！赶快，使用传送门！"
D.Strings[59024]="再给多伦一点时间。坚持住！"
D.Strings[59025]="别让部落渣滓通过！"
D.Strings[59026]="他们已经突破第二道障碍了！击退他们！"
D.Strings[59027]="$c来了！别让$G他:她;通过！"
D.Strings[59028]="阻止$G他:她;！别让$G他:她;接近多伦！"
D.Strings[59029]="开始表演吧！"
D.Strings[59030]="要是你如此慷慨，我就把这金币收下了。"
D.Strings[59031]="那么……不如我们先别打赌了，继续过我们忙碌的生活吧？"
D.Strings[59032]="想骗我是吧？没那么容易！"
D.Strings[59033]="帮我们铲除他们，你的族人就能挺起胸膛傲然屹立在部落身边！"
D.Strings[59034]="我已经好多年没见到它显现得如此强烈了。"
D.Strings[59035]="如果你愿意，可以放弃。"
D.Strings[59036]="一笔不幸的业务开支。"
D.Strings[59037]="记住你的训练，海伦娜……这对你有益。"
D.Strings[59038]="我做到了！"
D.Strings[59039]="嗯，我想是熟能生巧吧。"
D.Strings[59040]="趁你还没受伤，赶快回来！"
D.Strings[59041]="好极了！胜利在望！"
D.Strings[59042]="噢不！那可不太妙……"
D.Strings[59043]="我们高飞吧！"
D.Strings[59044]="我们在高空翱翔！"
D.Strings[59045]="是的，多亏了$n。韶天领袖兆金已经被杀死了！"
D.Strings[59046]="在天神的帮助下，我们粉碎了魔古族的进攻。我们的士兵们得以清理残余，将他们赶出山谷。"
D.Strings[59047]="莱文！你还活着！那意味着……"
D.Strings[59048]="我们对抗魔古的战争还远未结束。但今天我们可以稍作休息，欢庆胜利。"
D.Strings[59049]="向你致敬，$n！你是山谷的救星，韶天征服者，人民的卫士！愿星辰吟诵你的大名！"
D.Strings[59050]="把迷雾萨满的火把从地里拔出来！"
D.Strings[59051]="击破长空！"
D.Strings[59052]="$n，你做到了！"
D.Strings[59053]="我们正说着呢！"
D.Strings[59054]="见好就收……"
D.Strings[59055]="你一定会后悔的，我保证。"
D.Strings[59056]="我警告过你了。真遗憾。"
D.Strings[59057]="情势发生了……最悲惨的转变。"
D.Strings[59058]="出乎意料的转折。"
D.Strings[59059]="别担心，很快就过去了。"
D.Strings[59060]="这下它没用了。"
D.Strings[59061]="你竟敢挑战我？我要让你见识部落真正的力量！"
D.Strings[59062]="你可真走运，我竟然如此心慈手软。"
D.Strings[59063]="不！你这卑鄙的可怜虫！我是不会输的！"
D.Strings[59064]="在我打败你之前，我决不会懈怠！"
D.Strings[59065]="咱俩谁先来？"
D.Strings[59066]="我赢了！我赢了！"
D.Strings[59067]="你可真是个作战高手！"
D.Strings[59068]="我要保存实力。"
D.Strings[59069]="我赢了？"
D.Strings[59070]="它怎么不动？"
D.Strings[59071]="以瓦里安国王的王权之力，我要打败你！"
D.Strings[59072]="联盟军队的又一场大捷！"
D.Strings[59073]="有人警告过我要小心你。我真不该大意。"
D.Strings[59074]="承蒙安度因王子的恩惠，我将在今天迎来胜利。"
D.Strings[59075]="我们将坚持不懈。"
D.Strings[59076]="祝你运气奇佳。"
D.Strings[59077]="别难过。继续训练，你一定能成就大业。"
D.Strings[59078]="我必须离开了——还有其他人登上了我们南方的海岸。"
D.Strings[59079]="干得好。我要为你的战术喝彩。"
D.Strings[59080]="养精蓄锐，伺机再战。"
D.Strings[59081]="一切都恰到好处。"
D.Strings[59082]="你确实相当强大。"
D.Strings[59083]="对决的时间到了！"
D.Strings[59084]="莫鲁克是最棒的！"
D.Strings[59085]="莫鲁克……被打败了？"
D.Strings[59086]="莫鲁克还没完呢！"
D.Strings[59087]="我的宠物都是我亲手养大的！你毫无半点机会！"
D.Strings[59088]="我就知道我的队伍赢定了！"
D.Strings[59089]="我的整支队伍都被消灭了！"
D.Strings[59090]="要是你以为我已经落败，那就大错特错了！"
D.Strings[59091]="我们现在可真要攻破你的队伍了！"
D.Strings[59092]="很快就胜负分明了！"
D.Strings[59093]="让我们看看谁才是更厉害的驯宠师。"
D.Strings[59094]="今天我是主角。打得漂亮。"
D.Strings[59095]="你是个强大的对手。今天是属于你的。"
D.Strings[59096]="聪明的斗士知道该在什么时候抽身退出。"
D.Strings[59097]="利用敌人的弱点，是制胜要诀。"
D.Strings[59098]="有时即便是精英也会犯错。"
D.Strings[59099]="你还没资格击败我，驯宠师。"
D.Strings[59100]="希望你能从自己的失败中吸取教训。"
D.Strings[59101]="显然，我对你的评价是错误的。"
D.Strings[59102]="你应该感到高兴，因为你差点打败了我其中一只宠物。"
D.Strings[59103]="只是时间问题了。"
D.Strings[59104]="休想打败我。"
D.Strings[59105]="择日再战吧，驯宠师。"
D.Strings[59106]="干得好！恭喜你大获全胜。"
D.Strings[59107]="别低估了我的实力。"
D.Strings[59108]="别妄想我会手下留情，驯宠师。我不会手软。"
D.Strings[59109]="真了不起。太出乎我的意料了。"
D.Strings[59110]="让我们开始表演吧！"
D.Strings[59111]="没人能击败一个意气风发的矮人！"
D.Strings[59112]="哇哦！哇哦！放轻松！你赢了！"
D.Strings[59113]="我还有许多招数没使出来呢！"
D.Strings[59114]="他只是块小卵石……"
D.Strings[59115]="谢谢你。我的宠物变得比以往更加强大了。"
D.Strings[59116]="这般惨死……"
D.Strings[59117]="好好休息，以便尽早整装再战。"
D.Strings[59118]="啊。胜利的味道真甜美。"
D.Strings[59119]="至少我的宠物是英勇战死的。"
D.Strings[59120]="让他们瞧瞧痛苦的真正含义。"
D.Strings[59121]="你从无半点机会，小崽子。"
D.Strings[59122]="怎么？我决不会输！我体内充满了暮光之力！"
D.Strings[59123]="相差甚远。"
D.Strings[59124]="继续屠杀。"
D.Strings[59125]="你个蠢货！"
D.Strings[59126]="我们迎来了对你进行清算的时刻。"
D.Strings[59127]="不要惧怕失败。那是酝酿成功的催化剂。"
D.Strings[59128]="我以为自己赢定了。可造物主显然另有安排。"
D.Strings[59129]="你的时间还未到。"
D.Strings[59130]="只是造物主眼中的微小尘埃。"
D.Strings[59131]="你比我想象中强大。"
D.Strings[59132]="我一直在想，什么时候才能与你对决。"
D.Strings[59133]="湖水告诉我会是这样！"
D.Strings[59134]="我一定是误解了水流的智慧。"
D.Strings[59135]="表面之下，暗流汹涌。"
D.Strings[59136]="被无尽潮水夺去的又一条生命。"
D.Strings[59137]="深渊中的又一座坟墓。"
D.Strings[59138]="等你与金莲教的关系达到崇敬后，你就能帮助至尊天神了。$B$B在东面，玉珑的寺院正在遭受疑之煞的攻击。$B$B在南面，赤精的学徒正在寺院遭到攻击后，进行重建与复训。$B$B在北面，雪怒正在考验那些竞技勇士的力量。$B$B在西面，砮皂正警惕地注视着潘达利亚大陆上最危险的敌人。"
D.Strings[59139]="你可以在自己的主城里使用拍卖行服务。"
D.Strings[59140]="当然！别客气。"
D.Strings[59141]="哇……头晕！"
D.Strings[59142]="感谢风筝女士！"
D.Strings[59143]="他们怯懦的首领就躲在这道屏障后面。你准备好了就告诉我。"
D.Strings[59144]="耶！我喜欢这首歌！"
D.Strings[59145]="那是只很酷的蚱蜢对吧？想要一只属于你自己的吗？"
D.Strings[59146]="我怎样才能成为一名战斗宠物训练师？"
D.Strings[59147]="你得去暴风城，找奥黛丽·伯恩赫普聊聊！城里的任何一名守卫都能为你指路。$b$b在寺院里有传送门，可以将你传送过去。祝你好运！"
D.Strings[59148]="你见过这么多独特的宠物吗？想不想给自己抓几只？"
D.Strings[59149]="吴大师的防御力已经接近极限。使用轮回之触来终结她！"
D.Strings[59150]="你觉得我的宠物猴怎么样？很酷对吧？"
D.Strings[59151]="你这有什么美酒出售吗？"
D.Strings[59152]="我不会容忍毫无必要的暴力！"
D.Strings[59153]="我一直期待能用这战机歼灭强大的目标。让我们开火吧！"
D.Strings[59154]="你应该去奥格瑞玛找瓦佐克聊聊！城里的任何卫兵都能为你指路。$b$b寺院里有通往奥格瑞玛的传送门，可以把你传送过去。祝你好运！"
D.Strings[59155]="你对部落真是深恶痛绝，对吧？"
D.Strings[59156]="<空军上将变得面色凝重。>$b$b我从小在南海镇长大。我的双亲……的遗骸……都被埋在那里。"
D.Strings[59157]="这些熊猫人看起来都是好人。$b$b他们不愿意卷入我们的战争，可在与部落纠缠几个星期之后，相信他们一定会站到我们这边来。"
D.Strings[59158]="我做好战斗准备了！帮我集中精神，卡兹提克。"
D.Strings[59159]="那……那是什么？！"
D.Strings[59160]="熊猫人可没有那么大的气球……是外乡人的吗？"
D.Strings[59161]="那是……那是什么巨型飞鲸吗？"
D.Strings[59162]="炮弹已装填！"
D.Strings[59163]="物有所值。我希望提升自己的力量。<付10,000金币。>"
D.Strings[59164]="物有所值。我希望提升自己的智力。<付10,000金币。>"
D.Strings[59165]="风领主梅尔加拉克察觉到3个以上的盟友丧失了能力，并释放了他们！"
D.Strings[59166]="你可以留在我们的村子里，随便待多久都没问题，陌生人。但……请不要亮出武器。"
D.Strings[59167]="这么多客人……我们的村子出什么事了？"
D.Strings[59168]="坡东村欢迎你，还有你的联盟。"
D.Strings[59169]="我们是来执行和平救援任务——你会帮我们吗？"
D.Strings[59170]="谁？……什么？噢！乌克死了？真是太棒了！干得好英雄们。"
D.Strings[59171]="这杯我请！"
D.Strings[59172]="继续干活！上将决不容许失败。"
D.Strings[59173]="把那些引擎发动起来！马上！"
D.Strings[59174]="再加把劲儿！你们是我所见过最没用的地精！"
D.Strings[59175]="哇哦——你是位来自迷雾之外的$r？这是一个多么疯狂的时代啊！$b$b我只需要在这歇息片刻。长途跋涉真能让你筋疲力尽——上下坡都一样。"
D.Strings[59176]="快点儿！酋长的眼睛在盯着你们呢。"
D.Strings[59177]="噢，可恶。"
D.Strings[59178]="你还好吧？"
D.Strings[59179]="继续擦亮那些炮弹。我要它们亮得能照出人影来！"
D.Strings[59180]="就快了！$b$b在迷雾酒肆里有冰镇美酒等着我呢。我仿佛已经尝到了……"
D.Strings[59181]="继续走，就快到了！$b$b这是我第三次经过隘口了。真希望能用上熟能生巧这个词！$b$b等你抵达顶部之后，你会找到一家很棒的旅店，叫做“迷雾酒肆”。不过你可得把武器贴身放好。那可是个藏龙卧虎的地方。"
D.Strings[59182]="我要这甲板干净到足以入口！"
D.Strings[59183]="小心点！要是我在新船上发现一道划痕，就等着掉脑袋吧！"
D.Strings[59184]="加快节奏，伙计们。我们就快出发了！"
D.Strings[59185]="过来，$n！你的旋翼机可以使用了！"
D.Strings[59186]="好吧，我们回海岸上去。"
D.Strings[59187]="%s朝$n叫着。"
D.Strings[59188]="哈！这地方从来没接待过这么多访客。你想买些炖菜吗，邻居？"
D.Strings[59189]="真是炮火连天啊！现在该收拾残局了。"
D.Strings[59190]="天火号上的那些人都是联盟精英。但有些事情，仍然只有军情七处可以办到。"
D.Strings[59191]="有许多飞行员都被击落在北方，其中一位是我们军情七处的特工。$B$B我们必须帮助他们，但首先得解决这些部落。"
D.Strings[59192]="真是太热闹了！\n\n相信我们的酿酒师明年也会到场竞技吧。"
D.Strings[59193]="我听说指挥官利尔他们找到了安玻！真是个好消息。"
D.Strings[59194]="用碎玉闪电击倒曾大师的助手们。"
D.Strings[59195]="你好，宝贝儿！我已经迫不及待，想要迎接战斗了！"
D.Strings[59196]="难民从高原各地涌向滨岸村。我担心野牛人已经攻破了长城！"
D.Strings[59197]="是不是应该点燃斯普洛德的引线？在第七页上有个污点……"
D.Strings[59198]="毁灭……"
D.Strings[59199]="你欢庆过酿月祭吗？那真是个大饱口福的好机会。我正在为这佳节准备一大批昆莱劲酒。$b$b想来滨岸村加入我吗？"
D.Strings[59200]="你们的软弱攻击不值一提！"
D.Strings[59201]="啊！仇恨将我吞噬！"
D.Strings[59202]="你好，驯宠师！准备战斗！"
D.Strings[59203]="等这一切结束之后，你就要跟鱼人一起游泳了！"
D.Strings[59204]="国王肩上的担子很重，可身为父亲，也是肩负重责。我会不惜一切代价寻找儿子。"
D.Strings[59205]="如果部落非要把我们逼到战争的边缘，那就来吧。$B$B在圣光的庇佑下，我会为自己的王国和人民而战。$B$B荣耀属于联盟！"
D.Strings[59206]="祝你下次好运，旱鸭子！"
D.Strings[59207]="在我船长的日记里又增添了新的胜利篇章！"
D.Strings[59208]="对于旱鸭子来说，算是不错了。"
D.Strings[59209]="打得漂亮！要是你什么时候决定不再玩战斗游戏了，也许可以加入我的队伍！"
D.Strings[59210]="让他们见识下我们的厉害！……嗝儿！"
D.Strings[59211]="没这么快，伙计。这是我的地盘！"
D.Strings[59212]="准备好受死了？"
D.Strings[59213]="再接再厉，伙计们。他们四散奔逃了！"
D.Strings[59214]="全员都到甲板上集合！我们正迅速损兵折将！"
D.Strings[59215]="我的宠物怎么不见了？"
D.Strings[59216]="你会像虫子一样被我碾死！"
D.Strings[59217]="我先成为强大的驯宠师，然后就会成为戈多克大王！"
D.Strings[59218]="我是大王！"
D.Strings[59219]="格鲁克是最棒的！"
D.Strings[59220]="哇哦！你真了不起！"
D.Strings[59221]="你不是食人魔！怎么会赢？"
D.Strings[59222]="谁也别想跟格鲁克捣乱！"
D.Strings[59223]="宠物碎击！你死定了！"
D.Strings[59224]="我们要粉碎你！"
D.Strings[59225]="我现在生气了！"
D.Strings[59226]="愚蠢的小东西杀死了我的小东西。啊啊！"
D.Strings[59227]="你准备好开战了吗？"
D.Strings[59228]="我可没时间陪你，伙计！"
D.Strings[59229]="战斗结束了，宝贝儿。祝你下次好运。"
D.Strings[59230]="一直等到永望镇的同伴们听见这个消息！"
D.Strings[59231]="对菜鸟来说……你可真不赖。"
D.Strings[59232]="是的，是的，你赢了。真了不起。"
D.Strings[59233]="嘿，看那边！"
D.Strings[59234]="任何身价不菲的驯宠师都会有备而来！"
D.Strings[59235]="别担心，我相信下一个会做得更好！"
D.Strings[59236]="熊猫人现在或许还是陌生人，可总有一天，他们会成为最可宝贵的盟友。"
D.Strings[59237]="迸发之恨的死应该摧毁了他的护盾！赶快！"
D.Strings[59238]="<作为无伤者玛里克仅存的遗留物，他的长矛突兀地挂在武器架上。>"
D.Strings[59239]="<思考玛里克的教诲。>"
D.Strings[59240]="又有个陌生人来到村里了……看样子还是个$c。进来吧，但别像那些部落一样，对我们拔剑相向。"
D.Strings[59241]="<玛里克的话语在你脑中回响。>$B$B“英烈长存。”"
D.Strings[59242]="我因力量而战栗！我是天启的孤单破坏者！"
D.Strings[59243]="准备迎接末日吧。"
D.Strings[59244]="你在这里不会找到丝毫慰藉。"
D.Strings[59245]="哇哦……这些联盟可真会使唤人……"
D.Strings[59246]="这里的工作条件太糟糕了！我们已经几个小时没有坐下来喝喝酒了！"
D.Strings[59247]="那些该死的家伙再一次展示了自己的优越性。"
D.Strings[59248]="<他擦了擦额头上的汗水。>$b$b你好啊，$c。你是来帮忙的？"
D.Strings[59249]="<她擦了擦额头上的汗水。>$b$b你好啊，$c。你是来帮忙的？"
D.Strings[59250]="你是来让我休息的吗？我好像已经连续工作几辈子了！"
D.Strings[59251]="我以为我们只是要造一座房子，而不是堡垒。"
D.Strings[59252]="我的痛苦还在继续。"
D.Strings[59253]="我从小到大都没这么玩命工作过！我不喜欢这样！"
D.Strings[59254]="不！你休想打败我！"
D.Strings[59255]="这些家伙怎么有这么多武器？"
D.Strings[59256]="生死有命。"
D.Strings[59257]="别急。我跟你还没完呢。"
D.Strings[59258]="你现在可以回家了。我来掩护你。"
D.Strings[59259]="我还没完呢。"
D.Strings[59260]="你真以为死亡能阻止得了我吗？我就是死亡的化身！"
D.Strings[59261]="来吧，面对血骑士的完美战术吧！"
D.Strings[59262]="挑战我真是个错误。"
D.Strings[59263]="没人能抵挡血骑士的猛攻。"
D.Strings[59264]="你是个强大的对手。"
D.Strings[59265]="看来要换个策略了。"
D.Strings[59266]="真正的斗士决不会鲁莽应战。"
D.Strings[59267]="让我们继续杀戮吧。"
D.Strings[59268]="你必将败亡！"
D.Strings[59269]="胜利的天平倾向了你那一边，驯宠师。"
D.Strings[59270]="圣光在上，我要打败你！"
D.Strings[59271]="赞美圣光！"
D.Strings[59272]="与你交战，令我倍感荣幸。"
D.Strings[59273]="其他驯宠师对你的评价真是精确。"
D.Strings[59274]="干得好，驯宠师。"
D.Strings[59275]="换走！"
D.Strings[59276]="每个士兵都很重要。"
D.Strings[59277]="我的胜利近在咫尺。"
D.Strings[59278]="在切割者里卡尔积聚力量时拖住扎尼提克！"
D.Strings[59279]="为了联盟的荣耀！"
D.Strings[59280]="我们会战斗到最后一刻！"
D.Strings[59281]="我的力量回来了。在我向卡拉克西报告之前与我交谈，唤醒者。"
D.Strings[59282]="希望这是一场光荣的战斗。"
D.Strings[59283]="愿你的宠物已经做好了战斗的准备。"
D.Strings[59284]="今天我将是胜者。"
D.Strings[59285]="感谢你为我提供了展示技能的机会。"
D.Strings[59286]="恭喜你，驯宠师！"
D.Strings[59287]="干得好，驯宠师！"
D.Strings[59288]="又有一只宠物加入了战斗。"
D.Strings[59289]="我不会让你打败我的。"
D.Strings[59290]="胜利的天平倾向我了。"
D.Strings[59291]="今天，胜利属于我。"
D.Strings[59292]="我会为你的失败而哀悼。"
D.Strings[59293]="这真是太不幸了。"
D.Strings[59294]="你做好准备了吗？"
D.Strings[59295]="莫鲁克赢了！"
D.Strings[59296]="没人能打败我！"
D.Strings[59297]="你真难对付！"
D.Strings[59298]="你被骗了！"
D.Strings[59299]="别这样！我会输的！"
D.Strings[59300]="呃——噢……"
D.Strings[59301]="你以为自己有机会？我可不这么想！"
D.Strings[59302]="救命！救命！这儿有部落！"
D.Strings[59303]="守卫！这儿有部落！"
D.Strings[59304]="部落来了！在我们的基地里！"
D.Strings[59305]="守卫！这边！"
D.Strings[59306]="你一定会后悔与我交手的，我保证！"
D.Strings[59307]="真是一场大捷！"
D.Strings[59308]="我的宠物是不是太难对付了，驯宠师？"
D.Strings[59309]="哇哦，你可真强！"
D.Strings[59310]="真令人失望……"
D.Strings[59311]="当庄稼陷入危险时，勤恳的农夫从不会放弃希望。"
D.Strings[59312]="干得不错，可那还远远不够！"
D.Strings[59313]="出什么问题了，连个淳朴农夫的宠物都解决不了吗？"
D.Strings[59314]="你得再加把劲才能打败我。"
D.Strings[59315]="我想我该回家了。"
D.Strings[59316]="你是对的。我可没签过什么建造战争基地的合约。"
D.Strings[59317]="谢天谢地！"
D.Strings[59318]="谢谢！我要离开了！"
D.Strings[59319]="你……你不是联盟的成员？很好。"
D.Strings[59320]="我想马上回家去。"
D.Strings[59321]="你真是志在必得啊，对吧？"
D.Strings[59322]="我们当时正在地穴里调查邪煞的腐化情况……然后一切都变得很不对劲。我们的领袖金·铁拳被邪煞控制了，开始大开杀戒。即便是现在，他还在那里加害无辜。"
D.Strings[59323]="做好准备，驯宠师。我是为胜利而来。"
D.Strings[59324]="你吓不倒我的，驯宠师。"
D.Strings[59325]="是邪煞夺去了金的生命——不要为他的死而责怪自己。你的努力令我望尘莫及。"
D.Strings[59326]="等你准备充分再回来吧。"
D.Strings[59327]="也许我们下一次交手时，你会交好运。"
D.Strings[59328]="你的一招一式犹如大师级驯宠师。干得好。"
D.Strings[59329]="你现在可以回去与家人团聚了。"
D.Strings[59330]="很了不起，驯宠师。"
D.Strings[59331]="我不会让你得逞。"
D.Strings[59332]="你休想轻易打败我。"
D.Strings[59333]="在战斗中击败对手，是对战术最好的检验。"
D.Strings[59334]="看来我的战略无人能及。"
D.Strings[59335]="如果胜局已定，就不必惧怕区区一场战斗的失败。"
D.Strings[59336]="我明白了。你我想象中要强大得多。"
D.Strings[59337]="我经历过你们无法想象的恐惧。击败你们就是小菜一碟。"
D.Strings[59338]="我片刻也没怀疑过自己的胜利。"
D.Strings[59339]="我不会容忍这个！"
D.Strings[59340]="我严重低估了你的实力。"
D.Strings[59341]="你得再加把劲，才能击败我。"
D.Strings[59342]="你半点机会都没有。我会打败你！"
D.Strings[59343]="够了吗？"
D.Strings[59344]="你根本不是我的对手。"
D.Strings[59345]="你真走运。"
D.Strings[59346]="不胡闹了。我要粉碎你！"
D.Strings[59347]="你的胜利到此为止，驯宠师。"
D.Strings[59348]="很少有人能在与我交战时维持平衡。让我们瞧瞧你是否与众不同。"
D.Strings[59349]="如我所料。你还没本事打败我。"
D.Strings[59350]="别担心。你只是我的手下败将之一。"
D.Strings[59351]="真是战技卓绝啊！"
D.Strings[59352]="你的胜利受之无愧，驯宠师。"
D.Strings[59353]="离结束还早着呢。"
D.Strings[59354]="山谷赋予我力量。"
D.Strings[59355]="要是你这么想逃跑，那就请便。"
D.Strings[59356]="也许你确实有些实力。"
D.Strings[59357]="干得好。可你有决心继续下去吗？"
D.Strings[59358]="我们终于要面对面交手了。"
D.Strings[59359]="我已经预见到了自己的胜利。"
D.Strings[59360]="如同落网之鱼！"
D.Strings[59361]="你真是位了不起的驯宠师！"
D.Strings[59362]="光靠蛮力可击败不了我。"
D.Strings[59363]="愿水流给我指引。"
D.Strings[59364]="我们会在你做出反应前将你粉碎。"
D.Strings[59365]="我的宠物们又夺取了一条性命。"
D.Strings[59366]="像那样的还多得是呢！"
D.Strings[59367]="情况有些不妙……"
D.Strings[59368]="我会打败你。"
D.Strings[59369]="真正的大师已经告捷。"
D.Strings[59370]="一切都在我的计划之内。"
D.Strings[59371]="我已经败给了你的战技。"
D.Strings[59372]="我想不明白。我怎么会输？"
D.Strings[59373]="休息一下，好让战局继续朝有利于我们的方向发展。"
D.Strings[59374]="你无法击败这片土地上的流沙。"
D.Strings[59375]="被黄沙掩埋的又一具枯骨。"
D.Strings[59376]="胜利的天平再一次倾向了我。"
D.Strings[59377]="真是令人大失所望。"
D.Strings[59378]="也许这场战斗并不像我想的那么容易……"
D.Strings[59379]="去吧，艾美拉达！让他们明白自己的愚蠢！"
D.Strings[59380]="去干掉他们，毒牙！"
D.Strings[59381]="干掉他们，死神800型！"
D.Strings[59382]="你能办到，毛尾巴！"
D.Strings[59383]="杀死他们，黑牙。"
D.Strings[59384]="送他们下地狱，小黑贼！"
D.Strings[59385]="长钉，让他们瞧瞧你的厉害！"
D.Strings[59386]="撕碎他们，裂肉豹！"
D.Strings[59387]="该你了，钳子先生！"
D.Strings[59388]="酒仙布兰琪可能在雷掌台上。她确信一场风暴即将来袭，所以我得确保她的设备都已准备就绪。$b$b我无法想象，自己有朝一日能具备她五成的酿酒功力——她曾经将春风封存在了一只酒桶里。一年过后，当他们在青龙寺将桶塞拔出时，你仍能闻到那股芳香！"
D.Strings[59389]="让他们尝尝苦头，蟒蛇。"
D.Strings[59390]="石皮，让他们瞧瞧你的力量！"
D.Strings[59391]="拉斯普，开火！"
D.Strings[59392]="柳枝龙，该你翱翔了！"
D.Strings[59393]="没人能打败咯咯鸡！"
D.Strings[59394]="来吧烈焰，让我们烧焦他们！"
D.Strings[59395]="面对奥卓姆斯的愤怒吧！"
D.Strings[59396]="虫蜥，给他们上一课。"
D.Strings[59397]="眩光，击倒他们！"
D.Strings[59398]="也许142号要比141号成功得多。"
D.Strings[59399]="瘟疫使者，让他们见识下瘟疫的力量！"
D.Strings[59400]="面对欧比斯东的怒火吧！"
D.Strings[59401]="出来吧，鸣蟾！"
D.Strings[59402]="伊格尼斯，替我烧死他们，没问题吧？"
D.Strings[59403]="干掉他们，夜行者。"
D.Strings[59404]="歌利亚已启动。"
D.Strings[59405]="你能做到的，冯戈！"
D.Strings[59406]="斯多皮，让这位驯宠师看看你的本事！"
D.Strings[59407]="嚼嚼，该你展示自己的力量了。"
D.Strings[59408]="阿卡努斯，让他们见识下我们无尽的力量！"
D.Strings[59409]="我看好你，哥培尔！"
D.Strings[59410]="斯蒂奇，你愿不愿意让我们这位准驯宠师瞧瞧，我们是如何战斗的？"
D.Strings[59411]="卓戈，消灭他们！"
D.Strings[59412]="撕肉者现在要将你杀死。"
D.Strings[59413]="灰毛，铁炉堡的骄傲，前来应战吧！"
D.Strings[59414]="铁壁龟，请来战场上加入我们。"
D.Strings[59415]="针背龟要打扁你！"
D.Strings[59416]="没人能击败你，崩牙者！"
D.Strings[59417]="咩咩，来面对这位敌人吧。"
D.Strings[59418]="来战斗吧，碎石蟹。"
D.Strings[59419]="鞭风者，击溃这些敌人。"
D.Strings[59420]="将他们撕成碎片，脆脆！"
D.Strings[59421]="我召唤你，卡利。"
D.Strings[59422]="让他们灰飞烟灭，阿米瑟尔。消灭他们！"
D.Strings[59423]="你在匹兹的力量面前毫无机会。"
D.Strings[59424]="掠影者，我的老朋友，该你出战了。"
D.Strings[59425]="%s消退了。"
D.Strings[59426]="%s被耗竭了。"
D.Strings[59427]="来吧，再试一次！"
D.Strings[59428]="<刀刃在你前方的空中盘旋。>"
D.Strings[59429]="你是一位猎人？我能快速帮你解决野兽的难题！"
D.Strings[59430]="你需要别人帮你照看宠物？我保证会多加考虑，争取别吃掉它们。"
D.Strings[59431]="嗨，头儿，情况如何？"
D.Strings[59432]="放、开、我。卡拉克西在召唤。"
D.Strings[59433]="孵化的时间快到了。我必须回应虫群的召唤。"
D.Strings[59434]="不。你休想把我关进这该死的牢笼。"
D.Strings[59435]="她再也不是风暴烈酒大妈了！"
D.Strings[59436]="|TInterface\\Icons\\inv_weapon_shortblade_37.blp:32|t猛攻$b$b|TInterface\\Icons\\inv_weapon_shortblade_92.blp:32|t强攻$b$b|TInterface\\Icons\\ability_rogue_shadowstrikes.blp:32|t狂攻"
D.Strings[59437]="如果你想将战火引到我们的海岸，那么这片土地会对你的冲动和暴力作出回应。我不知道最终会造成什么后果——没人知道。"
D.Strings[59438]="装填炮弹！"
D.Strings[59439]="把那怪物从天上炸下来！"
D.Strings[59440]="控制住火势！"
D.Strings[59441]="$n给饥肠辘辘的人们准备了一些剩菜剩饭。"
D.Strings[59442]="|TInterface\\Icons\\trade_archaeology_delicatemusicbox.blp:20|t皇家宰相佐尔洛克吟唱了|cFFFF0000|Hspell:123791|h[女皇赞歌]|h|r！"
D.Strings[59443]="够了！清点伤亡。那是什么……联盟的据点！他们认为已经占领这片土地了？有我在，休想！"
D.Strings[59444]="快把引擎修好，否则我们就死在天上了。全力攻击那个联盟基地！"
D.Strings[59445]="对极了。让他们尝尝地狱咆哮的怒火！"
D.Strings[59446]="那一下是为陶拉祖报仇！"
D.Strings[59447]="哈哈哈！杀死一切喘气儿的东西！"
D.Strings[59448]="联盟狗在这片土地上没有立足之地。"
D.Strings[59449]="瞄准射击！把他们赶回暴风城！"
D.Strings[59450]="我们已经挫了他们的锐气。在部落的力量面前，他们抱头鼠窜。绝不留情！"
D.Strings[59451]="他们懦弱的领袖就藏在这道屏障后面。我的工兵去哪儿了？"
D.Strings[59452]="点击武僧以击退他们。"
D.Strings[59453]="再给我一个面具，肯肯。"
D.Strings[59454]="我把“探路棍”弄丢了。"
D.Strings[59455]="谢谢你，陌生人。我……从没有过那样的感觉。"
D.Strings[59456]="人生突然变得充满光明。$B$B虽然我还是喜欢睡觉。"
D.Strings[59457]="再次感谢你的帮助。我会暂时留在这里，帮忙照料伤患。$B$B然后我会向北行进……"
D.Strings[59458]="送我回到现在。"
D.Strings[59459]="当你准备好回到现在时，再开口发问。"
D.Strings[59460]="我准备好帮你寻找武器了。"
D.Strings[59461]="我……我弄丢了面具。需要一个新的。"
D.Strings[59462]="$n引爆了风爆弹！"
D.Strings[59463]="你听说林找到隐秘大师了吗？他在抱拳林。"
D.Strings[59464]="她找到了？他在抱拳林？$b$b看来我得走一趟了。也许……等我再吃几口……"
D.Strings[59465]="林找到隐秘大师了？那我们的训练可以继续了！$b$b现在就还剩下一件事。肯肯得先帮助那些悲伤的家伙。这里有太多哀苦的人了。"
D.Strings[59466]="真令人难以置信！我以为隐秘大师一定会在荒野里。$b$b你说在抱拳林？我很快就会去找林，然后我们就能继续训练了。至于目前嘛，我已经找到属于自己的冒险了。"
D.Strings[59467]="果然，我就知道她能办到。她尽管羞涩，但却强大得很。$b$b我得先干完这里的事。然后就去找她。"
D.Strings[59468]="（已通过启用卡拉克西共鸣，在英雄难度下击败了某位首领。该效果不能被取消。）"
D.Strings[59469]="（已通过启用净化仪式，在英雄难度下击败了某位首领。该效果不能被取消。）"
D.Strings[59470]="我准备好帮你处理那些杂事了。"
D.Strings[59471]="在这里发生的事情将永远改变这片土地。"
D.Strings[59472]="我可以适应这种生活的。"
D.Strings[59473]="我感觉谈判进行得并不顺利……"
D.Strings[59474]="嘿，菜鸟！你想来打一场吗？"
D.Strings[59475]="是的，我要报名！"
D.Strings[59476]="胜利者是：$n！"
D.Strings[59477]="哎哟……抱歉，$n。请回去重新排队，再试一次。"
D.Strings[59478]="现在上场的是——1级$r$c，$n！$n是一位新人，所以请不要紧张！"
D.Strings[59479]="你是来报名参战的吗？"
D.Strings[59480]="很好很好！$n获胜！看来我要欠某人一些钱了。"
D.Strings[59481]="祝贺你，$n！请不要在场外留下血脚印。"
D.Strings[59482]="官方消息！$n活下来了。能活下来就不容易啊，$n！"
D.Strings[59483]="呃……真是一团糟。找个牧师之类的来好吗？！"
D.Strings[59484]="这个……下场可不怎么样。"
D.Strings[59485]="$n，$n，$n。拜托你下回别再死那么多次了。"
D.Strings[59486]="我可以替换已经种下去的作物吗？"
D.Strings[59487]="当然可以！我从一大堆农具里找到了我爷爷的铲子。$B$B你可以用它来挖掉生长中的作物，清理出田地来种别的东西。"
D.Strings[59488]="$n代表奥格瑞玛出战！"
D.Strings[59489]="$n代表暗矛巨魔出战！"
D.Strings[59490]="$n代表雷霆崖出战！"
D.Strings[59491]="$n代表幽暗城出战！"
D.Strings[59492]="$n代表银月城出战！"
D.Strings[59493]="$n代表锈水财阀出战！"
D.Strings[59494]="$n代表火金派熊猫人出战！"
D.Strings[59495]="这是$n的首战！"
D.Strings[59496]="这是$n今天的首战！"
D.Strings[59497]="同时进场的还有布鲁斯，它是我们特意找来的一条巨鳄！"
D.Strings[59498]="来自黑石山深处的火焰大师，萨诺里亚克！"
D.Strings[59499]="同时进场的还有来自泰罗卡森林的驭风鸦人，奇拉瓦克！"
D.Strings[59500]="保护营地，抵抗入侵。"
D.Strings[59501]="入侵警报！"
D.Strings[59502]="站住。你无权进入此地。"
D.Strings[59503]="发现入侵者。准备接战。"
D.Strings[59504]="激活毁灭协议。"
D.Strings[59505]="启动武器系统。"
D.Strings[59506]="下一个就是你了！除非有人插队。"
D.Strings[59507]="看来你排在第三，$c。"
D.Strings[59508]="你现在是第四位，$r。"
D.Strings[59509]="你排在第五个。应该很快就会轮到你的。"
D.Strings[59510]="你排在第六个。"
D.Strings[59511]="你排在第七个。"
D.Strings[59512]="你是第八个，$r。"
D.Strings[59513]="你是第九个。"
D.Strings[59514]="你是第十个。"
D.Strings[59515]="今天人很多。你前面至少还有十个人。不过你应该不用等很久。"
D.Strings[59516]="你前面至少还有十五个人。这很难说——现在人有点儿多。"
D.Strings[59517]="等着吧——你前面至少还有二十个人。没准还不止。"
D.Strings[59518]="我想你应该是第三十个？也许是第四十个？我刚才数糊涂了。"
D.Strings[59519]="你前面至少还有五十个人。这儿人太多了。如果你想在接下来的一到两个小时内打上的话，最好还是先等大家的热情稍微冷却一点后再来。"
D.Strings[59520]="我前面还有多少人？"
D.Strings[59521]="现在进场的是一位后起之秀——2级$c，$n！"
D.Strings[59522]="请大家鼓掌欢迎——$n！$n是一位3级$c。"
D.Strings[59523]="下面是我们的挑战者。今天，我们迎来了一位4级$r$c，$n！"
D.Strings[59524]="现在进场的是一位非常有天分的$c。大家一起欢迎5级拳手$n！"
D.Strings[59525]="看呐……现在走来的是极度危险的6级$r，$n！"
D.Strings[59526]="宠物对战！尽在荣耀斗兽场！"
D.Strings[59527]="驯宠师们！你们的宠物能击败马戏团的顶尖高手吗？"
D.Strings[59528]="所有驯宠师们的挑战！你敢来我的宠物对战吗？你能把它们全部打败吗？"
D.Strings[59529]="考验你的宠物，挑战顶尖高手！"
D.Strings[59530]="想要挑战顶尖高手吗？$B$B你会像别人一样铩羽而归吗？$B$B验证的办法只有一个。你敢来试试吗，$g先生:女士;？$B$B一个代币就能玩一局……"
D.Strings[59531]="那就开始吧。"
D.Strings[59532]="祝你在马戏团玩得愉快。或者你还想再来一局……？"
D.Strings[59533]="干得好，干得好。"
D.Strings[59534]="我们不如试试别的……？"
D.Strings[59535]="它们毕竟是马戏团的精英嘛。"
D.Strings[59536]="唉！真没意思。"
D.Strings[59537]="我想和你进行宠物对战！|cFF0008E8(暗月游戏代币)|r"
D.Strings[59538]="船要爆炸啦。快到上层甲板上去，用绳索逃生！"
D.Strings[59539]="这是一片生机盎然的丛林，$c。鸟儿在树冠间啁啾，野兽在树下的阴影中咆哮。$b$b而我们这些猎手，则要控制它们的数量。这是我们使命——我们的责任。"
D.Strings[59540]="我们想与远古血冠鹤战斗。"
D.Strings[59541]="我们想与卡桑利老年虎战斗。"
D.Strings[59542]="我们想与巨型钳爪蟹战斗。"
D.Strings[59543]="我能向你买个陷阱吗？"
D.Strings[59544]="$n捕获了一只远古血冠鹤！"
D.Strings[59545]="$n捕获了一只卡桑利老年虎！"
D.Strings[59546]="$n捕获了一只巨型钳爪蟹！"
D.Strings[59547]="干涉者Mk.3R-Alpha型准备进行战斗测试。"
D.Strings[59548]="干涉者Mk.3R-Alpha型正在初始化垂直干涉光束。"
D.Strings[59549]="运行状态：正常。"
D.Strings[59550]="激活三元干涉者Alpha。"
D.Strings[59551]="激活三元干涉者Beta。"
D.Strings[59552]="激活二元干涉者Alpha。"
D.Strings[59553]="激活二元干涉者Beta。"
D.Strings[59554]="激活五元干涉者Omega。"
D.Strings[59555]="不不不！把它们全打开！把它们全打开！"
D.Strings[59556]="干涉者Mk.3R-Alpha型正在关闭，建议重校战斗测试。"
D.Strings[59557]="干涉者Mk.3R-Alpha型正在关闭。战斗测试：成功。"
D.Strings[59558]="很好。你们要小心仙鹤的鸣叫声……它会让你们无法专心战斗。"
D.Strings[59559]="我只有一个忠告：跟紧她。"
D.Strings[59560]="干扰力场校正成功，进程终止。"
D.Strings[59561]="千万别让螃蟹静立不动。它的甲壳历久弥坚，但它的关节却很脆弱。"
D.Strings[59562]="外边出什么事了？"
D.Strings[59563]="守护之眼保护兹恩沙尔不受任何伤害！"
D.Strings[59564]="兹恩沙尔衰弱了！"
D.Strings[59565]="你孤身一人是无法战胜这头野兽的，$n。去召集一些盟友来吧。等你确信自己做好准备后，我就打开兽笼。"
D.Strings[59566]="炮台无法运转，更新测试参数。"
D.Strings[59567]="为了地狱咆哮的荣耀！"
D.Strings[59568]="你竟敢挑战库卡隆！"
D.Strings[59569]="联盟的渣滓！"
D.Strings[59570]="一个$c？！我恨$c！<但他们很美味。>"
D.Strings[59571]="总算可以热热身了！<联盟的小家伙！>"
D.Strings[59572]="为我报仇……达克！<不，你得为我报仇……奥！>"
D.Strings[59573]="我……恨死……$r啦！<该跑的……我们该跑的！>"
D.Strings[59574]="收集“纯化”燃料。"
D.Strings[59575]="收集木材。"
D.Strings[59576]="采集铁矿。"
D.Strings[59577]="该死的……"
D.Strings[59578]="在这里狩猎可带劲儿了。鸟儿在树冠间啁啾，野兽在树下的阴影中咆哮。$b$b而我们则要控制它们的数量。$b$b这是我们身为猎手使命——而且也是一项很棒的运动。"
D.Strings[59579]="波尔，你的死亡射线可没广告上吹的那么好用！"
D.Strings[59580]="如果我们能活下来，记得提醒我找个靠得住的搭档！"
D.Strings[59581]="我来掩护，你去干掉他们！"
D.Strings[59582]="剩下的就交给你了，马克西，我跟着你呢！"
D.Strings[59583]="欢迎来到丛林，$n。"
D.Strings[59584]="计时器调整……开始！"
D.Strings[59585]="我要把你那张臭脸拿去GG工程公司当拖把用！"
D.Strings[59586]="都是我队友的错……"
D.Strings[59587]="小心仙鹤的啼鸣声，伙计。它会让你无法专心战斗的。"
D.Strings[59588]="想听听我的建议吗？跟紧她。"
D.Strings[59589]="让那只螃蟹动起来，伙计。它的甲壳虽然久经风霜，可它的关节是很脆弱的。"
D.Strings[59590]="你可不能和这只野兽单打独斗，$n。去召集些朋友来。等你确信自己准备好之后，我就打开兽笼。"
D.Strings[59591]="有时我是如此紧张，但我不能加速时间……"
D.Strings[59592]="我们都需要忍耐。"
D.Strings[59593]="我无意玩这游戏，只因我需要你。"
D.Strings[59594]="我坐在这瀑布边，只因我宁愿孤独。"
D.Strings[59595]="我说，女人，慢慢来，一切都会好起来……"
D.Strings[59596]="你我必须为它而忍耐。"
D.Strings[59597]="在我动摇的瞬间，你令我放宽心情。"
D.Strings[59598]="进攻的时刻即将到来！"
D.Strings[59599]="你相信吗？这儿的人居然免费发放食物！这地方真是太棒了！"
D.Strings[59600]="怎么了，$r？"
D.Strings[59601]="我的小队已经准备就绪，$r。$b$b我们已经开发出了一种可以有效打击你的部落敌人的武器。"
D.Strings[59602]="锦鱼人，瓦里安·乌瑞恩国王有令，我们必须准备好防御工事。"
D.Strings[59603]="好吧！看来我们得呼叫空中支援了。"
D.Strings[59604]="歼灭者？没有侏儒技术搞不定的东西。呼叫直升机！"
D.Strings[59605]="唔。这些歼灭者在火箭弹面前有着致命的弱点。呼叫直升机！"
D.Strings[59606]="兽人很危险，而上了坐骑的兽人更危险。放狗！"
D.Strings[59607]="被囚禁的狼？我们要“解救”这些可怜的动物。"
D.Strings[59608]="你瞧，我一直想造一条机械狗。我们应该好好研究下这些狼。"
D.Strings[59609]="啊！我正好可以趁机测试一下我的Mk V型掘地机器人！抓紧了！"
D.Strings[59610]="该把你送进要塞去了。抓紧了！"
D.Strings[59611]="该测试一下我最新的“飞速掘地翼”升级版了！抓紧！"
D.Strings[59612]="全体上坐骑！我们有任务了！"
D.Strings[59613]="噢！我很抱歉。"
D.Strings[59614]="唔。遥测功能好像关闭了。"
D.Strings[59615]="提醒自己：造一个示波器。"
D.Strings[59616]="那是不是一堵墙？听上去像。"
D.Strings[59617]="如果我能看见就好了。"
D.Strings[59618]="我投降。这是一场光荣的战斗，朋友。"
D.Strings[59619]="我的武器必须保持锋利——燃烧军团的威胁时刻存在。"
D.Strings[59620]="怎么了，小鱼苗？你的鳞片折断了？继续前进！"
D.Strings[59621]="你们这些小鱼快点干完，然后就能去畅游一番了。听起来不错吧？"
D.Strings[59622]="法兰的死激怒了%s。"
D.Strings[59623]="放松点。这些东西可不能扔得太早……"
D.Strings[59624]="把锤子挥起来，你们这些没骨头的家伙！"
D.Strings[59625]="最好能快点！我们可不想等战斗开始后还呆在这儿。"
D.Strings[59626]="发现这些碎片中能量使我看到了走出困境，重获新生的希望。$B$B噢，而且我也被开除了。"
D.Strings[59627]="远离魔法的这四个月感觉好极了。$B$B有了这些新鲜水果和热气腾腾的茶，谁还在乎魔法的无穷奥秘呢？"
D.Strings[59628]="这些熊猫人酿的烈酒棒极了，可他们都没听说过我最喜欢的那种饮料。$B$B或许我以后可以教教他们……"
D.Strings[59629]="-嗅- 哇！这件旧长袍都有点发臭了。$B$B或许我今晚可以溜到那个池塘里洗个澡……"
D.Strings[59630]="我能用这些碎片打开什么样的传送门呢？"
D.Strings[59631]="地精炸弹。它们有一个最大的弱点：其他炸弹。我稍后回来。"
D.Strings[59632]="又是地精炸弹？我昨天好像才搞定一堆地精炸弹。在这儿等我一会儿。"
D.Strings[59633]="地精显然很爱炸弹。我们继续前进，让他们看看侏儒是怎么造炸弹的吧。我稍后回来。"
D.Strings[59634]="一座通往部落或联盟主城的一次性小型传送门。$B$B它们都是一起被冲下来的，所以我也不知道哪个碎片能够通向哪里。我最多只能分辨出它们是来自于夺日者的传送门，还是银色盟约的传送门。这两边都喜欢在自己的传送门魔法中加入一点自己的特色——典型的恶趣味。$B$B我可以卖给你相应阵营的碎片，而你得在它们稳定下来之后自己分辨它们通向哪里。"
D.Strings[59635]="听起来不错。"
D.Strings[59636]="我想买一些传送门碎片。"
D.Strings[59637]="谢谢你，英雄。你给了第二次生命。"
D.Strings[59638]="魔古族的力量真是令人震惊。"
D.Strings[59639]="如果援军早点赶来，我们或许还有胜利的希望。"
D.Strings[59640]="魔古族的巫术和我们之前所见过的完全不同。"
D.Strings[59641]="我亲眼看着魔古族如何折磨我的朋友。多亏了你，我才逃过一劫。"
D.Strings[59642]="他们就像我们碾死蚂蚁一样横扫了我们。这些魔古族的力量简直恐怖！"
D.Strings[59643]="欢迎欢迎！我是工匠大师欧沃斯巴克，当代侏儒工程学的总工程师。$b$b我们的装配工段正在努力组装各种神奇机械，保护你免遭刀戳、剑劈、爆炸或被放逐出物质领域之害。$b$b好吧，就算出故障，至少不是敌人干的。"
D.Strings[59644]="这座堡垒会比加尔鲁什尔前哨站更难攻破。但它们迟早会被攻破的。部落必将败落。"
D.Strings[59645]="是部落！"
D.Strings[59646]="部落来啦！部落来啦！"
D.Strings[59647]="救命啊——"
D.Strings[59648]="我还没见过吉安娜女士呢……"
D.Strings[59649]="我干嘛要离开闪金镇啊？！"
D.Strings[59650]="有种你别跑！"
D.Strings[59651]="这是陷阱！"
D.Strings[59652]="干得好，队员们。解散！"
D.Strings[59653]="尝尝我的利刃吧！"
D.Strings[59654]="准备好开始了吗？"
D.Strings[59655]="我准备好了。出发。"
D.Strings[59656]="很好，你来了。在把这个地精扔进海里前，我总算能离开这儿了。"
D.Strings[59657]="这是你的逃生设备。"
D.Strings[59658]="要不是一位熊猫人织雾者在战后为我疗伤，我早就死在翡翠林了。$b$b这些熊猫人都是好人，我们应该保护他们免遭联盟奴役。"
D.Strings[59659]="欢迎参战，孩子。"
D.Strings[59660]="别担心，我马上就治好你！"
D.Strings[59661]="只是断了几根骨头外加内出血而已。没有冰袋治不好的伤！"
D.Strings[59662]="嘘，这个伤员需要休息。"
D.Strings[59663]="这个伤员的情况很糟糕。"
D.Strings[59664]="我的风绒绷带哪儿去了？"
D.Strings[59665]="你看到这畜生的体格了吗？我们要将近六个人才能制得住他。"
D.Strings[59666]="这些魔古族的野人力气大得惊人。"
D.Strings[59667]="按照酋长的指示，我们得揭开魔古族的所有秘密。"
D.Strings[59668]="我会运用手里的一些资源来找出魔古族的力量之源。"
D.Strings[59669]="我按照加尔鲁什的要求，带着我的人来到这里。我完全没意识到，我们是被当做弃子利用了。"
D.Strings[59670]="证明实力和盲目涉险完全是两码事。而加尔鲁什给我们的任务就属于后者，对此我无法接受。"
D.Strings[59671]="难道我们的忠诚还不算久经考验？我们的酋长口中，全是谎言和借口。"
D.Strings[59672]="加尔鲁什总把荣耀和力量挂在嘴上，可实际上我们的领袖眼里只有胜王败寇那一套。"
D.Strings[59673]="我的部队不需要懦夫。最近，我一直在质疑血精灵的勇气，和忠诚。"
D.Strings[59674]="潘达利亚，是属于部落的应许之地。我们必须得到它，要是谁想螳臂当车，无论是魔古族还是联盟，都将被我们踩在脚下。"
D.Strings[59675]="我本以为你的血精灵们能够自己搞定的，看来我想错了。"
D.Strings[59676]="你们的软弱可不是我的错，摄政王。在我的部落里，只有强者才能立足。"
D.Strings[59677]="没错，有了你们的帮助，我们将解开这片土地的秘密。为了部落的荣耀！"
D.Strings[59678]="如果我必须为此付出一些精灵的鲜血，那也未尝不可。"
D.Strings[59679]="你太胆小了，摄政王。要在这乱世中立足，我们就必须付出鲜血的代价。"
D.Strings[59680]="你完全没有提醒我们魔古族的存在，酋长。这些雕像突然变活了！"
D.Strings[59681]="如果事先得到消息，我们就能有所准备。你这是送羊入虎口。"
D.Strings[59682]="不要质疑我的忠诚，酋长。我们可是远渡重洋来为你作战。"
D.Strings[59683]="小心，加尔鲁什。你的“美好未来”恐怕会摧毁部落。"
D.Strings[59684]="我绝不会再坐视我的人民白白流血。如果你愿意的话，就让你的人去送死好了，但你别想拿我的人当炮灰。"
D.Strings[59685]="你们都上山，我们检查一下其他入口。"
D.Strings[59686]="我，就是伟大的篡夺者——位元毁灭者！如你所见，我已经发现了你们的秘密计划！"
D.Strings[59687]="蠢货！你们却还以为它们深藏在奥丹姆的沙砾之下……"
D.Strings[59688]="现在，咽下这傲慢的苦果吧！"
D.Strings[59689]="啊哈哈哈哈！"
D.Strings[59690]="我的……伟大造物！你们怎么敢这么做？"
D.Strings[59691]="拧紧阀门。"
D.Strings[59692]="滚出来，联盟的渣滓！"
D.Strings[59693]="滚出这里，否则这些工人就要遭殃了！"
D.Strings[59694]="我们要把你们这些蠢货统统赶出这片土地！"
D.Strings[59695]="联盟渣滓在这片丛林里呆不长了！"
D.Strings[59696]="轮到你了，去死吧！"
D.Strings[59697]="来吧，孩子们，享用他们的血肉吧！"
D.Strings[59698]="你竟敢打扰蜥蜴人的孵化仪式？这是死罪！"
D.Strings[59699]="呃，我的背！你会付出代价的！"
D.Strings[59700]="锦鱼人建筑营地遭到攻击！"
D.Strings[59701]="使用守护之光阻止黑暗召唤师的爪牙！"
D.Strings[59702]="英雄，你必须击败黑暗召唤师的爪牙才能削弱他的防护魔法。在此之前，他是免疫伤害的。"
D.Strings[59703]="黑暗召唤师将暂时衰弱，你的机会来了！"
D.Strings[59704]="黑暗召唤师重新激活了防护魔法。"
D.Strings[59705]="暗生蜥蜴领主在召唤援军！"
D.Strings[59706]="暗生蜥蜴领主准备施放激水喷涌！"
D.Strings[59707]="%s雇用了一名法师！"
D.Strings[59708]="%s雇用了一名圣骑士！"
D.Strings[59709]="%s雇用了一名牧师！"
D.Strings[59710]="%s雇用了一名德鲁伊！"
D.Strings[59711]="%s雇用了一名战士！"
D.Strings[59712]="%s雇用了一名潜行者！"
D.Strings[59713]="%s雇用了一名萨满祭司！"
D.Strings[59714]="%s为连通统御岗哨和火箭岗哨的传送门添加了燃料！"
D.Strings[59715]="唔，我们或许可以想想办法……$b$b你把国王的指令送来时，我们正要开饭。我想，一些食物或许能让大家多些动力。$b$b还有，我想起来了，我们的尖刺还需要一些木头。你能帮我们去收集一些吗？$b$b然后……嗯……哦，还是算了吧。"
D.Strings[59716]="%s为通往双月殿的传送门添加了燃料！"
D.Strings[59717]="%s为通往奥格瑞玛的传送门添加了燃料！"
D.Strings[59718]="%s订购了一桌大餐！"
D.Strings[59719]="快没时间了！快告诉我！"
D.Strings[59720]="%s雇用了保卫墓地的守卫！"
D.Strings[59721]="%s雇用了保卫塔楼的守卫！"
D.Strings[59722]="雇佣提高法术急速的萨满祭司。"
D.Strings[59723]="延长我们的法师合同。"
D.Strings[59724]="延长我们的圣骑士合同。"
D.Strings[59725]="延长我们的牧师合同。"
D.Strings[59726]="延长我们的德鲁伊合同。"
D.Strings[59727]="延长我们的战士合同。"
D.Strings[59728]="延长我们的潜行者合同。"
D.Strings[59729]="延长我们的萨满祭司合同。"
D.Strings[59730]="呃，好吧，如果你坚持的话。$b$b你瞧，$r，传说这一地区埋藏着一件古代魔古神器——一根装饰精美的权杖。传说拥有这件宝物的人将得到部属的衷心爱戴。也可能是敬畏，具体的我忘了。$b$b总之呢，这也不会有什么坏处。你说呢？"
D.Strings[59731]="我找到你的宝贝权杖了。快拿上它！"
D.Strings[59732]="我们可以供养一座通往火箭岗哨的双向传送门，以及通往奥格瑞玛和双月殿的单向传送门。$b$b你想要为哪座传送门添加燃料呢？"
D.Strings[59733]="通往火箭岗哨的传送门。"
D.Strings[59734]="通往奥格瑞玛的传送门。"
D.Strings[59735]="通往双月殿的传送门。"
D.Strings[59736]="是谁竟敢打扰寇茹？你将为自己的傲慢付出代价！"
D.Strings[59737]="我想在水上行走。"
D.Strings[59738]="这似乎是某位古代魔古皇帝的雕像。"
D.Strings[59739]="这个洞穴中似乎有强大魔古法术的痕迹。"
D.Strings[59740]="看看你！哈！"
D.Strings[59741]="啊……你比看上去要聪明多了，我明白了。"
D.Strings[59742]="别……动……"
D.Strings[59743]="别抬头！"
D.Strings[59744]="%s刺向沃金的脖子。"
D.Strings[59745]="噢！布莱恩，看看这个爪子！我有种不好的感觉：魔古族似乎在研究某种黑暗魔法。"
D.Strings[59746]="嗯……根据这份抄本所说，寇茹魔古试图掌握煞魔的力量。这张地图就标出了他们的位置！干得好，$n。你今天可帮了我们大忙了。"
D.Strings[59747]="我明白你的意思，希尔达。魔古族和煞魔搅和到了一块儿？我一点儿也不喜欢这消息！我们最好将我们的发现上报给国王陛下。$n，非常感谢你今天的帮助，接下来的事就交给我们吧！"
D.Strings[59748]="潘达利亚。机遇之地。不能一夜暴富，就得倾家荡产。"
D.Strings[59749]="我们是来搞科研和发掘工作的，不是来惹麻烦的，我保证！"
D.Strings[59750]="你相信吗？那些神圣遗物学会的血精灵居然在这儿击败了我们？我们不能让他们继续挖掘属于我们的遗物！"
D.Strings[59751]="魔古族的文明十分古老，可以追溯到上千年前。或许我们能从他们那里学到点什么！"
D.Strings[59752]="噢，你是布莱恩的朋友吗？我敢打赌，你肯定不知道，在考古学院的时候，他还老抄我的笔记呢！"
D.Strings[59753]="探险者联盟的许多成员都得窝在图书馆里整理和分析我们的发现。$B$B我就曾这样度过了整整5年，而布莱恩却能周游世界，探索各种神奇的古迹。$B$B现在，希尔达终于重返野外了，我一定能搞出些大发现！"
D.Strings[59754]="雄狮港有什么消息吗，$c？"
D.Strings[59755]="我原本并不觉得这次的任务有什么了不起的，可血精灵的出现令我们警惕性大增。"
D.Strings[59756]="我向来不痴迷古代神器，可这次的任务确实比我想象中更加危险。"
D.Strings[59757]="魔古族的出现令我感觉非常不好。$B$B他们挖掘魔古神器的原因只有一个，而且那绝不是为了追求知识。$B$B他们在追寻魔古族的力量之谜。"
D.Strings[59758]="在兵营的时候，我听到过有关这种“煞魔”的传言。$B$B你真该听听那些疯狂的故事——煞魔控制了我们的王牌部队？那不过是吓唬小孩子的鬼话而已。$B$B煞魔没什么了不起的，我和我的姐妹们完全能对付它们。"
D.Strings[59759]="目前为止，一切平静。我们一直躲着那些血精灵。"
D.Strings[59760]="我侦察了这片废墟。这里的血精灵已经是倾巢而出了。"
D.Strings[59761]="我和萨拉哈并肩作战多年。她在战斗中总是勇往直前，而我则总是掩护她。"
D.Strings[59762]="快来帮帮我！螺旋桨里卷到东西了！"
D.Strings[59763]="你们必须滚出这片土地。"
D.Strings[59764]="这里不欢迎联盟。"
D.Strings[59765]="滚……下……我的……船！"
D.Strings[59766]="我的船上没有部落的位置！"
D.Strings[59767]="挑战号是我的！不滚就死！"
D.Strings[59768]="总算来了！一场势均力敌的战斗！"
D.Strings[59769]="你自以为很勇敢？！"
D.Strings[59770]="死吧，联盟的人渣！"
D.Strings[59771]="你休想妨碍我们的研究！"
D.Strings[59772]="我随手就能干掉你，$r！"
D.Strings[59773]="不错嘛，$c。我们今天的工作暂时完成了，但你要保持警惕。过几天，给你的下一道指令说不定就是从雄狮港发出的了，这是完全有可能的。"
D.Strings[59774]="还不错，$c。血精灵在积极地研究魔古族。很明显，加尔鲁什在搜寻强大的神器，但我们不会让他们得逞。"
D.Strings[59775]="嗯……根据这份抄本所说，寇茹魔古试图掌握煞魔的力量。而且，我们还知道了他们确切的活动地点。干得好，$n。"
D.Strings[59776]="显然，这些魔古族值得我们进一步研究。今天我们这里的工作已经结束了，$n。如果我们还需要你，会到统御岗哨跟你联络的。"
D.Strings[59777]="感谢你的协助，$n。你今天已经帮了我们不少忙了。如果我还需要你的帮助，会去统御岗哨找你的。"
D.Strings[59778]="感谢你的协助，$n。作为血精灵的领袖，保护人民是我的职责。这份责任不容轻忽。"
D.Strings[59779]="GG，联盟获胜！"
D.Strings[59780]="GG，部落获胜！"
D.Strings[59781]="看看这里吧，马尔考罗克。只有我们的人民才配得上这样繁荣昌盛的国土。"
D.Strings[59782]="是谁建造了这个王国？再告诉我一次他们的名字。"
D.Strings[59783]="是吗？看来我得向这些“魔古族”好好学习学习。"
D.Strings[59784]="是魔古族，酋长。根据熊猫人的历史记载，魔古族是生性残暴的统治者。他们靠强权震慑人民，而非仁政。"
D.Strings[59785]="这地方又热又黏糊，还有股闻起来要倒霉的味道。"
D.Strings[59786]="水银守护者活了过来！"
D.Strings[59787]="我们有活儿干了，$c。这片树林可不会自己倒下！"
D.Strings[59788]="“伐木”这个词听上去不合适，我更喜欢“美化景观”这个说法！$b$b这么多树在这儿挡着，我们怎么看得到海景？"
D.Strings[59789]="我正考虑在这里建造一个伐木场。$b$b这里有这么多可以砍伐的树木，要是错过这个大好机会，那我就是傻子了！"
D.Strings[59790]="别为这些树木担心。这就叫生命循环！它们长，我们砍，然后再用它们建造东西！$b$b好像这不叫循环，这叫流水线……"
D.Strings[59791]="这项技术的首次实地测试效果超过预期！带着这个，就算遇到再多虫群，你也能搞定它们。"
D.Strings[59792]="利用树木挣钱的好处就是，它们还会长出来。这就叫可持续发展！"
D.Strings[59793]="他们在前头破坏，我就跟在后头修理！这是一种共生关系。"
D.Strings[59794]="我的理论就是，没有啥是用火修不好的！"
D.Strings[59795]="你没看见我正忙着吗！"
D.Strings[59796]="我们都有要完成的使命，$c。只是，有些人会比别人做得更好！"
D.Strings[59797]="这是台好机器。实际上，我跟它已经有感情了。我甚至还给它起了个昵称叫“布鲁斯”！$b$b它只是没法正常运转而已，有点渗漏，而且还可能对周围10英里范围内的人造成威胁。"
D.Strings[59798]="这些机器人一定能让我载入发明史册。$b$b它们当然有一些副作用，但肯定比我们以前处理蜘蛛的方法要好用得多。$b$b毕竟为此把你自己的房子都给烧了是不实际的！"
D.Strings[59799]="伐木机原本的工作原理很简单。但它们现在有了新的操作系统。现在它们每过5分钟就得趴窝一次！"
D.Strings[59800]="保持仪态可不容易，可总得有人这么做！"
D.Strings[59801]="我一定能够惊艳全场。"
D.Strings[59802]="工头可不是人人都能当的！它需要技巧、头脑，当然还有仪表！"
D.Strings[59803]="人们总是指责我任人唯亲。可我把这看做合理使用资源。$b$b再说了，不然我的家人还能做什么？"
D.Strings[59804]="一大群螳螂妖在附近出现，并开始发动攻击！"
D.Strings[59805]="能为女工头干活，你应该感到荣幸！"
D.Strings[59806]="我们不能让任何部落成员逃离这个地方。有什么好主意吗？"
D.Strings[59807]="水银守护者的皮肤变得和白银一样坚硬。"
D.Strings[59808]="噢，我们知道现在需要什么……"
D.Strings[59809]="小队注意！失心果作战行动开始！"
D.Strings[59810]="够了！你的死期到了，入侵者！"
D.Strings[59811]="如果我没弄错的话，$n，这口……圣钟……正是加尔鲁什正在寻觅的武器。你先回去忙其他事情吧，我会亲自把这个消息告诉酋长的。"
D.Strings[59812]="看来我们的油料有点不够了。睁大你的眼睛，小心那些蛇，我们会没事的。"
D.Strings[59813]="队员们都在盯着那个没油的喷火器。这附近有可以吃的东西吗？"
D.Strings[59814]="如果铁矿供应充足的话，进展还能再快些……这附近或许会有一些矿点。"
D.Strings[59815]="我在日记里记了一些特殊的图表，可我把日记弄丢了。我们就凑合着用吧。"
D.Strings[59816]="来啊，你们这些懒骨头！加快脚步！"
D.Strings[59817]="如果让老爸看到我现在的样子……带着自己的队员为国王效力。他一定会骄傲地流泪的。"
D.Strings[59818]="%s召唤了一座连通雄师港和天火号的传送门！"
D.Strings[59819]="%s召唤了一座通往七星殿的传送门！"
D.Strings[59820]="%s召唤了一座通往暴风城的传送门！"
D.Strings[59821]="……你想要什么？"
D.Strings[59822]="有关这本法典，你有什么能告诉我的吗？"
D.Strings[59823]="嗯……我曾在纳斯雷兹姆的家乡见过这些文字。我无法读懂这些文字，你的族人应该也不行。"
D.Strings[59824]="你好，主人……我今天能为你做点什么呢……？"
D.Strings[59825]="什么？你就想让我看这些又脏又旧的书？噢，真扫兴。$B$B这是纳斯雷兹姆，也就是你们所说的恐惧魔王的语言。他们很少在家乡之外的地方使用这种文字。"
D.Strings[59826]="你想要什么，你这$r可怜虫？"
D.Strings[59827]="不。我才不帮你解读古代纳斯雷兹姆文献呢。立刻放了我！！"
D.Strings[59828]="……嗯？开饭了吗，老板？"
D.Strings[59829]="嗯……我不清楚。"
D.Strings[59830]="放我走吧……我想回到虚空中去。"
D.Strings[59831]="虚空之中不需要文字。我不知道……它似乎能连通……两颗星辰……"
D.Strings[59832]="你想和我谈谈……？真少见……"
D.Strings[59833]="我无法读懂这些文字……但这股魔法指向了另一个已不复存在的世界。它是被燃烧军团摧毁的。"
D.Strings[59834]="它茫然地看着你。"
D.Strings[59835]="地狱犬歪着头，奇怪地看着你。"
D.Strings[59836]="啊，$n主人，我能帮您什么忙吗？"
D.Strings[59837]="当然！这本法典是由古代纳斯雷兹姆语写成的。纳斯雷兹姆，也就是你们所说的恐惧魔王，曾是睿智而强大的种族。在无尽的黑暗虚空之中，没有哪个种族的召唤和传送法术造诣能超越他们。$B$B这本法典记载着如何开启通向另一个世界的传送门。可惜的是，那个世界已经不复存在了。在克索诺斯统治期间，为了展示力量，它把这个世界毁了。$B$B这本法典恐怕已经没用了。没有哪个$r$c能够光凭自己的力量打开这道传送门。"
D.Strings[59838]="想不到你知道的还挺多。"
D.Strings[59839]="我们眼魔就是为了见证万物的兴衰而生的。而我在您身边已经品尝到许多美味的魔法，主人。"
D.Strings[59840]="古布来帮忙了！"
D.Strings[59841]="‘乖孩子’，老爸总这么叫我。呃，可我们给这些部落混蛋准备的东西可就不那么美妙了！"
D.Strings[59842]="不要古布帮忙了？"
D.Strings[59843]="好吧，古布回兹诺那儿了。"
D.Strings[59844]="古布和伙计们干得好！"
D.Strings[59845]="誓死效忠部落。"
D.Strings[59846]="我还以为你就不问了呢！$b$b我们迟早会完成的，可现在也有很多你帮得上忙的地方。$b$b我们侏儒的新陈代谢很快——在我们努力工作时尤其如此。所以食物总是很受欢迎的。$b$b然后是油。这些陷阱非常精巧，不用担心齿轮会被卡住。把你能找到的油都带回来给我们。$b$b除此之外，还要保障我们的安全！$b$b<罗塞向四周看了看，又压低声音说道。>$b$b还——可能还有一件事……"
D.Strings[59847]="好吧，那是什么？"
D.Strings[59848]="<罗塞强忍着眼泪，说道。>$b$b我的……我的日记。它不见了。$b$b里面充满了我老爸的回忆，还有他的大量有关建造天堂都市的完美地点的研究。那可是侏儒工程学的巅峰之作！$b$b总之，里面有一副他的旧图纸或许能在这里派上用处。如果你在这附近的草丛里发现了它，请一定要告诉我。"
D.Strings[59849]="这是你的日记吗，罗塞？"
D.Strings[59850]="什么？你找到了！哇！我马上就开工！"
D.Strings[59851]="哇，你知道吗？它起作用了！"
D.Strings[59852]="侏儒建筑营地遭到攻击！"
D.Strings[59853]="听上去很糟糕！"
D.Strings[59854]="啊！我忘记反转两极协同转换器了。"
D.Strings[59855]="|TInterface\\Icons\\inv_misc_bomb_01.blp:20|t你成为了|cFFFF0000|Hspell:133925|h[狂轰滥炸]|h|r的目标！快跑！"
D.Strings[59856]="正在解读“你好，世界”程序。第一行：把敌人的脸打扁。"
D.Strings[59857]="出错：试图在写保护内存上存储信息。解决方案：向敌人移动并自爆。"
D.Strings[59858]="空指针异常。启动自爆协议。"
D.Strings[59859]="出错：除数为零。解决方案：启动自爆程序。"
D.Strings[59860]="检测到哈希数据表冲突。解决方案：自爆。"
D.Strings[59861]="喔！有指令！让我们看看……自爆？！"
D.Strings[59862]="嗯，看起来我的程序是用来……自爆。"
D.Strings[59863]="天呐！一个新程序！让我们看看……自爆？！"
D.Strings[59864]="好吧，让我们看看这些程序……自爆？！"
D.Strings[59865]="好吧，很高兴认识你。"
D.Strings[59866]="呃……以后再说！"
D.Strings[59867]="我想知道自爆感觉如何？"
D.Strings[59868]="我……得走了！"
D.Strings[59869]="自爆的感觉太棒了。"
D.Strings[59870]="什么？在这儿？现在？我们可是在打仗！$b$b尽管你对侏儒工程学的热情让我非常欣慰，但还是等我们回到铁炉堡的工匠镇再来谈这件事情吧。"
D.Strings[59871]="很好，我希望谈点别的。"
D.Strings[59872]="自由啦！一万年以后，我终于自由啦！今天是个好日子！很好很好的好日子！要搞个大派对！要有好吃的！要有好玩的！要有好喝的！叫上丛林猢狲！叫上山地猢狲！叫上天空猢狲！"
D.Strings[59873]="不！走……走开！"
D.Strings[59874]="别过来！"
D.Strings[59875]="啊……我的头……好疼！"
D.Strings[59876]="发……发生了什么？我控制不了自己的身体了。"
D.Strings[59877]="我梦到我变成了一个怪物。还好你把我弄醒了。"
D.Strings[59878]="谢谢你把我从那个噩梦中救出来。当时我真想把一切都毁了！"
D.Strings[59879]="我不知道我刚才怎么了。谢谢你让我变得清醒。"
D.Strings[59880]="感谢你救了我，士兵。也谢谢你，年轻的王子。"
D.Strings[59881]="我极力对抗愤怒，但我无法战胜它。太感谢你了。"
D.Strings[59882]="血喉来了！"
D.Strings[59883]="研究员莫里安来了！"
D.Strings[59884]="|TInterface\\Icons\\inv_sword_2h_mantid_01.blp:20|t%s装备上了他的|cFFFF0000剑|r！"
D.Strings[59885]="|TInterface\\Icons\\inv_misc_bomb_01.blp:20|t%s装备上了他的|cFFFF0000炸弹|r！"
D.Strings[59886]="|TInterface\\Icons\\inv_knife_1h_mantid_02.blp:20|t%s装备上了他的|cFFFF0000匕首|r！"
D.Strings[59887]="你没看见我正忙着吗？"
D.Strings[59888]="我们……还有更重要的事情要做，没空来应付你。滚开，废物。"
D.Strings[59889]="做好心理准备，$n。也许我们不得不把矛头指向我们自己人。"
D.Strings[59890]="我们在这地方发现好东西啦，$c！我们只需要把这些没用的树全都砍掉，再赶走那些烦人的动物就可以了！"
D.Strings[59891]="…… 我在你眼里看到了恐惧，裘碧卡。"
D.Strings[59892]="你想让我看什么……？"
D.Strings[59893]="古尔丹为了追求力量毁了这个世界……你担心我会对艾泽拉斯做出同样的事情。"
D.Strings[59894]="什么……？不！我……我不……知道……"
D.Strings[59895]="不！别过来……！你……你太危险了。我只要召唤召唤恶魔就满足了，可你……"
D.Strings[59896]="……你竟然想把自己变成恶魔！"
D.Strings[59897]="恶魔学识就是一把双刃剑……"
D.Strings[59898]="…… 我们既要面对外部威胁……"
D.Strings[59899]="…… 也要克服内心的软弱。"
D.Strings[59900]="我选你做我的同伴并非无的放矢。"
D.Strings[59901]="…… 一旦我失败了，我要你把我永远放逐。"
D.Strings[59902]="你究竟有什么邪恶的目的……？"
D.Strings[59903]="我厌倦了你的喋喋不休，末日守卫。告诉我你和你的同类为何如此执迷于献祭法术。"
D.Strings[59904]="我的契约只让我为你而战，而非向你透漏军团的秘密，凡人。"
D.Strings[59905]="别想欺骗我，恶魔！"
D.Strings[59906]="早在萨格拉斯背叛之前你们就已经存在了。你们究竟是什么？"
D.Strings[59907]="这种知识毫无用处……你究竟想要什么，坎雷萨德？"
D.Strings[59908]="这不关你的事！这个恶魔必须回答我，马上！"
D.Strings[59909]="多么奇怪的要求。即使是我的同类都很少关心我们的起源。你为什么想知道？"
D.Strings[59910]="既然你不关心，那告诉我又有什么关系？"
D.Strings[59911]="……在萨格拉斯释放我们之前，我们只是泰坦的走狗，被永远奴役着，监督奥术能量的使用。"
D.Strings[59912]="献祭法术在当时被视作是对生命最严重的亵渎，任何想要深入研究这种……美妙的法术的生物，都会立即受到惩罚。"
D.Strings[59913]="你也有你的小秘密，坎雷萨德。现在，我必须要问你……你为什么在意这些？"
D.Strings[59914]="我想我们的契约里不包括这个。到此为止吧。"
D.Strings[59915]="裘碧卡，结束仪式吧。"
D.Strings[59916]="有何吩咐，国王陛下？"
D.Strings[59917]="很高兴再见到你，$n。$b$b带上这些劳工，召集你在这片区域能找到的所有人手，帮助他们建立防御工事，确保没有任何部落人员能够逃脱我们的复仇。$b$b另外，这些劳工没有受过作战训练，你要保护他们抵达。$b$b现在，快点动身吧。时间不多了！"
D.Strings[59918]="多么奇怪的生物。燃烧军团都离开了，它们为什么还一直留在这里？"
D.Strings[59919]="……那种说法有个小漏洞。"
D.Strings[59920]="眼魔曾是伊利丹的仆从……而非燃烧军团。"
D.Strings[59921]="好吧，可他也死了……它们为什么还留在这里？"
D.Strings[59922]="我怎么知道？"
D.Strings[59923]="好吧，我花了几个星期的时间，想要弄明白怎么召唤这些家伙。如果你知道什么诀窍又愿意跟我们这些“下等”凡人分享的话，我会十分感激的。"
D.Strings[59924]="怎么了？你束缚邪能小鬼和空灵领主时可是游刃有余啊。"
D.Strings[59925]="相比之下，它们根本不算什么！它们根本就不是一个档次的。"
D.Strings[59926]="它们有点……奇怪……有些不对劲……"
D.Strings[59927]="又有精灵来送死了！"
D.Strings[59928]="誓死效忠部落！"
D.Strings[59929]="当心，伙计们。又有铁皮人过来了！"
D.Strings[59930]="这儿有不少油，好吧，我们会用到的！"
D.Strings[59931]="阿格娜，我不会离开很久的。暗矛氏族的人民都很坚强，也许他们并不需要我太多的帮助。"
D.Strings[59932]="好吧，亲爱的。来吧，朋友，我们一同前往暗矛部族的家园。"
D.Strings[59933]="嘿，$g小伙子:小姑娘;。有什么能为你效劳的？"
D.Strings[59934]="带头干吧，朋友。该建造你们的防御工事了！"
D.Strings[59935]="上坐骑，伙计们！不干活可挣不到啤酒。"
D.Strings[59936]="一场可笑的小冲突！联盟毫无战斗意志。"
D.Strings[59937]="守住这里，血卫士。我们将在这里建造要塞。劳工将在一小时内到达，注意激励士气。"
D.Strings[59938]="我来这里可不是为了救你，地精。发现燃料了没有？"
D.Strings[59939]="库卡隆？在这里？加尔鲁什在搞什么鬼？"
D.Strings[59940]="我有离开这么久吗？你都把我给忘了？"
D.Strings[59941]="你一定会的。我会派步兵来监督。"
D.Strings[59942]="真没想到，酋长亲自来救我了！"
D.Strings[59943]="有，有！发现了很多。海滩上到处都是。我们会立刻着手开采的，酋长大人！"
D.Strings[59944]="这些是我们的盟友！你竟然将他们视作威胁？你要给我一个交代！"
D.Strings[59945]="我们要出发了！"
D.Strings[59946]="<沃金毫无知觉地躺在地上，奄奄一息。>"
D.Strings[59947]="我们在传送进出的时候一定要小心，绝不能让吉安娜发现。$b$b你做好潜入的准备了吗？"
D.Strings[59948]="远离那些守卫！这个法术可以让你躲过暗夜精灵的视线，可你还是得保持距离。如果你遇到麻烦，就撤回来。"
D.Strings[59949]="小心点，$n。我们绝对不能被抓住。"
D.Strings[59950]="离联盟的家伙远点儿，$n。我们可不能让你在敌境腹地被抓住。"
D.Strings[59951]="如果你胡乱传送，吉安娜会抓住我们的。拜托你，下次再小心点。"
D.Strings[59952]="圣钟！我就知道你靠得住，$n。"
D.Strings[59953]="沃金是我的朋友，那是很久之前的事了。我们已经认识了很多年了。"
D.Strings[59954]="沃金出什么事了？"
D.Strings[59955]="几天前，沃金被冲上了海滩。$b$b他的血液中有一种毒素阻碍了他的再生机能。这种毒素一定是专门用来对付巨魔的。$b$b要我说的话，这个伤口一定出自刺客之手。而且是来自潘达利亚之外的刺客。"
D.Strings[59956]="站住！这座城市已经戒严。表明你们的身份。"
D.Strings[59957]="这里！把船停下。"
D.Strings[59958]="这个岛很适合充当海防要塞。罗克拉！等劳工一到，就把这些树砍了，开始建造码头。"
D.Strings[59959]="勇士，你已经来了很久，很了解这里。跟我来。"
D.Strings[59960]="%s呼唤附近守卫的帮助！"
D.Strings[59961]="你看见什么了，兄弟？"
D.Strings[59962]="这里不欢迎你们，术士。"
D.Strings[59963]="这座神殿属于灰舌兄弟会。我要求你立刻离开。"
D.Strings[59964]="又是一个术士？自从上次那件事之后，你真该庆幸我没有立刻杀你。"
D.Strings[59965]="矮人建筑营地遭到攻击！"
D.Strings[59966]="这位勇士，我能和你…… 私下谈谈吗？"
D.Strings[59967]="你是部落的英雄。你在诺森德和大灾变中的事迹堪称传奇。因此，我相信你的判断力。"
D.Strings[59968]="我是个游侠，而非政客。可无论如何，领袖的重担已落在我的肩头。"
D.Strings[59969]="我的人民，经历了太多的挑战与背叛，希望我能保证他们的未来。"
D.Strings[59970]="我们辛多雷是被联盟的偏见与猜忌逼入部落的。"
D.Strings[59971]="而现在，我在部落的酋长身上，看到了同样的歧视。他随意将我们当做炮灰。"
D.Strings[59972]="记住：我不会坐视部落与血精灵之间的利益冲突。我或许会重新考虑与联盟的关系。"
D.Strings[59973]="睁大眼睛，勇士。我们是同一阵线的……目前是。"
D.Strings[59974]="我父亲并不是要求你带领肯瑞托加入联盟——"
D.Strings[59975]="安度因，我知道他想要什么。噢，看看谁来了。"
D.Strings[59976]="没人比我更恨加尔鲁什。愤怒每天都折磨着我。"
D.Strings[59977]="跟我来——四处看看吧。"
D.Strings[59978]="塞拉摩陷落以后，我的第一反应就是要血洗奥格瑞玛——把城里的男女老幼全都杀光。"
D.Strings[59979]="我很惭愧。后来，我和卡雷苟斯就力量的使用进行了一次长谈。"
D.Strings[59980]="……吉安娜！"
D.Strings[59981]="肯瑞托向来不乏滥用力量之徒。克尔苏加德把魔法知识用在了死灵法术上。"
D.Strings[59982]="另一个背叛我们的人，凯尔萨斯·逐日者也曾在这里学习。"
D.Strings[59983]="安度因，你比别人更清楚，应该将部落及其人民区别开来。"
D.Strings[59984]="我每天都自问：“什么才是对的？”"
D.Strings[59985]="夺日者也在这里活动。联盟和部落相互合作。"
D.Strings[59986]="如果我们穷兵黩武，整个世界的希望就将破灭。"
D.Strings[59987]="我将这座城市视为一盏指路的明灯。"
D.Strings[59988]="只有对彼此充满信任，这份希望才能留存。"
D.Strings[59989]="谢谢你，安度因。"
D.Strings[59990]="我明白。我会跟父亲谈的。"
D.Strings[59991]="%s察觉了它的命运！"
D.Strings[59992]="%s高兴地一边转圈，一边咔嚓作响。"
D.Strings[59993]="%s开心地拍打着地面。"
D.Strings[59994]="%s以机械式的敬畏好奇地打量着四周。"
D.Strings[59995]="%s精力充沛地咔咔作响。"
D.Strings[59996]="%s购买了一箱旗帜！"
D.Strings[59997]="%s购买了一个土拨鼠笼子！"
D.Strings[59998]="%s购买了一个欺诈之碑！"
D.Strings[59999]="%s购买了一个灵视祭坛！"
D.Strings[60000]="%s购买了一盒改写程序的挖掘机器人！"
D.Strings[60001]="你来晚了，$n。\n\n我们就直奔主题吧。我们最近的侦查表明夏柯希尔的残余部队就躲在这座岛屿的中心。他们守护着一座加尔鲁什下令夺取的大型武器库。问题是他们激活了岛上的防御工事，一座覆盖整个扎尼维斯的大型护盾。\n\n这就是你的任务了。我要你去乘坐一艘炮艇并击毁护盾发生器。只要它们还在运转，我们的部队就无法到达武器库。"
D.Strings[60002]="干得好，英雄！我得承认你比我强。"
D.Strings[60003]="享受这来之不易的佳酿吧。它的配方在我的家族珍藏了上万年。据说，这酒还特别受到美猴王本人的亲睐。"
D.Strings[60004]="救命！我被攻击了！"
D.Strings[60005]="覆盖整个岛屿的护盾生成器保护着扎尼维斯之心，使我们无法抵达武器库。"
D.Strings[60006]="如果不能尽快消除这个护盾，我们就会被打垮。"
D.Strings[60007]="将军，他们激活了某种力场，岛上的控制塔楼都亮起来了。"
D.Strings[60008]="这些该死的螳螂妖！所有空中作战单位，摧毁那些塔楼！"
D.Strings[60009]="进入作战区域！拿下那些塔楼！"
D.Strings[60010]="瞄准那些琥珀炸弹。只要点着一个，它们就会产生大爆炸！"
D.Strings[60011]="干得漂亮！护盾似乎正在削弱。"
D.Strings[60012]="愚蠢的术士，我就知道你们还在打我们神殿的主意……！"
D.Strings[60013]="等等……你不是上次那些偷偷潜入的术士之一。那你来干什么？"
D.Strings[60014]="嗯……你的名字很耳熟，$n。$B$B你想在黑暗神殿里找到什么？留下跟我谈谈吧，别像个小贼那样鬼鬼祟祟的乱闯。"
D.Strings[60015]="部落酋长加尔鲁什正在寻找那些最近擅闯黑暗神殿的黑暗收割议会成员。"
D.Strings[60016]="乌瑞恩国王正在寻找那些最近擅闯黑暗神殿的黑暗收割议会成员。"
D.Strings[60017]="联盟曾鼎力协助我们从伊利丹手中夺回黑暗神殿。$B$B我愿意帮助你，因为我们彼此信任。"
D.Strings[60018]="$n，若非你和其他联盟成员的鼎力相助，我的族人是无法从伊利丹手中夺回黑暗神殿的。$B$B我愿意帮助你，因为我们彼此信任，也因为你帮助过我。"
D.Strings[60019]="告诉我他们的去向。"
D.Strings[60020]="带路吧，阿卡玛！"
D.Strings[60021]="部落曾鼎力协助我们从伊利丹手中夺回黑暗神殿。$B$B我愿意帮助你，因为我们彼此信任。"
D.Strings[60022]="$n，若非你和其他部落成员的鼎力相助，我的族人是无法从伊利丹手中夺回黑暗神殿的。$B$B我愿意帮助你，因为我们彼此信任，也因为你帮助过我。"
D.Strings[60023]="那两个术士是在几个月前闯入神殿的……但我依然无法确定他们到底在找什么。"
D.Strings[60024]="跟着我。他们光顾了失落灵魂神殿和神殿之巅。"
D.Strings[60025]="我决定暂时相信这位术士。$g他:她;可以自由出入神殿。"
D.Strings[60026]="要消除玛瑟里顿、伊利丹以及邪兽人对这片圣地所造成的破坏，我们还需要很多年的时间。"
D.Strings[60027]="里面就是失落灵魂神殿。无数死去兄弟们的灵魂还在这里徘徊。"
D.Strings[60028]="当心点，这里仍藏有很多陷阱。也许你的某个恶魔法术能够使你拥有探测前路的能力。"
D.Strings[60029]="多年来，它饱受煎熬，慢慢积蓄力量。"
D.Strings[60030]="这……太神奇了……一种未被开发原始奥术能量。"
D.Strings[60031]="想想吧，只要有一小部分这种力量，我们能召唤出什么样的恶魔来啊！"
D.Strings[60032]="召唤……呵呵，应该想象一下有了这样的力量，我们能够变成什么……"
D.Strings[60033]="这股力量和艾泽拉斯永恒之井最初的那股力量并无二致。"
D.Strings[60034]="所以，伊利丹就是靠这种办法役使了大量的恶魔……"
D.Strings[60035]="是的。作为酬劳，这些恶魔能够啜饮这个地方的能量。"
D.Strings[60036]="在这股能量的滋养下，它们能够摆脱对燃烧军团魔法的依赖。"
D.Strings[60037]="依我所见，他之所以追寻这股原始能量，是想要利用它来帮助血精灵们摆脱对太阳井的依赖……但由于某些原因，他没有让血精灵接触它……"
D.Strings[60038]="什么？？你这种说法毫无根据。"
D.Strings[60039]="你难道没有发现吗？伊利丹手下的恶魔并不像燃烧军团那样被熵化，被绿色的魔能腐蚀。"
D.Strings[60040]="……你为什么要说这么多，坎雷萨德？"
D.Strings[60041]="在那时……我亲眼目睹了这一切……"
D.Strings[60042]="……噢，拜托，你该不是又要跟我讲你那些恐怖故事了吧？"
D.Strings[60043]="……闭嘴。"
D.Strings[60044]="我想我更喜欢变成哑巴的你。"
D.Strings[60045]="你听到了吗？！那些灰舌恶狗要过来了。我们快点开始仪式吧！"
D.Strings[60046]="很好。等水晶完全充能完毕，我们再回来。"
D.Strings[60047]="根据我的研究，在很久以前，熊猫人专门为这口圣钟制作了一把特别的钟杵。"
D.Strings[60048]="当熊猫人武僧使用这把钟杵敲响圣钟，就能产生纯净的祥和之力。"
D.Strings[60049]="不过，有一天美猴王决定偷走这把钟杵，并把它藏了起来。这个恶作剧令钟杵彻底失传了。"
D.Strings[60050]="而我发现的，正是这个声名在外的“美猴王”最后的安息之地。"
D.Strings[60051]="这个地方的力量不容你们亵渎，术士！"
D.Strings[60052]="棘手之处在于，他是在和一名史称“青玉战神”的魔古族决斗的时候被困在玉石中的。"
D.Strings[60053]="我发现了能够释放这两人的法术，注意，是他们两个。一旦我施放法术，你必须在青玉战神回过神来之前击败他。"
D.Strings[60054]="加尔鲁什妄想利用圣钟来霸占这片土地。我们必须想个办法阻止他。"
D.Strings[60055]="安度因，我们来这里干什么？"
D.Strings[60056]="无数人因你们这种人的野心而丧命，面对他们的灵魂吧，术士！"
D.Strings[60057]="%s开始施放|cFFFF0000|Hspell:113134|h[群体复活]|h|r！"
D.Strings[60058]="既然你这么喜欢恶魔……那就尝尝它们的厉害！"
D.Strings[60059]="$n！我手下不少人被困在了地下室。时间不多了，帮帮我救出他们吧！"
D.Strings[60060]="啊，有人想知道金铁酒有多带劲儿？"
D.Strings[60061]="你可得小心了，这配方可是由美猴王传授给我们家族，然后代代相传，流传至今的。"
D.Strings[60062]="这种酒的真谛就是要在大战后与好友一起分享。来吧……朋友……如果你敢和我干一架的话。"
D.Strings[60063]="咿！你的招式真是快准狠。很好很好，看来你不是个一无是处的无毛怪。"
D.Strings[60064]="按我的要求解开其他的谜语！然后到南边的雄狮港来找我。"
D.Strings[60065]="……哟，$n！还记得我吗？好的，好的……嘿，听着……我们没必要帮这个家伙……"
D.Strings[60066]="这地方肯定有不少财宝……得了吧老板，你肯定是想……"
D.Strings[60067]="矮人建筑建造完毕！"
D.Strings[60068]="你害我损失了一个好战士，小王子。你将为此付出代价。"
D.Strings[60069]="你错了，加尔鲁什。"
D.Strings[60070]="死吧，小崽子！！"
D.Strings[60071]="魔古族用圣钟制造混乱，而熊猫人制作了一个特殊的钟杵，能化混乱为祥和。它被埋藏了数千年，直到今天。"
D.Strings[60072]="你休想得逞，加尔鲁什。"
D.Strings[60073]="你们联盟山穷水尽了吗，居然派孩子来对付我。"
D.Strings[60074]="我不杀你，去告诉你的国王，他的挑衅付出了什么代价！"
D.Strings[60075]="我们是强大的部落！我们绝不接受奴役！"
D.Strings[60076]="有了圣钟，就能根除我们内心的软弱：恐惧……绝望……仇恨……怀疑。低等种族才会被它们压垮。而我们，要掌控它们的力量。"
D.Strings[60077]="我们将携手摧毁联盟，夺取我们应得的一切。奏响这胜利的战歌吧。"
D.Strings[60078]="我们必将赢得胜利。有了圣钟的力量，我们将无人能挡。"
D.Strings[60079]="如果有人想螳臂当车，我们就碾过他们！"
D.Strings[60080]="是的！感受这力量吧。战胜恐惧。征服仇恨！"
D.Strings[60081]="这只是考验我们的力量。我们将一如既往地通过这个试炼！"
D.Strings[60082]="住手，加尔鲁什！你不明白那个钟的力量！"
D.Strings[60083]="啊哈哈……最后来的居然不是瓦里安，而是他的小崽子。你这是送死，小鬼。"
D.Strings[60084]="我不会让你得逞的。我发誓。"
D.Strings[60085]="那就试试看啊，人类。"
D.Strings[60086]="啊……啊啊啊！好痛苦！我控制不了了！"
D.Strings[60087]="战胜煞魔——控制它！利用它！"
D.Strings[60088]="真的吗，加尔鲁什？部落能撑过这场战争吗？"
D.Strings[60089]="弱者的猜忌！不要怀疑你的力量，伊什。我们必须撑过去！部落必胜！"
D.Strings[60090]="我们失去太多了，酋长。亲人死去，朋友离散，家园破碎。我们还要承受多少苦难？"
D.Strings[60091]="苦难结束了。战争胜利后，部落将迎来繁荣兴盛。"
D.Strings[60092]="既然可以趁敌人沉睡的时候杀死他们的孩子，为何还要顾及荣誉？我的剑在渴望联盟的鲜血！"
D.Strings[60093]="控制你的仇恨，伊什。杀戮不是谋杀。将你的怒火对准敌人。"
D.Strings[60094]="每晚，我都梦见手下的亡魂。当我们的身躯变冷，灵魂将去向何方？我…… 我怕死。"
D.Strings[60095]="利用这恐惧，伊什！将它留给敌人。当死亡降临，你是想站着面对还是跪着失败？"
D.Strings[60096]="酋长！我……我让你失望了。"
D.Strings[60097]="是的，伊什。的确如此。"
D.Strings[60098]="我对这个神器所知不多。意志薄弱的人才控制不了煞能，但是我一定可以。"
D.Strings[60099]="至少人类王子死了。这下，瓦里安为他的挑衅付出了代价。"
D.Strings[60100]="你走吧。我要好好想想。"
D.Strings[60101]="登陆场安全了。我们可以开始行动了。"
D.Strings[60102]="勇士，这份殊荣该归你。给舰队发信号吧。"
D.Strings[60103]="%s雇用了保卫岗哨的守卫！"
D.Strings[60104]="让我们在实战中看看部落的实力吧，我们要将这里建成统御岗哨！"
D.Strings[60105]="你看到了吗，勇士。我的部落无所不能。这是谁啊？"
D.Strings[60106]="沃金。你来干什么？你不是该躲在岛上和青蛙亲嘴吗？"
D.Strings[60107]="正是你的短视令你的人民始终落后。也正是你的不忠令我决定不召唤暗矛部族参战。"
D.Strings[60108]="问题是，我们来干什么？你将战火烧到了别处，我要知道是什么原因。"
D.Strings[60109]="看看吧，沃金。这里资源丰富：木材、石料、铁矿、原油。还有人口。"
D.Strings[60110]="在这里展示一下力量，就能让熊猫人对加入联盟产生疑虑。"
D.Strings[60111]="这些杀戮只会让别人对加入部落产生疑虑。"
D.Strings[60112]="这就是我们之间的差别，沃金。我可不会让我的人民在沙漠中饿死。为了让兽人和任何勇于站在我们一边的人拥有辉煌的未来，我会不惜一切——一切！在这儿等着。"
D.Strings[60113]="你还有点用，巨魔，证明一下你对部落的价值吧。去这片大陆的中心执行个任务。"
D.Strings[60114]="不，不，不！圣钟！"
D.Strings[60115]="我已经彻底封锁了整个达纳苏斯！我抓住了所有那些试图潜入城市的笨贼和想要靠传送法术躲过陷阱的半吊子法师！"
D.Strings[60116]="他们不可能通过……这可是内部机密。某个在城里的人带着圣钟，除非……不……"
D.Strings[60117]="跟我来。"
D.Strings[60118]="这些传送门通往达拉然。就是说肯瑞托……我的肯瑞托里……有人在助纣为虐。"
D.Strings[60119]="我绝不容忍又一次背叛！那些罪人必将受到惩罚！"
D.Strings[60120]="艾萨斯·夺日者！"
D.Strings[60121]="你背叛了肯瑞托，夺日者。是你让加尔鲁什的军队进入我的城市。"
D.Strings[60122]="你都不敢看我。我的城市不再欢迎你和你那些不服管束的同党。"
D.Strings[60123]="你搞错了，吉安娜。我没有。"
D.Strings[60124]="它同样属于我们，普罗德摩尔。"
D.Strings[60125]="哈！我明白了。那我就用武力驱逐夺日者。"
D.Strings[60126]="你，艾萨斯，跟我走一趟吧。"
D.Strings[60127]="吉安娜！达拉然出什么事了？被袭击了吗？"
D.Strings[60128]="肯瑞托内部出了叛徒。我已经控制了局势。"
D.Strings[60129]="我将部落逐出了达拉然。你的目的达到了，陛下：肯瑞托将属于联盟。"
D.Strings[60130]="我记得我说的话。可我信错了人。"
D.Strings[60131]="可你说——"
D.Strings[60132]="那些辛多雷——夺日者呢？"
D.Strings[60133]="投降的人将被送去紫罗兰监狱。而选择对抗的人，我不保证他们的性命。"
D.Strings[60134]="你在行动前应该和我谈谈——"
D.Strings[60135]="怎么管理肯瑞托是我的事。"
D.Strings[60136]="我一直在与辛多雷谈判。我们正在商讨辛多雷重返联盟的可能性！你在这种时候攻击他们的人，这只会——"
D.Strings[60137]="那是他们自己选的路。"
D.Strings[60138]="你把他们又推向了部落。"
D.Strings[60139]="这是自欺欺人。一入部落，再难回头。我现在明白了。我正在动员肯瑞托。"
D.Strings[60140]="吉安娜。我们得合作。联盟必须团结一致。"
D.Strings[60141]="不要劝我了，瓦里安。"
D.Strings[60142]="情况有变。"
D.Strings[60143]="勇士，请别走——我们谈谈！"
D.Strings[60144]="加尔鲁什袭击了我的儿子……？他人呢？"
D.Strings[60145]="安度因！"
D.Strings[60146]="安度因，你到底在想什么？我真该把你送回暴风城！"
D.Strings[60147]="他还活着，可全身的骨头都碎了。"
D.Strings[60148]="去找维伦，马上带他来！"
D.Strings[60149]="艾萨斯！你还活着。"
D.Strings[60150]="多亏这位英雄，我们逃了出来。还有许多人被送去了紫罗兰监狱。"
D.Strings[60151]="Anar’alash denal！谁来告诉我达拉然怎么了？"
D.Strings[60152]="普罗德摩尔！她将夺日者逐出了城市。她要将部落赶出肯瑞托！"
D.Strings[60153]="她太过分了。联盟的战斗法师肯定横行达拉然了。那个人类……巫婆！"
D.Strings[60154]="他们何时才能明白，才能看清？正是联盟的偏见与猜忌促成了部落！？他们把我们推向了地狱咆哮的部落。"
D.Strings[60155]="大人……"
D.Strings[60156]="哈杜伦，召集游侠。罗曼斯，集结血法师，让夺日者也加入你们。"
D.Strings[60157]="我们辛多雷要亲手掌握自己的未来。"
D.Strings[60158]="把这该死的玩意拿走！地狱咆哮用血精灵的鲜血换取他的宝物。真希望这钟把他毁了。"
D.Strings[60159]="大人。你会是个好酋长的。"
D.Strings[60160]="或许如此。把我的剑拿来。该我行动了。"
D.Strings[60161]="你想尝尝青春之水吗？"
D.Strings[60162]="吉安娜太过分了。她囚禁了夺日者，攻击任何抵抗的人。更糟糕的是，银色盟约也趁机加入了屠杀。"
D.Strings[60163]="上面一片混乱。我们得尽力救人，而且要快。"
D.Strings[60164]="等我的命令……"
D.Strings[60165]="上上上！去城市中心！这边走！"
D.Strings[60166]="艾萨斯不在……肯定被转移了。没有他我们也得继续。"
D.Strings[60167]="住手，让开。很好。"
D.Strings[60168]="艾萨斯，这边！进传送门！"
D.Strings[60169]="跟紧我！我们要出隧道了！"
D.Strings[60170]="跟着我！"
D.Strings[60171]="大家到齐了。我们开始吧。"
D.Strings[60172]="徒步前进。我们到四周找找其他入口。"
D.Strings[60173]="如酋长所愿……"
D.Strings[60174]="很高兴有你掩护我。我讨厌加尔鲁什的恶棍。"
D.Strings[60175]="我们上马，出发！"
D.Strings[60176]="嘿——等等我！我也讨厌那些恶棍。"
D.Strings[60177]="斥候说洞穴里有古代魔法。酋长让他们来调查。"
D.Strings[60178]="该死的蜥蜴人。随我战斗，兄弟们！"
D.Strings[60179]="你以前和这些家伙战斗过吗？"
D.Strings[60180]="看来他们空有武器，却没有脑子。"
D.Strings[60181]="我们可以把船开进去。只要做一点改装……"
D.Strings[60182]="啊……完成了！自行式蜥蜴人宰杀机。"
D.Strings[60183]="一人操作机枪，其他人步行。"
D.Strings[60184]="杀光那些爬虫！"
D.Strings[60185]="哎呀，甩掉它！"
D.Strings[60186]="他们在破坏我们的船！"
D.Strings[60187]="到了！在这儿停船。"
D.Strings[60188]="格里兹尔看着船。其他人跟我走。"
D.Strings[60189]="给！它能帮你对付虫子。"
D.Strings[60190]="准备工作完成了吗？"
D.Strings[60191]="是的，大人。陷阱已经设下。圣钟将安全地留在墓穴里，等待雷电之王的归来。"
D.Strings[60192]="我们只需撤走工人和剩余的战士即可。"
D.Strings[60193]="那好吧。愿兄弟们的鬼魂永远庇佑此地。"
D.Strings[60194]="没有时间了。影踪派追过来了。不能让他们发现圣钟的下落。"
D.Strings[60195]="他们不会就这样白白牺牲的。"
D.Strings[60196]="你也不会白死的，阿瓦图。"
D.Strings[60197]="光……我看到了光……经历了几百年的沉寂，终于有人来了。"
D.Strings[60198]="主人，我一直谨守誓言，守护着圣钟。"
D.Strings[60199]="等等……你不是魔古！入侵者！"
D.Strings[60200]="醒来吧，守护者们！消灭这些妄想窃取雷电之王宝藏的家伙。"
D.Strings[60201]="堕入黑暗吧！"
D.Strings[60202]="这座墓穴就是你的葬身之地！"
D.Strings[60203]="你们也将随之沉寂。"
D.Strings[60204]="如此恐怖……如此空虚。"
D.Strings[60205]="等待你们的只有死亡！"
D.Strings[60206]="不！圣钟！"
D.Strings[60207]="站住！现在该我了。我会给你们一个痛快的。"
D.Strings[60208]="那是我的勘察组。带我们过去。"
D.Strings[60209]="情况如何？"
D.Strings[60210]="陛下！这里有我们需要的一切：木材、石料和……"
D.Strings[60211]="还有部落？"
D.Strings[60212]="托德曼元帅和几个斥候追击一支部落小队去了海滩，至今还没回来。"
D.Strings[60213]="托德曼恐怕已经自顾不暇了。我们得分兵。"
D.Strings[60214]="琳娜，你留下来建营地。医疗帐篷和掩体一定要优先建造。等农夫到达后，就安排他们开始建港口。"
D.Strings[60215]="盘角，通知勘察组的其他人，等舰队一到，就把采石场和矿场搞起来。"
D.Strings[60216]="勇士，你对这片土地最为了解。跟我来，我们去找托德曼。"
D.Strings[60217]="托德曼你这老狗，我就知道你又惹麻烦了。"
D.Strings[60218]="勘察组干得不错。这是一处深水良港。"
D.Strings[60219]="这里要建一座塔楼。"
D.Strings[60220]="元帅，你一定要守住这地方，直到建设完成。"
D.Strings[60221]="现在，来看看补给……"
D.Strings[60222]="探险者协会前来报到，陛下！"
D.Strings[60223]="你对战争的积极令人欣慰。但我需要补给。你有什么？"
D.Strings[60224]="大量的石头。但这里没有发现大型铁矿。"
D.Strings[60225]="石头我要了。别的呢？"
D.Strings[60226]="还有更好的东西。史无前例！一个强大的远古遗物！"
D.Strings[60227]="我们做个交易吧，盘角。帮我的人把采石场开起来，而我们保护你搞考古挖掘。"
D.Strings[60228]="真的？！噢，我得到了国王陛下批准！真想看看布莱恩知道后的表情！我保证在下次日落前搞定采石场！"
D.Strings[60229]="我曾经以为领导力就是力量。现在我明白多了——付出才有回报。领导者要将人民团结起来。正所谓独木不成林。"
D.Strings[60230]="万事俱备。我们要利用海岸上的资源在这座半岛中央建一座城镇。"
D.Strings[60231]="现在我们要与当地人接触，并遏制部落的侵略行动。"
D.Strings[60232]="勇士！没有你对潘达利亚的开拓，这座要塞是不可能建成的。"
D.Strings[60233]="这份殊荣属于你。给舰队发信号吧。"
D.Strings[60234]="元帅，干得好。港口防御得到了巩固。接下来——"
D.Strings[60235]="安度因！你还活着！"
D.Strings[60236]="父亲，不能这样。我们的仇恨和愤怒——会腐蚀这片土地。"
D.Strings[60237]="放心。这场战争不同，孩子。它并非出于对部落的仇恨，而是出于对正义的热爱，源于有所必为的信念。"
D.Strings[60238]="这里——与众不同。它是块珍宝。"
D.Strings[60239]="那更要用生命来保护它。孩子！你要帮我。我们一起上阵？"
D.Strings[60240]="陛下！部落躲在西边的一座寺院里。许多暗夜精灵游侠已经包围封锁了那里……"
D.Strings[60241]="游侠？……泰兰德。"
D.Strings[60242]="父亲！不能让朱鹤寺变成战场！它还没能从煞魔入侵中恢复元气……"
D.Strings[60243]="那可是历史的瑰宝。"
D.Strings[60244]="大家冷静。这恐怕是加尔鲁什的陷阱。他想把我们引出海滩。托德曼？去组织农夫和迫击炮小队，不要放松守卫。"
D.Strings[60245]="可父亲——"
D.Strings[60246]="我会亲自带领一小队勇士去跟泰兰德谈谈。安度因，我能应付。相信我，我不会犯错的。"
D.Strings[60247]="……我相信你，父亲。"
D.Strings[60248]="向吉尔尼斯国王，吉恩·格雷迈恩致敬！"
D.Strings[60249]="高阶祭司泰兰德·语风从遥远而宁静的达纳苏斯来到了这里！"
D.Strings[60250]="德莱尼人的代表，睿智而高贵的预言者，来自埃索达的努波顿！"
D.Strings[60251]="我明白了。所以是这些……煞魔……引发了我们部队中的暴力行为？"
D.Strings[60252]="是的，父亲。我在旅途中也遇到过煞魔。不受约束的煞魔是令人惧怕的对手。"
D.Strings[60253]="我们联盟曾齐心协力打败过许多敌人，我的孩子。煞魔也将倒在我们面前，和其他敌人一样。"
D.Strings[60254]="这不一样，父亲。煞魔是不会被轻易击败的。它们会汲取我们内心的弱点，扭曲我们的心智。不要低估它们！"
D.Strings[60255]="没错，陛下！请看！"
D.Strings[60256]="圣光在上，那就是煞魔？"
D.Strings[60257]="是的。别靠近它！"
D.Strings[60258]="我能感到这个……东西散发着强大的黑暗力量。消灭它，马上！"
D.Strings[60259]="我同意。只有深重的苦难才能造就这种生物。"
D.Strings[60260]="我在翡翠林亲眼见过煞魔对我的士兵所做的一切。严重的猜疑令我手下最坚强的士兵都深感无助，自暴自弃。"
D.Strings[60261]="陛下，我们应该好好研究它。把它变成我们的武器。部落在潘达利亚的军力已经超过了我们。我们需要利用一切可能的条件。"
D.Strings[60262]="只是研究的话不会出事的。不过我很不喜欢它看我的眼神。"
D.Strings[60263]="太棒了！嗯，非常有趣！也许我可以用它提炼出一种新能源？"
D.Strings[60264]="加尔鲁什会利用手头的一切武器。难道我们不应该争取公平竞争的机会吗？"
D.Strings[60265]="安度因，你怎么看？"
D.Strings[60266]="我可不想以加尔鲁什为榜样。联盟应该有自己的决断。正确的决断。"
D.Strings[60267]="说得好，我的孩子。"
D.Strings[60268]="这种力量太危险了。我不同意！"
D.Strings[60269]="$n，感谢你今天的帮助。我就知道，我们一定可以说服我父亲选择正确的道路。现在，请回到你的岗位上去吧。"
D.Strings[60270]="肯瑞托之首，来自浮空之城达拉然的吉安娜·普罗德摩尔女士！"
D.Strings[60271]="我准备好了。请释放美猴王吧。"
D.Strings[60272]="没错，或许有一天，我们真的可以驱使煞魔作为武器。但在这个过程中，我们得冒着让人民遭遇灭顶之灾的威胁。我可不愿意付出这样的代价。"
D.Strings[60273]="<熊猫人响亮地打着呼噜。>"
D.Strings[60274]="醒醒！部落过来了——我们得组织好防线！"
D.Strings[60275]="噢。你恐怕选错了建造工事的时机，朋友。"
D.Strings[60276]="你瞧，昨天傍晚的庆祝时间有点长。我们都有点……喝过头了。"
D.Strings[60277]="我就知道你合适这任务，$c。等这里的事完成后，到楼上来找我。"
D.Strings[60278]="裘碧卡留下的记号清楚地表明她进入了黑暗神殿。"
D.Strings[60279]="进入神殿。"
D.Strings[60280]="放松点，伙计们。现在是畅饮时间。"
D.Strings[60281]="转动"
D.Strings[60282]="我们要守住这座滩头堡垒。我们要给部落建立一处据点，全潘达利亚都将成为下一个塞拉摩。"
D.Strings[60283]="我们必须防止部落侵占潘达利亚……可我们同时还要尽力减少我们造成的伤害。"
D.Strings[60284]="他们为什么叫我“烤鸡”？\n\n你真的想知道？你瞧，化学试剂会起那种反应并不是我的错！都怪该死的“科学”！"
D.Strings[60285]="探险者协会又理所当然地陷入了窘境并把自己闹了个手忙脚乱。\n\n而我们也就理所当然地要利用这一点。"
D.Strings[60286]="哎哟！\n\n我们要在这里同时对付幽灵和神圣遗物学会？！我再也想不出比这更糟的了！"
D.Strings[60287]="呃，我搞砸了……"
D.Strings[60288]="大家小心。封印正在崩溃。"
D.Strings[60289]="加尔鲁什，你真的相信煞魔可以被控制？你看到它对我们的人都做了什么吗？"
D.Strings[60290]="卫兵！干掉那个怪物。"
D.Strings[60291]="煞能可以被利用，成为强有力的武器。魔古族可能已经将煞的力量封入圣钟。看看他们依靠它缔造起了多么辉煌的帝国吧。"
D.Strings[60292]="可他们的帝国最终衰亡了。也许是由于煞魔，也许是由于熊猫人，或者是……由于他们自身的傲慢。"
D.Strings[60293]="这是怎样疯狂的愚行？"
D.Strings[60294]="天灾军团把你们族人的勇气都吸干了吗，血精灵！我们是部落。只要有机会能获得力量，我们就要抓住它。在我的部落里，弱者没有发言权！"
D.Strings[60295]="如你所说……酋长。"
D.Strings[60296]="怎么了，我的$g兄弟:姐妹;？你准备好给你的同胞做个榜样了吗？"
D.Strings[60297]="仪器表明你已经非常接近异常位置了。"
D.Strings[60298]="你一味对肯瑞托卑躬屈膝，好像他们才是我们的救世主。别忘了他们的背叛，艾萨斯。"
D.Strings[60299]="我们是辛多雷！我们不应向任何人低头，无论是肯瑞托，还是联盟，更不用说部落了。"
D.Strings[60300]="你总是这么毛躁，年轻人。没有什么知识是无用的。这件神器的历史能与圣钟相媲美。只要解开它的秘密，我们就能一进步了解加尔鲁什的战利品。"
D.Strings[60301]="当然，它还是很危险的。否则，这件神器的秘密对我们就毫无价值了。"
D.Strings[60302]="可向酋长低头就对了吗？加尔鲁什对这些魔古神器的痴迷程度简直让我想起了凯尔萨斯。"
D.Strings[60303]="罗曼斯，要是没有盟友支持，我们只会在这场战争中粉身碎骨。对加尔鲁什，我们没有保持中立的余地。我们要么追随他，要么就得反抗他。"
D.Strings[60304]="我们已经知道，魔古族拥有将生命能量禁锢在仪器中的能力。我们对这种法术所知不多。"
D.Strings[60305]="那是加尔鲁什的战利品，不是我们的。记住我的话，这个想法很危险。"
D.Strings[60306]="混沌的追随者……恶魔的召唤者……暗影的掌控者……"
D.Strings[60307]="你那里还有那种超级稀有、很难找到的护符吗？"
D.Strings[60308]="你们的存在逃不出我们的注意，$c。"
D.Strings[60309]="就像伊利丹，你总是努力想要掌控那消磨心志的混沌之力。"
D.Strings[60310]="你是在绝对的强权和彻底的堕落间走钢丝。"
D.Strings[60311]="银月城与达拉然的盟约长达2000余年。这段友谊决不能因为我们“可敬”的加尔鲁什酋长一时兴起而被轻易抛弃。$b$b哦……你是为神器而来的？"
D.Strings[60312]="艾泽拉斯击退了燃烧军团，你也战胜了你内心的黑暗并控制了它。"
D.Strings[60313]="或许你能做到伊利丹没能做到的事……或许你能接受这个宇宙的无序。"
D.Strings[60314]="现在，吉安娜·普罗德摩尔成了肯瑞托的领袖和达拉然的统治者。$b$b无论艾萨斯如何鼓吹所谓的中立，这都无异于将这座城市交于联盟之手。$b$b这位年轻的新贵或许已经忘了，可联盟曾在第三次大战时试图囚禁并屠杀我们的人民。$b$b很抱歉我无法认同他所谓的……“中立”观念。"
D.Strings[60315]="你们可以达到我们无法企及的领域。你们可以在九死一生的恶劣环境下顽强生存。"
D.Strings[60316]="坎雷萨德试图制造的神器并不完整。"
D.Strings[60317]="它能赋予凡人大规模施法的能力……可他们很快就会无法控制那股力量。"
D.Strings[60318]="酋长要看你们的研究成果。"
D.Strings[60319]="我可以解开水晶的力量，可只有你才能决定如何使用它。"
D.Strings[60320]="你一定要谨慎选择，$n。"
D.Strings[60321]="这里不是讨论这种事的地方。请到远行者广场下的大厅来找我。$b$b哦，记得带上武器。我想我们会用到你的力量。"
D.Strings[60322]="恶魔停止攻击了……这里出什么事了？！"
D.Strings[60323]="风暴之眼……为了寻找那件神器，曾爆发过无数惨烈的大战。我不知道为什么克希利会把它交给你，$c……可你一定要小心……掌握它的人无一不付出了惨重的代价。"
D.Strings[60324]="幸会，$c。我从在潘达利亚的兄弟们那里听到了一些传言。一些负面的抱怨和忧虑。$B$B我本人很支持部落的事业，可同时……也不希望事态过于失控。"
D.Strings[60325]="你也是亲爱的瓦里安国王派来请求协助的吗？"
D.Strings[60326]="我会带领肯瑞托加入联盟，并取得胜利！"
D.Strings[60327]="管好你的舌头，血精灵！你竟敢质疑酋长的决定？"
D.Strings[60328]="冷静点，伊什。让摄政王说出他的想法。"
D.Strings[60329]="我们已经踏上了南方大陆的土地。$b$b这里就跟我小时候在迷踪岛上听过故事里一样美丽。只是这里的鱼个头更大。"
D.Strings[60330]="你敢破坏我的好运气？那我就打破你的头！"
D.Strings[60331]="地精都是倒霉蛋！"
D.Strings[60332]="等我踩扁你之后，我会再弄一个幸运符的！"
D.Strings[60333]="地精都比你强。你这蠢货！"
D.Strings[60334]="这副肩甲……太重了……"
D.Strings[60335]="我一挥手，你就死了。接招吧！"
D.Strings[60336]="你真的没法选择其中一方吗？"
D.Strings[60337]="时不时来这种地方消遣一下是不错的选择，它能让我们回想起自己努力奋战究竟是为了守护什么。"
D.Strings[60338]="准备好了。"
D.Strings[60339]="不用着急，古伊尔。如果沃金相信他的人民正处在危险之中，那你最好尽力帮助他们。"
D.Strings[60340]="萨尔，我们不再听命与你了。我们有了一位新酋长。是他提醒我们要坚强！"
D.Strings[60341]="这比我想的还要糟糕。"
D.Strings[60342]="我们的另一边，则是雷电之王的狂热追随者，瓦安！"
D.Strings[60343]="另一位进入竞技场的是：血角！他会用你的鲜血染红他的角！"
D.Strings[60344]="我们还要欢迎广受痛苦爱好者追捧的：地下城主韦沙斯！"
D.Strings[60345]="嘿嘿！请看我们今日为大家带来的……布拉特！"
D.Strings[60346]="五对一看来似乎不太公平，可拜托……那只是一群半死不活的侏儒而已。欢迎我们的麻风侏儒五人组！"
D.Strings[60347]="同时进场的还有——巴特隆！当然，他不是由地精制造的……可他依然有着致命的威胁！"
D.Strings[60348]="另一边进场的是……嘿，看呐！那是我的好兄弟，法兰！他还带来了他的坐骑！"
D.Strings[60349]="我们还要欢迎人见人爱的白色小伙伴：帝皮！"
D.Strings[60350]="我们在希利苏斯的法阵里发现了这个钻洞的家伙。当时他已经被人打得半死。他就是，伊克西！"
D.Strings[60351]="同时进场的还有——位元毁灭者……以及他那滑稽的侏儒全息投影仪！"
D.Strings[60352]="再看这边！他怒气冲冲。他所向披靡。他还有点小可爱。他就是来自不息山的压路者！"
D.Strings[60353]="没错，她穿着裙子，她的脚关节还是反着长的，可她照样能痛扁你一顿。她就是多米尼卡！"
D.Strings[60354]="下面这位，或许是我见过的最无能、最丑陋、最没天分的拳手。它就是又笨又臭的侏儒，米莉·沃特！大家来点嘘声吧！"
D.Strings[60355]="我们在索拉查盆地花了数天功夫才找到这家伙。欢迎来到丛林！他就是，玛扎伦！"
D.Strings[60356]="你们中的一些老兵或许还记得这家伙。没错，他是有点支离破碎的，可他也能砸扁你！他就是，阿卡玛！"
D.Strings[60357]="同时进场的还有——大家最喜爱的、12英尺高的神奇僵尸，弗琼！我没读错吧？"
D.Strings[60358]="呃！又是侏儒？这一位似乎是自称米尔豪斯·法力风暴。快来干掉他吧！"
D.Strings[60359]="我们在奥金顿找到了这位在风暴中嚎叫的家伙。大家鼓掌欢迎——伊坎·伊祖！"
D.Strings[60360]="大家一起来跳舞吧！迪肯来啦！"
D.Strings[60361]="我们还要欢迎来自雷霆崖的恐怖牛头人——斯马什·重蹄！"
D.Strings[60362]="另一边进场的是，长着无数眼睛的兹恩沙尔！下次还会有什么呢，一个会打架的鼻子吗？"
D.Strings[60363]="他们的搭档完全是一个意外。事实上我对此颇为厌恶。他们就是，GG工程公司组合！"
D.Strings[60364]="接下来，正是我们最喜闻乐见的场面！拜托，再多来几条恐龙吧！有请，库拉卡大王！"
D.Strings[60365]="嗯。接下来这位是名符其实的工程学杰作。下面是，干涉者时间！"
D.Strings[60366]="哈哈哈！你可真够倒霉的！是普罗波库斯！啊哈哈哈！我敢出25个金币打赌，你肯定会被烧死的！"
D.Strings[60367]="各位，请安静……我们可不想激怒它。请屏息静气地欢迎我们的杀人鹿，乌古洛克斯！"
D.Strings[60368]="$n代表暴风城出战！"
D.Strings[60369]="$n代表铁炉堡出战！"
D.Strings[60370]="$n代表诺莫瑞根出战！"
D.Strings[60371]="$n代表达纳苏斯出战！"
D.Strings[60372]="$n代表埃索达出战！"
D.Strings[60373]="$n代表吉尔尼斯出战！"
D.Strings[60374]="$n代表土水派熊猫人出战！"
D.Strings[60375]="嘿，小家伙！你想来打一场吧。"
D.Strings[60376]="请等我一分钟，我想看完这场比赛。"
D.Strings[60377]="怎么了，$n？不敢动手了吗？来吧，让竞技场沸腾起来吧！"
D.Strings[60378]="$g他:她;的名字是$n。"
D.Strings[60379]="辉煌的胜利，$n！现在请回去排队。"
D.Strings[60380]="很抱歉，$n。现在，可以请你把自己的尸体弄走，好让下面的人继续比赛吗？"
D.Strings[60381]="说实话，$n……你到底出力了吗？"
D.Strings[60382]="要想收获，你就得先付出。"
D.Strings[60383]="啊哈哈哈！太厉害了！很好。"
D.Strings[60384]="让他们放马过来吧，$n。"
D.Strings[60385]="$n获胜！$n获胜！"
D.Strings[60386]="不！绝不！"
D.Strings[60387]="你竟敢反抗酋长？！"
D.Strings[60388]="我们正在肃清叛徒。似乎我们又找到了一个……"
D.Strings[60389]="这些巨魔必须知道自己的地位。"
D.Strings[60390]="部落没有弱者的空间。"
D.Strings[60391]="你休想阻挡我们！"
D.Strings[60392]="这是“我们”的部落！"
D.Strings[60393]="部落进攻了，诺弗！"
D.Strings[60394]="你必须帮助我们，诺弗！"
D.Strings[60395]="啥？哈？哦，对，防御工事……"
D.Strings[60396]="啊，非常感谢你，朋友。我正需要那个。"
D.Strings[60397]="噢，我只是……躺在地上……探听远方敌人的动向。嗯……我们暂时还是安全的。"
D.Strings[60398]="这头牦牛是公的！愤怒的公牛朝你冲过来了！"
D.Strings[60399]="哦，我只是打了个小盹，养精蓄锐。现在，整装待发！"
D.Strings[60400]="嗷！看看你都对我的毛做了什么！"
D.Strings[60401]="噢，为什么？你打扰了我的好梦……"
D.Strings[60402]="成功了！母牦牛轻轻地对你哞叫着。"
D.Strings[60403]="干得好。现在只需要把单简的头发加到酒剂中。"
D.Strings[60404]="褐石大师和他的小队睡着了！"
D.Strings[60405]="我快失去耐心了，单简。告诉我，圣钟在哪里！"
D.Strings[60406]="要杀就杀，我不会听命于你，或者你的部落。我只效忠雷电之王。"
D.Strings[60407]="伊什，去拿你的剑，他会改主意的。小心点，别要了他的命。"
D.Strings[60408]="加尔鲁什，请等等。也许有还有另外一个办法，无需流血的办法。"
D.Strings[60409]="那就快说！"
D.Strings[60410]="我知道如何调制一种古代熊猫人酒剂，借助这种酒剂，我们能看到单简的过去。所以我们只需要收集调酒需要的原料。"
D.Strings[60411]="巨石之核不过是个小小的挫折！"
D.Strings[60412]="我听过那些谣言和笑话……"
D.Strings[60413]="没人能在背后嘲笑伟大的米尔豪斯·法力风暴之后还能活着去向他人讲述这个故事！"
D.Strings[60414]="我这里有些你会喜欢的东西……"
D.Strings[60415]="值得表扬，甜心。"
D.Strings[60416]="祝你下次好运！挖哈哈哈哈哈！"
D.Strings[60417]="是地下城主韦沙斯！给我穿上皮衣，然后用你的鞭子狠狠抽我吧！"
D.Strings[60418]="另一边是诺莫瑞根的精英小队……至少他们曾经是。麻疯侏儒五重奏！"
D.Strings[60419]="另一位进入竞技场的是：巴特隆！这块破铜烂铁会把你们全炸飞！"
D.Strings[60420]="在竞技场的另一侧……一坨恶心的蠢地精骑在一头可笑的伐木畜生身上。是法兰和里东！大家一起嘘他们！"
D.Strings[60421]="别让他逮到机会，他会啄你的眼睛！帝皮出场！"
D.Strings[60422]="我们在希利苏斯发现了他。他身受重创已经命悬一线。他就是伊克西！"
D.Strings[60423]="另一位进入竞技场的是：位元毁灭者……和他的特别惊喜！"
D.Strings[60424]="她的微笑令我神往，她的法术令我倾心，她的角……令我醉心。她就是多米尼卡！"
D.Strings[60425]="哦，下一位选手是米莉·沃特！上工程学院的时候我和她约过会！"
D.Strings[60426]="也许有些老兵还记得这个人。他是个破碎者，但今天他会打碎你的骨头！是阿卡玛！"
D.Strings[60427]="今天我们将迎来一位特别的客人：最迷人，最坚强的侏儒：米尔豪斯·法力风暴！祝你好运，米尔豪猛男！"
D.Strings[60428]="我们还要欢迎来自雷霆崖的恐怖牛头人——斯马什·重蹄！看看他那华丽到掉渣的肩铠！"
D.Strings[60429]="在竞技场的另一侧……什么？一只漂浮的巨眼？这可不妙。"
D.Strings[60430]="哦，天哪……对不起，你的对手好像是普罗波库斯。"
D.Strings[60431]="我现在接受你对本场比赛胜负的预测。"
D.Strings[60432]="好了！停止竞猜！我们看比赛吧！"
D.Strings[60433]="你是谁？\n\n我可以向你保证，这里的一切都是正当合法的，尊敬的$g先生:女士;。我们都是小有资产的企业家，来这里欣赏友好的拳赛而已，绝对没有任何金币交易。"
D.Strings[60434]="|TInterface\\Icons\\INV_SWORD_04.BLP:32:32:0:0|t英雄。"
D.Strings[60435]="|TInterface\\Icons\\INV_MISC_MONSTERCLAW_04.BLP:32:32:0:0|t怪物。"
D.Strings[60436]="除非你亲自参加过搏击竞技，否则我不会接受你的竞猜。想参加竞猜，你需要“入股经营”才行。\n\n去和那些守卫谈谈并且排队参加搏击，然后我们再来玩竞猜。"
D.Strings[60437]="快点，尊敬的$g先生:女士;。你觉得下场比赛的获胜者会是谁？"
D.Strings[60438]="魔古族既傲慢专横又力量强大——加尔鲁什见了他们肯定会头脑发热怒不可遏。\n\n所以我们要赶在这种事情发生之前抓住魔古族的首领，并且从他的嘴里挖出我们需要的情报。"
D.Strings[60439]="快放我们出来！"
D.Strings[60440]="这里是我们的家园。如果你认为我们会默默忍受，你就大错特错了。"
D.Strings[60441]="你为什么要做这种事情？我们忠诚于部落！"
D.Strings[60442]="好吧，你也想参加？$b$b快点，快点，你觉得谁会赢，菜鸟？"
D.Strings[60443]="你是谁？\n\n这里绝对没有任何不法行为，$g先生:女士;。只是一些友好的拳赛而已，绝对没有任何金币交易。这里的一切都是光明磊落的！"
D.Strings[60444]="除非你亲自参加过搏击竞技，否则我不会让你参加竞猜。你得“亲自参股”，老大。\n\n去和那些守卫谈谈并且排队参加搏击，然后我们再来玩竞猜。"
D.Strings[60445]="好，还有谁参加？"
D.Strings[60446]="好了！搏击开始，停止竞猜！"
D.Strings[60447]="根据酋长的命令，这座“城市”现在受军队管辖。违背酋长意志者将被当作叛徒处置！"
D.Strings[60448]="你无权关押我们！"
D.Strings[60449]="这是我们的家园！库卡隆，你们在这里不受欢迎！"
D.Strings[60450]="你为什么要做这种事情？我们都是部落成员！"
D.Strings[60451]="沃金在哪里？"
D.Strings[60452]="这里不欢迎你们！"
D.Strings[60453]="酋长肯定是疯了。"
D.Strings[60454]="你是谁？凭什么质疑我们的忠诚？"
D.Strings[60455]="为部落流血的可不只是你们这些兽人！"
D.Strings[60456]="不必使用武力，让我们说服他。我这里有一桶熊猫人溯源酒。酒的力量可以让我们看到单简的过去。"
D.Strings[60457]="你到底……要杀多少自己人……才能夺回“你的”部落。"
D.Strings[60458]="部落正在改变！沃金不愿意与时俱进，而且他正在荼毒他的人民。"
D.Strings[60459]="你再也不能荼毒部落的儿女了。你的意志已经堕落了。"
D.Strings[60460]="我是为了联盟才做的……"
D.Strings[60461]="你有兴趣交易宠物战斗石吗？"
D.Strings[60462]="又和埃涅亚一起执行任务？好吧，除非我别无选择。"
D.Strings[60463]="你不再需要这把武器了，对吗？"
D.Strings[60464]="让我来教你该如何使用你自己的武器，兄弟。"
D.Strings[60465]="你死了之后就不会这么顽固了，对吧？"
D.Strings[60466]="你应该趁着能跑的时候赶紧跑。"
D.Strings[60467]="你想要夺走我们的土地？我们会把你埋在这里。"
D.Strings[60468]="暗生巫师使船陷入了停滞！杀了它以打断法术。"
D.Strings[60469]="附近有一组暗生之卵开始孵化了！"
D.Strings[60470]="格里兹尔给了你一把便携式火焰喷射器！用它来对付附近的蜥蜴卵。"
D.Strings[60471]="你需要暗月木马门票才能乘坐旋转木马。"
D.Strings[60472]="叛徒。你给你的种族蒙羞了。"
D.Strings[60473]="不能让那些巨魔继续忤逆酋长了！我们得收拾他们！"
D.Strings[60474]="难道你忘了生为兽人的意义？！我们是部落之血！我们和那些岛上的乞丐是不一样的。"
D.Strings[60475]="地狱咆哮会得知此事！"
D.Strings[60476]="我们不是什么被洗脑的野蛮人。违抗地狱咆哮就是和部落最伟大兽人作对！"
D.Strings[60477]="让我看看……你排在第二个。很快就轮到你了。"
D.Strings[60478]="你排在……第六个。"
D.Strings[60479]="你是第十个，孩子。"
D.Strings[60480]="今天人很多。你前面至少还有十个人。不过应该不会更多了。"
D.Strings[60481]="说不准，我想你应该是第三十个？也许是第四十个？我刚才数糊涂了。"
D.Strings[60482]="老板说你前面至少还有五十个人。$b$b我们就排到这里为止了。"
D.Strings[60483]="我马上就来，$g先生:女士;。"
D.Strings[60484]="褐石大师和他的那些手下因为时常在工作中偷懒睡觉而臭名昭著。"
D.Strings[60485]="我得确保那些懒鬼有在好好干活儿并且把那段防御工事给造起来。"
D.Strings[60486]="快进入终极巫毒术的效果范围内！"
D.Strings[60487]="只要我还活着，我就不会让那些蛮子的阵线向前推进一寸。"
D.Strings[60488]="植物饿了……"
D.Strings[60489]="这可是个重大发现！"
D.Strings[60490]="你只能选择一个任务。"
D.Strings[60491]="再见，附近的活体生物！独一无二的我即将被召唤到另一个位面。"
D.Strings[60492]="我的身体归于大地……"
D.Strings[60493]="去告诉其他人，林木有刺！"
D.Strings[60494]="帮我喂饱它们吧。"
D.Strings[60495]="没有什么东西能比针灸的疗效更好啦。"
D.Strings[60496]="坚持住，他们又回来了！"
D.Strings[60497]="小心，部落又来了！"
D.Strings[60498]="我从没想过这一天会真的到来！竟然是达纳苏斯的女勇士！快用力拍你的手，把最热烈的掌声献给莉安娜·地风！"
D.Strings[60499]="另一位是……肉弹！"
D.Strings[60500]="我从没想过这一天会真的到来！我们曾经的冠军，退役归来的勇士！快用力拍你的手，把最热烈的掌声献给莉安娜·地风！"
D.Strings[60501]="好了，褐石，该干活儿了！"
D.Strings[60502]="洛瑟玛想要知道实验的最新进展。"
D.Strings[60503]="这些寇茹设备和以前我们用来使驭恶魔能量的邪能水晶有些相似。无论是恶魔还是愤怒之魂还是某种情绪的元素具象产物，驾驭它们的原理都是相同的。$b$b我们需要调查一下存储在这件神器里的东西是否还保存完好。既然你已经在潘达利亚大陆上经历了这么多冒险，也和魔古族打过这么多交道，不知你是否有兴趣亲自动手？$b$b我们已经关闭了大部分的保护结界。你只需要手动调节一下这件神器的增强圆盘，然后准备好对付可能会蹦出来的东西就行。"
D.Strings[60504]="洛瑟玛想知道最新的进展？我猜是他的主子加尔鲁什想知道吧？$b$b没关系，反正你可以告诉他们俩，这实验完全是浪费时间。魔古族的力量来自于剥夺其他生物的生命精华。难道我们的酋长会涉足这种邪恶的勾当？$b$b这是凯尔萨斯·逐日者曾经走过的邪道，而这段历史几乎毁掉了我们的人民。我们为什么要听命于某个想要令我们重蹈覆辙的人？"
D.Strings[60505]="你知道圣钟被藏在哪里了？很好。加尔鲁什会很满意的。我们会试着找出你所描述的位置，一旦我们成功就会立即与你联系。"
D.Strings[60506]="来吧，$r。"
D.Strings[60507]="如果你想要打上两场，就来和我聊聊，$r。"
D.Strings[60508]="如果你想要参加搏击，尽管告诉我就行。"
D.Strings[60509]="在旋转木马上享受你的快乐时光！"
D.Strings[60510]="快来玩暗月旋转木马了！"
D.Strings[60511]="木马门票！快来买木马门票了！"
D.Strings[60512]="先付钱才能玩，朋友！快来买木马门票了！"
D.Strings[60513]="木马门票大特价！快来买门票了！"
D.Strings[60514]="你要先买木马门票才能玩旋转木马。快来买票了！"
D.Strings[60515]="快来看快来买！旋转木马门票这边就有卖！"
D.Strings[60516]="木马门票！这边能买到一整套木马联票！"
D.Strings[60517]="够了，罗曼斯！辛多雷必须从部落的桎梏中解脱出来！"
D.Strings[60518]="使用库卡隆伪装，然后在加尔鲁什尔先锋营中寻找情报。"
D.Strings[60519]="什么？！你知道魔古族把圣钟藏在哪里了？我必须立刻警告雄师港。我们必须赶在加尔鲁什之前拿到圣钟！一旦我们找到它就会马上通知你！"
D.Strings[60520]="闯入者！渣滓！臭虫！我会把你打烂！"
D.Strings[60521]="消耗了一张暗月木马门票。"
D.Strings[60522]="如果你想要参加搏击，尽管告诉我就行，$r。"
D.Strings[60523]="鲜血与荣耀，$c。"
D.Strings[60524]="如果你想要参战，就去和守卫聊聊，$c。"
D.Strings[60525]="肉弹饿了！"
D.Strings[60526]="肉弹想吃就吃！"
D.Strings[60527]="肉弹很高兴！"
D.Strings[60528]="肉弹肚子咕咕响！"
D.Strings[60529]="肉弹肚子痛！"
D.Strings[60530]="你获得了魔古能量！捡起更多的符文会继续增强你的能量。"
D.Strings[60531]="肉弹吃掉臭东西！"
D.Strings[60532]="嘎啊啊啊啊！"
D.Strings[60533]="感谢你救我出来。这段经历真是令人不快。"
D.Strings[60534]="我得洗个澡。"
D.Strings[60535]="别躲在你那些陷阱后面，出来面对我，懦夫！"
D.Strings[60536]="嘿，我认识你！你以前在竞技场里比试过！你这是又回来参赛了？"
D.Strings[60537]="欢迎回来，斗士。准备好比赛了？"
D.Strings[60538]="嘿，$g老大:甜心;。你想要打一场吗？"
D.Strings[60539]="欲罢不能，对吧？"
D.Strings[60540]="瞧瞧，瞧瞧……有大人物回来参赛了！"
D.Strings[60541]="$n！我能为你效劳吗？"
D.Strings[60542]="这不是拳手$n本人吗？你又来欺负我的怪物了？"
D.Strings[60543]="赢了几场，没错，我看着呢！再接再厉。"
D.Strings[60544]="你想要进去再打上两场吗？我会把你的名字写到单子上。"
D.Strings[60545]="哦，欢迎回来，$n。你是来打肿几张老脸的，对吧？"
D.Strings[60546]="又回来了？往后的战斗只会越来越难。"
D.Strings[60547]="你最近很受观众的欢迎啊，$n。有你就有好生意。"
D.Strings[60548]="嘿！$n！你今天想上场吗？"
D.Strings[60549]="嘿，$n。你今天是来看竞技场比赛的呢，还是打算亲自上场？"
D.Strings[60550]="感受烈焰的拥抱吧！"
D.Strings[60551]="烧吧！"
D.Strings[60552]="别以为你能逃掉！"
D.Strings[60553]="这儿冷吗……？"
D.Strings[60554]="准备好迎接强风了吗！奇拉瓦克！"
D.Strings[60555]="飞翔的感觉如何？"
D.Strings[60556]="奇拉……瓦克……"
D.Strings[60557]="你毫无机会。弗琼看你就像看一只臭虫。"
D.Strings[60558]="我的眼前……只有一片紫色……"
D.Strings[60559]="这才是我的$n！"
D.Strings[60560]="这儿是不是热起来了？"
D.Strings[60561]="嘘，伙计们！得赶快了！"
D.Strings[60562]="动起来！快一点！"
D.Strings[60563]="时间就要到了！"
D.Strings[60564]="啊呃……我闻到烟的味道了……"
D.Strings[60565]="火要烧起来了！"
D.Strings[60566]="好吧，好吧，有观众离场了，你懂的。"
D.Strings[60567]="我觉得吧，这场无聊的闷战我们已经看够了。对吧？"
D.Strings[60568]="这儿是不是热起来了？是我的错觉吗？"
D.Strings[60569]="我们可不能让你们打上一整晚。抓紧时间了！"
D.Strings[60570]="我觉得你们差不多该动真格的了。"
D.Strings[60571]="你闻到烟味了吗？"
D.Strings[60572]="好吧，好吧，后面还有一堆人等着要打呢，你懂的。"
D.Strings[60573]="嘿！想要搭一程吗？骑我们的陆行鸟吧！"
D.Strings[60574]="如果你需要坐骑，别客气，骑上这些小可爱吧！"
D.Strings[60575]="欢迎来到暗月岛！你可以骑着这些可爱的动物前往马戏团。"
D.Strings[60576]="巨型森林陆行鸟！前往暗月马戏团的免费坐骑！"
D.Strings[60577]="蠢货！我能控制那些驱动你战斗的情绪……恐惧，愤怒，疑惑……这些是我的武器！"
D.Strings[60578]="恐惧，愤怒，疑惑……这些情绪都是武器。我的武器。它们会让你死无葬身之地！"
D.Strings[60579]="让那些肮脏的野兽老实点！"
D.Strings[60580]="我闻到了联盟间谍渣滓的味道！"
D.Strings[60581]="占位符"
D.Strings[60582]="一口以血肉为坯，以星辰之火锻造，以大地之血熔接而成的大钟。"
D.Strings[60583]="这口钟响起时，足以震动世界，上达天听。"
D.Strings[60584]="在战场上，那钟声能让雷神的战士们热血沸腾。"
D.Strings[60585]="它能催化恨意和怒火，让战士们在战场上获得力量。"
D.Strings[60586]="圣钟的尖啸还能在皇帝的敌人心中植入恐惧和猜忌，让他们望风而逃。"
D.Strings[60587]="雷电之王对它的力量敬畏不已，称它为“众神之声”，并将它命名为圣钟。"
D.Strings[60588]="后来，雷电之王陨落，圣钟几易其手。许多人觊觎它的力量。也有人想让它永远沉寂。可他们都失败了。"
D.Strings[60589]="最终，寇茹织法者夺回了圣钟，把它藏了起来。从此，圣钟就失落在了历史的长河之中。"
D.Strings[60590]="可怜虫！你和你那些魔古族根本无法和部落的力量匹敌。"
D.Strings[60591]="现在……如果你还想要活命，废物，就好好回答我的问题。"
D.Strings[60592]="指挥官斯卡格尔变得狂怒无比！避开他的近战攻击！"
D.Strings[60593]="圣钟在哪里？！"
D.Strings[60594]="哈……<咳嗽>……你们这些年轻的种族……总是易怒而缺乏耐心。兽人……你甚至不能控制自己的愤怒……和恐惧。"
D.Strings[60595]="我……什么都不会……告诉你们。"
D.Strings[60596]="哈，不愧是忠实可靠的联盟$c！相信我，我理解这种情绪。$b$b接下来，作为肯瑞托的领袖，与此同时还是忠实的联盟成员，你会如何处置夺日者？诚然，他们是部落的支持者，但在过去的两千年中，他们也是肯瑞托的重要成员。这座城市也是他们的家园。$b$b你会驱逐他们吗？"
D.Strings[60597]="是，他们归根到底还是部落。"
D.Strings[60598]="<吉安娜的眼神有些悲伤。>$b$b所以说……你要肃清这座城市？你要把夺日者，那些曾经帮助人类洞悉魔法奥秘的人，赶出他们自己的家园？$b$b显然，你我持有不同的观点。我很明白我应该扮演的角色——以及肯瑞托的任务——和你的希望有所不同。我的心意已决。你想听听我的想法吗？"
D.Strings[60599]="你确定吗？"
D.Strings[60600]="不是你死就是我活！"
D.Strings[60601]="除非他们放弃与部落的盟约。"
D.Strings[60602]="<吉安娜轻轻拨弄着眼前的一缕金发，陷入了沉思。>$b$b你对你们的事业无比热忱，并且意志坚定。但相信我，夺日者和你是一样的。部落是他们的家人。$b$b并不是所有的部落都支持加尔鲁什，但他们不会抛弃自己的人民……我不能驱逐他们，这样会让肯瑞托分裂。$b$b对我来说，肯瑞托是一个神圣的词。我们必须团结一致。"
D.Strings[60603]="我会挣扎着保持中立。"
D.Strings[60604]="<吉安娜露出了微笑。>$b$b要是我们能够分享你的力量和信念就好了！老实说。我每一天都在挣扎。每一天。$b$b但你说的没错，肯瑞托高于你我，高于联盟。我有责任去维持肯瑞托的舷窗，并且明智地使用它的力量。$b$b看上去，你我能达成共识，但我怀疑暴风城国王是否也能认同这一点。不过……你觉得我们能说服安度因吗？"
D.Strings[60605]="*嗯哼*你好啊，旅行者！"
D.Strings[60606]="无毛怪，我回来了！"
D.Strings[60607]="哈……<咳嗽>……圣钟……你们竟然想要利用它？"
D.Strings[60608]="圣钟的声音……是神之声……"
D.Strings[60609]="<咳嗽>……你们易怒而天真，又缺乏耐心。你们甚至不能……控制自己的恐惧……和愤怒。"
D.Strings[60610]="你们还想要……<咳嗽>……控制圣钟？"
D.Strings[60611]="嘎啊啊啊！"
D.Strings[60612]="很好。这是你自己的选择，魔古。现在，去死吧……"
D.Strings[60613]="加尔鲁什！斧下留人！"
D.Strings[60614]="精灵！你想要忤逆我吗？！"
D.Strings[60615]="我不能眼睁睁看着你毁掉我们寻找圣钟的唯一线索，这可是我的族人在魔古岬拼死战斗才换来的。"
D.Strings[60616]="……很好。他是你的了，血精灵。"
D.Strings[60617]="无论他是否开口，即使把这块大陆撕成碎片我也会找到我想要的东西……只要那东西能给部落带来荣耀。"
D.Strings[60618]="但是，精灵……"
D.Strings[60619]="如果你再敢对我不敬，我会把你的脑袋砍下来，插在奥格瑞玛的城门外。"
D.Strings[60620]="希望你的审问能有个好结果。"
D.Strings[60621]="嘘！你会让我的伪装暴露的！"
D.Strings[60622]="你就是那个跟着康奈利的探子？"
D.Strings[60623]="他是我们找到圣钟的唯一线索。我们会让他说实话的。只需要给我们一些时间。"
D.Strings[60624]="好吧……真有趣。我们去外面见洛瑟玛吧。"
D.Strings[60625]="他很冲动，但我们会取得好结果的。他最终也会认同我们。"
D.Strings[60626]="纠错信息：法术失败。快报BUG！"
D.Strings[60627]="好了，所有人听好。准备把这名囚犯带回锦绣谷。当地狱咆哮冷静下来之后，我们再将他移送过去。"
D.Strings[60628]="当地狱咆哮冷静下来之后，我们再将他移送过去。我们不能让他毁掉我们的奖品，对吧？"
D.Strings[60629]="哈！没想到会在这里碰到我，对吧？美猴王从不错过决斗！现在，你是要当英雄呢，还是当个笨蛋无毛怪？"
D.Strings[60630]="明白了！让我瞧瞧你的本事。"
D.Strings[60631]="钟杵由三部分组成：杵柄，杵头和药膏。没有杵你想怎么敲这口钟？现在认真听我说话，然后准备好对付那些邪恶的坏蛋吧。"
D.Strings[60632]="不！笨蛋无毛怪不能拿走猢狲的宝贝棍子！"
D.Strings[60633]="不！不不！不开聚会了！这是盎迦盎迦的村子！"
D.Strings[60634]="停！别闹了！这不是真的美猴王！美猴王很多很多很多很多很多年前就死了！"
D.Strings[60635]="不！别唱了！"
D.Strings[60636]="美猴王说话不算！盎迦盎迦酋长说了算！听酋长的话！"
D.Strings[60637]="别喝酒了！记得乌克头领的下场吗？想要和他一样吗？"
D.Strings[60638]="不！停下来！停！停！停！"
D.Strings[60639]="你不是猴王！盎迦盎迦酋长不会承认你！"
D.Strings[60640]="美猴王是个大坏蛋无毛怪！"
D.Strings[60641]="看我的金闪闪！"
D.Strings[60642]="最好不要把坏的一面暴露给那些帮你准备食物的人。但这位老主顾似乎完全没有好的一面……"
D.Strings[60643]="都说眼睛是灵魂的窗口。如果这是真的，那我猜这位客人还有他的灵魂都藏起来了。"
D.Strings[60644]="这位客人穿戴有爱人的遗物。看来人们说的没错：每一段爱情都有荆棘，正如每个夜晚都会迎来黎明。"
D.Strings[60645]="我准备好听第一条线索了。"
D.Strings[60646]="好吧，再告诉我一条线索！"
D.Strings[60647]="这很简单！我准备好听下一条线索了。"
D.Strings[60648]="我明白了！告诉我最后一条线索。"
D.Strings[60649]="将钟杵组合起来。"
D.Strings[60650]="这是您点的吗？"
D.Strings[60651]="您不会正巧点了这杯锈色利刃吧？"
D.Strings[60652]="这杯酒是您的吗？"
D.Strings[60653]="我怎么可能会点这个？！"
D.Strings[60654]="你以为你是谁？！胆子好大！"
D.Strings[60655]="终于来了！我还以为我的酒压根不会送来了！"
D.Strings[60656]="当然，这就是我点的！这种酒其实是我发明的！"
D.Strings[60657]="那还能是谁点的？你那滑稽的表情是怎么回事？你看起来就像是我会揍你一样！"
D.Strings[60658]="总算来了！我都快渴死了！"
D.Strings[60659]="久旱逢甘霖啊！"
D.Strings[60660]="酒来了才算是聚会嘛！"
D.Strings[60661]="咦！这看起来真恶心！"
D.Strings[60662]="你竟然认为我会点这种酒，真是失礼！"
D.Strings[60663]="你们这里的服务简直越来越差了！"
D.Strings[60664]="趁我还没向你吐口水赶紧滚出去！"
D.Strings[60665]="真是大胆！"
D.Strings[60666]="你看看我这样子像是会点这种东西的人吗？"
D.Strings[60667]="别搞笑了。这当然是我的酒！"
D.Strings[60668]="我就在想，你和我的酒差不多该出现了！"
D.Strings[60669]="你还真是够快的！"
D.Strings[60670]="难道妹子就不能顺顺利利地拿到自己的酒？"
D.Strings[60671]="有时候看着其他人以命相搏真是令我感动！"
D.Strings[60672]="这地方根本没有跳舞的气氛嘛！"
D.Strings[60673]="我能要点喝的吗？"
D.Strings[60674]="所以说你想让我去这个什么……熊猫……利亚……的联盟前线？"
D.Strings[60675]="长毛的蠢蛋偷走了杵头！昆森猢狲在很多年之前遗失了杵头。现在那些长毛的蠢蛋把杵头藏在他们的巢穴里，把它当作某种宝贝胡萝卜供奉了起来。$b$b小心点，那些长毛蠢蛋咬人可疼了。"
D.Strings[60676]="事情不能只看表面，泰兰德。而且我儿子说这是个圣地。"
D.Strings[60677]="对方早有准备。不能被他们牵着走，得把他们引出来。"
D.Strings[60678]="你们三个就是我的耳目。散开！准备防御！"
D.Strings[60679]="后退！不要孤军深入。"
D.Strings[60680]="别靠近大门，那正中他们的下怀。"
D.Strings[60681]="建好防御工事。他们迟早会出来的。"
D.Strings[60682]="坚守阵地！等他们出来。"
D.Strings[60683]="把工事准备好。"
D.Strings[60684]="要利用有利地形。"
D.Strings[60685]="我们得互相支援。任何弱点都会成为目标。"
D.Strings[60686]="就要完成了。再接再厉！"
D.Strings[60687]="将他们逼入瓶颈。让他们自以为能赢……"
D.Strings[60688]="不要进攻。让他们犯错误。"
D.Strings[60689]="这里是我们的。他们每进一步都得付出代价。"
D.Strings[60690]="再接再厉！我们会赢的。"
D.Strings[60691]="利用每一点资源！让他们无路可逃！"
D.Strings[60692]="耐心点，泰兰德。"
D.Strings[60693]="耐心点，泰兰德。我们必将取胜，但得做好准备。"
D.Strings[60694]="我不会让联盟白白流血。我只想要一场彻底的胜利。"
D.Strings[60695]="很好。这说明他们就要突围了。"
D.Strings[60696]="很好。计划奏效了。"
D.Strings[60697]="非常结实的矮人建筑。它一定能大发神威。"
D.Strings[60698]="看来锦鱼人盟友准备好了。剩下的事怎么样？"
D.Strings[60699]="啊，侏儒科技！肯定能让部落死得不明不白。"
D.Strings[60700]="了不起！让我们看看这些熊猫人农夫的本事吧。"
D.Strings[60701]="他们过来了。到工事后面去！"
D.Strings[60702]="自己出来数数啊，懦夫！"
D.Strings[60703]="这里可没有什么大军，只有暴风城国王和几名英雄而已。难道你怕了吗？"
D.Strings[60704]="如我所料。退回防线——让他们过来！"
D.Strings[60705]="这是一场惨胜，但原本可能更惨。你赢得了这份奖励。"
D.Strings[60706]="逝者已矣，但要不是你，牺牲者可能更多。为表谢意，请接受这份礼物。"
D.Strings[60707]="干得好！我们将伤亡降到了最低。为了表彰你的贡献，请接受这份奖励。"
D.Strings[60708]="完胜！多亏了你的机智和高效，我方无一伤亡。接受这份奖励，以及我诚挚的谢意。"
D.Strings[60709]="我们胜利了！而且没让这片圣地溅上一滴鲜血。"
D.Strings[60710]="我曾经也和你一样。但这么多年来我学会了许多，我也已经尝够了加尔鲁什的诡计。"
D.Strings[60711]="从今天起，我们赋予了战争新的含义。"
D.Strings[60712]="泰兰德，我并非政客，我是个战士。我知道我们能赢。"
D.Strings[60713]="我们必须团结一致。你要相信我，并且认同我。只要我们齐心协力，就一定会赢。"
D.Strings[60714]="我们把他们堵在了寺院里。应该立刻进攻！"
D.Strings[60715]="那就更该净化它了。"
D.Strings[60716]="你在浪费宝贵的时间。"
D.Strings[60717]="这是浪费时间，应该冲进去厮杀！"
D.Strings[60718]="你太犹豫了，瓦里安。如果你想领导联盟，就得果断点。"
D.Strings[60719]="我们为什么不直接进攻？"
D.Strings[60720]="他们在寺院里嘲弄我们。"
D.Strings[60721]="我们的工事完成了。"
D.Strings[60722]="换了我会直接进攻，而我那样冒进的话可能会牺牲更多人。"
D.Strings[60723]="我明白了。请领导我们，陛下。愿它成为一个好的开端。"
D.Strings[60724]="这是一场耐心的试炼。狼群之首究竟是野兽，还是国王？"
D.Strings[60725]="战士的武器是利剑，而国王的武器则是耐心。"
D.Strings[60726]="今日之战已胜，可前方还有更多险阻……"
D.Strings[60727]="联盟狗！你的爪牙呢？"
D.Strings[60728]="让步兵上。进攻！"
D.Strings[60729]="你们就是这么打仗的？"
D.Strings[60730]="你们联盟太弱了！"
D.Strings[60731]="胆小鬼！"
D.Strings[60732]="我的眼中……曾经满是黑暗……感谢你。"
D.Strings[60733]="光……哪里来的亮光？愿天神保佑你……"
D.Strings[60734]="终于，苦难终结了……"
D.Strings[60735]="本以为……我会被永远囚禁于此……最终我还是重获自由了吗？"
D.Strings[60736]="终于我的灵魂可以离开这被诅咒的地方……"
D.Strings[60737]="终于，灵魂不再惶恐……"
D.Strings[60738]="圣钟对于部落而言意义重大。$b$b酋长对我们寄予厚望。"
D.Strings[60739]="|TInterface\\Icons\\ability_thunderking_thunderstruck.blp:20|t%s开始施放|cFFFF0000|Hspell:135096|h[雷霆打击]|h|r！快跑！"
D.Strings[60740]="童福！来点吃的。"
D.Strings[60741]="联盟的领袖——国王瓦里安·乌瑞恩。"
D.Strings[60742]="你知道吗？他曾做过角斗士。没错，我调查过。"
D.Strings[60743]="当时失忆的他，在部落竞技场里厮杀求生。"
D.Strings[60744]="在那里，他叫“洛戈什”，外号“幽魂之狼”。"
D.Strings[60745]="他战技超群。可他…能当领袖吗？"
D.Strings[60746]="想想吧！他的敌人利用了我父亲引发的大灾变。"
D.Strings[60747]="部落的军队在浩劫之后席卷大地。"
D.Strings[60748]="瓦里安·乌瑞恩却没有利用灾难赢得军事优势。"
D.Strings[60749]="这是因为他软弱……？还是因为太讲原则？"
D.Strings[60750]="更大的问题是：原则能赢得战争吗？"
D.Strings[60751]="潘达利亚对你们的国王无疑将是个挑战。"
D.Strings[60752]="让我们看看他的能力。"
D.Strings[60753]="让我们看看联盟是否能够统治艾泽拉斯。"
D.Strings[60754]="加尔鲁什·地狱咆哮！部落酋长。"
D.Strings[60755]="他并非一直如此强硬。"
D.Strings[60756]="在德拉诺，他就是个可怜虫。他父亲的过去总是纠缠着他。"
D.Strings[60757]="我明白，加尔鲁什。我知道背负父亲的罪孽是什么感觉。"
D.Strings[60758]="让加尔鲁什这样的战士上台本身就说明了——"
D.Strings[60759]="部落正面临转折。这场战争将定义你们。"
D.Strings[60760]="什么才是部落？"
D.Strings[60761]="它究竟是为了人民的未来而拼搏的复仇工具？"
D.Strings[60762]="还是为了团结互助而建立起来的，庇护受压迫者的牢固同盟？"
D.Strings[60763]="或者说，仅仅是一个权宜之计，由一群各怀目标的盟友临时拼凑而成？"
D.Strings[60764]="所以我想问你：部落的灵魂是什么？"
D.Strings[60765]="我们将在潘达利亚寻找答案。"
D.Strings[60766]="让我看看部落的实力吧，勇士！"
D.Strings[60767]="向我证明，部落有资格统治艾泽拉斯。"
D.Strings[60768]="还记得我们之前的谈话吗？"
D.Strings[60769]="我们分析了你的国王。我一直在密切关注他。"
D.Strings[60770]="他的确有着狼的灵魂。他能像狼一样战斗。"
D.Strings[60771]="看了他的作为，我明白了一件事。"
D.Strings[60772]="狼是群居动物。"
D.Strings[60773]="你的国王召唤狼群，组成了“联盟”，赋予这个词真正的涵义。"
D.Strings[60774]="他的路还很长。他刚迈出第一步。"
D.Strings[60775]="然而，有你这样的英雄在，联盟就没有什么做不成的事。"
D.Strings[60776]="童福：把东西拿来！"
D.Strings[60777]="你对这份事业的贡献配得上这份奖励。"
D.Strings[60778]="和你一样，我也在潘达利亚锻炼自己。相信结果会让你满意的。"
D.Strings[60779]="挑选奖励吧！"
D.Strings[60780]="小心，英雄。雷电之王的回归既是威胁……也是机遇！"
D.Strings[60781]="我们谈了你的酋长。他内心的矛盾和外在的征服欲。"
D.Strings[60782]="我问过你：部落的灵魂是什么？"
D.Strings[60783]="你在潘达利亚南岸和其他地方的努力已经给了我答案。"
D.Strings[60784]="你就是部落的灵魂。"
D.Strings[60785]="你在不久的未来定义你的人民。"
D.Strings[60786]="我想让你为未来的试炼做好准备。"
D.Strings[60787]="欢迎回来，联盟的英雄！沿海的战斗进行得如何？"
D.Strings[60788]="你杀掉他了吗？血柄曾在南贫瘠之地为部落效命。你为许多人报了仇，勇士。"
D.Strings[60789]="欢迎回来，部落的英雄！沿海的战斗进行得如何？"
D.Strings[60790]="那么，双辫将军死了吗？他是联盟在南贫瘠之地行动的关键人物。你干得很好。"
D.Strings[60791]="保持警惕，英雄。这地方封闭了数百年。天知道里面会有什么东西。"
D.Strings[60792]="就是它，英雄！圣钟！"
D.Strings[60793]="那是什么？不管了。谁敢来妨碍我们就打倒他。"
D.Strings[60794]="我们必须把它送到安全的地方。哨兵，我们动手吧。"
D.Strings[60795]="部落。真可惜，你们来晚了。圣钟归我们了。游侠们！出击！"
D.Strings[60796]="啊！我的弓箭手应该阻止你的！哨兵！进攻！"
D.Strings[60797]="很好。我将亲自对付你。为了联盟！"
D.Strings[60798]="呃……我的死……不算什么。圣钟已经被送到了达纳苏斯。肮脏的部落……永远得不到它！"
D.Strings[60799]="天空之子，进攻！"
D.Strings[60800]="你必将死在我的剑下！"
D.Strings[60801]="我从阴影中出击！"
D.Strings[60802]="再后来发生了什么？"
D.Strings[60803]="来点儿噪音！"
D.Strings[60804]="不！美猴王不能拿走棍子！你也不能拿走棍子！这个是冒牌美猴王。$b$b酋长盎迦盎迦从他爸爸盎迦盎迦那里拿到棍子，他爸爸从他爸爸的爸爸那里拿到棍子，他爸爸的爸爸从他爸爸的爸爸的爸爸那里棍子。$b$b很久很久以前美猴王就把棍子给了我们家，我们家就都是酋长了。$b$b没有猢狲可以活这么久！没有！"
D.Strings[60805]="但那确实是真的美猴王啊。"
D.Strings[60806]="时间宝贵，$n。普凡迪特·格兰特利也许能够帮助你返回暴风城。当然，你得付点钱。"
D.Strings[60807]="可怜的酋长盎迦盎迦。他的家族忘记了那棍子的用途。太疯狂。$b$b要是让他继续疯下去，他的人民会堕落。太不幸。"
D.Strings[60808]="安静受死吧，夺日者！"
D.Strings[60809]="肯瑞托绝不容忍叛乱。"
D.Strings[60810]="这是你们自找的，夺日者。"
D.Strings[60811]="你放弃了逃跑的机会。"
D.Strings[60812]="没有你们，达拉然会更好。"
D.Strings[60813]="你们以为自己不用付出代价吗？"
D.Strings[60814]="肯瑞托在你们心中还不如那个酋长。"
D.Strings[60815]="现在……你去死吧！"
D.Strings[60816]="快进传送门！"
D.Strings[60817]="那把细细的钟杵曾经闪亮而神圣。"
D.Strings[60818]="但它只是用来敲钟的，我才不想要呢。"
D.Strings[60819]="可是魔古族偷走了那口钟，我一个猢狲应该怎么办？"
D.Strings[60820]="我想那些混蛋肯定还要偷钟杵。"
D.Strings[60821]="魔古族不聪明，他们看不清事物存在的原因。"
D.Strings[60822]="美猴王折断了钟杵，把碎片藏得远远的。"
D.Strings[60823]="我的猢狲们带着这些碎片，去往大陆各地。"
D.Strings[60824]="它们被伪装成“漂亮的小东西”，从未落入魔古族之手。"
D.Strings[60825]="只要把钟杵的头和柄合起来，它就又完整了。"
D.Strings[60826]="再配上一点药膏，就能驱除这口钟的邪恶。"
D.Strings[60827]="如果“加尔鲁什”拥有了这口钟，那我们只能做一件事情了。"
D.Strings[60828]="我会召集我的猢狲朋友们，重铸这把钟杵。"
D.Strings[60829]="瓦里安派我在你建造防御工事的时候留意寺庙附近的情况。\n\n耐心一点，除非瓦里安下达命令，否则不要靠近寺庙。"
D.Strings[60830]="我们将在寺庙周围建造防御工事。你的德鲁伊们能帮忙吗？"
D.Strings[60831]="来吧孩子们。愿艾露恩指引我们今日的行动。"
D.Strings[60832]="我感觉这像个陷阱，但是我们不能浪费时间了。我们走！"
D.Strings[60833]="在寺庙西边和我们碰头，$rt。我们需要你的帮助。"
D.Strings[60834]="正好米师回到了我身边。你可得万分小心！这是件独一无二的稀有神器。"
D.Strings[60835]="你真以为你能打败我？"
D.Strings[60836]="又有人来挑战了？"
D.Strings[60837]="胜利者诞生了！$n赢得了此次锦标赛的第二名！"
D.Strings[60838]="胜利者诞生了！$n赢得了此次锦标赛的第三名！"
D.Strings[60839]="|TInterface\\Icons\\spell_arcane_massdispel.blp:20|t |cFFFF0000|Hspell:132275|h[湮灭]|h|r杀死了你。在它失效之前离开能量漩涡。"
D.Strings[60840]="今天我们有活要干了，嗯？\n\n我可怜的狮鹫......"
D.Strings[60841]="一起行动吧。|cFF0008E8（达金会跟着你。）|r"
D.Strings[60842]="继续前进，你不必担心这个。"
D.Strings[60843]="你要是识时务，就不要插手这事。"
D.Strings[60844]="这些银色盟约的家伙们想要打垮我们，你能相信吗？"
D.Strings[60845]="到底是怎么回事？“肃清”是什么意思？"
D.Strings[60846]="嘿，你好！我是泰克泰克。我现在就把你带到谷地去，就像那个绿皮大个子告诉我的那样。"
D.Strings[60847]="等等！你就是那个把海滩上的联盟蠢蛋打得满地找牙的无毛怪？"
D.Strings[60848]="当时我正自得其乐地玩着牌，那可是副好牌啊……忽然这些银色盟约的流氓就闯进来叫我们收拾东西走人。凭什么？"
D.Strings[60849]="银色盟约的人全疯了吗？肯瑞托肯定不会容忍这种事情发生的！"
D.Strings[60850]="他们说普罗德摩尔女士要我们离开。我……我不明白啊。"
D.Strings[60851]="这里已经不安全了。你必须马上逃离达拉然。"
D.Strings[60852]="这些都是你干的？你真能干！"
D.Strings[60853]="你知道吗，那个棕色皮肤的大家伙去北边儿了。那个加鲁德……呃……加诺什……呃，反正他名字我记不住。"
D.Strings[60854]="他看上去有很重要的事情。泰克泰克想要和他聊聊，但是他一瞪我，我就只能闭嘴了。"
D.Strings[60855]="好吧，如果你这么说的话。"
D.Strings[60856]="只要有你在背后支援……"
D.Strings[60857]="哦，看起来我们到了！"
D.Strings[60858]="运气真不错。"
D.Strings[60859]="我们又见面了。你今天过得好吗？"
D.Strings[60860]="不管怎样，泰克泰克在营地里听到了许多信息。我听说你的酋长加尔鲁什正在调查锦绣谷。"
D.Strings[60861]="你和你的漂亮精灵们在那儿的时候有什么发现吗？"
D.Strings[60862]="我听说了关于一口钟的事情，由那些疯狂的魔古族……在几千年前制造的。太可怕了！"
D.Strings[60863]="我想我能回银月城了……"
D.Strings[60864]="离开达拉然？那我应该去哪里……"
D.Strings[60865]="你的酋长现在想要找那口钟？任何魔古族制造的东西都很危险……也很厉害。"
D.Strings[60866]="不管怎样，我们就快到滨岸村了。我想你一定是在做一件非常重要的事情。"
D.Strings[60867]="是一个大块头熊猫人叫我把你带去那里的。"
D.Strings[60868]="他说别把你的行踪告诉任何人！"
D.Strings[60869]="泰克泰克很守信用。泰克泰克口风很紧。我能帮忙！"
D.Strings[60870]="好了，我们到了。下去吧！"
D.Strings[60871]="想要飞回昆莱山吗，无毛怪？"
D.Strings[60872]="我们上次见面的时候，你正要去滨岸村找你的熊猫人朋友。"
D.Strings[60873]="你把该干的事干完了吗？"
D.Strings[60874]="不管怎样，我又看到许多漂亮的精灵往北边儿去了。很多很多精灵。"
D.Strings[60875]="他们正在找那口钟。又大又厉害的钟！无毛怪，你也在找那钟吗？"
D.Strings[60876]="这太过分了！艾萨斯会知道这一切的！"
D.Strings[60877]="好吧，但是我会直接向大法师汇报此事。"
D.Strings[60878]="我们到了。再见！"
D.Strings[60879]="哦，那个大东西晃起来了。"
D.Strings[60880]="我听说不少漂亮的精灵在魔古岬被打翻了。"
D.Strings[60881]="那个，当时你在吗？你看见了吗？"
D.Strings[60882]="不管怎样，高个子精灵首领，那个洛瑟姆……什么的，他简直气疯了！"
D.Strings[60883]="血精灵并未做好与寇茹魔古战斗的准备。许多血精灵牺牲了，可我听说你救下了不少幸存者。"
D.Strings[60884]="好吧，我早就厌烦这下水道了。"
D.Strings[60885]="你不用告诉我两次。在这城里我欠了许多债，我不想还了。"
D.Strings[60886]="你可能想问，然后发生了什么？"
D.Strings[60887]="然后精灵游侠的手下都被干掉了！噢！"
D.Strings[60888]="他气疯了，兄弟，真的疯了！"
D.Strings[60889]="他仍然效忠部落酋长，但是他想干点与众不同的事情。"
D.Strings[60890]="加尔鲁什只注重力量！而洛瑟玛更在乎战略。"
D.Strings[60891]="就连泰克泰克这样单纯的猢狲都看出来了！"
D.Strings[60892]="哦，看呀，我们到了。回头见！"
D.Strings[60893]="你的皇帝谷之旅如何呀，无毛怪？"
D.Strings[60894]="那儿可真冷，而且很危险！"
D.Strings[60895]="还有好多魔古族。只有那些笨蛋高山猢狲亲戚们才会住在那里。"
D.Strings[60896]="他们真是蠢死了！"
D.Strings[60897]="我听说你找到了什么东西……还是什么人来着？你抓到了个魔古族，是不是？"
D.Strings[60898]="也许坏蛋魔古族会告诉你那口钟在哪儿。"
D.Strings[60899]="谢谢你的警告。一路平安。"
D.Strings[60900]="我走了。Shorel'aran."
D.Strings[60901]="泰克泰克还听说魔古族会使用黑暗魔法。"
D.Strings[60902]="我们猢狲叫它……伊克！你们叫它煞，但是伊克这个名字要好得多！"
D.Strings[60903]="不管怎样，那些疯狂的魔古族会使用伊克魂能。"
D.Strings[60904]="即使是最笨的猢狲都知道伊克比什么东西都坏。别吃烂东西，也别碰伊克！"
D.Strings[60905]="你觉得“该死的”是脏话？你伊克的什么都不知道。"
D.Strings[60906]="我可不想乘一只风筝飞到银月城！你疯了吗？"
D.Strings[60907]="哟。"
D.Strings[60908]="很久没见了，无毛怪。最近好吗？"
D.Strings[60909]="泰克泰克听到了很多。每个人都想，哦，泰克泰克是个笨猢狲，他啥都不懂。"
D.Strings[60910]="但是泰克泰克知道的可不少！"
D.Strings[60911]="还有那个大个子兽人将军，纳兹戈林！"
D.Strings[60912]="泰克泰克还知道……"
D.Strings[60913]="精灵游侠洛瑟玛正在考虑脱离部落！"
D.Strings[60914]="贝恩则怀疑加尔鲁什是否合适当酋长。"
D.Strings[60915]="加尔鲁什找不到那口该死的钟，他已经快没耐心了。魔古族可真会藏东西！"
D.Strings[60916]="我听说，加尔鲁什要折磨那个魔古囚犯，除非他开口。"
D.Strings[60917]="不管怎样，你得做你该做的。"
D.Strings[60918]="你不应该插手的。"
D.Strings[60919]="要是你找到什么东西，一定要告诉我，伙计！"
D.Strings[60920]="你知道吗，营地里的人都在谈论你。"
D.Strings[60921]="还有我，泰克泰克，我是你的好朋友！赞！"
D.Strings[60922]="部落营地热火朝天，每个人都在干活。"
D.Strings[60923]="既然你阅读了单简的记忆，他们一定会派出侦察队。"
D.Strings[60924]="好像他们现在已经知道魔古族把那口钟藏在哪里了。"
D.Strings[60925]="祝你好运。我希望你能够找到那口钟。"
D.Strings[60926]="我可不会乘着风筝去达纳苏斯，无毛怪。我都不知道那地方在哪儿！用那儿的传送门吧。"
D.Strings[60927]="你觉得我知道达拉然在哪，$G伙计:姑娘;？我连自己的尾巴都不知道在哪儿！有时候找得到它，有时候找不到。$B$B但是你知道我听说了什么吗，$n？$B$B我听到的都是真的。$B$B我听说你去了趟达纳苏斯，拿到了那口圣钟。$B$B但是那个人类女人……吉娜什么的……她被气疯了！$B$B她说部落背叛了她的信任，还说什么要把你们的人民赶出她的城市！$B$B兽人将军纳兹戈林说，我们必须帮助他们撤……撤走……撤退……撤离……呃……反正就是带他们离开！"
D.Strings[60928]="我听到的都是真的。"
D.Strings[60929]="我听说你去了趟达纳苏斯，拿到了那口圣钟。"
D.Strings[60930]="但是那个人类女人……吉娜什么的……她被气疯了！"
D.Strings[60931]="兽人将军纳兹戈林说，我们必须帮助他们撤……撤走……撤退……撤离……呃……反正就是带他们走！"
D.Strings[60932]="我对这事儿感觉很不好。"
D.Strings[60933]="你们的酋长得到了那口钟，然后用它来使得部落变得更加强大。"
D.Strings[60934]="但我觉得那口钟有股力量……不好的力量。"
D.Strings[60935]="它让我有种说不出的难受！"
D.Strings[60936]="没有人，没有猢狲，没有人类，没有兽人……可以利用煞能。"
D.Strings[60937]="伊克会把这片土地弄坏的。"
D.Strings[60938]="小心点。"
D.Strings[60939]="我希望能再见到你，朋友。"
D.Strings[60940]="他们从下方攻击我们的舰船，随时都有可能抢先占据要塞！\n\n我们没有足够的兵力去阻止他们……"
D.Strings[60941]="加入我们吧。|cFF0008E8（泰勒上将会跟随你。）|r"
D.Strings[60942]="我们将誓死守卫雄师港！"
D.Strings[60943]="你太多管闲事了！"
D.Strings[60944]="别插手这事！"
D.Strings[60945]="你以为自己是谁？"
D.Strings[60946]="干得不错啊——受死吧！"
D.Strings[60947]="夺日者都是渣滓！"
D.Strings[60948]="为了银色盟约！"
D.Strings[60949]="我们绝不容许你横加干预！"
D.Strings[60950]="你也想来尝尝苦头？很好！"
D.Strings[60951]="肯瑞托怎么能这样把我们赶出去？"
D.Strings[60952]="我的剑已经尘封多年，看来是时候把它擦亮了……"
D.Strings[60953]="他们会为此付出代价。"
D.Strings[60954]="我要前往达拉然。"
D.Strings[60955]="抓紧时间，$n，但你仍要万分小心。虽然时间紧迫，但是如果你死了，这个任务也就失败了。"
D.Strings[60956]="我想要去卡桑琅丛林。"
D.Strings[60957]="来吧，姑娘们。这是你们今天的肉。"
D.Strings[60958]="再见了，达拉然……"
D.Strings[60959]="谢谢你，$n。我们银月城见……"
D.Strings[60960]="希望部落还有我这个法师的立足之地……"
D.Strings[60961]="吉安娜靠武力夺走了我的家园？我会记住这一切的……"
D.Strings[60962]="你在看什么？我的鞋子？"
D.Strings[60963]="我需要一个通往达纳苏斯的传送门。"
D.Strings[60964]="我们现在找钟去。"
D.Strings[60965]="带我去双月殿。"
D.Strings[60966]="带我去滨岸村。"
D.Strings[60967]="带我去魔古岬。"
D.Strings[60968]="带我去加尔鲁什尔先锋营。"
D.Strings[60969]="带我去寇茹废墟。"
D.Strings[60970]="带我去帝皇之域。"
D.Strings[60971]="哎呦！今天我真是激动死了。就刚才我从那堆火里炼了八块铁。"
D.Strings[60972]="希尔达把所有的文件都给我了。你知道吗，我们每找到一个神器，我就要填六份表格！我想知道，这些该死的文件到底有什么用！？"
D.Strings[60973]="好像嫌我手头的麻烦事儿还不够多似的，那帮矿洞里的矮人最近迷上了一种叫咔啡的新饮料。$B$B他们一定要让我每天早上给他们带去新鲜的咔啡！$B$B他们知道我应该上哪儿去弄那些咔啡豆吗？行行好吧！"
D.Strings[60974]="我在执行行政管理的时候得穿上漂亮的短裤，但是其他的呢？能来点儿有新意的吗？"
D.Strings[60975]="哦天呐，是你吗？你一定就是那个每个人都在谈论的英雄。"
D.Strings[60976]="喔，在这种东西上飞行，你们是怎么做到的？圣光在上！你们这小手艺可太拉风了！"
D.Strings[60977]="抱歉，我在这儿还有点事情要做。"
D.Strings[60978]="我姐姐希尔达告诉我你会来。"
D.Strings[60979]="她不让我下挖掘场，所以我就成了私人助理和司机。"
D.Strings[60980]="不管怎样，我遇到了那个退役的军情七处特工。"
D.Strings[60981]="特工康奈利，对不？那个男的很有魅力……还很有胆量！他的甜言蜜语让我的脸羞得比铁炉堡的铁砧还红！"
D.Strings[60982]="他现在正在任务现场等着你。"
D.Strings[60983]="不过我们的目的地离一个部落营地很近，所以你一定要多加小心。"
D.Strings[60984]="代范妮向康奈利问好！"
D.Strings[60985]="你想要去达拉然？我听说吉安娜·普罗德摩尔正想见你！这条路直走，穿过那个法师传送门吧。"
D.Strings[60986]="好吧，我们又见面了。"
D.Strings[60987]="我想你过得还不错？"
D.Strings[60988]="你听说雄师港最近闹得沸沸扬扬的传闻了吗？"
D.Strings[60989]="听说部落掌握某种远古魔古族神器的信息……一个名叫圣钟的东西。"
D.Strings[60990]="那口钟能够把普通的军队变成杀戮机器！"
D.Strings[60991]="没人知道那个神器被藏在哪里，但是部落正在动用一切力量，想要先下手为强。"
D.Strings[60992]="神圣遗物学会正在魔古岬努力搜寻这口钟的下落。"
D.Strings[60993]="我们可不是没用的笨蛋，一定要打败他们！"
D.Strings[60994]="我只是希尔达的助理，能力有限。但是你能做的有很多。希望你能发现他们的动向。"
D.Strings[60995]="我们到了。"
D.Strings[60996]="好好教训那些部落！"
D.Strings[60997]="我将要把你送往七星殿。"
D.Strings[60998]="年轻的安度因王子正在等你。"
D.Strings[60999]="探险者协会在魔古岬完成勘探任务之后，他们把发掘出来的东西都带回了锦绣谷的城市里。"
D.Strings[61000]="他们正在研究那些被血精灵偷走的古物。"
D.Strings[61001]="本来这事儿我不应该告诉任何人的，但是你的脸长得就像矮人酒桶这么可爱，一定是个好人，所以我相信你！"
D.Strings[61002]="那些魔古族属于一个叫做寇茹的部族。"
D.Strings[61003]="寇茹部族好像在数千年以前就效忠于雷电之王……比熊猫人统治这片土地更早。"
D.Strings[61004]="他们钻研暗影法术，然后……通过某种方法，他们开始能够控制煞能。"
D.Strings[61005]="如果寇茹部族真的拥有这种能力，那就不难设想加尔鲁什为何要获得他们的知识了！"
D.Strings[61006]="想象一下，那个凶狠难缠的加尔鲁什在挥动他的大斧子的时候还能运用煞能，接下来会发生什么。"
D.Strings[61007]="我想到就会发抖。"
D.Strings[61008]="你已经到了。祝你好运！"
D.Strings[61009]="你好，今天过得怎样？"
D.Strings[61010]="自从上次我把你送到之后，我听说一些在七星殿的士兵们被煞能感染了。"
D.Strings[61011]="如果你和安度因王子不在那儿的话，他们可能就会自相残杀，我们最好的战士们可能就会被他们自己的愤怒击败！"
D.Strings[61012]="我还听说，瓦里安国王发誓不会利用煞能做不光彩的事。"
D.Strings[61013]="但愿他不是因为没吃到葡萄就说葡萄是酸的！我们的国王能有这样的表态就很不错啦。"
D.Strings[61014]="不管怎样，特工康奈利托口信让我送你到昆莱山去见他。"
D.Strings[61015]="听上去部落就快要找到那口圣钟的地点了，那可不是什么好事。"
D.Strings[61016]="你最好在任务现场和他碰面，看看加尔鲁什在干什么。"
D.Strings[61017]="快上风筝！"
D.Strings[61018]="我们没时间可以浪费了。"
D.Strings[61019]="为了找到你在那个魔古族记忆里看到的场景，我们找遍了昆莱山，最终，我们发现了那个隐蔽的寇茹部族处所。"
D.Strings[61020]="如果我们不能抢先得到那口圣钟，那个坏心眼的疯子加尔鲁什就会把它占为己有。我无法想象控制邪恶煞能的部落打起架来有多厉害。"
D.Strings[61021]="指挥官天剑已经在挖掘场和一小队探险者协会的考古学家开展工作了。"
D.Strings[61022]="我们将派出精英部队，那也包括你。"
D.Strings[61023]="我们到了。没时间可以浪费了。"
D.Strings[61024]="我可不会乘着风筝去达拉然！我都不知道吉安娜把那城市飘到哪儿了！你最好使用那边那个传送门。"
D.Strings[61025]="我可不会乘着风筝去达纳苏斯！那东西要飞过山脉都很难，你还指望它飞过整片海域？你最好使用那边那个传送门。"
D.Strings[61026]="嘿，泰勒上将让我载你一程，把你送到帝皇谷。"
D.Strings[61027]="你真幸运，我是安度因王子手下最能干的姑娘。我们是好朋友，但是可别把这告诉特工康奈利。"
D.Strings[61028]="那个男人肯定会非常嫉妒，而我可不想他为了我和王子闹矛盾。"
D.Strings[61029]="不管怎样，我知道王子躲藏在哪里，我会把你送到他那儿去的。"
D.Strings[61030]="虽然我不赞成让那个男孩子到处自个儿乱跑，但我能理解他的想法。"
D.Strings[61031]="我还是无法相信，我们在达纳苏斯做好了完全的准备，部落竟然还是偷走了圣钟。"
D.Strings[61032]="听说吉安娜女士到现在还在对这事儿震惊不已。"
D.Strings[61033]="她已经准备好原谅部落在塞拉摩的所作所为。"
D.Strings[61034]="她已经准备好为肯瑞托创造一个崭新的未来，让部落的夺日者和联盟的银色盟约能够在一起和平共处。"
D.Strings[61035]="我亲耳听到她说，达拉然将向世界展示一个部落与联盟和平共处的典范。"
D.Strings[61036]="然后夺日者竟然背叛了她的信任，在她的城市里直接开启传送门，通往安放那口圣钟的地方！"
D.Strings[61037]="她当然会感到气愤啦。她当然有权利把那些卑鄙的夺日者赶出达拉然。"
D.Strings[61038]="然而我仍然不由地觉得部落不会就此善罢甘休。"
D.Strings[61039]="现在加尔鲁什已经得到了圣钟。他随时就会对我们发动攻击！"
D.Strings[61040]="希望安度因心中已有打算。"
D.Strings[61041]="是你该登场的时候了。末日正在逼近。"
D.Strings[61042]="加尔鲁什正在昆莱山的北侧扩充他的军队。"
D.Strings[61043]="他将会使用圣钟的力量，如果我们不能及时阻止他，那只能祈求圣光保佑我们了。"
D.Strings[61044]="安度因已经先走一步了。那个冒冒失失、莽撞性急的小笨蛋！"
D.Strings[61045]="这孩子天真的以为他可以说服部落，拯救世界……可是……他只是个孩子。"
D.Strings[61046]="你要么阻止那孩子，要么就帮帮他……二选一！"
D.Strings[61047]="我们正在集结军队来对抗加尔鲁什，但是那需要时间，而王子可能已经身处险境。"
D.Strings[61048]="哦，为什么这风筝不能飞快点儿呢？"
D.Strings[61049]="快，他们还没发现我们。"
D.Strings[61050]="我回去呼叫援军。"
D.Strings[61051]="无论今天你成功与否，英雄，你做得一切都是为了联盟。"
D.Strings[61052]="啊！我把我的家当都压在那个上面了！"
D.Strings[61053]="不！不不不！"
D.Strings[61054]="我输了？不，你才输了！"
D.Strings[61055]="那可是板上钉钉的事儿啊！我全都押上了！"
D.Strings[61056]="怎么……搞什么啊……该死！"
D.Strings[61057]="该我们登场发挥了，把暴风城踩烂吧！"
D.Strings[61058]="这地方已经挤满了！我们应该组起队伍，往瓦里安漂亮的小脸蛋儿上来上几脚！"
D.Strings[61059]="如果你如此渴望鲜血，为什么不组起队伍，把暴风城砸烂？"
D.Strings[61060]="传送门就在这儿！穿过这门，告诉他们部落是怎么打架的！"
D.Strings[61061]="我开启了一道通往暴风城的传送门。穿过它，猛踹联盟的屁股！"
D.Strings[61062]="传送门准备好了！快进去！"
D.Strings[61063]="联盟全明星，人气爆棚！让我们把奥格瑞玛踩平吧！"
D.Strings[61064]="你们想来点儿带劲儿的？让我们去部落的地盘找点儿乐子！"
D.Strings[61065]="别再保持优雅的风度了，奥格瑞玛等着我们去踩平呢！"
D.Strings[61066]="我开启了一道通往奥格瑞玛的传送门。谁想要猛踹部落的屁股？"
D.Strings[61067]="奥格瑞玛传送门已经开启，搏击粉丝们！告诉他们是“泡泡”送你们来的。"
D.Strings[61068]="有人预定了通往奥格瑞玛的传送门吗？没有？怎么可能！"
D.Strings[61069]="%s现在能够入眠了。"
D.Strings[61070]="带我去巴塔尔火营。"
D.Strings[61071]="带我去达拉然。"
D.Strings[61072]="带我去七星殿。"
D.Strings[61073]="带我去达纳苏斯。"
D.Strings[61074]="你好啊，幸运儿。你喜欢看数据？$b$b我对这里进行的每场比赛都进行跟踪。我可以告诉你每个挑战者赢过多少场比赛。$b$b它们可能会派上用场，特别你想要……我是说……通过对一些比赛的预测来获取一些……实际利益。你懂我的意思？"
D.Strings[61075]="查看等级1-2首领的战斗记录。"
D.Strings[61076]="查看等级3-4首领的战斗记录。"
D.Strings[61077]="查看等级5-6首领的战斗记录。"
D.Strings[61078]="查看等级7首领的战斗记录。"
D.Strings[61079]="返回。"
D.Strings[61080]="血柄督军准备施放嗜血打击！"
D.Strings[61081]="嘿$c，你想要去暴风城？我的传送门最便捷！但如果你没有委任状的话，你就只能自己去那儿了。"
D.Strings[61082]="带我去银月城。"
D.Strings[61083]="我早就想和夺日者划清界限了，只是一直在等待这样的机会。我曾向我过世的丈夫提过将他们赶出达拉然，但是他决意要把肯瑞托放在绝对中立的位置。$b$b他是个睿智的人，但是远见不足。肯瑞托的命运就应当如此：效忠联盟。"
D.Strings[61084]="我准备好前往潘达利亚了。"
D.Strings[61085]="暗夜精灵建筑营地遭到攻击！"
D.Strings[61086]="我们的船只！这到底是怎么回事？！"
D.Strings[61087]="我终于自由了！反叛的臭猴子们，我终于摆脱你们了。"
D.Strings[61088]="帝国……必将……再度崛起。"
D.Strings[61089]="我要把你从生死簿上除名！"
D.Strings[61090]="有本事就把我从这里赶出去！"
D.Strings[61091]="为了夺日者！"
D.Strings[61092]="所以必须做个了断了，对吧？"
D.Strings[61093]="该死……银色盟约的人也来了。"
D.Strings[61094]="但愿能成功。根据我的调查，这个青玉战神不是什么好东西。准备好战斗吧。"
D.Strings[61095]="这个屋子在旋转？"
D.Strings[61096]="……*嗝*"
D.Strings[61097]="我的酒洒啦！"
D.Strings[61098]="能请我喝一杯吗？"
D.Strings[61099]="没错，布鲁姆就是我的爱人，我们俩就像是一个豆荚里的两颗豆子，即使他是轻量级选手，我也一样爱他！"
D.Strings[61100]="你有话和我说？没问题，你负责说，我负责喝！"
D.Strings[61101]="你最好别相信我说的任何话。算了，当我没说过。"
D.Strings[61102]="啊，没错，那些关于我的谣言满天飞，可惜都是假的。什么我小时候是暗月马戏团的吉祥物，五岁生日那天杀了六个恶魔——用的还是一把勺子——我最喜欢这段了。但事实上，我只是个普通的金发姑娘。人们就喜欢相信那些有的没的。"
D.Strings[61103]="我喜欢这个地方。在别的地方，那些人总是叫我“暴力孤僻女”。好吧，其实在这儿他们也这么叫我，不过至少他们是当着我的面，并且面带着微笑地叫这个名字。"
D.Strings[61104]="我闻起来像不像火腿？"
D.Strings[61105]="我过敏了，得吃点药。"
D.Strings[61106]="前几天的一个晚上，有人扔了个球过来，还叫我去捡。我照他说的做了，只不过把球和他脑袋一起扔回去了。不用说，他没接着那个球。"
D.Strings[61107]="我总是为血角欢呼。那头愤怒的铲齿鹿看似娇小，却总是能让那些大块头吃尽苦头。"
D.Strings[61108]="城市生活会改变一名德鲁伊。上周我生平第一次使用了公共飞行路线……感觉真是不错啊。"
D.Strings[61109]="大多数德鲁伊都很古板，不过我是个例外，我是个真正的聚会动物。我的笑话说完了。你该笑了。"
D.Strings[61110]="我能轻松打断四层强化松木板，只是要借用一下你的脑袋。要我给你做个示范吗？"
D.Strings[61111]="我不知道为啥这么多武僧都把酒桶乱扔。真浪费。"
D.Strings[61112]="当然，我会上场的，等我把这两桶酒喝完。"
D.Strings[61113]="啊，对不起，我不能请你喝酒了。我最近有点小穷，但我相信我会时来运转的。"
D.Strings[61114]="这地方看起来很硬派，但这里的人其实内心里都是软蛋。"
D.Strings[61115]="哦，没错，我刚到奥格瑞玛不久。这不明摆着的吗？"
D.Strings[61116]="你应该排队参加搏击——这样我就能笑上好一阵了。"
D.Strings[61117]="继续瞪着我。我喜欢尴尬的沉默。"
D.Strings[61118]="弱者才穿鞋。"
D.Strings[61119]="上一回我在竞技场里把对手打到边哭边逃。按说对手打架打到一半就逃这不算什么稀奇事儿，但这可是我头一回看到鳄鱼流眼泪。"
D.Strings[61120]="“娜丽，把这东西举起来！”，他们总是这么冲我嚷嚷。为什么不能说“娜丽，能跳支舞吗？”我可是个伟大的舞者。"
D.Strings[61121]="斯特林顿公爵就是个渣渣。他吹牛吹得厉害，但连自己的剑都拿不起来。啊，没错，他的名字也是瞎编的，我相信你肯定猜到了。"
D.Strings[61122]="你想吃拳头了，笨蛋？"
D.Strings[61123]="昨晚我教训了三个兽人和一个牛头人，连一根指甲都没刮花。"
D.Strings[61124]="你搬过东西吗，兄弟？"
D.Strings[61125]="不，那是我的大腿骨，但是我见到你很高兴。"
D.Strings[61126]="小鸡就喜欢啄伤疤，所以你知道为啥我这么受女士们欢迎了吧。"
D.Strings[61127]="你喜欢眼前这一切吗？你当然喜欢了。"
D.Strings[61128]="为什么每个人都知道我的名字？"
D.Strings[61129]="我很想抱抱你。"
D.Strings[61130]="掩护我，伙计。"
D.Strings[61131]="睁大你的眼睛。"
D.Strings[61132]="跟紧我。"
D.Strings[61133]="小心——那里有东西。"
D.Strings[61134]="啊……陛下？"
D.Strings[61135]="抱歉。我的名字叫安度因·乌瑞恩。我和这位勇士需要你的帮助。"
D.Strings[61136]="谢谢你。但现在可不是开派对的时候。一个穷凶极恶的军阀已经找到了圣钟，他的名字叫加尔鲁什。我们需要祥和钟杵来对抗他。"
D.Strings[61137]="而且，调查显示你是最后一个——"
D.Strings[61138]="这会有所帮助。"
D.Strings[61139]="继续战斗。"
D.Strings[61140]="万灵与你同在。"
D.Strings[61141]="用这个治疗你！"
D.Strings[61142]="把他拖进陷阱！"
D.Strings[61143]="把他引到陷阱里！"
D.Strings[61144]="我设了个陷阱。"
D.Strings[61145]="把他引到陷阱里来！"
D.Strings[61146]="别让这些野兽靠近我！"
D.Strings[61147]="又来了。"
D.Strings[61148]="干掉那个巫师！"
D.Strings[61149]="让那些畜生离船远点！"
D.Strings[61150]="喔吼！一个大王的儿子！手脚发麻。手脚发麻。腿没睡醒。手没睡醒。脑袋也没睡醒。"
D.Strings[61151]="这似乎是某种孵化室……"
D.Strings[61152]="小心！洞顶塌了！"
D.Strings[61153]="喔？陛下？我可不是什么皇帝，小家伙。我是美猴王！"
D.Strings[61154]="这些生物不太正常。"
D.Strings[61155]="帮助？你把我从玉石里救出来了，不用一直被关着了！我要为你开一个最最大的派对！"
D.Strings[61156]="这就是我们要找的地方。"
D.Strings[61157]="酋长发现魔古族与这些生物密切相关。"
D.Strings[61158]="巨魔！你最了解这……巫毒玩意儿了。有何发现？"
D.Strings[61159]="哦……那个丢失的祥和钟杵，是吗？真是个傻名字。那么你来找到美猴王，是要问罪于他？"
D.Strings[61160]="“巫毒玩意儿”"
D.Strings[61161]="啊哈哈哈！别担心，你来对地方了。但是先让我看看你的面相是不是讨喜。"
D.Strings[61162]="掩护我，我要调查一下……"
D.Strings[61163]="这些“魔古族”，在这里施了邪法。"
D.Strings[61164]="蜥蜴人不是天生的——而是创造出来的。是扭曲成形的血肉。"
D.Strings[61165]="这是最黑暗的魔法，伙计！"
D.Strings[61166]="没错！能制造战士的血肉塑形之力。这……正合酋长之意！"
D.Strings[61167]="加尔鲁什想成为神？制造怪物？这有违部落精神！"
D.Strings[61168]="他早知道你是个叛徒。"
D.Strings[61169]="救——救命——"
D.Strings[61170]="酋长之敌必亡！"
D.Strings[61171]="酋长……亮出了底牌。"
D.Strings[61172]="破坏阀门。"
D.Strings[61173]="这就是部落的现状？自相残杀？我们不能坐视不理。"
D.Strings[61174]="勇士，我需要你。"
D.Strings[61175]="回去找酋长。告诉他我死了。跟紧他。看着他。"
D.Strings[61176]="你和我，我们将在适当的时机推翻他。"
D.Strings[61177]="还有和我一样的人。去找他们。"
D.Strings[61178]="跟我发下血誓。"
D.Strings[61179]="好。你我结成兄弟。直到末日。"
D.Strings[61180]="我得消失一段时间了。别忘了我。"
D.Strings[61181]="我会试着带这个“美猴王”回到雄师港，看看能不能说服他告诉我们所需要的信息。同时，我也会尽力解答他的谜题，在那儿和我们碰头吧。"
D.Strings[61182]="部落的畜生！你们杀了我唯一的儿子！！"
D.Strings[61183]="为了巴尔莫丹！"
D.Strings[61184]="这就对了，你们这些乌合之众！我这就证明给大家看，你们部落就是一堆羊屎！"
D.Strings[61185]="炮弹！！"
D.Strings[61186]="你们这些……畜生……*呸*"
D.Strings[61187]="你毫无机会。"
D.Strings[61188]="什么？这怎么可能！"
D.Strings[61189]="让我们给其他人一点机会，让他们也搞点破坏！"
D.Strings[61190]="你真以为你所有的宠物都能活下来？"
D.Strings[61191]="不！那可是我最喜爱的宠物！"
D.Strings[61192]="这就是说加尔鲁什也在寻找那个叫做圣钟的东西？不管那是什么，一定不是个好东西。我会让总部知道这个消息的。"
D.Strings[61193]="干得好！我很快会再联系你。"
D.Strings[61194]="嗤！嘿，在这儿，是我，特工康奈利！"
D.Strings[61195]="棍子就是力量！棍子就是我的力量！"
D.Strings[61196]="盎迦猴岛是我的！"
D.Strings[61197]="美猴王早就死了！他是个冒牌货。"
D.Strings[61198]="盎迦，我把这根棍子给你们是为了保护你们，不是给你用来该死的耍流氓的！"
D.Strings[61199]="盎迦，棍子不是给你玩的，把它给我，不然它会把你也毁了。"
D.Strings[61200]="我们要返回雄师港了。你准备好以后和我们在那里碰头。"
D.Strings[61201]="<卡拉克西瓦·伊克用审视的眼神注视着你。>"
D.Strings[61202]="你准备好见证历史了吗，唤醒者？"
D.Strings[61203]="我们遭到攻击！"
D.Strings[61204]="有飞弹打过来了！护盾！护盾！"
D.Strings[61205]="使用力场护盾挡住飞弹。"
D.Strings[61206]="你被击中了！我们正在失去你的信号！"
D.Strings[61207]="他们盯上你了！护盾！护盾！"
D.Strings[61208]="这就叫探囊取物！"
D.Strings[61209]="这太简单了！"
D.Strings[61210]="填弹完毕，锁定目标！"
D.Strings[61211]="苏利，快下来！"
D.Strings[61212]="苏利，我真希望你再掉进那滩泥里！"
D.Strings[61213]="……这是丑恶的谋杀！"
D.Strings[61214]="这就是你的忠诚？"
D.Strings[61215]="地狱咆哮的部落要求绝对的服从……"
D.Strings[61216]="酋长必将发现这次背叛！"
D.Strings[61217]="地狱咆哮……会知道的……"
D.Strings[61218]="力量！"
D.Strings[61219]="愤怒！"
D.Strings[61220]="……死亡！"
D.Strings[61221]="藏好尸体！"
D.Strings[61222]="好吧，这次我去。但这是我最后一次潜入部落！我说真的。"
D.Strings[61223]="我现在要去准备补给，再找点儿过去的线人。要是在潘达利亚我有需要你的地方，我会来找你的！"
D.Strings[61224]="明白了。"
D.Strings[61225]="我们来搞点破坏吧。"
D.Strings[61226]="荣耀与忠诚。"
D.Strings[61227]="酋长会奖赏你的忠诚。"
D.Strings[61228]="附近的一群暗生幼嗣孵化了！"
D.Strings[61229]="格里兹尔给了你一把便携死亡射线枪！用它对附近的蜥蜴人卵使用。"
D.Strings[61230]="格里兹尔给了你一把地雷！用它对附近的蜥蜴人卵使用。"
D.Strings[61231]="格里兹尔给了你一把便携集束火箭！用它对附近的蜥蜴人卵使用。"
D.Strings[61232]="在你穿过洞穴的时候，使用船只的技能来抵挡蜥蜴人的进攻。"
D.Strings[61233]="暗生蜥蜴领主开始剧烈地旋转。"
D.Strings[61234]="孵化大师诺什开始施放大规模的死亡新星。赶快躲进终极巫毒术的效果范围内！"
D.Strings[61235]="孵化大师诺什被钟乳石击晕了！"
D.Strings[61236]="瞄准那些琥珀炸弹，只要设法把其中一个引爆，它们就会造成剧烈的爆炸！"
D.Strings[61237]="孵化大师诺什开始孵化一群暗生幼嗣！"
D.Strings[61238]="那些蝎子在移动塔楼！消灭它们！"
D.Strings[61239]="孵化大师诺什开始向四周所有物体汲取能量！"
D.Strings[61240]="钟乳石从洞顶纷纷坠落！"
D.Strings[61241]="没剩下几座塔楼了，那东西马上就要被打垮了！"
D.Strings[61242]="根据斥候的报告，这座岛屿上有几部护盾发生器，它们为护盾提供能量。"
D.Strings[61243]="我需要你赶在部落冲垮我们的防线之前摧毁这些发生器。"
D.Strings[61244]="你接近第一座发射塔了！炸掉它！"
D.Strings[61245]="我这就将下一座发射塔的坐标发送给你。"
D.Strings[61246]="护盾消失了！赶快前往滩头！"
D.Strings[61247]="阻止那些部落！他们在抢占这座岛屿！"
D.Strings[61248]="帮助建造五座防御工事中的至少两座。"
D.Strings[61249]="胆小鼠辈！"
D.Strings[61250]="瓦里安……我……辜负……了你。"
D.Strings[61251]="瓦里安将为这场胜利表彰我！"
D.Strings[61252]="你的力量在加尔鲁什面前不值一提！"
D.Strings[61253]="扎尼维斯不会陷落！"
D.Strings[61254]="你来这儿就是为了送死？"
D.Strings[61255]="扎尼维斯会被你的鲜血染红！"
D.Strings[61256]="女皇……"
D.Strings[61257]="部落不可阻挡！"
D.Strings[61258]="你是联盟真正的英雄！"
D.Strings[61259]="你是部落真正的英雄！"
D.Strings[61260]="拉克戈尔投下了一枚毒气炸弹。站在治疗结界里治疗你自己！"
D.Strings[61261]="你的装束简直不堪入目！"
D.Strings[61262]="我想说的是：你太胖了。"
D.Strings[61263]="我可不会给一头座狼上菜！"
D.Strings[61264]="也许你可以多做点菜，少吃点，嗯？"
D.Strings[61265]="我想这肉已经变质了。哦等等，这味道是你发出来的！"
D.Strings[61266]="你想穿着这个做菜？"
D.Strings[61267]="你有预定吗？"
D.Strings[61268]="不穿外套和靴子的不能享受服务！"
D.Strings[61269]="准备好用火烹饪了吗？"
D.Strings[61270]="和我们一起战斗。|cFF0008E8（安玻会跟随你。）|r"
D.Strings[61271]="为了治疗这些伤者，我已经尽了全力。能救的我都救了。\n\n我要留下来保护这些受伤的士兵……除非你有更好的计划？"
D.Strings[61272]="和我们一起战斗。|cFF0008E8（米希卡会跟随你。）|r"
D.Strings[61273]="如果血柄认为一点点援军就足够攻下雄师港，那他就大错特错了！"
D.Strings[61274]="来得也正好。这位就是进攻指挥官！"
D.Strings[61275]="做好准备，小伙子们！"
D.Strings[61276]="诺德和尼姆在部落进攻时进了潜水艇。\n\n但我依然能够合理利用他们的装备和炸药。\n\n我们可以在前线阵地建立防线。"
D.Strings[61277]="和我们一起战斗。|cFF0008E8（苏利会跟随你。）|r"
D.Strings[61278]="开始干活吧！"
D.Strings[61279]="该行动了。"
D.Strings[61280]="我们都准备好了。"
D.Strings[61281]="我的指挥官们不是死了就是失踪了。"
D.Strings[61282]="从军情七处那里给我报告——部落还剩下多少人，我们还剩下多少人——然后帮助苏利建立防线。"
D.Strings[61283]="准备好！他们随时都有可能发起进攻。"
D.Strings[61284]="就这么打，小伙子们！他们又来了！"
D.Strings[61285]="战斗到底，小伙子们！决不放弃！"
D.Strings[61286]="打得好！这是他们最后一波攻势！为了雄师港！"
D.Strings[61287]="我们守住了！我们做到了！"
D.Strings[61288]="继续建造！$b$b一旦两座防御工事完成，进攻就将开始。"
D.Strings[61289]="|cFF00ff00+25建造进度|r"
D.Strings[61290]="地方这么多，时间这么少。去哪儿呢，$G兄弟:姐妹;?"
D.Strings[61291]="有股怪味儿。"
D.Strings[61292]="|cFF00ff00建造进度：速率提升！|r"
D.Strings[61293]="你终于来了，$n。什么都不做可赢不了这场战斗！"
D.Strings[61294]="|cFF00ff00+5建造进度|r"
D.Strings[61295]="部落必须肃清所有叛徒！"
D.Strings[61296]="我们要把所有异端从这群杂种中找出来，清除出去！"
D.Strings[61297]="库卡隆办事！没什么好看的。"
D.Strings[61298]="在任何防御工事使用劳工的工具来提升建造进度！$B$B|TInterface\\Icons\\INV_HAMMER_17.blp:64|t"
D.Strings[61299]="有些事情必须做好，哪怕它意味着要损失一些其他的东西！"
D.Strings[61300]="在任何防御工事使用作战给养来提升建造进度！$B$B|TInterface\\Icons\\INV_MISC_FOOD_WHEAT_02.blp:64|t"
D.Strings[61301]="我还记得我和沃金第一次踏上这片土地的时候。那时的部落还只是一个想法。一个憧憬。那时的我们需要彼此。"
D.Strings[61302]="我们在这片沙漠上建起了自己的家园，用我父亲霜狼氏族酋长杜隆坦的名字命名了它。"
D.Strings[61303]="这并非是一片慷慨的土地。一次又一次，是沃金和他的人民用食物拯救我们于饥饿，用武器保护我们于战乱，从而保全了部落。"
D.Strings[61304]="巨魔和兽人曾经并肩作战，生死与共。我们是一家人，家人就该彼此照料。"
D.Strings[61305]="在特定的建筑营地使用脆弱的根茎来加快他们的进度！$B$B|TInterface\\Icons\\INV_WEAPON_SHORTBLADE_09.blp:64|t"
D.Strings[61306]="在熊猫人建筑营地的爆烈酒大锅处使用丛林啤酒花来加快他们的进度！$B$B|TInterface\\Icons\\INV_MISC_HERB_08.blp:64|t"
D.Strings[61307]="在矮人或侏儒建造营地使用卡桑利生铁来加快他们的进度！$B$B|TInterface\\Icons\\INV_ORE_PLATINUM_01.blp:64|t"
D.Strings[61308]="在熊猫人建筑营地的爆烈酒大锅处使用燃烧剂来加快他们的进度！$B$B|TInterface\\Icons\\ABILITY_WARLOCK_BURNINGEMBERS.blp:64|t"
D.Strings[61309]="在任何一个建筑营地使用肥厚腰肉来加快他们的进度！$B$B|TInterface\\Icons\\INV_MISC_FOOD_50.blp:64|t"
D.Strings[61310]="但记住这一点，部落是所有部落人民的家，这个事实不会因为某些部落领袖忘记了它而改变。为了证明这一点，我会留在你们身边，并将我的力量借给你们挑选的领袖，直至沃金回归。"
D.Strings[61311]="在暗夜精灵或侏儒建筑营地使用蛇油来加快他们的进度！$B$B|TInterface\\Icons\\ABILITY_VEHICLE_OILJETS.blp:64|t"
D.Strings[61312]="灵吻之水能唤醒褐石大师，或者用来加快熊猫人或者暗夜精灵建筑营地的进度！$B$B|TInterface\\Icons\\INV_MISC_VOLATILEWATER.blp:64|t"
D.Strings[61313]="在矮人建筑营地使用哑火炮弹来永久提高他们的进度！$B$B|TInterface\\Icons\\ABILITY_VEHICLE_SIEGEENGINECANNON.blp:64|t"
D.Strings[61314]="和锦鱼人长老阿德勒交谈，他会使用缀饰权杖来显著提高锦鱼人营地的进度！$B$B|TInterface\\Icons\\INV_STAFF_2H_PANDARIATRADESKILL_C_05.blp:64|t"
D.Strings[61315]="和侏儒工头罗塞·轮轴交谈，她会使用浸水的日记来显著提高侏儒营地的进度！ $B$B|TInterface\\Icons\\INV_MISC_BOOK_11.blp:64|t"
D.Strings[61316]="单简的手畸变成了煞之爪！"
D.Strings[61317]="单简的眼睛闪耀着煞能的光芒！"
D.Strings[61318]="哟，朋友！有位英雄在释放我们的迅猛龙！"
D.Strings[61319]="别当叛徒，朋友！你休想再把我锁起来。"
D.Strings[61320]="我们暗矛巨魔不能被链子拴起来。你马上就会明白这一点了……"
D.Strings[61321]="沃金不会允许你这样质疑我们。"
D.Strings[61322]="休想这样对待我们，没脑子的库卡隆！"
D.Strings[61323]="你对即将降临的厄运一无所知！"
D.Strings[61324]="斯卡戈什不会放任何联盟逃出这片丛林！"
D.Strings[61325]="指挥官会把联盟国王的脑袋刺在长矛上！"
D.Strings[61326]="向你们的国王求救吧，$r！把他拖进来！"
D.Strings[61327]="你们敬爱的国王中了圈套！他会死在这片丛林里！"
D.Strings[61328]="我已经有太长的时间没有感受过情绪的波动了。"
D.Strings[61329]="我的利刃会拿你的鲜血当作今天的开胃点心，$c！"
D.Strings[61330]="欢迎来到丛林，$r。你们会死在这里！"
D.Strings[61331]="“煞”的能量似乎比我想的要强不少。"
D.Strings[61332]="那……那是什么？"
D.Strings[61333]="罗曼斯……我……我不知道我身上发生了什么事。"
D.Strings[61334]="正中眉心……"
D.Strings[61335]="让我们瞧瞧这个家伙流血的样子……"
D.Strings[61336]="对抗血精灵的都得死！"
D.Strings[61337]="国王，我保证。肯瑞托一定会让加尔鲁什受到最严厉的惩罚。血债必须血偿！"
D.Strings[61338]="我会亲自跟加尔鲁什做个了断。他的部落业已分崩离析。我们将作出致命一击。"
D.Strings[61339]="勇士，今天你和安度因挫败了部落酋长，为联盟赢得了关键的胜利。"
D.Strings[61340]="现在请你走吧，英雄。我要照顾我儿子……并准备下一场战斗了。"
D.Strings[61341]="这孩子的脸变得煞白。他几乎没有呼吸了。"
D.Strings[61342]="%s施放了|cFFFF0000|Hspell:135759|h[庇护之罩]|h|r来协助你！"
D.Strings[61343]="你怎么想？"
D.Strings[61344]="我们去和他谈谈。"
D.Strings[61345]="是的——肯瑞托不能卷入阵营的纷争中。"
D.Strings[61346]="我不确定。"
D.Strings[61347]="啊。这才是真正的战场的味道。我们孤军奋战的时间太长了。现在，部落将释放出全部的力量，而我们，将指引部落之力进攻的方向！"
D.Strings[61348]="你们这群可悲的联盟就这点能耐？呸！"
D.Strings[61349]="我们在南贫瘠之地摧毁了你们的军队。我们也将在这里取得胜利。整个潘达利亚都将颤抖！"
D.Strings[61350]="我们会把你们从这片海滩上赶回去。在那之后，所有熊猫人都会屈服于我们的力量！"
D.Strings[61351]="哈，你让我流血了。这不算什么。真正的兽人为战斗而生！"
D.Strings[61352]="酋长大人……我辜负了你……"
D.Strings[61353]="上面刻有一行字：“邪思难溢！”"
D.Strings[61354]="哈！不痛不痒！"
D.Strings[61355]="勇者无敌！"
D.Strings[61356]="雷霆天降！"
D.Strings[61357]="站在我面前的这是什么？"
D.Strings[61358]="好了，我们现在拿到了你要的杵柄，杵头和药膏。你能帮我们将钟杵组合起来吗？"
D.Strings[61359]="没错！笨小子，杵柄入杵头，钟杵重现世。"
D.Strings[61360]="就和新的一样！听好美猴王说的话。你的药膏只够敲一次钟。"
D.Strings[61361]="只能敲一次？一次真的就够了吗？我们有办法多找到一些药膏吗？"
D.Strings[61362]="上一次钟杵敲响圣钟的时候，美猴王就在旁边。美猴王热泪盈眶，但内心无比平静。在那之后，圣钟被魔古人夺走，再也没有人做过药膏了。心存感激，你手上的药膏就是最后的药膏。圣钟是危险的武器，一定要小心处理。"
D.Strings[61363]="这是什么黑暗魔法？"
D.Strings[61364]="别让它碰到你！"
D.Strings[61365]="她的传动设备还不能传动，但她的武器设备刚在流水线上组装完毕。"
D.Strings[61366]="宝贝，闪亮登场吧！"
D.Strings[61367]="我们就不能安静地工作吗？"
D.Strings[61368]="这地方让我感觉很不好。"
D.Strings[61369]="我们的援军呢？"
D.Strings[61370]="我们还能坚持多久？"
D.Strings[61371]="我不喜欢这种魔法的味道。"
D.Strings[61372]="朋友！如果你需要治疗，就来吸一口我的熏香！"
D.Strings[61373]="谢谢你，土地精的朋友！"
D.Strings[61374]="轮钳，你可真小，我很想你。"
D.Strings[61375]="云游者！如果你想快点结束战斗，就吸一口这熏香！"
D.Strings[61376]="感谢你！这是我最后一次在城墙的西边旅行。"
D.Strings[61377]="感谢你的帮助，朋友。按现在的速度，我们不久之后就能休息了！"
D.Strings[61378]="最近我们丢了一些酒。它们本来就在东边不远的地方……"
D.Strings[61379]="蜥蜴人喜欢收集战场上的破烂。他们身上带着什么东西都不奇怪。"
D.Strings[61380]="灵吻之水非常不稳定。每次只能携带一瓶。"
D.Strings[61381]="你应该总是随身携带一瓶灵吻之水，朋友。否则，我们……就会……打瞌睡。"
D.Strings[61382]="那些大猩猩看起来又愤怒又危险，朋友，但挑战他们总是能获得不错的回报！"
D.Strings[61383]="及时补充资源，别让它们耗尽了！"
D.Strings[61384]="过夜旅行什么的，最喜欢了！露营是我的最爱！"
D.Strings[61385]="我是个舞者。想要看看我跳舞吗？"
D.Strings[61386]="我不明白为什么其他人总是把我当小孩子对待！"
D.Strings[61387]="别烦我了！我一般要下午才起床。"
D.Strings[61388]="当我长大之后，我要当个歌手！"
D.Strings[61389]="哟哟哟切克闹！动次打次动次打次！$B$B你喜欢我的歌吗？"
D.Strings[61390]="正在清除会导致无法承受的悲伤情感的记忆数据……"
D.Strings[61391]="正在恢复出厂设定……"
D.Strings[61392]="遵命，小轮。"
D.Strings[61393]="也许这股能量可以被驾驭。我的人民……长久以来一直在控制内心的愤怒……"
D.Strings[61394]="干得好，$g小伙子:妹子;，你找到了些不错的东西。加油！"
D.Strings[61395]="这附近也许能找到一些哑火的炮弹。最近这片海滩上打了不少炮战……"
D.Strings[61396]="那些长得像蜥蜴一样的怪物身上总是带有一些稀奇古怪的东西。看到了就别错过！"
D.Strings[61397]="脆弱的根茎有时会暴露在土外。那些可是上好的木材。"
D.Strings[61398]="如果遭到进攻，生产就会停止。记得帮我们防守基地！"
D.Strings[61399]="看到你的信号弹我就第一时间赶来了！"
D.Strings[61400]="哦，不！安度因王子！"
D.Strings[61401]="别担心。我会把安度因平安送回雄狮港。我们回雄狮港见。"
D.Strings[61402]="那些蜥蜴人守着洞穴。我们得先对付他们。"
D.Strings[61403]="我可不是为了砍倒你这样的木桩子才成为伐木大师的！"
D.Strings[61404]="我的手艺……生锈了……"
D.Strings[61405]="你做得很好，$rt。你提高了我的工人们的效率。"
D.Strings[61406]="你让我们的工作效率提高了，$rt。按这个速度，我们的任务很快就会完成了。"
D.Strings[61407]="我们的进度迅如激流，朋友。你现在应该专注于让我们保持这样的速度。"
D.Strings[61408]="附近野兽身上的肉都可食用，$rt。去找些肉来喂饱那些工人吧。"
D.Strings[61409]="把你找到的食物都放到那边的桌子上吧，我们会自行取用。"
D.Strings[61410]="我们最主要的需求是食物和木材。如果你想要帮我们更多的忙，就和我谈谈吧。"
D.Strings[61411]="即使是在这片沼泽里也能找到可用的木材。去寻找那些暴露在土壤外的脆弱根茎吧。"
D.Strings[61412]="她来了！"
D.Strings[61413]="我的工人有着高超的建筑技艺，却并不擅长战斗。别跑得太远了。"
D.Strings[61414]="把补给物资送达之后，你的工作还没有结束。你需要保持我们的资源存量。"
D.Strings[61415]="如果敌人骚扰到了工人的工作，生产就会陷入停滞，直到你击退敌人的进攻。"
D.Strings[61416]="吉安娜！停下！"
D.Strings[61417]="我不会屈服于——"
D.Strings[61418]="我们不知道——"
D.Strings[61419]="你可以从野生动物身上找到肉，或者从兽人身上找到军粮。我们从不挑剔食物。"
D.Strings[61420]="那些蜥蜴怪身上可能带有各种各样的东西。别放过他们！"
D.Strings[61421]="为我们提供充分补给能让我们以最高效率工作。"
D.Strings[61422]="蛇油，卡桑利生铁，还有食物……记得帮我们小组寻找这些有用的物资！"
D.Strings[61423]="你可以为我们提供相同的道具补给来获得额外的特效。尽量保持这些特效，别让它们过期了。"
D.Strings[61424]="情况非常顺利，朋友。感谢你的援助。"
D.Strings[61425]="我们的资源储量充足，感谢你的帮助。请继续保持如此良好的势态。"
D.Strings[61426]="这里也是我们的家！你不能这样做！"
D.Strings[61427]="我们已经习惯于使用小精灵来进行体力劳动了。请带一些食物来帮助我们保持动力。"
D.Strings[61428]="我们特别不适应把野兽的肉当作食物，但在如今的特殊情形下，我们也只能勉为其难了。"
D.Strings[61429]="联盟女巫！"
D.Strings[61430]="附近的精怪身上携带有灵吻之水，这些水能够滋养我们的树苗。装满一次之后，你就不再需要去补充它们了。"
D.Strings[61431]="不要灰心，朋友。帮我们寻找补给，我们的工作很快就能完成。"
D.Strings[61432]="这里也是我的家！"
D.Strings[61433]="我不会屈服的！"
D.Strings[61434]="绝不投降！"
D.Strings[61435]="为我们的营地提供补给之后，请保持补给品的存量，不要让特效消失。"
D.Strings[61436]="所以……是联盟派你来的？"
D.Strings[61437]="以新手而言算是不错了。"
D.Strings[61438]="你的战斗技巧真心差劲，你应该感到羞耻。"
D.Strings[61439]="这就是你的攻击？我的奶奶都比你能打，她都已经过世了！"
D.Strings[61440]="就像个傻瓜一样站在那里吧，你最适合了。"
D.Strings[61441]="你比沾满了硫磺矿没洗的牦牛还要难闻。"
D.Strings[61442]="你可以做点让我们都吃惊的聪明举动，比如夹起尾巴逃走。"
D.Strings[61443]="我需要一个前往达拉然的传送门。"
D.Strings[61444]="和我们的人民一样，部落也一直在改变，一直在变革。但不用怀疑，我们会度过这黑暗的时代。"
D.Strings[61445]="让我们找到那些小偷！"
D.Strings[61446]="别停下，神圣遗物协会。我们会找到圣钟的。它会确保部落获得最终的胜利。我从骨子里相信这一点。"
D.Strings[61447]="当我拥有它之后，我自会考虑如何使用它，血精灵。"
D.Strings[61448]="圣钟是武器，它的力量无可置疑。它属于部落，属于我！"
D.Strings[61449]="我们接近了！所有文献都表明圣钟就在昆莱山。它肯定在这里。"
D.Strings[61450]="我们已经找了好几天，却只找到一些尘封的卷轴和破损的雕像。"
D.Strings[61451]="万一圣钟也年久失修了怎么办？就算我们能找到它，你确定它还能用吗？"
D.Strings[61452]="或许魔古族出于某些原因将圣钟藏了起来，酋长。"
D.Strings[61453]="把你的手拿开！"
D.Strings[61454]="我好像闻到了什么味道！"
D.Strings[61455]="你侵入了我们的地盘！"
D.Strings[61456]="你休想从我们手上夺走这片土地！"
D.Strings[61457]="加尔鲁什会砍掉你的脑袋！"
D.Strings[61458]="嘿，你！"
D.Strings[61459]="闭嘴，懦夫。你最好扪心自问一下自己效忠的是谁：是肯瑞托？还是部落？"
D.Strings[61460]="嗯？！入侵者！"
D.Strings[61461]="小偷！"
D.Strings[61462]="够了！你想让我去报告加尔鲁什，说你让我们向那个肯瑞托丫头低头吗？！"
D.Strings[61463]="抱抱……我们要抱抱……"
D.Strings[61464]="法利尔，这里出什么事了？我没有批准你们这么做。"
D.Strings[61465]="我真该对你倒竖大拇指，可我没有大拇指。"
D.Strings[61466]="嗨哟……嗨哟……噢，不！"
D.Strings[61467]="你在策划对达拉然的袭击？普罗德摩尔会怀疑夺日者的！你给我立刻停下！"
D.Strings[61468]="你休想活着走出这片丛林！"
D.Strings[61469]="这么说，你是来送死的？！"
D.Strings[61470]="暗夜精灵没有认真守好他们在达拉然的传送门。要利用那条魔法轨迹很容易……"
D.Strings[61471]="发现敌对个体。移除防护性损坏保护。"
D.Strings[61472]="击败挑战者。正在上传报告以供分析及语言骚扰。"
D.Strings[61473]="授权废止。祝你愉快。"
D.Strings[61474]="你的罪行将被处以火刑！"
D.Strings[61475]="别让你的眼睛欺骗了你。"
D.Strings[61476]="大家都过来抱一抱吧。"
D.Strings[61477]="你将为自己的罪行付出代价！"
D.Strings[61478]="我很想给自己找个替罪羊。"
D.Strings[61479]="我始终在背后支持着你……"
D.Strings[61480]="干得好，大个子。头脑加蛮力——只要我们齐心协力，就能克服任何障碍！"
D.Strings[61481]="我们战无不胜！"
D.Strings[61482]="快去死吧——我还要吃午饭呢！"
D.Strings[61483]="你这坏蛋马上就要倒霉了！"
D.Strings[61484]="真没劲。"
D.Strings[61485]="你们休想毁灭这片土地！"
D.Strings[61486]="噢，你想来玩玩？！"
D.Strings[61487]="接住，苏尼！"
D.Strings[61488]="你休想从这场接力游戏里活下来，$c！"
D.Strings[61489]="你毫无忠诚可言！"
D.Strings[61490]="不！不——！"
D.Strings[61491]="里东！"
D.Strings[61492]="你休想打败我们！"
D.Strings[61493]="好吧。我什么也没看见。可下次，你休想再利用我们与肯瑞托的关系。"
D.Strings[61494]="里……里……里东。"
D.Strings[61495]="我们熊猫人是热爱和平的种族，但我们也喜欢偶尔看看精彩的拳赛！"
D.Strings[61496]="这些熊猫人真是坐拥宝山而不自知。他们甚至有关于维库人的记载。我说的可是维库人！天呐！他们是怎么遇上的？"
D.Strings[61497]="该付过路费啦！"
D.Strings[61498]="放松点，艾萨斯。他们追查不到这次袭击的。我保证。"
D.Strings[61499]="确定要传送到暴风城吗？"
D.Strings[61500]="确定要传送到奥格瑞玛吗？"
D.Strings[61501]="这可不是街头混混能进的地方！"
D.Strings[61502]="等你得到贵宾资格再来吧！"
D.Strings[61503]="看看这个自作聪明的家伙！"
D.Strings[61504]="比兹莫老板说了，谁也不准进！"
D.Strings[61505]="这边！"
D.Strings[61506]="噢，是啊，我刚来暴风城。这不是很明显吗？"
D.Strings[61507]="我正在给激光枪充能！"
D.Strings[61508]="我正在发射激光枪！"
D.Strings[61509]="打死他！"
D.Strings[61510]="一起行动吧。|cFF0008E8（夏琪亚会跟着你。）|r"
D.Strings[61511]="联盟的走狗！\n\n看看我可怜的双足飞龙……"
D.Strings[61512]="让我们杀光他们。"
D.Strings[61513]="一起行动吧。|cFF0008E8（库姆萨尔会跟着你。）|r"
D.Strings[61514]="还没站起来的人都已经死了。血柄得到了他想要的战士。\n\n所以……我饿了。我们去找点吃的吧？"
D.Strings[61515]="他们休想发现我的踪迹。"
D.Strings[61516]="一起行动吧。|cFF0008E8（琪麟会跟着你。）|r"
D.Strings[61517]="幸好我把所有的业余时间都花在了我最感兴趣的领域：制造高能定向炸药！\n\n让我们用它在大门前建一些防御阵地吧。"
D.Strings[61518]="一起行动吧。|cFF0008E8（利维特会跟着你。）|r"
D.Strings[61519]="我们来搞点爆破吧！"
D.Strings[61520]="卑鄙的侏儒！他们从天上冲下来，把一切都点着了。\n\n现在整个炼油厂都着火了，联盟的主力部队随时都会杀到要塞外面！\n\n我们的人手不足以挡住他们……"
D.Strings[61521]="我们要誓死保卫统御岗哨！"
D.Strings[61522]="一起行动吧。|cFF0008E8（纳兹戈林将军会跟着你。）|r"
D.Strings[61523]="如果联盟以为靠一点点援军就能攻破我的堡垒，那他们就大错特错了！"
D.Strings[61524]="我需要情报，立刻就要！联盟还有多少人，我们还有多少兽人——还有，去帮那个地精疯子急刹建几个防御阵地。"
D.Strings[61525]="你们来得真及时。他们又过来了！"
D.Strings[61526]="准备好，你们这些肮脏的蛮兵！"
D.Strings[61527]="胜利！胜利属于部落！"
D.Strings[61528]="哈！地狱咆哮会为我们骄傲的！敌人又上来送死了……"
D.Strings[61529]="继续战斗，蛮兵！地狱咆哮之眼在注视着我们！"
D.Strings[61530]="这是最后一波攻击了。为了统御岗哨！把他们全杀光！"
D.Strings[61531]="拿起武器，你们这些大怪物！他们要冲锋了。"
D.Strings[61532]="由于闪电通道中的离子突然发生热膨胀，空气中出现一道震动波，雷声开始鸣响！"
D.Strings[61533]="在干燥的空气中，声波的传递速度约为343米/秒！"
D.Strings[61534]="我可以去，以证明巨魔的清白。会有人来收拾你的，加尔鲁什。"
D.Strings[61535]="%s和拉克戈尔·血刃轻声交流了几句。"
D.Strings[61536]="呃，真恶心！这些食物太恐怖了！"
D.Strings[61537]="自助餐为什么总是没有好东西呢？"
D.Strings[61538]="谁会吃这种东西啊？"
D.Strings[61539]="塞兹克管这叫食物？！"
D.Strings[61540]="要是女工头以为我会吃这种垃圾，那她就是个白痴！"
D.Strings[61541]="这些玩意儿伤害了我的感情！"
D.Strings[61542]="罗沙克！赐予我火焰之翼！"
D.Strings[61543]="我们谈谈吧！"
D.Strings[61544]="你被击中了！武器暂时不可用！"
D.Strings[61545]="你可以在秘语大厅中找到虚空契约者，进门后上楼右转就是。"
D.Strings[61546]="你可以在天界回廊中找到虚空契约者，进门后上楼右转就是。"
D.Strings[61547]="虚空契约者"
D.Strings[61548]="我不会心存怜悯！"
D.Strings[61549]="沃金将他的手伸向了你。"
D.Strings[61550]="向沃金发下血誓"
D.Strings[61551]="没有了这些飞斧，他们的掷斧者就起不了什么作用了。"
D.Strings[61552]="你想要参加搏击？等你变得更强壮之后再回来吧。$b$b当然，欢迎你留下来观看比赛。"
D.Strings[61553]="你想要参加搏击？你需要先收到一份邀请。$b$b当然，欢迎你留下来观看比赛。"
D.Strings[61554]="啊，$n，你的心脏会是一件出色的祭品！"
D.Strings[61555]="我们要对付的赞达拉祭司又少了一些。"
D.Strings[61556]="现在，那些无辜的翼手龙雏龙终于有机会过上真正的生活了。"
D.Strings[61557]="但愿夺走这些祭品能推迟他们的献祭仪式。"
D.Strings[61558]="这些赞达拉巨魔的威胁比我预料地更大。"
D.Strings[61559]="难以置信，赞达拉居然真的在搞活体献祭！"
D.Strings[61560]="你是什么时候抵达这座岛的？"
D.Strings[61561]="不久前，我就在这个地方亲眼见证了一场恐怖的灾难！"
D.Strings[61562]="一头巨型雷霆云端翔龙挡在了雷神领域的入口。"
D.Strings[61563]="这个世界上的雷霆云端翔龙已经很稀少了。"
D.Strings[61564]="我们正在调查下水道系统——或许还有其他进入城堡的方法。"
D.Strings[61565]="我？我掌握着碎玉闪电的技巧。我的出拳速度非常快，你甚至都看不清我的拳影！"
D.Strings[61566]="我想要看看飞翔在翡翠林天空中的天火号。带我回去。"
D.Strings[61567]="你确定想要改变你所处的相位吗？"
D.Strings[61568]="%s发出隆隆的召唤声，吸引着附近的旋龟。"
D.Strings[61569]="去沙塔斯城东北边的希尔米耶湖畔找老渔夫巴尔洛吧。"
D.Strings[61570]="我想要回到雄狮港。"
D.Strings[61571]="我是雷电之子！"
D.Strings[61572]="你感觉到劲吹的寒风了吗？风暴将至……"
D.Strings[61573]="复仇云层正在汇聚！"
D.Strings[61574]="愤怒的空气正在爆鸣！"
D.Strings[61575]="天空将为你的败亡而哭泣！"
D.Strings[61576]="我不过是……风暴之前的……黑暗……"
D.Strings[61577]="与我分享这份恩赐吧！"
D.Strings[61578]="又有人上来了。拖住他们！"
D.Strings[61579]="他们从海上派出了夺船小队。派你的人到船尾去开炮，击沉他们！"
D.Strings[61580]="拉风魔典"
D.Strings[61581]="黑暗之门炉石"
D.Strings[61582]="幽灵军马"
D.Strings[61583]="守护者的背叛"
D.Strings[61584]="我们暂时拖住了他们。快去左舷操作火炮，帮助其他船只！"
D.Strings[61585]="我们已经把他们赶回了自己的船上。在上空盘旋一圈，用他们自己的炸药炸飞他们！"
D.Strings[61586]="|TInterface\\Icons\\inv_misc_dust.blp:20|t杜鲁姆开始为自己的眼球充能，以施放|cFFFF0000|Hspell:134169|h[衰变光束]|h|r！"
D.Strings[61587]="你的电容器将在10秒后进行电能释放！快靠近闪电钻！"
D.Strings[61588]="在这座岛上，我不得不让你面对更大的危险。你的忠诚和信任令人赞赏，$n。"
D.Strings[61589]="我们血精灵历经风雨。无论雷电之王有什么花招，我们必将百倍奉还！"
D.Strings[61590]="虽然我们的目标是消灭魔古族，但也不能忽略我们的侧翼。$b$b虽然联盟和蜥蜴人都在与我们一同攻击魔古族，但这两者随时都有可能对我们倒戈相向。"
D.Strings[61591]="我们必须设法剥夺敌人的力量，没有了力量，我们就能随心所欲地轻松战胜他们了。"
D.Strings[61592]="窃取神器"
D.Strings[61593]="别惹恼了大块头，伙计！"
D.Strings[61594]="我们要拿你去喂大块头！"
D.Strings[61595]="现在逃跑可来不及了，伙计！"
D.Strings[61596]="你都不够大块头塞牙缝的。"
D.Strings[61597]="你来错地方了。"
D.Strings[61598]="来得好！我的宠物正好饿了，伙计。"
D.Strings[61599]="啊，食物自己送上门了。"
D.Strings[61600]="你来对地方了……准备被吃掉吧！"
D.Strings[61601]="臣服于赞达拉吧！"
D.Strings[61602]="喂食时间到啦！"
D.Strings[61603]="要想找死的话，你就来对地方了。"
D.Strings[61604]="我要拿你的灵魂去喂野兽。"
D.Strings[61605]="你这废物，只能给我补充能量。"
D.Strings[61606]="神灵会将你吞噬殆尽。"
D.Strings[61607]="去死吧，入侵者。"
D.Strings[61608]="你的灵魂太弱小了。"
D.Strings[61609]="靠近点。我只轻轻割一刀，我保证！"
D.Strings[61610]="一旦割开创口，鲜血就会迅速外流。"
D.Strings[61611]="你越挣扎就越痛！"
D.Strings[61612]="你不会马上死掉的。我保证！"
D.Strings[61613]="啊，一个新标本？我要把你撕成……碎片！"
D.Strings[61614]="对，靠近点，小家伙。我的手术刀在渴望你的鲜血！"
D.Strings[61615]="赫利东注视着$n并开始拍打他的尾巴！"
D.Strings[61616]="啊，兽栏。虽然我很欣赏赞达拉的驯兽技巧，但我更佩服他们忍受恶臭的本事。$b$b只要让魔暴龙处在你的逆风方向，它就休想偷袭到你。"
D.Strings[61617]="|TInterface\\Icons\\ability_warrior_focusedrage.blp:20|t目睹了战神贾拉克的倒下后，赫利东进入了|cFFFF0000|Hspell:136821|h[狂暴]|h|r状态！"
D.Strings[61618]="你给我回来！"
D.Strings[61619]="回来，笨蛋恶棍！"
D.Strings[61620]="别再来了！"
D.Strings[61621]="死在风暴的怒火之下吧！"
D.Strings[61622]="|TInterface\\Icons\\ability_thunderking_lightningwhip.blp:20|t%s开始施放|cFFFF0000|Hspell:136850|h[闪电之鞭]|h|r！"
D.Strings[61623]="我并非天生的短牙种。我原本很强壮。"
D.Strings[61624]="我父亲是个蛮兵，我母亲是蜥蜴人祭司。而我一无是处。$b$b我是邪刃部族的耻辱。我会死在垃圾堆里，谁也不会来吃我的肉。"
D.Strings[61625]="我无法体会克洛斯的力量。我无法在他的猎场中狩猎。$b$b我当不了猎人，我只是个猎物。"
D.Strings[61626]="他们说我能洗刷自己的耻辱。我只要做一件事，然后我就能摆脱短牙种的称谓。$b$b可我做不到。我不能将法洛斯的力量据为己有。尤其是想到他为我所做的一切……"
D.Strings[61627]="作为一个短牙种，我必须等更强壮的蜥蜴人先享用完他们的肉食。"
D.Strings[61628]="我闻出了你，外来者。我知道你不是我们的人。$b$b你为什么溜进我们的村子？你为什么披着我们族人的皮？我不明白。"
D.Strings[61629]="我知道你不是我们的人。你是他们的人。$b$b我跟踪了你。我监视着你。你杀了我们的人，可你也杀魔古族。你还杀直背的巨魔。$b$b我不关心你杀了什么人。我就跟在后面拣肉吃。好多好多肉。"
D.Strings[61630]="我看到了你的魔法。我知道你不是蜥蜴人。你是其他人。$b$b魔法让你变得软弱。你不勇敢。你是披着敌人外皮的懦夫。你一点也不强！$b$b<高卡尔向你脚下吐了一口唾沫。>"
D.Strings[61631]="我知道你的秘密，外来者。我知道你是敌人。我嗅出了你的伪装。$b$b我不怕你。弱者才害怕。我不是弱者。"
D.Strings[61632]="我嗅出了你的伪装，陌生人。你竟敢闯入如此神圣的仪式。$b$b你想干什么？你想吃考什克的肉吗？"
D.Strings[61633]="我们从克洛斯的血肉中诞生。我们由他的骨肉塑造而成。他是我们的造物主。$b$b考什克是克洛斯的血脉。他关注着我们。他是我们与克洛斯之间的纽带。他拥有克洛斯的力量，却行于我们的世界。$b$b当时机来临，考什克将会死去，而我们将获得他的力量。然后，轮回将重新开始。"
D.Strings[61634]="考什克是血肉之躯，可他拥有克洛斯的灵魂。$b$b总有一天，考什克的狩猎将会终结。但克洛斯的狩猎将永无止尽。"
D.Strings[61635]="魔古族对我们撒了谎。他们说我们是他们的造物，他们将我们的血肉扭曲成了现在的形态。他们声称我们的存在全靠了他们。$b$b我蔑视魔古族的说法！他们无权统治我们！他们不理解我们的想法，不懂我们的生活方式和我们的感受！他们看不透我们的灵魂！$b$b只有伟大的造物主克洛斯，才能看透你的灵魂。克洛斯无所不知，通晓万物。克洛斯赐予你们力量，蜥蜴人。你们不属于魔古族。"
D.Strings[61636]="克洛斯，我们的造物主，不会拯救弱者。弱者的灵魂将活在永恒的恐惧之中，逃避着克洛斯和他追随者们的尖牙与利爪。$b$b如果你够强大，那么克洛斯将允许你狩猎。你们将永远追逐弱者，享用他们的血肉，变得更加强大。$b$b坚强起来，蜥蜴人们。$b$b力量与邪刃部族同在。力量与你们同在，蜥蜴人们。"
D.Strings[61637]="享用考什克的血肉，净化你们的懦弱！让克洛斯的灵魂穿过你们的躯壳！"
D.Strings[61638]="你知道我怎么想吗？<托犸飞快地向身后看了一眼。>$b$b蜥蜴人祭司就跟这个村子本身一样肮脏。$b$b他们的考什克崇拜令自己变得软弱。他们鼓吹力量，可他们敢出去狩猎吗？他们敢杀人吗？他们敢在阵亡的兄弟们腐败的残躯上打滚吗？$b$b不敢。他们只会躲在山洞里夸夸其谈。如果他们真的够强壮，就应该出来与我们战斗。"
D.Strings[61639]="蜥蜴人祭司会告诉你说我们的力量来自考什克。别听他们那一套。$b$b我们的力量来自我们的爪子，我们的牙齿。它来自那些污秽污染者收集并培养的污秽。$b$b它来自我们本身。$b$b我不在乎我们究竟是源自某种魔暴龙，还是魔古族的造物。我只关心怎样保护这片土地不受敌人的侵扰。"
D.Strings[61640]="我们是由魔古族创造出来的。我们没道理拒绝相信这一点。任何否认它的人要么是无知，要么就是活在幻想之中。$b$b我可不想假装自己是一头魔暴龙。我知道我是什么。我知道我的力量从何而来。"
D.Strings[61641]="“只有那些吓破胆的蜥蜴人才会去崇拜考什克。$b$b他们假装我们都是一群直立行走的小魔暴龙，想靠证明我们的‘力量’来获取天上的某一头无形无影、全知全能的魔暴龙的垂青。$b$b他们真的这么想。$b$b我们不是魔暴龙。我们是蜥蜴人。当我们死后，也没有什么永恒的狩猎，没有许诺的天堂，没有对弱者的惩罚，更没有克洛斯。我们会被吃掉，而我们的残躯将被抛入污水池。就是这样。我亲眼看见了。”"
D.Strings[61642]="我才不参加他们那个虚伪的仪式呢。考什克没什么特别的，他的肉也是。肉就是肉。"
D.Strings[61643]="最近有找到什么好肉吗？$b$b我前几天吃了一个侏儒。太难吃了，我花了好多工夫才把牙缝里的粉色头发剔干净。"
D.Strings[61644]="你脚上有蟑螂，$g兄弟:姐妹;。$b$b小心走路。蟑螂能帮我们传播疾病。"
D.Strings[61645]="我今天在外面的沼泽里找到一些很好的污物。污染者会为我骄傲的。"
D.Strings[61646]="不要吃干净的肉。邪刃蜥蜴人的强壮必须表里如一。"
D.Strings[61647]="我看到了我们的新敌人。$b$b直背的巨魔与魔古族结了盟，但其他入侵者却在与他们交战。$b$b呸！我才不在乎。他们的战斗给我们留下了许多尸体。邪刃部族前所未有地强大。"
D.Strings[61648]="最近有找到什么好肉吗？$b$b我前几天吃了一个血精灵，那味道就好像他在花丛里滚过一样。"
D.Strings[61649]="帮我个忙：把你多余的污物丢到污水池里。"
D.Strings[61650]="伊瓜鲁克正在改变。蜥蜴人们正在互相争斗。有人认为我们中间出现了入侵者。"
D.Strings[61651]="最近有没有大开杀戒？$b$b我昨天杀了一个牛头人。我们出动了三个食腐者才把他运回污水池！"
D.Strings[61652]="魔古族想消灭我们。魔古族是我们敌人。我要杀光靠近我们家园的魔古族。$b$b你愿意来帮忙吗？"
D.Strings[61653]="最近有没有大开杀戒？$b$b我昨天杀了一个德莱尼。你可以在污水池附近找到她……有蓝色内脏的就是。"
D.Strings[61654]="磨利你的爪子。你永远不知道何时会有一块好肉经过。"
D.Strings[61655]="战斗、杀戮、进食，好好活过每一天。$b$b如果你死了，记得死在方便你的兄弟姐妹吃掉你的地方。没必要去给敌人送菜。"
D.Strings[61656]="杀魔古族。$b$b杀魔古族。$b$b杀杀杀！"
D.Strings[61657]="力量与邪刃部族同在。杀死我们敌人，割碎他们。"
D.Strings[61658]="你喜欢怎么杀人？用牙齿？用武器？从背后偷袭？还是从暗处偷袭？"
D.Strings[61659]="瞧瞧你这副干净的皮囊。你想让魔古族攻击你吗？你想做他们的宠物？$b$b保护好你自己，$g兄弟:姐妹;。快把污物涂在身上吧。"
D.Strings[61660]="我们的责任就是保持污泥的新鲜。污秽保护了我们的安全。它们能赶走敌人。"
D.Strings[61661]="管好你的胃，$g兄弟:姐妹;。记得留一点肉让它烂掉。$b$b暴饮暴食的蜥蜴人会害死我们大家的。"
D.Strings[61662]="啊！你身上有一块干净的地方，$g兄弟:姐妹;。让我帮你弄脏……"
D.Strings[61663]="如果你抓到破坏污水池的人，记得通知我。我听说了入侵者的事。"
D.Strings[61664]="别踩到我的蟑螂，$g兄弟:姐妹;。"
D.Strings[61665]="如果你需要污物，可以来找我。我能帮你。"
D.Strings[61666]="远离大海。它太干净了。$b$b蜥蜴人祭司会告诉你：污秽是仅次于虔诚的美德。"
D.Strings[61667]="魔古族自称创造了我们……并将我们扭曲成现在的形态。不要相信他们的谎言。$b$b我们是独立的人民，源自于伟大的造物主克洛斯！"
D.Strings[61668]="考什克是来自我们的造物主克洛斯的礼物。他让我们记住自己的力量，传承与遗产。他让我们看到了辉煌的未来。"
D.Strings[61669]="魔古族是我们的敌人。他们想将我们从这个世界上抹去。我们为什么要相信他们灌输给我们的造物神话？"
D.Strings[61670]="保持强壮。$b$b保持邪恶。$b$b屠杀吃不完的猎物。$b$b不要交朋友，不要养宠物。$b$b战斗到死。$b$b这些，以及其他许多真理，都是考什克的教诲。"
D.Strings[61671]="在考什克面前保持恭谨，蜥蜴人。在这个世界上，他是最接近克洛斯的存在。$b$b享用他的存在。他不会一直活下去。"
D.Strings[61672]="考什克将自己的血骨、力量和灵魂给了我们。我们要为自己的存在而感谢他。"
D.Strings[61673]="考什克是我们的造物主克洛斯的血脉。我们是克洛斯的选民。$b$b依靠它的力量，我们将得到永生。"
D.Strings[61674]="为克洛斯的理想而活。战斗不息，成长不止。每一天都要更加强壮。$b$b战胜痛苦，忍受污秽。所有人都是你的敌人。$b$b握着你的武器死去，将你的躯体献给伊瓜鲁克。"
D.Strings[61675]="杀魔古族。"
D.Strings[61676]="敌人就是会走路的肉。"
D.Strings[61677]="去死吧，魔古族。"
D.Strings[61678]="杀戮、进食、杀戮。"
D.Strings[61679]="尖牙与利爪。"
D.Strings[61680]="拒绝恐惧。拒绝同情。杀光入侵者。"
D.Strings[61681]="不要同情弱者。"
D.Strings[61682]="不要软弱，保持强壮。"
D.Strings[61683]="注意海面，$g兄弟:姐妹;。魔古族可能从任何方向发起攻击。"
D.Strings[61684]="克洛斯更看重海龙战士。大海是美食和污秽的发源地。"
D.Strings[61685]="克洛斯祭坛是神圣的地方，$g兄弟:姐妹;。在我的海滩上，你要小心行走。"
D.Strings[61686]="我们最近常常见到奇怪的船只，不是魔古族的船。$b$b这些入侵者是谁？他们想要什么？他们都什么味儿？"
D.Strings[61687]="海里有很多尸体。比平时更多。$b$b附近发生了战争。$b$b这对蜥蜴人是好事。更多的尸体意味着更多的食物，更多的污物。"
D.Strings[61688]="我闻到了入侵者的味道。他们就在附近。$b$b<海龙战士狐疑地看着你。>"
D.Strings[61689]="“某些蜥蜴人祭司称我为叛徒。‘考什克不会在海里狩猎，’”他们如是说。$b$b我信仰克洛斯之道，可我并不赞同这些祭司。考什克会在力所能及的范围内狩猎，我也是。$b$b在今天的邪刃部族里，这些祭司和他们对考什克顽固僵化的理解已经没有市场了。"
D.Strings[61690]="污秽保护着我们。我们敌人忍受不了伊瓜鲁克的臭味。$b$b可是，在海滩上保持肮脏是很难的。海滩消耗污物的速度比我们制造的速度更快。我们得想其他办法来保护我们的海滩。$b$b<海龙战士微微一笑，露出了锋利的牙齿。>这就是我的任务，$g兄弟:姐妹;。"
D.Strings[61691]="<这个蜥蜴人躲到了宠物身后。>"
D.Strings[61692]="求你，退后，强者。我不想打仗。"
D.Strings[61693]="蜥蜴人祭司看穿了我的软弱。那些暴徒殴打我，骂我是“短牙种”。要不是有我的蛇蜥保护我，我会很孤单的。$b$b生不如死。"
D.Strings[61694]="你竟然屈尊跟我说话？跟一个带宠者？一个短牙种？$b$b我知道自己在这个世界上的位置，强者。我不够强壮，不能单打独斗，所以我养了一头宠物来保护我。我被叫做弱者，被赶到村子的边缘来。$b$b你该离我远点儿，别被他们看见了。"
D.Strings[61695]="你好，强者。"
D.Strings[61696]="我一无是处，我是废物，我是弱者。$b$b我一无是处，我是废物，我是弱者……$b$b我是弱者……"
D.Strings[61697]="短牙种也是可以变强的。如果我愿意，我也可以摆脱族人对我的嘲笑。$b$b办法是有的……可我害怕。我太害怕，太软弱了。$b$b他们不理解我。我要当一辈子的短牙种。"
D.Strings[61698]="<这个短牙种恐惧地瑟缩着。>"
D.Strings[61699]="闭嘴，蠢货！考什克过来了！"
D.Strings[61700]="<蜥蜴人沉默而敬畏地跪下了。>"
D.Strings[61701]="放尊重点，蜥蜴人。你没看见考什克吗？"
D.Strings[61702]="闭上你的嘴，立刻跪下，蠢货。考什克就在附近。"
D.Strings[61703]="享用考什克的血肉，净化你的软弱。"
D.Strings[61704]="他的血肉滋养了我们，赐予我们力量。他腐烂的内脏将被扔进污水池，保护我们不受入侵者袭扰。他的骨骼将被建成我们的房屋。他的种子将延续永恒的轮回。$b$b力量与考什克同在。力量与邪刃部族同在。"
D.Strings[61705]="考什克！"
D.Strings[61706]="力量与邪刃部族同在！"
D.Strings[61707]="|TInterface\\Icons\\spell_nature_lightningoverload.blp:20|t|cFFFF0000西北部|r的大门敞开，引发了|cFFFF0000|Hspell:136889|h[暴乱狂风]|h|r！"
D.Strings[61708]="金铁领主莫诺汗正在准备回旋击！"
D.Strings[61709]="军阀古拉能将风暴的力量玩弄于股掌之间。只要一个指令，他就能让劈啪作响的电流笼罩大地。那些被他卷入风暴中的人都会浑身焦黑地凄惨死去。"
D.Strings[61710]="蠢东西！"
D.Strings[61711]="死亡，危机，赞达拉携带他们的魔法再次归来。真刺激！"
D.Strings[61712]="肯瑞托可以留着他们的达拉然，我才不在乎。这才是最合适我的地方，在白热化的战斗中深入敌后！"
D.Strings[61713]="水银污泥怪从他的刀刃上滴落下来！快杀死污泥怪以吸收它们的力量！"
D.Strings[61714]="谢谢你，朋友。你将我从可怕的命运中救了出来。"
D.Strings[61715]="是夺日者派你来的吗？感谢你的及时搭救。"
D.Strings[61716]="谢谢你。现在我可以自己回营地去了。"
D.Strings[61717]="谢谢你，勇士。请你也救救其他人吧！"
D.Strings[61718]="魔古族怎能如此残暴？多亏你及时赶到。"
D.Strings[61719]="我真是感激不尽，英雄。"
D.Strings[61720]="你救了我的命，勇士。我欠你一份人情。"
D.Strings[61721]="是银色盟约派你来的吗？感谢你的及时搭救。"
D.Strings[61722]="我就知道银色盟约不会抛弃我的。谢谢你，勇士。"
D.Strings[61723]="我就知道夺日者不会抛弃我的。谢谢你，勇士。"
D.Strings[61724]="我真该把你撕成碎片，联盟的人渣！这次我就饶你一命。"
D.Strings[61725]="我就饶你一次，联盟的英雄。免得让人说夺日者不懂得感恩。"
D.Strings[61726]="要不是你救了我一命，我一定立刻杀了你。下次再见时，我可不会手下留情。"
D.Strings[61727]="虽然我们是敌人，但我还是要谢谢你。只此一次，下不为例。"
D.Strings[61728]="谢谢你，联盟的英雄。但下次见面时，我还是不会对你手软的。"
D.Strings[61729]="谢谢你，部落的英雄。但下次见面时，我还是不会对你手软的。"
D.Strings[61730]="我就饶你一次，部落的英雄。免得让人说银色盟约不懂得感恩。"
D.Strings[61731]="我真该把你撕成碎片，部落的人渣！这次我就饶你一命。"
D.Strings[61732]="你想偷我们的污物吗？"
D.Strings[61733]="我要把你的尸体扔进污水池！"
D.Strings[61734]="你想对我做什么？"
D.Strings[61735]="不——不！"
D.Strings[61736]="力量。"
D.Strings[61737]="杀戮时刻。"
D.Strings[61738]="考什克之牙在上，你怎么进来的？！"
D.Strings[61739]="克洛斯，赐予我力量……"
D.Strings[61740]="我诅咒你，懦夫……"
D.Strings[61741]="我就说有什么味道……"
D.Strings[61742]="你会后悔的……"
D.Strings[61743]="我一直很忙。一些蜥首牧师想让部落和联盟流血。$b$b理所当然的，我就趁他们睡觉时把他们都杀了。"
D.Strings[61744]="我从没见过这么臭的污水池。我们需要找人来清理一下，免得它继续发展并扩散到峭壁外面。"
D.Strings[61745]="他们整天都在念叨“杀魔古族”。无论艾萨斯让你做了什么，它都起作用了。"
D.Strings[61746]="他们整天都在谈论自己在伊瓜鲁克峭壁发现的魔古武器。$b$b他们完全没有怀疑我们。继续加油吧。"
D.Strings[61747]="就我收集的情报来看，他们正准备在黎明时分袭击魔古族。"
D.Strings[61748]="这些蜥蜴人刚刚袭击魔古族回来。我会继续观察他们的。"
D.Strings[61749]="蜥蜴人首领已经终止了针对魔古族的袭击，并转而计划攻击部落和联盟。$b$b我们恐怕要有所行动了。"
D.Strings[61750]="蜥蜴人最近一直很安静，已经开始有些焦躁。是时候让他们去对付魔古族了。"
D.Strings[61751]="告诉艾萨斯，今天那些蜥蜴人很消停，没有再发动攻击。"
D.Strings[61752]="蜥蜴人很不安分，他们正在谋划着什么。艾萨斯会对此感兴趣的。"
D.Strings[61753]="去告诉大法师，就说伊瓜鲁克一切都在掌握之中。我过几天再给他发一份报告。"
D.Strings[61754]="看来那些食腐者恐怕很快就要到外面的沼泽去狂欢一番了。去告诉大法师，让他做好准备。"
D.Strings[61755]="正在重启……"
D.Strings[61756]="系统启动。现在感觉好多了。"
D.Strings[61757]="正在尝试修复令人难堪的故障……"
D.Strings[61758]="修复失败。羞愧指数上升。返回基地。"
D.Strings[61759]="腿部故障回路破损。返回基地。"
D.Strings[61760]="执行挖沙协议。"
D.Strings[61761]="警告：法力流失速率过高。"
D.Strings[61762]="尝试启动法力流失速率降低改写协议。"
D.Strings[61763]="\"一切正常\""
D.Strings[61764]="\"一切安好\""
D.Strings[61765]="\"$N会搞定的\""
D.Strings[61766]="法力流失速度正常。返回基地。"
D.Strings[61767]="尝试销毁超过6小时的记忆档案。"
D.Strings[61768]="记忆档案已销毁。你是谁。返回基地。"
D.Strings[61769]="正在开机……"
D.Strings[61770]="未知地点。返回已知的最后一个基地位置。"
D.Strings[61771]="执行感谢协议。"
D.Strings[61772]="\"谢谢你\""
D.Strings[61773]="看到我们雄壮的骑乘海龟了吗？它们乍看之下似乎慢吞吞的——可有经验的骑手却能驾着它们跟上全卡利姆多最迅捷的座狼。可惜，它们只提供给我们最信赖的盟友。"
D.Strings[61774]="你再也找不到比我们的龙龟更好的坐骑伙伴了。它们重心极低，哪怕是在急转弯时，上面的骑手也感觉不到一点震动或推挤。如果你想买的话，就必须向土水派证明你的忠诚。"
D.Strings[61775]="如此寒冷，如此黑暗……"
D.Strings[61776]="我们不能被遗忘，不，不……"
D.Strings[61777]="我们是完美的，对，不是残次品，不，不是残次品……"
D.Strings[61778]="这是什么？他们想干什么？惩罚我们？不，不……"
D.Strings[61779]="你的血肉，对，太完美了，给我们……"
D.Strings[61780]="不不不，又开始痛了！"
D.Strings[61781]="它从内部撕裂了我们！"
D.Strings[61782]="那么，谁更完美，嗯？对…对…"
D.Strings[61783]="又来了……我们被撕裂了……又要……回到冰冷的黑暗中……"
D.Strings[61784]="我想使用我的挑战卡牌！"
D.Strings[61785]="我想要参加战斗，提升我的等级！"
D.Strings[61786]="你的灵魂归我了，入侵者！"
D.Strings[61787]="啊，又一条灵魂送上门了。"
D.Strings[61788]="我会好好利用你的，入侵者。"
D.Strings[61789]="我会好好享受你的死亡的，闯入者！"
D.Strings[61790]="附近的池塘中开始形成活化液体！"
D.Strings[61791]="普利莫修斯发生|cFFFF0000|Hspell:136209|h[进化]|h|r并获得了|cFFFF0000|Hspell:136210|h[腹部毒囊]|h|r！"
D.Strings[61792]="普利莫修斯发生|cFFFF0000|Hspell:136209|h[进化]|h|r并获得了|cFFFF0000|Hspell:136215|h[毒气鱼鳔]|h|r！"
D.Strings[61793]="普利莫修斯发生|cFFFF0000|Hspell:136209|h[进化]|h|r并获得了|cFFFF0000|Hspell:136218|h[酸性脊刺]|h|r！"
D.Strings[61794]="普利莫修斯发生|cFFFF0000|Hspell:136209|h[进化]|h|r并获得了|cFFFF0000|Hspell:136225|h[病源腺体]|h|r！"
D.Strings[61795]="普利莫修斯发生|cFFFF0000|Hspell:136209|h[进化]|h|r并获得了|cFFFF0000|Hspell:136245|h[代谢增速]|h|r！"
D.Strings[61796]="普利莫修斯发生|cFFFF0000|Hspell:136209|h[进化]|h|r并获得了|cFFFF0000|Hspell:136246|h[迸裂脓疮]|h|r！"
D.Strings[61797]="这可是很疼的。"
D.Strings[61798]="普利莫修斯失控并发生了变异！"
D.Strings[61799]="霍古开始侵蚀你的血液……"
D.Strings[61800]="我准备好了！[排队等待单人副本。]"
D.Strings[61801]="爬虫们，欢迎来见证赞达拉帝国的重生！"
D.Strings[61802]="各部族已团结起来——你们面对的不是单一势力，而是整个巨魔帝国！祖尔之手将重新掌握艾泽拉斯！你们这些下等种族大难临头了！"
D.Strings[61803]="看看神兽真正的力量吧。D'akala di'chuka，赫利东！Kalimaste！"
D.Strings[61804]="达卡莱部族，让他们看看北地的冰封之力！"
D.Strings[61805]="古拉巴什部族，让丛林的毒液带走他们浮肿的尸身。"
D.Strings[61806]="法拉基部族，用沙漠的怒火撕裂他们！"
D.Strings[61807]="阿曼尼部族，以祖尔金之名，为陨落的领主复仇吧！"
D.Strings[61808]="哈哈哈！现在轮到我了！见识一下战神的实力吧！"
D.Strings[61809]="你的颅骨将成为我獠牙上的小装饰。"
D.Strings[61810]="Da'kala koraste……赫利东……消灭他们……"
D.Strings[61811]="你刚才是不是说了“你好”？"
D.Strings[61812]="“不。我说的是‘你好啊’。不过也差不多了。$b$b再见了。”"
D.Strings[61813]="你有时间去屠杀岛上无助的居民，却没有时间帮忙收集我伟大的身躯？"
D.Strings[61814]="别再拖拖拉拉了，乞求者！我要你去收集我的躯体！"
D.Strings[61815]="你管那叫击杀对手？我还以为会……火光冲天，或者来几道闪电呢。"
D.Strings[61816]="我见过的蜥蜴人都比你刚才打得更像样。"
D.Strings[61817]="啊！刚才那一下很漂亮。看来你还有点希望。"
D.Strings[61818]="你的能力挺让人印象深刻的。总有一天，你会成为出色的奴隶。"
D.Strings[61819]="在雷电之王统治期间，我都能活好几百年。你知道为什么吗？因为我从不让主人久等！"
D.Strings[61820]="多么可悲的生物。直接消灭掉算了。"
D.Strings[61821]="我准备好了。唤醒守卫吧！"
D.Strings[61822]="我们必须打倒山怖！你做好继续前进的准备了吗？"
D.Strings[61823]="我准备好对付山怖了！"
D.Strings[61824]="我们来迟了！暴风领主纳拉克就快被山怖复活了。但这只是个偶发事件。我们真正的目标是要击败山怖！"
D.Strings[61825]="我来掩护侧翼。你去收集炸药并把它们送到指定地点。快！"
D.Strings[61826]="赞布图拉驭兽师召唤迅猛龙前来助战！"
D.Strings[61827]="我已经选好了登陆点：就是我们东边那座易守难攻的半岛。"
D.Strings[61828]="可惜，赞达拉巨魔已经占据了那里。"
D.Strings[61829]="他们用一个强大的灵魂屏障守卫着它。得先解除它，才能让船只靠岸。"
D.Strings[61830]="勇士，我要你带领一支突击小队，从内部瓦解这个屏障！"
D.Strings[61831]="找一匹坐骑，去和斥候队长艾尔希娅会合吧。她会召集一队精锐游侠配合你行动。愿阳光照耀着你。"
D.Strings[61832]="我在上面，勇士！"
D.Strings[61833]="夺日者找到了保护坐骑不受闪电伤害的方法。可为了以防万一，还是分散飞行吧。"
D.Strings[61834]="看下面！我们对城镇和墓穴的持续攻击已经令敌人陷入了混乱。魔古族和赞达拉开始害怕部落了。"
D.Strings[61835]="你看到中央那座塔了吗？闪电一直在击打它。艾萨斯怀疑这场风暴就是源自于宫殿的中心。"
D.Strings[61836]="其他游侠就在前面等我们。我们的首要目标是——小心！"
D.Strings[61837]="太阳之井在上！天空背叛了我们——这里不安全了！"
D.Strings[61838]="降落！全体降落！"
D.Strings[61839]="勇士，你还好吧？"
D.Strings[61840]="我们还不安全。他们早就等着我们了。部队散落在沼泽各处，而我们却孤军深入敌后！"
D.Strings[61841]="哦，不好。"
D.Strings[61842]="他们撤退了，但还不能放松。"
D.Strings[61843]="我们逃出升天的唯一希望就是占领城镇。"
D.Strings[61844]="我讨厌那个巨魔的样子。小心！"
D.Strings[61845]="快击败那个家伙，我们才能获得自由！"
D.Strings[61846]="他们在保护那个面具。那一定是屏障的源头。摧毁它！"
D.Strings[61847]="快摧毁灵魂面具，解除屏障！"
D.Strings[61848]="他在保护面具。杀了他！"
D.Strings[61849]="别放弃。我们就要胜利了！"
D.Strings[61850]="护盾——消失了！我们成功了！"
D.Strings[61851]="勇士，要不是你，我已经死在沼泽里了。我欠你一条命。"
D.Strings[61852]="干得好，英雄。我们前进吧。"
D.Strings[61853]="你真是鼓舞人心。"
D.Strings[61854]="胜利属于辛多雷！部落又胜利了。"
D.Strings[61855]="罗曼斯，去建防线。艾萨斯，设下真视之眼。克希尔，把帐篷和补给卸下来。"
D.Strings[61856]="部落的兄弟姐妹们！我们如今群敌环伺！你们的勇气将是未来几周内决定胜败的关键。"
D.Strings[61857]="勇士，部落以你为荣。你坚定的意志是我们立足的关键。现在，真正的任务即将开始。"
D.Strings[61858]="他们来了！兄弟们，拿起武器——把他们扔回海里去！"
D.Strings[61859]="守住废墟！杀了他们！"
D.Strings[61860]="碾碎入侵者。别让屏障关闭。"
D.Strings[61861]="面对我吧！我的意志坚如精钢。我的人民坚不可摧！"
D.Strings[61862]="废物！你们都要变成兽粮！"
D.Strings[61863]="万灵将啜饮你的鲜血！"
D.Strings[61864]="万灵赐予我力量。粉碎他们的意志……"
D.Strings[61865]="赞达拉……"
D.Strings[61866]="醒醒，小猫咪们。游戏时间到了……"
D.Strings[61867]="打倒守门人！这样才能打开大门！"
D.Strings[61868]="这就够他们受的了。你准备好了吗？我要开门了。"
D.Strings[61869]="我们来不及阻止纳拉克的复活仪式了，但还有机会打败山怖及其大军！进攻！"
D.Strings[61870]="山怖，是时候了！别躲在你那些魔法背后了，出来与我一战！"
D.Strings[61871]="小心！赞达拉巨魔跳过了围墙！把那些驭兽师从坐骑上打下去！"
D.Strings[61872]="你低估了我们，山怖。我们从你的魔掌中救出了这个地方，潘达利亚也将因此变得更美好。"
D.Strings[61873]="起来吧，纳拉克。用你的怒火席卷那些胆敢亵渎我们主人宫殿的不速之客！"
D.Strings[61874]="炸药！$b$b干得好，$n。你来得正是时候。"
D.Strings[61875]="炸药来了，艾尔希娅。"
D.Strings[61876]="快，$n！$b$b没有炸药我们就攻不破这道城墙！"
D.Strings[61877]="啊！坚持住！"
D.Strings[61878]="我已经选好了登陆点：一片易守难攻的高地。"
D.Strings[61879]="不幸的是，赞达拉巨魔已占据并守卫着那里。"
D.Strings[61880]="他们用一道强大的灵魂屏障守卫着它。我们得先解除它，才能让部队过来。"
D.Strings[61881]="勇士，你要率领一支突击小队，从内部瓦解这道屏障！"
D.Strings[61882]="找一匹坐骑，去和温蕾萨·风行者会合吧。她正在召集一队精锐游侠来配合你。"
D.Strings[61883]="我们已经有了保护坐骑免受闪电干扰的方法。但为防万一，还是得分散飞行。"
D.Strings[61884]="我们对下方墓地和城镇的持续进攻取得了成效。无论是魔古族还是赞达拉巨魔都已无力反攻了。"
D.Strings[61885]="看到中央那座塔了吗？闪电一直在击打它。我们怀疑这场风暴就源自于宫殿内部。"
D.Strings[61886]="集合点就在前面。我们已经召集了一支精锐部队——什么？"
D.Strings[61887]="Anar’alah！天空背弃了我们——这里不安全了！"
D.Strings[61888]="他们一直在等着我们。部队被打散了，我们得靠自己了。"
D.Strings[61889]="这还真是惊喜不断。"
D.Strings[61890]="他们退回去了。我们得在他们重整队伍前压上去。跟我来！"
D.Strings[61891]="正如我所说——勇者无敌！"
D.Strings[61892]="快行动——那可不是普通的赞达拉巨魔！"
D.Strings[61893]="他守护着面具。杀了他！"
D.Strings[61894]="加油，他们开始溃散了！"
D.Strings[61895]="吉安娜选对了人。你挽救了这个任务……还有我的生命。"
D.Strings[61896]="这就是联盟的精神——勇往直前！"
D.Strings[61897]="温蕾萨，去建防线。茉德拉，设下真视之眼。纳莱丝，把帐篷和补给运过来。"
D.Strings[61898]="所有人，各就各位！我们周围都是敌人！千万不能够浪费时间了。"
D.Strings[61899]="勇士，你的成就已经超出了我的预期。你所表现出的勇气与决心巩固了我们的根基。现在，真正的工作开始了。"
D.Strings[61900]="不出我所料。"
D.Strings[61901]="以肯瑞托之名！"
D.Strings[61902]="呸！你们还没见识到赞达拉的全部力量呢！"
D.Strings[61903]="$n驱使赫利东冲向法拉基之门！"
D.Strings[61904]="$n驱使赫利东冲向古拉巴什之门！"
D.Strings[61905]="$n驱使赫利东冲向达卡莱之门！"
D.Strings[61906]="$n驱使赫利东冲向阿曼尼之门！"
D.Strings[61907]="赞达拉恐龙统领掉落了控制宝珠！"
D.Strings[61908]="起爆器到位了。英雄——这份殊荣属于你。"
D.Strings[61909]="你以为自己能神不知鬼不觉的从我们头上飞过去？！"
D.Strings[61910]="好吧，你想去哪里都可以。可惜你活不到那一天了！"
D.Strings[61911]="准备受死吧，入侵者！"
D.Strings[61912]="胡拉奇准备施放冰霜射击！"
D.Strings[61913]="胡拉奇对准天空施放了乱箭齐发！"
D.Strings[61914]="$n想要食物！"
D.Strings[61915]="|TInterface\\Icons\\achievement_moguraid_03:20|t%s被戈拉亚的灵魂|cFFF00000|Hspell:136442|h[占据]|h|r了！"
D.Strings[61916]="在一个从不锁门的世界里，锁匠要怎么谋生呢？"
D.Strings[61917]="|TInterface\\Icons\\spell_priest_divinestar:20|t%s召唤出了一个|cFFF00000|Hspell:137203|h[受祝福的神灵]|h|r！"
D.Strings[61918]="|TInterface\\Icons\\spell_priest_divinestar_shadow2:20|t%s召唤出了一个|cFFF00000|Hspell:137350|h[受庇护的神灵]|h|r！"
D.Strings[61919]="|TInterface\\Icons\\spell_monk_envelopingmist:20|t%s唤来了一场致命的|cFFF00000|Hspell:136894|h[沙尘暴]|h|r！"
D.Strings[61920]="|TInterface\\Icons\\spell_shaman_staticshock:20|t%s|cFFF00000|Hspell:137149|h[过载]|h|r了！"
D.Strings[61921]="|TInterface\\Icons\\spell_shaman_staticshock:20|t%s开始进行|cFFF00000|Hspell:137166|h[电能释放]|h|r！"
D.Strings[61922]="|TInterface\\Icons\\ability_deathknight_remorselesswinters2:20|t离开你的盟友！你受到了|cFFF00000|Hspell:136991|h[刺骨之寒]|h|r的影响！"
D.Strings[61923]="|TInterface\\Icons\\spell_mage_frostbomb:20|t$n受到了|cFFF00000|Hspell:136922|h[霜寒刺骨]|h|r的影响！"
D.Strings[61924]="我做好出击的准备了。 [排队等待单人副本。]"
D.Strings[61925]="很好，你来了。"
D.Strings[61926]="摄政王阁下！人员已经就位了，影踪派也进去了，可是……"
D.Strings[61927]="联盟就在庭院的那头等着我们。"
D.Strings[61928]="啊，肯瑞托那位了不起的女士想打一仗，是吗？"
D.Strings[61929]="游侠们！前进！"
D.Strings[61930]="我要亲自对付普罗德摩尔。"
D.Strings[61931]="|TInterface\\Icons\\spell_nature_unrelentingstorm.blp:20|t|cFFFF0000|Hspell:135680|h[北部导管]|h|r烧毁并引发了|cFFFF0000|Hspell:137176|h[导管短路]|h|r！"
D.Strings[61932]="|TInterface\\Icons\\spell_nature_unrelentingstorm.blp:20|t|cFFFF0000|Hspell:135681|h[东部导管]|h|r烧毁并引发了|cFFFF0000|Hspell:137176|h[导管短路]|h|r！"
D.Strings[61933]="|TInterface\\Icons\\spell_nature_unrelentingstorm.blp:20|t|cFFFF0000|Hspell:135682|h[南部导管]|h|r烧毁并引发了|cFFFF0000|Hspell:137176|h[导管短路]|h|r！"
D.Strings[61934]="|TInterface\\Icons\\spell_nature_unrelentingstorm.blp:20|t|cFFFF0000|Hspell:135683|h[西部导管]|h|r烧毁并引发了|cFFFF0000|Hspell:137176|h[导管短路]|h|r！"
D.Strings[61935]="一个个来，将士们。先集中解决赞达拉！"
D.Strings[61936]="你会跪着求我饶命的，怪物。"
D.Strings[61937]="祝踏岚！不管你召集多少帮手都没用。很快，所有人都将向陛下俯首称臣。"
D.Strings[61938]="那些雕像掌握着始皇帝的力量。摧毁他们！"
D.Strings[61939]="陶矢，打开那些门。"
D.Strings[61940]="勇士，跟我来。我们得继续前进，让你的同伴殿后。"
D.Strings[61941]="雷电之王的宫殿就在前面。在发动进攻前，我们必须在岛上建立一个据点。"
D.Strings[61942]="摄政王——矿洞那边的赞达拉又冲过来了！"
D.Strings[61943]="该死的家伙。游侠们！守住这里！"
D.Strings[61944]="谁还需要神？我们有雷电之王！"
D.Strings[61945]="巨魔——都行动起来。我就快完成了。"
D.Strings[61946]="山怖！你又妄想造神了。你何时才能吸取教训？"
D.Strings[61947]="赞达拉的援军就要来了。"
D.Strings[61948]="雅丽亚——我们需要治疗！陶矢——掩护后方！"
D.Strings[61949]="冲我来，山怖！难道雷电之王的朝堂上全是懦夫吗？"
D.Strings[61950]="来吧，纳拉克！保护陛下！"
D.Strings[61951]="等我将你们的脑袋呈上去，陛下一定会很满意的，影踪派。"
D.Strings[61952]="那些废物还没见识过我的力量。"
D.Strings[61953]="战神阿尔图克拉，接纳我的力量。"
D.Strings[61954]="那些祭司正在对那些侍卫灌注神灵之力！必须阻止他们！"
D.Strings[61955]="守卫的力量正在增长！快阻止他们！"
D.Strings[61956]="守卫醒过来了！快摧毁它！"
D.Strings[61957]="你剥夺了它的力量。现在，取走它的性命吧！"
D.Strings[61958]="让这些入侵者看看我的厉害，让万民在我面前颤栗。"
D.Strings[61959]="万物都将臣服于我们！！"
D.Strings[61960]="山怖，守住内庭。绝不能让活人见到我的造物。"
D.Strings[61961]="谨遵陛下旨意！"
D.Strings[61962]="这座岛屿蕴藏着极其强大的魔力。如果我们能驾驭它，就必将所向无敌。"
D.Strings[61963]="这里的赞达拉巨魔在使用一种我不了解的黑暗魔法。他们将奥术力量与暗影力量混合，这种做法非常恐怖，而且危险。"
D.Strings[61964]="这个地区散发出来的魔力太神奇了，$c。我已经迫不及待地要研究他们的神器了。我们有太多东西要学了。"
D.Strings[61965]="你看到那些在路上游荡的魔像了吗，$c？那些被束缚的灵魂将永世侍奉赞达拉。$b$b或许，魔古族和赞达拉比我们想象中更加相似。"
D.Strings[61966]="一个躁动之魂正在追逐你的灵魂。别让它碰到你！"
D.Strings[61967]="一个枯竭之魂正在吸取你的灵魂。躲开他，破坏他的法术！"
D.Strings[61968]="啊！英雄，我们正谈到你呢。"
D.Strings[61969]="算了吧。陶矢的提议太危险了。"
D.Strings[61970]="如果想要打倒雷电之王，我们就必须先攻破船坞。现在应该采取行动了！"
D.Strings[61971]="勇士，听我说：我们将在夜里，利用你驯服的这头神奇的野兽袭击船坞。"
D.Strings[61972]="进去之后，我们要破坏赞达拉的船只，并趁着混乱溜进庭院，从内侧打开大门。"
D.Strings[61973]="好主意！头脑总能胜过蛮力。"
D.Strings[61974]="好吧，陶矢。如果这位勇士同意，任务就可以进行。"
D.Strings[61975]="谢谢你，祝掌门。我不会让你失望的。"
D.Strings[61976]="准备好就告诉我一声！"
D.Strings[61977]="这正是这个计划吸引我的地方。如果我们攻破船坞，就能防止魔古族获得更多的赞达拉援军。"
D.Strings[61978]="你受到了灵魂之怒的影响。快跑开！"
D.Strings[61979]="你也明白，只有果断行动才能赢得战争，祝掌门。"
D.Strings[61980]="我看到六……不，七个守卫在天上巡逻。"
D.Strings[61981]="有一个比其他人飞得都高……他一直独自在海面上盘旋。他脱队了。这是个机会。"
D.Strings[61982]="我们得干掉他，并利用他的航线。动手！"
D.Strings[61983]="再靠近一点……"
D.Strings[61984]="赞达拉比我预想得还要警觉。看下面——全是巡逻兵。"
D.Strings[61985]="那些弓箭手密切监视着港区。"
D.Strings[61986]="他们的萨满用岗哨图腾拉起了一张警戒网。"
D.Strings[61987]="给，用这些飞镖尽量多打倒一些弓箭手。"
D.Strings[61988]="这些烟雾弹可以蒙蔽岗哨图腾。"
D.Strings[61989]="我们不能一直这样转圈。行动起来，我来想想下一步的计划。"
D.Strings[61990]="得多消灭一些防御部队，否则我们永远也进不去！再转一圈。"
D.Strings[61991]="醒来吧，虎申！你来负责码头。不要让任何人通过陛下的大门。"
D.Strings[61992]="雷电之王的旨意必将实现。"
D.Strings[61993]="时间到了。我们得登上那条船。"
D.Strings[61994]="我们得破坏对着船头的攻城武器，然后到甲板下面去找船长。"
D.Strings[61995]="放松点……靠过去，放倒他们。"
D.Strings[61996]="我来对付那个丑八怪。"
D.Strings[61997]="没我想得那么安静，但还是成功了。"
D.Strings[61998]="巨魔一旦触发它们，就会得到一个意想不到的惊喜。我们继续。"
D.Strings[61999]="%s安详地打着鼾。"
D.Strings[62000]="嗯——什么？入侵者！"
D.Strings[62001]="如果熊猫人就这点水平，那这片土地很快就得归我们了！"
D.Strings[62002]="哦呵呵，你是在给我挠痒痒。我已经玩够了。"
D.Strings[62003]="我是永不沉没的！"
D.Strings[62004]="你们……休想活着……逃出这里……"
D.Strings[62005]="庭院的大门就在那座山上。"
D.Strings[62006]="记住，躲开那些岗哨图腾。"
D.Strings[62007]="我们走。"
D.Strings[62008]="他们好像发现那个小礼物了。"
D.Strings[62009]="过来！到烟雾里来！"
D.Strings[62010]="躲够了没，小鬼们！"
D.Strings[62011]="你们无路可逃了。唯一的出路就是穿过我！"
D.Strings[62012]="穿过你是吗？这应该没问题。"
D.Strings[62013]="你想要我怎么穿过你呢？"
D.Strings[62014]="这些大门已经奉旨关闭了。"
D.Strings[62015]="你，熊猫人！你很快就会重新戴上镣铐。"
D.Strings[62016]="你的小伙伴就任我处置了。"
D.Strings[62017]="入侵者必将伏诛！"
D.Strings[62018]="滚、开！"
D.Strings[62019]="攻击我就等于攻击陛下！他是不会接受这种侮辱的！"
D.Strings[62020]="谁也……休想……"
D.Strings[62021]="干得好！现在——去门口。趁雷电之王的大军还没过来！"
D.Strings[62022]="游侠们——破坏铰链。把门打开！"
D.Strings[62023]="计划成功了！你们俩简直抵得上一整支军队。"
D.Strings[62024]="我同伴出色的战斗技巧已经迅速在影踪派中传开了。"
D.Strings[62025]="确实如此。我们送你们回去吧。多亏你们，雷神现在已经四面楚歌了。"
D.Strings[62026]="摄政王一定想听听完整的报告。我们送你回去吧——你该休息了。"
D.Strings[62027]="你相信吗？当我着手研究掩盖体味的魔法时，还受过嘲笑。大法师们都觉得我的研究不切实际，而且浪费时间。$b$b看看，现在站在魔暴龙的上风口笑的人又是谁？哈！"
D.Strings[62028]="真可惜，我只能掩盖我们自己的气味，却没办法驱散赞达拉巨魔和他们那些畜生身上的恶臭。"
D.Strings[62029]="我向来不喜欢野外工作，尤其是牵涉到一大群巨魔的工作。"
D.Strings[62030]="别停下！躲开暴风领主的闪电！"
D.Strings[62031]="靠近雅丽亚，接受她的治疗，勇士！"
D.Strings[62032]="躲开山怖的攻击。我们比他更快，更聪明！"
D.Strings[62033]="靠近雅丽亚，让她治疗你！"
D.Strings[62034]="你们的哀嚎将取悦陛下！"
D.Strings[62035]="我们是主，你们是仆！"
D.Strings[62036]="懦夫。你们影踪派只敢像蟑螂一样在阴影里活动。"
D.Strings[62037]="%s开始治疗她的姐妹！"
D.Strings[62038]="我受够你的无礼了！我要掐死你，放肆的奴隶！"
D.Strings[62039]="啊——杀了他。快！"
D.Strings[62040]="刺入的长矛上生成了一个暴风精华并锁定了你！"
D.Strings[62041]="我……不……陛下！陛下，我辜负了您！"
D.Strings[62042]="雷霆之主……保护我！"
D.Strings[62043]="|TInterface\\Icons\\ability_warlock_jinx:20|t%s开始施放|cFFF00000|Hspell:137891|h[扭曲命运]|h|r！"
D.Strings[62044]="阴影将成为我们的盟友。"
D.Strings[62045]="排队等待黑暗中的匕首场景战役。"
D.Strings[62046]="赞达拉是个骄傲的种族。他们的骄傲迟早会毁了他们。$b$b就算是最强大的敌人也会有弱点，我们只需要找出这个弱点就行了。"
D.Strings[62047]="生命之火……就此……熄灭了……"
D.Strings[62048]="鲜血！可口的鲜血！你将成为我的美餐！"
D.Strings[62049]="就连你自己的鲜血都能派上用处！"
D.Strings[62050]="不！我……流血了……"
D.Strings[62051]="勇士！战局已经处于白热化状态：我们推进到了雷电之王的宫殿门口。现在该去打破他的前门了。"
D.Strings[62052]="做好出击的准备后，请告诉我一声！"
D.Strings[62053]="你总在我们最需要的时候出现，英雄。该去踢开雷电之王的前门了。"
D.Strings[62054]="普罗德摩尔女士！人员已经就位，影踪派也进去了，但是……"
D.Strings[62055]="可是什么？"
D.Strings[62056]="部落就在庭院的对面。"
D.Strings[62057]="他们当然会来。一个个来，温蕾萨。"
D.Strings[62058]="全体前进！"
D.Strings[62059]="……如果有谁遇到艾萨斯·夺日者这个叛徒，记得把他留给我……"
D.Strings[62060]="别管部落——我们先对付守门的赞达拉！"
D.Strings[62061]="普罗德摩尔女士——码头上的赞达拉巨魔又冲过来了。"
D.Strings[62062]="他们想袭击我们的侧翼。守住这里！"
D.Strings[62063]="小心，他冲你去了！"
D.Strings[62064]="别让他靠近你！"
D.Strings[62065]="小心——他朝你去了！"
D.Strings[62066]="你们“联盟”空有速度，毫无力量可言。"
D.Strings[62067]="你们“部落”就是一群恶心的畜生，连奴隶都不如。"
D.Strings[62068]="你看到了？这世上没有力量能践踏纯洁的灵魂。"
D.Strings[62069]="祝掌门！联盟——部落——这里马上就要乱作一团了！"
D.Strings[62070]="真幼稚。"
D.Strings[62071]="陶矢！把武器给我。"
D.Strings[62072]="掌门……你伤得很重！"
D.Strings[62073]="我的武器！勇士，跟我来。我要你见证这一切。"
D.Strings[62074]="交出大法师，这样，我或许还能放你一条生路，洛瑟玛。"
D.Strings[62075]="普罗德摩尔！放了我在紫罗兰监狱的同胞，否则我就亲手杀了你！"
D.Strings[62076]="你所谓的同胞都是些战俘。他们居然敢在我的城市里策划袭击了达纳苏斯——"
D.Strings[62077]="夺日者根本不知道加尔鲁什袭击达纳苏斯的事！"
D.Strings[62078]="艾萨斯·夺日者不安地动了动。"
D.Strings[62079]="够了！！今天已经流了太多的血。"
D.Strings[62080]="我现在明白你们联盟和部落为何总是争斗不休了。"
D.Strings[62081]="每一次报复本身就是一次侵略，而每一次侵略又会立刻引来报复。"
D.Strings[62082]="他们破坏了我们每一次的和平努力！"
D.Strings[62083]="我必须保护我的人民。"
D.Strings[62084]="闭嘴！你们必须打破这个循环。"
D.Strings[62085]="这循环要在今日，此地结束。当你，摄政王，和你，普罗德摩尔女士，放过彼此，并各自回头。"
D.Strings[62086]="吉安娜深吸了一口气。"
D.Strings[62087]="洛瑟玛眯起了眼睛。"
D.Strings[62088]="游侠们。放下武器。"
D.Strings[62089]="按我说的做。"
D.Strings[62090]="很好。我们可以撤退。"
D.Strings[62091]="他们杀了我丈夫！"
D.Strings[62092]="这也不能让他活过来。"
D.Strings[62093]="但记住，“血”精灵：只要地狱咆哮还是部落酋长，我们就谈不上和平。"
D.Strings[62094]="这正是我今天决定保存实力的原因。"
D.Strings[62095]="吉安娜的表情柔和了下来。"
D.Strings[62096]="阁下。"
D.Strings[62097]="女士。"
D.Strings[62098]="快收拢伤员，撤回港口去。"
D.Strings[62099]="大家回营地休整。我们的任务完成了。"
D.Strings[62100]="祝掌门！"
D.Strings[62101]="勇士，这次停战也许持续不了多久，但请记住这一切。"
D.Strings[62102]="我们得送你回禅院。"
D.Strings[62103]="山怖的怪物还在宫殿之下。我们必须在它肆虐潘达利亚之前阻止它。"
D.Strings[62104]="雅丽亚，保护祝掌门。"
D.Strings[62105]="英雄，击败暴风领主纳拉克就靠你了。你得集结一支小部队。"
D.Strings[62106]="但以我今天的所见所闻，我对你有信心。"
D.Strings[62107]="与你并肩作战是莫大的荣幸。谢谢你。"
D.Strings[62108]="我相信你，英雄。将我的法杖放到雷电之王的平台上，它会搞定一切。敢接受这个任务的都是勇士。祝你好运！"
D.Strings[62109]="你成功了！不可思议！熊猫人游学者会传颂你的事迹的！"
D.Strings[62110]="我感觉……雷电之王的力量在我的法杖中流过。"
D.Strings[62111]="尤其是，你彻底破坏了雷电之王的恐怖机器，没有让部落将它们据为己有。"
D.Strings[62112]="如果有机会的话，我会用这根法杖炸毁奥格瑞玛的城墙，让它砸到加尔鲁什·地狱咆哮的头上。"
D.Strings[62113]="谢谢你，朋友。联盟幸亏有你。"
D.Strings[62114]="你赢得了我的信任，英雄。但这将是你最危险的一次任务：从雷电之王的巢穴中偷出他的秘密。祝你好运。"
D.Strings[62115]="你带来了什么？啊！好极了。"
D.Strings[62116]="以鲜血为源——这种魔法很强大。或许是泰坦的杰作？它是怎么运转的？"
D.Strings[62117]="艾萨斯，让我们最好的法师来研究它。我们有很多东西要学。"
D.Strings[62118]="谢谢你，勇士！部落或许正处在危机边缘，但无论如何，你在这片海滩上的行动已经确保了我们的生存与发展。"
D.Strings[62119]="你赢得了我们最深的谢意。Al diel shala，英雄。"
D.Strings[62120]="这么快就死了。"
D.Strings[62121]="你们是怎么打败我的？"
D.Strings[62122]="无聊。你该死了。"
D.Strings[62123]="雷电之王赐予我力量！来吧，我会让你们看到的！"
D.Strings[62124]="我必须消灭你们。"
D.Strings[62125]="碾碎你的骨头！"
D.Strings[62126]="我能呼风唤雨！"
D.Strings[62127]="|TInterface\\Icons\\ability_vehicle_electrocharge:20|t%s的|cFFFF0000|Hspell:137422|h[专注闪电]|h|r锁定了你。快跑！"
D.Strings[62128]="下层某个鸟巢中的蛋开始孵化了！"
D.Strings[62129]="使用位移石板。"
D.Strings[62130]="%s正准备施放|cFFFF0000|Hspell:133939|h[狂暴岩石吐息]|h|r！"
D.Strings[62131]="上层某个鸟巢中的蛋开始孵化了！"
D.Strings[62132]="快使用云雾地砖驱散雷电之王的斗篷！"
D.Strings[62133]="一片全新的土地正在遭受邪恶恐怖的侵蚀。一片全新的土地在等着我们去拯救。"
D.Strings[62134]="有人嘲笑我对野兽的关注。而我要嘲笑他们的冷漠。"
D.Strings[62135]="我们可以从这些赞达拉巨魔身上学到很多东西，尤其是去做他们不做的那些事。"
D.Strings[62136]="阿曼尼帝国所向披靡！"
D.Strings[62137]="雷电……之王……承诺过……"
D.Strings[62138]="你休想阻挠赞达拉！"
D.Strings[62139]="雷神赐予我们力量！"
D.Strings[62140]="雷电之王指引我们的道路！"
D.Strings[62141]="颤栗吧！"
D.Strings[62142]="你的灵魂归我了！"
D.Strings[62143]="雷电之王会因此奖赏我们的！"
D.Strings[62144]="见证缚灵者的力量吧！"
D.Strings[62145]="赞达拉所向无敌。"
D.Strings[62146]="雷电之王的力量将使赞达拉重生。"
D.Strings[62147]="雷神之力令我们更加强大！"
D.Strings[62148]="你将付出灵魂的代价！"
D.Strings[62149]="这些蠢货自以为曾击败过我。这只会让我更加强大。现在，看看赞达拉真正的力量吧！"
D.Strings[62150]="雷神要我们证明赞达拉的力量。我们将碾碎这些入侵者！"
D.Strings[62151]="我们绝不会辜负他！"
D.Strings[62152]="达卡莱部族绝对不会输给你们这种人！"
D.Strings[62153]="你们遇到对手了，蠢货！"
D.Strings[62154]="帝国……绝不会……陷落……"
D.Strings[62155]="死神冰冷的拥抱。"
D.Strings[62156]="见证达卡莱的力量！"
D.Strings[62157]="怕冷了吗？"
D.Strings[62158]="凛冬将至……"
D.Strings[62159]="让沙德拉的怒火消灭你！"
D.Strings[62160]="反抗帝国的人统统去死！"
D.Strings[62161]="沙德拉……救救……我……"
D.Strings[62162]="又一个神灵的祭品！"
D.Strings[62163]="她将享用你的灵魂！"
D.Strings[62164]="让她的毒液杀死你！"
D.Strings[62165]="缚灵者让我看到了你的灵魂！"
D.Strings[62166]="迎接你的末日吧！"
D.Strings[62167]="他们自以为能阻止法拉基部族？"
D.Strings[62168]="流沙将湮没一切！"
D.Strings[62169]="我将……归于……流沙……"
D.Strings[62170]="流沙无穷无尽。"
D.Strings[62171]="这只是第一个！"
D.Strings[62172]="小心脚下！"
D.Strings[62173]="风暴将至！"
D.Strings[62174]="雷神赐予我们生命！"
D.Strings[62175]="我将埋葬你们！"
D.Strings[62176]="这些不自量力的爬虫。戈拉亚，要是你想用这些废物来证明“实力”，那我也无所谓。"
D.Strings[62177]="宝珠邪恶地旋转起来……"
D.Strings[62178]="宝珠爆炸了！"
D.Strings[62179]="好啊。你的出场还真拉风。"
D.Strings[62180]="这边。这些门只能从内侧开启。"
D.Strings[62181]="我们可以悄悄溜过去，或者直接杀进去。你决定吧。"
D.Strings[62182]="魔古族用鲜血和钢铁锻造武器。他们的利刃必须啜饮死亡。"
D.Strings[62183]="奴隶——到处都是奴隶。你明白我们为何要抗争了吧。"
D.Strings[62184]="影踪派总是从阴影中出击，让我们的敌人惧怕黑暗。"
D.Strings[62185]="我也算见过些场面。可魔古族的残暴还是令我的血液为之凝固。"
D.Strings[62186]="我们进入了魔古战争机器的核心。"
D.Strings[62187]="我为此苦练了一辈子。"
D.Strings[62188]="他们会明白，在影踪派面前，没有安全的地方。"
D.Strings[62189]="我喜欢迅捷而安静的杀戮。但你的方式也有好处。"
D.Strings[62190]="你的战斗技巧很惊人。"
D.Strings[62191]="影踪派永不停歇。"
D.Strings[62192]="放轻脚步！我们就快到门边上了。"
D.Strings[62193]="看——奴隶主！你去引开他，我来开锁。"
D.Strings[62194]="这锁……比我预想的还要复杂……"
D.Strings[62195]="缠住他！我就快成功了！"
D.Strings[62196]="成功了！门打开了！"
D.Strings[62197]="法拉基大军从法拉基部族之门中涌出！"
D.Strings[62198]="古拉巴什大军从古拉巴什部族之门中涌出！"
D.Strings[62199]="达卡莱大军从达卡莱部族之门中涌出！"
D.Strings[62200]="阿曼尼大军从阿曼尼部族之门中涌出！"
D.Strings[62201]="鬼魂消失在了迷雾中……"
D.Strings[62202]="归来吧，我的主人。"
D.Strings[62203]="我就是你的主人。"
D.Strings[62204]="别……过来。"
D.Strings[62205]="你看起来不太像他。"
D.Strings[62206]="不！不不！放下它。"
D.Strings[62207]="你们还站在那里做什么？把那些箱子运走！"
D.Strings[62208]="这不是结构性的损坏。回去干活儿。"
D.Strings[62209]="你是不是连走路都不会了？赶紧动动腿，你这一无是处的废物！"
D.Strings[62210]="那些桶呢？被你弄丢了？我们需要更多的桶！"
D.Strings[62211]="如果你再敢弄丢一个箱子，我发誓我一定要把你拆了。"
D.Strings[62212]="你怎么又把货物弄丢了？我发誓，我鞋子里的宝石都比你聪明。"
D.Strings[62213]="理论上说，这些水晶都是天然的绝缘体。它们可以吸收这个地区的大部分闪电打击。"
D.Strings[62214]="说明书上写明这些水晶需要多少法力了吗？我可不想在用了它之后就变成任人宰割的可怜虫。"
D.Strings[62215]="我觉得左边那块水晶有瑕疵。我们不该赶工的。事故就是这么来的。"
D.Strings[62216]="这座岛是怎么回事？为什么不管我走到哪里，我的头发总是会竖起来？"
D.Strings[62217]="每当这种时候，我都会怀念以前使用邪法的光景。它虽然很邪恶，但很管用。"
D.Strings[62218]="这些足够消灭那些飞翼龙了吗？"
D.Strings[62219]="有人告诉我，这些水晶在天然状态下是蓝色的。我很高兴有人花时间做了点适当的美化。"
D.Strings[62220]="据说赞达拉的统治者，神王拉斯塔哈在黄金宝座上统治着自己强大的帝国。"
D.Strings[62221]="多年前，他就在这个辉煌的宝座上，接见了黑暗先知：祖尔。"
D.Strings[62222]="祖尔向拉斯塔哈警告了可怕的大灾变。因为祖尔预见到一头装甲巨龙用可怕的巨颚撕裂了世界。"
D.Strings[62223]="拉斯塔哈无动于衷。"
D.Strings[62224]="几个月之后，祖尔又带回了更可怕的预言。他看见大群蛟龙从张开的裂隙中汹涌而出，撕裂了海床。"
D.Strings[62225]="拉斯塔哈还是无动于衷。"
D.Strings[62226]="最后，在大灾变发生的几个月前，祖尔又回来了。他撕碎衣裳，扔掉法杖，预言了地震与海啸的到来。"
D.Strings[62227]="他描述了赞达拉的黄金都城将在大灾变后慢慢沉入海底，昔日伟大的人民随着自己的杰作永远葬身海底。"
D.Strings[62228]="拉斯塔哈厌烦了祖尔和他的噩梦。为了摆脱先知，他让祖尔乘上自己最大的船只，好让他和他的追随者在预言实现时去寻找新大陆。"
D.Strings[62229]="他的预言真的实现了。"
D.Strings[62230]="当死亡之翼冲出大漩涡，黑暗的怒涛涌入赞达拉的都城。大地之脊一分为二，很快，这座城市和它所有的财富一同沉入大海。"
D.Strings[62231]="赞达拉人向他们的君王求助，可只有一个人能帮他们：先知祖尔。这位先知在他的国王麻木不仁时，已经召集了一支强大的舰队。"
D.Strings[62232]="现在你该明白了，君王们真正的力量源于帮助自己的人民。"
D.Strings[62233]="当他们玩忽职守时，就将权利让给了有能力的人。"
D.Strings[62234]="魔古族中流传着雷电之王雷神的传说。"
D.Strings[62235]="他的追随者向他跪下，并说：“我们将称您为‘闪电之王’。”"
D.Strings[62236]="据说他挖出了魔古之神的心脏。这骇人听闻的暴行令野心勃勃的雷神获得了风暴的力量。"
D.Strings[62237]="但雷神并不满意。"
D.Strings[62238]="“闪电的力量转瞬即逝，”他说道。"
D.Strings[62239]="“可雷电。雷电！它预示着风暴的来临。”"
D.Strings[62240]="“在闪电到来之前，雷电已经撼动苍穹；当闪电消散之后，雷电依然振动群山。”"
D.Strings[62241]="“是雷电令百兽瑟缩，是雷电令农夫恐惧。就让雷电成为我的先驱，让我的力量传遍大地。”"
D.Strings[62242]="“我将成为……雷电之王。”"
D.Strings[62243]="噢，我的朋友——那可怕的声音。数百年来，雷电可怕的巨响一直在熊猫人心中回荡。"
D.Strings[62244]="据说在熊猫人发动起义之后，希望的化身朱鹤在天空挂上了彩虹，好让熊猫人不再害怕风暴。"
D.Strings[62245]="我今天却没看见彩虹。你呢？"
D.Strings[62246]="父传子，母教女。作为父母，我们会将自己的遗产传给孩子。"
D.Strings[62247]="我们该给后代灌输怎样的价值观呢？"
D.Strings[62248]="孩子会从我们的错误中学到什么？"
D.Strings[62249]="我们该给子孙后代创造并留下一个怎样的世界？"
D.Strings[62250]="父母将孩子送上人生的道路，却不知道他们会走向何方。"
D.Strings[62251]="魔古族也是孩子。泰坦的孩子。他们曾是一支岩石大军，没有思想，只懂服从。"
D.Strings[62252]="他们按泰坦的指令与古神的可怕仆从战斗。他们垒起高山，挖开河流。"
D.Strings[62253]="他们在今天被我们称为锦绣谷的隐秘山谷建立了生命的魔法摇篮。"
D.Strings[62254]="可是，泰坦逐渐沉寂，他们的造物受到血肉的诅咒。"
D.Strings[62255]="魔古族变得残暴。多年之后，雷电之王统一了他们，他们获得了自己的遗产！"
D.Strings[62256]="我现在真的相信魔古族以为自己在完成泰坦的工作。他们与螳螂妖斗争，并使用锦绣谷的力量创造新生命。"
D.Strings[62257]="啊，多么可怕的工作！"
D.Strings[62258]="父母并不能确保自己总能留下好的遗产。"
D.Strings[62259]="尤其是，当父母本身是神，而他们的孩子却是怪物时。"
D.Strings[62260]="我只需要你的心脏。"
D.Strings[62261]="投降吧，我会给你个痛快的。"
D.Strings[62262]="兄弟们，又来了一个祭品！"
D.Strings[62263]="我就喜欢让敌人流血。"
D.Strings[62264]="我听到你的鲜血在流淌。"
D.Strings[62265]="快来帮忙，我宠物们。"
D.Strings[62266]="美餐送上门了！"
D.Strings[62267]="你将变成宠物们的美餐！"
D.Strings[62268]="有时他们不得不直接吞了你。"
D.Strings[62269]="兄弟们，我的宠物得到了一顿大餐。"
D.Strings[62270]="你是个弱者，朋友。"
D.Strings[62271]="你犯了一个的错误。"
D.Strings[62272]="又一个送死的蠢货。"
D.Strings[62273]="这家伙太英勇了。"
D.Strings[62274]="这家伙会死得很滑稽。"
D.Strings[62275]="仪式不能停止。"
D.Strings[62276]="你休想阻止我们！"
D.Strings[62277]="你应该敬畏神灵。"
D.Strings[62278]="神灵之力降临了。"
D.Strings[62279]="别干扰我们。"
D.Strings[62280]="什么？！那是什么？"
D.Strings[62281]="我什么也没看见。哈。那些愚蠢的巨魔连弄垮隧道都做不好。"
D.Strings[62282]="不对……也许有人正隐藏在暗处。把蜥蜴人奴隶找来！让他们嗅出那些入侵者……"
D.Strings[62283]="黑暗意志狂暴了！"
D.Strings[62284]="遵命，主人！我将血战到底！"
D.Strings[62285]="他们不是我孟楚的对手！"
D.Strings[62286]="直面真正的力量吧！"
D.Strings[62287]="哼，可悲的花招。"
D.Strings[62288]="我要踩扁你！"
D.Strings[62289]="还需要……训练……"
D.Strings[62290]="魁兹扎尔！向我的敌人发动风暴！！"
D.Strings[62291]="玳刃！冻死他们！"
D.Strings[62292]="孟楚，快攻击。不要手下留情！"
D.Strings[62293]="没脑子的废物。这点损失不算什么。"
D.Strings[62294]="集中精神，魏尚。让你的敌人尝尝痛苦的滋味！"
D.Strings[62295]="他曾为荣誉而战。这是他最大的错误。"
D.Strings[62296]="啊！没用的杂种！我要亲手杀了你们！"
D.Strings[62297]="够了！过来，爬虫。你们已经得到了奖赏。现在，你们将面对铁穹。"
D.Strings[62298]="回头吧，陌生人！你们将面对铁穹的大军！"
D.Strings[62299]="这怎么可能？！"
D.Strings[62300]="那好吧……"
D.Strings[62301]="真有这个必要吗……？"
D.Strings[62302]="你不该来这儿。"
D.Strings[62303]="好温暖。"
D.Strings[62304]="让我……安静一会儿！"
D.Strings[62305]="请走吧！你们激怒她了。"
D.Strings[62306]="只此一次……"
D.Strings[62307]="好孤单……"
D.Strings[62308]="再添点儿柴！来吧，露琳……把他们烧成灰烬！"
D.Strings[62309]="痛苦地死去吧！"
D.Strings[62310]="我看见了光明……"
D.Strings[62311]="入侵者！王座守卫，醒来吧！"
D.Strings[62312]="死亡之焰！"
D.Strings[62313]="露琳！将你的力量借给我！"
D.Strings[62314]="见证痛苦的真谛吧！"
D.Strings[62315]="彻底解决这些魔古族的时候到了。"
D.Strings[62316]="我来解决这里的塌方，然后我们就从后面溜进去。你准备好就告诉我一声。"
D.Strings[62317]="|TInterface\\Icons\\ability_monk_forcesphere.blp:20|t杜鲁姆开始为自己的心灵之眼充能，对|cFFFF0000$n|r施放|cFFFF0000|Hspell:136932|h[意志之力]|h|r！"
D.Strings[62318]="|TInterface\\Icons\\inv_misc_eye_02.blp:20|t杜鲁姆开始为自己的权衡之眼充能，以施放|cFFFF0000|Hspell:133792|h[纠缠凝视]|h|r！"
D.Strings[62319]="|TInterface\\Icons\\spell_shadow_lifedrain02.blp:20|t杜鲁姆开始为自己的饥饿之眼充能，对|cFFFF0000$n|r施放|cFFFF0000|Hspell:133795|h[生命吸取]|h|r！"
D.Strings[62320]="|TInterface\\Icons\\spell_shadow_curseofmannoroth.blp:20|t杜鲁姆开始为自己的邪恶之眼充能，对|cFFFF0000$n|r施放|cFFFF0000|Hspell:133597|h[黑暗寄生]|h|r！"
D.Strings[62321]="|TInterface\\Icons\\priest_icon_chakra_blue.blp:20|t杜鲁姆开始为自己的蓝色之眼充能，对|cFFFF0000$n|r施放|cFFFF0000|Hspell:134122|h[蓝光]|h|r！"
D.Strings[62322]="|TInterface\\Icons\\priest_icon_chakra_red.blp:20|t杜鲁姆开始为自己的红色之眼充能，对|cFFFF0000$n|r施放|cFFFF0000|Hspell:134123|h[红光]|h|r！"
D.Strings[62323]="|TInterface\\Icons\\priest_icon_chakra.blp:20|t杜鲁姆开始为自己的黄色之眼充能，对|cFFFF0000$n|r施放|cFFFF0000|Hspell:134124|h[强光]|h|r！"
D.Strings[62324]="红光照出了一只猩红雾行兽！"
D.Strings[62325]="强光照出了一只琥珀雾行兽！"
D.Strings[62326]="蓝光照出了一只碧蓝雾行兽！"
D.Strings[62327]="刺眼强光照出了一只苍白雾行兽！"
D.Strings[62328]="又有活儿干了？"
D.Strings[62329]="我们必须要了解魔古族的历史。知己知彼，才能百战不殆。"
D.Strings[62330]="魔古族的历史中充斥着野蛮的征服和力量的试炼。数千年来，这个种族中只有最强者才能生存下来。"
D.Strings[62331]="兽神倒下了！兄弟们，誓死保卫议会！"
D.Strings[62332]="<这个血精灵显然还在发抖。>$B$B太可怕了，太可怕了！我们被俘之后，一个魔古族捏着我的脖子。我以为自己死定了，可是那个魔古只是一捏然后一拉，我就觉得肺里的空气好像全被挤了出来。$B$B一阵可怕的扭曲和撕裂之痛向我袭来。我的皮肤和骨头就像火烧一样撕心裂肺。突然，我就从自己的身体里飘了出来。$B$B那个魔古对着我哈哈大笑，我就知道自己的灵魂将永远在痛苦中煎熬。$B$B你有没有品尝过纯粹的恐惧，$c？我就试过。$B$B<血精灵又颤抖了一下，便开始沉默了。>"
D.Strings[62333]="农夫思考着如果没有工作，那生命还有什么意义。"
D.Strings[62334]="坚强点，$c。魔古族是不会轻易放下屠刀的。在这个被遗忘的岛上，我们必须为每一寸土地而奋斗。"
D.Strings[62335]="我对魔古族的文化和历史相当感兴趣。我这可不是一时心血来潮。"
D.Strings[62336]="大法师茉德拉采用了一种直截了当的策略——武力击败魔古族。我相信随着进一步的研究，我们或许就能发现魔古族的弱点。"
D.Strings[62337]="我决定要写一本书，就叫《魔古族魔法之谜》。听上去很厉害吧？"
D.Strings[62338]="农夫希望能有更多的工作。"
D.Strings[62339]="我们在这里的人数远逊于敌人，但只要切实贯彻预定的战术，我相信我们是可以成功的。"
D.Strings[62340]="我们的战术很有效。胜利的果实正在向我们招手，我们决不能在这个时候动摇。"
D.Strings[62341]="|TInterface\\Icons\\spell_nature_lightningoverload.blp:20|t|cFFFF0000东北部|r的大门敞开，引发了|cFFFF0000|Hspell:136889|h[暴乱狂风]|h|r！"
D.Strings[62342]="|TInterface\\Icons\\spell_nature_lightningoverload.blp:20|t|cFFFF0000东南部|r的大门敞开，引发了|cFFFF0000|Hspell:136889|h[暴乱狂风]|h|r！"
D.Strings[62343]="|TInterface\\Icons\\spell_nature_lightningoverload.blp:20|t|cFFFF0000西南部|r的大门敞开，引发了|cFFFF0000|Hspell:136889|h[暴乱狂风]|h|r！"
D.Strings[62344]="准备工作。"
D.Strings[62345]="尝尝我的力量吧。"
D.Strings[62346]="这些农夫为什么显得这么沮丧？"
D.Strings[62347]="啊，久违的风暴之拥……"
D.Strings[62348]="创造……与毁灭之触。"
D.Strings[62349]="我在黑暗中等待了上千年，在死寂中只有受难者的尖叫，这是一个活生生的噩梦。"
D.Strings[62350]="我看到你们眼中天真的希望。你们……想来拯救我？丢掉那可笑的怜悯，打起精神吧，你们即将品尝我的痛苦。"
D.Strings[62351]="这扭曲的世界完了，被蒙蔽的英雄救不了它。清除堕落的唯一方法就是毁灭。就从现在……开始。"
D.Strings[62352]="我就先解决你们，再去净化这个世界。现在，去死吧！"
D.Strings[62353]="感受灵魂的背叛吧。"
D.Strings[62354]="顺应天命吧。"
D.Strings[62355]="有意思。你们真以为自己能赢。"
D.Strings[62356]="你们觉得还有胜利的希望？愚蠢！"
D.Strings[62357]="你们已经算是这个世界的精英了吗？哈，难怪它会沦为废墟。"
D.Strings[62358]="等等！我……我不是你们的敌人。你们很强。甚至，比他更强……或许你们是对的。或许还有希望。"
D.Strings[62359]="他们在为没有工作而沮丧？"
D.Strings[62360]="没错。"
D.Strings[62361]="可你们脚下就是黑暗的深渊，凡人。巨大的，无止尽的，吞噬一切的深渊。我不信你们能改变毁灭的结局。"
D.Strings[62362]="可……你们赢得了尝试的权利。再见。"
D.Strings[62363]="攻势已经发动，但重磅炸药还没有到位！"
D.Strings[62364]="在我召集援军时收集炸药，运到城墙下面。"
D.Strings[62365]="|TInterface\\Icons\\ability_warrior_throwdown:20|t%s抓住了$n并准备施放|cFFFF0000|Hspell:137175|h[雷霆投掷]|h|r！"
D.Strings[62366]="|TInterface\\Icons\\spell_shaman_thunderstorm:20|t%s开始引导一场剧烈的|cFFFF0000|Hspell:137313|h[闪电风暴]|h|r！"
D.Strings[62367]="%s死亡并向附近一名盟友发射弧形闪电！"
D.Strings[62368]="现在，去伊瓜鲁克峭壁。等你一到那里，我就给你施加另一半幻术。"
D.Strings[62369]="%s正在追踪你！"
D.Strings[62370]="$n受到了|cFFF00000|Hspell:136192|h[闪电风暴]|h|r的影响！"
D.Strings[62371]="守护者塔克乌正在施放火蛇吐息！快打断它！"
D.Strings[62372]="守护者塔克乌获得了九头蛇治疗波！快驱散它！"
D.Strings[62373]="陶矢指指哈鲁卡尔船长，然后用手指做了个割脖子的动作。"
D.Strings[62374]="%s使用|cFFFF0000|Hspell:138644|h[心能虹吸]|h|r从其他魔像处抽取能量！"
D.Strings[62375]="嘿，我们应该从黑暗神殿的边上跳下去，看看下面有什么！"
D.Strings[62376]="持续伤害！持续伤害！再来点持续伤害！"
D.Strings[62377]="……好了，结束持续伤害吧。"
D.Strings[62378]="看来你施放的暗影箭还不够多。"
D.Strings[62379]="上一个这么做的术士也失败了。"
D.Strings[62380]="有没有人说过你的手脚很笨？正确的姿势对施法是非常重要的！"
D.Strings[62381]="你是怎么活到今天的？我真佩服给你治疗的人！"
D.Strings[62382]="快跑到中间去！"
D.Strings[62383]="你不会以为他会就这么简单送你一团绿火的，对吧？"
D.Strings[62384]="治疗石！快用你的治疗石！"
D.Strings[62385]="那个终极厄运诅咒看起来很危险！驱散它，快！"
D.Strings[62386]="我要蓝火！"
D.Strings[62387]="你有没有试过不要站在那里面？那样或许会好一些。"
D.Strings[62388]="在法力值不足时，你就应该用魔杖！你有魔杖吧？"
D.Strings[62389]="我们应该喝点虎血。那我们就赢定了！"
D.Strings[62390]="%s正准备结束|cFFFF0000导管超能|r！"
D.Strings[62391]="小心点，阿加特！"
D.Strings[62392]="如果我们跑起来的话，是可以成功的！"
D.Strings[62393]="至少那里没有通电的铁丝网，或者巨魔。"
D.Strings[62394]="我早说了，你跟机械八字不合！"
D.Strings[62395]="我们该怎么了解一个已经绝种的生态系统呢？连这里的植物都是有毒的！"
D.Strings[62396]="你只带了七天份的食物！七天！这真是好极了。"
D.Strings[62397]="等我们重新控制住探险队，一切都会好起来的……"
D.Strings[62398]="由于某些奇怪的原因，我很喜欢盯着这根手杖看。唔……"
D.Strings[62399]="我们需要某种蛋白质的种群控制药物。或许我们应该在来这里之前就考虑好这个问题。"
D.Strings[62400]="探险队怎么会失败呢？我可是下了大本钱的！"
D.Strings[62401]="阿加特？奈莉？离开飞艇不是有点危险吗？"
D.Strings[62402]="有人，呃，听到了吗？那个，那个，那个震动。"
D.Strings[62403]="我在这里很紧张。"
D.Strings[62404]="记得提醒我谢谢汉姆洛克，他让我度过了一个愉快的周末。"
D.Strings[62405]="这是，呃，生命的轮回，唔。圣光创造了巨魔，巨魔创造了恐龙，恐龙吃人类，巨魔继承艾泽拉斯。"
D.Strings[62406]="你说他们会在，呃，旅途中带上这个吗？嗯？"
D.Strings[62407]="我真的很讨厌每次都被我说中。"
D.Strings[62408]="我是不是，唔，在自言自语？是吗？你看，我又说中了。"
D.Strings[62409]="互相掩护！坚守阵地！"
D.Strings[62410]="这才像我。丢掉文件，抛开政治——只有魔法与钢铁的炽烈怒火！"
D.Strings[62411]="前进！今天，我们将决定自己的命运！"
D.Strings[62412]="我们是部落。我们绝不后退。"
D.Strings[62413]="消灭他们。让他们看看我们的力量！"
D.Strings[62414]="兄弟们，消灭他们！"
D.Strings[62415]="万灵赐予你们力量！"
D.Strings[62416]="剐了他们！众神将畅饮他们的鲜血！"
D.Strings[62417]="碾碎他们！撕裂他们！"
D.Strings[62418]="雷电之王！多么强大的存在！"
D.Strings[62419]="要不是被熊猫人推翻并掩盖起来，他的帝国到今天会变成什么样子呢？"
D.Strings[62420]="我想不出比他更残暴的君主了。他奴役了整个大陆。"
D.Strings[62421]="对强者而言，仁慈是种奢望。没有哪个伟大的帝国是靠仁慈建立的。"
D.Strings[62422]="……我不知道。但我得说：没有哪个压榨人民的“伟大帝国”能经得起时间的考验。"
D.Strings[62423]="记住，魔古族被推翻了！雷电之王应该吸取教训。现在轮到你了。"
D.Strings[62424]="我很担心你太过软弱，不足以接过那个王冠，安度因王子。你该好好学学你父亲的强硬。"
D.Strings[62425]="你是在对我说教吗？你才多大——两岁？"
D.Strings[62426]="龙族的两岁。该你了。"
D.Strings[62427]="……你怎么还在玩那个东西？"
D.Strings[62428]="这是一种熊猫人的棋盘游戏。目标是双赢。"
D.Strings[62429]="简直荒唐！那有什么好玩的！？"
D.Strings[62430]="勇士，我们现在快回雷神岛去吧。我在熔炉那里等你，我们将共同制作一件传奇武器。"
D.Strings[62431]="为什么？你们俩有什么目的？"
D.Strings[62432]="……为了世界和平！"
D.Strings[62433]="就靠一座你们根本不了解的魔古武器熔炉？"
D.Strings[62434]="我亲爱的王子，我们的目标是一致的，只是投入程度不同。"
D.Strings[62435]="来吧，英雄！我们将打造全新的艾泽拉斯！"
D.Strings[62436]="勇士，我知道我们正在交战，可如果你盲目信任这头追逐力量的黑龙，那你又能比你的酋长强多少呢？请你三思。"
D.Strings[62437]="我的朋友，如果你盲目信任这头追逐力量的黑龙，那你又能比加尔鲁什强多少呢？请你三思。"
D.Strings[62438]="童福，有朋友来了？"
D.Strings[62439]="难以置信，你居然还活着。"
D.Strings[62440]="记得提醒我以后告诉你我们在拉文霍德庄园的事迹。那可真是一段好时光！"
D.Strings[62441]="我怎么说的来着？如此勇敢而坚毅的凡人实属罕见。"
D.Strings[62442]="老规矩，到石匠之愚上来见我！"
D.Strings[62443]="你们有什么阴谋？"
D.Strings[62444]="我向来坦荡！如果伤势允许，你可以一起来，安度因·乌瑞恩。"
D.Strings[62445]="但我得请求我的部落朋友别把你推下悬崖。"
D.Strings[62446]="真壮观！你见过这样的景色吗，安度因王子？"
D.Strings[62447]="真是震撼人心。"
D.Strings[62448]="它甚至令人心生敬畏。"
D.Strings[62449]="勇士！看看你的劳动成果吧！"
D.Strings[62450]="在世界破晓之初，凡人种族还很年轻，他们尚未掌握火的秘密。"
D.Strings[62451]="他们在凄风冷雨中颤栗，突然——闪电撕裂了天空！"
D.Strings[62452]="它劈倒了一棵树并将它点燃。"
D.Strings[62453]="凡人敬畏而惊奇地聚拢到火堆周围，用它烹煮、取暖。他们获取了它！小心呵护！"
D.Strings[62454]="火焰日以继夜地燃烧。红热的炭火在营地间传递。你明白了吗？只是一道闪电，文明由此诞生。"
D.Strings[62455]="闪电无疑是诸神赐下的礼物。"
D.Strings[62456]="魔古族，啊！魔古族！这些蠢货天生就是下人！当失去了主人，他们就转而侍奉自己。"
D.Strings[62457]="可他们原本可以更加伟大。"
D.Strings[62458]="他们本可以创造新世界，然而只建立起一个帝国。"
D.Strings[62459]="我们能做得更好。看！苍穹之冠！这是我的礼物。"
D.Strings[62460]="你就是那余烬！你就是那火星！你将成为燎原的烈焰。你将唤醒艾泽拉斯的潜力！"
D.Strings[62461]="过来。"
D.Strings[62462]="我们已经知道魔古族源自泰坦。可还有许多谜团。他们为何来此？为何来到潘达利亚？"
D.Strings[62463]="魔古族被派来守护什么？或是摧毁什么？我们还缺少关键线索，你得帮我找到它！"
D.Strings[62464]="这顶冠冕将成为你的第三只眼。它将我们连为一体。你将成为我的耳目。我们要一起揭开泰坦之谜。"
D.Strings[62465]="我会密切关注你的，英雄！"
D.Strings[62466]="勇士……如果我是你，一定会三思而行。"
D.Strings[62467]="根据这块符文石，魔古是泰坦创造的，没有灵魂的岩石生物。我猜也是。"
D.Strings[62468]="你又找到一块石头！上面写了什么？“血肉诅咒”将魔古变成凡人。啊——可他们找到了逆转诅咒的方法。聪明。"
D.Strings[62469]="魔古族侍奉一位名叫“莱”的泰坦守护者。在魔古语中，“莱登”即意为“主宰莱”。太神奇了！我需要更多信息！"
D.Strings[62470]="这里提到，魔古族和他们的主人被派来潘达利亚追踪巨大的黑暗——啊，这块碎片不完整。我们得找到剩余部分。"
D.Strings[62471]="这里提到了一位古神，“亚煞极”。这头野兽有七个头颅，能够吞吐黑暗。我怀疑如今困扰潘达利亚的煞魔就是这个家伙的手笔。"
D.Strings[62472]="这里提到了“生命的摇篮”。那是泰坦创造新物种的地方。噢，那一定是锦绣谷！它是一座生物实验室，就像安戈洛环形山或索拉查盆地。"
D.Strings[62473]="我们正在拼凑线索，勇士。魔古族是由泰坦创造并被派来守卫锦绣谷的。他们要守卫什么呢？古神是否仍是一个威胁呢？"
D.Strings[62474]="嘿，这块碎片提到了“亚煞极的飞翼军团。”那是古神的仆人吗？会不会是螳螂妖呢？"
D.Strings[62475]="这块符文石比较新。它提到了“沉睡的守护者”。我猜这是指莱登。可他为何会沉睡呢？"
D.Strings[62476]="你又找到了这个谜题的新线索！它是魔古族所刻。他们很沮丧——主人已经一千年没有下达指令了，他们的身体也变成了血肉之躯。他们发生了内讧。"
D.Strings[62477]="嗯。这里记录了魔古族早期的历史。他们分裂成数个部落。可有一位王者特别野心勃勃——雷电之王，雷神。泰坦守护者沉寂之后，雷神决心代他发号施令。"
D.Strings[62478]="啊！最后一块拼图也齐了。雷电之王窃取了莱登的力量，那是泰坦的精华。他统一魔古帝国，并试图继续泰坦的工作。显然他将自己看成了神！"
D.Strings[62479]="快，回雾纱栈道来找我。我们得当面谈谈。"
D.Strings[62480]="我一直在等待你的归来，勇士。"
D.Strings[62481]="雷电之王窃取了泰坦守护者的力量。我们得将它夺回来！"
D.Strings[62482]="将他的黑暗之核带给我。这不仅能帮熊猫人一把，解放出的力量也将再次造福艾泽拉斯。"
D.Strings[62483]="它让我毛骨悚然！"
D.Strings[62484]="我猜我们的朋友已经凯旋而归了。"
D.Strings[62485]="啊——君王之核。神明之力。"
D.Strings[62486]="你在干什么？你不会真的想吃它——"
D.Strings[62487]="它充满了泰坦的魔力，那是创造的语言——"
D.Strings[62488]="噢——我看见了——数百万个世界——闪烁着完美的光芒——其中一颗特别璀璨——噢——"
D.Strings[62489]="噢——我等已经陨落。我们必须挽救最后的泰坦。牢记这一点。"
D.Strings[62490]="你又想耍什么花招？"
D.Strings[62491]="结束了。我全都忘了。噢！他们也不记得了。真讽刺！"
D.Strings[62492]="你在说什么？我不相信你。"
D.Strings[62493]="那就对了。"
D.Strings[62494]="勇士，我需要时间来……“消化”这些信息。但我们很快就会行动的。"
D.Strings[62495]="你的职业冷却已经重置了！"
D.Strings[62496]="你们竟敢打断我的筹备工作！这一次，赞达拉不可阻挡！"
D.Strings[62497]="我命令你，消灭他们！不，住手！住手！"
D.Strings[62498]="是谁竟敢来打扰我？"
D.Strings[62499]="让万灵吞没你！"
D.Strings[62500]="不要后退，我们寸步不让！"
D.Strings[62501]="赞达拉就是一群走狗。听懂了没？你们就是魔古族的狗！"
D.Strings[62502]="所有人，相互靠拢，集中精力。"
D.Strings[62503]="继续进攻！我们要打得更聪明！"
D.Strings[62504]="谢谢你。现在，让我们攻破那道城墙吧！"
D.Strings[62505]="让我们与雷电之王决一死战吧！"
D.Strings[62506]="来吧！让我们继续前进！"
D.Strings[62507]="去死吧，赞达拉巨魔！"
D.Strings[62508]="在船只和上层大门间清出一条路来——我们得步行通过。"
D.Strings[62509]="Sinu a'manore，勇士。"
D.Strings[62510]="在影踪派和这头野兽的帮助下，我想我们能够潜入并摧毁雷电之王的武器库。"
D.Strings[62511]="艾尔希娅在等着你，勇士。"
D.Strings[62512]="难以置信。我就知道影踪派会是出色的盟友。"
D.Strings[62513]="无论如何，我们今天重创了雷电之王。部落的铁匠会立即开始研究魔古族的锻造技术。"
D.Strings[62514]="看情况，熊猫人朋友。这得看情况。"
D.Strings[62515]="我们有着共同的敌人，摄政王阁下。仅此而已。"
D.Strings[62516]="恕我直言——这些畸形的武器应该被销毁！"
D.Strings[62517]="很高兴再次见到你，冒险者。你做好出发的准备了吗？"
D.Strings[62518]="感谢你的帮助，冒险者。我们会尽力帮你挡住魔古族的。"
D.Strings[62519]="我准备好了，可以开始完成任务了。"
D.Strings[62520]="我的货物只卖给那些在战场上证明过自己的人。等你扫清了战场上的联盟渣滓再来找我吧。"
D.Strings[62521]="我的货物只卖给那些在战场上证明过自己的人。在我把它们托付给你之前，你得先证明自己比那些部落渣滓强。"
D.Strings[62522]="在邪刃祭司被克洛斯的回响吞噬之前，快去杀了他！"
D.Strings[62523]="你发现的这个生物能够免疫岛上的防御闪电。"
D.Strings[62524]="你能试着骑上它吗？"
D.Strings[62525]="很好！只要你飞上天空，赞达拉一定会来阻止你。"
D.Strings[62526]="做好空战的准备。必要时，你可以跳上别的坐骑！"
D.Strings[62527]="影踪派的密探会在矿洞后等你。别让她久等。祝你好运！！"
D.Strings[62528]="怎么了？又暴动了？"
D.Strings[62529]="我这就让你们滚回去。"
D.Strings[62530]="你不是奴隶。你在这里干什么？"
D.Strings[62531]="你马上就会被栓起来！到时候你会只求一死！！"
D.Strings[62532]="屈服于我！"
D.Strings[62533]="跪下吧！"
D.Strings[62534]="你会被……严惩的……"
D.Strings[62535]="余烬守护者提佐的生命值快要回满了！"
D.Strings[62536]="余烬守护者提佐正在偷取你所有的治疗！"
D.Strings[62537]="寇多克发动了一次强力盾牌猛击。"
D.Strings[62538]="耶！终于来了！我赢得了搏击俱乐部的邀请函！现在谁也别想拦着我！"
D.Strings[62539]="我想我还没有做好成为拳手的准备。"
D.Strings[62540]="大家快看！我赢得了搏击俱乐部的邀请函！我已经等不及要去试试身手了！"
D.Strings[62541]="我刚刚赢得了一张搏击俱乐部的邀请函！我今晚肯定就能到8级！但愿在抵达那里之前，我不会把票弄丢了。"
D.Strings[62542]="这上面的景色真是……激动人心！"
D.Strings[62543]="我的宠物，抓住他们！"
D.Strings[62544]="祝你安全降落，潜行者。"
D.Strings[62545]="正在……上升？"
D.Strings[62546]="但愿你在包里塞了羽毛，牧师。"
D.Strings[62547]="没有钱？那这次飞行就算我的好了。"
D.Strings[62548]="看呐！我真的掌握了这个世界的魔能！现在，我掌握着恶魔之力……它难以名状，无穷无尽，无所不能！"
D.Strings[62549]="你觉得我走火入魔了？没有这回事。黑暗收割议会将奴役最强大的恶魔，抽取他们的力量，并摧毁一切反抗者，无论是在这个世界，还是在艾泽拉斯！你真的想阻止我吗，小家伙？"
D.Strings[62550]="我的力量超出你的想象！"
D.Strings[62551]="哈。你虚弱无力的攻击简直令我发笑。想看看我的新宠物吗？"
D.Strings[62552]="我喜欢看你徒劳的挣扎。"
D.Strings[62553]="安尼赫兰是极具毁灭性的生物。他们那排山倒海般的力量无人能挡。"
D.Strings[62554]="什么？！这下你可惹怒我了。"
D.Strings[62555]="我要撕碎你的灵魂！"
D.Strings[62556]="死亡之翼曾拥有无可匹敌的力量。现在，它属于我了。"
D.Strings[62557]="你休想抗拒末日的降临！"
D.Strings[62558]="今天就是你的末日。"
D.Strings[62559]="毁灭之力！"
D.Strings[62560]="纯粹的……混乱。"
D.Strings[62561]="混乱将统治一切。"
D.Strings[62562]="混乱之力将毁灭你。"
D.Strings[62563]="你时日无多了……"
D.Strings[62564]="变幻莫测！"
D.Strings[62565]="你将为此烈火焚身。"
D.Strings[62566]="别动……"
D.Strings[62567]="这刚开始可能不算什么，但只要等一段时间，疼痛就会变得难以忍受。"
D.Strings[62568]="在痛苦中扭曲吧。"
D.Strings[62569]="疼痛正在增加。"
D.Strings[62570]="痛苦将悄悄降临到你身上。"
D.Strings[62571]="离我远点儿，杂种！"
D.Strings[62572]="我是神圣不可侵犯的！"
D.Strings[62573]="害怕地逃跑吧，懦夫。"
D.Strings[62574]="毁灭之力将从内部侵蚀你。"
D.Strings[62575]="埋下一颗种子，然后看着它成长……"
D.Strings[62576]="我很好奇这颗种子会长成什么？"
D.Strings[62577]="我将赐予你毁灭的礼物！"
D.Strings[62578]="当这颗种子发芽时，可怕的毁灭将等着你。"
D.Strings[62579]="混乱魔法总是有可能导致出人意料的后果。"
D.Strings[62580]="阿克蒙德聪明地利用了埃雷杜因。他们对黑暗能量的掌控无人能及。"
D.Strings[62581]="自从阿克蒙德死后，埃雷杜因就失去了主人。现在，我将成为他们的新主人。"
D.Strings[62582]="虽然不是最强大的战士，但一群地狱犬还是很有用的。"
D.Strings[62583]="地狱犬总是渴望能吞噬更多的魔法。"
D.Strings[62584]="如果说两个小鬼就是比一个要强，那什么能比两个小鬼更强呢？那就是六个小鬼。"
D.Strings[62585]="哪怕是最小的恶魔，只要数量够多，也是非常宝贵的助力。"
D.Strings[62586]="我只是按照你之前的要求罢了，坎雷萨德。事情发展到这一步都是你自找的。"
D.Strings[62587]="$n，感谢你的帮助。虽然全世界或许都不会知道，但你又默默地拯救了他们一次。我们必须阻止坎雷萨德。我会确保他被放逐后无法再回来。"
D.Strings[62588]="坎雷萨德周围的邪能太过充沛，他已经被彻底腐蚀了。但稍微尝试一下他的力量并无大碍。去吧。"
D.Strings[62589]="去吧，好好利用你所学到的一切。如果你想净化体内的邪能，或者重新吸收坎雷萨德的力量，就跟我谈谈。我会待在影月谷的诅咒祭坛，确保他被放逐。"
D.Strings[62590]="哈哈哈……你以为自己能击败我？现在，没有什么能杀死我了，卑微的凡人！"
D.Strings[62591]="现在，你的可悲传说即将落幕。"
D.Strings[62592]="裘碧卡？！你在干什么……？！"
D.Strings[62593]="……啊啊啊啊！！！"
D.Strings[62594]="好多小鬼！快解决他们！"
D.Strings[62595]="%s吞噬你的奴役恶魔！"
D.Strings[62596]="这么说，你们帮我处理了门口的垃圾。我想我还得说声谢谢。"
D.Strings[62597]="但也只能到此为止了。你们以为我会让你们长驱直入吗？这座桥还可以重建，可你们的骨头…哼…"
D.Strings[62598]="你们！你们激怒我了。我要拿你们做个榜样，让所有仰望我力量的人颤抖臣服。"
D.Strings[62599]="吾乃雷神，弑君之君，诛神之神。你们犯了一个可悲的错误。"
D.Strings[62600]="闪电，找到我的敌人！"
D.Strings[62601]="狂风，响应我的召唤！"
D.Strings[62602]="我的力量无可匹敌！"
D.Strings[62603]="你们这是自掘坟墓！"
D.Strings[62604]="你们想在我的圣殿内挑战我？认清你们的愚蠢吧！"
D.Strings[62605]="呸！我要亲自动手。看看你们要怎么抗衡闪电吧。"
D.Strings[62606]="你们一无是处！我掌握着苍穹的力量！"
D.Strings[62607]="不！你们这些废物！我……是……雷电之王！"
D.Strings[62608]="我只想完成……诸神的任务……"
D.Strings[62609]="闪电一击。"
D.Strings[62610]="你被|cFFFF0000|Hspell:135096|h[雷霆打击]|h|r杀死了。远离冲击点可降低所受伤害。"
D.Strings[62611]="多么奇特的地方。我敢肯定，我们一定能在这里发现许多珍禽猛兽，而且每一只都浑身带电。真可爱！"
D.Strings[62612]="你捕捉到了一个非常可喜的标本。我一直在教它不要电击我们的雇员。但它还是个小宝宝，这种行为在幼年期是无法避免的。$b$b多亏了那边的烈日行者帮忙，恶作剧的受害者们都得到了妥善的治疗。$b$b噢，我还冒昧地给你的小家伙起了一个名字。"
D.Strings[62613]="这家伙的生长速度叫我震惊。我们一开始想喂它吃奶酪，结果却惹恼了它。$b$b但当我们改喂当地的山羊后，它就开始疯长。$b$b真是一个贪吃的家伙。"
D.Strings[62614]="我们从被击落的各种野兽尸体上找到了一副鞍座和笼头。$b$b只要好好擦一擦，再加上一点小魔法，然后“嗖”的一声……它就跟新的一样了！"
D.Strings[62615]="天界工匠已经濒临死亡！"
D.Strings[62616]="天界防御者已经濒临死亡！"
D.Strings[62617]="天界防御者为一片区域注入了|cFFFF2222|Hspell:140068|h[治疗能量]|h|r！"
D.Strings[62618]="“啊哈哈，快来看呐，伙计们！$b$b格里伏塔又回来啦！新的摊位，崭新的商品，已经做好开张营业的准备啦！$b$b想在山里更加走运吗？想要购买最好闻的“幸运符”吗？那就快过来看看吧，别跟土地精们磨叽了。只要来找你的老朋友格里伏塔就对了。$b$b这些神奇的小玩意绝对物超所值！”"
D.Strings[62619]="你觉得这些草药和昂贵的熏香能在山里给你带来好运气？哈哈！那你可找错人了，伙计。快来买一把货真价值的幸运锁吧！"
D.Strings[62620]="格里伏塔，你说那些是幸运符？它们闻上去更像倒霉符。"
D.Strings[62621]="格里伏塔，你的鼻子太尖了，根本闻不到好运的味道。而且你自己闻上去就像一头没有洗过的牦牛。"
D.Strings[62622]="熊猫人有很多关于你这种巨魔的传说，格里伏塔。真的有很多。"
D.Strings[62623]="嘿！格里伏塔！那个幸运符是我的！你从哪里弄来的？"
D.Strings[62624]="“想想吧，我的朋友们总说我太爱‘说大话’。我真该把你介绍给他们，格里伏塔。”"
D.Strings[62625]="那是什么味道？那是什么味道？！是你吗，格里伏塔？你怎么搞得那么臭？这真是太讨厌了。没错，最讨厌了。"
D.Strings[62626]="“你们土地精都是输得起的人。我喜欢这样。$b$b所以，我愿意把这支‘幸运卡祖笛’卖给你，它能吹奏出最幸运的乐曲。”"
D.Strings[62627]="“你可不能连骨质‘幸运缰绳’都不用，就这么骑着牦牛进山！这根本就是在发疯！让我便宜卖给你几根吧。”"
D.Strings[62628]="这么说你正在寻找发财的机会？跟我去锈水港怎么样，我们可以在赌桌上好好赚一笔。"
D.Strings[62629]="啊，来吧！这绝对是笔好买卖，你只要一闻就知道。"
D.Strings[62630]="别那么快下结论，好吗？这个小玩意儿绝对就是你在找的东西，伙计。"
D.Strings[62631]="很好！你来了。准备好就告诉我一声。"
D.Strings[62632]="先把你带来的延极矿精炼一下。"
D.Strings[62633]="这个铸造机应该能用。帮我操作模具吧。"
D.Strings[62634]="万一引发骚动，你要做好战斗准备。"
D.Strings[62635]="解决那些乌合之众吧。"
D.Strings[62636]="我得集中精神。不能受到打扰！"
D.Strings[62637]="好！材料准备好了。跟我来。"
D.Strings[62638]="有意思！这个熔炉建在了远古泰坦仪器上。雷神，你真是个聪明的暴君！"
D.Strings[62639]="现在，我可不会像个矮人那样乱搞一气。我们是有备而来的。"
D.Strings[62640]="我要激活熔炉了，掩护我。知道吗？巨龙天生就懂得泰坦语。这无疑也是他们“绝佳设计”的一部分。"
D.Strings[62641]="快看。难怪雷神这么轻易就建立起了一个帝国，他掌握了创世之力。"
D.Strings[62642]="别让我分心。我得集中精神。"
D.Strings[62643]="保护熔炉！"
D.Strings[62644]="“安全协议”？荒唐。泰坦为何总是热衷于把好东西藏起来？"
D.Strings[62645]="你们泰坦激怒我了。我这么做是为了更重要的目的。"
D.Strings[62646]="帮我个忙，让他们闭嘴。我还有别的事要做。"
D.Strings[62647]="幸好我解除了警报。要没有我的话你该怎么办，嗯？"
D.Strings[62648]="肯定有更简单的办法——噢。哈！好了！"
D.Strings[62649]="噢，快看！"
D.Strings[62650]="魔古族只使用了一小部分可调动的资源。很少有人能像雷电之王那么狡猾。"
D.Strings[62651]="什么——“发现异常。”异常？"
D.Strings[62652]="看。这种古代泰坦技术会像磁石一样吸引煞魔。"
D.Strings[62653]="你可是对付煞魔的专家。快去解决它们！"
D.Strings[62654]="熔炉从周围的土地中抽取力量。太神奇了！我怀疑这座岛曾经也像锦绣谷一样繁华似锦。"
D.Strings[62655]="加把劲。我正在创造奇迹。"
D.Strings[62656]="干得好！保护熔炉——我就快完成了。"
D.Strings[62657]="糟糕——好险呐。我们稍后再试一次！"
D.Strings[62658]="熔炉被占领了！我们离开这儿！"
D.Strings[62659]="不不不——这完全不对。我们快离开这儿。"
D.Strings[62660]="好！完成了——我们铸造了一件杰作！"
D.Strings[62661]="这里的任务完成了，可武器还没有淬火。"
D.Strings[62662]="你得在暴风领主活着时，将长矛刺入他的心脏。"
D.Strings[62663]="注意！当长矛刺穿他的外皮时，你会受到他的反击。"
D.Strings[62664]="你得在杀死那头野兽前掷出长矛，这很重要。不能太早，也不能太晚！"
D.Strings[62665]="我得返回大陆了。等你拿到我需要的东西，再来雾纱栈道找我吧。"
D.Strings[62666]="噢，你可别死了。"
D.Strings[62667]="要登记工作投诉？很好！请先交纳五百杏仁币的调查费和三百杏仁币的杂费。"
D.Strings[62668]="|cFFF00000墨格瑞拉|r从迷雾中现身了！"
D.Strings[62669]="我的组织在这片土地上游历多年，尽力帮助他人。自从雷神的时代至今，我们的成员一直保持在五人，将组织的秘密代代相传。"
D.Strings[62670]="什么秘密？"
D.Strings[62671]="如果我告诉了你……那它就不能称之为秘密了，明白吗？"
D.Strings[62672]="五名巫师？"
D.Strings[62673]="我不记得其他人去哪里了。我们真的已经很久没有见面了，其他人很可能已经死了，或者被他们的弟子取代了。我只能确信，我们还有五个人。"
D.Strings[62674]="蠢货！让我来给你们示范一下吧！"
D.Strings[62675]="洞穴剧烈地震动起来！"
D.Strings[62676]="迷雾中出现了一头远古巨兽！"
D.Strings[62677]="我的父母曾说过，在大分裂之前，在离我们家乡很遥远的南方居住着一个毛茸茸的奇怪种族。我一直以为他们说的是一种比较聪明的熊怪。$b$b现在我知道自己错得有多离谱了。真希望他们能活到今天，亲眼看看这一切。"
D.Strings[62678]="你被|cFFFF0000|Hspell:134916|h[斩首]|h|r杀死了。距离雷神越远，斩首对你的伤害就越低。让副坦克去嘲讽他！ "
D.Strings[62679]="你说过你要第一个敲锣的。"
D.Strings[62680]="我才不要！而且，那不是锣！那是一口钟。我可没说过我要敲钟。"
D.Strings[62681]="我看你是不敢吧！"
D.Strings[62682]="没门。那口钟比我爸爸的肚子还大呢！"
D.Strings[62683]="你明明就是胆小！"
D.Strings[62684]="敲钟人就在那边。我听说他会把小孩子塞进钟里！"
D.Strings[62685]="那是你姐姐说的，根本不能算数。她是个小气鬼。你一定要去敲钟，否则我就把你的丑事都说出去！"
D.Strings[62686]="*咕噜* 都……都说出去？"
D.Strings[62687]="没错！你要是不敲的话，我就告诉晨芳园里所有人，你就是个喜欢红酒而不喜欢啤酒的大懦夫！"
D.Strings[62688]="可我爸爸说我太小了，不能喝酒。"
D.Strings[62689]="没错！那一样会让你丢脸！现在快去敲钟，你这个大笨蛋。"
D.Strings[62690]="我曾向肯瑞托发过誓。那是一个互信互谅的誓约。后来，他们背弃了这个誓言。是时候让他们知道，血精灵是不会轻易放过背叛者的。"
D.Strings[62691]="阻止他们！别让他们干扰黑暗意志！"
D.Strings[62692]="这力量……不能这么使用！你们在运用无法驾驭的力量！"
D.Strings[62693]="你们是在找死。它……被……释放了。"
D.Strings[62694]="$C，如果你是来找黑王子的，那他就在楼上。"
D.Strings[62695]="这片大陆是不会轻易交出自己的秘密的。"
D.Strings[62696]="我们还有很多东西要学。"
D.Strings[62697]="熊猫人热爱生活。在这个战火纷飞的年代，了解我们为何而战更能振奋人心。"
D.Strings[62698]="来喝一杯吧。这位王子正在教我玩一种当地的游戏。"
D.Strings[62699]="魔古族、螳螂妖、蜥蜴人……他们不仅是需要我们击败的敌人，更是有待解开的谜团！"
D.Strings[62700]="你好，朋友！"
D.Strings[62701]="我有一个潜入雷电之王武器库的计划。但是这需要你找到的那个生物，以及影踪派的帮助。"
D.Strings[62702]="温蕾萨在等着你，勇士。"
D.Strings[62703]="进入山怖之死场景战役。"
D.Strings[62704]="你救下的这个美丽生物能免疫岛上的闪电攻击。"
D.Strings[62705]="太棒了！一旦你飞上天空，赞达拉就会追上来的。"
D.Strings[62706]="影踪派的密探就在矿洞后等你。祝你好运！！"
D.Strings[62707]="一旦你结识了潘达利亚的各个阵营，大量产品订单就会蜂拥而至。"
D.Strings[62708]="几千年没见过新玩具了……我会好好享受的。"
D.Strings[62709]="看看虚空的力量吧！"
D.Strings[62710]="我还以为会更有趣呢。真让人失望。"
D.Strings[62711]="我欢迎虚空的拥抱……"
D.Strings[62712]="你看到我干了什么吗？"
D.Strings[62713]="看来你坚持不下去了。真遗憾。"
D.Strings[62714]="注意脚下……唔哈哈哈！"
D.Strings[62715]="迷雾里有许多秘密，如果你知道往哪儿看的话……"
D.Strings[62716]="我盯着你呢……"
D.Strings[62717]="见证你的末日吧。"
D.Strings[62718]="这就是“黑暗中的匕首”的故事！$B$B正是在这里，三位勇敢的冒险者阻止了一场精心策划的暗杀，救了部落的暗矛巨魔首领沃金一命。"
D.Strings[62719]="我为什么是巨魔的样子？"
D.Strings[62720]="啊，因为你将是这个故事中的一名演员！$B$B比起从落满灰尘的卷轴上阅读历史，这样会更有趣，你说呢？$B$B现在，快出发吧，好好学习！"
D.Strings[62721]="这个故事叫做“王者的耐心”！$B$B正是在这里，人类国王瓦里安·乌瑞恩建议暗夜精灵的首领、月亮女神的高阶女祭司泰兰德·语风保持耐心。$B$B凭借瓦里安国王的运筹帷幄，以及三位勇敢冒险者的努力，寡不敌众的联盟军队竟在朱鹤寺击败了由指挥官斯卡戈什统领的部落大军，取得了大捷。"
D.Strings[62722]="我为什么是人类的样子？"
D.Strings[62723]="普罗德摩尔女士，请进吧。"
D.Strings[62724]="你们成功了！我就知道影踪派会是出色的盟友。"
D.Strings[62725]="我们有着共同的敌人，普罗德摩尔女士。仅此而已。"
D.Strings[62726]="女士，雷电之王的武器都是畸形的怪胎。我们应该销毁它们。"
D.Strings[62727]="但是至少，我们一起重创了雷电之王！"
D.Strings[62728]="温蕾萨，抢在魔古族回来之前多收集点东西。什么都别留给部落。"
D.Strings[62729]="噢，我们会的。但知识就是力量，我从不放弃学习新知识的机会。谢谢你，陶矢。"
D.Strings[62730]="还有你，英雄。要守住熔炉很困难，但是想想我们能学到的东西吧！"
D.Strings[62731]="|TInterface\\Icons\\trade_archaeology_whitehydrafigurine:20|t墨格瑞拉开始|cFFF00000|Hspell:139458|h[狂暴]|h|r！"
D.Strings[62732]="影踪派也来了！他们或许对我们有用。快帮忙。"
D.Strings[62733]="这个铸造机应该能用。我们得用电荷给金属充能。"
D.Strings[62734]="如果让熔炉过载的话，或许就能消灭这该死的煞魔。试试看。"
D.Strings[62735]="瞧。搞定了。"
D.Strings[62736]="噢——我好像言之过早了。煞魔变强了！消灭它！"
D.Strings[62737]="你们没有恶意的，对吧？"
D.Strings[62738]="我让铁砧超载了。它们对付煞魔很有效，但每个只能使用一次！"
D.Strings[62739]="完成了。快，用它扔那个煞魔！"
D.Strings[62740]="陶矢冲右边的船员点点头。潜行到他背后并将他打晕了！"
D.Strings[62741]="你们将被消灭！"
D.Strings[62742]="等待装货与递送的空箱子。"
D.Strings[62743]="你正在被闪电追逐！"
D.Strings[62744]="你好，$n。\n\n坎雷萨德的力量太过强大，反而无法获得自由。只要我还活着，他就会一直被放逐下去。\n\n不过，稍微尝试一下他那充沛的力量并无大碍。你可以随意抽取一些给自己用。如果你厌倦了它的效果，也可以支付一定的代价让我帮你净化这些邪能。"
D.Strings[62745]="裘碧卡，我不想再被这种邪能污染了。"
D.Strings[62746]="你确定不再想要克萨雷斯魔典了吗？"
D.Strings[62747]="赞达拉预言书。"
D.Strings[62748]="雷电轰鸣。"
D.Strings[62749]="神祗与妖魔。"
D.Strings[62750]="我做好攻打城墙的准备了！[排队等待单人副本。]"
D.Strings[62751]="融合之煞开始施放|cFFFF2222|Hspell:139382|h[疯狂]|h|r！快释放铁砧中的能量来阻止它！"
D.Strings[62752]="好极了！前进——压上去。不要给他们喘息之机！"
D.Strings[62753]="这边——赞达拉撤退了！"
D.Strings[62754]="快通过缺口！瞄准伤员！"
D.Strings[62755]="什么……他们对那个巨魔做了什么？"
D.Strings[62756]="摄政王阁下——你不该到前线来。"
D.Strings[62757]="游侠们——跟我来！我们击穿了他们的防线！"
D.Strings[62758]="胡说。这里才是我的舞台。"
D.Strings[62759]="勇士！你又冲在了为部落夺取胜利的最前线。我又欠你一份人情。"
D.Strings[62760]="快去掩体后面重整队伍。他们会反攻……但我们会做好准备的。"
D.Strings[62761]="快进去！注意那些牧师——他们正在强化其他人！"
D.Strings[62762]="圣光在上——他们做了什么？"
D.Strings[62763]="我受伤了——别后退。"
D.Strings[62764]="杀了那家伙！"
D.Strings[62765]="没什么。我很好。"
D.Strings[62766]="温蕾萨，你受伤了？"
D.Strings[62767]="你得回营地去。我不能失去你。"
D.Strings[62768]="去搜寻伤员！今天我们做出了致命一击——战役进入了新阶段。"
D.Strings[62769]="站出来！见证雷电之王的恩赐吧！"
D.Strings[62770]="我是他的选民。我的鲜血中燃烧着他的力量！"
D.Strings[62771]="太强了……万灵控制不了他的力量……"
D.Strings[62772]="你将受到严惩！你的生命将成为徒劳的教训！"
D.Strings[62773]="为了赞达拉！！"
D.Strings[62774]="堵上大门。赞达拉守不住城墙了。"
D.Strings[62775]="绝不能让雷神恢复鼎盛时期的力量。$b$b直接攻打前门需要时间，以及你们联盟和部落的协助。但我们影踪派最相信一件事，那就是车到山前必有路。$b$b这条隧道深处的下水道可以通向堡垒的入口。我们必须守住这个入口。"
D.Strings[62776]="我相信，我们一定可以利用这里的雷霆翼龙狠狠打击雷神。"
D.Strings[62777]="我跟你去。让我们一起攻破那个船坞吧！ [排队等待单人副本。]"
D.Strings[62778]="绍尔马拉驭兽师召唤迅猛龙前来助战！"
D.Strings[62779]="$C！快来帮帮我！"
D.Strings[62780]="魔古族和赞达拉就躲在这些高墙后面。吉安娜制定了一个突击计划。你准备好了就跟我谈谈吧！"
D.Strings[62781]="滚开，爬虫。这里是雷电之王的疆域。"
D.Strings[62782]="快拿炸药来！"
D.Strings[62783]="我们必须冲破这里——我的炸药呢？"
D.Strings[62784]="炸药已经全部到位——这份殊荣属于你！"
D.Strings[62785]="它死了！你激励了我们的士气！"
D.Strings[62786]="快——把那些炸药给我！"
D.Strings[62787]="快把那些炸药收集起来！"
D.Strings[62788]="我受伤了！别管我——去干掉它！"
D.Strings[62789]="雷霆熔炉开始为附近的一块区域充能。跑进这个区域将使你|cFFFF2222|Hspell:139397|h[过载]|h|r！"
D.Strings[62790]="正在移除书籍。"
D.Strings[62791]="去死吧，魔古！"
D.Strings[62792]="为了伊瓜鲁克！"
D.Strings[62793]="痛苦地死去吧，魔古！"
D.Strings[62794]="把魔古撕成碎片！"
D.Strings[62795]="我要把你的尸体拖进污水池！"
D.Strings[62796]="墨格瑞拉的怒火平息了。"
D.Strings[62797]="|TInterface\\Icons\\spell_shadow_curseofmannoroth.blp:20|t杜鲁姆用|cFFFF0000|Hspell:133597|h[黑暗寄生]|h|r感染他的敌人！"
D.Strings[62798]="蜥蜴人很卑劣，但他们或许还有用处。$b$b如果我们能煽动他们反抗魔古族，或许就能把他们的注意力从我们的人身上移开。"
D.Strings[62799]="蜥蜴人让我很感兴趣。$b$b他们是怎么在明显占优的敌人的阴影下存活了那么长时间的？"
D.Strings[62800]="我是来处理邪刃蜥蜴人造成的疾病和瘟疫的。$b$b虽然我从没见过这种瘟疫，但它们肯定有一些相似之处。"
D.Strings[62801]="使用彩色锥形光束照出并杀死三只隐身的雾行兽。"
D.Strings[62802]="一定要记住战争真正的代价。"
D.Strings[62803]="愿圣光与你同在，勇敢的$r。"
D.Strings[62804]="虽然我们的目标是消灭魔古族，但也不能忽略我们的侧翼。$b$b虽然部落和蜥蜴人都在与我们一同攻击魔古族，但这两者随时都有可能对我们倒戈相向。"
D.Strings[62805]="“蜥蜴人引起了我的兴趣。$b$b事实上，由于我太过热衷，某些人甚至开始称我为‘邪刃’斯蒂芬。”"
D.Strings[62806]="我是来清理邪刃蜥蜴人留下的烂摊子的。$b$b虽然我从未见过它们这样的烂摊子，但其中肯定有相似之处。"
D.Strings[62807]="让我们快点搞定这件事，好早点回家去。"
D.Strings[62808]="打得好，$r。"
D.Strings[62809]="很高兴你能来！普罗德摩尔急需援军。你准备好出发了吗？"
D.Strings[62810]="熊猫人对“雷电之王”的归来深感不安。可我更担心部落的威胁。我们飞行途中再谈。"
D.Strings[62811]="一万两千多年前，“雷电之王”雷神建立了古老的魔古帝国。"
D.Strings[62812]="他统一魔古族，征服了其他熊猫人种族，并建立起了延续数千年的帝国。"
D.Strings[62813]="传说雷神拥有强大的力量，他为自己建造了一座宏伟的堡垒。我们应该很快就能看见了……"
D.Strings[62814]="就是那里！传说中的雷神岛。部落已经像饥饿的猛禽一样包围了它。"
D.Strings[62815]="如果不能打败雷电之王，潘达利亚就会遭殃。可是如果让部落得到他的力量，那全世界都得付出代价。"
D.Strings[62816]="哇——小心！我们要着陆了。这里简直没法飞行！"
D.Strings[62817]="吉安娜·普罗德摩尔女士希望尽快见到你。"
D.Strings[62818]="这真是我这辈子最糟糕的一年：塞拉摩被摧毁了。肯瑞托又出了叛徒。"
D.Strings[62819]="多么深刻的教训。以后，我要先发制人。"
D.Strings[62820]="在下面的海岸上，部落正在寻找驻扎地点。"
D.Strings[62821]="他们也想打败雷电之王，但不是为了保护潘达利亚，而是想攫取他的力量。"
D.Strings[62822]="可这次，我们领先了一步。"
D.Strings[62823]="部落休想在这片海滩上占得便宜。等雷神被击败后，熊猫人就会明白，在紧急关头，是联盟的英雄与他们并肩作战。"
D.Strings[62824]="这场战斗需要倾力而为。但愿你做好了准备。"
D.Strings[62825]="你来了！摄政王特地问起了你。你准备好出发了吗？"
D.Strings[62826]="熊猫人的传说中提到过“雷电之王”雷神。他是一万两千多年前魔古帝国的野蛮创立者。"
D.Strings[62827]="他统一魔古族，击败了其他熊猫人种族，并靠他征服的奴隶建立起了辉煌的帝国。"
D.Strings[62828]="他在帝国边境上建立了一座宏伟的要塞。我们很快就能看见了……"
D.Strings[62829]="好极了！你能感觉到这块水晶中的能量吗？我感觉我的头发都要竖起来了。"
D.Strings[62830]="看！就在前面：雷神岛。"
D.Strings[62831]="熊猫人害怕这位前皇帝会试图重建他的帝国，并再次奴役他们。"
D.Strings[62832]="而我们自有协助他们的理由。还是让洛瑟玛来解释吧。"
D.Strings[62833]="啊！小心——我们简直没法飞近这座岛！"
D.Strings[62834]="记得去跟摄政王谈谈。他就在船头等你。"
D.Strings[62835]="艾萨斯，请你回避一下。"
D.Strings[62836]="英雄，你历经战火，对部落忠心耿耿。我想我可以信任你。"
D.Strings[62837]="酋长在卡利姆多和潘达利亚的战役已令部落濒临分裂。"
D.Strings[62838]="我们来此对抗雷神。这是出于正义，而且地狱咆哮被统御岗哨所牵绊，无暇顾及这里。"
D.Strings[62839]="但击败他之后，我们必须找到他的力量之源。我们必须得到它，并借此对付我们的“酋长”。"
D.Strings[62840]="在举兵之前，我们得做好准备。"
D.Strings[62841]="哈！挽弓杀敌的感觉真不错。对手是联盟还是魔古族对我来说都一样。"
D.Strings[62842]="闲话少说。你也明白我们的处境很危险。在联盟和雷神的夹击下，只有像你这样的英雄才能帮我们获胜。"
D.Strings[62843]="Anar'alah belore，英雄。祝你好运。"
D.Strings[62844]="熔炉已经安全了，我们得走了。祝你好运，冒险者。"
D.Strings[62845]="在躲避杜鲁姆的衰变光束的同时走出炙眼灼光的迷宫。"
D.Strings[62846]="在意志之力施放完毕前走出发光区域以避免被击倒。"
D.Strings[62847]="显然肯瑞托对这座岛的力量一无所知。他们纯粹是为了报复才来这里阻挠我们的。我们一定要好好教训这些傲慢无礼的法师一顿。"
D.Strings[62848]="在雏鸟进食并成长前杀死它们。"
D.Strings[62849]="被击杀的雏鸟会掉落羽毛，使用羽毛可以短暂飞行一段时间。"
D.Strings[62850]="一颗强大的宝石。"
D.Strings[62851]="飞上巢穴以阻止幼年凤凰孵化。"
D.Strings[62852]="|TInterface\\Icons\\ability_druid_galewinds.blp:20|t季鹍拍打双翼，制造出一股巨大的|cFFFF0000|Hspell:134370|h[下冲气流]|h|r！"
D.Strings[62853]="|TInterface\\Icons\\ability_hunter_pet_dragonhawk.blp:20|t季鹍施放|cFFFF0000|Hspell:134380|h[飞羽满天]|h|r，向四面八方发射翎羽！"
D.Strings[62854]="|TInterface\\Icons\\ability_hunter_animalhandler.blp:20|t季鹍高声|cFFFF0000|Hspell:138923|h[鸣叫]|h|r，向她的敌人发射音波！"
D.Strings[62855]="季鹍陷入了狂怒！"
D.Strings[62856]="|TInterface\\Icons\\spell_nature_removecurse.blp:20|t黑暗寄生变异成了|cFFFF0000|Hspell:133598|h[黑暗天灾]|h|r！"
D.Strings[62857]="巨型蜗牛开始追逐|cFFFF0000$n|r！"
D.Strings[62858]="一只骸骨蜘蛛从上方的蛛网中苏醒过来了！"
D.Strings[62859]="附近活动的血肉令钻地蠕虫骚动了起来！"
D.Strings[62860]="在死亡时，隐藏雾行兽的强光迸发会照出该区域所有的苍白雾行兽。"
D.Strings[62861]="眼魔哨兵将附近的敌人拉入自己的痛苦领域，击败它才能获得自由！"
D.Strings[62862]="|TInterface\\Icons\\ability_creature_disease_02.blp:20|t眼魔仆从选中|cFFFF0000$n|r并对其施放|cFFFF0000|Hspell:134668|h[痛咬]|h|r！"
D.Strings[62863]="$n接住了！"
D.Strings[62864]="空气中的电流把我的头发都弄坏了。"
D.Strings[62865]="啊，好极了，一位$c。我们正需要你这样的人来完成某些任务。"
D.Strings[62866]="激活序列：换算协议"
D.Strings[62867]="激活序列：重置电源"
D.Strings[62868]="激活序列：解析指令"
D.Strings[62869]="激活序列：启动微波抑制器"
D.Strings[62870]="激活序列：加快活动速度"
D.Strings[62871]="激活序列：完成"
D.Strings[62872]="激活序列：成功除零"
D.Strings[62873]="激活序列：将毁灭指数设置为15,000"
D.Strings[62874]="不能再浪费时间了。在我们说话的时候，联盟正在雷神岛上不停推进呢！"
D.Strings[62875]="激活序列：测定你的死期"
D.Strings[62876]="不能再浪费时间了。在我们说话的时候，部落正在雷神岛上不停推进呢！"
D.Strings[62877]="谁想来试试我的长枪？"
D.Strings[62878]="我的大锤总能克敌先机！让大火烧得更猛烈些吧！"
D.Strings[62879]="电卜师乌古沉默地凝视着你，狠狠一挥手中的战戟，发动了进攻！"
D.Strings[62880]="激活序列：初始化"
D.Strings[62881]="只要想想我能分享多少知识，我们能种出怎样的食材吧！"
D.Strings[62882]="娜娜·泥爪邀请我加入阡陌客？"
D.Strings[62883]="可是……我恐怕无法在承担议会工作的同时管理日歌农场了。"
D.Strings[62884]="这个农场是我祖传的财产。我怎么能放弃它呢？可是，又有更重大的责任落到了我的肩上。"
D.Strings[62885]="$n，我决定把日歌农场送给你。现在，这里归你管了！"
D.Strings[62886]="我最好去和娜娜谈谈。现在农场已经归你了，$n。我知道你会好好照料它的。"
D.Strings[62887]="我从没想过加入阡陌客后会有这么多工作。"
D.Strings[62888]="日歌农场最近怎么样，$n？"
D.Strings[62889]="我已经快要忙死了，但汇风岭正日益繁荣。"
D.Strings[62890]="自从锦绣谷的大门开启，我们就在源源不断地向北方供应蔬菜。"
D.Strings[62891]="你在卡桑琅丛林的那群朋友胃口可真好，总是不断地向我们采购新鲜农产品。"
D.Strings[62892]="我听说影踪派正准备突袭西北方的雷神岛。他们肯定会需要大量食物，而我们就是那个供应商！"
D.Strings[62893]="我正在和种子保管人辛辛一起研究更高效的耕作、采集和储存方案。阡陌客的目标就是提供美味、新鲜、高品质的农产品！"
D.Strings[62894]="农夫老愚，你愿意加入阡陌客议会吗？"
D.Strings[62895]="我是来拿订好的红韭花的。"
D.Strings[62896]="统御岗哨感谢你！"
D.Strings[62897]="你这儿有女巫浆果吗？"
D.Strings[62898]="噢，他们在这儿呢！雄狮港感谢你！"
D.Strings[62899]="我们急需一些芜菁！"
D.Strings[62900]="太感谢了！金莲教欠你一份人情！"
D.Strings[62901]="我们还需要一些漂亮的菜瓜！"
D.Strings[62902]="我最喜欢它们爆炸时发出的声音了！"
D.Strings[62903]="我们预定的绿色卷心菜准备好了吗？"
D.Strings[62904]="唔！！！我最喜欢绿色卷心菜汤了！"
D.Strings[62905]="预订的南瓜到了吗？"
D.Strings[62906]="我准备好了执行任务了。"
D.Strings[62907]="呃，这些应该足够了。卡拉克西表达了他们的谢意，虽然我也不知道是为了什么。"
D.Strings[62908]="赤精的精魂消散了，只留下漫天的星尘。"
D.Strings[62909]="玉珑的精魂温和地对你笑了笑，慢慢消失在天空中。"
D.Strings[62910]="砮皂的精魂低声感谢了你的帮助。"
D.Strings[62911]="守护者开始碎裂，大量灰尘簌簌而落。"
D.Strings[62912]="守护者开始活动，并发出“隆隆”的响声。"
D.Strings[62913]="碎石开始从守护者身上滚落。仪式就要完成了！"
D.Strings[62914]="守护者塔克乌苏醒了！"
D.Strings[62915]="雪怒的精魂发出胜利的咆哮，爆散成一天星尘。"
D.Strings[62916]="魔古族和赞达拉正在将新一批的宝藏从雷神的陵寝运往他的王座。我们必须在他的部队抵达前快速出击，尽力多抢一些宝藏。你的时间有限，我们会准时把你拉出来，所以你得注意效率，$n。\n\n我们只有一次机会，所以好好珍惜吧。\n\n你准备好之后，就把钥匙给我，我来打开大门。"
D.Strings[62917]="钥匙在这儿。我们走。"
D.Strings[62918]="我们必须争分夺秒。\n\n你准备好之后，就告诉我一声。我会带你出去。"
D.Strings[62919]="我准备好了。我们离开这里吧。"
D.Strings[62920]="在里面找到什么好东西了吗？"
D.Strings[62921]="我很乐意帮你清空那个包裹。"
D.Strings[62922]="雷神归来才没多久，就在麾下聚集起了这么多盟友，这可真叫人沮丧。我们得趁他不在时多消灭一些。"
D.Strings[62923]="这座岛上到处都是敌人，新老都有。如果没有流血牺牲的觉悟，我们是无法在这里立足的。"
D.Strings[62924]="我的船经过一番斗争才得以靠上这片海岸。我一定会让他们为她船体上的每一条伤疤付出代价的。"
D.Strings[62925]="这座岛蕴藏着巨大的魔力。我还不清楚它是掌握在雷电之王，还是我们的夺日者老朋友手里。$B$B但我们迟早会找到答案的。"
D.Strings[62926]="想听个小秘密吗？关于今天该去哪儿钓鱼的……."
D.Strings[62927]="想听听关于该去哪儿钓鱼的秘密吗？"
D.Strings[62928]="恐惧废土的古克罗克浅滩在迎来大渔汛之后，日益频繁的鱼类活动有时会搅松沿岸的海藻。$b $b大虾、八爪鱼之类的东西就会被这些海藻缠住。我敢打赌，如果你去那里钓钓鱼，肯定能收获许多螳螂虾。 $b $b如果你需要我帮忙寻找渔点，就告诉我一声。"
D.Strings[62929]="当然了，朋友。我可以帮你把螳螂虾的位置标在地图上。去恐惧废土的西北角看看吧，那个地方叫古克罗克浅滩。"
D.Strings[62930]="香里拉村的垂钓翁报告说那里的八爪鱼数量异乎寻常的多。我敢打赌，肯定是它们的繁殖期到了，但谁知道呢？$b $b问题是，日益增多的八爪鱼危害到了那里的贝类生物数量……大家都知道，贝类才是最值钱的。$b $b快去那里挥舞你的钓竿吧，肯定能钓到不少八爪鱼。"
D.Strings[62931]="我想八爪鱼应该就在翡翠林的香里拉村一带。$b$b<班宏拿过你的地图，在翡翠林的东北海滩上按下了一根别针。>$b$b"
D.Strings[62932]="在满月期间，翡翠林的失落林地里的小精龙就会蜕鳞。这一般都发生在夜间，那个景象非常美丽。$b $b它们的鳞片会闪着明亮的翠绿光芒撒入水中。这会吸引到大量的翠绿肺鱼，数量之多绝对超乎你的想象！就像扑火的飞蛾一样！$b $b但你要小心别惊动了那里的魔古族……他们可不太友好。"
D.Strings[62933]="当然可以。翠绿肺鱼就集中在这一带，翡翠林的失落林地里。那里不算是潘达利亚最大的鱼塘，但别具一格。"
D.Strings[62934]="我今天在进货时，遇到了一个贩卖稀有药水和油膏的行脚商。他那里最奇怪的一种油膏就是针对鱼群的“爱情药水”。$b $b别管他是怎么做出来的了，你只要知道，这玩意儿真的有用！它让水塘里的红腹鳜鱼数量整整翻了一倍！$b $b我是在砮皂寺北方的湖边遇到他的。如果你能去让那里的鳜鱼数量恢复正常，没准还是做了件好事呢。"
D.Strings[62935]="<班宏抓了抓脑袋。>$b$b我的方向感不算太强，但我觉得红腹鳜鱼应该就在这一带，螳螂高原的砮皂旷野。$b$b<班宏在你的地图上划了一个大概的范围。>$b$b"
D.Strings[62936]="在四风谷，我们有着著名的风暴烈酒酿造厂。你或许已经注意到了，一群极具破坏力的猢狲想要强占那里。他们都是出了名的酒鬼，向来不懂节制。$b $b有时，当一批新酒酿好后，他们还会搞啤酒大战。没错，大量的美酒就这么浪费掉了，白白流进了炎子江。 $b $b这些美酒引来了帝王鲑鱼。我从没见过那么多帝王鲑鱼挤在一起的景象。而且这些鲑鱼还会变得更好抓……看来它们也喝高了。"
D.Strings[62937]="捕捉帝王鲑鱼的最佳地点或许就是四风谷的酒厂外面。我来帮你标在地图上。"
D.Strings[62938]="我看上去很生气？没错，我就是很生气！$b $b我的死对头维扎克·爆饵正在逐渐蚕食我的地盘。他是个卑鄙的小个子地精，专用……非常规手段来捕鱼。$b $b我上次遇见他是在卡桑利瀑布。如果你想要卡桑琅白鲟，就去那里钓吧。我敢打赌，它们肯定已经被他吓得六神无主了。如果让他看到别人在那里钓鱼，他或许就会觉得那里太挤而离开。$b $b噢，如果可以的话，请你好好唾弃他一番，就说是班宏让你去的。$b$b<班宏得意地笑了笑。>$b$b"
D.Strings[62939]="你可以在卡桑琅河最大的池塘找到卡桑琅白鲟和那个混蛋地精。就在卡桑琅丛林的中央。就是这儿。$b$b<班宏用爪子在你的地图上戳了一个洞。>$b$b"
D.Strings[62940]="今天，昆莱山滨岸村的锦鱼人和水流沟通了一番，发现水中充满了煞能。$b $b你或许已经知道了，刺皮鱼是一种极具攻击性的鱼类。如果再给它们加点煞能，那你就能见识到什么叫疯狂了！ $b $b如果你能抓住那些愤怒的野兽，或许就能帮忙恢复当地脆弱的生态平衡……更不用说你还能抓到大量刺皮鱼。"
D.Strings[62941]="刺皮鱼就在地图的这个位置。昆莱山滨岸村的海滩上。你找天色最阴沉黑暗的地方就对了。"
D.Strings[62942]="昨晚，雪流大师在昆莱山的影踪禅院授课。他教了弟子们如何施展冰霜之拳。$b $b好消息是，那些弟子们都做得很好。坏消息是，数百道冰霜拳劲被打入水中，冻住了周围湖泊中的虎皮丝足鱼！ $b $b如果你今天想抓一些虎皮丝足鱼，这或许就是最好的机会。"
D.Strings[62943]="虎皮丝足鱼可以在影踪派的宝塔附近找到……就是这里，在昆莱山。$b$b<班宏在你的地图上做了一个标记。>$b$b"
D.Strings[62944]="疯狂的乔宝没有任何恶意的。真的。他听说魔古山宫殿前的池塘能够实现你的愿望，你懂的……就像许愿井什么的。$b $b而且……呃……这个可怜的家伙有钱却没有脑子。据我得到的最新消息，他还在往水里扔金币呢……希望自己能成为世界之王！ $b $b遗憾的是，珍宝斑马鱼最喜欢的食物就是在水面上飞舞的萤火虫。那些闪闪发光的金币将它们成群结队地吸引了出来。$b $b但愿那些可怜的小家伙不要吞食太多的金币。但如果你有需要的话，今天就是钓珍宝斑马鱼的好日子。你甚至还能从里面发现一些金币。"
D.Strings[62945]="疯狂的乔宝和他的珍宝斑马鱼就在锦绣谷的仲夏原上。大概就在这里。$b$b<班宏在你的地图上做了一个标记。>$b$b"
D.Strings[62946]="当然，我最喜欢听秘密了。"
D.Strings[62947]="太好了，你能帮我在地图上标出来吗？"
D.Strings[62948]="这些鱼上蹿下跳的，就像弹跳幸运符！"
D.Strings[62949]="你这里有钓鱼用品吗？"
D.Strings[62950]="这片湖上有好运的味道……还是鱼泡泡的味道？"
D.Strings[62951]="真可惜，鱼都不能走路或爬山。如果我给它们多找一些鱼朋友回来，它们会高兴吗？"
D.Strings[62952]="闪电总比打雷好，对吧？嗯，那我希望能加冕为潘达利亚的闪电之王！"
D.Strings[62953]="我想要一百万金币……等等，我已经有一百万金币了……我想要十亿金币！"
D.Strings[62954]="噢，我知道了！我想要风暴烈酒酿造厂里所有的啤酒！"
D.Strings[62955]="我想要一头镶满了全世界最珍贵珠宝的猎豹！等等，我有个朋友不是已经有一头了吗？"
D.Strings[62956]="不不不，这不是我想要的。"
D.Strings[62957]="唔，再好好想想……"
D.Strings[62958]="噢，等等，我有了一个更好的主意！"
D.Strings[62959]="哈哈！吃吧，你们这些笨鱼！"
D.Strings[62960]="我向来用不好鱼竿……但没关系！"
D.Strings[62961]="尝尝热乎乎的TNT炸药把，坏鱼！"
D.Strings[62962]="当火雨从天而降，臣服于你们陆上的霸主吧！"
D.Strings[62963]="你要明白，那个大嗓门就会吹牛而已！"
D.Strings[62964]="这下我真的生气了！"
D.Strings[62965]="这是我见过的最粗鲁的行为！"
D.Strings[62966]="先是鱼！……现在轮到你了？"
D.Strings[62967]="敢捞这些光板儿你就要倒霉了。"
D.Strings[62968]="好多光板儿……猢狲就爱光板儿！"
D.Strings[62969]="该死的光板儿，就会给我惹麻烦！"
D.Strings[62970]="光板儿喜欢蠢蛋的去死……猢狲也喜欢蠢蛋去死！"
D.Strings[62971]="这个不幸的赞达拉巨魔已经被刺死被踩烂了。他脸上的表情并不是恐惧，而是一种视死如归的决心。$b$b他睁大的眼睛一眨不眨地瞪着天空，里面燃烧着狂热和兴奋。一只苍蝇在依然湿润的眼球上爬行着。"
D.Strings[62972]="国王希望安度因王子留在锦绣谷直至康复。但王子坚持要四处走走，并与人们多聊聊。当王子想要违抗国王时，我们又能怎么办呢？$b$b最好还是跟紧他，免得他惹上什么麻烦。"
D.Strings[62973]="<卫士怒视着你，紧紧抓住腰间的佩剑。>$b$b王子只想安静地聊聊，$c。如果你敢惹麻烦，我们一定会加倍奉还。"
D.Strings[62974]="<牛头人圣骑士上下打量着你，好像在猜测你的意图。>$b$b我无意与你为敌，$c。人类王子和我在白虎寺见过，他常常来找我聊我们的大酋长贝恩，并讨论战争与和平那些事。$b$b<圣骑士和王子的卫士不断用疑虑的眼神互相打量着。>"
D.Strings[62975]="欢迎你，$c！$b$b大酋长贝恩·血蹄得知加尔鲁什野蛮地袭击了人类王子后，一直非常忧虑。我们有许多仇视联盟的原因，但那都不是这个小家伙的错。$b$b王子和我在白虎寺见过。我用自己的荣誉发誓，一定会保证他的安全。$b$b<尽管这样说了，又有王子的热情介绍，但房间角落里的皇家卫士依然狐疑地打量着这位牛头人圣骑士。>"
D.Strings[62976]="不——住手。立刻住手！"
D.Strings[62977]="快住手！此时此地，你们不能这么做！"
D.Strings[62978]="拉希奥自称是最后一条活着的黑龙。你相信吗？$b$b他对世界的看法非常古怪。我不知道他是否珍视人类的生命，还是把它看做消耗品！但我真的很喜欢跟他聊天。"
D.Strings[62979]="<当你对王子说话时，安度因的卫士靠了过来。>$b$b没关系。我只想跟我的朋友聊聊。我们在这里远离战场。这世界上还有地方能容得下一场文明的对话吗？$b$b来，坐吧！跟我们聊聊！"
D.Strings[62980]="噢，这个？<安度因指了指他的拐杖。>$b$b加尔鲁什·地狱咆哮试图用一件古老的魔古神器召唤并控制煞能。我设法阻止了他，但我好像不该亲自去对付他。他以为我死了，让我就那么埋在那个失败计划的废墟下。我发誓，他把我全身所有的骨头都打碎了。$b$b熊猫人织雾者让我重新站了起来，但我恐怕还需要一些时间才能独立行走。"
D.Strings[62981]="你知道我们和黑龙军团的往事，对吧？我不会那么快忘记普瑞斯托女士——奥妮克希亚——对我的家族所做的一切。或许这就是我来找拉希奥的原因。$b$b<安度因看了看桌子对面那位不同寻常的同伴。>$b$b可是……他和其他黑龙不一样，不是吗？他非常坦诚，却又总在隐瞒着什么。和我预想中完全不同。"
D.Strings[62982]="拉希奥自称是最后一条活着的黑龙。你相信吗？会不会还有其他黑龙躲在外域的某个地方呢？$b$b无论如何，我发现他很特别。他和我见过的任何一条龙都不一样。他很坦诚，简直坦诚得过分了。我不知道他是否珍视人类的生命，还是把它看做消耗品。"
D.Strings[62983]="你的腿怎么了？你受伤了？"
D.Strings[62984]="你怎么能相信一条黑龙呢？尤其是在他们对你的家族做了那些事之后？"
D.Strings[62985]="你对拉希奥怎么看？"
D.Strings[62986]="只要你赢得了黑王子殿下的尊重，那你也就赢得了我的尊重。再去完成一些他给你的任务吧。$b$b在此之前，请你先走开。我没有什么可卖给你的。"
D.Strings[62987]="欢迎。我可以帮你找回从黑王子那里得到的奖励……只需要一点点代价。"
D.Strings[62988]="我该怎么找回以前从你那里得到的奖励？"
D.Strings[62989]="在酒肆里找到我的黑爪军需官。他可以帮你找回我先前给你的任何奖励……当然是收费的。显然你已经注意到了，我用的材料可是一点儿也不便宜。"
D.Strings[62990]="你成功了！太好了。现在我们可以开始了。"
D.Strings[62991]="%s用|cFFFF0000|Hspell:136898|h[火焰喷射器]|h|r横扫整片区域！"
D.Strings[62992]="%s在近战范围内找不到敌人，因此转而使用|cFFFF0000|Hspell:136854|h[死亡凝视]|h|r了！"
D.Strings[62993]="%s准备使用|cFFFF0000|Hspell:137074|h[裂地猛击]|h|r来打击附近的敌人！"
D.Strings[62994]="%s施放出了剧烈的|cFFFF0000|Hspell:136847|h[震荡波]|h|r！"
D.Strings[62995]="%s引导了|cFFFF0000|Hspell:138019|h[闪电之刺]|h|r！快远离那头蜥蜴人！"
D.Strings[62996]="寇多克复活一名阵亡的盟友来协助他战斗！"
D.Strings[62997]="避雷针施放的电能形成了一个元素生物！"
D.Strings[62998]="你被|cFFFF2222[电击]|r了。你可以对附近的一根避雷针释放电能。"
D.Strings[62999]="我的剑永远指向酋长所指的方向。"
D.Strings[63000]="现在只有一个办法了。我一定要加入议会。至于农场……"
D.Strings[63001]="我们惹上了大麻烦，$n。但一切都是值得的。"
D.Strings[63002]="|TInterface\\Icons\\spell_frost_piercing chill:20|t你成为了|cFFF00000|Hspell:139866|h[寒冰洪流]|h|r的目标！"
D.Strings[63003]="|TInterface\\Icons\\inv_misc_volatilefire:20|t你受到了|cFFF00000|Hspell:139822|h[燃烬]|h|r的影响！"
D.Strings[63004]="我拿到钥匙了，我们开始突击吧。[排队等待单人副本。]"
D.Strings[63005]="我很乐意帮忙！"
D.Strings[63006]="爸爸说，不要跟陌生人说话。"
D.Strings[63007]="我可以一直数到“九——十”哦。听好了！$B$B<米莉开始掰手指头和脚趾头。>$B$B一，二，三，五，六，嗯……七，八，九——十！$B$B等等，我漏了一个……"
D.Strings[63008]="别把种子塞进鼻子了。爸爸会很生气的！"
D.Strings[63009]="我喜欢海龟。"
D.Strings[63010]="数数最好玩了！"
D.Strings[63011]="米莉，请帮我包一些种子。"
D.Strings[63012]="我们随时都能发动突击，只是需要一把钥匙。你找到钥匙了吗？"
D.Strings[63013]="|TInterface\\Icons\\spell_nature_callstorm:20|t%s使用|cFFFF0000|Hspell:138732|h[电离反应]|h|r影响他的敌人！"
D.Strings[63014]="坚持训练，必有所获。"
D.Strings[63015]="我们到岛上去吧。"
D.Strings[63016]="你做好再试一次的准备了吗？"
D.Strings[63017]="是的，我们来给延极矿充能吧！"
D.Strings[63018]="干得好，时间刚刚好。我们发现了一把钥匙，应该能打开其中一个箱子。现在它归你了。"
D.Strings[63019]="我们差点就没法把你拉出来了。你真是走运，居然还活着。"
D.Strings[63020]="让煞魔过来吧！"
D.Strings[63021]="我只要一点点，我保证。"
D.Strings[63022]="你是阴性O型血，对吧？"
D.Strings[63023]="啊，没错，我在这儿都能闻到了！"
D.Strings[63024]="你即将放弃任务！在被传送到最近的墓地前，你必须返回原地。"
D.Strings[63025]="|TInterface\\Icons\\achievement_zone_cataclysm.blp:20|t%s开始引导一个大型|cFFFF0000|Hspell:138564|h[灾变]|h|r法术！"
D.Strings[63026]="|TInterface\\Icons\\ability_warlock_chaosbolt.blp:20|t%s开始施放一支大型|cFFFF0000|Hspell:138559|h[混乱之箭]|h|r！"
D.Strings[63027]="掌炉者沃空装备上他的法杖并开始引导闪电之力！"
D.Strings[63028]="掌炉者沃空装备上他的战锤并开始用力挥舞！"
D.Strings[63029]="融合之煞开始施放 |cFFFF2222|Hspell:139375|h[暗影爆裂]|h|r！快跑！"
D.Strings[63030]="融合之煞被削弱了！快用|cFFFF2222[闪电长枪]|r丢它！"
D.Strings[63031]="融合之煞开始施放|cFFFF2222|Hspell:139443|h[流星风暴]|h|r！"
D.Strings[63032]="融合之煞放逐了天界防御者！快保护你自己！"
D.Strings[63033]="天界防御者遭到重创，无法继续战斗了！"
D.Strings[63034]="一座|cFFFF2222[雷霆铁砧]|r过载了！快点击它以施放|cFFFF2222|Hspell:138834|h[雷霆涌动]|h|r！"
D.Strings[63035]="这艘船得有个新规矩了！所有不卖力干活儿的人，他们的灵魂将被注入魔像。"
D.Strings[63036]="在我的指挥下，这艘船将成为所有人的噩梦！对不对啊，利皮？"
D.Strings[63037]="这些赞达拉巨魔不可小觑。他们和我见过的任何巨魔都不一样。"
D.Strings[63038]="我的游侠从赞图尔发回的报告相当令人不安。我想，该是我们打上门去的时候了。"
D.Strings[63039]="枯骨与万灵同在！"
D.Strings[63040]="枯骨与死神同在！"
D.Strings[63041]="枯骨与我同在！"
D.Strings[63042]="枯骨与你同在，伙计！"
D.Strings[63043]="让骨头滚起来……"
D.Strings[63044]="祖尔查卡要滚骨头！"
D.Strings[63045]="炸药来了，温蕾萨。"
D.Strings[63046]="影踪派防御者放下了一颗|cFFFF2222|Hspell:132744|h[治疗宝珠]|h|r！"
D.Strings[63047]="你做好帮我开启雷霆熔炉的准备了吗？这可能有点危险。"
D.Strings[63048]="开启吧！"
D.Strings[63049]="一座|cFFFF2222[雷霆铁砧]|r过载了！快激活它以进行|cFFFF2222|Hspell:138834|h[释能]|h|r。"
D.Strings[63050]="|cFFFF2222[闪电长枪]|r充能完毕。快用它消灭融合之煞！"
D.Strings[63051]="|TInterface\\Icons\\spell_arcane_mindmastery.blp:20|t %s醒了过来，但依然遭受着可怕的|cFFFF0000|Hspell:140432|h[宿醉]|h|r折磨！"
D.Strings[63052]="它从船上过来了！我们走！"
D.Strings[63053]="闪电之柱附近正在酝酿一场风暴。小心！"
D.Strings[63054]="快远离镣铐以打破链接！"
D.Strings[63055]="|TInterface\\Icons\\ability_thunderking_thunderstruck.blp:20|t雷神被激怒了，开始召唤|cFFFF0000|Hspell:140549|h[闪电风暴]|h|r！"
D.Strings[63056]="|TInterface\\Icons\\spell_shadow_destructivesoul.blp:20|t%s施放了|cFFFF0000|Hspell:140543|h[灌能之斧]|h|r！快跑开！"
D.Strings[63057]="|TInterface\\Icons\\warrior_talent_icon_bloodandthunder.blp:20|t%s开始施放|cFFFF0000|Hspell:140531|h[绝杀]|h|r！快打破|cFFFF0000锁链|r以获取自由！"
D.Strings[63058]="设置"
D.Strings[63059]="将日歌农场设置为你的家。"
D.Strings[63060]="<一本厚重的书籍，封面非常陈旧，夹缝中还有灰尘。看来老愚延续了传统，一直在这本日志上记录日歌农场的历史。日志翻到他的最后一条记录上：这是一条写给你的信息！>$B$B“感谢你让我祖传的土地恢复了昔日的荣光。我又更重要的事情要做了；现在轮到你来书写这些书页了。”"
D.Strings[63061]="洞穴钻地者开始召唤附近的页岩追猎者来协助作战。"
D.Strings[63062]="洞穴钻地者用|cFFF00000|Hspell:140600|h[声波警告]|h|r向附近的页岩追猎者警告了你的到来！"
D.Strings[63063]="%s开始施放沉默赞歌！快躲到屏障里去！"
D.Strings[63064]="|cFFFF0000部落|r失去了对熊猫人矿洞的控制！"
D.Strings[63065]="联盟取得了对熊猫人矿洞的控制！"
D.Strings[63066]="|cFFFF0000部落|r取得了对熊猫人矿洞的控制！"
D.Strings[63067]="联盟失去了对熊猫人矿洞的控制！"
D.Strings[63068]="联盟取得了对地精矿洞的控制！"
D.Strings[63069]="|cFFFF0000部落|r取得了对地精矿洞的控制！"
D.Strings[63070]="|cFFFF0000部落|r失去了对地精矿洞的控制！"
D.Strings[63071]="联盟失去了对地精矿洞的控制！"
D.Strings[63072]="我赐予你北风的冷酷复仇之力！"
D.Strings[63073]="他代表着一切正直、正义以及其他的无聊品质。他就是德莱尼圣骑士，阿霍鲁！"
D.Strings[63074]="各位，快拿出你们的铲子吧！明格斯·迪格斯将给我们上一堂考古课！"
D.Strings[63075]="喔哟哟……看看是谁大摇大摆地回来了。它就是肿着嘴的大鸟，帝皮！这次，它不是一只鸟在战斗！"
D.Strings[63076]="他代表了一切正直、正义与其他为大多数人所不屑的美德。他就是德莱尼圣骑士，阿霍鲁！"
D.Strings[63077]="这位挑战者可是我们的老朋友了！欢迎回到竞技场，帝皮！"
D.Strings[63078]="蝾螈，去打开那道门。"
D.Strings[63079]="我们追查着最近发生在杜隆塔尔的失踪事件，最终来到了怒焰裂谷中的这片废弃地带。"
D.Strings[63080]="日安，长官！"
D.Strings[63081]="我们的任务就是挖出这一系列绑架事件的幕后黑手并加以阻止。"
D.Strings[63082]="沙砾、钟摆和伏特，你们三个去支援她。"
D.Strings[63083]="蝾螈，我们得立刻打开这道门。"
D.Strings[63084]="我正在装填最后一批炸药，长官！"
D.Strings[63085]="炸药装填完毕，你们准备好之后，就赶紧按下引爆装置吧！"
D.Strings[63086]="上！上！上！"
D.Strings[63087]="猴子偷桃！"
D.Strings[63088]="部落丢弃了联盟运金车！"
D.Strings[63089]="部落偷走了联盟的黄金！"
D.Strings[63090]="我还要用轰轰炸飞蠢蛋！"
D.Strings[63091]="给每次轰轰里多加一点轰轰！"
D.Strings[63092]="把蠢蛋炸上天！"
D.Strings[63093]="利用锥形光束发现并击败隐藏的猩红雾行兽！"
D.Strings[63094]="利用锥形光束发现并击败每种颜色的雾行兽各一只！"
D.Strings[63095]="还有两只雾行兽。"
D.Strings[63096]="还有一只雾行兽。"
D.Strings[63097]="你成为了红光的目标！快绕着战场移动，让你的队友找出并击败猩红雾行兽。"
D.Strings[63098]="你成为了蓝光的目标！快绕着战场移动，让你的队友找出并击败碧蓝雾行兽。"
D.Strings[63099]="入侵者！干掉他们！"
D.Strings[63100]="今天已经没有挑战者敢来挑战你了，$n。你真是太厉害了。\n\n你还想打？去弄一张挑战卡牌，然后再来找我吧。"
D.Strings[63101]="幸运之笛！"
D.Strings[63102]="同时进场的还有：豪爽的布姆布姆大师！就是那位扔炸药的猢狲武僧！"
D.Strings[63103]="同时进场的还有：带着大箱炸弹的猢狲！他就是扔炸药的猢狲武僧，布姆布姆大师！"
D.Strings[63104]="祝你倒大霉！"
D.Strings[63105]="你肯定带了强力幸运符。"
D.Strings[63106]="笨蛋土地精包裹！"
D.Strings[63107]="我们在下面有了重大发现！可后来，岩石突然就开始反击，所有人都疯了。真是亏本的买卖！"
D.Strings[63108]="拜托了，快阻止这一切吧！"
D.Strings[63109]="你在看什么呢，小鬼？该干活儿了！"
D.Strings[63110]="需要敌对目标！"
D.Strings[63111]="垂直尾翼离线。动力下降。"
D.Strings[63112]="目标停止运行。战斗行动终止。"
D.Strings[63113]="休想煮了我，你这愚蠢的巨魔！"
D.Strings[63114]="尝尝这个，你这蓝皮巫婆！"
D.Strings[63115]="想烤了我吗，你这暴牙狗？！我会好好教训你的！"
D.Strings[63116]="鸡蛋感应器离线。正在关闭。"
D.Strings[63117]="防护块故障。正在卸载系统。"
D.Strings[63118]="喙部设备过载。正在关闭装置。"
D.Strings[63119]="你引起了我的注意。呃，没事了。"
D.Strings[63120]="我这身行头全是靠揍人换回来的。"
D.Strings[63121]="没错，我打拳的日子已经过去了。现在，我全靠美酒和三流美女打发日子了。"
D.Strings[63122]="这上面的视线确实更好，而且还不会被血溅到。"
D.Strings[63123]="我总会为机器人们欢呼。"
D.Strings[63124]="你刚才说话了吗？抱歉，每次有人被干掉时，我总会兴奋过头，从而忘了听别人说话。"
D.Strings[63125]="不，不，我不是来打拳的。我主要是来给布鲁斯捧场的。"
D.Strings[63126]="啊，没错，我还记得我第一次跟黑暗召唤师战斗的情况。然后是第二次……第三次……"
D.Strings[63127]="你问我有什么建议？永远不要低估你的对手，无论他们有多瘦小，多笨拙，或是多可爱。"
D.Strings[63128]="什么？死亡骑士就不能偶尔打扮一下吗？"
D.Strings[63129]="真不敢相信，我居然跟她撞衫了。真是太尴尬了。"
D.Strings[63130]="你要敢再那么看我一眼，我就把你从船上推下去。"
D.Strings[63131]="古嘎其实不想呆在这儿的。古嘎只是不知道该怎么下去。"
D.Strings[63132]="古嘎打过一次，结果被鳄鱼咬了一口。$b$b人人都讨厌古嘎。$b$b古嘎伤心了。"
D.Strings[63133]="你认识里克？他是个好朋友！"
D.Strings[63134]="$g嘿，帅哥。比赛结束后去别处坐坐怎么样？就我们俩？:滚开，烂货。我正想搞搞气氛呢，都被你搞砸了。;"
D.Strings[63135]="我已经戴够拳手戒指了。最近，我正想找个别的戒指戴戴。"
D.Strings[63136]="$g嘿，陌生人。我随时都可以跟你打一场。而且我保证，战斗不会超过2分钟。\n\n<希尔加魅惑地眨了眨眼。>:我看到你对那边的哈尔抛媚眼了。那个牛头人是我的。\n\n你干嘛不顶着你那张拜金的丑脸到其他飞艇上去？;"
D.Strings[63137]="对！对！就这样！"
D.Strings[63138]="小鸡们……进攻！"
D.Strings[63139]="再来几只鸡！再来几只鸡！"
D.Strings[63140]="布鲁斯！"
D.Strings[63141]="布——鲁——斯！"
D.Strings[63142]="布——鲁——斯——！"
D.Strings[63143]="布鲁斯，上！"
D.Strings[63144]="你死定啦！"
D.Strings[63145]="咬他！咬他！咬死他！"
D.Strings[63146]="这才是我的布鲁斯！"
D.Strings[63147]="拜托，布鲁斯，起来！"
D.Strings[63148]="再来一下，布鲁斯。就一下！"
D.Strings[63149]="布鲁斯！怎么会这样！？！"
D.Strings[63150]="铁拳医师！"
D.Strings[63151]="给他们一拳！"
D.Strings[63152]="这五根手指对你的脸说了什么呢？"
D.Strings[63153]="制胜锤拳！"
D.Strings[63154]="尝尝我的铁拳吧！"
D.Strings[63155]="铁拳医师！！"
D.Strings[63156]="尝尝痛楚的滋味吧！"
D.Strings[63157]="咔吧！"
D.Strings[63158]="嘭！"
D.Strings[63159]="咔咔！"
D.Strings[63160]="巴泽法兰老板希望能有更多人加入拳手的行列，并希望他们能打出更高水平的比赛。\n\n“奖励！”她说，“我们需要给他们一个更诱人的理由去战斗！”\n\n于是，她让我们造了这艘飞艇。你瞧，这里能提供更好的观赛角度，各种顶级美酒，还有向朋友们吹嘘的资本。你瞧——只有8级或8级以上的拳手才能上去。\n\n你想上飞艇吗？那就多赢几场拳赛吧，伙计。"
D.Strings[63161]="快跳上传送器，$n！它没准是安全的！\n\n当然，它也有可能要了你的命。"
D.Strings[63162]="长官，这些库卡隆看起来不是很友善啊！"
D.Strings[63163]="+15点遗物奖励！"
D.Strings[63164]="+30点遗物奖励！"
D.Strings[63165]="联盟丢弃了部落运金车！"
D.Strings[63166]="联盟偷走了部落的黄金！"
D.Strings[63167]="啊，这么说你想决斗？那就如你所愿！"
D.Strings[63168]="|TInterface\\Icons\\inv_stone_10.blp:20|t %s选择了|cFFFF0000石头|r！你|cFF00FF00赢|r了！"
D.Strings[63169]="|TInterface\\Icons\\inv_stone_10.blp:20|t %s选择了|cFFFF0000石头|r！你|cFFFF0000输|r了！"
D.Strings[63170]="|TInterface\\Icons\\inv_stone_10.blp:20|t %s选择了|cFFFF0000石头|r！你们打平了！"
D.Strings[63171]="输给了……一只小鸡！"
D.Strings[63172]="这个死亡的兽人穿着霜狼氏族的服饰。附近或许还有其他死难者。"
D.Strings[63173]="我的密探追踪赞达拉到了这里。"
D.Strings[63174]="我真不敢想象赞达拉在跟他们搞什么邪恶阴谋……"
D.Strings[63175]="是啊，这天气确实不正常。"
D.Strings[63176]="我让勇士们先上。他们会竭尽所能把我们的人救出来的。"
D.Strings[63177]="你的到来真令人振奋，茉艾拉。谢谢你。"
D.Strings[63178]="……所以你才会不顾其他部族的反对，率领着私人卫队来到这里？"
D.Strings[63179]="嗯，保重，执政女王。"
D.Strings[63180]="闪光岭。我知道霜鬃巨魔就窝在那片白雪皑皑的山头上。"
D.Strings[63181]="这场风暴害我们损失了许多巡山人，这可能是巨魔在搞鬼。"
D.Strings[63182]="没错。我真不想派人过去，那儿净是埋伏和腐臭。"
D.Strings[63183]="如果他们能阻止风暴，我就亲自率领熔炉卫士上去。"
D.Strings[63184]="我也要多谢你，瓦里安。你在大厅上的话很有道理……"
D.Strings[63185]="没错。有了这些勇士的协助，黑铁矮人就能终结赞达拉对丹莫罗的威胁。"
D.Strings[63186]="我们回头见，暴风城国王。"
D.Strings[63187]="我们到了——古老的熊猫人智慧宝库。$b$b我们开始吧？"
D.Strings[63188]="那么，就去觐见玉珑吧。"
D.Strings[63189]="玉珑在等着呢！"
D.Strings[63190]="我们从很远之外就闻到你在跟踪我们了。要不是我们起了好奇心，你现在已经是个死人了。$b$b事实上，你干掉这家伙的手段引起了我们的注意。$b$b你到底想干什么？"
D.Strings[63191]="此时此地，我们将用自己的鲜血向议会、铁炉堡和联盟证明自己的忠诚。"
D.Strings[63192]="三锤议会的内讧必须终止。"
D.Strings[63193]="不管是什么邪恶力量引来了这场风暴，快去阻止它吧。这样，熔炉卫士就能攻上山头，并扫清那里的霜鬃和赞达拉巨魔。$B$B去找我的巡山人，或者任何被巨魔俘虏的人，他们能为你指路。"
D.Strings[63194]="请想办法阻止这场人为的风暴，勇士，并尽力拯救俘虏。$B$B祝你好运。"
D.Strings[63195]="是谁闯进了我的新巢穴？也许是霜狼兽人的某只小宠物？"
D.Strings[63196]="等等，这不是霜狼氏族的人。"
D.Strings[63197]="不管了，干掉他！让我们来尝尝他的味道。"
D.Strings[63198]="你们可来了。听我说：国王的密探都死光了。只有少数矮人斥候活了下来。"
D.Strings[63199]="前面就有一个。要是能救下他，也许就能了解些情况。"
D.Strings[63200]="从前——其实也没过多久——有位伟大的国王向三位强大的矮人，也就是三锤议会求助。"
D.Strings[63201]="国王的密探发现，赞达拉巨魔正威胁着矮人的主城。"
D.Strings[63202]="国王想当然地认为，只要帮他们化解巨魔危机，他们就会派出军队帮他对抗部落。"
D.Strings[63203]="可国王没有想到，矮人们竟然对彼此毫不信任！"
D.Strings[63204]="“我们帮不了你，”铜须矮人说，“如果我们不盯紧黑铁矮人，他们就会击败蛮锤矮人并占据铁炉堡！”"
D.Strings[63205]="“我们帮不了你，”蛮锤矮人说，“如果我们不盯紧黑铁矮人，他们就会击败铜须矮人并占据铁炉堡！”"
D.Strings[63206]="国王很生气，”如果你们都不帮忙，铁炉堡就会被攻陷！”"
D.Strings[63207]="只有一位矮人愿意帮忙：“我们愿意出力，”黑铁矮人茉艾拉说，“我们信任其他矮人兄弟，还要让他们看看什么叫忠诚！”"
D.Strings[63208]="于是茉艾拉和国王深入雪山去拯救铁炉堡，留下其他人反思自己的行为。"
D.Strings[63209]="后来怎么样了？我必须知道！"
D.Strings[63210]="国王率领他的勇士，和黑铁矮人齐心协力拯救了铁炉堡。"
D.Strings[63211]="其他矮人首领为自己的行为感到羞愧，发誓再也不让恐惧或猜忌影响自己的判断。"
D.Strings[63212]="就这样，一位人类国王将分裂已久的矮人部族团结了起来。"
D.Strings[63213]="彼此信赖的三位矮人首领承诺，要为联盟大业献出全部力量。"
D.Strings[63214]="而此时，在奥格瑞玛，酋长加尔鲁什·地狱咆哮向潘达利亚各地派出了大量地精挖掘队。"
D.Strings[63215]="他许诺，谁能为他解开这片土地中那股强大的黑暗力量背后的秘密，就能得到黄金和财富。"
D.Strings[63216]="令我惊讶的是，他的人真有了发现！就在这圣谷之中！那后来呢？"
D.Strings[63217]="故事仍在继续……"
D.Strings[63218]="所以，当联盟前所未有地团结一致时，部落却正在分崩离析。"
D.Strings[63219]="朋友，大事将要发生。我很想亲身体验接下来的故事，但是，很可惜，我只是个说故事的人。"
D.Strings[63220]="而你，勇敢的英雄——你很强大，足以搅动时代的狂澜。"
D.Strings[63221]="快去吧！去杜隆塔尔！在历史上留下你的印记！"
D.Strings[63222]="感谢物理法则，你可来了！"
D.Strings[63223]="|TInterface\\Icons\\inv_inscription_scroll.blp:20|t %s选择了|cFFFF0000布|r！你|cFFFF0000输|r了！"
D.Strings[63224]="|TInterface\\Icons\\inv_inscription_scroll.blp:20|t %s选择了|cFFFF0000布|r！你们打平了！"
D.Strings[63225]="|TInterface\\Icons\\inv_inscription_scroll.blp:20|t %s选择了|cFFFF0000布|r！你|cFF00FF00赢|r了！"
D.Strings[63226]="|TInterface\\Icons\\inv_sword_102.blp:20|t %s选择了|cFFFF0000剪刀|r！你|cFFFF0000输|r了！"
D.Strings[63227]="|TInterface\\Icons\\inv_sword_102.blp:20|t %s选择了|cFFFF0000剪刀|r！你们打平了！"
D.Strings[63228]="|TInterface\\Icons\\inv_sword_102.blp:20|t %s选择了|cFFFF0000剪刀|r！你|cFF00FF00赢|r了！"
D.Strings[63229]="噢，以我胡须的名义，我还以为死定了呢！谢谢你们！谢谢你们！"
D.Strings[63230]="那么……是人类国王派你们来的？他的密探都死了……我们的人也牺牲了大半。"
D.Strings[63231]="我看见他们拖着粗酿往南边的小屋去了。如果你们动作快，或许能救下她，她可能知道更多的情况。"
D.Strings[63232]="但别靠近那座大村子！那里全是发疯的冰巨魔！唉……那个赞达拉祭司让他们都发了疯！"
D.Strings[63233]="这种令人口水直流的美酒散发着一股令人迷醉的香气。"
D.Strings[63234]="噢，刚才好险呐，多谢了！"
D.Strings[63235]="幸存者很少；没被吃掉的人都被杀死在西北边的祭坛上。"
D.Strings[63236]="如果你们动作快，或许能救下几个！抱歉，我就知道这么多……"
D.Strings[63237]="现在不行，$c。我今天没法训练你。$b$b<你的训练师压低嗓门，悄声说道。>$b$b库卡隆正盯着我们的一举一动。加尔鲁什已经控制了精神谷。$b$b你想帮忙？那就去找沃金吧。他知道该怎么办。"
D.Strings[63238]="你需要训练？你真是来错时候了，这会儿精神谷可不太平。$b$b<你的训练师压低嗓门，悄声说道。>$b$b库卡隆正盯着我们的一举一动。加尔鲁什已经控制了精神谷。如果他们看见我跟你说话，可能会杀了我的。$b$b幸运的是，他们永远都休想看见我。靠近点，$n。我们得低调行事。"
D.Strings[63239]="训练服务已经暂停。你想学习烹饪？去别处学吧。"
D.Strings[63240]="不，现在不行。"
D.Strings[63241]="抱歉，$c。我的墨水都干了。"
D.Strings[63242]="库卡隆有令，今天不准钓鱼。"
D.Strings[63243]="今天不开业，$n。银行被暂时接管了。$b$b库卡隆首领说了，他们要杜绝任何“未经授权的提款行为”。但……你也许该去确认一下。"
D.Strings[63244]="我这里没有房间了，$n。我的旅馆已经被库卡隆征用，成为临时兵营了。"
D.Strings[63245]="<克苏卡紧张地看了看身后。>如果你想要你的宠物，最好去别处取，$c。库卡隆盯着呢。"
D.Strings[63246]="今天不举行拍卖，$r。以目前的局势看，拍卖恐怕要暂停一阵了。"
D.Strings[63247]="你最好去别处做生意吧，$r。我可不想惹麻烦。"
D.Strings[63248]="今天不卖东西。太危险了。"
D.Strings[63249]="我的蛇，伙计。他们抢走了我的蛇！"
D.Strings[63250]="我今天不卖东西。"
D.Strings[63251]="<胡祖警惕地看了看身后。>现在不行。最近这里的局势非常紧张。"
D.Strings[63252]="你最好保持距离，$c。最近库卡隆的戒严非常严格。谁都不知道究竟发生了什么事。"
D.Strings[63253]="抱歉，$c。我这里没有你要的东西。"
D.Strings[63254]="肮脏的怪物！我欠你一条命。"
D.Strings[63255]="听着：我们发现了风暴的源头。卑鄙的赞达拉巨魔让冰巨魔用鲜血祭祀元素。"
D.Strings[63256]="在北边，桥的另一头有个山洞。如果能杀死里面的元素，风暴就会停止。"
D.Strings[63257]="排队等待王者的耐心场景战役。"
D.Strings[63258]="排队等待公海激战场景战役。"
D.Strings[63259]="排队等待怒焰之谜场景战役。"
D.Strings[63260]="传送门都关闭了。我听说兽人在暗影裂口下还保留了一座通往诅咒之地的传送门。"
D.Strings[63261]="沃金还活着！"
D.Strings[63262]="沃金还活着，兄弟！"
D.Strings[63263]="反对压迫！"
D.Strings[63264]="站出来反抗加尔鲁什·地狱咆哮！部落将在今天迎来新生的曙光！"
D.Strings[63265]="$n被|cFFFF0000|Hspell:141407|h[冰霜凝结]|h|r了。快释放$g他:她;！"
D.Strings[63266]="妖术真带劲。"
D.Strings[63267]="这有助于提高波贝的巫医水平。"
D.Strings[63268]="波贝找到了一个志愿者！"
D.Strings[63269]="这会治好他们的。"
D.Strings[63270]="巨魔！你还在我的镇上做什么？"
D.Strings[63271]="训练法师啊。"
D.Strings[63272]="地狱咆哮的部落不需要你那些巫毒把戏，巨魔。现在，滚出我的视线！"
D.Strings[63273]="敲响挑战之锣以接受玉珑的挑战。你只需要从四位至尊天神的挑战中选择一项完成即可。"
D.Strings[63274]="敲响挑战之锣[远程输出挑战]"
D.Strings[63275]="啊，到了。唉，我这把老骨头可累惨了，绝对超出你的想象。"
D.Strings[63276]="你令我吃惊。我以为你这样的英雄会对扶老人上山的任务不屑一顾。他们就是太骄傲。"
D.Strings[63277]="我本想给你上一课，结果却是你给我上了一课。你知道，在我年轻那会儿……在我年轻那会儿……在我年轻那会儿……"
D.Strings[63278]="我曾经是……皇帝。"
D.Strings[63279]="你目光所及之处皆为我的领土。"
D.Strings[63280]="我征服了自己的疑虑、恐惧和愤怒……将它们埋入地底。"
D.Strings[63281]="但我仍有一个缺点，而且从未能征服它。那就是骄傲。"
D.Strings[63282]="骄傲令这片土地陷入迷雾！我们自以为比外面的世界更优越。"
D.Strings[63283]="我觉得我们能解决自己的问题。但一万年过去了，我们停滞不前，地下的疑虑和恐惧一有机会，就会出来作祟。"
D.Strings[63284]="骄傲，它是最阴险的。所谓成也骄傲，败也骄傲，它比其他所有煞魔加起来还要危险。"
D.Strings[63285]="警惕骄傲，保持谦卑！世界日渐混乱，宿敌当前必须同心协力。骄傲的种族要承认自己需要帮助。"
D.Strings[63286]="黎明前的天空总是格外黑暗。只有精诚团结，我们才能战胜这黑暗。"
D.Strings[63287]="而最大的阻碍……就是骄傲。"
D.Strings[63288]="全是木材？很好。把它们送去奥格瑞玛。"
D.Strings[63289]="奥格瑞玛的城墙还不够高，不够厚！"
D.Strings[63290]="谁也不能质疑地狱咆哮领导下的部落的实力！"
D.Strings[63291]="看看我们找到了什么？原油？"
D.Strings[63292]="把它送去奥格瑞玛。"
D.Strings[63293]="新鲜的肉！直接从屠宰场运出来的。很好。"
D.Strings[63294]="把它们送去南边的试炼谷。我们的小兽人正嗷嗷待哺呢。"
D.Strings[63295]="好极了，一车石料。快送到奥格瑞玛去！"
D.Strings[63296]="暴烈之怒即将|cFFFF2222|Hspell:141456|h[爆炸]|h|r！"
D.Strings[63297]="让你们的武器保持锋利。我们今天将要上阵杀敌！"
D.Strings[63298]="把这些武器擦干净。今天我们就要让巨魔血流成河！"
D.Strings[63299]="任何人都不能反抗地狱咆哮！"
D.Strings[63300]="酋长将听到我们胜利的消息！"
D.Strings[63301]="酋长会听到你们惨败的消息！"
D.Strings[63302]="暗矛部族将会为他们的背叛付出代价！"
D.Strings[63303]="将暗矛部族从艾泽拉斯抹去！"
D.Strings[63304]="这个村子归我们了！巨魔统统去死吧！"
D.Strings[63305]="你们每上交一件战利品，我就奖励你们一桶酒。"
D.Strings[63306]="谁要是临阵脱逃被我抓住，那就是死路一条。为了加尔鲁什！"
D.Strings[63307]="你想要礼物？！好极了，我的腿都不能动了！！！"
D.Strings[63308]="电……力……严重……不足……"
D.Strings[63309]="做好准备，英雄。你的挑战即将开始。"
D.Strings[63310]="这正是波贝所急需的训练。"
D.Strings[63311]="嘿，伙计。"
D.Strings[63312]="他们或许能让波贝变成真正的巫医！"
D.Strings[63313]="离巫术远点儿。"
D.Strings[63314]="万灵抛弃了你。"
D.Strings[63315]="总算让我遇到一个像样的对手了！"
D.Strings[63316]="啊，一个$r。我好久没杀过你们这些家伙了。"
D.Strings[63317]="我的战斧在渴望战斗！"
D.Strings[63318]="你休想躲过我的眼睛！"
D.Strings[63319]="我要拿你去喂我的狼。"
D.Strings[63320]="我看见你了！"
D.Strings[63321]="牛头人！你们的人都干了些什么？你们在我们神圣的山谷中挖出了一条丑陋的疤痕！"
D.Strings[63322]="祝掌门，请你理解——下达这个命令的兽人“酋长”已经不能再代表整个部落。许多人已经起来反对他了。"
D.Strings[63323]="我不关心你们的内政。你们部落亵渎了这片圣地。这里不再欢迎你们了——给我立刻离开这里！"
D.Strings[63324]="请给我们一点时间，祝掌门。请给我们一个将地狱咆哮绳之以法的机会。"
D.Strings[63325]="烈日行者，我很尊重你们的人民。你们在我们与煞魔和雷电之王的战役中出力甚多。否则，我已经直接命令影踪派肃清整座双月殿了。但我的耐心是有限的。部落必须离开这里。"
D.Strings[63326]="拜托，请给我们一点时间来纠正错误。"
D.Strings[63327]="祝踏岚冷酷地看向远处。"
D.Strings[63328]="很好。你们的时间就到这一季结束前为止。不能再久了。"
D.Strings[63329]="我们熊猫人对于推翻暴君并不陌生。即将到来的战争将考验你们的灵魂。愿至尊天神指引你们的道路。"
D.Strings[63330]="酋长下令严守这片海滩！一旦联盟采取行动，他们的鲜血将染红海水！"
D.Strings[63331]="你听说了吗？叛乱的巨魔对剃刀岭发动了攻击。"
D.Strings[63332]="里克保证守住这片海滩！"
D.Strings[63333]="我们或许不该相信联盟，但要想夺回部落，我们就需要他们的帮助。"
D.Strings[63334]="很好。你值得信赖，相信联盟也会做出正确的选择。"
D.Strings[63335]="暗矛部族会和盟友从地面进攻奥格瑞玛，以便你们从海上进攻。只有这个办法。"
D.Strings[63336]="如果我们能活下来，那么有一天，我或许能称你为……“朋友”。"
D.Strings[63337]="看看我们三个。又回到了杜隆塔尔的沙滩！就像从前一样。"
D.Strings[63338]="不一样了，老朋友。时代不同了。敌友间的界限已不再清晰。"
D.Strings[63339]="他们来了！地狱咆哮以为他的人能横扫一切。"
D.Strings[63340]="就让酋长看看暗矛部族的怒火吧！"
D.Strings[63341]="住手！别追了。如果他们敢回去，地狱咆哮会把他们当作懦夫处死的。森金村安全了！"
D.Strings[63342]="集合！我们得先发制人，抢在酋长增兵剃刀岭之前先占领它，并阻断通往贫瘠之地的交通！"
D.Strings[63343]="还能继续战斗的人，跟我来！"
D.Strings[63344]="等等，沃金。部落正在自相残杀。这简直让我崩溃。"
D.Strings[63345]="我们需要你，伙计。"
D.Strings[63346]="我知道。你负责指挥进攻。我有其他的事要做。"
D.Strings[63347]="我不信所有的兽人都支持加尔鲁什。"
D.Strings[63348]="只要你一踏进奥格瑞玛，地狱咆哮就会割断你的脖子！"
D.Strings[63349]="我要独自前往奥格瑞玛，伊崔格，萨鲁法尔肯定都反对加尔鲁什。我还得去找其他人。"
D.Strings[63350]="不要说这种丧气话。"
D.Strings[63351]="我一定要说。万一我们失败了——我希望你明白：你始终是我的朋友，我的兄弟。"
D.Strings[63352]="为了部落。"
D.Strings[63353]="暗矛巨魔，跟我来！日夜兼程赶往奥格瑞玛！"
D.Strings[63354]="酋长真不该去惹暗矛部族。他害得部落四分五裂了。"
D.Strings[63355]="我训练了数百名年轻战士。酋长却在让他们白白流血。他不再是“我的酋长”了。"
D.Strings[63356]="拜托——别伤害我们！我们完全欢迎沃金把起义军驻扎在这里。"
D.Strings[63357]="你可以让我对“酋长”拔刀相向，但我只对付他手下那些堕落的战士——不要伤害平民！"
D.Strings[63358]="我们才是真正的部落！"
D.Strings[63359]="你们都是叛徒！"
D.Strings[63360]="沃金和他手下的畜生将卑贱地死去！"
D.Strings[63361]="成功了！剃刀岭归我们了！酋长或许已经从格罗玛什要塞上看到火光了……"
D.Strings[63362]="你的笛子是个很好的幸运符！你不配拥有它！"
D.Strings[63363]="沃金——你还活着！看来是真的了——一场反对酋长的起义。"
D.Strings[63364]="贝恩。我们需要你。剃刀岭只是一处前哨——大灾变之后，奥格瑞玛的城墙更加坚固了。"
D.Strings[63365]="我必须谨慎。我有许多族人还留在奥格瑞玛。"
D.Strings[63366]="跟着我的笛声跳起来吧！"
D.Strings[63367]="笛子可不是笨蛋玩的。"
D.Strings[63368]="幸运符，还是厄运符？"
D.Strings[63369]="只有笨蛋才想遇见扫把星。"
D.Strings[63370]="等雷神岛事毕，洛瑟玛就会立即起兵，而女妖之王也责无旁贷，可他们都远隔重洋。没有你的力量，我们无法突破城防。我需要牛头人部队。"
D.Strings[63371]="我们正在准备。但我需要时间来确保族人的安全。可是，沃金……"
D.Strings[63372]="如今的奥格瑞玛固若金汤。你恐怕还需要……部落之外的盟友。"
D.Strings[63373]="啊，你真强壮！我年轻时，准会怀疑我们能否做到。可现在我不再怀疑了。"
D.Strings[63374]="这风真冷啊！过去，它曾让我这把老骨头感到绝望。但是今天，我却满怀希望。"
D.Strings[63375]="呵呵，别对元素发怒。狂暴是它们的天性。我早已征服了自己的愤怒。"
D.Strings[63376]="你很有耐心！年轻的时候，我最恨这种事。而现在，我感到了满满的关爱。"
D.Strings[63377]="别像我年轻时那样恐高。恐惧会驱使我们做出可怕的事情。啊，但我看得出来，你和我一样，都学会了勇敢！"
D.Strings[63378]="你好啊！我就是水解型二杠零，简称H2-0。"
D.Strings[63379]="我是来帮你对付硬煤的。"
D.Strings[63380]="我已经预存了足够使用一次的水，这是免费赠送的，如果你想反复使用我的水解功能，就需要找到更多的水。"
D.Strings[63381]="|cFFFF0000部落|r取得了对中央矿坑的控制！"
D.Strings[63382]="封闭大门，马上去通知监视者。"
D.Strings[63383]="所有下等种族都是正统部落的敌人！"
D.Strings[63384]="联盟取得了对中央矿坑的控制！"
D.Strings[63385]="|cFFFF0000部落|r失去了对中央矿坑的控制！"
D.Strings[63386]="联盟失去了对中央矿坑的控制！"
D.Strings[63387]="雷施的倒影荡起欢快的涟漪。"
D.Strings[63388]="雷施的倒影开心地微笑起来。"
D.Strings[63389]="雷施的倒影静静地冒着气泡。"
D.Strings[63390]="我的合同上不是这么写的！"
D.Strings[63391]="我没拿到足额的薪水。"
D.Strings[63392]="嗯，破坏者？这不归我管！"
D.Strings[63393]="长官，那是加尔鲁什的人。"
D.Strings[63394]="你想让我难堪？！"
D.Strings[63395]="联盟来了！"
D.Strings[63396]="嘿！你怎么进来的？！"
D.Strings[63397]="卫兵！这里有联盟！"
D.Strings[63398]="全体散开，搜索这座大厅。如果幕后黑手是加尔鲁什，那我们就需要证据。"
D.Strings[63399]="我们不是你的敌人，克索伦斯！"
D.Strings[63400]="这些补给箱来自奥格瑞玛。加尔鲁什要这么多战略物资做什么？"
D.Strings[63401]="这些都是从锦绣谷的挖掘场运来的。加尔鲁什到底想在那里找什么？"
D.Strings[63402]="就算你们阻止了风暴，也休想阻止赞达拉的意志！你们死定了……一个也跑不了！"
D.Strings[63403]="让鲜血染红雪地吧！"
D.Strings[63404]="所有的巨魔都将联手对付你们！"
D.Strings[63405]="我们掌握着沙漠、海洋和飓风……"
D.Strings[63406]="我们会……让你们葬身山腹！"
D.Strings[63407]="还……没完呢！赞达拉……永垂不朽……"
D.Strings[63408]="国王的勇士们成功了：风暴停止了！前进，黑铁矮人！向着战场前进！"
D.Strings[63409]="为了铁炉堡！为了联盟！"
D.Strings[63410]="以烈焰为心，钢铁为志！站起来吧！消灭他们！"
D.Strings[63411]="干得好。黑铁矮人还是一如既往的强大。"
D.Strings[63412]="哈！很高兴你能这么说。铜须和蛮锤矮人会后悔未能在此与你分享荣耀的。"
D.Strings[63413]="你已经做到了。来吧，让我们回铁炉堡去，向三锤议会宣告你的胜利。"
D.Strings[63414]="确实如此，瓦里安国王。我还想说，愿为联盟效劳。"
D.Strings[63415]="还是庆幸他们不用派族人来这里送死吧。我们只想守护家园，表达忠诚而已。"
D.Strings[63416]="你的眼睛欺骗了你！"
D.Strings[63417]="%s阴险地笑着。"
D.Strings[63418]="你还能找到我吗？"
D.Strings[63419]="我一直期待着这一天：白虎可是潘达利亚的力量化身！"
D.Strings[63420]="$n突袭了熊猫人矿洞！"
D.Strings[63421]="$n突袭了地精矿洞！"
D.Strings[63422]="$n守住了地精矿洞！"
D.Strings[63423]="$n突袭了中央矿坑！"
D.Strings[63424]="$n守住了中央矿坑！"
D.Strings[63425]="$n守住了熊猫人矿洞！"
D.Strings[63426]="白虎！请聆听我们的祈求。"
D.Strings[63427]="啊，年轻的黑龙光临了我的寺院。你们俩的事迹已成了广为流传的潘达利亚传奇了。"
D.Strings[63428]="我和我的勇士希望得到力量的祝福。"
D.Strings[63429]="我为我的同伴感到骄傲。"
D.Strings[63430]="告诉我，年轻的王子：什么是力量？"
D.Strings[63431]="毁灭敌人的能力。这就是力量。"
D.Strings[63432]="这只是对于敌人一方而言。"
D.Strings[63433]="当然，力量也能帮助盟友。"
D.Strings[63434]="怎么帮？"
D.Strings[63435]="……当然是摧毁共同的敌人！"
D.Strings[63436]="真不愧是黑龙。很好，我会给你们祝福，但我也有些建议："
D.Strings[63437]="用力量去帮助别人，会比用它来对付敌人更加强大。"
D.Strings[63438]="那么，我的挑战，如果你们接受的话，将测试你们正确应对危险的能力与毅力。"
D.Strings[63439]="|cFFFE1CF7|Hspell:139267|h[文物镐]|h|r可使你获得双倍的遗物，持续15秒！"
D.Strings[63440]="使用[细剑招架]技能来避免竖劈！"
D.Strings[63441]="%s开始饮用|cFFFF2222|Hspell:141327|h[不稳定的混合物]|h|r。"
D.Strings[63442]="敲响挑战之锣以接受雪怒的挑战。你只需要从四位至尊天神的挑战中选择一项完成即可。"
D.Strings[63443]="敲响挑战之锣[近战输出挑战]"
D.Strings[63444]="你能打开它吗，钟摆？"
D.Strings[63445]="我专门为这种特殊情况留了一手。"
D.Strings[63446]="这玩意儿刚好能派上用场！"
D.Strings[63447]="螳螂妖炸弹？！你确定这不会炸塌整座洞穴吗？"
D.Strings[63448]="我们需要做一点改装，但它会起作用的。"
D.Strings[63449]="新兵，把那个池塘小马拿给我，还有三枚炮弹，两个电池以及那个始祖龙蛋黄。"
D.Strings[63450]="等等？他们怎么把这玩意儿放在这儿？谁会把这种东西放在这里？不管是谁，他都应该为此感到抱歉。"
D.Strings[63451]="“要用真螺栓，”他说，“不会害死我们的那种，”他说。我呸。"
D.Strings[63452]="嗯，天知道该怎么让这玩意儿动起来。"
D.Strings[63453]="这些兽人的设计还不错。他们只需要多加一些炸弹。"
D.Strings[63454]="现在开始挑战吧！英雄，你必须要在近战中击败黑王子。"
D.Strings[63455]="你，拉希奥，将被蒙上眼睛。"
D.Strings[63456]="黑王子，你很强大。可是失去指引的力量又有什么用呢？"
D.Strings[63457]="等等——这太荒唐了。我会杀死我的勇士的！"
D.Strings[63458]="……有意思。但结果不会改变。"
D.Strings[63459]="好吧。抱歉了，勇士——但今天被教训的人肯定不会是我。"
D.Strings[63460]="我跟你们这些苦工说过多少次了！我们需要更多的原油！"
D.Strings[63461]="%s嘟囔着戴上了眼罩。"
D.Strings[63462]="一头瞎眼的龙。真可笑！"
D.Strings[63463]="找出真正的敌人！别被假象迷惑了！"
D.Strings[63464]="巨龙比你更强大，英雄！别让他完成攻击！"
D.Strings[63465]="得了吧！你们就是工人！你们就该干活！"
D.Strings[63466]="我们就这点炸药了吗？我靴子上用的炸药都比它多。"
D.Strings[63467]="多使用缴械，利用每一点优势。"
D.Strings[63468]="绕到敌人背后去。他看不见你！动起来！"
D.Strings[63469]="我们到了，玄牛砮皂的家园。他象征着潘达利亚的坚忍精神，是唯一住在长城之外的至尊天神。"
D.Strings[63470]="玄牛！请聆听我们的祈求！"
D.Strings[63471]="我和我的勇士希望得到坚忍的祝福。"
D.Strings[63472]="克服一切困难的力量！这就是坚忍。"
D.Strings[63473]="你是想说——力量是外在的表现，而坚忍来自于内心？"
D.Strings[63474]="……当然。我早就知道了。"
D.Strings[63475]="小龙和他的凡人勇士来了。欢迎你们。"
D.Strings[63476]="告诉我，黑王子：什么才是坚忍？"
D.Strings[63477]="你把力量和坚忍搞混了，小龙。没有精神的力量一无是处！"
D.Strings[63478]="我见过卑微的奴隶忍受着难以想象的折磨，只为推翻他们的主人。"
D.Strings[63479]="我还见过最强大的皇帝被渺小而坚忍不拔的敌人打倒。"
D.Strings[63480]="是啊……你知道。但或许我们该考验一下你的理解。"
D.Strings[63481]="如果你们能够接受我的挑战的话，它将测试这位勇士在艰苦条件下的防卫能力。"
D.Strings[63482]="躲开攻击。利用他的力量对付他！"
D.Strings[63483]="元素是不灭的！在它们复活前，利用好你的时间！"
D.Strings[63484]="联盟运金车已满，现在可以潜入他们的基地去偷走它了！"
D.Strings[63485]="部落运金车已满，现在可以潜入他们的基地去偷走它了！"
D.Strings[63486]="敲响挑战之锣以接受砮皂的挑战。你只需要从四位至尊天神的挑战中选择一项完成即可。"
D.Strings[63487]="敲响挑战之锣[防御挑战]"
D.Strings[63488]="%s跑去为|cFFFF2222|Hspell:141381|h[霰弹射击]|h|r装填弹药了。"
D.Strings[63489]="$n夺取了联盟运金车！"
D.Strings[63490]="$n夺取了部落运金车！"
D.Strings[63491]="朱鹤带来的希望曾在历史上最黑暗的时刻鼓舞过潘达利亚的人民。我很想跟他谈谈。"
D.Strings[63492]="朱鹤！请聆听我们的祈求。"
D.Strings[63493]="我和我的勇士想要得到希望的祝福。"
D.Strings[63494]="希望就是……就是相信明天会更好。"
D.Strings[63495]="……朱鹤。你未曾见过我眼中所见。"
D.Strings[63496]="……燃烧天空的烈火即将归来，无可避免。燃烧军团会找到艾泽拉斯。"
D.Strings[63497]="血海翻波，城邦倾覆！而我们呢——分裂的世界——怎能对抗大军？"
D.Strings[63498]="你就是希望的化身。相信我，正是那一点点熬过灭顶之灾的微小希望在支撑着我。"
D.Strings[63499]="我……谢谢你，朱鹤。"
D.Strings[63500]="哦，灭世者之子，你证明了众生皆可得到救赎。你的光临令我深感荣幸。"
D.Strings[63501]="告诉我，大地守护者之子：什么是希望？"
D.Strings[63502]="这句话连你自己都不相信。"
D.Strings[63503]="你太低估我了。"
D.Strings[63504]="起来吧，死亡之翼之子。我会给你我的祝福，你是我见过的最需要它的人。"
D.Strings[63505]="我不赞同你把“希望”看做模糊而且无法想象的未来。"
D.Strings[63506]="要怀着希望渡过每一天。如此，方能创造梦想中的未来。"
D.Strings[63507]="如果你们接受我的挑战的话，就要治愈最惨痛的创伤。"
D.Strings[63508]="敲响挑战之锣以接受赤精的挑战。你只需要从四位至尊天神的挑战中选择一项完成即可。"
D.Strings[63509]="敲响挑战之锣[治疗挑战]"
D.Strings[63510]="一辆从格罗多姆农场前往前沿哨所的部落货车需要护送。"
D.Strings[63511]="一辆从南贫瘠之地前往十字路口的部落货车需要护送。"
D.Strings[63512]="一辆从棘齿城前往十字路口的部落货车需要护送。"
D.Strings[63513]="一辆从淤泥沼泽前往杜隆塔尔的部落货车需要护送。"
D.Strings[63514]="一辆从石爪山脉前往十字路口的部落货车需要护送。"
D.Strings[63515]="一辆准备驶出无水岭的部落货车需要护送。"
D.Strings[63516]="一辆准备驶出哀嚎洞穴的部落货车需要护送。"
D.Strings[63517]="一辆准备驶出死水绿洲的部落货车需要护送。"
D.Strings[63518]="一辆部落货车已被摧毁。"
D.Strings[63519]="没时间啦！"
D.Strings[63520]="快拿上那些遗物！"
D.Strings[63521]="不要停——这地方有点不对劲。"
D.Strings[63522]="别碰它——天知道那是什么东西！"
D.Strings[63523]="那到底是什么邪恶的玩意儿？"
D.Strings[63524]="别紧张，我想没人愿意再碰那玩意儿了。只要拿到钱，我们马上就离开这儿。"
D.Strings[63525]="嘿，嘿，怎么回事？这点钱只有说好的一半！"
D.Strings[63526]="不不，合同上写了，必须全额付清——"
D.Strings[63527]="是啊，我倒要看看，到时谁还会支持他。"
D.Strings[63528]="噢，呃，没什么，大人。为了部落，就这样。再见！"
D.Strings[63529]="拦截失败。启动主动防御矩阵。"
D.Strings[63530]="安全漏洞。禁用所有安全协议。"
D.Strings[63531]="激活动力装置。"
D.Strings[63532]="达到最大功率。"
D.Strings[63533]="不过是篡位者留下的小玩意儿……你们，也就是一小撮尘埃。"
D.Strings[63534]="我的鲜血饥渴难耐了。"
D.Strings[63535]="我将畅享苦难。"
D.Strings[63536]="你的挣扎只会让我精神百倍。"
D.Strings[63537]="释放……我……"
D.Strings[63538]="仇恨让我更加强大！"
D.Strings[63539]="噢，如此……强烈的……痛苦！"
D.Strings[63540]="我只是再次沉睡。"
D.Strings[63541]="让开，地精。这个遗物正是酋长要找的东西。从现在起，它受库卡隆的保护。"
D.Strings[63542]="这是按出勤的工人算的，工头。酋长可不会付钱给死人。"
D.Strings[63543]="你！就是你这种人让我们高贵的部落死气沉沉！"
D.Strings[63544]="酋长都慷慨允许死者家属住进他的城市了。为部落而死本就是无上的荣誉，可是你却只想趁机再捞一笔！"
D.Strings[63545]="你们让我恶心。瘦小，懦弱，像小偷一样不知廉耻，感谢酋长容忍你们存在吧！"
D.Strings[63546]="你在说什么，地精！？"
D.Strings[63547]="%s正准备发出一招强力的|cFFFF2222|Hspell:141187|h[竖劈]|h|r。"
D.Strings[63548]="暗矛部族的畜生都将卑贱地死去！"
D.Strings[63549]="暗矛部族根本不配加入部落！"
D.Strings[63550]="我要将你的脑袋献给加尔鲁什！"
D.Strings[63551]="你背叛了酋长！"
D.Strings[63552]="暗矛部族的同谋犯都将被处死！"
D.Strings[63553]="细剑掉在了地上。快将它捡起来以对付海军上将哈格曼！"
D.Strings[63554]="你要为自己对我的迅猛龙所做的一切付出代价！"
D.Strings[63555]="跟老波贝来！他认识路！"
D.Strings[63556]="一辆满载木材的库卡隆货车倾覆了！"
D.Strings[63557]="一辆满载原油的库卡隆货车倾覆了！"
D.Strings[63558]="一辆满载食用肉的库卡隆货车倾覆了！"
D.Strings[63559]="一辆满载石料的库卡隆货车倾覆了！"
D.Strings[63560]="这正是我们所需要的！"
D.Strings[63561]="小心！这可不是玩具！"
D.Strings[63562]="这或许将是我最伟大的作品！"
D.Strings[63563]="你是直接用手拿的？！呃……等我们回去之后，你最好去找个医生看看……"
D.Strings[63564]="啊，你正是我一直在期盼的那个$r。"
D.Strings[63565]="我想你是误解了我的兄弟，古伊尔。他可不是那种能被陌生人说服的人，尤其对方还是个小个子。"
D.Strings[63566]="霜狼氏族要想抵抗钢铁部落，就必须团结一致。我们得把贾纳尔和他的战士们找回来。"
D.Strings[63567]="我们跟贾纳尔和他的流亡者们失去联络有一段时间了，但我怀疑他们在北边。"
D.Strings[63568]="但我必须警告你，贾纳尔和他的战士们可不是和平离开的，所以不太可能张开双臂欢迎你的到来。我认为古伊尔的提议根本不可能实现。"
D.Strings[63569]="这还是让你自己来判断吧。现在，快出发吧，但愿你能证明我是错的。"
D.Strings[63570]="这是最重要的材料！"
D.Strings[63571]="这应该能提供足以废止稳定矩阵的能量。"
D.Strings[63572]="还需要一点能量……"
D.Strings[63573]="废止？！"
D.Strings[63574]="我的杰作完成了！"
D.Strings[63575]="它真是……太美了！"
D.Strings[63576]="见鬼，你要池塘小马干什么？"
D.Strings[63577]="不要质疑我的天才！"
D.Strings[63578]="我才不在乎它有什么用呢，它能打开这道门吗？"
D.Strings[63579]="我们在这里停留的越久，加尔鲁什的人就越有可能发现我们。"
D.Strings[63580]="这玩意儿连加里维克斯的私人保险箱都能打开！"
D.Strings[63581]="一旦炸药爆炸……呃……快跑！"
D.Strings[63582]="如果你不能尽快进入战斗，就将自动告负！"
D.Strings[63583]="酋长会生气的。他把宝贵的军队都拿来抵御那些可悲的起义军了。"
D.Strings[63584]="我没想到会有这么多军队……"
D.Strings[63585]="我以前也卷入过不少麻烦，但这也太荒唐了！"
D.Strings[63586]="我们只要专心执行任务就好，肯定能够全身而退的。"
D.Strings[63587]="你能让我再隐身一次吗？"
D.Strings[63588]="非常好——放下武器！"
D.Strings[63589]="我希望你能明白，缺乏指引的力量是狭隘的。改变世界是一回事，但做正确的事就是另一回事了。"
D.Strings[63590]="年轻的王子，希望你能记住这一课。"
D.Strings[63591]="呸！这场挑战不公平。"
D.Strings[63592]="我很高兴我们的英雄还活着。谢谢你的祝福，强大的白虎。"
D.Strings[63593]="不出我所料。你还想再来一次吗？"
D.Strings[63594]="停手。"
D.Strings[63595]="勇士，你应该利用敌人的力量和自信来对付他。我相信你。"
D.Strings[63596]="小心地摇动陈旧的海盗骰子。骰子滚出了|cFFFF2222|Hspell:141967|h[两点]|h|r。"
D.Strings[63597]="乌萨吉召唤一个元素前来助战！"
D.Strings[63598]="钟摆？！醒醒！"
D.Strings[63599]="这门连动都没动一下……"
D.Strings[63600]="下次早点提醒我们！"
D.Strings[63601]="%s开始对$n施放|cFFFF2222|Hspell:136473|h[回击]|h|r。"
D.Strings[63602]="冷静点儿！这根本算不上是火嘛！"
D.Strings[63603]="他还活着吗，蝾螈？"
D.Strings[63604]="他快死了，需要马上送医！"
D.Strings[63605]="沙砾百无聊赖地走开了。"
D.Strings[63606]="沙砾，快把紧急传送器架起来！我们得立即向沃金报告这里的情况。"
D.Strings[63607]="你休想逃出这些山洞！"
D.Strings[63608]="真正的部落，纯粹的部落，是不可阻挡的！"
D.Strings[63609]="下等种族的鲜血将染红整个艾泽拉斯。"
D.Strings[63610]="新兵，现在只有你还能战斗了！"
D.Strings[63611]="在传送器准备就绪前，保护好我们！"
D.Strings[63612]="|cFFFF0000|Hspell:141387|h[乌萨吉之盾]|h|r被击破了！"
D.Strings[63613]="这些箱子上有库卡隆的印记。山洞里摆满了各种武器和其他战略物资。从这些东西来看，加尔鲁什正在策划一场入侵。"
D.Strings[63614]="%s在你身上放置了|cFFFF2222|Hspell:132998|h[黏性炸弹]|h|r！"
D.Strings[63615]="山洞里整齐地码放着始祖龙蛋。周围散落着许多刚刚孵化的蛋。有了这么多始祖龙，加尔鲁什的入侵足以威胁到任何地方。"
D.Strings[63616]="这里放着许多遗物，似乎都已经被丢弃了。大部分好像都是来自加尔鲁什在锦绣谷的挖掘场。无论他想在那里找到什么，看来都不包括这些被遗忘的文物。"
D.Strings[63617]="沃金将长矛插入地下，沉默不语。"
D.Strings[63618]="酋长会让你们血流成河！"
D.Strings[63619]="我诅咒暗矛部族！"
D.Strings[63620]="誓死效忠地狱咆哮！"
D.Strings[63621]="你们休想打败库卡隆！"
D.Strings[63622]="我死而无憾！"
D.Strings[63623]="听听人民的呼声吧！"
D.Strings[63624]="你们休想夺走我们的部落！"
D.Strings[63625]="给库卡隆陪葬吧！"
D.Strings[63626]="地狱咆哮必将失败！"
D.Strings[63627]="我们要清除渣滓！"
D.Strings[63628]="为了沃金！"
D.Strings[63629]="我们沉默得太久了！"
D.Strings[63630]="地精小队，保护自己！"
D.Strings[63631]="疯狂的工兵激活了绑在胸口的炸弹！"
D.Strings[63632]="开启基础伤害（白银）试炼"
D.Strings[63633]="开启基础伤害（黄金）试炼"
D.Strings[63634]="开启基础伤害（无限）试炼"
D.Strings[63635]="下等？我们会让你看看谁才是下等种族！"
D.Strings[63636]="你最近有找到什么稀有卡牌吗？把它们带给我，我可以把它们加入我的藏品里去。"
D.Strings[63637]="我想买一张挑战卡牌。"
D.Strings[63638]="接下来这位，他无需刀剑与魔法就能打败敌人。我们的下一个挑战者，海克索斯，使用强大的几何之力克敌制胜的战士！"
D.Strings[63639]="虽然他就像是一只大公鸡，但他仍然要奋勇战斗。他就是，泰森·山德士！"
D.Strings[63640]="他有两种模式，每一种都被贴上了“屠夫”的标签。让我们欢迎，T440！"
D.Strings[63641]="但愿大家都喜欢自己的拳手特脆饼干！现在进场的是，硬煤！！"
D.Strings[63642]="还有什么能比一场大爆炸更刺激呢？那当然是，很多很多大爆炸！这边进场的是，大型雷震天！！"
D.Strings[63643]="噢……看看这条可爱的小蛇，噬人蛇！上啊，让它咬一口你的脚趾。让我们看看会发生什么事。"
D.Strings[63644]="他不是真正的医生，但他将要给他的下一个对手做点整容手术。让我们欢迎，铁拳医师！"
D.Strings[63645]="擦亮你的幸运符吧，你会用得上它的。接下来进场的是，老爹土笛子！"
D.Strings[63646]="接下来这对挑战者难以用语言来形容。就请大家自己好好欣赏吧，巨熊与淑女！"
D.Strings[63647]="扔掉你的武器，拿起拳套吧。接下来将有一场精彩的传统拳击赛。做好被泰塔尔击倒的准备吧！"
D.Strings[63648]="他可能是我们搏击俱乐部有史以来最危险的拳手。遗憾的是，他的元素好像有点不够用了。请大家举杯欢迎，锋齿！"
D.Strings[63649]="搏击俱乐部的老手们可能还记得那个能自我复制的软泥怪，布拉特。今天，我们将迎来他这位更卑鄙、更丑陋的姐姐：斯普拉特！"
D.Strings[63650]="这是谁啊？布鲁斯回来了！一个更好、更快、更强的布鲁斯！他就是，机甲布鲁斯！！！"
D.Strings[63651]="他是一位战略大师，他甚至都没有脑袋，也没有肘子。他就是，猜拳手！让我们为他拍拍手吧！"
D.Strings[63652]="想知道我们是怎么处理报废机器人的吗？当然是把他们送到血腥的竞技场来送死了！现在进场的是，布林顿3000！"
D.Strings[63653]="很高兴见到你，我的朋友。最近发生了太多事情，让我这样的游学者都觉得目不暇接了。我已经通过洄梦仙酒看到了许多事件，但我们还需要像你这样的英雄来帮忙书写新的历史篇章。"
D.Strings[63654]="这种令人口水直流的美酒散发着一股令人迷醉的香气。$b$b（下列场景战役要求物品等级不低于425级）"
D.Strings[63655]="青龙！请聆听我们的祈求。"
D.Strings[63656]="我和我的勇士希望得到智慧的祝福。"
D.Strings[63657]="查看绝版挑战者的战斗记录。"
D.Strings[63658]="查看特殊挑战者的战斗记录。"
D.Strings[63659]="查看特殊挑战者的战斗记录（第2页）。"
D.Strings[63660]="$g他:她;可是我们搏击竞技场最精锐的9级拳手之一：$n！"
D.Strings[63661]="欢迎我们所向披靡的10级冠军拳手，$N！"
D.Strings[63662]="为了大义而不惜代价。这就是智慧。"
D.Strings[63663]="面对大义而无所作为，何时成了智慧？"
D.Strings[63664]="啊，巨龙之子和他的英雄。你们俩必将成就伟大的事业。"
D.Strings[63665]="告诉我，巨龙之子：什么是智慧？"
D.Strings[63666]="这口气真像巨龙的后裔。总想着改变世界。"
D.Strings[63667]="但真正的智慧源于了解何为大义。有时，无为也是种智慧。"
D.Strings[63668]="当你领悟真正的智慧之时。"
D.Strings[63669]="来吧！我将给你们我的祝福。"
D.Strings[63670]="我的挑战，如果你们接受的话，将测试你们在遭到生命危险时的机智和手段。"
D.Strings[63671]="小心地摇动陈旧的海盗骰子。骰子滚出了三点，使其受到|cFFFF2222|Hspell:141962|h[坏血病]|h|r的影响。"
D.Strings[63672]="小心地摇动陈旧的海盗骰子。骰子滚出了四点，一队骷髅海盗伏击了他！"
D.Strings[63673]="小心地摇动陈旧的海盗骰子。骰子滚出了四点，一队骷髅海盗伏击了她！"
D.Strings[63674]="小心地摇动陈旧的海盗骰子。骰子滚出了五点，使其受到|cFFFF2222|Hspell:142037|h[黑暗标记]|h|r的影响。"
D.Strings[63675]="小心地摇动陈旧的海盗骰子。骰子滚出了六点，引发了一次|cFFFF2222|Hspell:142058|h[火炮弹幕]|h|r攻击。"
D.Strings[63676]="小心地摇动陈旧的海盗骰子。骰子滚出了七点，什么都没有发生。"
D.Strings[63677]="小心地摇动陈旧的海盗骰子。骰子滚出了八点，使其获得了|cFF3366FF|Hspell:141968|h[海盗之赐]|h|r。"
D.Strings[63678]="小心地摇动陈旧的海盗骰子。骰子滚出了九点，使其获得了|cFF3366FF|Hspell:142107|h[厚皮]|h|r效果。"
D.Strings[63679]="小心地摇动陈旧的海盗骰子。骰子滚出了十点，召来一个骷髅海盗协助其作战。"
D.Strings[63680]="小心地摇动陈旧的海盗骰子。骰子滚出了十一点，使其获得了|cFF3366FF|Hspell:142061|h[被诅咒的海盗骰子]|h|r。"
D.Strings[63681]="小心地摇动陈旧的海盗骰子。骰子滚出了十二点，使其所有船员获得了|cFF3366FF|Hspell:142140|h[海盗传说]|h|r效果。"
D.Strings[63682]="开始挑战吧！英雄，你要在战斗中击败黑王子。"
D.Strings[63683]="你，黑王子，将被蒙上眼睛。"
D.Strings[63684]="我们将会看到，失去指引的力量会有怎样的局限。"
D.Strings[63685]="利用你的移动优势。别让巨龙之子靠近。"
D.Strings[63686]="注意周围的环境。"
D.Strings[63687]="别让元素缠住你！"
D.Strings[63688]="我掌握着泰坦的传奇力量！"
D.Strings[63689]="站住！我正要杀了你呢！"
D.Strings[63690]="你去哪儿？回来。"
D.Strings[63691]="啊……哈！"
D.Strings[63692]="你该庆幸我不是绿龙，他们闭着眼睛都能看见东西。"
D.Strings[63693]="停手！"
D.Strings[63694]="勇士，你要预判敌人的动作，并始终抢先一步。胜利就在你手中！"
D.Strings[63695]="很好——停手！"
D.Strings[63696]="看到了吗？缺乏指引的力量只会带来混乱和毁灭。"
D.Strings[63697]="我很高兴我们的英雄还活着。谢谢你的祝福，伟大的青龙。"
D.Strings[63698]="开始挑战吧！英雄，你要用治疗技能保证黑王子的生命。"
D.Strings[63699]="是吗？你心中充满了疑虑和恐惧，年轻的王子。"
D.Strings[63700]="你从未真正接受你的过去。现在是时候了。"
D.Strings[63701]="你的勇士会保证你的生命。开始！"
D.Strings[63702]="我可是黑龙。我不需要帮助。"
D.Strings[63703]="什么——等等——父亲！？"
D.Strings[63704]="不——不要逼我。"
D.Strings[63705]="我要将这世界撕成碎片！"
D.Strings[63706]="治疗王子，但也别忘了保护自己的安全！"
D.Strings[63707]="不要错过任何治疗黑王子的机会。"
D.Strings[63708]="阴影散开了！"
D.Strings[63709]="保持移动。敌人很危险，但你更聪明。"
D.Strings[63710]="使用世界之血治疗你自己。你能做到。"
D.Strings[63711]="不要害怕陷阱。你的治疗比他的法术更强大！"
D.Strings[63712]="你们的顽强令我赞叹，但毫无价值。"
D.Strings[63713]="谁都逃不过我的怒火！"
D.Strings[63714]="你的护甲毫无作用，你的信仰一文不值！"
D.Strings[63715]="够了！快停下！"
D.Strings[63716]="很好。试炼结束。"
D.Strings[63717]="但是，不要绝望。你有克服它的能力。再试一次——我相信你！"
D.Strings[63718]="很好！你成功了！"
D.Strings[63719]="不要绝望，年轻的王子。你不是你父亲。"
D.Strings[63720]="更重要的是，你的勇士不会让你倒下。明白吗？在朋友的支持下，一切皆有可能。"
D.Strings[63721]="太……疯狂了……"
D.Strings[63722]="我明白了。谢谢你，朱鹤。"
D.Strings[63723]="开始挑战吧！英雄，你必须在黑王子面对心魔的时候保护他。"
D.Strings[63724]="面对你的心魔吧，现在是时候了。"
D.Strings[63725]="你的勇士会保护你的。开始！"
D.Strings[63726]="控制战斗。注意你所有的敌人。"
D.Strings[63727]="利用战场对自己进行恢复。"
D.Strings[63728]="保护黑王子！引开他的敌人！"
D.Strings[63729]="不要让你的敌人完成攻击。"
D.Strings[63730]="为了不让王子倒下，你必须牺牲自己！"
D.Strings[63731]="好吧，试炼结束了。"
D.Strings[63732]="记住：除非甘心放弃，否则没有人能够击败你。真正坚忍的人总能在跌倒后爬起来。"
D.Strings[63733]="再来——我知道你们是可以的！"
D.Strings[63734]="你有朋友。你的勇士不会让你倒下。牢牢记住这一课吧。"
D.Strings[63735]="你比你的父亲更强大，年轻的王子。"
D.Strings[63736]="干得好！你们胜利了！"
D.Strings[63737]="我明白了。谢谢你，玄牛。"
D.Strings[63738]="$n将联盟运金车送回了基地！"
D.Strings[63739]="联盟运金车被送回了基地！"
D.Strings[63740]="$n将部落运金车送回了基地！"
D.Strings[63741]="%s正准备施放|cFFFF0000|Hspell:142111|h[瓦解咆哮]|h|r！"
D.Strings[63742]="部落运金车被送回了基地！"
D.Strings[63743]="蠢货！你们这些人在正统部落面前不堪一击。"
D.Strings[63744]="传送器准备就绪！让我们离开这儿！"
D.Strings[63745]="那些库卡隆正在集结。"
D.Strings[63746]="很快，那些库卡隆就会像潮水一样涌上山头。"
D.Strings[63747]="你会帮我们的，对吧？$c？"
D.Strings[63748]="你是来参加起义的吗，伙计？"
D.Strings[63749]="欢迎加入起义军。"
D.Strings[63750]="这次，那些库卡隆休想再偷袭我们了。"
D.Strings[63751]="我也有一些很好的兽人朋友。这世道太糟糕了。"
D.Strings[63752]="我们暗矛部族会做好准备的。"
D.Strings[63753]="你真是起义军的宝贵财富。现在，我们已经武装起来了。"
D.Strings[63754]="我还以为，你肯定会被穿在它的毒针上……"
D.Strings[63755]="我知道你是来干什么的，小崽子。我应该把你宰掉，扔在这里让秃鹫啃食，当做给我那个废物哥哥的警告。"
D.Strings[63756]="但我需要你帮我转达一个更重要的口信。"
D.Strings[63757]="我和我的人准备去戈隆岩窟，拿那里的戈隆开刀。"
D.Strings[63758]="如果你能驯服一头霜狼以证明自己的实力，那我可以带上你，让你做个见证。"
D.Strings[63759]="等这件事结束之后，我们再来谈谈我那个废物哥哥的要求。"
D.Strings[63760]="杜隆坦自封为领袖，并顶着这个头衔诱骗族人追随他。"
D.Strings[63761]="可杜隆坦既软弱又无能。他没有领导霜狼氏族的力量。"
D.Strings[63762]="他在这个季节之初带着我们来到这片北方家园，逃出位于纳格兰的新兽人氏族。他让我们的族人背上了懦夫之名。"
D.Strings[63763]="他将我们的食物浪费在他那个体弱多病的妻子，德拉卡身上，而不是按照传统，将弱者送进寒冷的冰原。"
D.Strings[63764]="他拒绝带领我们的战士讨伐戈隆，为我们的父亲报仇，还胡说什么没有人手。"
D.Strings[63765]="杜隆坦一次次表现出他的软弱，并唾弃我们的祖先流传下来的力量。"
D.Strings[63766]="现在，我们就要出发去为我的父亲复仇，并提醒整个霜狼氏族，真正的酋长应该如何行事。"
D.Strings[63767]="你将见证这次行动。如果你能活下来，你要把我今天的所作所为告诉我的哥哥和他的氏族。"
D.Strings[63768]="雷神氏族。我的斥候报告说他们就在这片绿洲里活动，截断了通往岩洞的道路。"
D.Strings[63769]="我们要引出他们的头领，将他的脑袋穿在矛尖上，然后杀掉所有挡路的家伙。"
D.Strings[63770]="出来吧，格拉图尔！我要在你的手下面前挑战你。我会在他们眼皮底下把你开膛破肚！"
D.Strings[63771]="我要对着你的尸体吐口水，兽人。你这废物！"
D.Strings[63772]="伙计们，杀光他们！一个不留！"
D.Strings[63773]="当霜狼氏族中的强者要证明自己领导氏族的能力时，他们就会带着精心挑选的战士来到这里，并带着新砍下来的戈隆脑袋返回氏族。"
D.Strings[63774]="我父亲曾带着这样一支队伍前来讨伐上古戈隆科洛克，却一去不返。"
D.Strings[63775]="今天，我要完成我父亲未竟的事业，并举起他的长矛和盾牌来祭悼他。我要提醒族人，真正的霜狼酋长应该做些什么。"
D.Strings[63776]="你们就是这么拿武器的？任何一个合格的库卡隆都能轻而易举地把你们缴械了。"
D.Strings[63777]="你还活着。我想这是一个好兆头。"
D.Strings[63778]="我们将要面对库卡隆。他们是全部落最卑鄙、最混账的兽人。你们最好别在训练中打瞌睡。"
D.Strings[63779]="记住！库卡隆必须用战斧开刃的那一面来攻击你。而你们的钉锤却没有这种限制。"
D.Strings[63780]="来竞技场找我吧。你在这件事中扮演了重要角色。你有资格看到它最后的结果。"
D.Strings[63781]="你们管这叫战吼？我们即将发动起义。你们要像胜利者那样咆哮，让另一方摸不着头脑。"
D.Strings[63782]="趁现在敌人还不多，大家快离开这儿！"
D.Strings[63783]="我会一直守到最后一个地精离开为止！我们在集合点见！"
D.Strings[63784]="年轻的王子，请记住这一课。"
D.Strings[63785]="停下，这些联盟恶棍爬到我们船上来了。去解决他们！"
D.Strings[63786]="%s交给你一条爬绳。"
D.Strings[63787]="跟我走，$c。沃金一会儿要见你。"
D.Strings[63788]="那位“酋长”还以为沃金死了，被他的库卡隆刺客暗杀于昆莱山。"
D.Strings[63789]="沃金侥幸逃过一死，但他不会忘记地狱咆哮的背叛所带来的伤痛。暗矛不死。"
D.Strings[63790]="在他回归之后，我发现他变了。他的眼中燃烧着变革的光辉！"
D.Strings[63791]="现在，看看你的周围吧。暗矛起义军正在壮大。它将成为地狱咆哮的噩梦。"
D.Strings[63792]="星星之火可以燎原。我们将一路延烧至奥格瑞玛的大门前。"
D.Strings[63793]="但我们必须为这架战争机器提供补给。石料、木材、原油和肉食——我们需要大量物资。"
D.Strings[63794]="这就是我们要用到你的地方了，$G兄弟:姐妹;。"
D.Strings[63795]="去吧，去跟沃金谈谈。你要做好准备。从现在起，我们对你的要求会比过去更高。"
D.Strings[63796]="部落快要爬上来了！快去甲板上帮忙御敌！"
D.Strings[63797]="我必须这么做。但是，如果我死了，请照顾好阿格娜和我儿子。"
D.Strings[63798]="你做的很好，$n。看来部落内部已经矛盾重重了。加尔鲁什有一整支巨魔起义军要对付了。"
D.Strings[63799]="这么说传言是真的？沃金还活着，并回来向加尔鲁什复仇了？"
D.Strings[63800]="没错。这正是联盟的大好机会。我们要利用巨魔为联盟主舰队的集结打掩护。你明白我的意思吧，苏利？"
D.Strings[63801]="等等！你是想让我们去帮助沃金吗？"
D.Strings[63802]="沃金已经没有退路了。有了我们的帮助，他就能成为破开地狱咆哮堡垒的那把“暗矛”。就让我们的敌人去自相残杀吧，我们只需在一边等待出击的机会即可。"
D.Strings[63803]="多聪明的姑娘！煽风点火！我喜欢这主意。那么，我们中有哪个勇士敢去拜访一下暗矛部族呢？"
D.Strings[63804]="不会吧！"
D.Strings[63805]="看呐，伙计，又是从塞拉摩来的联盟渣滓。干掉它！"
D.Strings[63806]="等等！放下你们的武器。我认识这个家伙。"
D.Strings[63807]="去告诉沃金，我带来了一位来自联盟的特使。"
D.Strings[63808]="跟我走，$r。"
D.Strings[63809]="别让你的手离开我们的视线。最近大家都有些神经质。我们正在进行一场战争，一场与酋长本人的战争。"
D.Strings[63810]="地狱咆哮已经派人来刺杀过沃金了。呵呵，巨魔可不是那么容易杀死的。"
D.Strings[63811]="你问他干了什么？他激起了整个暗矛部族的怒火。"
D.Strings[63812]="地狱咆哮本以为沃金已经死了，结果他却出现在森金村。然后酋长又试图绞杀起义军，但我们早有准备。我们已经在森金村击退了库卡隆，然后又攻占了剃刀岭。哈，就在酋长的鼻子底下打了个大胜仗！"
D.Strings[63813]="现在，我们已经将目光投向了最终的战场——奥格瑞玛。"
D.Strings[63814]="联盟想在奥格瑞玛开辟第二战线？可以。你们需要帮助，而我们需要物资：石料、木材、原油和肉食。只有这样，我们才有可能去攻打那座坚城。"
D.Strings[63815]="这个任务可不适合胆小鬼，陌生人。但如果你帮助我们，沃金或许会慢慢信任你们。无论如何，你们总能削弱酋长对他自己领土的控制力。软趴趴的联盟能做到这一点吗？啊哈哈哈哈！"
D.Strings[63816]="|TInterface\\Icons\\ability_deathknight_remorselesswinters:20|t%s召唤了一个|cFFF00000|Hspell:142320|h[冰川冻气图腾]|h|r！"
D.Strings[63817]="|TInterface\\Icons\\spell_fire_windsofwoe:20|t%s开始施放|cFFF00000|Hspell:142306|h[毁弃之土]|h|r！"
D.Strings[63818]="成功了，英雄！我们得到了至尊天神的祝福，完成了他们的挑战。"
D.Strings[63819]="我知道接下来该怎么做。回石匠之愚来找我——我为你准备了一个惊喜！"
D.Strings[63820]="嘿嘿嘿！你想快速前往贫瘠之地吗？"
D.Strings[63821]="你要去其他地方吗？如果那个“其他地方”是棘齿城，那我马上就能给你开辟一条快速通道！"
D.Strings[63822]="顾客满意度百分之百！今天就来试试跳闸旅行社的服务吧！"
D.Strings[63823]="我的高新传送器可以将你直接送往北贫瘠之地。想试试吗？"
D.Strings[63824]="我要去棘齿城。"
D.Strings[63825]="很好，过来吧，$r，站到传送器上来。"
D.Strings[63826]="走走走！到那个传送器上去。今天的客人很多，所以请你快一点！"
D.Strings[63827]="站到那个传送器上去。棘齿城，马上就到！"
D.Strings[63828]="加尔鲁什手下的恶棍不让我继续跟巨魔合作了。"
D.Strings[63829]="酋长把所有不同政见者都关押了起来，包括我们兽人！"
D.Strings[63830]="我从没想过加尔鲁什会对兽人下手！"
D.Strings[63831]="现在我明白暗矛部族为什么会反抗了！"
D.Strings[63832]="用你的身体为拉希奥挡住攻击！"
D.Strings[63833]="青龙是潘达利亚的智慧化身。我们来看看她会怎么说吧。"
D.Strings[63834]="死亡之翼的幻影锁定了拉希奥，快嘲讽他！"
D.Strings[63835]="我的仆从们，消灭这些爬虫！"
D.Strings[63836]="你已经拥有这件神器了！重置组合链……"
D.Strings[63837]="这些部落狗要爬上来了。击退他们！"
D.Strings[63838]="这些联盟猪要爬上来了。击退他们！"
D.Strings[63839]="这些恶棍要爬上来偷我们的财宝了。击退他们！"
D.Strings[63840]="又有人上来了。挡住他们！"
D.Strings[63841]="敌方上尉要登船了，击退他！"
D.Strings[63842]="我们把他们赶回自己船上去了。快跳过去，偷走他们的炸药，把他们的船炸成碎片！"
D.Strings[63843]="总算狠狠教训了他们！现在，跳进那座火炮里去，集中瞄准他们的旗舰！"
D.Strings[63844]="让我们看看这玩意儿有什么用吧！"
D.Strings[63845]="停下，这些部落恶棍爬到我们船上来了。去解决他们！"
D.Strings[63846]="停下，这些恶棍爬到我们船上来了。去解决他们！"
D.Strings[63847]="当时我们正在这里对付这堵墙，然后……额，我不记得了。那么，你是谁？轮滑去哪儿了？"
D.Strings[63848]="一切都很好。你瞧，要解释起来话可就长了……"
D.Strings[63849]="那么，警报解除了吗？"
D.Strings[63850]="这炸药可真够劲！我们进去检查一下吧。"
D.Strings[63851]="看起来像某种巨型箱子……可能还装满了金币。全归我们啦！"
D.Strings[63852]="出……什么事了？我脑子里……有某种……东西……"
D.Strings[63853]="要是不能挽回在这次灾难中造成的损失，那我就要变成穷光蛋了。"
D.Strings[63854]="帮帮我这个可怜的地精，为我收集一些珍贵遗物吧。与此同时，我的人会去清理矿洞入口的。"
D.Strings[63855]="不能再浪费时间了……让我们把这堵墙炸成碎片吧！"
D.Strings[63856]="你休想用那套猫皮伪装骗过老岑塔布拉。我会记住你的，$r。"
D.Strings[63857]="逃跑的机会来了。快跑啊！"
D.Strings[63858]="联盟愿意帮助暗矛部族？我从未想过自己能活着看到这一天。"
D.Strings[63859]="我要感谢你，$r。我不会忘记你所做的一切。"
D.Strings[63860]="拉希奥停止呼吸倒在了地上，他被击败了！"
D.Strings[63861]="一辆准备驶出无水岭的联盟货车需要护送。"
D.Strings[63862]="发现入侵者！守住雷霆熔炉！"
D.Strings[63863]="雷霆熔炉是我们的！我们要用生命来捍卫它！"
D.Strings[63864]="拉兹·疯线召唤疯狂的工兵！"
D.Strings[63865]="一辆准备驶出遗忘之池的联盟货车需要护送。"
D.Strings[63866]="一辆准备驶出鬼雾峰的联盟货车需要护送。"
D.Strings[63867]="一辆准备驶出淤泥沼泽的联盟货车需要护送。"
D.Strings[63868]="一辆准备驶出哀嚎洞穴的联盟货车需要护送。"
D.Strings[63869]="一辆准备驶出死水绿洲的联盟货车需要护送。"
D.Strings[63870]="一辆准备驶出荆棘岭的联盟货车需要护送。"
D.Strings[63871]="一辆联盟货车已被摧毁。"
D.Strings[63872]="暗矛部族绝不放弃！"
D.Strings[63873]="暗矛部族将终结你的生命！"
D.Strings[63874]="加尔鲁什必将付出代价！"
D.Strings[63875]="这只是刚刚开始！"
D.Strings[63876]="暗矛部族将摧毁加尔鲁什！"
D.Strings[63877]="死亡之翼的幻影锁定了拉希奥，快为他治疗！"
D.Strings[63878]="一名库卡隆指挥官出现在了战场上。"
D.Strings[63879]="万灵非常不安。"
D.Strings[63880]="<沃金的临时义军营地里散发着令人难以忍受的恶臭。巨魔首领示意你先开口，而他的护卫们则警惕地盯着你。>"
D.Strings[63881]="暗矛部族为什么要反叛加尔鲁什？"
D.Strings[63882]="地狱咆哮呢？部落对他来说意味着什么？"
D.Strings[63883]="我们为什么要帮助你？要是我们把贫瘠之地的补给都留给自己又会怎样？"
D.Strings[63884]="<沃金的脸愤怒地扭曲了起来。>$b$b你不明白。部落在你们眼里是什么？嗯？一群病夫？怪胎？叛徒？魔崽子？野兽？我知道你们是怎么说我们的。$b$b我来告诉你们部落是什么。部落是我和萨尔一手建立起来的。它是一个大家庭。当全世界都试图消灭我们时，这个家庭向我们伸出了援手。$b$b而地狱咆哮，他不懂这个家庭的意义。所以他也得不到家人的支持。"
D.Strings[63885]="对他来说，部落的全部意义便是兽人，以及如何壮大兽人的力量。他就像是刚刚穿过黑暗之门。任何挡他路的人，任何与他意见相左的人，都得闭嘴。$b$b<沃金用只有三根手指的手摸了摸身上的刀疤。>$b$b他就像一条疯狗。噢，没错，我是与地狱咆哮并肩战斗过。但要让他来掌管一切？你简直是在自找麻烦。他热衷于搞自己的小团体，发动他自己的战争，将我们这些老兄弟丢在一边……他觉得自己用不着任何人帮忙。但是，他错了。$b$b他会明白：一个人永远无法与这个大家庭对抗。"
D.Strings[63886]="<沃金笑了起来，带着恶臭的灼热呼吸直往你的鼻孔里钻。>$b$b噢，你有其他方案？我这儿正好也有一个备用方案。我就让你们自己去围攻奥格瑞玛。看看你们能打成什么样。等到城里堆满了尸体时，我再派出暗影猎手攻进去，干掉剩下的人，包括库卡隆和联盟，然后把你们的死者交给希尔瓦娜斯。哼！这么一来，我还可以保住许多暗矛部族同胞的性命。$B$B嗯？你不喜欢这个方案？那我们还是来谈谈第一个方案吧。我们合作。$b$b这并不需要我们喜欢彼此。"
D.Strings[63887]="你在潘达利亚发生了什么事？"
D.Strings[63888]="加尔鲁什知道你还活着吗？"
D.Strings[63889]="你为什么要反抗我们自己的酋长？"
D.Strings[63890]="你对部落怎么看？"
D.Strings[63891]="<沃金用只有三根手指的手摸了摸身上的刀疤。>$b$b这就说来话长了，朋友。加尔鲁什的匕首差点要了我的命。他的刺客割破了我的喉咙，把我扔在那儿等死。等我拼命爬出洞穴时，已经连话都说不出来了。是陈·风暴烈酒找到了我，把我从死亡的边缘拉了回来。$b$b我们一同前往影踪禅院，在他们的帮助下，我进行了一次深刻的自省。我看清了自己的立场，部落的立场。我的父亲……$b$b那时，我就下定了决心。我要不惜一切代价将部落夺回来。$b$b暗矛不死。"
D.Strings[63892]="<沃金愁苦的脸上露出一个冷酷的笑容。>$b$b他还不知道。他可能已经听到了一些流言，也许还想到那些鬼故事，以为老沃金的鬼魂回来纠缠他了。哈。$b$b但他很快就会知道的。真想看看当他听到老沃金回来兑现诺言时，那张绿豆眼的肥脸上会是什么表情。我要终结他那可悲的统治，射穿他的黑心。"
D.Strings[63893]="你还管他叫“酋长”吗，$c？他还是你的酋长吗？你怎么看他的战争带来的破坏？我看你并没有像他的库卡隆一样富裕幸福。他的部落只是兽人的部落。你觉得这里还欢迎你吗，$r？他的计划里有你的位置吗？当他有了新计划时，会不会直接把你当成垃圾一样处理掉？他承诺带来荣耀，却让我们的部落血流成河，并践踏一切与他意见相左的人。$b$b你知道我怎么看部落吗？我和萨尔建立起来的那个部落？"
D.Strings[63894]="部落是一个大家庭。当全世界都试图消灭我们时，这个家庭会我们伸出援手。你明白吗？我们彼此依靠。$b$b而地狱咆哮，他不懂这个家庭的意义。所以他也得不到家庭的支持。他眼里只有力量，和他刚通过传送门时一样。$b$b<沃金凝视着远方。>$b$b我们要起来反抗他——就在此时此地，我们要团结一致——否则，就会被他碾碎。各个击破。我身上的疤痕已经证明了这一点。$b$b你要相信谁，$n？你究竟忠于谁？地狱咆哮？还是部落这个大家庭？"
D.Strings[63895]="你还管他叫“酋长”吗，$c？他还是你的酋长吗？你怎么看他的战争带来的破坏？我看你并没有像他的库卡隆一样富裕幸福。$b$b看看吧，你是兽人，或许你还没有看明白这一点。奥格瑞玛里的贫民窟。他说起其他种族时的语气。他把他们当成炮灰试用的做法。你是他那少数选民中的一份子吗，$n？还是一个垃圾，就像我们其他人一样？一个等他达成那可怕的目标后，就会被丢在一旁的垃圾。他承诺带来荣耀，却让我们的部落血流成河。$b$b我和萨尔，我们的眼中的部落是完全不同的。"
D.Strings[63896]="很多年以前，我帮忙在这片沙漠上建起了部落。唉……时代真的不同了。"
D.Strings[63897]="你在这里做什么，陈·风暴烈酒？"
D.Strings[63898]="$n！真没想到，居然能在离潘达利亚的葱郁森林这么远的地方见到你。$b$b许多年前，当我第一次乘船离开迷踪岛时，这片怪石嶙峋的海滩是我最先造访的几个地方之一。啊！这里的空气还是这个味儿！$b$b但时代不同了。那时，我帮助萨尔、沃金、雷克萨和洛坎为奥格瑞玛打下了基石。今天，我差点就认不出这地方了。$b$b<陈的脸沉了下来。>$b$B太多毫无意义的流血牺牲了。我真不明白。潘达利亚给我们的教训还不够吗？"
D.Strings[63899]="拉希奥的眼睛被蒙上了，从他背后攻击可造成额外的伤害！"
D.Strings[63900]="你最好滚远点，笨蛋。霍夫可不是好惹得！"
D.Strings[63901]="姆格！快过来！霍夫被袭击啦！"
D.Strings[63902]="霍夫……完了……"
D.Strings[63903]="你休想逃出霍夫的手心！"
D.Strings[63904]="女士们，现在是火箭时间！来尝尝我的厉害吧！"
D.Strings[63905]="噢，这种行为可不好，伙计。非常不好。"
D.Strings[63906]="我会在祭坛那里等你的，勇士。"
D.Strings[63907]="记住，我们要拜访所有四个祭坛，但只要完成一个挑战就够了。"
D.Strings[63908]="所以，选择最适合你天赋的挑战吧。"
D.Strings[63909]="嘭！轰！啊哈哈哈哈！"
D.Strings[63910]="$n掠夺了联盟运金车！"
D.Strings[63911]="$n掠夺了部落运金车！"
D.Strings[63912]="始祖龙幼崽从附近的龙蛋中孵化出来了！"
D.Strings[63913]="灰烬！冒烟的火山口！啊哈哈哈哈！"
D.Strings[63914]="看来我的导火索……烧到头了……"
D.Strings[63915]="我的小伙子们也许不是最聪明的，但我们可以把你们全干掉！"
D.Strings[63916]="受不了我们的火爆脾气了，嗯？！"
D.Strings[63917]="死从天降！"
D.Strings[63918]="炸……成……碎片……"
D.Strings[63919]="鲜血与雷鸣！挑战者，你的死期到了！"
D.Strings[63920]="哈！一个挑战者？！"
D.Strings[63921]="闪开！"
D.Strings[63922]="真遗憾。我还没打过瘾呢。"
D.Strings[63923]="终于有个像样的对手了。"
D.Strings[63924]="鲜血的味道。只有卑微的蝼蚁才会害怕战斗。"
D.Strings[63925]="这家伙。干掉他一定会很有趣的。"
D.Strings[63926]="心跳停止！"
D.Strings[63927]="幸福地死去吧。"
D.Strings[63928]="终于……可以安息了……"
D.Strings[63929]="快回去干活，你们这些可悲的畜生！一小撮叛徒和联盟懦夫阻挡不了我们！"
D.Strings[63930]="你或许能闯过那些懦夫的拦截。但你休想闯过我这关。"
D.Strings[63931]="让它下吧！"
D.Strings[63932]="太弱了，就和我预料的一样。"
D.Strings[63933]="你怎么可能……打败我？"
D.Strings[63934]="我要碾碎所有胆敢反抗酋长的家伙！"
D.Strings[63935]="有敌人！碾碎他们！"
D.Strings[63936]="我要砸扁你！"
D.Strings[63937]="我是所向无敌的。"
D.Strings[63938]="小心背后……"
D.Strings[63939]="多么愚蠢。"
D.Strings[63940]="但愿你喜欢疼痛。"
D.Strings[63941]="哼。轻而易举。"
D.Strings[63942]="呵呵……呵……呵……"
D.Strings[63943]="哇哈哈哈哈！"
D.Strings[63944]="唔……"
D.Strings[63945]="哈……哈……"
D.Strings[63946]="这个世界将在酋长的力量下燃烧！"
D.Strings[63947]="再往火里添点儿柴。"
D.Strings[63948]="别被烧焦了……"
D.Strings[63949]="唔，一股烧焦的肉味儿……"
D.Strings[63950]="只要我一开口，整个海洋都将颤栗。恐惧吧，地狱咆哮之敌。"
D.Strings[63951]="我要把你冲到海里去。"
D.Strings[63952]="水流都臣服于我！"
D.Strings[63953]="溺死在你的失败中吧。"
D.Strings[63954]="我将被冲刷殆尽……"
D.Strings[63955]="让大地吞没你！"
D.Strings[63956]="这些家伙想要回归大地的怀抱……"
D.Strings[63957]="回到大地中去吧，懦夫。"
D.Strings[63958]="我……完了……"
D.Strings[63959]="我们会掩护你们，射杀你们指定的目标。"
D.Strings[63960]="地核蜘蛛从熔岩中爬出来了！"
D.Strings[63961]="神枪手凯尔握紧了手中的枪。"
D.Strings[63962]="你和苏利来这里做什么？"
D.Strings[63963]="国王陛下不想让加尔鲁什继续他那疯狂的战役了。它已经吞噬了太多无辜的生命。$b$b我们是来寻找奥格瑞玛的防线弱点的，那种能够为联盟部队所用的弱点。$b$b不幸的是，加尔鲁什显然也没闲着。他已经加快了库卡隆的征兵速度，并将他们变成了彻头彻尾的战争机器。"
D.Strings[63964]="他们原本是一支由精锐兽人组成的卫队，负责保护酋长的安全并执行他的命令。$b$b而现在，他们变成了一支由训练有素的屠夫组成的军队，加尔鲁什的私人军队。"
D.Strings[63965]="库卡隆是什么？"
D.Strings[63966]="但愿这只隐身小鸡不会出什么岔子。她最近不太对劲。"
D.Strings[63967]="再跟我说说国王与议会的故事吧……"
D.Strings[63968]="我好像看见一些带着镣铐的巨魔被押走了。兽人为什么要给巨魔戴镣铐，还要押着他们走呢？"
D.Strings[63969]="藏身于敌军腹地，只靠这只隐身小鸡来保护我们。这已经变成我最新的日常工作了！"
D.Strings[63970]="再跟我说说酋长与黑暗的故事吧……"
D.Strings[63971]="部落带回来一只猢狲？！他们在潘达利亚还没有受够那些家伙吗？"
D.Strings[63972]="我以前从没在一个地方见过那么多库卡隆！$b$b那些兽人总是又暴躁又愤怒。他们肯定扩大了征兵规模。"
D.Strings[63973]="C4T计划是从哪儿来的？"
D.Strings[63974]="老靴子？！它可是我的杰作。自从袜子死后，愿它安息，我需要一个更加耐用的小伙伴。$b$b都是安玻想出来要用它来执行这个任务的，所以你千万别把它炸坏了！"
D.Strings[63975]="纳拉利死不足惜！"
D.Strings[63976]="欢迎回来，英雄！"
D.Strings[63977]="你表现得很好。没想到至尊天神居然都这么啰嗦。"
D.Strings[63978]="我以为他们会给我们奖励，结果他们一直唠叨个不停。"
D.Strings[63979]="抱歉——我们说到哪儿了？噢，对了！我有东西要给你："
D.Strings[63980]="潘达利亚的诸神支持着我们伟大的事业！看看吧："
D.Strings[63981]="白虎之力。"
D.Strings[63982]="青龙之智。"
D.Strings[63983]="玄牛之韧。"
D.Strings[63984]="还有朱鹤的，对一个更美好世界的希望寄托！"
D.Strings[63985]="我们的世界。"
D.Strings[63986]="瞧！它近在咫尺。"
D.Strings[63987]="护送车队以获取额外的库卡隆补给品！"
D.Strings[63988]="击败敌方指挥官以获取额外的库卡隆补给品！"
D.Strings[63989]="联盟要登船了！快到甲板上去，为荣耀而战吧！"
D.Strings[63990]="如果你想接受挑战，就去敲响挑战之锣吧。否则，我们就到此为止吧。"
D.Strings[63991]="拍打酒桶"
D.Strings[63992]="灰烬之核从熔岩中苏醒了！"
D.Strings[63993]="嘿，你不是那只臭山羊！你找基尔里克做什么？"
D.Strings[63994]="干掉这些联盟渣滓！为了部落！"
D.Strings[63995]="滚开，乡巴佬！"
D.Strings[63996]="酋长在召唤。"
D.Strings[63997]="真正的部落将统治全艾泽拉斯。"
D.Strings[63998]="托托开始生气地吠叫起来！"
D.Strings[63999]="我们胜利了！快到火炮那里去，加强攻势！"
D.Strings[64000]="我还没有全部完成。这件斗篷能带给你至尊天神的力量。"
D.Strings[64001]="用不了多久，我们就能用我强大的巨龙之力强化你的斗篷了。"
D.Strings[64002]="继续帮助你的盟友作战吧。我稍后再联络你！"
D.Strings[64003]="先知昊梵舟将爬绳的一端交到你手中。将它绑在下一个绳锚上，帮助昊梵舟爬上山顶！"
D.Strings[64004]="$C！这里挤满了库卡隆。帮我们个忙吧？"
D.Strings[64005]="最后一个也拿到了！快到船底去，放下这些炸药！"
D.Strings[64006]="接下来这位，他无需刀剑与魔法就能打败敌人。我们的下一位挑战者，海克索斯，使用强大的几何之力克敌制胜的战士！"
D.Strings[64007]="还有什么能比一场大爆炸更刺激呢？那当然是很多很多大爆炸啦！这边进场的是，大型雷震天！！"
D.Strings[64008]="这是谁啊？布鲁斯回来了！一个更好、更快、更强的布鲁斯！他就是，机甲布鲁斯！！耶！！！"
D.Strings[64009]="像龙鹰一样漂移，像蝎子一样蜇人！"
D.Strings[64010]="没错，伙计！我是最强的拳手！"
D.Strings[64011]="每个人都有自己的小心思，直到他们的獠牙上被揍了这么一拳……"
D.Strings[64012]="这次，你就给我乖乖躺下吧！"
D.Strings[64013]="这是泰塔尔的地盘！"
D.Strings[64014]="我以前从没见过这么快的速度……"
D.Strings[64015]="我的零件被打坏了……"
D.Strings[64016]="尝尝我的锄头吧，$g小子:丫头;！"
D.Strings[64017]="你愿意帮助一位老人重走末代皇帝之路吗？"
D.Strings[64018]="我准备好了，我们出发吧。"
D.Strings[64019]="用我的铲子把我埋了吧……\n我是说真的……"
D.Strings[64020]="你能挖到它吗？！？"
D.Strings[64021]="现在，谁才是该退市的产品？"
D.Strings[64022]="%s似乎在哭泣。"
D.Strings[64023]="我会找到你的……"
D.Strings[64024]="死亡的声音……在我听来是如此甜蜜……"
D.Strings[64025]="这是什么感觉？那是……光吗……？"
D.Strings[64026]="%s似乎不太稳定……"
D.Strings[64027]="医师不在了……"
D.Strings[64028]="当你只剩下拳头的时候，你就会觉得看什么都像脸……"
D.Strings[64029]="你将受到审判。"
D.Strings[64030]="我掌握着……圣光！"
D.Strings[64031]="你在挑战我的信仰。"
D.Strings[64032]="圣光就是我的护盾。"
D.Strings[64033]="你很有……勇气……"
D.Strings[64034]="现在，直面你的末日吧。"
D.Strings[64035]="太慢了，凡人。"
D.Strings[64036]="咕咕咕——去死吧！"
D.Strings[64037]="嘎嘎！！"
D.Strings[64038]="帮我们击退这些联盟狗！"
D.Strings[64039]="又有人荡过来了。看来这是最后一批了！"
D.Strings[64040]="微风提高了你的移动速度——走到先知昊梵舟身边，与他分享此效果。"
D.Strings[64041]="拜托你小声点，$r。是贝恩·血蹄派我来监视锦绣谷动向的。"
D.Strings[64042]="我是个头脑简单的牛头人。贝恩和我是老朋友了。"
D.Strings[64043]="跟我们走，笨蛋，如果你不想见血的话。"
D.Strings[64044]="你这是在自讨苦吃。立刻放下武器。"
D.Strings[64045]="你以为你能跑到哪儿去？库卡隆已经控制了这座城市。"
D.Strings[64046]="你最好不要逼酋长动手。"
D.Strings[64047]="看看这个下贱的家伙，满身的稻草味儿。"
D.Strings[64048]="我会很乐意碾碎你的灵魂的。"
D.Strings[64049]="|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t奖励目标开启：在时间耗尽前击败所有敌人！"
D.Strings[64050]="|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t奖励计时器启动！"
D.Strings[64051]="我得练习一下。\n \n<指指你手中的工具。>\n \n如果你没有练过，那最好先练练。一定要坚持练习。\n \n不管你要做什么，这是都进步的唯一方法。\n \n练习，练习，练习。"
D.Strings[64052]="等我长大以后，我要成为世界上最杰出的萨满！"
D.Strings[64053]="煞魔侵蚀恐惧废土的两条路线似乎就是两条笔直的线。我很好奇它们会通向哪里？真是太奇怪了。"
D.Strings[64054]="有些事，不过是人们口口相传的留言罢了。这使得我们揭示历史真相时变得有些困难……但我们也只能将就一下了。"
D.Strings[64055]="不要过于怀念逝去的朋友和同伴。也许最好的解决办法就是为你能与他们有过一段交情感到荣幸。"
D.Strings[64056]="你听说过雷神岛吗？连身处此地的我们都收到了黑暗的预兆。"
D.Strings[64057]="据说雷电之王的军队庞大且强悍。你觉得战火会波及到这里吗？"
D.Strings[64058]="我们是和平的人民，可一旦我们心中那属于战士的热血被唤醒，我们也会奋起一战的。"
D.Strings[64059]="我听说雷神岛上有许多危险的敌人和生物。看来，外部的威胁每天都在发生变化。"
D.Strings[64060]="帮我们击退这些部落猪！"
D.Strings[64061]="我就是靠那些初至潘达利亚的旅客过活的。记得保持火药干燥。还有，啤酒需要冷藏！！"
D.Strings[64062]="这架火箭能把你送去遥远的荒芜之地。你确定吗？"
D.Strings[64063]="|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t奖励目标：救出所有的斥候并终止巨魔召唤来的风暴！"
D.Strings[64064]="|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t奖励目标：击败毁灭者波罗库拉！"
D.Strings[64065]="|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t奖励目标：击败怒煞畸体！"
D.Strings[64066]="好好享受这摇滚乐吧，伙计！"
D.Strings[64067]="我这辈子从没干过一整天的活儿。这只是做夜猫子的诸多好处之一。"
D.Strings[64068]="我宁可去看看书！"
D.Strings[64069]="我正在学说猢狲语，该死的蠢蛋！公孙镝甫吃光了我的鱼。我要狠狠揍他一顿。"
D.Strings[64070]="正统部落的敌人统统要死！"
D.Strings[64071]="我们的力量无人能挡！"
D.Strings[64072]="我们将净化这片土地！"
D.Strings[64073]="地狱咆哮之眼在注视着我们！"
D.Strings[64074]="我们会将你们踩在脚下！"
D.Strings[64075]="你不配活着，懦夫。"
D.Strings[64076]="让沃金和他所有的同谋都去死吧！"
D.Strings[64077]="为了正统部落！"
D.Strings[64078]="这门真有意思。"
D.Strings[64079]="我从没想过会有这样一个世界。"
D.Strings[64080]="很高兴再次见到你。我们见过吗？"
D.Strings[64081]="这结果真奇怪。"
D.Strings[64082]="这个世界真是太与众不同了。"
D.Strings[64083]="我得走了，还有好多东西要看呢。"
D.Strings[64084]="一切皆有可能。"
D.Strings[64085]="我？噢，我不是本地人。"
D.Strings[64086]="|TInterface\\Icons\\ability_creature_poison_04:20|t%s在他的匕首上涂抹了|cFFFF0000|Hspell:143224|h[速效药膏]|h|r！"
D.Strings[64087]="|TInterface\\Icons\\ability_rogue_deviouspoisons:20|t%s在他的匕首上涂抹了|cFFFF0000|Hspell:143239|h[致命剧毒]|h|r！"
D.Strings[64088]="导管能量已满，雷神断开了链接！"
D.Strings[64089]="一个奇怪的家伙。我能在你的尸体上找到什么宝贝呢？"
D.Strings[64090]="这似乎很紧急，卡德拉克。肯定还有其他办法的！"
D.Strings[64091]="很好，$n。我会到那里等你的。"
D.Strings[64092]="蠢货。尝尝真正的大漠毒针吧。"
D.Strings[64093]="你会像其他霜狼渣滓一样卑贱地死去。"
D.Strings[64094]="你以为我死了吗，嗯？"
D.Strings[64095]="我藐视死亡，更看不起你！"
D.Strings[64096]="你的刀剑敌不过我们的谋略。"
D.Strings[64097]="虽然你不是霜狼兽人，可你会像他们一样流血而死。"
D.Strings[64098]="[虚张声势]我们何不坐等你们去攻击奥格瑞玛，然后来一个渔翁得利？"
D.Strings[64099]="<沃金发现自己的机会正在溜走。他举起了手。>$b$b等等，$r！奥格瑞玛是一座坚城。我的人，我们不可能自己啃下这块硬骨头。我们又能在这里坚持多久呢？几天？几周？沃金可说不准。$b$b只要你们能源源不断地提供补给，我保证，我们一定能干掉更多的库卡隆，而且是在你们的部队登陆之前！你们的人甚至都不用流血牺牲！这应该能值几箱肉吧？"
D.Strings[64100]="很好，$r。感谢你帮助，许多库卡隆都将因此丧命。"
D.Strings[64101]="这可以让起义军再多坚持一段时间。奥格瑞玛必将陷落！"
D.Strings[64102]="这真是个诡异的时代……谢谢你，$r。有了这些东西，我们就能让更多的库卡隆血洒疆场。"
D.Strings[64103]="又是补给！联盟真像一架机器。很快我们就能在加尔鲁什手下的恶棍中杀出一条血路……许多兽人都站错了队。"
D.Strings[64104]="你很好，$r！有了这些，我们就能横扫加尔鲁什的部队！"
D.Strings[64105]="霜狼们，杀了这头戈隆。找到那个懦夫！"
D.Strings[64106]="去找莱恩·法尔娜。他可以教你任何的专业技能。"
D.Strings[64107]="|cFFFE1CF7|Hspell:139267|h[文物镐]|h|r可显示特殊的遗物！"
D.Strings[64108]="+5点遗物奖励！"
D.Strings[64109]="+10点遗物奖励！"
D.Strings[64110]="乌萨吉之死重创了剩余的元素生物！"
D.Strings[64111]="%s闻到了一群受伤的敌人散发出的血腥味并陷入了|cFFFF0404|Hspell:143440|h[血性狂乱]|h|r！"
D.Strings[64112]="%s开始用 |cFFFF0000|Hspell:141423|h[哈基玛的智慧]|h|r为自己治疗。"
D.Strings[64113]="感谢你们的协助，勇士们。在返回铁炉堡之前，我得先照料这里的死者和伤者。"
D.Strings[64114]="别动，小崽子。距离这么近，我们不费吹灰之力就能刺穿你的护甲。"
D.Strings[64115]="贾纳尔，我们抓住一个杜隆坦的探子。"
D.Strings[64116]="又是一条来玷污我们神圣土地的害虫。"
D.Strings[64117]="杜隆坦派$G他:她;来，肯定是有原因的。"
D.Strings[64118]="呸。我就让你看看我对我哥哥这个“口信”的看法吧。"
D.Strings[64119]="别动，恶魔。距离这么近，我们不费吹灰之力就能刺穿你的护甲。"
D.Strings[64120]="贾纳尔，我们抓住一个杜隆坦派来跟踪我们的绿皮兽人探子。"
D.Strings[64121]="又一个被腐蚀的渣滓。这些蝎魔已经够我们头疼的了。"
D.Strings[64122]="你那绿皮肤已经表明你就是个怪物。你比这坑底的那些渣滓也好不到哪儿去。"
D.Strings[64123]="你听到那呼啸的风声了吗？多么孤寂的声音。别犯错——如果你不小心提防，这片土地就会把你永远留在这里。"
D.Strings[64124]="你应该去找温比尔·任务栏，他就在南边的大路旁。\n\n他可以帮你学习任何感兴趣的专业技能！"
D.Strings[64125]="去旅店找尼德里奇·沙洛吧。\n\n他就在楼下的楼梯右边。"
D.Strings[64126]="去找伊兰尼斯·影花吧。\n\n你可以在旅店的主层找到他。"
D.Strings[64127]="去鹰翼广场的旅店找塞伦吧。\n\n你可以在楼上的厨房附近找到他。"
D.Strings[64128]="瓦伦可以帮助你。\n\n你可以在碧蓝岗哨的南边找到他。"
D.Strings[64129]="贾纳尔的莽撞会导致氏族分裂。他已经把个人追求置于氏族利益之上了。"
D.Strings[64130]="别担心。这位英雄会把贾纳尔劝回来的。他最看重实力，而我朋友恰好很有实力。"
D.Strings[64131]="而且，贾纳尔向来都将个人需求看得比氏族更重要。"
D.Strings[64132]="远古裂蹄牛的骨骼动了起来！"
D.Strings[64133]="能再给我一头赛羊吗？"
D.Strings[64134]="不！你这蠢货！仪式……失控了……"
D.Strings[64135]="是谁竟敢打断我的法术！"
D.Strings[64136]="你得骑着赛羊才能拿到酒桶！快去找尼尔·拉姆斯登再要一头吧。"
D.Strings[64137]="你得骑着赛羊才能拿到酒桶！快去找赛羊管理员雷恩再要一头吧。"
D.Strings[64138]="[%s]忏悔：当我的盟友被精神控制时，我总会很努力地干掉他们。"
D.Strings[64139]="[%s]忏悔：我从不使用最强的战斗宠物，只用最萌的。"
D.Strings[64140]="[%s]忏悔：我总是把两个野性之心搞混。"
D.Strings[64141]="[%s]忏悔：每次重铸装备时，我都要请教别人。"
D.Strings[64142]="[%s]忏悔：我常常观察别人，看他们有没有在观察我。"
D.Strings[64143]="[%s]忏悔：每当有熊猫人让我放慢脚步时，我就想揍他们一顿。"
D.Strings[64144]="[%s]忏悔：我总是把所有的旧装备都卖给同一个商人。有钱人的怪癖吧。"
D.Strings[64145]="[%s]忏悔：相比升级装备，我更喜欢幻化装备。"
D.Strings[64146]="[%s]忏悔：我很难在部落和联盟间做出选择。部落有四根辫子的地精法师，联盟也有麻花辫的矮人牧师。"
D.Strings[64147]="|TInterface\\Icons\\spell_frost_summonwaterelemental.blp:20|t%s开始施放|cFFFF0000|Hspell:143309|h[漩涡]|h|r！"
D.Strings[64148]="|TInterface\\Icons\\ability_shawaterelemental_split.blp:20|t%s|cFFFF0000|Hspell:143020|h[分裂]|h|r了！"
D.Strings[64149]="霜狼幼崽激动地在你脚踝上咬了一口，然后跟着你跑了起来。"
D.Strings[64150]="|TInterface\\Icons\\sha_spell_fire_blueflamestrike:20|t%s的|cFFFF0000|Hspell:143602|h[冥思之刺]|h|r锁定了$n！"
D.Strings[64151]="|TInterface\\Icons\\ability_shawaterelemental_reform.blp:20|t%s开始|cFFFF0000|Hspell:143469|h[重塑形体]|h|r！"
D.Strings[64152]="贾纳尔！你也该回来了。这些是什么东西？"
D.Strings[64153]="我杀了铁狼的儿子们。凶手必须血债血偿。"
D.Strings[64154]="你这次愚蠢的出击让我们伤亡惨重。"
D.Strings[64155]="我不承认，兄弟。凭我作为次子的权利，凭我今天所伸张的正义，我要与你决斗。"
D.Strings[64156]="也只能这样了。"
D.Strings[64157]="你们不能这么做——你们是亲人！"
D.Strings[64158]="家人就该互相照顾！只有我还想着为父亲报仇！"
D.Strings[64159]="复仇对我们氏族毫无益处。这就是父亲选我继任酋长的原因。"
D.Strings[64160]="父亲选错了人。氏族需要力量。"
D.Strings[64161]="酋长。"
D.Strings[64162]="她的存在玷污了霜狼的荣耀。其他氏族会唾弃我们的。"
D.Strings[64163]="那些连站都站不起来的人……都该……去死！"
D.Strings[64164]="复仇并不能让氏族变得强大。"
D.Strings[64165]="站起来，兄弟。我需要你。氏族需要你。"
D.Strings[64166]="为了保护挚爱的人，我们才会迸发出无限的力量。"
D.Strings[64167]="我们是一家人，贾纳尔。一家人就该团结一致。"
D.Strings[64168]="这才是令霜狼强大的关键。"
D.Strings[64169]="来跟我们并肩作战吧，兄弟。让我们齐心协力。我们还有很多事要做。"
D.Strings[64170]="够了！我认输。"
D.Strings[64171]="我想你并不是个软蛋。"
D.Strings[64172]="你不属于这里！厄托克会让你看看什么才是真正的力量！"
D.Strings[64173]="我输了？这怎么可能？"
D.Strings[64174]="是的，兄弟。我会张开双臂欢迎你的。"
D.Strings[64175]="还活着呢，小崽子？看来我是不用去救你了。过来，我们得谈谈。"
D.Strings[64176]="噢，你最好别死了。蝎魔可不懂得尊重遗体。"
D.Strings[64177]="你的尸体会派上大用处的。毛发、血肉和骨头。我可以用它们做出许多药剂。"
D.Strings[64178]="你来干什么？来找你的宝贝狼崽子吗？它们的血肉都归我了！"
D.Strings[64179]="我向来很骄傲，可我承认你击败了我，哥哥。我想学习你的力量。我们会回来的。"
D.Strings[64180]="如此……强大……"
D.Strings[64181]="|TInterface\\Icons\\ability_warrior_offensivestance.blp:20|t纳兹戈林将军进入了|cFFFF0000|Hspell:143589|h[战斗姿态]|h|r！"
D.Strings[64182]="|TInterface\\Icons\\ability_warrior_defensivestance.blp:20|t纳兹戈林将军进入了|cFFFF0000|Hspell:143593|h[防御姿态]|h|r！"
D.Strings[64183]="|TInterface\\Icons\\ability_racial_avatar.blp:20|t纳兹戈林将军进入了|cFFFF0000|Hspell:143594|h[狂暴姿态]|h|r！"
D.Strings[64184]="给我点钱，我给你看个好东西！"
D.Strings[64185]="火枪手"
D.Strings[64186]="这具尸体还很新鲜，而且几乎没有伤痕，只在腹部有六道整齐的切口。$B$B你发现每处切口下面都是巨大的空腔，那里原本可能长着重要的器官。"
D.Strings[64187]="|TInterface\\Icons\\ability_priest_pathofthedevout:20|t%s开始施放|cFFFF0000|Hspell:143497|h[金莲的羁绊]|h|r。"
D.Strings[64188]="毒心者夏克里尔在房间中投掷了蓝色催化药剂！"
D.Strings[64189]="毒心者夏克里尔在房间中投掷了红色催化药剂！"
D.Strings[64190]="毒心者夏克里尔在房间中投掷了黄色催化药剂！"
D.Strings[64191]="毒心者夏克里尔在房间中投掷了橙色催化药剂！"
D.Strings[64192]="毒心者夏克里尔在房间中投掷了紫色催化药剂！"
D.Strings[64193]="毒心者夏克里尔在房间中投掷了绿色催化药剂！"
D.Strings[64194]="停下！"
D.Strings[64195]="贾纳尔？是你？我还以为你已经死了。"
D.Strings[64196]="还是说你喜欢上了挨揍的滋味，所以又回来找揍了？"
D.Strings[64197]="你是想来雷神氏族祈求一个容身之所吗？哈哈哈哈！"
D.Strings[64198]="如果你肯学狗叫，我父亲或许—— "
D.Strings[64199]="你父亲或许还能认出你的小脑瓜。"
D.Strings[64200]="呃……杀——……杀了他们！！"
D.Strings[64201]="兄弟们！今天，我们做到了杜隆坦做不到的事！"
D.Strings[64202]="蝎魔已经无路可退，而我们的坐骑也已经准备好了，老朋友。"
D.Strings[64203]="今天，我们要向那个杀害加拉达的畜生复仇！"
D.Strings[64204]="贾纳尔，雷神氏族最近正在峡谷中训练他们的猎手。"
D.Strings[64205]="呸！雷神的渣滓。那个被他们称为“家园”的破地方已经住不下了吗？"
D.Strings[64206]="如果有必要，我们会从他们中间杀出一条血路来。"
D.Strings[64207]="这个战士的遗体上有好几处致命的穿刺伤害。人们将他仔细地摆放好之后才点起了火。"
D.Strings[64208]="求你……杀了我……"
D.Strings[64209]="法术……烧……啊啊啊！！！"
D.Strings[64210]="停下，兄弟们！看到你们面前的役畜了吗？"
D.Strings[64211]="我们必须吞噬他的血肉，因为他是弱者！轮回必将继续！"
D.Strings[64212]="是的！吃了他！连皮带骨吞下去！"
D.Strings[64213]="克洛斯之血在上！"
D.Strings[64214]="吃他的肉！喝他的血！"
D.Strings[64215]="邪刃之力！"
D.Strings[64216]="你们还不理解克洛斯之道吗？他被亵渎了！"
D.Strings[64217]="城门遭到攻击！"
D.Strings[64218]="杜隆克？这是什么邪恶的巫术？"
D.Strings[64219]="我的兄弟死了，只剩下这个家伙。它必须死！"
D.Strings[64220]="在你对付库拉克阿坎的同时，我会摧毁这个污秽的祭坛。"
D.Strings[64221]="欢迎来到霜风戈壁！"
D.Strings[64222]="雷神兽人，听好了！我是加拉达之子！霜狼氏族的贾纳尔！"
D.Strings[64223]="你们酋长杀了我父亲。所以我来取他狗崽子们的脑袋。谁有胆量来阻止我！？"
D.Strings[64224]="做好准备……"
D.Strings[64225]="贾纳尔，这个外来者的价值的确不可否认。"
D.Strings[64226]="哈！厄托克，舔你的伤口去吧。你，小崽子，你将取代他的位置。我们很快就要去为我的父亲复仇了。成功之后，我会亲自去见杜隆坦的。"
D.Strings[64227]="你可以跟我们一起去，但你得跟我们一样骑上来自这片山脉中霜狼，否则免谈。"
D.Strings[64228]="流亡者们！我们该出发了！小心这位新朋友的……坐骑！"
D.Strings[64229]="目标峡谷！为了荣耀！"
D.Strings[64230]="魔法装置"
D.Strings[64231]="范围攻击装置"
D.Strings[64232]="诱捕装置"
D.Strings[64233]="来吧，$r，我这就要去流亡者营地了。"
D.Strings[64234]="我一定要把看到的一切告诉贾纳尔。"
D.Strings[64235]="我们早知道蝎魔是群卑劣的害虫，可从没想过他们的数量会变得这么多。"
D.Strings[64236]="不过没关系。多亏了你，库拉克阿坎已经死了。库拉基蝎魔的威胁已经不复存在了。"
D.Strings[64237]="我一定会把你的事迹告诉贾纳尔的。"
D.Strings[64238]="兄弟们，看呐，一个外来者。"
D.Strings[64239]="弗拉格尔！这个小崽子是谁？"
D.Strings[64240]="他不是杂种，酋长。我愿意给这个陌生人作担保。"
D.Strings[64241]="弗拉格尔，你带回来的这个杂种是怎么回事？"
D.Strings[64242]="兄弟姐妹们，前进！杀过这片营地，在蛮荒峭壁汇合！ "
D.Strings[64243]="我敢打赌，我杀掉的戈隆肯定会比你多，兄弟。"
D.Strings[64244]="快吃吧，小伙子们！我们还要去杀戈隆呢。"
D.Strings[64245]="磨刀——磨刀了……"
D.Strings[64246]="又尖又快。最适合戳瞎戈隆的眼睛，或者刺入雷神兽人的胸膛了。"
D.Strings[64247]="快阻止$G他:她;！"
D.Strings[64248]="别让$G他:她;过去！"
D.Strings[64249]="别让$G他:她;跑了！"
D.Strings[64250]="嘘！软脚虾，过来！"
D.Strings[64251]="我可以闻到他们，浑身散发着恐惧的气味。"
D.Strings[64252]="如此饥渴……"
D.Strings[64253]="你！过来，让我们尝尝……"
D.Strings[64254]="出什么事了？把那家伙关回笼子里去！"
D.Strings[64255]="入侵者！我要把你们和其他渣滓关到一起去！"
D.Strings[64256]="快给我住手！你知道自己究竟在干什么吗？！"
D.Strings[64257]="<贾纳尔正在积蓄力量，准备挑战巨大的戈隆。>"
D.Strings[64258]="<协助贾纳尔作战。>"
D.Strings[64259]="伟大的役畜，请听从我的召唤！"
D.Strings[64260]="我来送你回到克洛斯的怀抱！将你的血肉交给我吧！"
D.Strings[64261]="老兄，让我的宠物把你烧成灰吧！"
D.Strings[64262]="我的兽群将畅享你的血肉。"
D.Strings[64263]="烧死他们！把他们烧成灰！"
D.Strings[64264]="时间到了。"
D.Strings[64265]="至于你，外来者……"
D.Strings[64266]="所以你得骑那头驮犬。哈哈哈！"
D.Strings[64267]="你已经在这次袭击中赢得了一席之地。鉴于你还没有属于自己的霜狼……"
D.Strings[64268]="谢谢，朋友们。我会尽力帮助你们的。"
D.Strings[64269]="%s痛苦地蜷缩起来，愤怒地瞪着$n。"
D.Strings[64270]="我的死没有任何意义。你们无法平息风暴！"
D.Strings[64271]="只要库拉克阿坎还活着……你就阻止不了我们！"
D.Strings[64272]="蠢货，你的行动毫无意义！我们真正的力量都在北边的山谷里。"
D.Strings[64273]="他们的狩猎营地恰好位于我们和戈隆的洞穴之间。"
D.Strings[64274]="%s一看到麻烦就跳了起来！"
D.Strings[64275]="贾纳尔可能有一点……暴躁。尤其是在他跟他哥哥闹翻之后。$b$b你最好别惹得他亲自把你踢进洞里。"
D.Strings[64276]="将杜隆坦派你来的用意告诉弗拉格尔。"
D.Strings[64277]="<这头蜘蛛恶狠狠地瞪着你。>"
D.Strings[64278]="开启宠物对战。"
D.Strings[64279]="你想要统一霜狼氏族？那我们的目标是一致的。我从贾纳尔和杜隆坦出生起就认识他们了。我得提醒你，要想让他们重归于好，光靠语言是不够的。$b$b贾纳尔必须完成他的任务。他想为父亲的死报仇，不管是这个世界还是其他世界，没有人能让放弃这个目标。$b$b所以，我没有跟他对着干，而是选择帮助他，并增加他成功的机会。"
D.Strings[64280]="许多骑兵还在翻越我们身后的沙丘。"
D.Strings[64281]="留在这里，等援军上来。同时让我们尽可能地多杀点人。"
D.Strings[64282]="我也没那——么尖刻，不是吗？"
D.Strings[64283]="我今天就要鸡蛋里挑骨头了！"
D.Strings[64284]="我为什么不在聚会上跳舞？因为我没有身体！"
D.Strings[64285]="什么鬼魂会在鸡舍里作祟？鸡的鬼魂！"
D.Strings[64286]="我知道我的笑话不怎么样……因为我的“笑骨”不见了！"
D.Strings[64287]="你谁也骗不了，小鬼！我看穿你了！"
D.Strings[64288]="我的骨子里充满了野性！"
D.Strings[64289]="刚刚谁骂我是榆木脑袋来着？"
D.Strings[64290]="我可能是有点死脑筋……"
D.Strings[64291]="抱歉我太爱开玩笑了。"
D.Strings[64292]="有时你就得对不守规矩的鬼魂狠一点。"
D.Strings[64293]="我以前是很幽默的。"
D.Strings[64294]="想听笑话吗？白痴。"
D.Strings[64295]="只要你的笑话行得通，谁还需要身体呢？"
D.Strings[64296]="你瞧……我的心思真的不在这里。"
D.Strings[64297]="他们连一条腿都没给我留下！"
D.Strings[64298]="鬼魂肯定都很冷。因为风能直接穿透他们！"
D.Strings[64299]="我一直很想弹风琴。"
D.Strings[64300]="我要把你的骨头都装到我自己身上！"
D.Strings[64301]="我正在钻研我的灵魂知识。"
D.Strings[64302]="不管你说什么，都不可能让我刻骨铭心！"
D.Strings[64303]="棍棒和石头可能会敲碎我的骨头……"
D.Strings[64304]="我很想约她出去，可我没那个胆。"
D.Strings[64305]="我恐怕对此没什么胃口……"
D.Strings[64306]="嘿，肉袋子！如果你有时间，就来跟我谈谈吧！我好空虚！"
D.Strings[64307]="成交。欢迎来到灵魂世界。从某种程度来说这里也算是啦。让我们翻翻这些箱子，看看你能不能找到我的身体吧！"
D.Strings[64308]="同时，我们还要尽量多引出一点来……"
D.Strings[64309]="你跟厄托克那一战打得很漂亮。让我们看看你那些小把戏对戈隆有没有用吧。"
D.Strings[64310]="杜隆坦派你来的？他应该亲自来。毕竟我们是来给他的父亲报仇的。"
D.Strings[64311]="我还记得自己第一次喂狼时的情景，那次差点把自己的手都给丢了。"
D.Strings[64312]="斥候发现科洛克就在刀塔绿洲的另一边。做好准备，我们就要出发了。"
D.Strings[64313]="听说雷神氏族挡在了我们和戈隆之间。那会是一场不错的热身。哈！"
D.Strings[64314]="一位$c，嗯？你在实战中的表现会是怎样呢？"
D.Strings[64315]="我还记得第一次跟贾纳尔行动时的情景，那次我差点就瞎了。真是个好日子！"
D.Strings[64316]="要想赢得一头真正的霜狼的心，几块碎肉是不够的。哪怕它并不伤人。"
D.Strings[64317]="还活着呢，小崽子？来吧，我们必须在贾纳尔出兵前找到他。"
D.Strings[64318]="我没空理会这家伙。厄托克，给我把这个废物扔出去。"
D.Strings[64319]="伊约库克开始根据$n选取标准！"
D.Strings[64320]="库卡隆，支援我！"
D.Strings[64321]="战士们，快过来！"
D.Strings[64322]="下一队，冲上去！"
D.Strings[64323]="守住大门！"
D.Strings[64324]="重新整队！"
D.Strings[64325]="库卡隆，听我的命令，杀了他们！"
D.Strings[64326]="省省吧，小崽子，我没功夫来听杜隆坦的牢骚。我们是来完成他拒绝完成的任务的。"
D.Strings[64327]="伊约库克选择了：长剑|TInterface\\Icons\\ABILITY_IYYOKUK_SWORD_white.BLP:20|t！"
D.Strings[64328]="伊约库克选择了：战鼓|TInterface\\Icons\\ABILITY_IYYOKUK_DRUM_white.BLP:20|t！"
D.Strings[64329]="伊约库克选择了：炸弹|TInterface\\Icons\\ABILITY_IYYOKUK_BOMB_white.BLP:20|t！"
D.Strings[64330]="伊约库克选择了：螳螂妖|TInterface\\Icons\\ABILITY_IYYOKUK_MANTID_white.BLP:20|t！"
D.Strings[64331]="伊约库克选择了：法杖|TInterface\\Icons\\ABILITY_IYYOKUK_STAFF_white.BLP:20|t！"
D.Strings[64332]="伊约库克选择了：|cFFFF0000红色|r！"
D.Strings[64333]="伊约库克选择了：|cFFFF00FF紫色|r！"
D.Strings[64334]="伊约库克选择了：|cFF0000FF蓝色|r！"
D.Strings[64335]="伊约库克选择了：|cFF00FF00绿色|r！"
D.Strings[64336]="伊约库克选择了：|cFFFFFF00黄色|r！"
D.Strings[64337]="伊约库克选择了：一！"
D.Strings[64338]="伊约库克选择了：二！"
D.Strings[64339]="伊约库克选择了：三！"
D.Strings[64340]="伊约库克选择了：四！"
D.Strings[64341]="伊约库克选择了：五！"
D.Strings[64342]="|TInterface\\Icons\\spell_nature_diseasecleansingtotem.blp:20|t黑暗萨满放置了|cFFFF0000|Hspell:144288|h[毒雾图腾]|h|r！"
D.Strings[64343]="|TInterface\\Icons\\spell_nature_natureresistancetotem.blp:20|t黑暗萨满放置了|cFFFF0000|Hspell:144289|h[污流图腾]|h|r！"
D.Strings[64344]="|TInterface\\Icons\\spell_frost_fireresistancetotem.blp:20|t黑暗萨满放置了|cFFFF0000|Hspell:144290|h[灰火图腾]|h|r！"
D.Strings[64345]="|TInterface\\Icons\\spell_shaman_totemrecall.blp:20|t黑暗萨满放置了|cFFFF0000|Hspell:144291|h[锈铁图腾]|h|r！"
D.Strings[64346]="|TInterface\\Icons\\spell_nature_bloodlust.blp:20|t黑暗萨满获得了|cFFFF0000|Hspell:144302|h[嗜血]|h|r效果！"
D.Strings[64347]="黑暗萨满陷入了狂怒！"
D.Strings[64348]="隆克喜欢玩跷跷板！"
D.Strings[64349]="隆克，让其他人也玩玩吧。"
D.Strings[64350]="当你靠近时，雕像发出了柔和的嗡鸣声。"
D.Strings[64351]="雕像进入了休眠状态。"
D.Strings[64352]="触摸雕像。"
D.Strings[64353]="我们预定的爽脆胡萝卜可以提货了吗？"
D.Strings[64354]="终于送来了！这些胡萝卜很不错，$n。肯瑞托远征军欠你一份人情。"
D.Strings[64355]="我是来取预定的小葱的。"
D.Strings[64356]="这些小葱的品质超出了我的预期，$c。夺日者先锋军感谢你的帮助。"
D.Strings[64357]="毒心者夏克里尔调制了一些白色催化药剂掷向他的敌人！"
D.Strings[64358]="开启基础坦克（青铜）试炼"
D.Strings[64359]="开启基础坦克（无限）试炼"
D.Strings[64360]="开启基础坦克（黄金）试炼"
D.Strings[64361]="开启基础坦克（白银）试炼"
D.Strings[64362]="|TInterface\\Icons\\inv_misc_sawblade_01.blp:20|t攻城匠师黑索转向你并准备|cFFFF0000|Hspell:143266|h[发射锯刃]|h|r！"
D.Strings[64363]="摧毁水晶。"
D.Strings[64364]="和你一样，我很难抗拒这个体验熊猫人古老传统的机会。当你准备好之后，就让我们看看你指挥宠物作战的本领吧。"
D.Strings[64365]="你好啊，$n。我是奥利安娜，我负责救治重伤的宠物，并为参赛者解释规则。\n\n你不能在比武大会期间治疗或复活宠物。如果你没有能够出战的宠物了，可以离开然后再次进入比武大会。\n\n如果你输给某个挑战者，就需要与其重新比赛。"
D.Strings[64366]="治疗宠物会使你失去当前场景战役的进度，而你也得与对手重新比试。你确定吗？"
D.Strings[64367]="支付5枚永恒铸币换取1把库库鲁的宝箱钥匙。"
D.Strings[64368]="支付5枚永恒铸币？"
D.Strings[64369]="聪明的猢狲说了：发光的不都是金子。但是金子总会发光。"
D.Strings[64370]="聪明的猢狲说了：财富就在你的内心深处，或者在这些箱子中。"
D.Strings[64371]="聪明的猢狲说了：外表充满了欺骗性，尤其是当你的眼神不好时。"
D.Strings[64372]="聪明的猢狲说了：有多大胃口吃多少东西，除非附近有其他饥饿的猢狲。"
D.Strings[64373]="聪明的猢狲说了：行动比言语更加振聋发聩，除非那家伙在大喊大叫。"
D.Strings[64374]="聪明的猢狲说了：如果你第一次失败了，就找别人来帮你做。"
D.Strings[64375]="聪明的猢狲说了：今日事今日毕……噢，算了，后半句我下次再告诉你吧。"
D.Strings[64376]="欢迎，旅行者！我这里有来自世界各地的宝物。$B$B想来试试手气吗？几个永恒铸币就能换一把钥匙了！"
D.Strings[64377]="嗨，$N！很高兴再次见到你。大家还在议论你上次赢得比武大会的事呢……我没能从头看到尾，因为有太多伤员需要我来治疗了。但不用担心，他们现在都好了！"
D.Strings[64378]="%s开始施放|cFFFF0000|Hspell:144590|h[月牙的诅咒]|h|r。"
D.Strings[64379]="%s切回了突击模式！"
D.Strings[64380]="%s切换至强攻模式！"
D.Strings[64381]="|TInterface\\Icons\\ability_mage_firestarter.blp:20|t|cFFFF0000攻城技师|r出现在两侧并开始施放|cFFFF0000|Hspell:144616|h[钢铁之星充能]|h|r！"
D.Strings[64382]="守住，伙计们！敌人登上甲板了！"
D.Strings[64383]="小心！又有敌人冲过来了！"
D.Strings[64384]="想活命的就得先拼命，伙计们！如果藤壶号沉了，我们都得去喂鱼！"
D.Strings[64385]="这把锤子摸上去热乎乎的。"
D.Strings[64386]="拿起锤子。"
D.Strings[64387]="菲尔拉伦的胡子啊，那是什么？杀了它！"
D.Strings[64388]="我们成功了，伙计们，我们拯救了藤壶号！自从进入这片隔绝一切的迷雾以来，我们总算能休息一会儿了。扬帆，伙计们。我们要回家啦！"
D.Strings[64389]="|cFFFF0000小心：|r月牙恐嚎者正在树林中徘徊！"
D.Strings[64390]="|cFFFF0000小心：|r暗月巢母月牙出现在了树林中！"
D.Strings[64391]="暗月巢母月牙被击杀了！"
D.Strings[64392]="你听到远处传来一声凄凉的哀嚎。"
D.Strings[64393]="痛苦的哀嚎在暮色中回荡。"
D.Strings[64394]="森林中回荡着悲伤的低吼。"
D.Strings[64395]="树林深处传出了一声痛苦的嚎叫。"
D.Strings[64396]="马上……就……好……"
D.Strings[64397]="噢，这可真是出人意料！"
D.Strings[64398]="呃……你能搞定它的，对吧？"
D.Strings[64399]="噢，你好啊！我正打算收线呢。我有预感，这是个大家伙！"
D.Strings[64400]="那你还等什么呢？！快让我们看看！"
D.Strings[64401]="好！那它就交给你了！"
D.Strings[64402]="愤怒、仇恨、恐惧！这是战争的武器——酋长的工具！"
D.Strings[64403]="啊，是的……我看见了……这世界的未来……由部落统治的世界……我的部落。"
D.Strings[64404]="进入我的国度。"
D.Strings[64405]="蛰龙被$r$c$n吸引了。"
D.Strings[64406]="你被|cFFFF0000|Hspell:144985|h[腐蚀漩涡]|h|r击杀了。远离加尔鲁什可降低受到的伤害。"
D.Strings[64407]="我不眠不休的监视将傲慢的腐蚀困锁于此。要想亲身面对这种腐蚀，你们就必须在熊熊燃烧的光明中净化自己。这个过程可不容易。\n\n你们准备好了吗？"
D.Strings[64408]="我们准备好了，守护者。"
D.Strings[64409]="确定要开启诺鲁什之战吗？"
D.Strings[64410]="这是酋长的最新武器：钢铁之星，大家喜欢吗？！"
D.Strings[64411]="噢，看看谁来了。就是你们毁了我的战蝎。"
D.Strings[64412]="这将是工作和娱乐的完美结合。"
D.Strings[64413]="嘿，$r！求求你们，放我们出去。"
D.Strings[64414]="我的族人可以帮你们作战。我发誓。"
D.Strings[64415]="只要你们打开这扇门。"
D.Strings[64416]="我们的祈祷得到了回应！"
D.Strings[64417]="我们必须拯救锦绣谷。"
D.Strings[64418]="尝尝失败的滋味吧。"
D.Strings[64419]="守护者们，协助我！"
D.Strings[64420]="我们都失败了，你们就能成功吗？"
D.Strings[64421]="我们没能履行自己的誓言！"
D.Strings[64422]="我们又找回了失去的方向。你们是……好人。"
D.Strings[64423]="感觉……好多了……谢谢你……小朋友。"
D.Strings[64424]="开启基础治疗（青铜）试炼"
D.Strings[64425]="开启基础治疗（无限）试炼"
D.Strings[64426]="开启基础治疗（黄金）试炼"
D.Strings[64427]="开启基础治疗（白银）试炼"
D.Strings[64428]="鲁克……有危险……"
D.Strings[64429]="鲁克……需要帮助！"
D.Strings[64430]="跟鲁克……打一架。"
D.Strings[64431]="鲁克要战斗！"
D.Strings[64432]="孙……禾……协助我。"
D.Strings[64433]="%s发出了求救信号。"
D.Strings[64434]="我很抱歉，$n，可我不想聊天。请让我安静一会儿。"
D.Strings[64435]="我们做出了这么多牺牲，可战斗依然久拖不决。这些战斗足以消磨我的意志……"
D.Strings[64436]="坚强点，$c。珍惜你所爱的人。我们永远不知道自己能在这个世界上停留多久。"
D.Strings[64437]="%s进入了冥想状态以治疗自己的伤势。"
D.Strings[64438]="|TInterface\\Icons\\ability_druid_typhoon:20|t%s进入了|cFFFF0000|Hspell:143559|h[黑暗冥想]|h|r状态！"
D.Strings[64439]="格鲁丹！攻击！"
D.Strings[64440]="|TInterface\\Icons\\ability_rogue_deadliness:20|t%s留下了一个|cFFFF0000|Hspell:143840|h[苦痛印记]|h|r！"
D.Strings[64441]="阿格隆！让他们看看谁才是老大！"
D.Strings[64442]="好吧，莎娜。你上。"
D.Strings[64443]="|TInterface\\Icons\\spell_monk_ringofpeace:20|t%s施放了|cFFFF0000|Hspell:143955|h[祸不单行]|h|r！"
D.Strings[64444]="看来我得找一个新助手了。"
D.Strings[64445]="这下是为了我的战蝎！"
D.Strings[64446]="客户一定会满意的。"
D.Strings[64447]="为各位送上——精美的ST-03震波飞弹炮台！"
D.Strings[64448]="知道有什么东西比炸弹更好吗？！答案是内含两颗炸弹的炸弹！"
D.Strings[64449]="来见识一下LT-403汽化激光炮。这可是鄙人的杰作。"
D.Strings[64450]="知道磁铁是怎么工作的吗？"
D.Strings[64451]="启动装配流水线！"
D.Strings[64452]="SD-5自动伐木机防御单位。一位劳模。"
D.Strings[64453]="别……以为你们赢了……"
D.Strings[64454]="你不是……我的朋友……"
D.Strings[64455]="你也失败了。"
D.Strings[64456]="%s向他的敌人点了点头。"
D.Strings[64457]="嘿，我听说你喜欢地雷，所以……"
D.Strings[64458]="再来点儿！"
D.Strings[64459]="未完成的武器从装配流水线上传送出来了。"
D.Strings[64460]="德雷克塔尔！你到底干了什么，这些鬣蜥人都发疯了。"
D.Strings[64461]="抄写"
D.Strings[64462]="$n放下了一辆汤面餐车！"
D.Strings[64463]="$n放下了一辆什锦汤面餐车！"
D.Strings[64464]="$n放下了一辆熊猫人八宝汤面餐车！"
D.Strings[64465]="吞下所有的苦酒吧！"
D.Strings[64466]="现在还不迟，加尔鲁什。卸下酋长的包袱吧。我们可以就此结束这场流血冲突。"
D.Strings[64467]="这是你逼我的。我要纠正过去犯下的错误。狂风、大地、流水之灵，听从我的召唤！请帮助我！"
D.Strings[64468]="我或许很软弱。但我不是一个人。"
D.Strings[64469]="哈！你心中还有荣誉和战场的荣耀吗？你这个与人类媾和，允许术士在我们眼皮底下施行黑暗魔法的家伙。你这个懦夫。"
D.Strings[64470]="我们是兽人的部落，是正统部落。我们会像真正的兽人那样，战死沙场，流血牺牲。"
D.Strings[64471]="你不配当一个兽人，你只能代表你自己。你背叛了我们的人民，来打造你那脆弱的同盟，能一手毁掉它是我的荣幸。"
D.Strings[64472]="蠢货。我的黑暗萨满已经扭曲了这附近的元素。它们听不到你的召唤了。这再次证明了你是多么软弱，一事无成。"
D.Strings[64473]="看来，你们想要挑战一位真正的兽人酋长。那好吧。"
D.Strings[64474]="早在第一次战争时，我的人民就该统治这个世界。可他们堕落了。他们软弱地允许艾泽拉斯的下等种族加入部落。我要完成他们未竟的事业，谁都别想阻止我！"
D.Strings[64475]="看看正统部落的军事实力吧！"
D.Strings[64476]="我们要用铁与火净化这个世界！"
D.Strings[64477]="蛮兵们，染红你们的刀刃吧！Lok'tar Ogar！"
D.Strings[64478]="先知们，为我们治疗！"
D.Strings[64479]="为荣耀而死！"
D.Strings[64480]="我充满了力量！"
D.Strings[64481]="这力量将碾碎你们的世界，抹杀一切！"
D.Strings[64482]="以地狱咆哮之名，毁灭一切！"
D.Strings[64483]="你们在我的新世界中一文不值。"
D.Strings[64484]="上古尊者在召唤！"
D.Strings[64485]="亚煞极之心就是你们的末日！"
D.Strings[64486]="跟我一起看清恐惧，绝望与猜忌的幻象吧！"
D.Strings[64487]="你们将被永远禁锢于此！"
D.Strings[64488]="正统部落必将诞生。我看到了。它让我看到了。我看到尸山血海。我将……拥有……我的……世界！"
D.Strings[64489]="鲁铎。"
D.Strings[64490]="我想参加比武大会。"
D.Strings[64491]="我能参加比武大会吗？"
D.Strings[64492]="我能看得出来，你的个人实力很强。但要想参加天神比武大会，你还必须证明自己的领导能力。只有等你将十五只战斗宠物练到满级之后，才能面对这里的挑战。"
D.Strings[64493]="卡格？我见过他。他救了我的命——他一个人就挡下了五个雷神氏族的恶棍。"
D.Strings[64494]="他之前也在这里，直到铁狼骑着那头双头飞龙出现，那是我见过的最大最凶狠的双头飞龙。卡格被它抓住并带走了。"
D.Strings[64495]="他们还抓了其他人，并把他们拖进峡谷里去了。快去问问，看看还有谁失踪了。"
D.Strings[64496]="小心点。这片土地是神圣的，可并不安全。我接下来的行动可能会引来一些不速之客。"
D.Strings[64497]="伟大的狂风之灵，请响应我的召唤！告诉我你的苦痛源自何处。"
D.Strings[64498]="有必要时，我会用我的图腾协助你的。"
D.Strings[64499]="战争在即，我来向元素求助。"
D.Strings[64500]="可在山间炽烈而刺骨的狂风中，我听到了霜火之怒的哭号。"
D.Strings[64501]="霜火之怒被名叫克鲁恩的玛戈隆囚禁。它的力量折损大半，身躯四分五裂。"
D.Strings[64502]="霜火之怒已被粉碎，它的残骸散落在风中，任由食腐鸟啄食。"
D.Strings[64503]="我的马夫，洛克诺试图用他的草叉击退那些双头飞龙，结果被拖到骨渣锻炉去了！"
D.Strings[64504]="我有段时间没看见马卡了。我们急需他的治疗技术！"
D.Strings[64505]="有个家伙抓走了我的女儿佳娜！他用铁链把她像牲口一样拖走了！"
D.Strings[64506]="真少见，阿卡玛居然派来一个陌生人……"
D.Strings[64507]="……但我相信你。谢谢你，外来者。"
D.Strings[64508]="唔。向那些肮脏的兽人复仇的时机到了。"
D.Strings[64509]="什么？哈？去找阿卡玛？好！！！"
D.Strings[64510]="你不是起义者吧？"
D.Strings[64511]="快点，$r，你们真让我恶心。"
D.Strings[64512]="我要去骨渣锻炉。"
D.Strings[64513]="进入试炼场。"
D.Strings[64514]="我们已经紧紧咬住他们了。现在，反击的时候到了。"
D.Strings[64515]="无论你去往何方，我都会永远追随你的，阿卡玛。"
D.Strings[64516]="我们必须把这些兽人耗子赶出我们的神殿！让他们好好尝尝德莱尼人的制裁。"
D.Strings[64517]="我得治疗我自己了！"
D.Strings[64518]="圣光在上……我们需要有人去对付那座兽人火炮。"
D.Strings[64519]="我看见了。"
D.Strings[64520]="阿胡拉！霍戈！$n！继续进攻！"
D.Strings[64521]="长官，我不能把这些人丢在这里。你们三个继续前进吧，别管我了。"
D.Strings[64522]="好吧。活下去，阿胡拉。"
D.Strings[64523]="霍戈，$n。这些兽人是不会自己死掉的。"
D.Strings[64524]="霍戈，你继续前进——别让他们发动反击。我留下来组织防线。"
D.Strings[64525]="$n！跟我来，深入敌人的阵线！为了卡拉波的圣光！！"
D.Strings[64526]="想要兑换你的战斗石吗？"
D.Strings[64527]="德雷克塔尔或许会怀疑他的能力，可我不会。$b$b我是不会让那个瞎了眼的蠢货背弃元素的，尤其是在它们为我们的族人付出了那么多之后。"
D.Strings[64528]="我的方法是绝不会失败的！"
D.Strings[64529]="很多人都质疑我的方法，但没人能否认我的成果。"
D.Strings[64530]="相信我吧，$r。酷刑能撬开所有人的嘴巴。"
D.Strings[64531]="我这活儿可不是人人都能干的。$b$b<折磨者赛普磨着他的小刀。>$b$b天赋，明白吗？噢，我真是个天才。"
D.Strings[64532]="那个巨魔似乎并不打算开口。你想拿他来练练手吗，$c？"
D.Strings[64533]="等这场战争结束后，我打算回杜隆塔尔去。$b$b在山上造一座小房子，或许还带一个小花园。$b$b嗯，听起来不错。"
D.Strings[64534]="等一会儿，我马上就让那个巨魔尖叫到半夜。"
D.Strings[64535]="去村里的主帐篷里找拉鲁姆·黑鬃吧。"
D.Strings[64536]="阿卡玛！为什么不捣毁他们的城镇？为什么还要给他们机会？"
D.Strings[64537]="兽人根本不可信。他们只是在拖延时间。"
D.Strings[64538]="别再谈什么战争了，霍戈。影月谷终于可以迎来和平了。"
D.Strings[64539]="我的耳朵好疼！"
D.Strings[64540]="阿莎！好姑娘，我们走。卡格和奈鲁克遇到麻烦了！"
D.Strings[64541]="我去找卡格。你去找其他人！"
D.Strings[64542]="|TInterface\\Icons\\sha_ability_warrior_bloodnova.blp:20|t你制造出了一个|cFFF00000|Hspell:145066|h[投影]|h|r！"
D.Strings[64543]="敌人终于来了！投石车，自由射击！"
D.Strings[64544]="<这头狼用充满智慧的眼睛看着你。>"
D.Strings[64545]="|TInterface\\Icons\\ability_priest_halo_shadow:20|t%s开始施放|cFFFF0000|Hspell:143491|h[灾祸]|h|r！"
D.Strings[64546]="|TInterface\\Icons\\Ability_Siege_Engineer_Superheated.blp:20|t一座激活的激光炮台锁定了你！"
D.Strings[64547]="|TInterface\\Icons\\Ability_Siege_Engineer_Detonate.blp:20|t一个蛛形地雷瞄准了你！"
D.Strings[64548]="谢谢！我这就离开这儿！"
D.Strings[64549]="啊！啊啊啊！"
D.Strings[64550]="我得离开这儿！白痴兽人，我最讨厌兽人了！"
D.Strings[64551]="你是最棒的！"
D.Strings[64552]="这该死的鬼地方！"
D.Strings[64553]="别碰我！！"
D.Strings[64554]="万灵，请听从我的召唤！帮助这位倒下的战士吧！"
D.Strings[64555]="前线的沃金需要你！"
D.Strings[64556]="愿万灵保佑你。"
D.Strings[64557]="嘿，谢谢！在我离开之前，你要看看我的货物吗？都是刚从潘达利亚运来的新鲜货色。东西是不便宜，你也知道，现在可是战争时期。"
D.Strings[64558]="我是不会像其他人那样坐以待毙的！面对你们最惧怕的恶魔吧，叛徒"
D.Strings[64559]="哪来的臭味儿？"
D.Strings[64560]="别让他们过去！"
D.Strings[64561]="保护神殿！！"
D.Strings[64562]="酋长无视了我的议会。我发现他在怒焰裂谷的洞穴下造了个基地。"
D.Strings[64563]="萨尔和萨鲁法尔已经下去了。"
D.Strings[64564]="小心点。地狱咆哮把下面变成了一座兵工厂——里面有地精佣兵，熊猫人神器，我感觉到，还有某种黑暗存在。"
D.Strings[64565]="呆在我们后面！把头低下！"
D.Strings[64566]="一台自动伐木机正在靠近！"
D.Strings[64567]="我听到了一个元素之灵的声音。它非常强大！挡住那些鬣蜥人，我还需要一点时间。"
D.Strings[64568]="再给我多争取一点时间。"
D.Strings[64569]="库卡隆已经蓄势待发了。让他们来尝尝铁与血的滋味吧！"
D.Strings[64570]="几乎所有的部队都在这儿了。"
D.Strings[64571]="我有点不安，老朋友。"
D.Strings[64572]="我也是。我们完全不知道加尔鲁什到底有什么阴谋，也不知道究竟有什么在等着我们。"
D.Strings[64573]="我很担心族人的安全。"
D.Strings[64574]="这场战争过后，许多人都会死去。"
D.Strings[64575]="这有什么意义呢？部落到底能从中得到什么？加尔鲁什是个蠢货，叛徒。我早就该杀了他，就在他背叛我父亲时。"
D.Strings[64576]="你会有机会的，伙计。但首先我们得攻破这座城。"
D.Strings[64577]="你跟人类沟通过了吗？"
D.Strings[64578]="联盟和部落都已经向港口派出了舰队。我们得分出一些部队来进攻前门。"
D.Strings[64579]="这计划很大胆。但愿我们不会遇到什么意外。"
D.Strings[64580]="恐怕我们别无选择，伙计。"
D.Strings[64581]="别动，萨满。喘口气吧。让这位勇士继续前进，我们等你准备好之后再追上去。"
D.Strings[64582]="赞美艾露恩，$c。"
D.Strings[64583]="我们要击败加尔鲁什，重建部落！"
D.Strings[64584]="万灵将在战斗中指引我们。"
D.Strings[64585]="我很荣幸能和你并肩作战，$n！"
D.Strings[64586]="我们做好与加尔鲁什战斗的准备了。"
D.Strings[64587]="做好战斗的准备了吗，伙计？"
D.Strings[64588]="沃金才是真正的领袖。"
D.Strings[64589]="这些投石车可不会自己修好！"
D.Strings[64590]="干活，干活。嘿，我还有你呢，对吧？"
D.Strings[64591]="对我们来说，如今的奥格瑞玛已经不再安全了。"
D.Strings[64592]="我只希望我的家人都安好。"
D.Strings[64593]="加尔鲁什是个暴君，他抢走了我们的家园。"
D.Strings[64594]="希望这一切能早日结束。"
D.Strings[64595]="妈妈说，爸爸很快就能回家了。"
D.Strings[64596]="我一直听到大人们在说悄悄话。"
D.Strings[64597]="我也想战斗！我准备好了！"
D.Strings[64598]="我活下来，就是为了能再上战场。"
D.Strings[64599]="这点伤阻止不了我继续对付库卡隆。"
D.Strings[64600]="我们的大军一定能攻克奥格瑞玛！"
D.Strings[64601]="我召唤万灵并得到了回应，$r。"
D.Strings[64602]="战争能化敌为友，也能让挚友反目成仇。"
D.Strings[64603]="加尔鲁什已经没有退路了，$r，这也是他最危险的时候。"
D.Strings[64604]="萨尔是我的兄弟，但愿他安然无恙。"
D.Strings[64605]="我们最大的敌人是加尔鲁什，而不是联盟。"
D.Strings[64606]="正统部落必胜。"
D.Strings[64607]="这些叛军不值一提。加尔鲁什会将他们践踏于脚下。"
D.Strings[64608]="我盯着你呢，$r。"
D.Strings[64609]="你不会是叛军吧，嗯？"
D.Strings[64610]="我们总算逮住这个牛头人了。"
D.Strings[64611]="我真想捅死这家伙。"
D.Strings[64612]="把他绑到树上去！"
D.Strings[64613]="这些术士的恶魔契约会让他们倒大霉的。"
D.Strings[64614]="我们要根除奥格瑞玛的一切腐败。"
D.Strings[64615]="你们这些家伙身上的恶臭真让人作呕。你将和其他勾结恶魔的家伙一起付出代价。"
D.Strings[64616]="只有我才能把这些库卡隆变成合格的战士。"
D.Strings[64617]="等战斗打响时，他们就会感激我的严格训练了。"
D.Strings[64618]="我知道你在想什么，等你进攻时，这些库卡隆会做好准备的。"
D.Strings[64619]="在面对库卡隆的力量时，你最好三思而后行。"
D.Strings[64620]="Ishnu-alah，指挥官。"
D.Strings[64621]="很好！再来！"
D.Strings[64622]="加尔鲁什绝不容许失败。再来！"
D.Strings[64623]="加尔鲁什需要你们积累的财富。让我进入金库！"
D.Strings[64624]="让我们看看，你被打断骨头之后还能不能这么目中无人。"
D.Strings[64625]="我……我不能！不行！"
D.Strings[64626]="加尔鲁什绝不容许在奥格瑞玛的城墙之内进行恶魔崇拜。你们必须立刻投降并接受羁押，否则就得死。"
D.Strings[64627]="嘿，伙计，救救我们！快去找钥匙！"
D.Strings[64628]="谢了，伙计，我们会记住你的。"
D.Strings[64629]="多尤达放置了一个抗性图腾来协助你！"
D.Strings[64630]="在这儿！放我们出去！钥匙就在这附近！"
D.Strings[64631]="谢谢！我们欠你一份情！"
D.Strings[64632]="蛮锤萨满放置了一个抗性图腾来协助你！"
D.Strings[64633]="去死吧，$C！！"
D.Strings[64634]="我不是你的朋友！！！"
D.Strings[64635]="谢谢你把我们从白鬼手里救了出来，$n。要不是你，我真不敢想象我们的下场会怎样。"
D.Strings[64636]="不用客气。"
D.Strings[64637]="我失去了我的图腾。"
D.Strings[64638]="你的图腾？"
D.Strings[64639]="我已经几个星期都没有阖眼了，我的脑海中充斥着别人听不见的咆哮声。$b$b有哪个萨满会举不起她自己的图腾？我都得靠臂扣才能握住自己的战斧，又有什么资格去说贾纳尔错了？我不适合战争，我也不适合当萨满。$b$b我必须搞明白万灵给我的旨意。现在，只有它们能为我指出正确的道路。它们显然另有打算，否则我早就失去作为萨满的力量了。"
D.Strings[64640]="你这是自寻死路，小崽子。"
D.Strings[64641]="他走了。"
D.Strings[64642]="狂风之灵，请赐予我们风一样的速度。"
D.Strings[64643]="雷神兽人多半都没什么脑子，但他们懂得如何与巨人战斗。"
D.Strings[64644]="众所周知，他们喜欢把自己最得意的战术刻在臂甲上。我很好奇，他们到底是为了炫耀，还是纯粹因为记不住？"
D.Strings[64645]="万灵拯救了我，可这里太冷了。我的肺里好像有火在烧。"
D.Strings[64646]="我们到了。就是这片废墟。我……我恐怕不能跟你一起进去了。我的手臂在止不住地颤抖，这片土地仿佛都在我的脑海中咆哮。"
D.Strings[64647]="不……我不能……他们抢走了我的孩子！"
D.Strings[64648]="我很抱歉！"
D.Strings[64649]="求求你，找到我的孩子们！"
D.Strings[64650]="求你，放过我们！"
D.Strings[64651]="我们也不想这么做的！"
D.Strings[64652]="攻击！"
D.Strings[64653]="你还有什么要说的吗，熊猫人？"
D.Strings[64654]="看到这根蜡烛了吗？你最好在它烧完之前，说出熊猫人神器的秘密！快点说出来！"
D.Strings[64655]="很好，你要是不说，那留着你的脑袋也没用了。"
D.Strings[64656]="季肯定在这附近，我要找到他！"
D.Strings[64657]="噢，不，季！他们要砍掉他的头！"
D.Strings[64658]="他被他们打晕了！我得赶快做点什么！"
D.Strings[64659]="季！不！我要杀了你们！"
D.Strings[64660]="季……对不起……"
D.Strings[64661]="季，真是对不起，现在我们可以在一起了，我们回迷踪岛吧，你不要死。"
D.Strings[64662]="我要带他离开这里。"
D.Strings[64663]="呼……嗯？我听到了洛卡拉的声音……就在不久之前……"
D.Strings[64664]="我听到了洛卡拉的声音……就在不久之前……"
D.Strings[64665]="啊，可她是个猎人，而非猎物。和往常一样，她又冲在了狼群之前……"
D.Strings[64666]="继续前进吧，朋友。我会赶上你的。我只是需要恢复一下力气。"
D.Strings[64667]="呼……谢谢你……"
D.Strings[64668]="我的身躯已满是伤痕，可我的心中翻滚着仇恨。"
D.Strings[64669]="我一次又一次倒在兽人手下，一次又一次地站了起来。"
D.Strings[64670]="以后再也不会了。"
D.Strings[64671]="每一个欺负过我的兽人，我都要让他们加倍地偿还！"
D.Strings[64672]="我，加摩尔，会拯救大家！"
D.Strings[64673]="付出代价吧！"
D.Strings[64674]="我是痛苦的风暴！"
D.Strings[64675]="锦绣谷发生了一些可怕的事，但真正的悲剧在于，那里已经完全不适合钓鱼了。所有的珍宝斑马鱼！都完了！$b $b但你很走运，我听说东部海岸附近的一座岛上还能钓到珍宝斑马鱼。如果传言属实的话，你可以在那儿找到满满一湖的鱼。"
D.Strings[64676]="如果传言属实的话，你应该可以在这里找到珍宝斑马鱼。$b$b<班宏在你的地图上做了一个标记。>$b$b"
D.Strings[64677]="一个写满了熊猫人象形文字的古老卷轴。你怀疑只有在净化了寺院中煞能腐蚀之后，才能继续研究里面的内容。"
D.Strings[64678]="阅读卷轴。"
D.Strings[64679]="怒火就是力量！"
D.Strings[64680]="哇啊啊！！"
D.Strings[64681]="你们接受了审判，证明了自己的价值。但要小心，接下来，你们的灵魂将受到极限的考验。准备好之后，你们就能进入大厅了。"
D.Strings[64682]="嘘……小声点！"
D.Strings[64683]="谢谢你。妈妈肯定担心死我了！"
D.Strings[64684]="到了这儿，我就可以自己回岗哨去了。如果你有皮革需要处理，尽管来找我好了！"
D.Strings[64685]="腐蚀正在扩大。在它变得不可收拾之前，必须净化这些碎片。"
D.Strings[64686]="没有关系，它来了。坚定你们的心智，做好准备。"
D.Strings[64687]="你们……必须……阻止……它……"
D.Strings[64688]="保持谦卑。"
D.Strings[64689]="远离傲慢。"
D.Strings[64690]="啊，我们又要一起冒险了，但是，这次的局势恐怕会更加危险。"
D.Strings[64691]="噢，锦绣谷怎么成这样了？"
D.Strings[64692]="这片土地遭受了重创，水流干涸，盛开的鲜花、葱郁的草木纷纷枯萎凋零。"
D.Strings[64693]="来，让我们看看，加尔鲁什还引来了哪些噩梦。"
D.Strings[64694]="泰坦们曾用这些生命之水创造了潘达利亚所有的物种。"
D.Strings[64695]="是它们令锦绣谷四季长春，又在流入四风谷后形成了全世界最肥沃的农田！"
D.Strings[64696]="而现在，邪恶的上古之神寄生在这些水中。"
D.Strings[64697]="这污秽的东西——消灭它，别让它渗入泥土，污染整个潘达利亚。"
D.Strings[64698]="啊，你成功了！水流恢复了洁净。"
D.Strings[64699]="感受到它们所蕴含的生命活力了吗？"
D.Strings[64700]="锦绣谷还要很久才能复原，但是你给了我们希望！"
D.Strings[64701]="这不是……？噢，不不不。"
D.Strings[64702]="金莲教……他们曾经誓死保卫这片土地。"
D.Strings[64703]="没错！鲁克·石趾！你还记得我！你怎么了？"
D.Strings[64704]="我明白了。煞魔禁锢了他们的灵魂，汲取由他们的失败而产生的绝望。"
D.Strings[64705]="这比死亡更可怕——英雄们，请解救他们的灵魂！"
D.Strings[64706]="安息吧，我的朋友们。"
D.Strings[64707]="愿你们的灵魂融入这片你们誓死守卫的土地。"
D.Strings[64708]="太惊人了！又一座由这些“泰坦”建造的殿堂。"
D.Strings[64709]="它早在有史可考之前就被隐藏了起来。这一定是有原因的！"
D.Strings[64710]="在前面的大厅里，在我们祥和的土地下，沉睡着古神之心。"
D.Strings[64711]="噢！什么？你好！我是游学者周卓！"
D.Strings[64712]="深度腐蚀者？不，我们是来阻止腐蚀，拯救潘达利亚的！"
D.Strings[64713]="是的！请让我们过去！"
D.Strings[64714]="祝踏岚！"
D.Strings[64715]="别说话，朋友，我马上送你去找大夫。"
D.Strings[64716]="我这就去找援军！你要坚持挡住煞魔！"
D.Strings[64717]="英雄们，你们还好吗？援军来了。"
D.Strings[64718]="周卓……外来者……这都怪他们……真不该让他们进来……"
D.Strings[64719]="<佳娜紧张地四下张望着，然后悄声说道。>$B$B他们……走了吗？"
D.Strings[64720]="打破锁链。"
D.Strings[64721]="如果你不出现，那我就轻松多了，卡德加。"
D.Strings[64722]="我打算潜入那个恶魔的巢穴。我们一起抓住它。"
D.Strings[64723]="在这里。"
D.Strings[64724]="我又不是缩在你斗篷下的孩子，科达娜。"
D.Strings[64725]="我们继续跟着他们。等你恢复过来之后就跟上来吧。"
D.Strings[64726]="快，阿莎！跟上他们！"
D.Strings[64727]="我们走，天狼！跟上他们！"
D.Strings[64728]="等等。援军应该很快就到了。"
D.Strings[64729]="我们的工作至关重要。"
D.Strings[64730]="干得好。我会把它带回岗哨并盯紧它的。"
D.Strings[64731]="启动仪式吧。"
D.Strings[64732]="钢铁部落还在不断从南方发起攻击。"
D.Strings[64733]="我们该怎么办？"
D.Strings[64734]="你。"
D.Strings[64735]="快去告诉阿卡兰娜·迅蹄，就说战局已经失控了。"
D.Strings[64736]="不！我要拿你们的骨头去喂她的小崽子！！！"
D.Strings[64737]="%s正准备发动|cFFFF0404|Hspell:144485|h[地震冲击]|h|r！"
D.Strings[64738]="我们来战斗吧！"
D.Strings[64739]="我今天没有机会挑战至尊天神，但我期待看到你的进步。祝你好运，$n。"
D.Strings[64740]="深度腐蚀者严禁进入中央大厅！"
D.Strings[64741]="你们想要净化腐蚀？"
D.Strings[64742]="如果就这样让你们进去，你们一定会失败的。你们，全都被名为“傲慢”的恶疾腐蚀了。"
D.Strings[64743]="当你们准备好面对自己的心魔，再来跟我说话吧。"
D.Strings[64744]="很好，我会制造一个空间来隔离你们的腐蚀。"
D.Strings[64745]="证明自己吧，那我才能让你们通过。"
D.Strings[64746]="|TInterface\\Icons\\spell_shadow_shadesofdarkness.blp:20|t%s开始施放|cFFF00000|Hspell:142842|h[亚煞极之息]|h|r！"
D.Strings[64747]="光明净化一切，但它绝不温和。做好准备，接受净化吧！"
D.Strings[64748]="看清你的内心，净化其中的黑暗。"
D.Strings[64749]="面对你们的心魔吧！"
D.Strings[64750]="在光明中得到净化吧！"
D.Strings[64751]="只有纯洁的心灵才能通过！"
D.Strings[64752]="光明不会被你们玷污。"
D.Strings[64753]="他到过这里……我让他们溜了。"
D.Strings[64754]="我很抱歉，阿莎。要是我训练时再刻苦一点……要是我能再快一点就好了。"
D.Strings[64755]="你把自己逼得太紧了，细爪。"
D.Strings[64756]="啊！我的勇士来了！"
D.Strings[64757]="啊！我来自翡翠林的老朋友！"
D.Strings[64758]="等等，等等——我可不能把故事搞错了。"
D.Strings[64759]="你为了爱情而奔走杀戮，细爪。可你还得想想整个狼群，和你自己的安全。"
D.Strings[64760]="马卡！我说过了，别那么叫我……"
D.Strings[64761]="这个传奇将在熊猫人中代代相传！"
D.Strings[64762]="阿莎。如同雨过天晴。她会好起来的。她很坚强，就像你。"
D.Strings[64763]="它由一位英雄谱写。"
D.Strings[64764]="我要去落雷堡了，萨满。我要救出卡格，哪怕是要赔上我自己的性命。"
D.Strings[64765]="一个来自迷雾之外的陌生人！"
D.Strings[64766]="不，我可不会那么想。"
D.Strings[64767]="征服了陌生的新大陆！"
D.Strings[64768]="一定要用“征服”这个词吗？"
D.Strings[64769]="深入被遗忘的宝库……"
D.Strings[64770]="我会召集岩牙岗哨里最强大的骑兵。去巨人的阴影与愤怒的群山交汇之处找我们吧。"
D.Strings[64771]="用怒火折服了螳螂妖和魔古族。"
D.Strings[64772]="我们要让猎手芬里斯看看，有些人是不会因为他的淫威而屈服的。"
D.Strings[64773]="谢谢你，马卡。"
D.Strings[64774]="凭力量和智慧攫取了更光辉的荣耀！"
D.Strings[64775]="你血脉中的狼群之魂和你心中的爱火在支撑着你战斗。这是宝贵的天赋，别浪费了它们。"
D.Strings[64776]="当战火降临，我们的英雄早有准备。"
D.Strings[64777]="这位万众爱戴的英勇先驱，让敌人望风披靡。"
D.Strings[64778]="就连雷电之王，都倒在这位勇士的脚下。"
D.Strings[64779]="雷神那古老帝国的秘密也被一一破解。"
D.Strings[64780]="发现了令全世界受益的知识。"
D.Strings[64781]="获得了战争与征服的力量！"
D.Strings[64782]="然后，上古尊者会将这个世界赐予螳螂妖！"
D.Strings[64783]="我要畅饮你的鲜血！"
D.Strings[64784]="等等，不太对劲——这是我所说的那个英雄吗？"
D.Strings[64785]="享用敌人的鲜血吧！"
D.Strings[64786]="我的刀上又多了一个缺口。"
D.Strings[64787]="兄弟们，为我复仇！"
D.Strings[64788]="我亲手造就的毁灭使者，他将永远改变艾泽拉斯的面貌。"
D.Strings[64789]="干掉你们简直易如反掌，就像过去屠杀熊猫人一样。"
D.Strings[64790]="你们的速度太慢了，这副德性还怎么捕猎？"
D.Strings[64791]="我需要力量！"
D.Strings[64792]="我的朋友，请认真考虑要为后人留下什么。"
D.Strings[64793]="看到了吗？速度才是王道！"
D.Strings[64794]="看呐！它暗藏泰坦之力，注入了我的巨龙精华，由睿智的熊猫人天神淬炼。"
D.Strings[64795]="太慢了。"
D.Strings[64796]="看看他们倒下的样子，活像狂风中的杂草。"
D.Strings[64797]="这该死的甲壳，我还不够快！"
D.Strings[64798]="它无所不能。守护还是毁灭，尽在你的掌握！"
D.Strings[64799]="这不合理，他们没听到你的警告吗，克尔鲁克？"
D.Strings[64800]="下等头脑理解不了混沌的秩序！"
D.Strings[64801]="来玩个游戏吧？"
D.Strings[64802]="过来，勇士！来接受你应得的奖励吧！"
D.Strings[64803]="有趣的共性，让我来利用一下吧！"
D.Strings[64804]="我要把你们分一下类……"
D.Strings[64805]="我早就预测到类似的结果了。"
D.Strings[64806]="太容易解决了，你们毕竟不算复杂！"
D.Strings[64807]="我的计算，出错了？或许还要800年……"
D.Strings[64808]="我们忍受着篡位者和他子民的行径，熬过了上古尊者的陨落，很快……就轮到你们了。"
D.Strings[64809]="来面对至尊者，向高等种族低头吧。"
D.Strings[64810]="琥珀保护着我们。"
D.Strings[64811]="上古尊者赐予我们力量。"
D.Strings[64812]="篡位者抛弃了你。"
D.Strings[64813]="我们是不会受伤的。"
D.Strings[64814]="故事会如何继续？"
D.Strings[64815]="让我回到琥珀的怀抱……"
D.Strings[64816]="没关系，上古尊者是不会被他们侵扰的。"
D.Strings[64817]="来吧，小恐虫们，喂食时间到了！"
D.Strings[64818]="你的心智比以前更脆弱了。"
D.Strings[64819]="这可不是佐尔洛克的独门绝招。"
D.Strings[64820]="要想知道，只有一个办法。"
D.Strings[64821]="很合我的小宝贝们的胃口。"
D.Strings[64822]="科沃克……过来……我需要……"
D.Strings[64823]="熊猫人的传奇诞生了！赞颂我们的新英雄，$n吧！"
D.Strings[64824]="来吧，泰坦之子，来面对英杰的挑战。"
D.Strings[64825]="该做点瞄准练习了。"
D.Strings[64826]="没错……一个重要目标。"
D.Strings[64827]="情报显示，这是一个极具价值的目标。"
D.Strings[64828]="又干掉一个，又一座奖杯！"
D.Strings[64829]="瞄准练习结束。"
D.Strings[64830]="啊……猎人……变成了猎物……"
D.Strings[64831]="螳螂妖所信奉的力量，比他们和伪神更强大。"
D.Strings[64832]="想试试我的新药吗，唤醒者？我保证你从未尝过这种滋味。"
D.Strings[64833]="好品种太多了，我该选哪种呢？"
D.Strings[64834]="所有的反应都需要恰当的催化剂。"
D.Strings[64835]="我的炼金术无与伦比！"
D.Strings[64836]="恰当的合剂是无所不能的！"
D.Strings[64837]="我一直没能发现……阻止死亡的……药物……"
D.Strings[64838]="看呐，兄弟们，唤醒者来了！"
D.Strings[64839]="让我最后送你一程，唤醒者，飞向你的末日。"
D.Strings[64840]="我是风中落叶！"
D.Strings[64841]="看我如何飞翔！"
D.Strings[64842]="我可是警告过你的，唤醒者。"
D.Strings[64843]="打得好，唤醒者，后会有期……"
D.Strings[64844]="他们竟能走到这里？我早说了，其他人需要一些微波基因改造。"
D.Strings[64845]="很好……全新的试验品！"
D.Strings[64846]="成功了！他们还活着！"
D.Strings[64847]="自然进化所需的时间太长了。让我来帮你一把……"
D.Strings[64848]="该死！早夭导致数据丢失了。"
D.Strings[64849]="唔，已经死了？我在想，微波深度基因探测能不能让他们复苏……"
D.Strings[64850]="或许我应该……强化一下……我自己……"
D.Strings[64851]="看看这儿！一个与世隔绝的、完整的生态圈，与已知的所有时间流都毫无牵连！$b$b很少有东西能让我这样的人感到吃惊。我一定要好好珍惜在这里度过的每一秒钟。"
D.Strings[64852]="还记得我们役使全视之眼监视暗影议会的事吗？"
D.Strings[64853]="我……死得其所。"
D.Strings[64854]="胡扯。我已经搞定了，游刃有余。"
D.Strings[64855]="战歌兽人绝不投降！"
D.Strings[64856]="我就知道。你应该留在要塞里的，大法师。"
D.Strings[64857]="卡德加会跟我们一起去。来吧，索姆瓦尔就在山的另一边。"
D.Strings[64858]="我已经侦查过这片丘陵。一股恶魔能量已经感染了一些野兽。"
D.Strings[64859]="我们确信这里的事和暗影议会有关，但我们还没找到确凿的证据。"
D.Strings[64860]="你们都给我滚远点！"
D.Strings[64861]="唔……看来这些兔子就是造成本地瘟疫的罪魁祸首。"
D.Strings[64862]="你们高高在上，居功自傲，它会让你们走向灭亡。"
D.Strings[64863]="要想击败腐蚀，首先要净化自己内心的腐蚀。"
D.Strings[64864]="纳兹戈林辜负了我们。库卡隆，消灭入侵者！"
D.Strings[64865]="我是不会辜负酋长的！"
D.Strings[64866]="加尔鲁什赐予我力量！"
D.Strings[64867]="你竟敢挑战酋长？"
D.Strings[64868]="看看正统部落的力量吧！"
D.Strings[64869]="让酋长的力量湮没你们吧！"
D.Strings[64870]="正统部落是……不可阻挡的！"
D.Strings[64871]="站起来……面对我吧！"
D.Strings[64872]="为酋长而死……是我的……荣幸……"
D.Strings[64873]="所向披靡！"
D.Strings[64874]="这是酋长的命令！"
D.Strings[64875]="钢铁战蝎向你发射了一束|cFFFF0404|Hspell:144918|h[切割激光]|h|r！"
D.Strings[64876]="凯诺兹！来认识一下，这位是我最出色的帮手。"
D.Strings[64877]="说说看，这里为何如此奇特？"
D.Strings[64878]="我就是喜欢研究这些特别的东西。"
D.Strings[64879]="……我喜欢你这个想法！"
D.Strings[64880]="我们不知道！所以我才会到这里来。"
D.Strings[64881]="这里的时间是凝固的。岛上充满生机，却又亘古不变。"
D.Strings[64882]="不久前，这里还为迷雾所笼罩。那些被迫滞留于此的居民只能自行铸造能够抵抗时间扭曲的货币。只有这样，才能进行交易。"
D.Strings[64883]="我也是！永恒岛的存在证明许多原本被视为疯狂的设想是完全有可能实现的。"
D.Strings[64884]="确实。在大灾变之后，青铜龙军团与时间流的联系彻底改变了。"
D.Strings[64885]="如果能像捏泥巴一样塑造时间，那会怎么样？历史会变成什么样？我们能创造出怎样的新世界？"
D.Strings[64886]="|TInterface\\Icons\\racial_orc_berserkerstrength.blp:20|t%s进入了|cFFF00000|Hspell:142879|h[血之怒]|h|r状态！"
D.Strings[64887]="我能看出你的灵魂有多么空虚，$n。最后的赢家一定是我！"
D.Strings[64888]="开始收服全视之眼。"
D.Strings[64889]="|TInterface\\Icons\\racial_orc_berserkerstrength.blp:20|t%s的|cFFF00000|Hspell:142879|h[血之怒]|h|r消退了！"
D.Strings[64890]="蠢货！这里已经被龙喉氏族控制了！你们将和这些船只一起葬身火海！"
D.Strings[64891]="增援部队快去码头！Lok'tar Ogar！"
D.Strings[64892]="你们自以为能赢？我们是兽人！是史上最伟大的酋长领导下的纯血兽人！你们的鲜血将染红这片海湾！"
D.Strings[64893]="龙喉氏族，夺回码头，把他们赶到海里去！以地狱咆哮和正统部落的名义！"
D.Strings[64894]="下一队，前进！"
D.Strings[64895]="龙喉氏族，前进！"
D.Strings[64896]="他们攻破了塔楼，摧毁它！"
D.Strings[64897]="那就让他们光荣地战死吧！"
D.Strings[64898]="让攻城武器攻击那座塔，把他们都活埋了！"
D.Strings[64899]="迦拉卡斯，喷火烧死他们！"
D.Strings[64900]="国王陛下！我带来了援军。"
D.Strings[64901]="我可以打开通向码头的传送门——足以让突击队通过。"
D.Strings[64902]="龙喉氏族在支持着酋长。"
D.Strings[64903]="我们现在急需火力支援。"
D.Strings[64904]="噢——谢谢！"
D.Strings[64905]="她将攻城武器对准了自己的塔楼！"
D.Strings[64906]="干掉一个，还剩一个！"
D.Strings[64907]="成功了！始祖龙掉下来了！"
D.Strings[64908]="我们会守住码头，等待后续登陆部队。沿着这条路到奥格瑞玛的城门那里去，找到沃金和他的起义军。"
D.Strings[64909]="我召唤了暴风雪，把他们引进去！"
D.Strings[64910]="我……坚持……不住了……"
D.Strings[64911]="瓦里安！不！瓦里安！"
D.Strings[64912]="你还活着！很好。城里的街道已经乱作一团了。"
D.Strings[64913]="库卡隆正在煽动这群乌合之众。他们还不肯投降！"
D.Strings[64914]="我们都等得望眼欲穿了。沃金的起义军没有能守住海湾。我们遭到了重创。"
D.Strings[64915]="去吧！等我们肃清这里，就能顺利登陆了。勇士们，我就指望你们了。"
D.Strings[64916]="干得好！登陆小队，集合！步兵打头阵！"
D.Strings[64917]="是的。斥候们已经发现了。“督军扎伊拉”。只要把她的始祖龙打下来，龙喉氏族就会崩溃。"
D.Strings[64918]="占领那些塔楼！调转炮口，把她给我从天上打下来！"
D.Strings[64919]="你们得留下一部分人，守住登陆区域。"
D.Strings[64920]="我不能再受伤了！"
D.Strings[64921]="沉重的一击！"
D.Strings[64922]="她正在调集更多的攻城武器！"
D.Strings[64923]="两个都完蛋了！开炮！"
D.Strings[64924]="它向我们冲过来了。小心！"
D.Strings[64925]="哈！他们要是再大一点……"
D.Strings[64926]="让我们看看，他到底能不能完成自己的承诺。"
D.Strings[64927]="把他们引到我的剑下来！"
D.Strings[64928]="吉安娜！你这个兽人杂种！"
D.Strings[64929]="安度因……"
D.Strings[64930]="沃金的起义军被压制了，但我们守住了阵线。"
D.Strings[64931]="我们得留下一些部队。斥候去侦察一下，看能不能把加尔鲁什揪出来。"
D.Strings[64932]="那塔里面还有我们的部队！"
D.Strings[64933]="刃拳海湾的防御增强了——这简直是屠杀！"
D.Strings[64934]="英雄们。快传送到码头，摧毁他们的海防工事，阻止这场杀戮。"
D.Strings[64935]="希尔瓦娜斯！不准碰我们的尸体，否则我现在就干掉你。"
D.Strings[64936]="……呃，那是你和联盟之间的事，不是吗？"
D.Strings[64937]="干得好。第一纵队已经成功登陆了。"
D.Strings[64938]="要用战术，黑暗女王。我们得重新布置海防工事。"
D.Strings[64939]="英雄们，占领那些塔楼，把枪口对准那条始祖龙，把它打下来！"
D.Strings[64940]="你们得留一部分人守住滩头阵地。"
D.Strings[64941]="啊，这下好多了。"
D.Strings[64942]="看来她要攻击自己的塔楼了！"
D.Strings[64943]="我们已经成功一半了！"
D.Strings[64944]="真不容易！看来我得换身衣服了。"
D.Strings[64945]="谢谢你的赞美。我们得守住码头，指挥部队。沃金应该就在奥格瑞玛的城门前等你们。"
D.Strings[64946]="我正在召唤烈焰风暴，把他们引进去！"
D.Strings[64947]="这……血……是从哪儿来的？"
D.Strings[64948]="噢，天呐，我们的黑暗女王怎么了？"
D.Strings[64949]="我能复活死者，摄政王，让你的游侠重返战场。"
D.Strings[64950]="可惜啊，你真是缺乏奉献精神。那人类的尸体呢？"
D.Strings[64951]="来吧，我的天使们！用尖叫声让奥格瑞玛的街道颤栗吧！"
D.Strings[64952]="加尔鲁什真是豁出去了，对吧？说实话，我本以为要多费一些手脚的。"
D.Strings[64953]="看来龙喉氏族把宝押在加尔鲁什身上了。"
D.Strings[64954]="光凭我的箭没法把那头怪物打下来。"
D.Strings[64955]="快把她打下来，然后我要活活掐死她。"
D.Strings[64956]="此时此地，我是不会倒下的！"
D.Strings[64957]="勇敢的一击。"
D.Strings[64958]="她又去攻击塔楼了。"
D.Strings[64959]="你也发现我们就在它下边，对吧？"
D.Strings[64960]="噢，你还活着呢？我还真希望你死掉。你的尸体一定很迷人。"
D.Strings[64961]="如果他还没死的话。"
D.Strings[64962]="死亡已经逼近！让他们偿命吧！"
D.Strings[64963]="我都等不及要看看他被复活后的表情了。"
D.Strings[64964]="我还会……回来的……"
D.Strings[64965]="点燃导火索！他们休想活着离开这里！"
D.Strings[64966]="至少……我是光荣地……战死……"
D.Strings[64967]="你们竟敢攻击我的塔楼？哈哈哈……"
D.Strings[64968]="我是龙喉兽人，我是巨龙血脉、部落之拳！"
D.Strings[64969]="你们……休想赢得……这场战争……"
D.Strings[64970]="我父亲把他的笔记放在哪儿了？肯定就在这附近……"
D.Strings[64971]="没有秘密配方，叫我怎么做秘制面汤啊？"
D.Strings[64972]="真该死，没有了祖传秘方，我要怎么把祖传的面摊经营下去啊？"
D.Strings[64973]="谁还要汤！"
D.Strings[64974]="啊，有新客人来了，欢迎欢迎！"
D.Strings[64975]="做好汤面的诀窍就在于筋道的面条！"
D.Strings[64976]="面汤一定要烧得滚烫，才能温暖食客的心！"
D.Strings[64977]="这就要走了吗？下次再来！"
D.Strings[64978]="这就要走了吗？请告诉你的朋友，务必要来林家面摊尝尝我们的秘制汤面。"
D.Strings[64979]="已经要关门了？好吧，我得回家去看潮薇了。"
D.Strings[64980]="祝你们好运，英雄们。很荣幸能和你们并肩战斗。"
D.Strings[64981]="欢迎来到比武大会，$n。你想学学怎么指挥宠物战斗吗？"
D.Strings[64982]="我酝酿着一场真正的战斗，就看你能不能应付了。"
D.Strings[64983]="宠物对战是艾泽拉斯有史以来最棒的游戏，可我见过不少人在战斗中表现得就像三岁小孩儿。你又能好到哪里去呢？"
D.Strings[64984]="天神比武大会的历史几乎和潘达利亚一样古老。许多人都曾来这里检验自己的勇气。我们可以开始了吗？"
D.Strings[64985]="你到底是来欣赏美女还是来打架的？"
D.Strings[64986]="我从没想过自己会有跟动物交流的天分，直到这些小家伙的出现。那么，你想来打一场吗？"
D.Strings[64987]="我让一个巨魔巫医把我的武僧们给变小了，以迎合比赛的体型要求。你想跟他们打一场吗？"
D.Strings[64988]="你能在活水面前赢得胜利吗？"
D.Strings[64989]="你赢了，算你走运。但愿你的礼物盒里装满死老鼠。"
D.Strings[64990]="干得好，$n。你的战斗力就跟我的酒量一样强！"
D.Strings[64991]="好吧，呃，我得再回顾一下战局。从头想起！"
D.Strings[64992]="今天你战胜了我，但你必须具备一切优良品质才有可能面对至尊天神。"
D.Strings[64993]="独狼难逃，群狼易生。"
D.Strings[64994]="你是怎么给亡灵浣熊治疗的？"
D.Strings[64995]="看来我们还得多练习练习。"
D.Strings[64996]="你战斗起来就像暴怒的河水一样凶猛。但愿你的勇气永不干涸。"
D.Strings[64997]="欢迎你来参加这一特殊的试炼！领袖的智慧要靠他的追随者来反映。让我们来看看你能否真正激励你的追随者……"
D.Strings[64998]="在这场试炼当中，你不能治疗自己的宠物。伟大领袖的特质之一就是能够将不同背景的属下团结在同一面旗帜之下。"
D.Strings[64999]="今天，你将面对许多成名已久的驯宠高手。你的宠物是否也能证明你的优秀呢？让我们拭目以待！祝你好运！"
D.Strings[65000]="啊，你把宠物养得很好，还击败了潘达利亚最老道、最杰出的驯宠师。但试炼，还远未结束！"
D.Strings[65001]="你将要面对智慧、力量、坚毅与希望的真正化身——至尊天神的后裔！请多加小心，他们拥有着失传已久的强大力量和神秘技巧。"
D.Strings[65002]="为我们的新冠军欢呼吧！你展现了自己的内在力量，并由你的宠物表现了出来。他们很幸运，能拥有如此强大的领袖。愿至尊天神之道在危急关头指引你。"
D.Strings[65003]="我们已经站在了战争的悬崖边上。当你的部队准备好之后，就给我发信号吧，然后我就会下达进攻的指令。"
D.Strings[65004]="加尔鲁什还要杀害多少人才会满意？能在这里攻击奥格瑞玛的城墙既是我的耻辱，也是我的荣幸，但我很高兴能有你们这样的英雄在我身边。"
D.Strings[65005]="就是这里了，英雄。当你们做好进攻准备后，就给我发信号吧。噢，还有，别让希尔瓦娜斯女王乱来，好吗？"
D.Strings[65006]="我会尽力的，摄政王阁下。我的部队已经准备好了。"
D.Strings[65007]="说说我的故事吧……"
D.Strings[65008]="幸会，$n。"
D.Strings[65009]="我准备好发掘林家秘制汤面的秘方了！"
D.Strings[65010]="这将是一个单人场景战役。你确定要继续吗？"
D.Strings[65011]="格罗姆加尔就在东南方。你只要找一副巨型骨骼就对了——肯定不会认错路的。"
D.Strings[65012]="卡格应该不会走这么远的。"
D.Strings[65013]="格罗姆加尔，它建在一个巨人的遗骸中。看看这玩意儿的块头……"
D.Strings[65014]="封锁南部塔楼的大门被攻破了！"
D.Strings[65015]="他在那儿！卡格！"
D.Strings[65016]="封锁北部塔楼的大门被攻破了！"
D.Strings[65017]="我可不想再见识一下这玩意儿的尾巴了。"
D.Strings[65018]="以加尔鲁什酋长的名义，守住阵线！"
D.Strings[65019]="用钢铁碾碎他们！用血海湮没他们！"
D.Strings[65020]="为了阵亡的将士们，杀光他们！"
D.Strings[65021]="你们休想看到任何东西！"
D.Strings[65022]="你的祖先将在痛苦中煎熬！"
D.Strings[65023]="今天真是个收服恶魔的好日子！"
D.Strings[65024]="迦拉卡斯摇晃了一下，又从冲击中恢复了过来！"
D.Strings[65025]="%s从她的坐骑上掉了下来！"
D.Strings[65026]="快跑啊！！！"
D.Strings[65027]="愿艾露恩的光辉赐予我力量！"
D.Strings[65028]="沐浴着……艾露恩的光辉……坦白吧，恶魔！"
D.Strings[65029]="屈服在艾露恩的威能之下吧！"
D.Strings[65030]="哇啊啊啊！！！"
D.Strings[65031]="够了！我愿意帮你们查看古尔瓦……"
D.Strings[65032]="我要碾碎它！（白鬼才是关键。）"
D.Strings[65033]="这些幽灵看起来很愤怒！快杀了它们！"
D.Strings[65034]="欢迎，$n。快请坐。"
D.Strings[65035]="我听说这地方有很棒的汤面。"
D.Strings[65036]="我都快饿死了。"
D.Strings[65037]="我听说他们发现了失传的林家秘制汤面秘方。"
D.Strings[65038]="总算有位子了，那么，该吃点什么呢？"
D.Strings[65039]="我要点哪种面呢？"
D.Strings[65040]="好多品种啊，我不知道该选哪个了！"
D.Strings[65041]="太好吃了！"
D.Strings[65042]="啊……美味的汤面总能让我身心舒畅。"
D.Strings[65043]="我从没吃过这么好吃的汤面。你们有什么秘诀吗？"
D.Strings[65044]="这里上菜真慢。"
D.Strings[65045]="等不下去了，我还是去石犁村吧。听说那边有奇美拉肉片卖。"
D.Strings[65046]="要是他们继续这么下去，那这儿经营不了多久。"
D.Strings[65047]="这面是不错，可我点的不是这个，厨师都不知道我点的是什么面吗？"
D.Strings[65048]="我吃过比这更好的面。"
D.Strings[65049]="唔，对我来说还不够辣。"
D.Strings[65050]="不……不能就这样……结束……我看到了……"
D.Strings[65051]="%s正准备施放|cFFFF0404|Hspell:143343|h[震耳尖啸]|h|r！"
D.Strings[65052]="月之女祭司还有话要问你。"
D.Strings[65053]="小心点。这种石头好像会引来附近树林里的生物。"
D.Strings[65054]="%s被嗜血的索克吞噬了！"
D.Strings[65055]="不像你，你的宠物都很可爱。"
D.Strings[65056]="我被加入了幸灾乐祸的程序。哈哈。哈哈。哈哈。"
D.Strings[65057]="这可真遗憾。"
D.Strings[65058]="来看看真正的宠物吧。"
D.Strings[65059]="感觉如何，$r？"
D.Strings[65060]="如果我有感情——那我也不会为你感到难过的。"
D.Strings[65061]="一台来历不明的大型设备在你面前嗡鸣。它的一侧刻着一行小字：\n\n|TInterface\\Icons\\inv_gizmo_02:20|t |cFFDD2222[地精泰坦控制模块]|r\n\n它似乎受到了声音识别模块的保护。"
D.Strings[65062]="用力踢这台机器。"
D.Strings[65063]="雪怒是不会被打败的。他在战斗中是如此优雅。"
D.Strings[65064]="在雪怒面前，他们毫无取胜的希望。"
D.Strings[65065]="幸好我没下场。"
D.Strings[65066]="欢迎，$n。我已经在市集上为半山的第一家面摊腾出一块空地了，由你来经营！"
D.Strings[65067]="这将是一场值得你去向朋友们炫耀的战斗，伊莱。"
D.Strings[65068]="客人们会排队等待你的招呼。但他们只愿意等一小会儿，所以你必须在他们离开之前招呼他们入座。"
D.Strings[65069]="坐下之后，客人会等着你给他们上面。和排队一样，你要在他们离开前送上他们要的食物。"
D.Strings[65070]="提示：你可以从客人的穿着打扮上看出他们的需求。"
D.Strings[65071]="有些客人特别饿，会在吃完之后再要一碗。"
D.Strings[65072]="小心。我可不想让你摔到赛场里去。"
D.Strings[65073]="有些客人比较性急，不愿等太久。但如果你能迅速招呼好他们，他们就会很开心。"
D.Strings[65074]="现在，快去煮汤面吧！"
D.Strings[65075]="哇，我今天真是胃口大开啊！"
D.Strings[65076]="你的宠物已经完蛋了。"
D.Strings[65077]="我的嗅觉感应器检测到一股烧焦的味道。"
D.Strings[65078]="真糟糕。现在，来见识下真正的宠物吧。"
D.Strings[65079]="|TInterface\\Icons\\sha_ability_rogue_sturdyrecuperate.blp:20|t%s开始施放|cFFF00000|Hspell:144563|h[囚禁]|h|r！"
D.Strings[65080]="你不觉得吗？这地方很神奇！"
D.Strings[65081]="嘿，$n。要来尝尝我的热汤面吗？"
D.Strings[65082]="塔楼里的援军拒绝撤离岗位！"
D.Strings[65083]="这里真是热火朝天啊！"
D.Strings[65084]="谁说火焰不美丽？"
D.Strings[65085]="没人能理解我……"
D.Strings[65086]="人人都兴高采烈的，除了我。"
D.Strings[65087]="他们干嘛要让我来看守这些愚蠢的死狼？……这不公平。"
D.Strings[65088]="我的守望永不停歇，但我很珍惜这个短暂的假期。"
D.Strings[65089]="一场精彩的战斗总能令我肾上腺素飙升。"
D.Strings[65090]="这里聚集了来自各行各业的人们。今天，我们都是观众，来此观看这些史诗般的战斗。"
D.Strings[65091]="干嘛这么吃惊，$n？$b$b我早就跟你说了。潘达利亚是一片充满未解之谜的神奇土地。"
D.Strings[65092]="挑战至尊天神将考验你的决心、技巧并唤醒你的崇高精神。$B$B你准备好了吗？"
D.Strings[65093]="可惜没有酿酒比赛。我从没见过这么多酒仙聚在一起！"
D.Strings[65094]="今天，就让我们看看谁能打败至尊天神，谁又会被打得一败涂地吧。"
D.Strings[65095]="在联盟对熊猫人做出了那些事之后，他们居然还被允许来到这里！"
D.Strings[65096]="如果走运的话，我们或许能看到哪个联盟狗被撕成碎片。"
D.Strings[65097]="愿酋长指引你走向胜利。"
D.Strings[65098]="嗯？你想跟至尊天神打架吗，蠢蛋？$B$B卡哈卡哈很乐意看热闹，但不会出手帮你。"
D.Strings[65099]="该死的锦鱼人居然也来了！$B$B$n愿意帮卡哈卡哈干掉几个锦鱼人吗？"
D.Strings[65100]="愿意给卡哈卡哈一把亮闪闪的武器吗？$B$B想想看，要是卡哈卡哈有了这么一把武器，能干出多少大事啊！"
D.Strings[65101]="当我们在地狱咆哮之拳上第一次见到潘达利亚时，谁能想到这里还会有这种地方的存在？"
D.Strings[65102]="两个字：轰隆！$B$B我想说的是，像这样的盛会，如果能再来一两桶炸药就更好了。"
D.Strings[65103]="我正在研究一项能把你的理智炸飞的新发明！$B$B或许还能让你的其他肢体一起瘫痪。"
D.Strings[65104]="让我们看一场精彩的战斗吧！"
D.Strings[65105]="这真的很刺激，不是吗？"
D.Strings[65106]="能在与煞魔斗争之余稍稍休息一下，这种感觉可真不错。"
D.Strings[65107]="非离最好小心摆弄她那些焰火。"
D.Strings[65108]="安静点！笨狗。"
D.Strings[65109]="这地方可真是安宁祥和。它完全没有被肆虐大陆的战火所波及。"
D.Strings[65110]="忠于自我，你的决心就会变成强大的冰川。"
D.Strings[65111]="玩家控制了北部塔楼的防空炮台！"
D.Strings[65112]="一只螳螂妖试图跟踪我到这里。$B$B他的下场可不太好。"
D.Strings[65113]="这座岛上一定会有很多奇遇的！"
D.Strings[65114]="我看出来了，这里会有很多乐趣的！"
D.Strings[65115]="放松点。你还有朋友呢。"
D.Strings[65116]="保持警惕，但也别忘了享受生活中的小乐趣。美食，好友，还有美酒！"
D.Strings[65117]="我们可以通过观摩他人的战斗学到很多东西。"
D.Strings[65118]="能见到雪怒和其他至尊天神真是我的荣幸。"
D.Strings[65119]="我觉得自己根本不可能去挑战任何一位至尊天神。"
D.Strings[65120]="听说这座岛屿不受时光的侵蚀。在这里肯定能发现许多神奇的东西！"
D.Strings[65121]="我从没见过这样的水。它会说话，可我听不懂它说的是什么。"
D.Strings[65122]="好好打，为你的同胞争光吧！"
D.Strings[65123]="你有出色的战斗技巧，也有坚定的战斗意志。但愿有一天我也能像你一样。"
D.Strings[65124]="|TInterface\\Icons\\achievement_dungeon_ulduarraid_titan_01.blp:20|t你受到了|cFFF00000|Hspell:144359|h[泰坦之赐]|h|r的祝福！"
D.Strings[65125]="客人吃完之后，他们坐过的位子还需要清洁。你只需要点击它们，我就会去清洁了。"
D.Strings[65126]="我都想自己下场试试了……但现在还不行。"
D.Strings[65127]="在与魔古族战斗过之后，其他敌人又能比他们强大多少呢？"
D.Strings[65128]="站直了！"
D.Strings[65129]="至尊天神的子民们，天神比武大会将考验你们在宠物战斗中的领导能力，以及你们能否做个成功的领袖。"
D.Strings[65130]="对不起，老板……"
D.Strings[65131]="我要参加天神比武大会。"
D.Strings[65132]="我能用天神铸币买到些什么？"
D.Strings[65133]="我很仰慕赤精。伟大的朱鹤或许能传授一些智慧给我。"
D.Strings[65134]="大家都在努力战斗。大家都在开怀畅饮。大家都很开心！"
D.Strings[65135]="你也该喝一杯！干！祝你开心！"
D.Strings[65136]="这里的时间是停滞的，这样真好。肯肯希望比试永远不要结束！"
D.Strings[65137]="我很高兴看到砮皂依然健壮。"
D.Strings[65138]="在更多冲突降临之前，我们一定要好好享受这段团聚的时光。"
D.Strings[65139]="我好久没这么放松过了！"
D.Strings[65140]="我不是战士。我只是个种菜养牦牛的。$B$B你去打，我就看看。"
D.Strings[65141]="勇士……你成功了……"
D.Strings[65142]="你何不表现一番，让我开开眼界呢？"
D.Strings[65143]="凡人很难拥有这种精神和力量。真的——我试过很多人！"
D.Strings[65144]="我正考虑在这里种点庄稼。$B$B你能想象，如果我在这里种下一颗谜之种，会发生什么事吗？"
D.Strings[65145]="要完成我们的伟大目标，还需要一片圣地。"
D.Strings[65146]="快去锦绣谷吧，到闻道之座来找我。"
D.Strings[65147]="一个传奇诞生了！"
D.Strings[65148]="参加天神比武大会有什么要求？"
D.Strings[65149]="只有经过充分训练的人才能参加比武大会。\n\n当你拥有15只满级宠物时，你才能获得参赛资格。"
D.Strings[65150]="再跟我说说比武大会的事吧。"
D.Strings[65151]="洛卡拉！亲爱的！你在这儿做什么？！"
D.Strings[65152]="你说呢？当然是来救你的！"
D.Strings[65153]="奈鲁克呢？"
D.Strings[65154]="我们走散了。阿莎呢？"
D.Strings[65155]="呼，我就知道，德拉卡比她表现出来的要强得多。"
D.Strings[65156]="这些小鸡现在或许还很小，但它们很快就会长大的！"
D.Strings[65157]="少打架，多种田。我跟你说，这才是生活。$B$B当然，如果你想打架，我也不妨来看看。"
D.Strings[65158]="哼。想当年，我们可得翻过一座雪山才能觐见至尊天神的。"
D.Strings[65159]="我很乐意与你并肩战斗，但你并没有向我求助。"
D.Strings[65160]="我很期待能看到一位真正的$c全部的潜力。"
D.Strings[65161]="对我而言，竞技场有点太吵了，但能看到这么精彩的比赛还是值得的。"
D.Strings[65162]="你喜欢我今天这身打扮吗？"
D.Strings[65163]="祝你能在这里交上好运！"
D.Strings[65164]="真不敢相信，农夫老愚和农夫老方都来了！$B$B这叫我一个姑娘家该怎么办啊？"
D.Strings[65165]="让我们坐下来喝杯冰镇啤酒，好好聊聊吧？"
D.Strings[65166]="许多阡陌客都赶来看比赛了。再没有比精彩的战斗和冰镇啤酒更棒的消遣了！"
D.Strings[65167]="好好打，但可别忘了去照料你的农场！"
D.Strings[65168]="赛场上的激烈战斗可以帮助你保持状态，迎接未来的挑战。"
D.Strings[65169]="这座岛上隐藏着许多秘密。你得把它们找出来。"
D.Strings[65170]="见到像你这么强大的$r总是一件令人高兴的事。"
D.Strings[65171]="历史正在被创造……"
D.Strings[65172]="我显然已经离家万里了！"
D.Strings[65173]="……有意思。"
D.Strings[65174]="我很少打架，但这真的很刺激！"
D.Strings[65175]="英雄，你是一个榜样！"
D.Strings[65176]="这会是一个很精彩的故事的，你不觉得吗？"
D.Strings[65177]="我早知道，你会成为伟大的人。"
D.Strings[65178]="我一早上都在跟至尊天神们搏斗！"
D.Strings[65179]="大好的机会送上门来了！我敢肯定，激发你斗篷潜力的关键就在永恒岛。"
D.Strings[65180]="一座失落在时间长河中，永不日落的海岛。这意味着什么呢？"
D.Strings[65181]="力量！荣耀！宝藏！"
D.Strings[65182]="全是我们的！英雄，来永恒岛找我吧。"
D.Strings[65183]="发生了那么多的事！这难道不刺激吗？"
D.Strings[65184]="我很想亲眼看看这座岛。或许我们还会在那里相见？"
D.Strings[65185]="哇！你真是狠狠教训了他们一顿啊！"
D.Strings[65186]="最近怎么样啊，老板？跟蒙蒙来喝一杯吧！"
D.Strings[65187]="蒙蒙尝过老酒湾的啤酒。太难喝了！"
D.Strings[65188]="反正我现在不用种田，这真是个消遣的好去处！"
D.Strings[65189]="在战斗之余，别忘了好好休息。一个好$c应该懂得劳逸结合。"
D.Strings[65190]="燃烧军团的威能会降临到你们的世界！"
D.Strings[65191]="一个鲜嫩多汁的月之女祭司。你会变成一顿可口的小点心，可爱的德拉丝。"
D.Strings[65192]="我都看见了！你们全都逃不过我的怒火！"
D.Strings[65193]="蒙蒙不够耐心，没法独立工作。$B$B我正试图帮他放慢节奏。"
D.Strings[65194]="啊……尊贵的卡德加。你的苦难史将成为传奇。"
D.Strings[65195]="德拉诺微不足道。它会像阿古斯一样陨落。总有一天，你们的世界也将被毁灭！"
D.Strings[65196]="这个可悲的陷阱困不住我。你最好现在就放我走，那我或许还能大发慈悲给你个痛快。"
D.Strings[65197]="噢！你好啊！我……呃……没想到能在这儿遇见你！$B$B<艾拉突然回头向竞技场看去。>"
D.Strings[65198]="熊猫人将世代传颂你的事迹。"
D.Strings[65199]="那些粉色的仙鹤真漂亮！$B$B我是说……如果你想知道的话……"
D.Strings[65200]="噢，我得去看看我的猫咪们了。但愿它们一切都好！"
D.Strings[65201]="这地方真古怪，到处都充斥着强大的魔力。"
D.Strings[65202]="我不敢在这里开传送门。这么做的后果会……很有趣的。"
D.Strings[65203]="我听说岛上藏着许多宝藏。"
D.Strings[65204]="来面对我的斧头吧！"
D.Strings[65205]="为了霜狼氏族！"
D.Strings[65206]="这是什么？！两条迷路的野狗？！而且还是两条找死的野狗！"
D.Strings[65207]="我永远不会忘记我父亲的牺牲。"
D.Strings[65208]="啊！！该死的……野狗……"
D.Strings[65209]="你早就该杀了我的，现在已经迟了。那么，我的狼在哪儿？！"
D.Strings[65210]="我知道。所以我们最好在那之前找到他。"
D.Strings[65211]="他们想要驯服他？奈鲁克死也不会屈服的！"
D.Strings[65212]="要说我不珍惜这个放松的机会，那是假的。"
D.Strings[65213]="这些比赛让我想起了自己接受新兵训练时的日子。"
D.Strings[65214]="这里没有战争的空间。"
D.Strings[65215]="为荣耀而战。"
D.Strings[65216]="战士的责任是永无止尽的。"
D.Strings[65217]="住手，召唤者。放过我的族人，你要找的东西在我们脚下，就在审判祭坛里。"
D.Strings[65218]="部署设备！建立防御带！"
D.Strings[65219]="噢，你们好，朋友们！我们已经差不多肃清了地面，看来真正的战斗还在下面！"
D.Strings[65220]="别担心，我们会支援你们的！前进吧，英雄们！"
D.Strings[65221]="噢，快看那个姑娘。真漂亮，10分！"
D.Strings[65222]="10分？哈！这也就是在剃刀岭了。在奥格瑞玛，她最多也就6分。"
D.Strings[65223]="你听说了吗？迪娜·泥爪也来了。$B$B不知道农夫老愚和农夫老方发现没有……"
D.Strings[65224]="总算不用打理市集了，真是太轻松了。"
D.Strings[65225]="我真该带一辆餐车来的。在这里绝对能赚大钱！"
D.Strings[65226]="能量……枯竭……"
D.Strings[65227]="你的力量将这片土地从恒古的黑暗中解救了出来。我很荣幸能亲眼见证你的事迹，勇士。"
D.Strings[65228]="好虚弱……"
D.Strings[65229]="黑暗之星背弃了我……"
D.Strings[65230]="这棵树就是希望的象征。但愿你所做的一切能让这片土地痊愈，并更加繁荣昌盛。"
D.Strings[65231]="你总能打动我，$n。"
D.Strings[65232]="太迟了，女祭司。我们已经知道了你那个宝贝“预言”。"
D.Strings[65233]="现在……告诉我彩虹水晶到底藏在哪儿，不然就眼睁睁看着你的勇士们送命吧。"
D.Strings[65234]="要想治愈这片土地和我们自己的伤口，还有许多事情要做。多亏了你的帮助，我们再也不用担心亚煞极的七大吐息了。$b$b同时，煞魔也不再活动了，你的美名将与末代皇帝一样流芳百世。"
D.Strings[65235]="来喝一杯吧，$c？"
D.Strings[65236]="带着决心去战斗吧，朋友。"
D.Strings[65237]="能和至尊天神战斗真是叫人羡慕。"
D.Strings[65238]="和老朋友一起渡过的时光总是宝贵的。"
D.Strings[65239]="这座岛上藏着许多未解之谜。"
D.Strings[65240]="我们今天可走运了。好多人都来托运东西了。"
D.Strings[65241]="你很有冠军像哦，$r。"
D.Strings[65242]="忙碌的土地精才是好土地精！"
D.Strings[65243]="愿你的美酒醇香，心志坚定。"
D.Strings[65244]="你的故事还将继续，朋友。$B$B这个故事很有看头。"
D.Strings[65245]="你战斗起来就像个真正的$r。"
D.Strings[65246]="再也没有比环游世界，谱写你的故事更有趣的工作了。$B$B这就是云游者之道。"
D.Strings[65247]="这种场合怎么能少了美酒呢！"
D.Strings[65248]="想跟我一起去岛上探险吗？"
D.Strings[65249]="你看到那些烟火了吗？真漂亮！"
D.Strings[65250]="至尊天神都好高大啊！"
D.Strings[65251]="哇，你肯定是个$c吧？$B$B$C最厉害了！"
D.Strings[65252]="影月兽人毫无征兆地打了过来。快，勇士，帮我们守住上层平台！"
D.Strings[65253]="战斗和啤酒。再也没有比这里更棒的地方了。"
D.Strings[65254]="下次我请！"
D.Strings[65255]="今天是个好日子。"
D.Strings[65256]="我的密探遍布各个大陆，可没有一个人能明白地告诉我，奥格瑞玛到底出了什么事！"
D.Strings[65257]="该死的国王！"
D.Strings[65258]="你休想离开这里。你回不去了。"
D.Strings[65259]="要想离开这里，唯有一死。你的世界已经化为乌有了。"
D.Strings[65260]="你的朋友们都死了。"
D.Strings[65261]="你的盟友们抛弃了你。"
D.Strings[65262]="你不会成功的。你的事业毫无希望。"
D.Strings[65263]="你在盟友的眼中就是个弱者。"
D.Strings[65264]="你没有打败他的力量。你太软弱了。"
D.Strings[65265]="|cFFFF8040刺客阿奇|r对$n使用了|cFF71D5FF|Hspell:145427|h[脚踢]|h|r|cFFFF8040。|r"
D.Strings[65266]="|cFFFF8040奥术师卡凡|r对$n使用了|cFF71D5FF|Hspell:145530|h[法术反制]|h|r|cFFFF8040。|r"
D.Strings[65267]="在影月氏族发动攻击的前一刻，观星台的灯光熄灭了。"
D.Strings[65268]="我们可以在特鲁纳观星台上观测星象。"
D.Strings[65269]="先知的工作是非常重要的。"
D.Strings[65270]="在我还是个小女孩时，我就开始研习圣光之道了。"
D.Strings[65271]="星辰可以告诉我们过去与未来，只要你懂得解读它们的语言。"
D.Strings[65272]="有时，在寒冷而黑暗的夜晚，我能听见遥远的星辰在窃窃私语。<赛勒尼神经质地笑了起来。>听起来很蠢，是不是？"
D.Strings[65273]="影月兽人都是强大的萨满。"
D.Strings[65274]="有人说月亮是一个魅惑的美人，用她银色的光辉引诱着流浪者。那些沉溺在她光辉中的人……都会发疯。"
D.Strings[65275]="为了加尔鲁什酋长！！！"
D.Strings[65276]="快下来吧，玉儿。那上面不安全。"
D.Strings[65277]="如果你摔下来了，我可接不住你！"
D.Strings[65278]="拜托，快下来吧。你让我怎么去跟其他阡陌客交代啊？"
D.Strings[65279]="很好，摔下来吧。我不在乎。"
D.Strings[65280]="我学到了很多酿酒知识。我还没能酿出自己的酒，但快了！"
D.Strings[65281]="你现在有些什么？"
D.Strings[65282]="我将为你奉献一切，黑暗之星……"
D.Strings[65283]="虚空，请响应我的召唤！"
D.Strings[65284]="我愿将一切奉献给虚空……"
D.Strings[65285]="虚无的虚空……"
D.Strings[65286]="要来杯好酒吗？"
D.Strings[65287]="你看来需要喝一杯。"
D.Strings[65288]="没有好酒的战斗不是好战斗！"
D.Strings[65289]="再没有比美酒更好的东西了！"
D.Strings[65290]="再来一杯怎么样？"
D.Strings[65291]="你就像你喝的酒，$n——呃，但愿你喝的是烈酒吧。"
D.Strings[65292]="你打得很好，但你的战术完全错了。来喝一杯，好好想想吧。"
D.Strings[65293]="你看看，我可被打惨了！下次我得好好想几个计划。"
D.Strings[65294]="他为什么要打比赛？很显然，就是为了找死。"
D.Strings[65295]="风向对我有利。"
D.Strings[65296]="幸运的一击！"
D.Strings[65297]="我就知道会这样。"
D.Strings[65298]="虽败犹荣！"
D.Strings[65299]="休息一下吧，小朋友。"
D.Strings[65300]="你，呃，做好学习混沌之道的准备了吗？"
D.Strings[65301]="你太过执着于输赢，却没有停下来想想是否应该这么做。"
D.Strings[65302]="喔唷，你还真是不懂得敬畏自然啊，呃……我真是太吃惊了。"
D.Strings[65303]="胜利好在什么地方？那是一种让人刻骨铭心的暴力行为。你所说的胜利……呃，还是算了。"
D.Strings[65304]="死了？你是指灭绝吗？"
D.Strings[65305]="你的宠物完全是活该，自然已经决定了它的灭绝。"
D.Strings[65306]="我，我只是说生命，呃……是找不到出路的。"
D.Strings[65307]="这，这就是混沌理论。"
D.Strings[65308]="你队伍里那是什么啊，穆克拉？"
D.Strings[65309]="恐龙……粪便？粪便？"
D.Strings[65310]="你将要面对耐心！智慧！还有知识！你又有哪些优点呢，$n？"
D.Strings[65311]="今天你失败了——可你从中学到了什么呢？"
D.Strings[65312]="你教会了我很多，$r。看来老师又变成学生了。"
D.Strings[65313]="这是必要的牺牲。"
D.Strings[65314]="秋叶必须为春花让路。"
D.Strings[65315]="失败只是一个被失望所掩盖的教训。"
D.Strings[65316]="如同溪流遭遇悬崖就会变成美丽的瀑布，只要你懂得该从何处着眼。"
D.Strings[65317]="死亡将是一场神奇的大冒险。"
D.Strings[65318]="如果你失去了一项美德，就必须牢牢把握剩余的那些。"
D.Strings[65319]="这样的牺牲值得吗？"
D.Strings[65320]="噢，但愿你会喜欢惊喜。"
D.Strings[65321]="算你走运，这次还只是你的宠物……"
D.Strings[65322]="在天神比武大会上，向来都是你死我活的。"
D.Strings[65323]="把握机会，趁胜追击。"
D.Strings[65324]="噢，那是你最喜欢的宠物？我很抱歉。"
D.Strings[65325]="要不是本身很有意思的话，这么轻松的战斗就会很无聊。"
D.Strings[65326]="你这混蛋，我的宠物恐怕再也不能走路了！"
D.Strings[65327]="我们所珍爱的东西总会毁掉我们自己，$c，记住这句话。"
D.Strings[65328]="你要再敢伤害我的宠物，你今晚的酒杯里就会多出一滴毒药了。"
D.Strings[65329]="恐惧比利剑伤得更深。"
D.Strings[65330]="算你走运，吉兹莫来不了了，可我照样能把你打得落花流水，$c。"
D.Strings[65331]="这场胜利是送给你的，吉兹莫！"
D.Strings[65332]="哎，我指挥动物的本事也就这样了。这些绷带该怎么用？"
D.Strings[65333]="哈！这比我想象中还要管用！"
D.Strings[65334]="噢，抱歉，你待会儿恐怕要好好安慰安慰那家伙了。"
D.Strings[65335]="有那么一瞬间，我还以为我们要有大麻烦了。"
D.Strings[65336]="不！又输了！"
D.Strings[65337]="我这该死的运气！"
D.Strings[65338]="喂，你会为此付出代价的！"
D.Strings[65339]="别被他们娇小的体型给骗了，$n，他们可都是训练有素，行动敏捷的家伙。"
D.Strings[65340]="莽撞是失败的根源，你必须学会控制节奏。"
D.Strings[65341]="要想击败我的武僧们真的需要高明的战术。干得好，$n。"
D.Strings[65342]="跟我预想的完全一样。"
D.Strings[65343]="你缺乏必要的纪律。"
D.Strings[65344]="你还能靠剩下的宠物反败为胜吗？"
D.Strings[65345]="他为荣誉而战，也为荣誉而死。"
D.Strings[65346]="胜利总是需要牺牲的。"
D.Strings[65347]="当一名影踪派成员倒下时，总会有更多战友站出来顶上他的位置。"
D.Strings[65348]="就像水滴能令石穿，我们也将成为你的终结者。"
D.Strings[65349]="河流早就预言了这场胜利。"
D.Strings[65350]="河流早就预言了这场失败。"
D.Strings[65351]="他们连同那一点可怜的痕迹都被一起冲刷掉了。"
D.Strings[65352]="岩石总以为自己不可撼动，直到它身下的大地被一起冲走。"
D.Strings[65353]="让正义之水净化你吧！"
D.Strings[65354]="我的同伴被打散了。但她一定会在适当的时候卷土重来的。"
D.Strings[65355]="一块孤岩阻挡不了汹涌澎湃的河流。"
D.Strings[65356]="战斗中总是免不了会有高潮和低谷。"
D.Strings[65357]="亘古的呼唤唤醒了我。"
D.Strings[65358]="龙无论大小都是非常危险的，我一定会让你明白这一点的。"
D.Strings[65359]="如果我能赢得这样的战斗，那我或许就有机会战胜至尊天神了。"
D.Strings[65360]="干得好，$n。你明智地选择了自己的战友，并出色地领导了它们。"
D.Strings[65361]="我早就警告过你，龙是以其致命的攻击而著称的。"
D.Strings[65362]="哪怕是最强大的盟友也会倒在龙族魔法之下。"
D.Strings[65363]="玻璃做的火炮常常在开火前就会碎裂。"
D.Strings[65364]="你的力量超出了我的预料。"
D.Strings[65365]="真是出人意料。"
D.Strings[65366]="这真是个难以弥补的损失。"
D.Strings[65367]="轰！"
D.Strings[65368]="不要因为这儿的满目疮痍而绝望。"
D.Strings[65369]="很久很久以前，这片土地曾为猜忌、恐惧和仇恨的阴影所笼罩。"
D.Strings[65370]="我将其逐一制服——并深深埋入地下。"
D.Strings[65371]="可是……它们依然存在。"
D.Strings[65372]="一万年以来……浓雾保护着潘达利亚不受外敌的觊觎。"
D.Strings[65373]="当大灾变降临时，我意识到散去迷雾的时刻到了……我们要协助治愈这个破碎的世界。"
D.Strings[65374]="可当你们的舰队抵达我们的海岸，我昔日的猜忌和恐惧再次袭来，又一次在这片土地上肆虐。"
D.Strings[65375]="你战胜了那被封印已久的黑暗。"
D.Strings[65376]="向潘达利亚展示了一个真英雄的力量。"
D.Strings[65377]="但你是否仍有困惑：吾辈何以为战？"
D.Strings[65378]="直面恐惧。抛开仇恨。"
D.Strings[65379]="只有当自己静心忍性，才能做到万物归心，宠辱不惊。"
D.Strings[65380]="这些才是生命宝贵的真谛。"
D.Strings[65381]="告诉了我们何以为战。"
D.Strings[65382]="嘿，听起来马尔考罗克已经把那些入侵者给撕成碎片了。"
D.Strings[65383]="不知道，但我的感觉不太好。那边有点太安静了。"
D.Strings[65384]="它要从笼子里冲出来了！快用电击项圈控制住它！"
D.Strings[65385]="电击它，别让它动弹！真是一团糟！"
D.Strings[65386]="先对付魔暴龙，然后把剩下的关起来！"
D.Strings[65387]="蠢货！低能！"
D.Strings[65388]="我已经向游学者叙述了你的事迹，勇士。想听听你的故事吗？"
D.Strings[65389]="说说我的故事吧。"
D.Strings[65390]="小心点……我猜那些石头周围会有重兵把守。"
D.Strings[65391]="请发发善心，给它们一个痛快吧。那些生灵都是无辜的牺牲品。"
D.Strings[65392]="卡德加，我正在介绍情况。"
D.Strings[65393]="你好，先知。我们为一桩紧急事件而来。沃高尔的拯救者——$n，能为我们担保。"
D.Strings[65394]="你好，指挥官。很高兴再次见到你。"
D.Strings[65395]="她说的很对。暗影议会和古尔丹就躲在附近。我能感觉得到。"
D.Strings[65396]="让我们光荣地死去吧，$n！！"
D.Strings[65397]="你好，$n。你把我从这个洞里救了出来，我要谢谢你。请接受这份礼物以及我最衷心的感谢。"
D.Strings[65398]="我接受这份礼物。"
D.Strings[65399]="来吧。臣服于你的骄傲吧。让我看看你有多么“伟大”。"
D.Strings[65400]="多么愚蠢……"
D.Strings[65401]="你比其他人优秀多了！"
D.Strings[65402]="你的傲慢驱使着你……"
D.Strings[65403]="屈服于你的骄傲吧！"
D.Strings[65404]="你的傲慢让我壮大！"
D.Strings[65405]="不要向任何国王或酋长低头。"
D.Strings[65406]="你被骄傲蒙蔽了双眼，泰坦的傀儡。你休想阻止我！"
D.Strings[65407]="一个弱者。"
D.Strings[65408]="这家伙只会拖你们后腿。"
D.Strings[65409]="要怪就怪你的同伴吧！"
D.Strings[65410]="半个锦绣谷都被毁了！这些外来者的破坏性比螳螂妖和魔古族加起来还要大。"
D.Strings[65411]="我们到这儿是来帮忙的。我们可以帮忙重建锦绣谷。"
D.Strings[65412]="录像开了吗？开了？很好。地精泰坦控制模块启动，请退后。"
D.Strings[65413]="正在检查数据，请稍等，好吗？"
D.Strings[65414]="噢，那你来试试？那绝对绝对绝对不是正确的代码。"
