D.Strings[65421]="2号模组准备完毕，可以系统重置。"
D.Strings[65422]="系统重置中。请勿关闭电源，否则将发生爆炸。"
D.Strings[65423]="安全系统关闭。欢迎回来，攻城匠师黑索。"
D.Strings[65424]="|TInterface\\Icons\\ability_titankeeper_uncheckedcorruption.blp:20|t%s开始施放|cFFFF0000|Hspell:147011|h[暴怒具象]|h|r！"
D.Strings[65425]="祝你拥有美好的一天，出去时别让门夹了。"
D.Strings[65426]="|TInterface\\Icons\\ability_garrosh_empowered_whirling_corruption.blp:20|t%s开始施放|cFFFF0000|Hspell:144985|h[强化腐蚀漩涡]|h|r!"
D.Strings[65427]="系统正在关闭。嘿，有谁知道，这样正常吗？"
D.Strings[65428]="“末日决战”级防御系统全面上线。大爆炸来啦！"
D.Strings[65429]="你要敢停下，我就把你献祭给黑暗！"
D.Strings[65430]="你以为自己是来玩的吗，杂种？快干活儿！"
D.Strings[65431]="再加把劲儿！"
D.Strings[65432]="钢铁部落需要这些补给品。快点儿干！"
D.Strings[65433]="你想让钢铁部落碾碎我们吗？接着干！"
D.Strings[65434]="亲爱的皇上，我们来了。那些曾让您苦苦挣扎的邪恶和黑暗已经永远地远离了潘达利亚。"
D.Strings[65435]="可这代价…这惨痛的代价…"
D.Strings[65436]="小心点。恶魔会试图欺骗你的。"
D.Strings[65437]="小心。入侵者！"
D.Strings[65438]="这些外来者给这片土地带来了混乱。我们能够相信他们吗？"
D.Strings[65439]="见鬼！你找到了我的身体！看看这些老骨头。"
D.Strings[65440]="我还以为自己会更加激动呢……"
D.Strings[65441]="知道吗？我根本就不想要身体。我喜欢自由自在地飘浮。"
D.Strings[65442]="这头嗜鱼鹤死得很惨。$B$B它的身体上布满了齿痕和爪印，内脏也被吞吃一空。$B$B它显然成了某个家伙的一顿美餐。"
D.Strings[65443]="臣服于正统部落吧！"
D.Strings[65444]="为了加尔鲁什酋长！"
D.Strings[65445]="你的脑袋将是一个不错的战利品！"
D.Strings[65446]="加尔鲁什是所向无敌的！"
D.Strings[65447]="跟我来，$n。"
D.Strings[65448]="长久以来，我们德莱尼人与影月氏族勉强保持了和平共处。"
D.Strings[65449]="可自从钢铁部落来到我们的山谷，他们的侵略性就日渐增长。"
D.Strings[65450]="现在，他们似乎在寻找彩虹水晶——这种奇异的宝石中蕴藏着惊人的能量。"
D.Strings[65451]="无论如何，你能帮我去检查一下那些望远镜吗？"
D.Strings[65452]="你们是精英中的精英！是正统部落的中坚力量！"
D.Strings[65453]="古尔丹向你问好。"
D.Strings[65454]="我们的大军将动摇世界的支柱！"
D.Strings[65455]="不要对妨碍我们的敌人心慈手软！"
D.Strings[65456]="我们将为加尔鲁什酋长夺取胜利！"
D.Strings[65457]="|TInterface\\Icons\\ability_vehicle_demolisherflamecatapult.blp:20|t部落舰队开始进行|cFFFF0000|Hspell:147088|h[轰炸]|h|r！"
D.Strings[65458]="为了私利而去干扰时间流的家伙通常都很危险。\n\n所以我才加入了守望者的队伍，这是时光旅行者中的防卫部队。\n\n我们会在观察者和编织者执行任务时保护他们。"
D.Strings[65459]="我相信你已经领悟了：若因恐惧和愤怒而战，则此战永无休止。"
D.Strings[65460]="真是浪费！"
D.Strings[65461]="|TInterface\\Icons\\ability_garrosh_siege_engine.blp:20|t部落舰长发现了一处密集人群！开始发射|cFFFF0000|Hspell:147047|h[不稳定的钢铁之星]|h|r!"
D.Strings[65462]="又失败了！趁这头野兽还没失控，快干掉他！"
D.Strings[65463]="等我完善了灌注过程，亚煞极的力量将使我们所向披靡！"
D.Strings[65464]="编织者都是精通时间法术的魔法师，最擅长编织时间。\n\n在时光旅行者中，只有我们能修复受损的时间流，开启时光传送门，并执行其他类似的任务。\n\n这些事原本对青铜龙军团来说轻而易举，可惜，一切都变了。"
D.Strings[65465]="观察者是时光旅行者中的学者、斥候、研究员以及密探。\n\n我们观察时间流并记录、调查和报告时光的扰动和异常现象。\n\n也正是观察者将时光旅行者的目光引向这座时间凝固的小岛的。"
D.Strings[65466]="|TInterface\\Icons\\sha_ability_rogue_envelopingshadows.blp:20|t你受到了|cFFF00000|Hspell:146817|h[傲气光环]|h|r的影响！"
D.Strings[65467]="我这里有着皇帝陛下最珍贵的遗物。如果你想赢得少昊的青睐，就请帮我们赶走那些试图占据天神庭院的斡耳朵野牛人吧。"
D.Strings[65468]="让入侵者来吧！我已经等不及要砸碎他们的脑袋了。"
D.Strings[65469]="当然，这些懦夫很可能会悄悄溜过去而不敢直面我的怒火。"
D.Strings[65470]="对于那些胆小鬼，你还能指望什么呢？"
D.Strings[65471]="死在我手里可能就是他们最大的成就了。"
D.Strings[65472]="我能用永恒铸币买到些什么？"
D.Strings[65473]="%s引爆了不稳定的钢铁之星。"
D.Strings[65474]="让我们来解决它。"
D.Strings[65475]="好吧，伙计们，让他们看看黑索公司的战斗力！"
D.Strings[65476]="没人能打败黑索。没有人！"
D.Strings[65477]="别来打扰艺术家。"
D.Strings[65478]="噢，你会为此付出代价的……"
D.Strings[65479]="你这个……"
D.Strings[65480]="我的精神……永垂不朽……"
D.Strings[65481]="别以为你们已经赢了，你们这些瞎子。睁大眼睛好好看看！"
D.Strings[65482]="见证我充满荣耀的命运吧！啊哈哈哈！"
D.Strings[65483]="在我的世界里，你们无处容身！"
D.Strings[65484]="我会摧毁你们所钟爱的一切。"
D.Strings[65485]="不，不！这难道就是我的宿命……我的宿命…… "
D.Strings[65486]="我，格罗姆之子，加尔鲁什，会让你们看看地狱咆哮家族的力量！"
D.Strings[65487]="到这儿来，英雄。"
D.Strings[65488]="天哪。这就是多年以来一直侵扰着潘达利亚的恐怖生物。"
D.Strings[65489]="终于，它也归于沉寂，化为乌有。"
D.Strings[65490]="跟我来，英雄。我们回到山谷中去。有个人现在一定非常想知道事情的起承转合，如果他愿意搭理我们的话。"
D.Strings[65491]="你不出去才是对的！"
D.Strings[65492]="你来了！这么说都是真的？奥格瑞玛怎么了？"
D.Strings[65493]="卡兹达尔说他们知道预言……但这怎么可能？这真是个令人不安的消息。"
D.Strings[65494]="那个愚蠢的国王！！"
D.Strings[65495]="我准备好了一切，对他而言，整个世界已经唾手可得！"
D.Strings[65496]="当然，还是得打一仗。要想攻陷雷霆崖必然会伤亡惨重。但其他部落成员一定会逐渐崩溃。"
D.Strings[65497]="童福！拿酒来！快！"
D.Strings[65498]="什么？没错，我支持了联盟。"
D.Strings[65499]="我本以为地狱咆哮赢定了，结果他把部落搞得四分五裂。所以我改变了想法。"
D.Strings[65500]="%s战败并跪了下来。你的部队撤退了。"
D.Strings[65501]="|TInterface\\Icons\\ability_warlock_eradication.blp:20|t%s对|cFFFF0000$n|r施放了|cFFFF0000|Hspell:147209|h[恶意]|h|r！"
D.Strings[65502]="确定要认输吗？"
D.Strings[65503]="欢迎来到试炼场。你的首场试炼即将开始。请在时间用尽前击败所有的幻影。"
D.Strings[65504]="和以前一样，请在时间用尽前击败所有的幻影。但这次，你所面对的幻影将更强大。"
D.Strings[65505]="准备迎接最强大的幻影吧。在时间用尽前击败他们，你就胜利了。"
D.Strings[65506]="这个试炼将考验你的技巧极限。它永不结束，只会越来越难。"
D.Strings[65507]="成功了！干得好。来找我开启下一场试炼吧。"
D.Strings[65508]="时间到。要再试一次吗？"
D.Strings[65509]="幻影恶棍总是成群结队地出现，但完全无害。你可以用范围伤害技能快速击杀它们。"
D.Strings[65510]="幻影织珀者会召唤一些琥珀球向你飘去，并在接触后爆炸。将琥珀球引到其他幻影身边去吧！"
D.Strings[65511]="啊，幻影掷蕉兵。它会向你快速投掷香蕉，你可以通过移动来躲避。你要尽量避免让它拉开距离。"
D.Strings[65512]="幻影秘法师会治疗被重创的幻影。注意打断它的治疗法术！"
D.Strings[65513]="作为防御大师，幻影守卫会偏转来自正面的所有攻击。绕到它背后去！"
D.Strings[65514]="噢，幻影煞魔。等它的屏障消散，弱点暴露后再使用你最强的攻击！"
D.Strings[65515]="这个幻影杀戮者会测试你的伤害输出能力。别担心，它不会攻击的。"
D.Strings[65516]="幻影女妖！杀了它，快，别让它爆炸！"
D.Strings[65517]="你好。在试炼中，你必须在我对付幻影时保证我的生命。我是鸥图，我会保护你的。"
D.Strings[65518]="坚持住，我来了！"
D.Strings[65519]="我是钢铁之盾！但是我坚持不了多久了！"
D.Strings[65520]="幻影虫巢咏者来了！它们的音波能伤害整个团队。"
D.Strings[65521]="一个新挑战：幻影征服者！当它们暴怒时，它们的攻击凶狠异常。"
D.Strings[65522]="我失败了！抱歉，今后我会更加努力训练的。"
D.Strings[65523]="欧图，我老被攻击的话就没法全力输出了！"
D.Strings[65524]="刚才是水爆弹爆炸了？！下次快点驱散它！"
D.Strings[65525]="这些幻影侍水僧会对我们施放危险的魔法效果，快驱散它们！"
D.Strings[65526]="我倒下了。在那种紧急情况下，最好使用快速治疗。"
D.Strings[65527]="你好啊。这次的幻影会更多，我们需要更多的治疗。"
D.Strings[65528]="抱歉，隐身！"
D.Strings[65529]="他们已经很努力了，卡凡。礼貌点。"
D.Strings[65530]="苏立，快跑开！"
D.Strings[65531]="第一个敌人！幻影撕裂者只是普通战士。来干掉他们吧！"
D.Strings[65532]="幻影召焰者！各位，注意脚下！别站在岩浆里！"
D.Strings[65533]="我失败了！……我们再试一次吧！"
D.Strings[65534]="哦不！你忘记给自己治疗了吗？"
D.Strings[65535]="这次，幻影是不会后退的。它们会连续攻击。准备使用你最强的治疗手段吧。"
D.Strings[65536]="噢，天呐……飞毛腿，来帮忙！"
D.Strings[65537]="哈？……噢！"
D.Strings[65538]="啊，幻影隧道工。我和飞毛腿对付过这种敌人。小心，它们会钻洞，然后突然从新目标脚下冒出来狂啃！哈哈！"
D.Strings[65539]="啊啊……请照顾好……飞毛腿。"
D.Strings[65540]="这些幻影是无穷无尽的，但我们要尽力守住！"
D.Strings[65541]="哈哈！干得好，各位！朋友，去找罗敦开启下一轮试炼吧。"
D.Strings[65542]="我不会再倒下了！"
D.Strings[65543]="你是个高贵的兽人，纳兹戈林。很抱歉我必须这么做。"
D.Strings[65544]="你带着荣耀而战，加摩尔会让你的精神流传下去。为了部落，我的朋友。"
D.Strings[65545]="不能就这样……结束……"
D.Strings[65546]="你能否独立山巅，任由风霜侵袭，直至沧海变为桑田，高山沉入海底？"
D.Strings[65547]="风刀霜剑，四面受敌。"
D.Strings[65548]="不动如山，亘古不移。"
D.Strings[65549]="想要达到目标，你必须寸步不让。"
D.Strings[65550]="虽然被强大得超乎想象的敌人包围，毅力还是让你坚持了下来。在未来的日子里，请记住这一课。"
D.Strings[65551]="在面对空前的挑战时，你有着怎样的期盼？你想要怎样的未来？"
D.Strings[65552]="让我们开始吧。"
D.Strings[65553]="相信彼此，让别人为你带来希望！"
D.Strings[65554]="没有希望，未来就没有光明！"
D.Strings[65555]="去创造你想要的命运吧！"
D.Strings[65556]="不要放弃自己！"
D.Strings[65557]="你们的希望十分闪亮，你们团结起来后，它更是璀璨夺目。哪怕在最黑暗的地方，它也将照亮你们的道路。"
D.Strings[65558]="亲爱的英雄，真正的智慧就在你心中，也在你所作出的选择中。当面对压倒性的黑暗时，你能否作出正确的选择呢？"
D.Strings[65559]="试炼开始！"
D.Strings[65560]="倾听你内心的声音，找出真相吧！"
D.Strings[65561]="审时度势，别让危机干扰你的判断！"
D.Strings[65562]="考虑好行动的顺序！"
D.Strings[65563]="从错误中汲取教训！"
D.Strings[65564]="你的智慧帮你赢得了这次试炼。愿它能始终带你走出困境。"
D.Strings[65565]="力量。它不仅仅是指单纯的肉体强度。在面对真正的考验时，你是否能够分清力量与能力？"
D.Strings[65566]="哈哈！试炼开始！"
D.Strings[65567]="你拥有改变命运的能力！"
D.Strings[65568]="不要把黑暗之力错当成真正的力量！"
D.Strings[65569]="加倍奉还！"
D.Strings[65570]="你很强大，比你自己以为的还要强大。带着这个信念勇敢迎接黑暗吧，它将会庇佑着你。"
D.Strings[65571]="啊，总算能活动了。 Lok'tar Ogar！"
D.Strings[65572]="啊……哈……打得好……"
D.Strings[65573]="别傻了，沃金！你们没有攻城武器了！你是赢不了的！"
D.Strings[65574]="就算你们打败了它，可城门依然耸立。你们休想攻占奥格瑞玛。"
D.Strings[65575]="什么？库卡隆，到城门那边去！快！"
D.Strings[65576]="我从未被联盟打倒过。你觉得自己够强吗？"
D.Strings[65577]="我是纳兹戈林，酋长之拳，部落统帅。就算我今天难逃一死，也要光荣地战死沙场。为了部落！"
D.Strings[65578]="你训练得太糟糕了。"
D.Strings[65579]="我……虽死犹荣……Lok'tar Ogar……"
D.Strings[65580]="啊……加摩尔……你终于变强了……能死在……你的手上……是我的荣幸……"
D.Strings[65581]="啊……你学会了很多……学得很好……光荣的战斗。"
D.Strings[65582]="我最终站在了酋长一边，因为这是我的使命，很高兴打倒我的人是你。愿你的力量……带领部落……走向繁荣昌盛。"
D.Strings[65583]="这一天终于来了。多年来我们一起成长，一起学习，如今却在战场上兵戎相见。别幻想我会放过你，我也不会求饶。此时此刻，我们所做的一切，都是为了部落。"
D.Strings[65584]="能够与你一战是我的荣幸。Lok'tar Ogar，为了荣耀，为了部落！"
D.Strings[65585]="很久以前，睿智的青龙教会我净化自己的灵魂并与大地融为一体，我的疑虑就此被打消了。"
D.Strings[65586]="当旅程开始时，我只会鲁莽地运用自己的力量。白虎教我学会控制，从而征服了我的仇恨、愤怒和暴虐。"
D.Strings[65587]="朱鹤看到了我内心的希望，并且教我学会自省。透过绝望的表象，我发现了希望，并由此征服了绝望。"
D.Strings[65588]="在巨大的恐惧面前，玄牛教我懂得坚毅，让我在恐怖与黑暗的时代不屈不挠，征服恐惧。"
D.Strings[65589]="你通过了智慧的试炼，并领悟了青龙之道。愿你能像我一样，有所收获。"
D.Strings[65590]="你通过了力量的试炼，并领悟了白虎之道。愿你永远记住这一课。"
D.Strings[65591]="你通过了希望的试炼，并领悟了朱鹤之道。愿它永远指引你的脚步。"
D.Strings[65592]="你通过了坚毅的试炼，并领悟了玄牛之道。愿它永远护佑你的道路。"
D.Strings[65593]="我用尽了一切办法想要移走塌方的石头！可玄牛在上，我连一块石头都搬不动。或许我得去寺院里借一把传奇武器来才行……"
D.Strings[65594]="我的朋友，请到锦绣谷中心的繁盛矿洞附近来找我。我想给你看点东西。"
D.Strings[65595]="里克里克可是很有两下子的……"
D.Strings[65596]="噢，别那么惊讶！我可是黑龙。我只忠于我自己。"
D.Strings[65597]="里克喜欢烟火！"
D.Strings[65598]="里克有个主意。乱斗俱乐部！"
D.Strings[65599]="当河流转向时，我们应该顺应潮流，而非逆势而上。"
D.Strings[65600]="永远不要忘记你最伟大的朋友，他们会与你并肩作战，直到最后一刻。"
D.Strings[65601]="皇帝就快成功了，他击败了猜忌、仇恨、暴怒和恐惧。"
D.Strings[65602]="可那个白痴，白痴“国王”乌瑞恩！"
D.Strings[65603]="他怎能容忍新的“酋长”的出现！他本可以一统全世界。我真傻，居然会指望他的野心！"
D.Strings[65604]="我就该像奥妮克希亚一样，把王者之位抢过来。亲手搞定一切。"
D.Strings[65605]="%s拒绝撤离塔楼！"
D.Strings[65606]="请小心些，$n。\n\n至尊天神严禁联盟和部落在此地私斗。"
D.Strings[65607]="救命！把它们赶开！"
D.Strings[65608]="你往哪儿站呢？！离火焰远点儿！"
D.Strings[65609]="幻影撕裂者来了。它们算不上挑战，只是些没脑子的蛮兵。"
D.Strings[65610]="准备防御。那是幻影征服者！它们暴怒时，会造成极高的伤害，无人能挡！"
D.Strings[65611]="有新的敌人来了，幻影召焰者。它们会施放火球术并喷吐岩浆。好好利用这些岩浆，它们能烧死其他幻影！"
D.Strings[65612]="小心，幻影风卫士会用翅膀击退你，然后再转过头来攻击我！"
D.Strings[65613]="幻影伏击者！快吸引它们的主意，让它们离我远点，别让那些危险的香蕉击中我！"
D.Strings[65614]="幻影抢劫者进攻了！别让它们可爱的样子骗了，它们能合力造成极高的伤害。"
D.Strings[65615]="啊，我治疗不了那么高的伤害！你忘记换坦克装了吗？"
D.Strings[65616]="我失败了！或许下次我应该穿上治疗装备？"
D.Strings[65617]="你好。我是司佳丽，碎玉闪电、真气与治疗之雾的大师。在试炼中，你得保护我，挡住涌来的幻影。而我会治疗你并对付我们敌人。"
D.Strings[65618]="你好啊。我们的下一场试炼更具挑战性。准备保护我！"
D.Strings[65619]="这次，你还是要保护我。嘿，罗敦，来场真正的挑战吧！"
D.Strings[65620]="虽然失败无法避免，但是我们还是要尽力杀敌。做好准备！"
D.Strings[65621]="击败疑之煞后，你终于可以阅读这些卷轴了。"
D.Strings[65622]="你已经为获取这一失传的技艺做出了一切努力。"
D.Strings[65623]="出门在外，请多加小心。\n\n除了那些巨兽，这片海滩的另一头还有敌人的营地。"
D.Strings[65624]="%s恶毒地瞥了你一眼。"
D.Strings[65625]="帮我向卡德加问好。我为他准备了一个小礼物。"
D.Strings[65626]="好痛苦！"
D.Strings[65627]="有刺客！"
D.Strings[65628]="说，说，说！"
D.Strings[65629]="你只知道说，却从不倾听！你忽略了潘达利亚的教训！"
D.Strings[65630]="万物自有平衡之道。这智慧铭刻在我们的皮毛上：黑与白。黑暗与光明。"
D.Strings[65631]="当末代皇帝将我们的土地与外部世界隔离时，他也留下了我们的宿敌，螳螂妖。他为什么这么做？"
D.Strings[65632]="联盟和部落之间的战争也是一样。如果没有对方存在的话，他们也绝不会如此强盛。"
D.Strings[65633]="你把自己最大的优势当成了劣势。你明白吗？"
D.Strings[65634]="……他毁了我的酒馆，还不给小费。真没风度。"
D.Strings[65635]="呃？"
D.Strings[65636]="……你……你不过是个倒酒的！"
D.Strings[65637]="我发誓：我要不惜一切代价让这个世界做好战争的准备。"
D.Strings[65638]="下一次，我绝不会再失手。"
D.Strings[65639]="绝不！"
D.Strings[65640]="因为这才是一片完整的土地。一万年来，与螳螂妖的战争令双方都变得强大。"
D.Strings[65641]="祝你们玩得愉快。"
D.Strings[65642]="“哪怕血流漂杵，山岳岿然不动。”——砮皂"
D.Strings[65643]="“真理之光总在混沌的时代闪耀。”——玉珑"
D.Strings[65644]="“精诚团结，才能燃起希望之火。”——赤精"
D.Strings[65645]="“力量与气力的差别，就如日月般一目了然。”——雪怒"
D.Strings[65646]="祭坛被斡耳朵斯腐蚀了！"
D.Strings[65647]="点击一名排队的客人。如果点击成功，他们就会向你招手。"
D.Strings[65648]="|TInterface\\Icons\\ability_racial_timeismoney.blp:20|t|cFFFF0000|Hspell:146506|h[排队等候]|h|r"
D.Strings[65649]="选中一名客人后，点击一个空位，客人就会过去入座了。"
D.Strings[65650]="|TInterface\\Icons\\inv_misc_fork&knife.blp:20|t|cFFFF0000|Hspell:146448|h[等待食物]|h|r"
D.Strings[65651]="我们必须保卫池塘不受污染！"
D.Strings[65652]="我们的工作尚未结束！快阻止他们！"
D.Strings[65653]="保卫池塘！"
D.Strings[65654]="为你的客人煮汤面吧。这是一位学者，他们都喜欢简单清爽的汤面。试着做一碗吧。"
D.Strings[65655]="汤面做好了，现在，点击拿起它吧。如果放置太久，汤面就会坏掉。所以，你一定要按照客人的需求来煮面。"
D.Strings[65656]="现在，点击入座的客人，把汤面给他们送过去吧。"
D.Strings[65657]="好极了！现在你的客人就会开心地品尝你为他们煮的面了。吃完之后，他们也会高高兴兴地离开。"
D.Strings[65658]="你要离开营地吗？\n\n至尊天神已经要求我们岛上的部队停止推近了，所以我们就留在这里守卫登陆点。\n\n你要出去的话一定要小心。敌人也对这里表现出了兴趣。他们的营地就在海滩的另一头，且守卫森严。"
D.Strings[65659]="斡耳朵斯指引我的道路！"
D.Strings[65660]="烈火即真理！"
D.Strings[65661]="我的命运将由烈火来书写！"
D.Strings[65662]="你将在痛苦中死去！"
D.Strings[65663]="为了斡耳朵斯！"
D.Strings[65664]="誓死效忠火焰之神！"
D.Strings[65665]="为了永恒不灭的烈火！"
D.Strings[65666]="接受光明的审判吧！"
D.Strings[65667]="你……鲁克认识你……"
D.Strings[65668]="鲁克……不知道……头……好晕……"
D.Strings[65669]="我们满心绝望。这是失败者应得的惩罚。"
D.Strings[65670]="请……帮帮我们……"
D.Strings[65671]="不！我们还没完成！"
D.Strings[65672]="水流尚未净化！"
D.Strings[65673]="在我们完成工作前，必须阻止这些闯入者！"
D.Strings[65674]="你必须保护我。"
D.Strings[65675]="保卫主人的重担就交给你了。"
D.Strings[65676]="你在掺和自己完全不了解的事情。"
D.Strings[65677]="|TInterface\\Icons\\INV_MISC_FOOD_COOKED_GREATPABANQUET_POT.BLP:20|t|cFFFF0000|Hspell:146498|h[饥肠辘辘]|h|r"
D.Strings[65678]="|TInterface\\Icons\\ability_hunter_posthaste.BLP:20|t|cFFFF0000|Hspell:146497|h[焦躁不安]|h|r"
D.Strings[65679]="看来$n已经决定要治疗并复活他的宠物了！$g他:她;在比武大会中的进度已被重置，需要重新进行挑战。"
D.Strings[65680]="快去告诉主人！"
D.Strings[65681]="弄到那头恶魔的心脏后，就去山上的熔炉附近找我吧。"
D.Strings[65682]="快。将这些碎片熔铸成对付古尔丹的灵魂陷阱。"
D.Strings[65683]="小心点，朋友。不管你准备得多么充分，古尔丹始终是个不可小觑的对手。"
D.Strings[65684]="我可没那么好对付。"
D.Strings[65685]="拉索恩，该轮到你了。"
D.Strings[65686]="什么？不……"
D.Strings[65687]="没关系。很快我就会有充足的魔血来为燃烧军团制造出千军万马。"
D.Strings[65688]="卑贱的小崽子。死亡就是他最大的成就了。"
D.Strings[65689]="啊哈哈哈哈……你们太迟了。现在，水晶已经被送去沙兹古尔了。"
D.Strings[65690]="/叹气"
D.Strings[65691]="离开的顾客太多了。你要再试一次吗？"
D.Strings[65692]="为什么不？"
D.Strings[65693]="这是你用来猎兔子的长矛吗？"
D.Strings[65694]="没错，我都不想要那根长矛了……"
D.Strings[65695]="Throm-Ka，伟大的霜狼氏族的战士们。"
D.Strings[65696]="因为它被这个小鬼的弱者之血玷污了。"
D.Strings[65697]="我们必须找到暗影议会的基地并解决掉他们。"
D.Strings[65698]="那么……你怎么看？"
D.Strings[65699]="守望者，让我们去向索姆瓦尔的先知介绍一下情况吧。"
D.Strings[65700]="想想看：这个地方完全在我们的时间流之外——而且已经存在了上千年！\n\n我们最有经验的编织者已经确认，这座岛的时空坐标目前还是稳定的，可我还是忍不住会想……\n\n万一这岛在我们滞留期间又消失了该怎么办？"
D.Strings[65701]="指挥官，就请你来为我们介绍一下情况吧。"
D.Strings[65702]="霜狼氏族的勇士，如果他们是你的朋友，那他们就是我们的客人。"
D.Strings[65703]="感谢您，皇上。感谢您。"
D.Strings[65704]="好痛苦。"
D.Strings[65705]="战斗吧，我的兄弟们。让他们知道战歌氏族的厉害。"
D.Strings[65706]="兔子都很软弱。"
D.Strings[65707]="请发发善心，给它一个痛快吧。狼母才是这里真正的受害者。"
D.Strings[65708]="钳爪蟹害怕地逃开了！"
D.Strings[65709]="迦拉卡斯被击中了！打得好！"
D.Strings[65710]="我做好去面档上工的准备了！"
D.Strings[65711]="我们支持德兹科和他的决定。我们要奋起反抗魔古族、蜥蜴人、煞魔甚至是部落酋长。如有必要，我们愿意保护这座山谷直至最后一人。"
D.Strings[65712]="这次是你赢了！"
D.Strings[65713]="我要把你的尸体烧成灰烬！"
D.Strings[65714]="都几个小时了，太阳却一直没动过……"
D.Strings[65715]="这是什么造成的？"
D.Strings[65716]="这是熊猫人的秘密，我的小王子！迷雾中的秘密。"
D.Strings[65717]="没错。时间在此凝固。万物难逃因果，因果本是虚无。"
D.Strings[65718]="我会找到这个答案！究竟是因为迷雾？还是一万年前的大分裂所释放出的能量？我们必须好好调查！"
D.Strings[65719]="是的。此地推翻了我们对时间的认识，以及宇宙形成的理论。"
D.Strings[65720]="这里有着全潘达利亚最危险的生物。如果你坚持，安度因王子，你可以去探索一番。但请务必小心。"
D.Strings[65721]="你好，$c。你发现永恒岛的秘密了吗？"
D.Strings[65722]="你能相信吗？世上居然有这种地方的存在！这里有太多需要学习和发现的东西了！在这里的发现绝对能让我著作等身。$b$b但它们的信息量太大了，我不知道有谁能读完它们。查德里克觉得我们该把它们写成歌谣，但这太蠢了……对吧？"
D.Strings[65723]="你们的路到此为止了，懦夫！只要我还活着，你们休想打开这些门！"
D.Strings[65724]="……杀了……我。"
D.Strings[65725]="[%s]忏悔：我已经好几个月没去过日歌农场了。我都能想象出那里杂草丛生，兔妖遍地的样子了。"
D.Strings[65726]="[%s]忏悔：我曾经试图杀死雷施，而非雷神。"
D.Strings[65727]="[%s]忏悔：我曾经以为麦迪文是德鲁伊，因为他身上插满了羽毛。"
D.Strings[65728]="[%s]忏悔：我到现在还留着银色北伐军的天灾石。天知道它们什么时候又能派上用场。"
D.Strings[65729]="[%s]忏悔：我为我的地面坐骑感到难过。我几乎不怎么用它们了。"
D.Strings[65730]="[%s]忏悔：我要抢光那个猎人的装备。"
D.Strings[65731]="[%s]忏悔：我很疑惑，为什么女性德莱尼长得像侏儒。"
D.Strings[65732]="在你的触摸下，水晶振动了起来！"
D.Strings[65733]="卡德加——这里有人！"
D.Strings[65734]="凛风之地属于战歌氏族。"
D.Strings[65735]="这比我想象中要困难地多。"
D.Strings[65736]="一棵？"
D.Strings[65737]="一后面是几来着？"
D.Strings[65738]="有多少棵树？"
D.Strings[65739]="又一棵。"
D.Strings[65740]="很多个一棵。"
D.Strings[65741]="今天，有一团明亮的火焰在天空中爆散，$B$B一块巨大的白色石头就落在我们村子下面的平原上。$B$B我们不知道那是什么。那是先祖给我们的礼物吗？"
D.Strings[65742]="不久之后，天空中的白月之下浮现出一块阴影。有些人恐惧地看着它，其他人则对它顶礼膜拜。$B$B族人们给它起了很多名字：比如圣父，比如黑暗之母。$B$B酋长则称它为“黑暗之星”。"
D.Strings[65743]="自从水晶从天而降，我们的力量就出现了难以理解的增长。$B$B我们一直在聆听群星和大地的低语。而现在，我们听到了另一种声音——暗影之声。"
D.Strings[65744]="昨天，我们发现有一个族人亵渎了先祖的灵魂。$B$B酋长十分暴怒。显然——这种新魔法很危险。它会将我们引上一条不归路。$B$B从今日起，我们要世代牢记，所有族人都禁止使用暗影的力量。$B$B“黑暗之星”是邪恶的。"
D.Strings[65745]="<拉希奥独坐一隅，转动着手上的棋子。他专注地凝视着棋盘，但你觉得他的心思已经飞到其他地方去了。>"
D.Strings[65746]="在很久很久以前，志向高远的英雄和帝王们会来这里面对至尊天神的考验。\n\n如今，我们也像我们的祖先一样，守卫着这些被时光侵蚀的道路。\n\n天神卫士绝不容许在这片圣地上发生阵营冲突。"
D.Strings[65747]="我从没见老板这么焦躁过。$b$b你最好等王子殿下冷静下来之后再去找他。"
D.Strings[65748]="我已经尽力不去看太阳了。它是不会移动的。$b$b这到底是什么地方？"
D.Strings[65749]="好想钓鱼啊！"
D.Strings[65750]="阻止入侵者！"
D.Strings[65751]="你阻止不了我们的，$c！总有一天，所有的兽人都将喝下魔血！"
D.Strings[65752]="黑暗降临了！"
D.Strings[65753]="暗影议会的旨意必将实现！"
D.Strings[65754]="你的灵魂将被吞噬！"
D.Strings[65755]="快！杀了这些入侵者！"
D.Strings[65756]="干掉外来者！"
D.Strings[65757]="你会成为一个不错的祭品！"
D.Strings[65758]="你已经迟了！"
D.Strings[65759]="你已经迟了，$c。暗影议会已经崛起！"
D.Strings[65760]="出去后要小心点。那些东西随时都有可能跳出来。"
D.Strings[65761]="安息吧，光荣的母亲。我们会为你复仇的。"
D.Strings[65762]="是什么在令大地震颤？"
D.Strings[65763]="我没有看见戈隆。那是什么？"
D.Strings[65764]="先知说睡魔哈拉德已经醒来了。"
D.Strings[65765]="巨虫正在巢穴中扭动。"
D.Strings[65766]="雷神氏族没准已经赶过来了。"
D.Strings[65767]="大地怎么在震动？我们遭到攻击了吗？"
D.Strings[65768]="有人安抚了狼群。"
D.Strings[65769]="都怪那个人类巫师和他的精灵跟班。大地知道他们不属于这里。"
D.Strings[65770]="所谓的玩火丧眼…… "
D.Strings[65771]="嘿，你在看什么呢？"
D.Strings[65772]="拉索恩，你留下。我还有计划……那是什么？"
D.Strings[65773]="我只想要它无尽的力量。"
D.Strings[65774]="如你所愿，古尔丹大人。"
D.Strings[65775]="你做好改变世界的准备了吗，$n？"
D.Strings[65776]="你知道该怎么做，勇士。"
D.Strings[65777]="等事情了结之后，就来雾纱栈道找我——如果你那时还活着的话。"
D.Strings[65778]="我的痛苦……永无止尽……"
D.Strings[65779]="永不……熄灭的烈焰……"
D.Strings[65780]="日夜……煎熬……"
D.Strings[65781]="你将代替我永远在这洪炉中煎熬。"
D.Strings[65782]="你的血肉将会融化。"
D.Strings[65783]="你的痛苦永无止尽。"
D.Strings[65784]="这点痛苦比不上我的万分之一。"
D.Strings[65785]="灰飞烟灭吧。"
D.Strings[65786]="永恒的烈焰不会熄灭。"
D.Strings[65787]="手不要抖……"
D.Strings[65788]="到底是绿条纹的蓝线还是黄条纹的黑线？我总是记不住。"
D.Strings[65789]="快呀！"
D.Strings[65790]="不是红色的线，是蓝色的！"
D.Strings[65791]="等等我！"
D.Strings[65792]="击倒"
D.Strings[65793]="南海是我永远的狩猎场！"
D.Strings[65794]="来啊，瓦祖维斯号，从深海归来吧！"
D.Strings[65795]="|TInterface\\Icons\\ability_gouge:20|t%s试图对你使用|cFFFF0000|Hspell:143330|h[凿击]|h|r，快转身！"
D.Strings[65796]="噢！真是段有趣的旅程！"
D.Strings[65797]="英雄们，向你们致敬。这些地下大厅里有着某种非常邪恶的东西。"
D.Strings[65798]="呼，它看起来很危险，冲上去，小伙子们，让他们看看我们的本事。"
D.Strings[65799]="真是个暴躁的家伙。你们最好小心点，英雄们。"
D.Strings[65800]="嘿，看看我们找到什么了？"
D.Strings[65801]="加尔鲁什还以为他能赖掉格里兹尔的帐，嗯？"
D.Strings[65802]="干掉它，在正版地精工程学面前，那玩意儿不堪一击！"
D.Strings[65803]="看来还有点本事。我最好……呃……去看看其他人。"
D.Strings[65804]="这座岛真是既迷人又可怕。"
D.Strings[65805]="鳄鱼人。"
D.Strings[65806]="<库玛瞪着你。>"
D.Strings[65807]="那就让我们来测试一下你的历史知识吧！告诉我，英雄，亡灵鱼人被称作什么？"
D.Strings[65808]="行尸鱼人。"
D.Strings[65809]="狼獾人。"
D.Strings[65810]="巫妖鱼人。"
D.Strings[65811]="答对了！"
D.Strings[65812]="那就让我们来测试一下你的历史知识吧！白狼曾是哪个兽人氏族最喜爱的坐骑？"
D.Strings[65813]="那就让我们来测试一下你的历史知识吧！德鲁伊的最高称号是什么？"
D.Strings[65814]="那就让我们来测试一下你的历史知识吧！侏儒如今的领袖是谁？"
D.Strings[65815]="那就让我们来测试一下你的历史知识吧！由玛法里奥·怒风协助建立的，艾泽拉斯最主要的德鲁伊组织叫什么名字？"
D.Strings[65816]="那就让我们来测试一下你的历史知识吧！在第三次大战过去数年之后，黑暗之门重新开启时，艾泽拉斯首次出现了棕色皮肤的兽人。这些兽人被称为什么？"
D.Strings[65817]="那就让我们来测试一下你的历史知识吧！在被阿尔萨斯复活为亡灵，并加入天灾军团之前，辛达苟萨曾属于哪个巨龙军团？"
D.Strings[65818]="那就让我们来测试一下你的历史知识吧！赞加沼泽有一个地方，那里为纳迦所控制，他们还试图在那里抽取一种珍贵而稀有的资源：外域之水。这个地方叫什么名字？"
D.Strings[65819]="那就让我们来测试一下你的历史知识吧！通过黑暗之门与艾泽拉斯相连的世界，它的本名叫什么？"
D.Strings[65820]="那就让我们来测试一下你的历史知识吧！下列哪一把剑能够将亡灵烧成灰烬？"
D.Strings[65821]="那就让我们来测试一下你的历史知识吧！为了保护艾泽拉斯世界，有几个巨龙军团被赋予了特殊的能力？"
D.Strings[65822]="那就让我们来测试一下你的历史知识吧！被称为“背叛者”的暗夜精灵是谁？"
D.Strings[65823]="那就让我们来测试一下你的历史知识吧！在第二次大战之后，大部分森林巨魔都开始仇视部落。如今，哪一个森林巨魔部族依然对部落友善？"
D.Strings[65824]="那就让我们来测试一下你的历史知识吧！是哪个恶魔强迫蓝龙卡雷苟斯在太阳之井高地去攻击一群冒险者的呢？"
D.Strings[65825]="那就让我们来测试一下你的历史知识吧！希尔瓦娜斯·风行者有一位姐妹领导着一个高等精灵的武装阵营以及肯瑞托。这个组织叫什么名字？"
D.Strings[65826]="那就让我们来测试一下你的历史知识吧！格罗姆·地狱咆哮在战斗中使用的著名战斧叫什么名字？"
D.Strings[65827]="那就让我们来测试一下你的历史知识吧！在上古之战后，守护巨龙们给了暗夜精灵什么东西？"
D.Strings[65828]="那就让我们来测试一下你的历史知识吧！在第三次大战期间，是什么证据促使阿尔萨斯王子屠杀了斯坦索姆的居民？"
D.Strings[65829]="那就让我们来测试一下你的历史知识吧！阿尔萨斯用来训练死亡骑士，后来又由于大部分死亡骑士背叛巫妖王而被占领的浮空堡垒叫什么名字？"
D.Strings[65830]="那就让我们来测试一下你的历史知识吧！大领主库德兰·蛮锤最近痛失爱将，他英勇的狮鹫在一次大火中不幸丧生。这头狮鹫叫什么名字？"
D.Strings[65831]="那就让我们来测试一下你的历史知识吧！有一位王后，在大灾变和被遗忘者袭击她的国度时，她井井有条地安排了人民的疏散工作。这位王后叫什么名字？"
D.Strings[65832]="那就让我们来测试一下你的历史知识吧！在撕心狼变成狼人之前，他也曾有过家室。他的妻子叫什么名字？"
D.Strings[65833]="那就让我们来测试一下你的历史知识吧！艾泽拉斯出现的第一个死亡骑士是谁？"
D.Strings[65834]="那就让我们来测试一下你的历史知识吧！有一位德莱尼人，他曾是一个健康的圣骑士，但在与燃烧军团作战时，他身染恶疾，变成了破碎者。后来，他成了一个强大的萨满。这个德莱尼人是谁？"
D.Strings[65835]="那就让我们来测试一下你的历史知识吧！在黑曜石圣殿守护暮光龙蛋的三头暮光幼龙分别叫什么？"
D.Strings[65836]="那就让我们来测试一下你的历史知识吧！提里奥·弗丁的灰色公马叫什么名字？"
D.Strings[65837]="那就让我们来测试一下你的历史知识吧！由地精制造，原计划搭载萨尔和阿格娜前往大漩涡，却被联盟意外摧毁的部落舰船叫什么名字？"
D.Strings[65838]="那就让我们来测试一下你的历史知识吧！隶属于万神殿精锐的泰坦知识守护者叫什么名字？"
D.Strings[65839]="那就让我们来测试一下你的历史知识吧！被洛肯捕获并变成锋鳞的强大始祖龙叫什么名字？"
D.Strings[65840]="那就让我们来测试一下你的历史知识吧！根据德莱尼人的玩笑，“埃索达”在纳鲁语中是什么意思？"
D.Strings[65841]="那就让我们来测试一下你的历史知识吧！下列哪一位的墓志铭上刻有“愿血染的王冠永远被遗失和忘却”这句话？"
D.Strings[65842]="那就让我们来测试一下你的历史知识吧！这个世界上的第一个萨特是谁？"
D.Strings[65843]="那就让我们来测试一下你的历史知识吧！瓦里安·乌瑞恩国王的第一任妻子的正确名字是什么？"
D.Strings[65844]="那就让我们来测试一下你的历史知识吧！虚灵的家乡叫什么名字？"
D.Strings[65845]="那就让我们来测试一下你的历史知识吧！在最初的部落建立之前，有一种高传染性的病毒在兽人间快速传播。兽人们称这种病为什么？"
D.Strings[65846]="那就让我们来测试一下你的历史知识吧！一位血色十字军保卫者在刺杀恐惧魔王贝塞利斯时遇害，她叫什么名字？"
D.Strings[65847]="那就让我们来测试一下你的历史知识吧！铁炉堡图书馆中展出了一具巨型山羊的骨架复制品。这头传奇山羊叫什么名字？"
D.Strings[65848]="那就让我们来测试一下你的历史知识吧！在突袭冰冠堡垒时，部落军队无耻地偷袭正与天灾军团激战的联盟士兵，并试图占领的那座城门叫什么名字？"
D.Strings[65849]="那就让我们来测试一下你的历史知识吧！下列哪句话是龙语中“谢谢你”的意思？"
D.Strings[65850]="那就让我们来测试一下你的历史知识吧！在担任家庭教师期间，斯塔文·密斯特曼托爱上了自己的学生，一个名叫蒂罗亚的年轻姑娘。请问她的弟弟叫什么名字？"
D.Strings[65851]="那就让我们来测试一下你的历史知识吧！不久之前，一个脆弱的赞达拉巨魔想要驯服一头恐角龙。虽然他登上了巨兽岛，却在任务过程中遇害。请问这个巨魔叫什么名字？"
D.Strings[65852]="那就让我们来测试一下你的历史知识吧！嫌弃银月城过于明亮和干净的部落大使叫什么名字？"
D.Strings[65853]="那就让我们来测试一下你的历史知识吧！魅魔热衷于制造痛苦，她们在燃烧军团中专门负责进行可怕的拷问工作。请问魅魔属于哪个品种的恶魔？"
D.Strings[65854]="那就让我们来测试一下你的历史知识吧！头衔中包含“夜晚之友”的是哪位神灵？"
D.Strings[65855]="那就让我们来测试一下你的历史知识吧！在牛头人的语言中，lar'korwi是什么意思？"
