D.Strings[66028]="你好，旅行者！$b$b你是来参加今晚的云游节的吗？日落之后，熊猫人们就会纷纷聚集到这片海龟沙滩上！那场景壮观极了！$b$b在活动快开始前跟我对话，我会告诉你还需要等待多久。"
D.Strings[66029]="你好，旅行者！$b$b你是来参加今晚的云游节的吗？日落之后，熊猫人们就会纷纷聚集到这片海龟沙滩上！那场景壮观极了！$b$b现在距离庆典开始还有不到三小时。请在整点时回来确认！"
D.Strings[66030]="你好，旅行者！$b$b你是来参加今晚的云游节的吗？日落之后，熊猫人们就会纷纷聚集到这片海龟沙滩上！那场景壮观极了！$b$b现在距离庆典开始还有不到两小时。请在整点时回来确认！"
D.Strings[66031]="你好，旅行者！$b$b你是来参加今晚的云游节的吗？日落之后，熊猫人们就会纷纷聚集到这片海龟沙滩上！那场景壮观极了！$b$b现在距离庆典开始还有不到一小时。请在整点时回来确认！"
D.Strings[66032]="庆典已经开始了！快去邀请你的朋友们吧！$b$b千万别错过庆典头尾的烟火表演。那是最精彩的部分。"
D.Strings[66033]="听国王的命令，守住阵线！帮我们的英雄争取追击加尔鲁什的时间！"
D.Strings[66034]="需要万能钥匙"
D.Strings[66035]="你竟敢打扰我用餐？！"
D.Strings[66036]="有怪味道……啊哈！我看见你了，$c！"
D.Strings[66037]="好……好饿……哎呀！！"
D.Strings[66038]="嘿，伙计！我是助理历史学家帕吉。他们还没有正式授予我这个的头衔，但我相信那是迟早的事。"
D.Strings[66039]="你好！我是历史学家勒洛尔！大家都说我笑得太多了，可我觉得这完全不可能！"
D.Strings[66040]="复仇的时刻终于到来了。这个怪物将为我们所牺牲的每一位联盟战友而受到惩罚。"
D.Strings[66041]="加尔鲁什将为他的罪行付出代价。"
D.Strings[66042]="谢谢你来帮助我纠正过去所犯下的错误，是它将我们的人民推入了黑暗的深渊。我一个人是无法成功的。现在，我就要赢回自己的荣誉，并彻底终结加尔鲁什的恐怖统治。"
D.Strings[66043]="为了部落，结束这一切吧。"
D.Strings[66044]="我们会守住战线的，$n。你只需要考虑如何阻止加尔鲁什的疯狂罪行。"
D.Strings[66045]="三重锁的囚笼上的第一道锁“喀啦”一声掉在了地上，还剩两道锁。"
D.Strings[66046]="三重锁的囚笼上的第二道锁“喀啦”一声掉在了地上，还剩一道锁。"
D.Strings[66047]="三重锁的囚笼上的第三道锁“喀啦”一声掉在了地上。囚笼打开了！"
D.Strings[66048]="我喜欢穿短裤！它最适合这里的天气！"
D.Strings[66049]="我只有一只宠物！但愿这能行！"
D.Strings[66050]="你要让让我哦！"
D.Strings[66051]="你的宠物倒下了！"
D.Strings[66052]="噢！不公平！"
D.Strings[66053]="耶！我是最棒的！"
D.Strings[66054]="你是来拿包裹的吗？还是来寄信的？$B$B我可以提供超速快递服务哦！"
D.Strings[66055]="使用邮件服务。"
D.Strings[66056]="呃！什、什么？！噢……$B$B你、你需要、要什么吗？$B$B我、我怎么就让姐姐给骗过来了呢……你看到那些动物有多、多大吗？！"
D.Strings[66057]="<这个脏兮兮的老熊猫人安详地打着呼噜，身边丢满了各种瓶子。>"
D.Strings[66058]="检查他的货物。"
D.Strings[66059]="噢，你好！$B$B请进，快请进！请休息一会儿吧。$B$B你想吃点什么吗？或者来杯喝的？"
D.Strings[66060]="小心你的脸！"
D.Strings[66061]="再快一点！别停下！"
D.Strings[66062]="你要是再出一次岔子，那下一个就是你！"
D.Strings[66063]="你真该庆幸没有被分去厨房劈柴！"
D.Strings[66064]="我们得立刻完成仪式！再快一点儿！"
D.Strings[66065]="让我看看你的工作成果吧！"
D.Strings[66066]="再见了我的朋友，时间不早，我得走了。"
D.Strings[66067]="你知道什么好笑话吗，$r？"
D.Strings[66068]="阿哈哈，这个不错！"
D.Strings[66069]="知道吗，你真的很幽默。"
D.Strings[66070]="不不，我不太喜欢这个。还有吗？"
D.Strings[66071]="啊哈哈哈……哈哈哈哈哈哈！"
D.Strings[66072]="啊哈哈哈……噢，我喜欢这个！"
D.Strings[66073]="嚯嚯嚯嚯，这个很搞笑！再讲一个吧。"
D.Strings[66074]="多么美好的一天啊，不是吗？"
D.Strings[66075]="为了圣光。"
D.Strings[66076]="你见过我的同伴吗？"
D.Strings[66077]="外来者，我们接受你的挑战。斡耳朵，以火神的名义，夺下这个地方！"
D.Strings[66078]="你瞧，历史学家的工作是永远也干不完的。那些需要我们铭记的重要事件总是层出不穷。$B$B我已经记下了你的大部分事迹，但有待了解的东西还是太多了！你的事迹肯定会流芳百世的。"
D.Strings[66079]="我不是眼花了吧？！船上那些……是骷髅吗？"
D.Strings[66080]="那场风暴将我们吹离了航道。我们可能位于库尔提拉斯和洛丹伦之间的任何地方，所以都给我提高警惕！"
D.Strings[66081]="我从没见过这么浓的雾。我们得把帆降下来，等雾散开。我可不想让藤壶号撞上暗礁啥的。"
D.Strings[66082]="远处那是什么？船帆！嘿！我们都搁浅九天啦！救命！"
D.Strings[66083]="全体上甲板！藤壶号遭到攻击啦！"
D.Strings[66084]="谢谢你。要不是你的帮助，我真不知道自己能不能活下来。"
D.Strings[66085]="图格尔是一个残酷的主人。他整日折磨他的奴隶，任由我们活活饿死！"
D.Strings[66086]="很抱歉我这么快就要走了。我得去找我的双头飞龙伙伴。她在我被捕前就失踪了。不过我还是要对你说一声谢谢。"
D.Strings[66087]="嘿，小心点！"
D.Strings[66088]="噢！我要打断你的后背！"
D.Strings[66089]="别打我，蠢货！"
D.Strings[66090]="让开，这是我的！"
D.Strings[66091]="啊！那我就先杀了你，再碾碎这个小东西！"
D.Strings[66092]="呃，我要杀了你！"
D.Strings[66093]="啊，我的眼睛！你从哪儿学来的？！"
D.Strings[66094]="够了没有？！"
D.Strings[66095]="硬汉，嗯？我让你看看什么才是硬汉！"
D.Strings[66096]="这将是你犯下的最后一个错误，外来者。尝尝熔岩的威力吧，它将融化你的骨头！"
D.Strings[66097]="我的身躯已与火山融为一体。"
D.Strings[66098]="看你还敢跟我作对！"
D.Strings[66099]="我正是那么想的！"
D.Strings[66100]="你就不该挡我的路！"
D.Strings[66101]="啊！！我又碾碎了一个挑衅者！"
D.Strings[66102]="现在，去死吧蠢货！"
D.Strings[66103]="时间既是美丽的，也是残酷的。"
D.Strings[66104]="没办法了，伙计。我们必须马上阻止加尔鲁什，否则大家只能白白送死。"
D.Strings[66105]="他们一定攻占了码头！哈哈！欢迎来到修罗场。"
D.Strings[66106]="不用怀疑，他们是英雄。"
D.Strings[66107]="那头野兽完蛋了！"
D.Strings[66108]="泰兰德……"
D.Strings[66109]="加尔鲁什藏了一个秘密基地。他到底有什么打算？"
D.Strings[66110]="贝恩，你和你的战士们守住这里。这些英雄们要继续前进，找到加尔鲁什的踪迹。"
D.Strings[66111]="人民正在哀嚎。城里一片混乱。我要去阻止这场屠杀。我会回来找你的。"
D.Strings[66112]="没事的，贝恩。我们会找到萨尔，打倒酋长，为你父亲报仇的。"
D.Strings[66113]="哈。暗矛永不灭亡。"
D.Strings[66114]="姐妹们，进攻！为了卡利姆多！"
D.Strings[66115]="我们可不是来救你的，巨魔。我们是为卡利姆多而来。我们来引开敌人，让你的部队趁势杀进去。"
D.Strings[66116]="我们的伤亡太大了！"
D.Strings[66117]="或许新来的援军能帮上忙。"
D.Strings[66118]="或许我们还有希望。"
D.Strings[66119]="愿大地母亲祝福他们。"
D.Strings[66120]="我们很快就知道了。他就像老鼠一样躲在某条地道里。"
D.Strings[66121]="那么你呢？"
D.Strings[66122]="……好吧。"
D.Strings[66123]="愿大地母亲护佑着你，沃金。"
D.Strings[66124]="这么快就要走了吗？客人怎么办？"
D.Strings[66125]="哈！我们还见识过比这更可怕的风暴呢，$n。那么，快行动吧，可别让加尔鲁什久等了！"
D.Strings[66126]="必须阻止加尔鲁什的疯狂行为，$n，我们的未来全系于此。由于这个任务极其重要，所以我不能把它托付给别人。"
D.Strings[66127]="|TInterface\\Icons\\ability_titankeeper_quarantine.blp:20|t诺鲁什启动了检疫空间中的|cFFFF0000|Hspell:145779|h[安全措施]|h|r！"
D.Strings[66128]="你需要伪装服吗，旅行者？我可以帮你。"
D.Strings[66129]="我在一英里外，就能看见你穿着那套衣服了，$r。"
D.Strings[66130]="我就知道，这个颜色最衬你的肤色了。"
D.Strings[66131]="这边，$r。把那些碎布递给我，我可以给出好几种选择方案。"
D.Strings[66132]="我发誓，只要我还有一口气在，这些库卡隆畜生就休想通过这里。你只要保证把加尔鲁什那条疯狗干掉就够了。"
D.Strings[66133]="目前，我能提供的最好的医疗手段就是给你一些能够避免伤害的东西了。"
D.Strings[66134]="这肯定会比我平时的情报收集工作刺激得多。现在，快去对付加尔鲁什吧，我可不希望这变成我在军情七处的最后一次任务。"
D.Strings[66135]="我不管你的装备有多好，$n，如果不注意脚下，那你就死定了。让那些小崽子们休息一下，用我的传送门立即返回入口处吧。"
D.Strings[66136]="我可以帮你赶制任何造型。你想要什么？"
D.Strings[66137]="让我挑选一下吧。"
D.Strings[66138]="这个任务太重要了，所以我不放心把你的修理工作交给别人。"
D.Strings[66139]="啊！我是来引导你前往永恒岛的，但我看到你已经抵达了。我恐怕又把时间流搞混了。"
D.Strings[66140]="%s拿出一个铜质计时器，眯着眼看了看刻度盘。她看起来有些尴尬。"
D.Strings[66141]="别吵了！"
D.Strings[66142]="别打了！"
D.Strings[66143]="快来帮帮我！你们可以稍后再打个够！"
D.Strings[66144]="每个生命都是一条线，而把我们交织起来，就构成了这个世界的故事。熊猫人游学者对此的理解无人能及。看看这个图书馆吧！这么多故事……"
D.Strings[66145]="来吧，熔岩之精！"
D.Strings[66146]="欢迎光临王记，这里的太阳永不下山，这里的美食永远热气腾腾！"
D.Strings[66147]="什么味道这么香？"
D.Strings[66148]="能和新朋旧友欢聚一堂真是太好了。"
D.Strings[66149]="别忘了花点时间去欣赏风景！"
D.Strings[66150]="我的位子是整个庭院里最好的，你不觉得吗？"
D.Strings[66151]="这里的人都很好……吱吱喜欢这里。"
D.Strings[66152]="你要去跟大牛战斗吗？"
D.Strings[66153]="你是吱吱见过的，最强大的$c！"
D.Strings[66154]="我准备好飞往卡拉波了。"
D.Strings[66155]="这下你可上我的当了。"
D.Strings[66156]="唔。"
D.Strings[66157]="再来一盘吧，凯特。"
D.Strings[66158]="啊，是沃金的起义军。你们来了。"
D.Strings[66159]="你找到萨尔了吗？我受了重伤，他坚持要独自前进。"
D.Strings[66160]="告诉我，上面的战斗怎么样了？纳兹戈林呢？告诉我！"
D.Strings[66161]="啊，纳兹戈林。他是个好领袖，好战士。他珍视自己的誓言胜过生命。"
D.Strings[66162]="我试图告诉他……地狱咆哮背叛了我们大家，抛弃了对人民的责任。但纳兹戈林……太忠诚……太骄傲了。"
D.Strings[66163]="该死的地狱咆哮。他的野心令部落四分五裂。"
D.Strings[66164]="去找萨尔吧。结束这一切。我会活下来的。"
D.Strings[66165]="以督军加尔鲁什的名义，杀光他们。"
D.Strings[66166]="谢谢你能这么快赶到，$n。"
D.Strings[66167]="把这些入侵者赶出洛克拉斯，再拆了他们的破营地。"
D.Strings[66168]="钢铁部落，用你们的战争机器夷平敌人的营地吧。"
D.Strings[66169]="你来得正是时候，祭品！"
D.Strings[66170]="快去吧，$n，去干掉加尔鲁什。记住，大地母亲在关注着你。"
D.Strings[66171]="我以安瑟的威能起誓，这些库卡隆杂种休想通过这里。"
D.Strings[66172]="里克会把这些库卡隆都干掉的。作为回报，$n能帮里克一个忙吗？你只要告诉琪麟，加尔鲁什是里克干掉的就行了。"
D.Strings[66173]="我……输了？"
D.Strings[66174]="这正是我想要的！"
D.Strings[66175]="我以先祖的名义发誓，这些库卡隆休想通过此地。快去吧，$n，打倒加尔鲁什的荣誉就归你了！"
D.Strings[66176]="让我想想……"
D.Strings[66177]="我还留了好几手呢！"
D.Strings[66178]="我的法力值不够了！噢，不！"
D.Strings[66179]="我得重新建一套牌组……"
D.Strings[66180]="你也不怎么厉害嘛！"
D.Strings[66181]="打得好，老兄。"
D.Strings[66182]="再来一盘怎么样？"
D.Strings[66183]="你看这张牌怎么样？"
D.Strings[66184]="唔。好牌。"
D.Strings[66185]="你感觉到他们正在汲取的力量了吗？（那是纳格兰的纳鲁！）"
D.Strings[66186]="我从没见过这张牌。"
D.Strings[66187]="三局两胜！"
D.Strings[66188]="我要翻盘！"
D.Strings[66189]="这才是我所说的比赛！"
D.Strings[66190]="这次，我要踢爆你的屁股！"
D.Strings[66191]="好吧，好吧，你赢了。"
D.Strings[66192]="好好，我这就跟你走。但让我再玩一盘。"
D.Strings[66193]="这是我近几年玩过的最好的游戏！"
D.Strings[66194]="看到这张牌了吗？它肯定能把那个矮人从椅子上打翻。"
D.Strings[66195]="你说他怎么就打得那么好呢？"
D.Strings[66196]="看见这张牌了吗？他这次休想打败我！"
D.Strings[66197]="我会打败他的，我发誓！"
D.Strings[66198]="把沙戈尔放出来。让纳格兰魔王发威吧！"
D.Strings[66199]="我会尽力帮忙的，$n。你只要在追杀加尔鲁什的路上，顺手多留下几具美味的库卡隆尸体就行了。"
D.Strings[66200]="我有脑子，你有力气。只要齐心协力，我们就能打个漂亮仗。"
D.Strings[66201]="港口防线崩溃了！库卡隆，后撤，到高地上去！"
D.Strings[66202]="玩家控制了南部塔楼的防空炮台！"
D.Strings[66203]="欢迎，$r。我是观察者麦佳娜的忠实守卫。她有着特殊的天赋，令我……呃，我们的领袖……十分欣赏，所以必须受到严密的保护。"
D.Strings[66204]="商人会愿意多花一些钱来品尝浇头比较多的面，如龙须汤面。"
D.Strings[66205]="农夫在经过一天的辛勤耕作后，就需要分量十足的熊猫人八宝汤面来帮他们恢复精神。"
D.Strings[66206]="好吧。我需要一些帮助……我在找我的身体。它就在这个山洞里的某处，但你只有在进入灵魂世界后才能看到它。如果你愿意帮忙，就告诉我一声。\n\n但你要小心。永恒之灵能把我们赶出灵魂世界，如果那样的话，凭我的力量恐怕无法让我们马上再次进入灵魂世界。"
D.Strings[66207]="我做好进入灵魂世界的准备了。"
D.Strings[66208]="这些武器必须在几个小时内完成。快点干！"
D.Strings[66209]="这没什么了不起的……"
D.Strings[66210]="我在干呢，我在干呢。"
D.Strings[66211]="我正忙着呢！你想要什么？"
D.Strings[66212]="卡拉克西英杰开始狂暴了！"
D.Strings[66213]="$n占领了中央矿坑！"
D.Strings[66214]="$n占领了熊猫人矿洞！"
D.Strings[66215]="$n占领了地精矿洞！"
D.Strings[66216]="来吧，恶心的家伙。"
D.Strings[66217]="只要同心协力，我们就能战胜暗影议会。"
D.Strings[66218]="没人能阻挡我们！向公海进发！"
D.Strings[66219]="请选择要刻在标志上的话。"
D.Strings[66220]="前方有城镇。"
D.Strings[66221]="前方危险。"
D.Strings[66222]="前方有宝藏。"
D.Strings[66223]="前方有危险敌人。"
D.Strings[66224]="前方有敌对阵营。"
D.Strings[66225]="附近有秘密。"
D.Strings[66226]="这里！"
D.Strings[66227]="死路。"
D.Strings[66228]="致命陷阱。"
D.Strings[66229]="附近有部落。"
D.Strings[66230]="附近有联盟。"
D.Strings[66231]="需要坦克。"
D.Strings[66232]="需要治疗者。"
D.Strings[66233]="需要伤害输出者。"
D.Strings[66234]="需要特殊物品。"
D.Strings[66235]="需要史诗级武器。"
D.Strings[66236]="需要朋友。"
D.Strings[66237]="稀有生物。"
D.Strings[66238]="致命坠落。"
D.Strings[66239]="眼泪。"
D.Strings[66240]="这不可能！瓦祖维斯号怎么可能败在你这种人手上！"
D.Strings[66241]="地下堡垒被攻破了！快去开动切割者，把这些入侵者撕成碎片！"
D.Strings[66242]="一百箱肉、毛皮和木材已经发往塔纳安丛林了，阿诺克。"
D.Strings[66243]="记住，影月氏族始终善待它的盟友，并将痛苦带给它的敌人。"
D.Strings[66244]="干得好。当钢铁部落攻占德莱尼在海边的那座神庙时，你的氏族将有幸与我们一同享受胜利果实。"
D.Strings[66245]="钢材呢？煤炭、原油和黑火药呢？这点东西跟你承诺的相比，只是九牛一毛！"
D.Strings[66246]="很抱歉，指挥官。我们正在加班加点地赶制其他订单。钢铁部落将收到一份无以伦比的礼物……"
D.Strings[66247]="一件足以毁灭诸世界的武器。"
D.Strings[66248]="那这件武器在哪儿呢？"
D.Strings[66249]="耐心点，指挥官。我们可是钢铁部落的忠实仆人。它很快就要完成了。"
D.Strings[66250]="那就快一点！很快……德莱尼人的神殿就将陷落。"
D.Strings[66251]="信使！快去主建筑，把彩虹水晶交给耐奥祖酋长。我们可能不能让钢铁部落的朋友们久等了。"
D.Strings[66252]="几代以来，我一直用迷雾保护着我的人民，但看着眼前的一个个勇士，我越来越意识到自己的错误。愿你和我一样，从潘达利亚的历史中得到教训。"
D.Strings[66253]="我很高兴能和我的儿子分享这一时刻。再次感谢你为我们所做的一切。"
D.Strings[66254]="我很高兴能和我的儿子分享这一时刻。"
D.Strings[66255]="卖魔法天灯啦！只要点亮蜡烛，它就能飞上天空，甚至不需要有风！"
D.Strings[66256]="随着枢纽大门的打开，削磨金属的刺耳噪音在大厅里回荡开来。"
D.Strings[66257]="你们这些蠢货，我手里有着无穷无尽的库卡隆物资！立即投降，我还能给你们一个痛快。"
D.Strings[66258]="你必须找到萨尔，并推翻加鲁什的统治。"
D.Strings[66259]="等我们解决掉那些食人魔、火刃氏族还有洛克拉斯的兽人，就可以向格罗玛什尔进发了。"
D.Strings[66260]="没有至尊天神的庇护，你被驱逐出了斡耳朵圣殿！"
D.Strings[66261]="一个游侠间谍？在我们的村子里？"
D.Strings[66262]="你又在执勤时睡觉了吗？"
D.Strings[66263]="噢……不……"
D.Strings[66264]="还是拿来喂我们的狼？"
D.Strings[66265]="我们对这些兽人仁慈，可他们是怎么回报我们的？！看看这一切吧！"
D.Strings[66266]="他们在制造武器，可这是为了什么呢？"
D.Strings[66267]="我们赢得了这场战役，可战争远未结束，$n。"
D.Strings[66268]="我会把彩虹水晶带给先知的。我能感觉到，你还有许多事情要做。"
D.Strings[66269]="要是知道我们失败了，先知一定会很失望的。"
D.Strings[66270]="看看他们囤积的这些补给品！"
D.Strings[66271]="要是钢铁部落不打算再进攻的话，那他们还要这些武器做什么？"
D.Strings[66272]="我们就不该对他们手软……"
D.Strings[66273]="我们所做的一切，只是给了他们重整旗鼓的机会。"
D.Strings[66274]="我们得快一点了。看样子，钢铁部落很快就会卷土重来。"
D.Strings[66275]="我要用我的战锤砸碎那些兽人的脑袋！"
D.Strings[66276]="我们就不该相信钢铁部落！"
D.Strings[66277]="只有死掉的兽人才是好兽人……"
D.Strings[66278]="地狱咆哮必须为他的背信弃义而偿命！"
D.Strings[66279]="我们该尝试一下先发制人的措施了！"
D.Strings[66280]="我要把你们赶出这片土地！"
D.Strings[66281]="你们背信弃义的行为将遗臭万年，兽人！"
D.Strings[66282]="就当是给格罗玛什的一个警告！"
D.Strings[66283]="你们不属于影月谷，兽人渣滓！"
D.Strings[66284]="我来解决这家伙！"
D.Strings[66285]="这太可怕了……格罗玛什·地狱咆哮已经下令对卡拉波发动第二波攻势了。和平解决的希望到此为止了。"
D.Strings[66286]="这不太像是日记，倒像是一张订单……"
D.Strings[66287]="他们订购的这些武器和弹药，足以把卡拉波夷为平地！"
D.Strings[66288]="让我看看。找到了！彩虹水晶已经被转移了，但它还在这附近。我们还有时间去找到它，并把它交给先知。"
D.Strings[66289]="谢、谢谢你，陌生人……"
D.Strings[66290]="我们不能再浪费时间了，$n。"
D.Strings[66291]="多么完美的烧烤，乌夫戈！我敢打赌，我们来自钢铁部落的客人肯定从来没尝过这么好吃的东西。"
D.Strings[66292]="我们得快一点了。快点炸毁这些东西，我们就能集中精力来激活水晶了。"
D.Strings[66293]="我需要一些小玩意儿和一罐卡亚可乐来完成这个装置。"
D.Strings[66294]="我要给那些臭烘烘的兽人一点颜色瞧瞧。"
D.Strings[66295]="为什么？他们为什么要袭击我们？"
D.Strings[66296]="我一点都不想打仗……"
D.Strings[66297]="我还以为我死定了呢！"
D.Strings[66298]="感谢纳鲁，我得救了！"
D.Strings[66299]="连续执行相同的动作可以让你获得一些小奖励。尽量连续引导客人入座或者连续上菜来赢得额外的分数吧！"
D.Strings[66300]="你喜欢锤子吗？"
D.Strings[66301]="别碰那些锤子！"
D.Strings[66302]="这玩意儿没用了。"
D.Strings[66303]="那些锤子不管用。"
D.Strings[66304]="该换几把锤子了。"
D.Strings[66305]="这些锤子太蠢了。"
D.Strings[66306]="那边还有更多的锤子。"
D.Strings[66307]="试试新锤子。"
D.Strings[66308]="有一把锤子好像裂了。"
D.Strings[66309]="我的锤子比修理工还要多。"
D.Strings[66310]="我们到了，$n。让我们来彻底铲除这些兽人吧。"
D.Strings[66311]="你肯定想不到，我还有第五把锤子呢！"
D.Strings[66312]="再来尝尝这个吧！"
D.Strings[66313]="我要把这些锤子扔到你的脑袋上！"
D.Strings[66314]="来听听锤子的叮当声吧！"
D.Strings[66315]="这第五把锤子才是我的最爱！"
D.Strings[66316]="我得试试其他锤子！"
D.Strings[66317]="锤子越多越好！"
D.Strings[66318]="站住！"
D.Strings[66319]="来吧，老伙计们。应该执行下一步计划了。"
D.Strings[66320]="塔隆戈尔，你要渗透进奥金尼并控制奥金顿。去榨干他们的鲜血。 "
D.Strings[66321]="古加尔，你在霜火岭的任务先停下来。"
D.Strings[66322]="我看穿你的伪装了，孩子。别害怕。"
D.Strings[66323]="我打算派你去纳格兰，收服沃舒古的纳鲁。"
D.Strings[66324]="我们应该把她的脑袋送去卡拉波，作为警告！"
D.Strings[66325]="使用一瓶月亮圣水收服全视之眼。$B$B|TInterface\\Icons\\INV_Potion_20.blp:64|t"
D.Strings[66326]="当恶魔被削弱时，诵念艾露恩的经文。$B$B|TInterface\\Icons\\INV_Scroll_12.blp:64|t"
D.Strings[66327]="$n附近的蛛形地雷爆炸了！"
D.Strings[66328]="污秽水流的目标指向了你！"
D.Strings[66329]="我们应该趁早解决钢铁部落。"
D.Strings[66330]="让后备队上来！冲锋！"
D.Strings[66331]="督军扎伊拉命令|cFFFF0404|h库卡隆投石车|h|r攻击塔楼！"
D.Strings[66332]="士兵们！快来帮我！"
D.Strings[66333]="地狱咆哮！"
D.Strings[66334]="你对卡拉波的袭击是卑鄙且毫无理由的。"
D.Strings[66335]="更重要的是，我们在战场上完胜了你们兽人。"
D.Strings[66336]="我完全有权利砍下你的脑袋，并毁掉这座城镇……"
D.Strings[66337]="……但不是今天。今天，我们就饶你一次。带上你们的战争机器，滚出这片土地。"
D.Strings[66338]="遵……遵命，先生。我们这就走。我向你保证。"
D.Strings[66339]="我要跟你同归于尽，$c！"
D.Strings[66340]="夺回彩虹水晶！"
D.Strings[66341]="我的月亮石！别跟着我！"
D.Strings[66342]="你真臭！你才不是什么好朋友呢！"
D.Strings[66343]="你休想得到食物！"
D.Strings[66344]="快跑啊！！"
D.Strings[66345]="让我一个人待着！！"
D.Strings[66346]="这块月亮石给好朋友！"
D.Strings[66347]="不好！"
D.Strings[66348]="没人喜欢你！别过来，$C！"
D.Strings[66349]="没人喜欢你！"
D.Strings[66350]="小酒灵一直在喝叔叔的酒。但愿这能让它在战斗中凶猛一点！"
D.Strings[66351]="那个白痴蟋蟀害得我整晚都睡不着觉。别告诉我叔叔，你帮我去踩死它吧！"
D.Strings[66352]="有时唐莎会让我骑到他背上……可他太臭了。"
D.Strings[66353]="我也不知道他为什么就不肯听我的！我只想告诉他怎么才能把面条做得更好吃。"
D.Strings[66354]="歌谣？"
D.Strings[66355]="是的！一首关于传说，以及我们从中所得到的知识的歌谣。听起来很激动人心吧？$b$b不过……我们还在研究。查德里克最近似乎一直在分心。我的战袍上有什么脏东西吗？"
D.Strings[66356]="所有侵入卡拉波的兽人必将遭受制裁！"
D.Strings[66357]="英雄们，我得去其他地方支援了！如果你们见到加尔鲁什，记得告诉他，他应该投资侏儒科技才对！"
D.Strings[66358]="大地！"
D.Strings[66359]="听从我们的命令！"
D.Strings[66360]="我们不需要元素的帮助……"
D.Strings[66361]="扭曲之风，腐蚀众生！"
D.Strings[66362]="死寂之火，浓烟蔽日！"
D.Strings[66363]="正统部落的血脉渴望力量！"
D.Strings[66364]="我听不到它们的声音了……"
D.Strings[66365]="我的座狼将畅饮你的鲜血。"
D.Strings[66366]="风暴！"
D.Strings[66367]="烈焰！"
D.Strings[66368]="正统部落掌控一切！"
D.Strings[66369]="苦痛之水，流毒无穷！"
D.Strings[66370]="崩解之地，锈蚀万物！"
D.Strings[66371]="元素……我们干了什么……"
D.Strings[66372]="我要把你的脑袋穿在项链上。"
D.Strings[66373]="很高兴你们成功了。我们可以前进了吗？"
D.Strings[66374]="我们将征服白鬼兽人和……（有入侵者！我们走吧。）"
D.Strings[66375]="食物！"
D.Strings[66376]="又有食物了！真是个好日子！"
D.Strings[66377]="哇，食物！"
D.Strings[66378]="我要当酋长！你就是午餐。"
D.Strings[66379]="我们再也不喜欢你了！"
D.Strings[66380]="去告诉酋长，我就是这片树林里的新首领了！"
D.Strings[66381]="有了这个术士的魔法装置，我们就可以窥探暗影议会了。"
D.Strings[66382]="我快饿死了……"
D.Strings[66383]="|TInterface\\Icons\\Ability_Siege_Engineer_Superheated.blp:20|t莎娜正在向你发射激光！"
D.Strings[66384]="听起来他们好像召唤了魔眼警卫。下去时小心点。"
D.Strings[66385]="任何生物都不应该像下面那些人一样被奴役。"
D.Strings[66386]="我们必须根除暗影议会的威胁。"
D.Strings[66387]="快来拿你的汤面吧！"
D.Strings[66388]="我准备好了，卡德加。我们来使用全视指环吧。"
D.Strings[66389]="皮埃尔很厉害吧？是我的朋友贾德帮我做的！"
D.Strings[66390]="我想要训练他，可我又不想让他受伤害。"
D.Strings[66391]="他真的很好，还想帮我煮东西吃。可惜那些东西根本没法入口，我只能趁他不注意的时候都扔了。"
D.Strings[66392]="来吧，兽人！来接受审判吧！"
D.Strings[66393]="你们一路杀入了卡拉波，现在你们必须踏过我的尸体，否则别想继续前进！"
D.Strings[66394]="来啊！来与我一战！你们怕了吗？"
D.Strings[66395]="攻击卡拉波将是你们最大的错误，兽人。你们唤醒了沉睡的巨人！"
D.Strings[66396]="塔隆戈尔，我们将一起完成你在影月谷的任务。"
D.Strings[66397]="我打算派你去塔拉多。你要渗透进奥金尼，控制住奥金顿，让它流干最后一滴血。"
D.Strings[66398]="遵命，指挥官！"
D.Strings[66399]="古加尔，我打算派你去纳格兰。"
D.Strings[66400]="为了钢铁部落！"
D.Strings[66401]="你要去降服沃舒古的堕落纳鲁。"
D.Strings[66402]="吉塞尔达，你留下。我还有计划要……我身后的是什么？"
D.Strings[66403]="能让我咬一口吗？"
D.Strings[66404]="你闻起来很像食物！"
D.Strings[66405]="唔唔！"
D.Strings[66406]="机会来了！"
D.Strings[66407]="你是我最好的朋友。"
D.Strings[66408]="我会帮你找到好朋友。"
D.Strings[66409]="你好啊，好朋友！"
D.Strings[66410]="让我们去找你的好朋友吧！"
D.Strings[66411]="好朋友，你真香。"
D.Strings[66412]="你会帮你的，好朋友！"
D.Strings[66413]="这是我的！滚开！"
D.Strings[66414]="去找你自己的食物吧！"
D.Strings[66415]="现在，我是酋长了！快去告诉好朋友！"
D.Strings[66416]="你才不是好朋友呢！"
D.Strings[66417]="你真臭！臭泥巴！"
D.Strings[66418]="滚开！这是我的森林了！"
D.Strings[66419]="别碰我的好朋友！"
D.Strings[66420]="我从没见过类似的东西！等比武大会结束之后，恐怕有很多宠物需要我的治疗了。"
D.Strings[66421]="噢，不，我很抱歉，可我不能这么做！在比武大会期间治疗宠物是违反规则的。"
D.Strings[66422]="有时候我觉得自己还不错。那条龙掉下来了！"
D.Strings[66423]="另一个也完蛋了。"
D.Strings[66424]="加尔鲁什·地狱咆哮"
D.Strings[66425]="纳兹戈林将军"
D.Strings[66426]="赫利克斯·黑索"
D.Strings[66427]="那些火炮都哑火了。干得好，英雄。你做好解决这一切的准备了吗？"
D.Strings[66428]="地狱咆哮酋长"
D.Strings[66429]="军团士兵纳兹戈林"
D.Strings[66430]="攻城匠师黑索"
D.Strings[66431]="督军扎伊拉"
D.Strings[66432]="快来树荫下歇歇吧！"
D.Strings[66433]="好酒好菜，物美价廉！"
D.Strings[66434]="来歇歇脚吧，冒险者！"
D.Strings[66435]="饿了？渴了？还是累了？让优雅的斯万来照顾你吧！"
D.Strings[66436]="修理武器护甲了！"
D.Strings[66437]="修护甲磨武器了！"
D.Strings[66438]="不打无准备之仗！让工匠郭婉看看你的装备吧！"
D.Strings[66439]="卖精品武器护甲了！"
D.Strings[66440]="卖面啦！"
D.Strings[66441]="最好吃、最好吃的面啦！"
D.Strings[66442]="卖好吃的面条啦！"
D.Strings[66443]="莫莫跟面条大师傅学了好多好多周呢。"
D.Strings[66444]="来尝尝我精心烹制的金龙面吧。"
D.Strings[66445]="这里有全潘达利亚最美味的面条。"
D.Strings[66446]="感谢你的光顾，冒险者。"
D.Strings[66447]="金龙面！最好吃的面！"
D.Strings[66448]="看这里！他丢下了自己的武器。"
D.Strings[66449]="看来他已经彻底疯了。"
D.Strings[66450]="我们也一样。希尔瓦娜斯和我都派出舰队去支援沃金了。"
D.Strings[66451]="我还是很高兴见到您的，普罗德摩尔女士。"
D.Strings[66452]="勇士们，跟我来。该去找我们的……“酋长”算总账了。"
D.Strings[66453]="看来地狱咆哮的傲慢放出了最后一头煞魔。我早料到了。"
D.Strings[66454]="这并不稀奇，摄政王。如今，乌瑞恩国王的舰队正驶向奥格瑞玛。"
D.Strings[66455]="我警告你，洛瑟玛。联盟已经包围了那座城市，我们要消灭地狱咆哮。你的人最好别妨碍我们。"
D.Strings[66456]="英雄们，穿过传送门！围攻奥格瑞玛的战役开始了！"
D.Strings[66457]="%s的投影爆炸了！"
D.Strings[66458]="野牛人鲜辣面！酋长才能享用的美食！"
D.Strings[66459]="那种清汤寡水的面有什么好吃的？来尝尝野牛人鲜辣面吧！"
D.Strings[66460]="新鲜热辣，分量十足！快来尝尝野牛人鲜辣面吧！"
D.Strings[66461]="又鲜又辣！无与伦比的美味！"
D.Strings[66462]="芬芳馥郁、强身提神的异域美酒！"
D.Strings[66463]="荧光琥珀酒！快来尝尝吧！"
D.Strings[66464]="来自蟠龙脊之外的琥珀美酒！"
D.Strings[66465]="快来尝尝真正的独家美酒吧！绝对提神、过瘾的……琥珀酒！"
D.Strings[66466]="关键就在于里面的树脂。"
D.Strings[66467]="热气羊肉面！最好吃的面！"
D.Strings[66468]="快来吃碗面垫垫肚子吧！好吃的面！"
D.Strings[66469]="热气羊肉面！最美味的面！"
D.Strings[66470]="超级好吃的面！你要来一碗吗？"
D.Strings[66471]="古尔丹跟他们在一起！"
D.Strings[66472]="你好，我是少昊。你是来聆听至尊天神教诲的吗？"
D.Strings[66473]="你准备好了就告诉我一声，$n。做好战斗准备。"
D.Strings[66474]="最美味的食物，别光看不尝啦！"
D.Strings[66475]="快请坐，好好享用一顿美餐吧！"
D.Strings[66476]="没有我不会做的菜！快来尝尝吧！"
D.Strings[66477]="机会来了。我们走！"
D.Strings[66478]="美味的食物，刚出锅的海岛佳肴！"
D.Strings[66479]="卖魔法天灯啦！"
D.Strings[66480]="只要点亮蜡烛，它就能飞上天空，甚至不需要有风！"
D.Strings[66481]="想从天空俯瞰永恒岛吗？快来买金色滑翔机吧！"
D.Strings[66482]="南北美酒，完美融合！"
D.Strings[66483]="快来喝一杯吧！"
D.Strings[66484]="这里的美酒是独一无二的。快来尝尝吧！"
D.Strings[66485]="快来喝一杯巨龙P.I.E.吧！它能让你身体强健，龙精虎猛！"
D.Strings[66486]="我要咬掉你的脸！！！"
D.Strings[66487]="幸运儿！来吃碗面条吧！"
D.Strings[66488]="哟呵！快来尝尝吉祥蘑菇面吧？"
D.Strings[66489]="最好吃！最美味！能给你带来双倍好运的美味面条！"
D.Strings[66490]="嘿嘿！快来尝尝好吃的面条吧！"
D.Strings[66491]="那个洞穴就在深黯峰里。那是西边的阿塔加废墟。"
D.Strings[66492]="这让我想起了当初我们用全视指环监视古尔丹和暗影议会的情形。"
D.Strings[66493]="河鲜面，只用最新鲜河鱼烹制。"
D.Strings[66494]="请来尝尝我的杂烩河鲜面吧，绝对不会让你失望。"
D.Strings[66495]="刚出水还不到一小时的新鲜河鱼！……好像是吧？都怪这该死的岛。"
D.Strings[66496]="杂烩河鲜面！"
D.Strings[66497]="风暴烈酒时间！"
D.Strings[66498]="风暴烈酒，一切尽在不言中。"
D.Strings[66499]="风暴烈酒：酒中帝王！"
D.Strings[66500]="风暴烈酒：可口清爽！"
D.Strings[66501]="风暴烈酒：美酒中的美酒！"
D.Strings[66502]="如果你有空，就来尝尝我们的美酒吧。风暴烈酒！"
D.Strings[66503]="风暴烈酒，熊猫人的“啤酒”。"
D.Strings[66504]="风暴烈酒，全艾泽拉斯最好的酒。"
D.Strings[66505]="绿石佳酿！来自翡翠林腹地的美酒！"
D.Strings[66506]="绿石佳酿！美玉的滋味！"
D.Strings[66507]="绿石佳酿，一口难忘！"
D.Strings[66508]="你！过来尝尝我的绿石佳酿吧！"
D.Strings[66509]="快去告诉其他人：我们找到铁狼之子了。Lok'tar ogar！ "
D.Strings[66510]="我……父亲……会……报仇……"
D.Strings[66511]="<你在一个血池中发现了一本日记。$b$b你想要翻阅一下，可惜血水已经把书页都糊上了。>"
D.Strings[66512]="你父亲会像我过去那样痛不欲生。"
D.Strings[66513]="很荣幸你能来帮我们，$n。只要我们联手，就一定能除掉祸害我们土地的毒瘤。"
D.Strings[66514]="睡魔的巢穴就在西南边，需要穿过沙丘。"
D.Strings[66515]="我要用它做一顶最酷的帽子！"
D.Strings[66516]="我们到那儿见。"
D.Strings[66517]="你要完蛋了！"
D.Strings[66518]="这会有点疼！"
D.Strings[66519]="我们现在多干掉一个暗影议会的爬虫，将来的麻烦就会少一点。"
D.Strings[66520]="数千年前，潘达利亚的人民曾在这里见证雄心勃勃的帝王们面对至尊天神的挑战。\n\n那么，你是来观看未来的英雄接受天神试炼的吗？\n\n还是想要亲自挑战一下呢？"
D.Strings[66521]="响骨！"
D.Strings[66522]="我……记得……你……"
D.Strings[66523]="放置祭品"
D.Strings[66524]="这三块水晶分别位于废墟中三处战略要地上。用菲努斯之心摧毁它们。"
D.Strings[66525]="卡德加，我是不是把菲努斯之心忘在这儿了？"
D.Strings[66526]="我比以前更漂亮了。"
D.Strings[66527]="什么？！我记得你。"
D.Strings[66528]="我才不会自降身份来跟你战斗呢，但我想到了一个主意。"
D.Strings[66529]="想要离开这个噩梦了吗？"
D.Strings[66530]="请送我回去。"
D.Strings[66531]="吉塞尔达，我的美人，你表现的机会来了。"
D.Strings[66532]="杂种。"
D.Strings[66533]="只要戈尔索格还活着，我就无法干坐在这里等待利戈拉和科尔加。"
D.Strings[66534]="Throm-Ka，$C。我们得在第一波攻击时远离贾纳尔。"
D.Strings[66535]="Lok'tar。戈尔索格的房间就在前面。"
D.Strings[66536]="叔叔要是赢了，就会喝一桶酒；要是输了，那就要喝两桶。所以我猜他还是赢了！"
D.Strings[66537]="我们还有很多事要做，朋友。我会守住这里，直到堡垒里的局势稳定下来。我们不能让戈尔索格跑了。"
D.Strings[66538]="钢铁部落正在靠近。别乱动。"
D.Strings[66539]="我已经冲上了通往戈尔索格王座的斜坡。准备攻击！"
D.Strings[66540]="<砮皂赞许地向你点点头。>"
D.Strings[66541]="你今天的壮举将决定潘达利亚在未来几千年中的面貌。$b$b谢谢你，英雄。游学者将会世代传颂你的故事。"
D.Strings[66542]="随着最后一位液态防御者的死亡，柔和的嗡鸣声停止了，腐化物也不再生成新的软泥怪。"
D.Strings[66543]="我要吃了你！！"
D.Strings[66544]="不！你才是食物……"
D.Strings[66545]="Throm-Ka，指挥官沃尔卡。你的到来让影月氏族深感荣幸。"
D.Strings[66546]="萨满，女人……<吐口水>。我没功夫理会先知和神棍。"
D.Strings[66547]="你们的战士都上哪儿去了？难道有关影月氏族的那些传闻都是真的？"
D.Strings[66548]="你们就是一群躲在魔法后头的懦夫？"
D.Strings[66549]="铁甲哨兵！支援我！"
D.Strings[66550]="请让开，兄弟们。我们必须和地狱咆哮谈谈。"
D.Strings[66551]="谁都不准进入城市。包括你，萨满。"
D.Strings[66552]="萨尔？萨鲁法尔？你们来干什么？"
D.Strings[66553]="力量和荣誉，将军。我们是来找加尔鲁什谈判的。这样或许还有一线和平的希望。"
D.Strings[66554]="库卡隆！都上前线去！"
D.Strings[66555]="你们知道的，我无法保证你们的安全……以及加尔鲁什的反应。"
D.Strings[66556]="Lok'tar Ogar，兄弟们。"
D.Strings[66557]="懦夫？我让你看看谁才是懦夫！"
D.Strings[66558]="住手。我今天可不是来跟你动手的，哈拉。"
D.Strings[66559]="你们影月氏族确实继承了骄傲的战士精神！"
D.Strings[66560]="<眯起了眼睛，但放松了下来。>"
D.Strings[66561]="很好，沃拉什之子沃尔卡。影月氏族会加入钢铁部落的。"
D.Strings[66562]="Lok-Regar。上面有什么命令？"
D.Strings[66563]="去召集你的氏族。钢铁部落很快就将彻底碾碎卡拉波！"
D.Strings[66564]="我好饿啊。$b$b酋长把我赶出了村子。谁说我是食物？我是新酋长。等我有了食物，蕨人朋友们都会爱我的。只要朋友们爱我，他们就会给我更多食物！我需要很多很多朋友！$b$b你就是我最好的朋友，$c。"
D.Strings[66565]="小心，朋友，这片树林很危险。"
D.Strings[66566]="小心魔荚人，$c。他们可不像表面上那么友善。"
D.Strings[66567]="魔荚人会管你叫好朋友。那都是谎言。"
D.Strings[66568]="如果我们不保持警惕，饥饿的魔荚人就会把我们都吃了的。"
D.Strings[66569]="要是我，就会在这片森林里保持警惕，$c。"
D.Strings[66570]="耶！！！"
D.Strings[66571]="我在想什么呢？我没练习过这种装备！啊哈！！"
D.Strings[66572]="好热！好热！好热！"
D.Strings[66573]="警告。你正在燃烧。请执行安全程序。"
D.Strings[66574]="好吧，伙计们，让我们疯狂一把吧。"
D.Strings[66575]="歼灭者已激活！"
D.Strings[66576]="我们这儿需要一个拖把！"
D.Strings[66577]="哇！这玩意儿真是让人难以置信，太耀眼了！"
D.Strings[66578]="让我们看看库卡隆造了些什么玩意儿吧。"
D.Strings[66579]="横扫时刻！激活歼灭者！"
D.Strings[66580]="这些食人魔得到了一个惨痛的教训。"
D.Strings[66581]="一个霜狼兽人也别放过。"
D.Strings[66582]="谢谢你救了我。你战斗起来真像一个霜狼兽人。"
D.Strings[66583]="我们就在这里分道扬镳吧。祝你好运，勇士。"
D.Strings[66584]="看呐，小伙子们，加拉达的野杂种起死回生了。"
D.Strings[66585]="哈哈哈！你应该继续装死的。那你还能多活几天。"
D.Strings[66586]="要是加拉达肯乖乖加入钢铁部落，那你的好爸爸今天或许还能救你一命。"
D.Strings[66587]="说话小心点，哈托克。在我面前，雷神兽人全都不堪一击。"
D.Strings[66588]="你的狼崽子们在开阔地是很厉害，看看他们遇到戈隆还有什么能耐。"
D.Strings[66589]="兄弟们……把它放出来！"
D.Strings[66590]="拉紧那些锁链。"
D.Strings[66591]="他的胳膊松脱了！快拉紧，否则他会把你们都打到墙上去。"
D.Strings[66592]="我们得按时完成目标。"
D.Strings[66593]="你准备好了就告诉我一声，我们得继续推进。"
D.Strings[66594]="霜狼氏族将会世代传唱今天的伟大战斗。"
D.Strings[66595]="你准备好了就告诉我一声。"
D.Strings[66596]="当你的斗篷在翠绿色的雾气中翻滚时，你感受到了至尊天神的祝福。"
D.Strings[66597]="你们对霜狼氏族的侵扰到此为止了，食人魔。"
D.Strings[66598]="我的背后站着整整一个帝国。你们有什么呢，小兽人？"
D.Strings[66599]="我们有霜狼氏族的力量。Lok'tar ogar！"
D.Strings[66600]="住手！住手！"
D.Strings[66601]="别杀我，我们不会再袭击你们的族人了。"
D.Strings[66602]="那你在袭击我的氏族时，可曾怜悯过那些可怜的妇孺？"
D.Strings[66603]="所谓的“帝国”。"
D.Strings[66604]="其他人呢，他们还好吗？"
D.Strings[66605]="我们……也走散了。"
D.Strings[66606]="你做好参赛准备了吗？"
D.Strings[66607]="各就各位……预备……开始！"
D.Strings[66608]="你来这里做什么？这是什么？"
D.Strings[66609]="我不知道。可是把我们拖来这里的兽人就在附近用餐。我们先去干掉他。"
D.Strings[66610]="来吧。让我们去找你的霜狼。"
D.Strings[66611]="怎么啦，贾纳尔？居然害怕一头戈隆？"
D.Strings[66612]="我还以为你们霜狼兽人都是高手呢？"
D.Strings[66613]="想跟雷神氏族作对可没那么容易。"
D.Strings[66614]="在我的刀剑之下，你们这些杂种不堪一击！"
D.Strings[66615]="如果你们加入钢铁部落，我就放你一马。"
D.Strings[66616]="没错，就是这样！完美的伪装！"
D.Strings[66617]="这才是真正的帽子！"
D.Strings[66618]="哈托克！你逃不了的！"
D.Strings[66619]="还行，如果你只想打扮成一个毫无时尚感的兽人的话。"
D.Strings[66620]="要我说的话，那件衬衣上的刺绣很可爱。"
D.Strings[66621]="这件小饰品非常适合抢劫，你不觉得吗？"
D.Strings[66622]="我已经能感受到那些火球了！"
D.Strings[66623]="哇！你带上那个面具之后，完全就是个兽人了。"
D.Strings[66624]="噢，没错，水下风正是这一季的风尚！"
D.Strings[66625]="你这个又小又没用的虫子！"
D.Strings[66626]="看呐，酋长！我把这些家伙给您带来了！我们能吃掉这家伙吗！"
D.Strings[66627]="看起来很酷！"
D.Strings[66628]="我为帝国而战！"
D.Strings[66629]="哇！你看起来很酷，不过那衣服似乎有点……抽象。"
D.Strings[66630]="颜色很漂亮，但我觉得裁剪有点太老土了。"
D.Strings[66631]="很时髦，但不怎么像兽人。"
D.Strings[66632]="那件衬衣是去年的旧款了。"
D.Strings[66633]="不不不，那个红色不正！我要的深红色，不是绯红色。"
D.Strings[66634]="我是最强壮的！"
D.Strings[66635]="那条短裙很配你的眼睛。"
D.Strings[66636]="它很配你，就是不那么“$n”。"
D.Strings[66637]="你……会……后悔的……"
D.Strings[66638]="我们得搭配出完美的服装，请在三个服装选项里进行挑选，配出正确的影月兽人伪装。"
D.Strings[66639]="哈哈哈哈！你被我们包围了，小崽子！"
D.Strings[66640]="Throm-Ka，$C。萨尔对你的评价很高。"
D.Strings[66641]="刀塔食人魔已经祸害我的人民太久了。是时候采取行动了。"
D.Strings[66642]="是时候从源头上解决这个问题了。"
D.Strings[66643]="来吧，兄弟。你自由了。"
D.Strings[66644]="%s嗅了嗅洛卡拉，呜咽起来。"
D.Strings[66645]="他必将付出代价！！"
D.Strings[66646]="你闻到阿莎的味道了，对不对？我……很抱歉，奈鲁克。我没能保护好她。"
D.Strings[66647]="我们失去了这么多兄弟姐妹……"
D.Strings[66648]="噢，他们会的。相信我。"
D.Strings[66649]="让兽人氏族团结在同一面旗帜下！今天就加入钢铁部落吧！"
D.Strings[66650]="格罗玛什·地狱咆哮：传奇战士，可怕的敌人。他将带领我们走向更美好的明天！"
D.Strings[66651]="钢铁部落的力量毋庸置疑。今天就来加入吧！"
D.Strings[66652]="加入钢铁部落，推翻德莱尼统治！"
D.Strings[66653]="你是敢于迎接挑战的真兽人吗？今天就来加入地狱咆哮的军队吧。"
D.Strings[66654]="不要相信德莱尼人。他们只想让你衰弱！"
D.Strings[66655]="相信你的同胞。相信钢铁部落的力量！"
D.Strings[66656]="做骄傲的兽人！帮助钢铁部落！"
D.Strings[66657]="很高兴看到你成功了，$n！$B$B欢迎来到霜火岭！"
D.Strings[66658]="我准备好飞往刀塔堡垒了。"
D.Strings[66659]="这块金属和你以前加工过的任何一种金属都不一样。它会反击。你必须更加强大。"
D.Strings[66660]="你要以坚决的意志，就像要砸碎仇敌的脑袋那么用力地敲打它！"
D.Strings[66661]="注意！这一部分很重要。"
D.Strings[66662]="看见没？这就是你要的反应。"
D.Strings[66663]="认真对待每一次锻打！别再把矛头砸飞了！"
D.Strings[66664]="砰！"
D.Strings[66665]="那些火星只是被锻打出来的杂质。"
D.Strings[66666]="我很高兴你能陪我走完这段旅程，朋友。"
D.Strings[66667]="来啊，你这笨蛋，再加把劲！"
D.Strings[66668]="让我听到那块金属的清鸣声！"
D.Strings[66669]="你想要得到黑石品质的武器，就得像黑石兽人那样干活儿！"
D.Strings[66670]="你每挥舞一次锤子，就离粉碎我们的敌人又近了一步！"
D.Strings[66671]="好。这几下打得很好。"
D.Strings[66672]="别给那块原料喘息的机会！"
D.Strings[66673]="使用纳鲁之动能伤害敌人，或快速逃离危险。$B$B|TInterface\\Icons\\Spell_Holy_Heroism.blp:64|t"
D.Strings[66674]="屈服在黑暗之下吧！进攻！"
D.Strings[66675]="黑暗之星……变亮了……"
D.Strings[66676]="呵呵呵……你们这些小崽子都得死在这儿……"
D.Strings[66677]="烈焰会吞噬你的，很快……"
D.Strings[66678]="钢铁的洪流很快就会淹没你的，德莱尼之友……"
D.Strings[66679]="钢铁部落……来了……"
D.Strings[66680]="着火啦！！！！"
D.Strings[66681]="快跑，兄弟们！快跑啊！"
D.Strings[66682]="我们在他们面前毫无还手之力！"
D.Strings[66683]="快回塔里去！"
D.Strings[66684]="到塔里去！"
D.Strings[66685]="快逃命吧！他们杀进来了！"
D.Strings[66686]="贾纳尔！我们来帮你了！Lok'tar ogar！"
D.Strings[66687]="你还给我们留了几个？真体贴！"
D.Strings[66688]="来吧，$n。让我们讨论一下，怎么才能更好地帮助杜隆坦和他的氏族。"
D.Strings[66689]="<这面盾牌似乎是属于失踪的搜索队。$b$b经过进一步的检查，你发现在血迹斑斑的护甲上有着上百处细小的刺痕。>"
D.Strings[66690]="<你发现在死去的运货骡子身上，有着成百上千处微小的刺痕。>"
D.Strings[66691]="德莱尼人来了！撤退！"
D.Strings[66692]="快回船上去！"
D.Strings[66693]="|TInterface\\Icons\\spell_holy_powerinfusion.blp:32|t卡拉祝福了你。现在你可以在小地图上追踪剩余的兽人了。"
D.Strings[66694]="霜狼们！去干掉那些雷神兽人。为了复仇！"
D.Strings[66695]="消灭他们！以影月氏族的名义，消灭他们！"
D.Strings[66696]="啊哈哈……你的反抗只会让我们更兴奋，德莱尼。"
D.Strings[66697]="仁慈、真理和善良能救得了你吗？"
D.Strings[66698]="你们的理想主义让你们变得软弱，德莱尼。生存才是这世界上唯一的真理。"
D.Strings[66699]="够了！我要亲手宰了你！"
D.Strings[66700]="我得休息下，等你找到其他人之后，我们就在楼上汇合。"
D.Strings[66701]="你的朋友们来过这儿，但现在他们已经不在了。"
D.Strings[66702]="你要找的线索，就在池塘边上。"
D.Strings[66703]="你找到了他们的护甲，但没有找到朋友。"
D.Strings[66704]="你可以在旷野上找到更多的答案。"
D.Strings[66705]="他们的坐骑死了，但他们一定得救了。"
D.Strings[66706]="你最后的线索，就在山洞里。"
D.Strings[66707]="不要对卡格手软。"
D.Strings[66708]="我跟你没什么好说的，$r。"
D.Strings[66709]="我跟你没什么好说的，$r。你们的人要为许多事情负责。但这或许能成为一个新的开始。"
D.Strings[66710]="谢谢你，英雄。你和你的同伴们都是联盟的尖刀：你探索潘达利亚、保卫锦绣谷，以及突袭加尔鲁什老巢的一系列行动为我们带来了这次胜利。$b$b我们在这里的胜利将使卡利姆多的纷争落下帷幕，但即使在和平时期，我们在这里、在家乡、在全世界，都还有许多事情要做。"
D.Strings[66711]="联盟接下来该怎么办？"
D.Strings[66712]="为什么不继续打下去？"
D.Strings[66713]="我们如今正空前的团结。我们为卡利姆多的人民带来了安全，终止了封锁，并结束了这场令大洋两岸无数人民流血牺牲的战争。$b$b现在，我们该致力于恢复和平。我打算在塞拉摩附近建立一座军营。我们需要研究如何净化吉尔尼恩的瘟疫，以便他们重建家园。我们必须遏制希尔瓦娜斯。$b$b从今往后，联盟将采取先发制人的策略，绝不会再让第二个地狱咆哮出现。"
D.Strings[66714]="我理解你希望进一步打击部落的想法。但冤冤相报何时了？如果我们入侵雷霆崖、艾萨拉和回音群岛，联盟又会增加多少伤亡？我们又该如何管理那些被征服的人民？$b$b熊猫人总是问我们为何而战。今天，我们赢得了正义，并通过支援起义军给了部落一个赎罪改过的机会。更多的血腥杀戮就变成了单纯的复仇——而这只会引来更多的复仇。"
D.Strings[66715]="乌瑞恩国王迟早会为自己允许部落出现另一个酋长而后悔的。$b$b我们应该继续打下去。谁敢保证几年之后这位新酋长的巨魔脑袋里不会冒出什么馊主意？"
D.Strings[66716]="我觉得我父亲做得对。如果我们试图占领奥格瑞玛，那战争将永无止境。而且剩下的部落人民怎么办？难道要依靠收容所吗？我们过去就这么干过——那根本行不通！$b$b我们废黜了一个战争贩子，并让一位可以沟通的领袖取代了他。这是达成和解的唯一机会。"
D.Strings[66717]="胜利属于联盟！在我们撤出这里之前，我的人要尽可能多搞一些疯狂的地精科技。"
D.Strings[66718]="一个共同的敌人，是让人民保持团结的最好方法。矮人部族从未如此团结过。如果和平能持续下去，我们三大王国将会空前的强大……"
D.Strings[66719]="在瓦里安今天做出决定之前，他和我就和平的代价讨论了很久。只要部落同意永久放弃灰谷，我就允许他们使用艾萨拉的木材。考虑到地精吞噬资源的做派，我们倒要看看艾萨拉能支撑多久。$b$b我支持和解，可我没有国王陛下那么自信。如果部落胆敢撕毁条约，再来招惹我们……我们也会做好准备的。"
D.Strings[66720]="毫无疑问，这是一次大捷。现在，我们得将注意力放到我们在吉尔尼恩的家园——那个被瘟疫毁于一旦的地方。乌瑞恩已经保证会帮忙重建我的王国，但该从何处着手依然是个难题。"
D.Strings[66721]="和平是唯一值得为之而战的东西。"
D.Strings[66722]="抬头挺胸，$c。今天，你挽救了部落的灵魂。"
D.Strings[66723]="我以为加尔鲁什已经做好了准备。我以为酋长的重任能让他把目光放长远。可当我们的人民面临重重困难时，他却只看到了一种解决办法——他对部落的虚妄规划将我们都逼到了悬崖。$b$b是时候了，我们要寻找新的方向。沃金会带领我们前进。他其实并不想挑起这个重担……但我想这反而能让他成为一个更好的领袖。"
D.Strings[66724]="我发现政治真是个累死人的玩意儿。我相信沃金会带领我们走上正确的道路。$b$b<洛瑟玛瞥了一眼希尔瓦娜斯。>$b$b假如他能让部落团结一致的话。"
D.Strings[66725]="我们需要和衷共济，$c。"
D.Strings[66726]="“沃金酋长”。你觉得听起来滑稽吗，$c？最起码，我是不会听从一个巨魔的命令的。$b$b可是，是他集结起了这支小小的联军，并赢得了今天的胜利。而且他还证明了自己是杀不死的——这是我最佩服的一点。$b$b\n时间会证明他有多少真本事的……"
D.Strings[66727]="沃金是个坚强的人。哪怕被割断了脖子，他还能挺着回来为自己讨还公道。我喜欢这家伙！$b$b我的人民需要安全和利润。在加尔鲁什手下，我们啥都得不到。"
D.Strings[66728]="他会为反抗我而后悔的。"
D.Strings[66729]="戈尔索格！我，加拉达之子贾纳尔，来取你的脑袋了！Lok'tar ogar！"
D.Strings[66730]="|TInterface\\Icons\\inv_misc_bomb_05:20|t你身后被|cFFFF0000|Hspell:145996|h[设置炸弹]|h|r了！快使用|cFFFF0000|Hspell:146364|h[投掷炸弹]|h|r扔掉它们！"
D.Strings[66731]="跟我来。也许我弟弟杜隆坦会有足够的勇气，跟我们一起来对抗戈尔索格。"
D.Strings[66732]="地狱咆哮已经完蛋了。$b$b<沃金警惕地看着你。>$b$b接下来呢，$r？"
D.Strings[66733]="光荣的兄弟姐妹们！今天，我们取得了杜隆坦想都不敢想的成就！"
D.Strings[66734]="显然，这是一场战争。我们需要一位酋长！ "
D.Strings[66735]="有种的就跟着我干！我们会向整个世界展现霜狼氏族的力量！"
D.Strings[66736]="我们……是……霜狼氏族！"
D.Strings[66737]="留下吧！"
D.Strings[66738]="别让他跑了！"
D.Strings[66739]="你们不可能打败我们所有人，懦夫。"
D.Strings[66740]="$c，快跑，这是个陷阱！"
D.Strings[66741]="你是不是迷路了，伙计？"
D.Strings[66742]="去城中台地的顶上找名叫瓦佐克的兽人，就在飞行管理员东边。你一定不会找错人的，伙计。"
D.Strings[66743]="地精的商店就在桥那头的荣誉谷里。"
D.Strings[66744]="力量谷的银行就在格罗玛什要塞的南边，主大门的西北方。"
D.Strings[66745]="理发师？她的店就在力量谷上方的悬崖上。"
D.Strings[66746]="你要找什么技能的训练师？"
D.Strings[66747]="智慧谷的烈日行者阿托莫应该能帮上忙。"
D.Strings[66748]="季通常都在荣誉谷的熊猫人小亭里。"
D.Strings[66749]="多拉斯就在力量谷的飞行塔顶层上。"
D.Strings[66750]="这就是审判祭坛。"
D.Strings[66751]="先知早就预见到，我们的人民将会在未来遭遇严重的危机。"
D.Strings[66752]="这个祭坛里蕴藏着能拯救我们免于毁灭的力量。"
D.Strings[66753]="我一直祈祷这个审判日永远不要到来。使用这样的力量势必要付出极大的代价。"
D.Strings[66754]="激活审判祭坛需要难以想象的庞大能量——一种不存在于这个世界的能量。"
D.Strings[66755]="幸运的是，彩虹水晶并非产自德拉诺。我觉得三块水晶已经足以供应我们所需的能量。"
D.Strings[66756]="五块彩虹水晶从天而降，散落于影月谷各地。"
D.Strings[66757]="不幸的是，影月氏族似乎也在收集它们。我们绝不能让他们成功。"
D.Strings[66758]="先知对此的预言也终将实现。"
D.Strings[66759]="你明白我们的魔法原理吗，旅行者？"
D.Strings[66760]="看到这把锤子了吗？在我手中，它就能以魔法之力打击敌人。但在一个新兵手里，它不过是一块钝石头。"
D.Strings[66761]="审判祭坛的威力取决于它的使用者。"
D.Strings[66762]="在正确的人手中，它是挽救这个世界的希望。在错误的人手中，它就是灭绝一切的武器。"
D.Strings[66763]="你要找乌特伦？他就在力量谷的西侧。"
D.Strings[66764]="部落大使馆就在力量谷里。"
D.Strings[66765]="从主城入口进城之后，力量谷右边的第二幢建筑物就是旅馆。那里的老板是格雷什卡。"
D.Strings[66766]="去力量谷寻找旅店老板格雷什卡。她的旅馆就在东边，主城门以北的地方。"
D.Strings[66767]="飞龙之尾就在勇者大厅外面，那可是个歇脚的好地方！"
D.Strings[66768]="传说大厅就在力量谷西边的山顶上。"
D.Strings[66769]="大地之环的萨满们在飞艇塔楼北边的悬崖上建起了通向世界各地的传送门。\n\n你还可以在那里找到通往托尔巴拉德的传送门。"
D.Strings[66770]="我来帮你标在地图上吧。"
D.Strings[66771]="你想锻炼自己的炼金技巧？那你最好去耶尔玛克。他的商店，耶尔玛克药剂店就在暗巷区的中央。"
D.Strings[66772]="耶尔玛克是炼金专家。他的店就在暗巷区的中心。"
D.Strings[66773]="格罗玛什要塞里有位血精灵，他的名字是贝洛克。他对古代遗物特别感兴趣。如果你想接受训练，可以去找他谈谈。"
D.Strings[66774]="萨鲁·钢怒就在荣誉谷的“燃烧的铁砧”里。他向来很乐意传授锻造技艺。"
D.Strings[66775]="荣誉谷里就有一位兽人锻造大师，他叫萨鲁·钢怒。你可以沿着红石谷矿业工会前的道路走，在荣誉谷的深处找到他。"
D.Strings[66776]="啊，霜狼的兄弟们。我知道我们迟早会在战场上重逢的。"
D.Strings[66777]="你们不认识自己的哥哥了吗？"
D.Strings[66778]="你可以去暗巷区里找一家店，就在智慧谷的旁边。店名是古丹的符文工艺店。"
D.Strings[66779]="兄弟们！好好招待一下这些霜狼氏族的客人！"
D.Strings[66780]="鲁玛克是这里最好的渔夫。你可以在荣誉谷的码头附近找到他。"
D.Strings[66781]="马卡鲁就能教授你想学的东西。他就在荣誉谷湖边的红石谷矿业工会里。"
D.Strings[66782]="去暗巷区的科多兽皮工店跟苏尔德谈谈吧。他能教授你想学的一切知识。"
D.Strings[66783]="科多兽皮工店旁边的大树南边就是玛加尔布品店。我可以帮你标在地图上，伙计。"
D.Strings[66784]="卡格和其他人随时可能攻破前门。"
D.Strings[66785]="在我们俩对付芬里斯时，他们会拖住雷神氏族的大部分战士。"
D.Strings[66786]="为了氏族！"
D.Strings[66787]="你可以在荣誉谷湖边的码头上找到鲁玛克。"
D.Strings[66788]="去智慧谷找先知利瓦萨。她的治疗能力无人能及。"
D.Strings[66789]="烈日行者阿托莫深谙圣光之道，你可以去找他接受进一步训练。"
D.Strings[66790]="没有比纳胡更勇敢的战士了。多年来，他一直保护着我们的人民。你可以在智慧谷找到他。"
D.Strings[66791]="想学点猎人的绝招吗？去智慧谷找诺希吧。"
D.Strings[66792]="莎伊·云歌正在智慧谷中与元素沟通。去跟她谈谈吧。"
D.Strings[66793]="莎乌拉是受大地母亲眷顾的幸运儿。她应该在智慧谷，和其他训练师在一起。让我帮你标记在地图上吧。"
D.Strings[66794]="熊猫人在荣誉谷建立了一座营地。去找季·火掌提升你的技巧吧。"
D.Strings[66795]="奥莫克那个狡猾的家伙就在暗影裂口里。他能教会你如何在奥格瑞玛的街头生存。"
D.Strings[66796]="暗影裂口里有一个术士的秘密社团。我来给你标在地图上吧。"
D.Strings[66797]="在暗影裂口里可以学到很多奥术的秘密。去找玛鲁德吧，他会教你的。"
D.Strings[66798]="魔荚人看起来都很天真。我还是很震惊……我丈夫。他们杀了我丈夫……"
D.Strings[66799]="他们向我们撒了很多谎。所幸有关水晶的事都是真的。"
D.Strings[66800]="既然水晶已经激活，那我得联系维伦了。"
D.Strings[66801]="但愿这块水晶能对得起我们抛洒在这片森林里的热血。"
D.Strings[66802]="我真不敢相信，它一直都在这里。"
D.Strings[66803]="贾纳尔和其他人到第二层去了。"
D.Strings[66804]="快出去，沿着南边的坡道走。科尔加应该就在那儿。她知道贾纳尔去了哪儿。"
D.Strings[66805]="我们可以解决这里的。出发！"
D.Strings[66806]="很高兴在这儿见到你！"
D.Strings[66807]="祝你平安幸福，朋友！"
D.Strings[66808]="他们来了。做好准备！"
D.Strings[66809]="蠢货，我从一开始就在骗你。是时候了，我要吃掉你的心脏！"
D.Strings[66810]="祝你在森林里过得愉快！"
D.Strings[66811]="你得摧毁那个路障才能继续前进！"
D.Strings[66812]="感谢圣光……我都已经做好了最坏的打算。"
D.Strings[66813]="再次感谢你，$c。剩下的事就让我自己来解决吧。"
D.Strings[66814]="流水之灵，我需要你的指引。大地之灵，我需要你的力量。"
D.Strings[66815]="我……我听到了愤怒的声音！"
D.Strings[66816]="库扎莉就在精神谷东南端的一座小岛上训练猎头者呢，伙计。"
D.Strings[66817]="曾迦就在精神谷东南端的一座小岛上训练猎头者呢，伙计。"
D.Strings[66818]="他们就在精神谷东南端那座高大建筑的顶上。"
D.Strings[66819]="暗影行者祖鲁能够帮助你。$B$B你可以在精神谷东南方那座更高的建筑物的底层找到他。"
D.Strings[66820]="巫医尤姆布一直在精神谷里四处活动，照料受伤的病人与元素之灵。$B$B去中央建筑物附近找他吧。"
D.Strings[66821]="你一定是疯了，伙计，居然对那样的巫术感兴趣。可我没资格阻止你。$B$B乌恩加里·邪语就在精神谷东南方那座较高的建筑里，穿过暗影祭司的神殿就是了。"
D.Strings[66822]="跟我来，英雄。我们得从空中支援他们！"
D.Strings[66823]="纳鲁的净化之光既是我们的战锤又是我们的护盾。"
D.Strings[66824]="他们就在神殿大门口——飞近点！快！"
D.Strings[66825]="飞回去。我们得肃清台阶上的敌人。"
D.Strings[66826]="大主教阿卡玛！小心你的侧翼！"
D.Strings[66827]="谢了，老朋友！"
D.Strings[66828]="你们这些兽人再也别想玷污卡拉波的光辉！"
D.Strings[66829]="前进。以纳鲁之光的名义！"
D.Strings[66830]="使用视介石标记投石车。时光旅行者可以摧毁这些投石车，但没有地面上的眼线，他们是无法准确命中的。"
D.Strings[66831]="小心！鬣蜥人！"
D.Strings[66832]="不准打扰主人。"
D.Strings[66833]="主人需要安静！"
D.Strings[66834]="火焰之灵，我需要你的……啊啊啊！"
D.Strings[66835]="快一点！我们快被围死了。"
D.Strings[66836]="狼肉是美味的小点心！"
D.Strings[66837]="沃高尔！"
D.Strings[66838]="Lok'tar ogar！非胜即死！"
D.Strings[66839]="我们知道你在里面！别逼我们烧掉这座小房子！"
D.Strings[66840]="躲是没用的！出来受死吧！"
D.Strings[66841]="不要对多罗戈手软。Lok'tar ogar。"
D.Strings[66842]="你听到了吗，阿莎？卡格来了。你可以跟奈鲁克一起玩了！"
D.Strings[66843]="又有雷神氏族的恶棍从东边杀过来了！我们被困在卡格的屋子里了！"
D.Strings[66844]="我要杀光雷神兽人！"
D.Strings[66845]="这是我的家！"
D.Strings[66846]="雷神氏族的恶狗！"
D.Strings[66847]="打得好！快过来，我们该进攻堡垒的腹地了。"
D.Strings[66848]="我会跟贾纳尔和其他人到斜坡上跟你汇合的。"
D.Strings[66849]="|TInterface\\Icons\\spell_holy_heroism.blp:32|t\n卡拉祝福了你。你将在非战斗状态下获得|cff71d5ff|Hspell:147414|h[纳鲁的荣耀]|h|r技能。"
D.Strings[66850]="|TInterface\\Icons\\spell_holy_aspiration.blp:32|t\n卡拉祝福了你。你受到的伤害降低且为你恢复一定的生命值。"
D.Strings[66851]="|TInterface\\Icons\\spell_fire_ragnaros_supernova.blp:32|t\n卡拉祝福了你。你的攻击命中后将获得神圣能量，能量将周期性爆炸，对附近敌人造成伤害。"
D.Strings[66852]="|TInterface\\Icons\\spell_holy_aspiration.blp:32|t\n卡拉祝福了你。你的减伤能力提高且生命恢复速率提高。"
D.Strings[66853]="|TInterface\\Icons\\spell_fire_ragnaros_supernova.blp:32|t\n卡拉祝福了你。你的攻击命中后将获得更多神圣能量，对附近敌人造成更多伤害。"
D.Strings[66854]="$n，我们在这儿呢。快过来！"
D.Strings[66855]="刀塔食人魔就是一群废物。他们的大军已经倒在我们的刀剑之下。"
D.Strings[66856]="戈尔索格已经走投无路了，让我们去打倒他吧。"
D.Strings[66857]="鬼鬃会送你去戈尔索格的大厅。它很喜欢你。"
D.Strings[66858]="鬼鬃期待地看着你。"
D.Strings[66859]="够了，孩子。别说了。"
D.Strings[66860]="我很抱歉……我有点失态了。快，$c，这边走。"
D.Strings[66861]="利戈拉、科尔加，守住这里。我们来对付这个渣滓。"
D.Strings[66862]="来吗，兄弟？"
D.Strings[66863]="很好，让我们结束这一切吧。"
D.Strings[66864]="你这是在自寻死路！至于你的酋长，就让我们走着瞧吧。"
D.Strings[66865]="钢铁部落的行径极其卑劣。他们的意图是肮脏的，他们的领袖是堕落的。"
D.Strings[66866]="此时此地，杀戮才是唯一的答案。带着我的祝福，勇往直前吧，勇士。"
D.Strings[66867]="快去找到他们，你们这些废物！巴赛尔大人必须得到他的祭品！"
D.Strings[66868]="你做得很好，勇士。影月氏族终于消停了……你也可以休息了。"
D.Strings[66869]="道路已经安全了，冒险者！我看到你已经成功将入侵者赶回海里去了。你是真正的圣光勇士。"
D.Strings[66870]="嘿，伙计，快帮帮我们！暮光之锤正打算献祭我们这些绿皮呢。"
D.Strings[66871]="我拿到了你从雷神氏族那儿弄来的锁链和抓钩。只要你攻击那些匠灵，我就会用它们让它的弱点暴露出来。"
D.Strings[66872]="我锁住它了！快！用力打它！"
D.Strings[66873]="快！打倒它！"
D.Strings[66874]="刀塔堡垒的那场战斗让我彻底记住了你。你杀了至少二十头食人魔！你想要什么就随便拿吧。"
D.Strings[66875]="这些微粒应该够了。这个图腾已经快撑不下去了。"
D.Strings[66876]="我拿到源生微粒了！去下一个锻炉吧。"
D.Strings[66877]="多年来，鲁尔坎一直是耐奥祖最信赖的顾问。耐奥祖的力量和雄心引领着我们的肉体，但鲁尔坎的智慧和预言鼓舞着我们的精神。"
D.Strings[66878]="耐奥祖的风格粗暴而直接。他会用暴力打倒敌人。$B$B而鲁尔坎聪明又睿智，最擅长以彼之道还施彼身。"
D.Strings[66879]="影月氏族完了。虽然它的躯壳还在，但它的灵魂已经堕落了。"
D.Strings[66880]="我们是自我放逐来到这里的。我们都不愿意接受耐奥祖的黑暗之星的魔力。"
D.Strings[66881]="我们今后的命运还不明朗，但有一点是肯定的，我对女酋长鲁尔坎绝对忠诚。"
D.Strings[66882]="我们攻进来了！杀光他们！"
D.Strings[66883]="兽人以惊人的速度迅速适应了他们的新技术，即使那些技术还十分原始。"
D.Strings[66884]="我们遭到了攻击！"
D.Strings[66885]="我是最强大的！啊啊！！"
D.Strings[66886]="你会变成一份美味的小点心！"
D.Strings[66887]="只要疼一下就好了。"
D.Strings[66888]="你不该来这儿！去死吧！"
D.Strings[66889]="我很好，萨……萨满。我还得战斗。"
D.Strings[66890]="我绝不能就这么死去。躺在这里……像个懦夫。"
D.Strings[66891]="他们的投石车摧毁了我们的大军……"
D.Strings[66892]="戈尔索格会为此付出代价的……"
D.Strings[66893]="德拉卡，帮帮我。我们得……啊啊！"
D.Strings[66894]="别忘了，孩子，我们中有一个盲人，而且已经不能像过去一样召唤万灵了。"
D.Strings[66895]="呸！那只是让这一战更加公平而已。站起来，老家伙。"
D.Strings[66896]="面对连元素本身都能吞噬的敌人，我们还能有什么希望？"
D.Strings[66897]="很久之前，你教导我说元素永远与我们同在。而现在，该轮到我们与它们同在了。非胜即死，我们必须尝试一下，这是我们欠它们的。"
D.Strings[66898]="噢，他会的。相信我。"
D.Strings[66899]="%s发出赞同的低鸣。"
D.Strings[66900]="我也曾经目空一切过；但我错了。我们必须回到狼群中去。铁狼将会面对霜狼氏族的全力一击。"
D.Strings[66901]="$C！你解放了我的孩子们，让我重塑了身躯。接受我的恩赐，将霜火的愤怒倾泻到你的敌人头上吧。"
D.Strings[66902]="萨满，你很强大，竟然能听到我的呼唤。你也很睿智，知道应该做些什么。把你的图腾给我。"
D.Strings[66903]="感受烈焰的愤怒吧！"
D.Strings[66904]="霜狼用鼻子蹭了蹭它的主人，发出轻柔的哼哼声。"
D.Strings[66905]="人们一直以为艾索洛托斯只是个传说，一个萨满之间世代相传的故事，是元素真灵的象征。$b$b看到自己世代尊崇的存在竟然被镣铐所束缚，这是对所有兽人，对萨满教，对我的侮辱。"
D.Strings[66906]="很高兴再次见到你，$n。我们的时间已经不多了。"
D.Strings[66907]="你做好离开的准备后，就爬到布拉森背上去吧。我会在路上向你解释一切的。"
D.Strings[66908]="我们出发吧。"
D.Strings[66909]="空气中弥漫着岩石的焦糊味，德拉卡。你看见了什么？"
D.Strings[66910]="我能感觉到，有无数鬣蜥人正在地下潜伏。这可不容易。"
D.Strings[66911]="我们对这个所谓的钢铁协议早有耳闻。事实上，这不过就是让各个氏族联合起来绞杀与他们持不同政见的对手。$B$B杜隆坦拒绝这个所谓的“钢铁部落”的决定很明智。我只希望我们足够强大，能够与之抗衡。"
D.Strings[66912]="这么多……鬣蜥人。我们得引开他们，让你潜入寒冰熔炉。"
D.Strings[66913]="你提出的方法应该足以打倒匠灵了，但每次只能持续几秒钟。"
D.Strings[66914]="太可怕了。那些魔荚人就当着我的面吃掉了瑞恩……"
D.Strings[66915]="雪莉和其他人被魔荚人大王抓住了……我们必须找到他们。我……我不能眼看着他们丧命。"
D.Strings[66916]="我们必须杀了他们的大王……他们往西边去了……救救他们。救救我妻子！"
D.Strings[66917]="这就是霜火岭。霜狼氏族每年都会来此，让新成年的战士寻找属于他们自己的狼。"
D.Strings[66918]="如今的部落非常脆弱。我们已无法再供养一支属于我们自己的部队了。"
D.Strings[66919]="我已经会见过他们的酋长并讨论了结盟的可能性。可杜隆坦对此……有些抵触。"
D.Strings[66920]="刀塔食人魔的袭击更加频繁了。他希望能尽快对他们的堡垒发动一次突袭。"
D.Strings[66921]="食人魔！布拉森，拦住他们！"
D.Strings[66922]="我们已经靠近堡垒了。"
D.Strings[66923]="杜隆坦的部队已经发动攻击了！坚持住，我们来了。"
D.Strings[66924]="时间不多了。我们必须帮助霜狼氏族。"
D.Strings[66925]="我们的生死存亡，就看这一战了。"
D.Strings[66926]="我只希望我们几个足够了。"
D.Strings[66927]="杜隆坦和贾纳尔就在前面。我们走。"
D.Strings[66928]="这些畜生毫无建树，只会到处制造混乱和死亡。让我们给他们一个明确的信号。"
D.Strings[66929]="你们这些畜生！给我进攻！"
D.Strings[66930]="快点！小崽子都等急了。你不是娘们吧？谁是娘们？"
D.Strings[66931]="就等着那些小偷呢。"
D.Strings[66932]="让你们的塔布羊停一下，好吗？这里还有战利品呢。"
D.Strings[66933]="等我们把那些火炮弄回来，有的是时间让你来收拾战利品。我们走！"
D.Strings[66934]="戈尔索格！我，加拉达之子贾纳尔，来取你的脑袋了！"
D.Strings[66935]="来吧。我要让你的鲜血溅满这些墙壁，兽人。"
D.Strings[66936]="他们说：“撤回岗哨去！”$B$B他们还说：“雷神氏族会杀了你的！”$B$B<老兽人吐了口唾沫。>$B$B呸！这是我的房子，我才不走呢。我要站在我的土地上，光荣地战死！$B$B你呢，小崽子？你也要跑吗？不是就起来战斗！"
D.Strings[66937]="起来战斗！非胜即死！"
D.Strings[66938]="来次小小的战略性撤退也没什么大不了的……"
D.Strings[66939]="你想让我们干坐着，任由戈尔索格逍遥法外？没门！"
D.Strings[66940]="<老兽人又吐了口唾沫。你确信自己看到他吐出了一颗牙齿。>$B$B呸！！$B$B等你的脊梁长好了再回来找我吧！"
D.Strings[66941]="做个真正的兽人吧！现在就有一个让你证明自己的机会。雷神氏族杀过来了！"
D.Strings[66942]="来吧，蠢货们！快来受死吧！！"
D.Strings[66943]="啊，战斗的狂热！我好像又回到了年轻的时代！"
D.Strings[66944]="到我的屋子里去——墙角有一只旧箱子。我希望你能收下里面的东西。"
D.Strings[66945]="走开！让我来解决！"
D.Strings[66946]="呃——石头！"
D.Strings[66947]="粉身碎骨……"
D.Strings[66948]="下次让我先上，你这个只会耍嘴皮子的懦夫！"
D.Strings[66949]="你不过是巨石间的一颗小石子……"
D.Strings[66950]="天崩地裂！"
D.Strings[66951]="哈，愚蠢的石头！"
D.Strings[66952]="哈哈！太弱了。"
D.Strings[66953]="只要我还有一口气在，就要保卫自己的家园。$B$B我只希望能够战死沙场，而不是老死在床上。"
D.Strings[66954]="你还在等什么？快去拿你的报酬吧。$B$B你连接受礼物的基本礼貌都没有吗？"
D.Strings[66955]="鬼鬃会送你去见杜隆坦和贾纳尔的。"
D.Strings[66956]="很好……野性变弱了……"
D.Strings[66957]="杀了他！我就自由了！"
D.Strings[66958]="洛卡拉，等等！嗨……那家伙太冲动了。"
D.Strings[66959]="父亲的灵魂就在天上看着我战斗呢。不管是食人魔还是兽人，都不是我的对手。"
D.Strings[66960]="我准备好了，随时可以战斗。"
D.Strings[66961]="<裂蹄牛咀嚼着好不容易找到的青草。在戈尔隆德，青草十分罕见。>"
D.Strings[66962]="又来一头！他们到底放了多少头出来？！"
D.Strings[66963]="小心！别让它靠近那些屋子！"
D.Strings[66964]="浪费材料。"
D.Strings[66965]="我要让你死无全尸。"
D.Strings[66966]="护送大篷车前往[嘲颅废墟]。"
D.Strings[66967]="护送大篷车前往[TANK TEST FACILITY]。"
D.Strings[66968]="护送大篷车前往[食人魔奴隶营地]。"
D.Strings[66969]="护送大篷车前往[蒸汽油井营地]。"
D.Strings[66970]="护送大篷车前往[船坞营地]。"
D.Strings[66971]="你找到了好朋友的一把武器。"
D.Strings[66972]="你可以在海滩附近找到更多线索。"
D.Strings[66973]="<这把武器似乎是属于某个失踪的搜索队成员的。>"
D.Strings[66974]="清风之灵，响应我的召唤！我们需要你的智慧。"
D.Strings[66975]="这些石头似乎能够储存被锻打进其中的力量和热量。"
D.Strings[66976]="这些厚厚的金属板经过了淬火处理，能够耐受极端高温。"
D.Strings[66977]="手脚轻点，陌生人。我的体内已经在翻江倒海了。"
D.Strings[66978]="那是不是……戈尔索格？外面那个？"
D.Strings[66979]="你们这些软弱、卑微、脆弱的家伙。我会好好欣赏你们的死亡的。"
D.Strings[66980]="贾纳尔，你来带头突击，端掉他们的投石车。"
D.Strings[66981]="我们剩下的人会跟上，并确保……"
D.Strings[66982]="来吧，兄弟。我们不能让他跑了！"
D.Strings[66983]="不，贾纳尔。这太危险了。我们得按计划来。"
D.Strings[66984]="不，就让我们在这里做个了断吧。"
D.Strings[66985]="洛戈什！科尔加！我们走！"
D.Strings[66986]="虚空之主，请听从我们的召唤。让我们的鲜血指引你降临这个世界！"
D.Strings[66987]="虚空……饿了！"
D.Strings[66988]="那是什么怪物！"
D.Strings[66989]="你们的鲜血只会让我更强大。"
D.Strings[66990]="你们无法击败虚空！"
D.Strings[66991]="放松点，汉瑟尔。我保证，你还有大把痛宰钢铁部落的机会。"
D.Strings[66992]="石槌食人魔的营地。他们是一群奴隶贩子。"
D.Strings[66993]="这不是霜狼该来的地方。小心你脚下的阴影。"
D.Strings[66994]="喂，你！我这儿有上好的美酒，买点儿路上喝吧。"
D.Strings[66995]="我可以出发了，将军。"
D.Strings[66996]="让烈焰烧焦你……"
D.Strings[66997]="不管你是谁，我欠你一条命……"
D.Strings[66998]="啊，我感觉……好多了。"
D.Strings[66999]="终于，自由了。"
D.Strings[67000]="这些食人魔会付出代价的！"
D.Strings[67001]="我会把你的事迹告诉杜隆坦的，陌生人。"
D.Strings[67002]="我的死亡，只是滋养了上古之神……"
D.Strings[67003]="万物终将消亡。"
D.Strings[67004]="你也将被吞噬。"
D.Strings[67005]="他们来了。守住这条路！"
D.Strings[67006]="我们霜狼兽人比外表看起来更睿智，外来者。$b$b我会盯着你的……"
D.Strings[67007]="有三道食人魔的足迹追着我们那位神秘的女士往东边去了。"
D.Strings[67008]="小心那些鞭尾牛，它们可不好惹。"
D.Strings[67009]="要是我的狼还活着，她今晚一定能大快朵颐。"
D.Strings[67010]="戈尔索格是个白痴。没有哪个食人魔能对抗霜狼氏族的勇士。"
D.Strings[67011]="你还是一如既往地英勇善战，兄弟。现在，我们得巩固边防，清剿剩余的刀塔食人魔。雷神氏族随时可能发动攻击。"
D.Strings[67012]="看看你的周围，杜隆坦。刀塔氏族已经完了。我们应该趁着士气正高，一鼓作气打下雷神氏族。"
D.Strings[67013]="我们的骑兵和他们的狼需要休息。急于出兵是愚蠢的做法。我绝不会为了报复雷神氏族而牺牲氏族自身的安全。"
D.Strings[67014]="你才是笨蛋，兄弟。无论芬里斯躲到哪里，我们都应该杀了他。而不是放任他袭击我们的村子，坐以待毙。"
D.Strings[67015]="如果你不肯为我们的父亲报仇，那就让我去。"
D.Strings[67016]="愿意跟我走的都过来，我可不想在一座食人魔建造的堡垒里浪费时间。"
D.Strings[67017]="我会带着芬里斯的死讯回来的。"
D.Strings[67018]="谁都不准干扰耐奥祖！"
D.Strings[67019]="谢谢你，陌生人！影月氏族毫无预兆地袭击了观星台。"
D.Strings[67020]="快——影月酋长占领了观星台！"
D.Strings[67021]="阿卡特岗哨的研究员们已经收集到了许多先祖的原始残骸碎片。"
D.Strings[67022]="我的斥候敏捷而强大。他们会第一时间向我们通报敌人动向的。"
D.Strings[67023]="卡拉波的斥候迅捷如风。我们的攻击快速精准。"
D.Strings[67024]="<这个年轻的德莱尼人专注地盯着战场。>"
D.Strings[67025]="维伦在这个时候召唤我们？还有什么任务能比抵挡兽人进攻，保卫卡拉波更重要？"
D.Strings[67026]="他有了一个突围的计划，但他需要你们守备官的力量。"
D.Strings[67027]="<这个死去的德莱尼人似乎是被战斧从脑后劈死的。这个可怜的灵魂显然没有预计到这种情况。>"
D.Strings[67028]="他是先知。他或许已经预见到了将要发生的事。"
D.Strings[67029]="我曾发誓坚守职责。哪里有需要，我们就会出现在那里。守备官们，都过来！"
D.Strings[67030]="唔……没错，你的说法很有道理。守备官们，都过来！"
D.Strings[67031]="他们从悬崖下面爬上来了！快去找守备官——随便谁——来帮忙！"
D.Strings[67032]="来吧，孩子。到我的图腾中寻找庇护吧。"
D.Strings[67033]="拜托你小声点儿。我可不想暴露我们的位置。"
D.Strings[67034]="这太不寻常了。我们的位置非常完美！干嘛要走？"
D.Strings[67035]="这么多？很好。只要是先知的召唤，游侠们必然响应。跟我来，伙计们！维伦需要我们的帮助。"
D.Strings[67036]="我相信维伦的智慧。他毕竟是我们的先知。跟我来，伙计们！"
D.Strings[67037]="我不知道计划的细节，但他要游侠、学者、守备官和技师们都过去。"
D.Strings[67038]="这是维伦的命令。"
D.Strings[67039]="我得尽快修好这块水晶，但附近的狼令这个任务变得格外困难。$B$B你能在我进行修复时保护我吗？"
D.Strings[67040]="你——你是塔纳安的那位英雄，对吧？我需要你的帮助。$b$b由于卡拉波的常规防御护盾消散，我们正在安装艾鲁恩防护水晶。下面那块水晶发生了故障，在把它修好之前，我都没法离开这儿。你能帮我把这个共鸣水晶放上去吗？"
D.Strings[67041]="好极了。故障的水晶就在北边，靠近神殿的外墙。"
D.Strings[67042]="完成了？很好。等这场战斗结束，我们就可以开始修复卡拉波的常规防御护盾了。"
D.Strings[67043]="好的，罗姆尔。我会帮你修好那块水晶的。"
D.Strings[67044]="外来者。你有什么事？"
D.Strings[67045]="我当然愿意听从先知的召唤。但首先，我有一个要求。$b$b我的学者们精通治疗，但不擅长战斗。在敌人的阵线后方，还有很多受伤的防御者，我却找不到身经百战的冒险者去营救他们……"
D.Strings[67046]="非常感谢，外来者。如果有需要，你可以用这个印记来治疗受伤的士兵们。"
D.Strings[67047]="从今往后，你就是学者之友，外来者。我们集合点再见。"
D.Strings[67048]="我愿意帮你救助那些受伤的防御者。"
D.Strings[67049]="维伦需要你的帮助。"
D.Strings[67050]="贾纳尔和他的追随者们离开之后，我们已经没法守住这座堡垒了。"
D.Strings[67051]="哈！在这里，你的游侠朋友可就射不到我了。让我们看看没了他你还能怎么办。"
D.Strings[67052]="我们应该结成同盟，杜隆坦。部落可以帮助你的氏族。"
D.Strings[67053]="你说得对，萨尔。我们愿意加入你的部落。你已经证明了自己的价值和荣誉。"
D.Strings[67054]="我们已经占领了堡垒。现在，我们得解放下面的矿洞和附近的区域。"
D.Strings[67055]="我们不能让这么多伤员留在敌后。"
D.Strings[67056]="我已经完成了你的要求，先驱者。"
D.Strings[67057]="水晶又开始运转了，大技师。"
D.Strings[67058]="如果那块水晶不能运转，钢铁部落就能从空中直接进入卡拉波了。"
D.Strings[67059]="啊！碾碎 $G他:她;*！"
D.Strings[67060]="你被|cFFFF0000|Hspell:150381|h[劲射]|h|r击杀了。注意在芬里斯施放该技能前跑开！"
D.Strings[67061]="请带上它继续战斗吧，它象征着我对你的感激之情。让它的火焰与你一起将你敌人烧成灰烬吧。"
D.Strings[67062]="我们是唯一能够收集这些碎片并释放它的人。"
D.Strings[67063]="快点干，蠢货！"
D.Strings[67064]="快点挖！"
D.Strings[67065]="我们需要更多的投石！"
D.Strings[67066]="我需要更多的石头，否则我就去报告图格尔。"
D.Strings[67067]="你真没用！"
D.Strings[67068]="快点，否则我还打你！"
D.Strings[67069]="这个很卖力。"
D.Strings[67070]="你在偷懒吗？"
D.Strings[67071]="要是我还有力气战斗该多好……"
D.Strings[67072]="这些该死的食人魔！"
D.Strings[67073]="要不是你，我就死定了。"
D.Strings[67074]="我都已经不抱获救的希望了。"
D.Strings[67075]="感谢你的义举。"
D.Strings[67076]="我还以为死定了呢。"
D.Strings[67077]="你有一颗真正的战士之心！"
D.Strings[67078]="我来攻击他们的侧翼！"
D.Strings[67079]="我来啦，雷神氏族的懦夫们！"
D.Strings[67080]="以斧之名！杀呀！"
D.Strings[67081]="杀光敌人！"
D.Strings[67082]="有两道足迹往北边去了。看起来是一个食人魔带着一个女人，肯定是他的俘虏。"
D.Strings[67083]="哼！你们两个别吵了！"
D.Strings[67084]="感谢你分享的情报，游侠。"
D.Strings[67085]="很好，我们这就出发。联盟会坚定地站在你的人民身后。"
D.Strings[67086]="啊，$n！你来了！"
D.Strings[67087]="射得好！趁他们还没有发起反击，我们快离开这儿。抓紧了！"
D.Strings[67088]="霜狼的白痴，居然来攻击食人魔。 "
D.Strings[67089]="我要把你的脑袋留作纪念，德雷克塔尔。"
D.Strings[67090]="接受耻辱，承认失败吧。我会给你个痛快的。"
D.Strings[67091]="我去仓库那儿侦察一下，好制定出摧毁它的计划。"
D.Strings[67092]="我准备好了，我会从安全的坦克里支援你的。"
D.Strings[67093]="我看到钢铁部落的援军已经在路上了。伊瑞尔正在穿越车站往东北方跑。我们最好快点跟她汇合。"
D.Strings[67094]="让我们看看能不能刺激一下苟克，让他来协助我们。"
D.Strings[67095]="我们解开了你的束缚，并带来了礼物。"
D.Strings[67096]="好的，小家伙们，我们要一起碾碎他们！"
D.Strings[67097]="你的警卫太松懈了，酋长。我在村子里抓住了这些间谍。"
D.Strings[67098]="他们已经迟了。俘虏都被送去痛楚堡垒了。"
D.Strings[67099]="他们的鲜血将召唤出黑暗之星，并使我成为钢铁部落的神！"
D.Strings[67100]="酋长看重的是行动，而非言语，暗影法师。"
D.Strings[67101]="封锁出口！不要让这些德莱尼活着离开！"
D.Strings[67102]="他已经同意了。来吧，$n，让我们骑到苟克背上去。"
D.Strings[67103]="我们有着共同的敌人。我在此谦卑地请求你伸出援手。让我们共同消灭他们。"
D.Strings[67104]="雷神……我让你失望了……"
D.Strings[67105]="苟克，格鲁尔之子，戈隆的王子，我是伊瑞尔，请听我说。"
D.Strings[67106]="我看到了你的未来，贾拉克。它可不太妙。"
D.Strings[67107]="来吧，$n。让我们来说服苟克帮助我们摧毁这个地方。"
D.Strings[67108]="下去解放矿洞？骑上你们的狼跟我来，我知道一条近路。"
D.Strings[67109]="你可以从这里下到矿洞和竞技场，勇士。"
D.Strings[67110]="亲爱的……"
D.Strings[67111]="够了！就让你们这些狡猾的德莱尼暂且留着那座神殿吧。"
D.Strings[67112]="钢铁部落还会回来的！"
D.Strings[67113]="我得到前面去，为反击部队开辟一处集结点。"
D.Strings[67114]="对钢铁部落放尊重点，再加把劲儿，废物。"
D.Strings[67115]="残次品。"
D.Strings[67116]="你的鲜血将带给我黑暗之星的力量。跟我回沙兹古尔吧！"
D.Strings[67117]="把俘虏押到沙兹古尔去。"
D.Strings[67118]="让我们去阻止布莱克松吧！"
